PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = FULL;
PRAGMA busy_timeout = 5000;

CREATE TABLE schema_meta (
  schema_version INTEGER PRIMARY KEY,
  installed_at_ms INTEGER NOT NULL,
  min_reader_version INTEGER NOT NULL,
  min_writer_version INTEGER NOT NULL
) STRICT;

INSERT INTO schema_meta VALUES (21, unixepoch('subsec') * 1000, 21, 21);

CREATE TABLE schema_install_receipts (
  digest TEXT PRIMARY KEY,
  schema_version INTEGER NOT NULL UNIQUE REFERENCES schema_meta(schema_version),
  prior_schema_version INTEGER CHECK (prior_schema_version IS NULL),
  migration_digest TEXT NOT NULL UNIQUE,
  schema_inventory_digest TEXT NOT NULL,
  sqlite_closure_digest TEXT NOT NULL,
  integrity_check_result TEXT NOT NULL CHECK (integrity_check_result = 'ok'),
  foreign_key_violation_count INTEGER NOT NULL CHECK (foreign_key_violation_count = 0),
  installer_key_fingerprint TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  installer_signature TEXT NOT NULL,
  installed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TRIGGER schema_install_receipt_is_exact_fresh_v21
BEFORE INSERT ON schema_install_receipts
BEGIN
  SELECT RAISE(ABORT, 'schema install receipt is not the exact fresh v2.1 closure')
  WHERE NEW.schema_version <> 21
     OR NEW.prior_schema_version IS NOT NULL
     OR length(NEW.digest) <> 71 OR substr(NEW.digest, 1, 7) <> 'sha256:'
     OR length(NEW.migration_digest) <> 71 OR substr(NEW.migration_digest, 1, 7) <> 'sha256:'
     OR length(NEW.schema_inventory_digest) <> 71 OR substr(NEW.schema_inventory_digest, 1, 7) <> 'sha256:'
     OR length(NEW.sqlite_closure_digest) <> 71 OR substr(NEW.sqlite_closure_digest, 1, 7) <> 'sha256:'
     OR NEW.installer_signature = ''
     OR NEW.installed_at_ms < (unixepoch('subsec') * 1000) - 30000
     OR NEW.installed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_type(NEW.canonical_json) <> 'object'
     OR (SELECT COUNT(*) FROM json_each(NEW.canonical_json)) <> 10
     OR EXISTS (
       SELECT 1 FROM json_each(NEW.canonical_json) field
       WHERE field.key NOT IN (
         'digest','schema_version','prior_schema_version','migration_digest',
         'schema_inventory_digest','sqlite_closure_digest','integrity_check_result',
         'foreign_key_violation_count','installer_key_fingerprint','installed_at_ms'
       )
     )
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.schema_version') IS NOT NEW.schema_version
     OR json_type(NEW.canonical_json, '$.prior_schema_version') IS NOT 'null'
     OR json_extract(NEW.canonical_json, '$.migration_digest') IS NOT NEW.migration_digest
     OR json_extract(NEW.canonical_json, '$.schema_inventory_digest') IS NOT NEW.schema_inventory_digest
     OR json_extract(NEW.canonical_json, '$.sqlite_closure_digest') IS NOT NEW.sqlite_closure_digest
     OR json_extract(NEW.canonical_json, '$.integrity_check_result') IS NOT NEW.integrity_check_result
     OR json_extract(NEW.canonical_json, '$.foreign_key_violation_count') IS NOT NEW.foreign_key_violation_count
     OR json_extract(NEW.canonical_json, '$.installer_key_fingerprint') IS NOT NEW.installer_key_fingerprint
     OR json_extract(NEW.canonical_json, '$.installed_at_ms') IS NOT NEW.installed_at_ms;
END;

CREATE TRIGGER schema_install_receipts_no_update
BEFORE UPDATE ON schema_install_receipts
BEGIN SELECT RAISE(ABORT, 'schema install receipts are immutable'); END;

CREATE TRIGGER schema_install_receipts_no_delete
BEFORE DELETE ON schema_install_receipts
BEGIN SELECT RAISE(ABORT, 'schema install receipts are immutable'); END;

CREATE TABLE installation_trust_root (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  root_key_fingerprint TEXT NOT NULL UNIQUE,
  installer_manifest_digest TEXT NOT NULL UNIQUE,
  installer_manifest_json TEXT NOT NULL CHECK (json_valid(installer_manifest_json)),
  installer_signature TEXT NOT NULL,
  installed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE leader_transition_authorizations (
  digest TEXT PRIMARY KEY,
  previous_term INTEGER,
  new_term INTEGER NOT NULL UNIQUE CHECK (new_term >= 1),
  previous_leader_instance_id TEXT,
  new_leader_instance_id TEXT NOT NULL,
  previous_heartbeat_at_ms INTEGER,
  lock_evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK ((new_term = 1 AND previous_term IS NULL) OR
         (new_term > 1 AND previous_term = new_term - 1))
) STRICT;

CREATE TABLE leader_heartbeat_attestations (
  digest TEXT PRIMARY KEY,
  term INTEGER NOT NULL REFERENCES leader_terms(term),
  heartbeat_seq INTEGER NOT NULL CHECK (heartbeat_seq >= 1),
  leader_instance_id TEXT NOT NULL,
  lock_evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL,
  UNIQUE (term, heartbeat_seq)
) STRICT;

CREATE TABLE leader_terms (
  term INTEGER PRIMARY KEY CHECK (term >= 1),
  leader_instance_id TEXT NOT NULL,
  transition_authorization_digest TEXT NOT NULL UNIQUE REFERENCES leader_transition_authorizations(digest),
  state TEXT NOT NULL CHECK (state IN ('active','retired')),
  acquired_at_ms INTEGER NOT NULL,
  heartbeat_at_ms INTEGER NOT NULL,
  heartbeat_seq INTEGER NOT NULL DEFAULT 0 CHECK (heartbeat_seq >= 0),
  retirement_authorization_digest TEXT UNIQUE REFERENCES leader_transition_authorizations(digest),
  retired_at_ms INTEGER
) STRICT;

CREATE UNIQUE INDEX one_active_leader
ON leader_terms(state) WHERE state = 'active';

CREATE TABLE control_state (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  current_term INTEGER NOT NULL REFERENCES leader_terms(term),
  bootstrap_manifest_digest TEXT REFERENCES bootstrap_manifests(digest),
  portfolio_epoch INTEGER NOT NULL CHECK (portfolio_epoch >= 1),
  dispatch_enabled INTEGER NOT NULL CHECK (dispatch_enabled IN (0,1)),
  admission_mode TEXT NOT NULL DEFAULT 'stopped'
    CHECK (admission_mode IN ('open','draining','stopped')),
  kill_switch INTEGER NOT NULL DEFAULT 0 CHECK (kill_switch IN (0,1)),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  last_command_authorization_digest TEXT REFERENCES command_authorizations(digest),
  CHECK (
    (dispatch_enabled = 0 AND admission_mode = 'stopped')
    OR (dispatch_enabled = 1 AND admission_mode IN ('open','draining'))
  ),
  CHECK (kill_switch = 0 OR admission_mode = 'stopped')
) STRICT;

CREATE TABLE principals (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('human','service','executor')),
  display_name TEXT NOT NULL,
  auth_subject TEXT NOT NULL UNIQUE,
  state TEXT NOT NULL CHECK (state IN ('active','disabled')),
  created_at_ms INTEGER NOT NULL,
  disabled_at_ms INTEGER
) STRICT;

CREATE TABLE signing_keys (
  key_id TEXT PRIMARY KEY,
  principal_id TEXT NOT NULL REFERENCES principals(id),
  algorithm TEXT NOT NULL CHECK (algorithm IN ('ed25519')),
  public_key TEXT NOT NULL,
  public_key_fingerprint TEXT NOT NULL UNIQUE,
  key_purpose TEXT NOT NULL CHECK (
    key_purpose IN ('key_admin','control_plane','ingress_broker','artifact_broker',
                    'executor_result','runtime_supervisor','provider_observer',
                    'approval_broker','credential_broker','release_broker','schema_validator')
  ),
  state TEXT NOT NULL CHECK (state IN ('active','revoked','expired')),
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER,
  revoked_at_ms INTEGER,
  CHECK (expires_at_ms IS NULL OR expires_at_ms > created_at_ms),
  CHECK ((state = 'revoked') = (revoked_at_ms IS NOT NULL))
) STRICT;

CREATE TABLE credential_reference_revocations (
  digest TEXT PRIMARY KEY,
  credential_reference_id TEXT NOT NULL UNIQUE REFERENCES credential_references(id),
  reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 512),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  revoked_at_ms INTEGER NOT NULL
) STRICT;

CREATE VIEW current_valid_keys AS
SELECT sk.key_id, sk.principal_id, sk.key_purpose, sk.algorithm,
       sk.public_key, sk.public_key_fingerprint
FROM signing_keys sk
JOIN principals p ON p.id = sk.principal_id
WHERE sk.state = 'active'
  AND p.state = 'active'
  AND (sk.expires_at_ms IS NULL
       OR sk.expires_at_ms >= (unixepoch('subsec') * 1000));

CREATE TABLE signature_verification_receipts (
  digest TEXT PRIMARY KEY,
  record_kind TEXT NOT NULL,
  record_id TEXT NOT NULL,
  record_canonical_json TEXT NOT NULL CHECK (json_valid(record_canonical_json)),
  record_signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  record_signature TEXT NOT NULL,
  validator_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  verdict TEXT NOT NULL CHECK (verdict = 'pass'),
  canonical_encoding_verified INTEGER NOT NULL CHECK (canonical_encoding_verified = 1),
  duplicate_keys_rejected INTEGER NOT NULL CHECK (duplicate_keys_rejected = 1),
  referenced_digests_verified INTEGER NOT NULL CHECK (referenced_digests_verified = 1),
  payload_digest_verified INTEGER CHECK (payload_digest_verified IS NULL OR payload_digest_verified = 1),
  verified_payload_digest TEXT,
  record_digest_verified INTEGER CHECK (record_digest_verified IS NULL OR record_digest_verified = 1),
  verified_record_digest TEXT,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  verified_at_ms INTEGER NOT NULL,
  UNIQUE (record_kind, record_id, validator_closure_digest, signer_key_id),
  CHECK ((payload_digest_verified IS NULL) = (verified_payload_digest IS NULL)),
  CHECK ((record_digest_verified IS NULL) = (verified_record_digest IS NULL)),
  CHECK (record_kind <> 'command' OR
         (payload_digest_verified = 1 AND verified_payload_digest IS NOT NULL))
) STRICT;

CREATE VIEW current_valid_signature_receipts AS
SELECT receipt.*
FROM signature_verification_receipts receipt
JOIN current_valid_keys validator_key
  ON validator_key.key_id = receipt.signer_key_id
 AND validator_key.principal_id = receipt.signer_principal_id
 AND validator_key.key_purpose = 'schema_validator'
JOIN configuration_artifacts validator
  ON validator.digest = receipt.validator_closure_digest
 AND validator.artifact_kind = 'toolchain_closure'
JOIN artifact_manifests evidence ON evidence.digest = receipt.evidence_manifest_digest
JOIN current_valid_keys evidence_key
  ON evidence_key.key_id = evidence.signer_key_id
 AND evidence_key.key_purpose = 'artifact_broker'
WHERE NOT EXISTS (
  SELECT 1 FROM configuration_artifact_invalidations invalidation
  WHERE invalidation.configuration_digest = receipt.validator_closure_digest
);

CREATE TABLE policies (
  digest TEXT PRIMARY KEY,
  policy_type TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version >= 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (policy_type, version)
) STRICT;

CREATE TABLE release_policy_effect_rules (
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  effect_type TEXT NOT NULL CHECK (
    effect_type IN ('dry_run','test_pr','test_deploy','production_pr',
                    'deploy','publish','release','client_deliverable')
  ),
  human_approval_required INTEGER NOT NULL CHECK (human_approval_required IN (0,1)),
  required_role TEXT CHECK (
    required_role IS NULL OR required_role IN ('owner','operator','approver','risk_acceptor')
  ),
  CHECK (
    (human_approval_required = 1 AND required_role IS NOT NULL)
    OR (human_approval_required = 0 AND required_role IS NULL)
  ),
  PRIMARY KEY (policy_digest, effect_type)
) STRICT;

CREATE TABLE host_resource_policy_limits (
  policy_digest TEXT PRIMARY KEY REFERENCES policies(digest),
  max_model_rss_fraction_ppm INTEGER NOT NULL
    CHECK (max_model_rss_fraction_ppm BETWEEN 1 AND 700000),
  emergency_disk_bytes INTEGER NOT NULL CHECK (emergency_disk_bytes > 0),
  clone_log_allowance_bytes INTEGER NOT NULL CHECK (clone_log_allowance_bytes >= 0),
  emergency_ram_bytes INTEGER NOT NULL CHECK (emergency_ram_bytes > 0),
  min_platform_baseline_rss_bytes INTEGER NOT NULL
    CHECK (min_platform_baseline_rss_bytes > 0),
  control_cpu_millis INTEGER NOT NULL CHECK (control_cpu_millis >= 2000),
  cpu_oversubscription_ppm INTEGER NOT NULL
    CHECK (cpu_oversubscription_ppm BETWEEN 1 AND 1000000),
  persistent_idle_cpu_millis INTEGER NOT NULL
    CHECK (persistent_idle_cpu_millis BETWEEN 1 AND 500),
  active_call_cpu_millis INTEGER NOT NULL
    CHECK (active_call_cpu_millis BETWEEN 1 AND 4000),
  cpu_window_ms INTEGER NOT NULL CHECK (cpu_window_ms = 1000),
  max_model_pid_count INTEGER NOT NULL CHECK (max_model_pid_count > 0),
  max_model_fd_count INTEGER NOT NULL CHECK (max_model_fd_count > 0)
) STRICT;

CREATE TABLE resource_profiles (
  digest TEXT PRIMARY KEY REFERENCES policies(digest),
  host_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  profile_name TEXT NOT NULL CHECK (
    profile_name IN ('fable_portfolio_process','fable_project_process',
                     'fable_active_call','codex_fresh_process',
                     'opus_fresh_process','managed_opus_process')
  ),
  pool TEXT NOT NULL CHECK (pool IN ('fable','codex','opus')),
  reservation_kind TEXT NOT NULL CHECK (reservation_kind IN ('process','active_call')),
  disk_bytes INTEGER NOT NULL CHECK (disk_bytes >= 0),
  rss_bytes INTEGER NOT NULL CHECK (rss_bytes >= 0),
  pid_count INTEGER NOT NULL CHECK (pid_count >= 0),
  fd_count INTEGER NOT NULL CHECK (fd_count >= 0),
  cpu_millis INTEGER NOT NULL CHECK (cpu_millis > 0),
  UNIQUE (host_policy_digest, profile_name)
) STRICT;

CREATE TABLE policy_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  invalidation_type TEXT NOT NULL
    CHECK (invalidation_type IN ('superseded','revoked')),
  replacement_policy_digest TEXT REFERENCES policies(digest),
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL,
  CHECK (
    (invalidation_type = 'superseded' AND replacement_policy_digest IS NOT NULL)
    OR (invalidation_type = 'revoked' AND replacement_policy_digest IS NULL)
  ),
  CHECK (replacement_policy_digest IS NULL OR replacement_policy_digest <> policy_digest),
  UNIQUE (policy_digest, invalidation_type)
) STRICT;

CREATE TABLE configuration_artifacts (
  digest TEXT PRIMARY KEY,
  artifact_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  artifact_kind TEXT NOT NULL CHECK (
    artifact_kind IN ('runtime_settings','environment_allowlist','provider_proxy_profile',
                      'io_protocol','system_prompt','runtime_binary','runtime_probe_contract',
                      'executor_config','managed_service_config',
                      'sanitization_rules',
                      'output_schema',
                      'control_plane_closure','cli_runtime_closure','sandbox_runtime_closure',
                      'scanner_profile','toolchain_closure','projection_schema_closure',
                      'projection_transformer_closure',
                      'benchmark_analysis_closure','benchmark_normalizer_closure',
                      'egress_adapter_closure','git_lineage_verifier_closure')
  ),
  object_path TEXT NOT NULL UNIQUE,
  object_digest TEXT NOT NULL,
  path_inventory_digest TEXT NOT NULL,
  dependency_closure_digest TEXT NOT NULL,
  sbom_digest TEXT NOT NULL,
  owner_uid INTEGER NOT NULL CHECK (owner_uid = 0),
  owner_gid INTEGER NOT NULL CHECK (owner_gid = 0),
  service_writable INTEGER NOT NULL CHECK (service_writable = 0),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  CHECK (object_path LIKE '/usr/local/libexec/cortex-harness/objects/sha256/%'),
  CHECK (instr(object_path, '..') = 0),
  CHECK (instr(canonical_json, '/Users/') = 0)
) STRICT;

CREATE TABLE configuration_artifact_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  configuration_digest TEXT NOT NULL UNIQUE REFERENCES configuration_artifacts(digest),
  replacement_configuration_digest TEXT REFERENCES configuration_artifacts(digest),
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL,
  CHECK (
    replacement_configuration_digest IS NULL
    OR replacement_configuration_digest <> configuration_digest
  )
) STRICT;

CREATE TABLE runtime_catalogs (
  digest TEXT PRIMARY KEY,
  version INTEGER NOT NULL CHECK (version >= 1),
  runtime TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('anthropic','openai')),
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  resolved_model TEXT NOT NULL,
  resolved_model_family TEXT NOT NULL,
  resolved_effort TEXT NOT NULL,
  binary_path TEXT NOT NULL,
  binary_digest TEXT NOT NULL,
  binary_artifact_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  settings_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  environment_allowlist_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  provider_proxy_profile_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  io_protocol_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  system_prompt_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  toolchain_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  permission_mode TEXT NOT NULL CHECK (permission_mode = 'brokered-deny-by-default'),
  service_uid TEXT NOT NULL CHECK (service_uid = 'cortex-harness'),
  probe_contract_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  argv_json TEXT NOT NULL CHECK (json_valid(argv_json)),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  effective_at_ms INTEGER NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (runtime, requested_model, requested_profile, version)
) STRICT;

CREATE TABLE runtime_catalog_probe_attestations (
  digest TEXT PRIMARY KEY,
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  probe_contract_digest TEXT NOT NULL,
  executed_uid TEXT NOT NULL CHECK (executed_uid = 'cortex-harness'),
  clean_environment INTEGER NOT NULL CHECK (clean_environment = 1),
  parser_verified INTEGER NOT NULL CHECK (parser_verified = 1),
  authentication_verified INTEGER NOT NULL CHECK (authentication_verified = 1),
  proxy_scope_verified INTEGER NOT NULL CHECK (proxy_scope_verified = 1),
  io_round_trip_verified INTEGER NOT NULL CHECK (io_round_trip_verified = 1),
  binary_digest TEXT NOT NULL,
  actual_model TEXT NOT NULL,
  actual_model_family TEXT NOT NULL,
  actual_effort TEXT NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  probed_at_ms INTEGER NOT NULL,
  UNIQUE (runtime_catalog_digest, probed_at_ms)
) STRICT;

CREATE TABLE runtime_catalog_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  replacement_runtime_catalog_digest TEXT REFERENCES runtime_catalogs(digest),
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL,
  CHECK (
    replacement_runtime_catalog_digest IS NULL
    OR replacement_runtime_catalog_digest <> runtime_catalog_digest
  ),
  UNIQUE (runtime_catalog_digest)
) STRICT;

CREATE TABLE bootstrap_manifests (
  digest TEXT PRIMARY KEY,
  schema_version INTEGER NOT NULL CHECK (schema_version = 21),
  roster_digest TEXT NOT NULL,
  runtime_catalog_set_digest TEXT NOT NULL,
  resource_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  control_plane_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  cli_runtime_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  sandbox_runtime_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  scanner_profile_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE bootstrap_executor_bindings (
  bootstrap_manifest_digest TEXT NOT NULL REFERENCES bootstrap_manifests(digest),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  principal_id TEXT NOT NULL,
  pool TEXT NOT NULL CHECK (pool IN ('fable','codex','opus')),
  runtime TEXT NOT NULL,
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  model TEXT NOT NULL,
  model_family TEXT NOT NULL,
  profile TEXT NOT NULL,
  host_id TEXT NOT NULL,
  config_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  sandbox_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  fresh_session_required INTEGER NOT NULL CHECK (fresh_session_required IN (0,1)),
  PRIMARY KEY (bootstrap_manifest_digest, executor_id),
  UNIQUE (bootstrap_manifest_digest, principal_id)
) STRICT;

CREATE TABLE bootstrap_capability_bindings (
  bootstrap_manifest_digest TEXT NOT NULL REFERENCES bootstrap_manifests(digest),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  capability TEXT NOT NULL,
  scope TEXT NOT NULL,
  PRIMARY KEY (bootstrap_manifest_digest, executor_id, capability, scope)
) STRICT;

CREATE TABLE bootstrap_managed_identity_bindings (
  bootstrap_manifest_digest TEXT NOT NULL REFERENCES bootstrap_manifests(digest),
  service_alias TEXT NOT NULL CHECK (service_alias IN ('morty','space-beth')),
  managed_identity_digest TEXT NOT NULL REFERENCES managed_service_identities(digest),
  PRIMARY KEY (bootstrap_manifest_digest, service_alias),
  UNIQUE (bootstrap_manifest_digest, managed_identity_digest)
) STRICT;

CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  owner_principal_id TEXT NOT NULL REFERENCES principals(id),
  submit_command_authorization_digest TEXT NOT NULL UNIQUE REFERENCES command_authorizations(digest),
  priority INTEGER NOT NULL CHECK (priority BETWEEN 0 AND 3),
  state TEXT NOT NULL CHECK (
    state IN ('queued','admitted','active','blocked','paused',
              'parked','done','cancelled')
  ),
  created_at_ms INTEGER NOT NULL,
  updated_at_ms INTEGER NOT NULL,
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0)
) STRICT;

CREATE TABLE principal_project_roles (
  grant_id TEXT PRIMARY KEY,
  principal_id TEXT NOT NULL REFERENCES principals(id),
  project_id TEXT NOT NULL REFERENCES projects(id),
  role TEXT NOT NULL CHECK (
    role IN ('owner','operator','reviewer','approver','risk_acceptor','viewer')
  ),
  granted_at_ms INTEGER NOT NULL,
  revoked_at_ms INTEGER,
  grant_authorization_id TEXT UNIQUE REFERENCES role_change_authorizations(digest),
  project_submit_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  revocation_authorization_id TEXT UNIQUE REFERENCES role_change_authorizations(digest),
  CHECK ((grant_authorization_id IS NULL) <> (project_submit_authorization_digest IS NULL))
) STRICT;

CREATE UNIQUE INDEX one_active_project_role_grant
ON principal_project_roles(principal_id, project_id, role)
WHERE revoked_at_ms IS NULL;

CREATE TABLE principal_global_roles (
  grant_id TEXT PRIMARY KEY,
  principal_id TEXT NOT NULL REFERENCES principals(id),
  role TEXT NOT NULL CHECK (role IN ('admin','operator','auditor')),
  granted_at_ms INTEGER NOT NULL,
  revoked_at_ms INTEGER,
  grant_authorization_id TEXT NOT NULL UNIQUE REFERENCES role_change_authorizations(digest),
  revocation_authorization_id TEXT UNIQUE REFERENCES role_change_authorizations(digest)
) STRICT;

CREATE UNIQUE INDEX one_active_global_role_grant
ON principal_global_roles(principal_id, role)
WHERE revoked_at_ms IS NULL;

CREATE TABLE executors (
  id TEXT PRIMARY KEY,
  principal_id TEXT NOT NULL UNIQUE REFERENCES principals(id),
  pool TEXT NOT NULL CHECK (pool IN ('fable','codex','opus')),
  runtime TEXT NOT NULL,
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  model TEXT NOT NULL,
  model_family TEXT NOT NULL,
  profile TEXT NOT NULL,
  host_id TEXT NOT NULL,
  config_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  sandbox_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  fresh_session_required INTEGER NOT NULL CHECK (fresh_session_required IN (0,1)),
  state TEXT NOT NULL CHECK (
    state IN ('starting','healthy','degraded','quarantined','offline')
  ),
  health_epoch INTEGER NOT NULL DEFAULT 0 CHECK (health_epoch >= 0),
  breaker_state TEXT NOT NULL DEFAULT 'closed'
    CHECK (breaker_state IN ('closed','open','half_open')),
  breaker_until_ms INTEGER,
  consecutive_successes INTEGER NOT NULL DEFAULT 0,
  consecutive_failures INTEGER NOT NULL DEFAULT 0,
  last_seen_at_ms INTEGER,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE executor_capabilities (
  executor_id TEXT NOT NULL REFERENCES executors(id),
  capability TEXT NOT NULL,
  scope TEXT NOT NULL,
  PRIMARY KEY (executor_id, capability, scope)
) STRICT;

CREATE TABLE executor_slots (
  id TEXT PRIMARY KEY,
  executor_id TEXT NOT NULL REFERENCES executors(id),
  ordinal INTEGER NOT NULL CHECK (ordinal >= 1),
  state TEXT NOT NULL CHECK (
    state IN ('available','leased','draining','quarantined','offline')
  ),
  fence_counter INTEGER NOT NULL DEFAULT 0 CHECK (fence_counter >= 0),
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  UNIQUE (executor_id),
  UNIQUE (executor_id, ordinal),
  UNIQUE (id, executor_id)
) STRICT;

CREATE TABLE project_slots (
  slot_no INTEGER PRIMARY KEY CHECK (slot_no BETWEEN 1 AND 4),
  orchestrator_executor_id TEXT NOT NULL UNIQUE REFERENCES executors(id),
  project_id TEXT UNIQUE REFERENCES projects(id),
  generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0),
  owner_fence INTEGER NOT NULL DEFAULT 0 CHECK (owner_fence >= 0),
  binding_authorization_digest TEXT UNIQUE REFERENCES project_admission_permits(digest),
  assigned_at_ms INTEGER,
  released_at_ms INTEGER
) STRICT;

CREATE TABLE budget_accounts (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id),
  account_scope TEXT NOT NULL CHECK (account_scope IN ('project','portfolio')),
  creation_authorization_digest TEXT NOT NULL UNIQUE
    REFERENCES budget_account_creation_authorizations(digest),
  currency TEXT NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),
  cap_micro_usd INTEGER NOT NULL CHECK (cap_micro_usd >= 0),
  reserved_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK (reserved_micro_usd >= 0),
  spent_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK (spent_micro_usd >= 0),
  state TEXT NOT NULL CHECK (state IN ('active','breached','frozen','closed')),
  created_at_ms INTEGER NOT NULL,
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  CHECK (
    (account_scope = 'project' AND project_id IS NOT NULL)
    OR (account_scope = 'portfolio' AND project_id IS NULL)
  ),
  UNIQUE (project_id, currency)
) STRICT;

CREATE UNIQUE INDEX one_portfolio_budget_per_currency
ON budget_accounts(currency)
WHERE account_scope = 'portfolio';

CREATE TABLE pricing_catalogs (
  digest TEXT PRIMARY KEY,
  provider TEXT NOT NULL CHECK (provider IN ('anthropic','openai')),
  model TEXT NOT NULL,
  input_rate_per_million INTEGER NOT NULL CHECK (input_rate_per_million BETWEEN 0 AND 1000000000),
  output_rate_per_million INTEGER NOT NULL CHECK (output_rate_per_million BETWEEN 0 AND 1000000000),
  cache_read_rate_per_million INTEGER NOT NULL CHECK (cache_read_rate_per_million BETWEEN 0 AND 1000000000),
  cache_write_rate_per_million INTEGER NOT NULL CHECK (cache_write_rate_per_million BETWEEN 0 AND 1000000000),
  tool_call_rate_per_million INTEGER NOT NULL CHECK (tool_call_rate_per_million BETWEEN 0 AND 1000000000),
  millisecond_rate_per_million INTEGER NOT NULL CHECK (millisecond_rate_per_million BETWEEN 0 AND 1000000000),
  effective_at_ms INTEGER NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (provider, model, effective_at_ms)
) STRICT;

CREATE TABLE pricing_catalog_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  pricing_catalog_digest TEXT NOT NULL UNIQUE REFERENCES pricing_catalogs(digest),
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE replan_override_authorizations (
  digest TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  predecessor_run_id TEXT NOT NULL REFERENCES runs(id),
  planned_run_id TEXT NOT NULL UNIQUE,
  replan_ordinal INTEGER NOT NULL CHECK (replan_ordinal IN (3,4)),
  justification_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > issued_at_ms),
  UNIQUE (predecessor_run_id, replan_ordinal)
) STRICT;

CREATE TABLE runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  predecessor_run_id TEXT REFERENCES runs(id),
  run_kind TEXT NOT NULL CHECK (run_kind IN ('planning','delivery')),
  project_slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  state TEXT NOT NULL CHECK (
    state IN ('created','active','blocked','paused',
              'completed','failed','cancelled')
  ),
  root_request_digest TEXT NOT NULL,
  root_command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  admission_permit_digest TEXT UNIQUE REFERENCES project_admission_permits(digest),
  pipeline_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  benchmark_preregistration_digest TEXT REFERENCES benchmark_preregistrations(digest),
  benchmark_task_id TEXT,
  benchmark_arm TEXT CHECK (benchmark_arm IS NULL OR benchmark_arm IN ('A','B','C','D')),
  replan_ordinal INTEGER NOT NULL DEFAULT 0 CHECK (replan_ordinal BETWEEN 0 AND 4),
  replan_override_authorization_digest TEXT UNIQUE
    REFERENCES replan_override_authorizations(digest),
  plan_manifest_digest TEXT REFERENCES artifact_manifests(digest),
  plan_author_attestation_digest TEXT UNIQUE REFERENCES plan_author_attestations(digest),
  created_at_ms INTEGER NOT NULL,
  finished_at_ms INTEGER,
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  CHECK ((admission_permit_digest IS NOT NULL) <> (root_command_authorization_digest IS NOT NULL)),
  CHECK (
    (benchmark_preregistration_digest IS NULL
      AND benchmark_task_id IS NULL AND benchmark_arm IS NULL)
    OR
    (benchmark_preregistration_digest IS NOT NULL
      AND benchmark_task_id IS NOT NULL AND benchmark_arm IS NOT NULL)
  ),
  CHECK (benchmark_preregistration_digest IS NULL OR replan_ordinal = 0)
) STRICT;

CREATE UNIQUE INDEX one_open_run_per_project
ON runs(project_id)
WHERE state IN ('created','active','blocked','paused');

CREATE UNIQUE INDEX one_successor_per_run
ON runs(predecessor_run_id)
WHERE predecessor_run_id IS NOT NULL;

CREATE TABLE logical_nodes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  node_key TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (project_id, node_key)
) STRICT;

CREATE TABLE node_versions (
  id TEXT PRIMARY KEY,
  logical_node_id TEXT NOT NULL REFERENCES logical_nodes(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  version_no INTEGER NOT NULL CHECK (version_no >= 1),
  stage TEXT NOT NULL,
  role TEXT NOT NULL,
  required_pool TEXT NOT NULL CHECK (required_pool IN ('fable','codex','opus')),
  required_capability TEXT NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('pending','ready','dispatched','accepted','failed',
              'superseded','cancelled')
  ),
  input_manifest_digest TEXT REFERENCES artifact_manifests(digest),
  output_schema_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  retry_limit INTEGER NOT NULL DEFAULT 2 CHECK (retry_limit BETWEEN 0 AND 5),
  estimated_cost_units INTEGER NOT NULL DEFAULT 1 CHECK (estimated_cost_units BETWEEN 1 AND 1000),
  ready_since_ms INTEGER,
  current_attempt_id TEXT REFERENCES attempts(id),
  accepted_attempt_id TEXT UNIQUE REFERENCES attempts(id),
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  created_at_ms INTEGER NOT NULL,
  CHECK ((state = 'accepted') = (accepted_attempt_id IS NOT NULL)),
  UNIQUE (logical_node_id, run_id, version_no)
) STRICT;

CREATE TABLE failover_decisions (
  id TEXT PRIMARY KEY,
  authorization_digest TEXT NOT NULL UNIQUE REFERENCES failover_authorizations(digest),
  from_node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  to_node_version_id TEXT NOT NULL UNIQUE REFERENCES node_versions(id),
  fallback_pool TEXT NOT NULL CHECK (fallback_pool IN ('fable','codex','opus')),
  fallback_capability TEXT NOT NULL,
  reason_code TEXT NOT NULL CHECK (
    reason_code IN ('provider_outage','capacity_exhausted','policy_fallback',
                    'breaker_open','deadline_exhausted')
  ),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  provider_observation_id TEXT REFERENCES provider_health_observations(id),
  host_capacity_revision INTEGER CHECK (host_capacity_revision IS NULL OR host_capacity_revision >= 0),
  required_resource_profile_digest TEXT REFERENCES resource_profiles(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  project_slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  owner_fence INTEGER NOT NULL CHECK (owner_fence >= 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  CHECK (from_node_version_id <> to_node_version_id)
) STRICT;

CREATE TABLE failover_authorizations (
  digest TEXT PRIMARY KEY,
  from_node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  to_node_version_id TEXT NOT NULL,
  logical_node_id TEXT NOT NULL REFERENCES logical_nodes(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  version_no INTEGER NOT NULL CHECK (version_no BETWEEN 2 AND 3),
  stage TEXT NOT NULL,
  role TEXT NOT NULL,
  fallback_pool TEXT NOT NULL CHECK (fallback_pool IN ('fable','codex','opus')),
  fallback_capability TEXT NOT NULL,
  output_schema_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  retry_limit INTEGER NOT NULL CHECK (retry_limit BETWEEN 0 AND 5),
  estimated_cost_units INTEGER NOT NULL CHECK (estimated_cost_units BETWEEN 1 AND 1000),
  dependencies_json TEXT NOT NULL CHECK (json_valid(dependencies_json)),
  reason_code TEXT NOT NULL CHECK (
    reason_code IN ('provider_outage','capacity_exhausted','policy_fallback',
                    'breaker_open','deadline_exhausted')
  ),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  provider_observation_id TEXT REFERENCES provider_health_observations(id),
  host_capacity_revision INTEGER CHECK (host_capacity_revision IS NULL OR host_capacity_revision >= 0),
  required_resource_profile_digest TEXT REFERENCES resource_profiles(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  project_slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  owner_fence INTEGER NOT NULL CHECK (owner_fence >= 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK (
    (reason_code IN ('provider_outage','breaker_open')
      AND provider_observation_id IS NOT NULL AND host_capacity_revision IS NULL
      AND required_resource_profile_digest IS NULL)
    OR (reason_code = 'capacity_exhausted'
      AND provider_observation_id IS NULL AND host_capacity_revision IS NOT NULL
      AND required_resource_profile_digest IS NOT NULL)
    OR (reason_code IN ('policy_fallback','deadline_exhausted')
      AND provider_observation_id IS NULL AND host_capacity_revision IS NULL
      AND required_resource_profile_digest IS NULL)
  )
) STRICT;

CREATE TABLE node_dependencies (
  node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  depends_on_node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  dependency_type TEXT NOT NULL CHECK (
    dependency_type IN ('hard','artifact','review','approval','merge')
  ),
  PRIMARY KEY (node_version_id, depends_on_node_version_id),
  CHECK (node_version_id <> depends_on_node_version_id)
) STRICT;

CREATE VIEW node_replacement_reachability AS
WITH RECURSIVE replacement_chain(root_node_version_id, reachable_node_version_id) AS (
  SELECT node.id, node.id FROM node_versions node
  UNION ALL
  SELECT chain.root_node_version_id, decision.to_node_version_id
  FROM replacement_chain chain
  JOIN failover_decisions decision
    ON decision.from_node_version_id = chain.reachable_node_version_id
)
SELECT root_node_version_id, reachable_node_version_id
FROM replacement_chain;

CREATE VIEW resolved_dependency_winners AS
SELECT dependency.node_version_id,
       dependency.depends_on_node_version_id AS declared_parent_node_version_id,
       dependency.dependency_type,
       winner.id AS accepted_parent_node_version_id,
       winner.accepted_attempt_id AS accepted_parent_attempt_id
FROM node_dependencies dependency
JOIN node_replacement_reachability reachability
  ON reachability.root_node_version_id = dependency.depends_on_node_version_id
JOIN node_versions winner
  ON winner.id = reachability.reachable_node_version_id
 AND winner.state = 'accepted';

CREATE TABLE attempts (
  id TEXT PRIMARY KEY,
  node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  project_id TEXT NOT NULL REFERENCES projects(id),
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  dispatch_key TEXT NOT NULL UNIQUE,
  executor_id TEXT NOT NULL REFERENCES executors(id),
  executor_slot_id TEXT NOT NULL,
  fence INTEGER NOT NULL CHECK (fence >= 1),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  project_slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  role TEXT NOT NULL,
  runtime TEXT NOT NULL,
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  model TEXT NOT NULL,
  model_family TEXT NOT NULL,
  profile TEXT NOT NULL,
  pricing_catalog_digest TEXT NOT NULL REFERENCES pricing_catalogs(digest),
  max_input_tokens INTEGER NOT NULL CHECK (max_input_tokens BETWEEN 1 AND 2000000),
  max_output_tokens INTEGER NOT NULL CHECK (max_output_tokens BETWEEN 1 AND 2000000),
  max_cache_read_tokens INTEGER NOT NULL CHECK (max_cache_read_tokens BETWEEN 0 AND 4000000),
  max_cache_write_tokens INTEGER NOT NULL CHECK (max_cache_write_tokens BETWEEN 0 AND 4000000),
  max_tool_calls INTEGER NOT NULL CHECK (max_tool_calls BETWEEN 0 AND 400),
  max_wall_time_ms INTEGER NOT NULL CHECK (max_wall_time_ms BETWEEN 1 AND 7200000),
  required_reservation_micro_usd INTEGER NOT NULL CHECK (required_reservation_micro_usd > 0),
  benchmark_treatment_cell_id TEXT
    REFERENCES benchmark_treatment_call_cells(id),
  fairness_dispatch_permit_digest TEXT NOT NULL UNIQUE
    REFERENCES fairness_dispatch_permits(digest),
  lineage_digest TEXT NOT NULL,
  input_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  state TEXT NOT NULL CHECK (
    state IN ('created','dispatched','acked','running','result_pending',
              'accepted','failed','expired','cancelled','stale',
              'quarantined','unknown')
  ),
  ack_deadline_ms INTEGER NOT NULL,
  lease_deadline_ms INTEGER NOT NULL,
  hard_deadline_ms INTEGER NOT NULL,
  created_at_ms INTEGER NOT NULL,
  started_at_ms INTEGER,
  finished_at_ms INTEGER,
  error_code TEXT,
  FOREIGN KEY (executor_slot_id, executor_id)
    REFERENCES executor_slots(id, executor_id),
  UNIQUE (node_version_id, attempt_no),
  UNIQUE (id, dispatch_key),
  UNIQUE (id, executor_id),
  UNIQUE (id, executor_slot_id, fence),
  CHECK (created_at_ms < ack_deadline_ms),
  CHECK (ack_deadline_ms <= lease_deadline_ms),
  CHECK (lease_deadline_ms <= hard_deadline_ms),
  CHECK (hard_deadline_ms <= created_at_ms + max_wall_time_ms + 120000)
) STRICT;

CREATE UNIQUE INDEX one_live_attempt_per_node_version
ON attempts(node_version_id)
WHERE state IN ('created','dispatched','acked','running','result_pending','unknown');

CREATE UNIQUE INDEX one_accepted_attempt_per_node_version
ON attempts(node_version_id) WHERE state = 'accepted';

CREATE UNIQUE INDEX one_live_attempt_per_executor
ON attempts(executor_id)
WHERE state IN ('created','dispatched','acked','running','result_pending','unknown');

CREATE TABLE leases (
  id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL UNIQUE,
  executor_slot_id TEXT NOT NULL,
  fence INTEGER NOT NULL,
  worker_instance_id TEXT NOT NULL,
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  state TEXT NOT NULL CHECK (
    state IN ('active','released','expired','revoked','quarantined')
  ),
  heartbeat_seq INTEGER NOT NULL DEFAULT 0 CHECK (heartbeat_seq >= 0),
  acquired_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  released_at_ms INTEGER,
  FOREIGN KEY (attempt_id, executor_slot_id, fence)
    REFERENCES attempts(id, executor_slot_id, fence)
) STRICT;

CREATE UNIQUE INDEX one_active_lease_per_physical_slot
ON leases(executor_slot_id) WHERE state = 'active';

CREATE TABLE runtime_intents (
  id TEXT PRIMARY KEY,
  executor_id TEXT NOT NULL REFERENCES executors(id),
  executor_slot_id TEXT NOT NULL,
  session_scope TEXT NOT NULL CHECK (session_scope IN ('portfolio','project_generation')),
  project_id TEXT REFERENCES projects(id),
  project_slot_no INTEGER REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER CHECK (project_slot_generation >= 1),
  fence INTEGER NOT NULL CHECK (fence >= 1),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  worker_instance_id TEXT NOT NULL,
  launch_identity TEXT NOT NULL UNIQUE,
  process_identity TEXT NOT NULL UNIQUE,
  provider_idempotency_key TEXT NOT NULL UNIQUE,
  scope_epoch INTEGER NOT NULL CHECK (scope_epoch >= 1),
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  state TEXT NOT NULL CHECK (state IN ('prepared','launch_claimed','launch_permitted','launched','terminated','unknown','cancelled','failed')),
  claim_token TEXT,
  claim_until_ms INTEGER,
  created_at_ms INTEGER NOT NULL,
  FOREIGN KEY (executor_slot_id, executor_id) REFERENCES executor_slots(id, executor_id),
  CHECK (
    (session_scope = 'portfolio' AND project_id IS NULL
      AND project_slot_no IS NULL AND project_slot_generation IS NULL)
    OR (session_scope = 'project_generation' AND project_id IS NOT NULL
      AND project_slot_no IS NOT NULL AND project_slot_generation IS NOT NULL)
  )
) STRICT;

CREATE UNIQUE INDEX one_live_persistent_runtime_intent_per_executor
ON runtime_intents(executor_id)
WHERE state IN ('prepared','launch_claimed','launch_permitted','launched','unknown');

CREATE TABLE charge_subjects (
  id TEXT PRIMARY KEY,
  scope_kind TEXT NOT NULL CHECK (
    scope_kind IN ('attempt','portfolio_runtime','project_runtime','service_operation')
  ),
  attempt_id TEXT UNIQUE REFERENCES attempts(id),
  runtime_intent_id TEXT UNIQUE REFERENCES runtime_intents(id),
  service_operation_key TEXT UNIQUE,
  project_id TEXT REFERENCES projects(id),
  billing_provider TEXT NOT NULL CHECK (billing_provider IN ('anthropic','openai')),
  billing_model TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  CHECK (
    (scope_kind = 'attempt'
      AND attempt_id IS NOT NULL
      AND runtime_intent_id IS NULL
      AND service_operation_key IS NULL
      AND project_id IS NOT NULL)
    OR (scope_kind = 'portfolio_runtime'
      AND attempt_id IS NULL
      AND runtime_intent_id IS NOT NULL
      AND service_operation_key IS NULL
      AND project_id IS NULL)
    OR (scope_kind = 'project_runtime'
      AND attempt_id IS NULL
      AND runtime_intent_id IS NOT NULL
      AND service_operation_key IS NULL
      AND project_id IS NOT NULL)
    OR (scope_kind = 'service_operation'
      AND attempt_id IS NULL
      AND runtime_intent_id IS NULL
      AND service_operation_key IS NOT NULL
      AND project_id IS NULL)
  )
) STRICT;

CREATE TABLE managed_service_identities (
  digest TEXT PRIMARY KEY,
  service_alias TEXT NOT NULL CHECK (service_alias IN ('morty','space-beth')),
  version INTEGER NOT NULL CHECK (version >= 1),
  principal_id TEXT NOT NULL REFERENCES principals(id),
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  sandbox_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  config_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  workspace_root TEXT NOT NULL,
  asset_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  sanitization_attestation_digest TEXT NOT NULL REFERENCES sanitization_attestations(digest),
  sanitization_rules_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (service_alias, version),
  UNIQUE (service_alias, principal_id, version)
) STRICT;

CREATE TABLE managed_service_identity_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  managed_identity_digest TEXT NOT NULL UNIQUE REFERENCES managed_service_identities(digest),
  replacement_identity_digest TEXT REFERENCES managed_service_identities(digest),
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL,
  CHECK (replacement_identity_digest IS NULL OR replacement_identity_digest <> managed_identity_digest)
) STRICT;

CREATE TABLE managed_service_intents (
  id TEXT PRIMARY KEY,
  service_alias TEXT NOT NULL CHECK (service_alias IN ('morty','space-beth')),
  managed_identity_digest TEXT NOT NULL REFERENCES managed_service_identities(digest),
  principal_id TEXT NOT NULL REFERENCES principals(id),
  charge_subject_id TEXT NOT NULL UNIQUE REFERENCES charge_subjects(id),
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  service_epoch INTEGER NOT NULL CHECK (service_epoch >= 1),
  launch_identity TEXT NOT NULL UNIQUE,
  process_identity TEXT NOT NULL UNIQUE,
  provider_idempotency_key TEXT NOT NULL UNIQUE,
  state TEXT NOT NULL CHECK (state IN ('prepared','launch_claimed','launch_permitted','launched','terminated','unknown','cancelled','failed')),
  claim_token TEXT,
  claim_until_ms INTEGER,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE UNIQUE INDEX one_live_managed_service_intent_per_alias
ON managed_service_intents(service_alias)
WHERE state IN ('prepared','launch_claimed','launch_permitted','launched','unknown');

CREATE TABLE managed_service_sessions (
  id TEXT PRIMARY KEY,
  service_alias TEXT NOT NULL CHECK (service_alias IN ('morty','space-beth')),
  managed_identity_digest TEXT NOT NULL REFERENCES managed_service_identities(digest),
  principal_id TEXT NOT NULL REFERENCES principals(id),
  managed_service_intent_id TEXT NOT NULL UNIQUE REFERENCES managed_service_intents(id),
  process_identity TEXT NOT NULL UNIQUE,
  provider_session_id TEXT NOT NULL UNIQUE,
  runtime_catalog_digest TEXT NOT NULL REFERENCES runtime_catalogs(digest),
  runtime TEXT NOT NULL,
  actual_model TEXT NOT NULL,
  actual_model_family TEXT NOT NULL,
  actual_profile TEXT NOT NULL,
  sandbox_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  private_home_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  handshake_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('starting','running','terminating','terminated','unknown')),
  started_at_ms INTEGER NOT NULL,
  terminated_at_ms INTEGER,
  termination_reason TEXT,
  UNIQUE (service_alias, provider_session_id)
) STRICT;

CREATE TABLE budget_reservations (
  id TEXT PRIMARY KEY,
  budget_account_id TEXT NOT NULL REFERENCES budget_accounts(id),
  charge_subject_id TEXT NOT NULL REFERENCES charge_subjects(id),
  runtime_call_lease_id TEXT REFERENCES runtime_call_leases(id),
  reservation_no INTEGER NOT NULL CHECK (reservation_no >= 1),
  pricing_catalog_digest TEXT NOT NULL REFERENCES pricing_catalogs(digest),
  amount_micro_usd INTEGER NOT NULL CHECK (amount_micro_usd > 0),
  consumed_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK (consumed_micro_usd >= 0),
  state TEXT NOT NULL CHECK (
    state IN ('held','partially_consumed','consumed','released','breached')
  ),
  created_at_ms INTEGER NOT NULL,
  closed_at_ms INTEGER,
  UNIQUE (charge_subject_id, reservation_no)
) STRICT;

CREATE TABLE usage_events (
  id TEXT PRIMARY KEY,
  charge_subject_id TEXT NOT NULL REFERENCES charge_subjects(id),
  reservation_id TEXT NOT NULL REFERENCES budget_reservations(id),
  provider TEXT NOT NULL,
  provider_usage_id TEXT,
  sequence_no INTEGER NOT NULL CHECK (sequence_no >= 1),
  pricing_catalog_digest TEXT NOT NULL REFERENCES pricing_catalogs(digest),
  delta_micro_usd INTEGER NOT NULL CHECK (delta_micro_usd >= 0),
  input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens BETWEEN 0 AND 2000000),
  output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens BETWEEN 0 AND 2000000),
  cache_read_tokens INTEGER NOT NULL DEFAULT 0 CHECK (cache_read_tokens BETWEEN 0 AND 4000000),
  cache_write_tokens INTEGER NOT NULL DEFAULT 0 CHECK (cache_write_tokens BETWEEN 0 AND 4000000),
  tool_calls INTEGER NOT NULL DEFAULT 0 CHECK (tool_calls BETWEEN 0 AND 400),
  wall_time_ms INTEGER NOT NULL DEFAULT 0 CHECK (wall_time_ms BETWEEN 0 AND 7200000),
  final_marker INTEGER NOT NULL DEFAULT 0 CHECK (final_marker IN (0,1)),
  observed_at_ms INTEGER NOT NULL,
  payload_digest TEXT NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  UNIQUE (reservation_id, sequence_no)
) STRICT;

CREATE UNIQUE INDEX unique_provider_usage_event
ON usage_events(provider, provider_usage_id)
WHERE provider_usage_id IS NOT NULL;

CREATE TABLE budget_ledger (
  id TEXT PRIMARY KEY,
  budget_account_id TEXT NOT NULL REFERENCES budget_accounts(id),
  reservation_id TEXT REFERENCES budget_reservations(id),
  usage_event_id TEXT REFERENCES usage_events(id),
  entry_type TEXT NOT NULL CHECK (
    entry_type IN ('reserve','spend','release','adjustment')
  ),
  delta_reserved_micro_usd INTEGER NOT NULL,
  delta_spent_micro_usd INTEGER NOT NULL,
  source_key TEXT NOT NULL UNIQUE,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE host_capacity_measurements (
  id TEXT PRIMARY KEY,
  host_id TEXT NOT NULL,
  measured_free_disk_bytes INTEGER NOT NULL CHECK (measured_free_disk_bytes >= 0),
  measured_physical_ram_bytes INTEGER NOT NULL CHECK (measured_physical_ram_bytes > 0),
  measured_available_ram_bytes INTEGER NOT NULL CHECK (measured_available_ram_bytes >= 0),
  observed_platform_rss_bytes INTEGER NOT NULL CHECK (observed_platform_rss_bytes >= 0),
  measured_logical_cpu_millis INTEGER NOT NULL CHECK (measured_logical_cpu_millis > 0),
  measurement_at_ms INTEGER NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  UNIQUE (host_id, measurement_at_ms),
  CHECK (measured_available_ram_bytes <= measured_physical_ram_bytes),
  CHECK (observed_platform_rss_bytes <= measured_physical_ram_bytes)
) STRICT;

CREATE TABLE host_capacity (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  host_id TEXT NOT NULL,
  measurement_id TEXT NOT NULL UNIQUE REFERENCES host_capacity_measurements(id),
  resource_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  measured_free_disk_bytes INTEGER NOT NULL CHECK (measured_free_disk_bytes >= 0),
  reserved_disk_bytes INTEGER NOT NULL DEFAULT 0 CHECK (reserved_disk_bytes >= 0),
  emergency_reserve_bytes INTEGER NOT NULL CHECK (emergency_reserve_bytes >= 0),
  clone_log_allowance_bytes INTEGER NOT NULL CHECK (clone_log_allowance_bytes >= 0),
  measured_physical_ram_bytes INTEGER NOT NULL CHECK (measured_physical_ram_bytes > 0),
  measured_available_ram_bytes INTEGER NOT NULL CHECK (measured_available_ram_bytes >= 0),
  observed_platform_rss_bytes INTEGER NOT NULL CHECK (observed_platform_rss_bytes >= 0),
  max_model_rss_bytes INTEGER NOT NULL CHECK (max_model_rss_bytes > 0),
  reserved_rss_bytes INTEGER NOT NULL DEFAULT 0 CHECK (reserved_rss_bytes >= 0),
  emergency_ram_bytes INTEGER NOT NULL CHECK (emergency_ram_bytes > 0),
  max_model_pid_count INTEGER NOT NULL CHECK (max_model_pid_count > 0),
  reserved_pid_count INTEGER NOT NULL DEFAULT 0 CHECK (reserved_pid_count >= 0),
  max_model_fd_count INTEGER NOT NULL CHECK (max_model_fd_count > 0),
  reserved_fd_count INTEGER NOT NULL DEFAULT 0 CHECK (reserved_fd_count >= 0),
  measured_logical_cpu_millis INTEGER NOT NULL CHECK (measured_logical_cpu_millis > 0),
  max_model_cpu_millis INTEGER NOT NULL CHECK (max_model_cpu_millis > 0),
  reserved_cpu_millis INTEGER NOT NULL DEFAULT 0 CHECK (reserved_cpu_millis >= 0),
  measurement_at_ms INTEGER NOT NULL,
  revision INTEGER NOT NULL CHECK (revision >= 0),
  CHECK (measured_available_ram_bytes <= measured_physical_ram_bytes),
  CHECK (observed_platform_rss_bytes <= measured_physical_ram_bytes)
) STRICT;

CREATE TABLE runtime_call_leases (
  id TEXT PRIMARY KEY,
  charge_subject_id TEXT NOT NULL REFERENCES charge_subjects(id),
  call_no INTEGER NOT NULL CHECK (call_no >= 1),
  pricing_catalog_digest TEXT NOT NULL REFERENCES pricing_catalogs(digest),
  max_input_tokens INTEGER NOT NULL CHECK (max_input_tokens BETWEEN 1 AND 2000000),
  max_output_tokens INTEGER NOT NULL CHECK (max_output_tokens BETWEEN 1 AND 2000000),
  max_cache_read_tokens INTEGER NOT NULL CHECK (max_cache_read_tokens BETWEEN 0 AND 4000000),
  max_cache_write_tokens INTEGER NOT NULL CHECK (max_cache_write_tokens BETWEEN 0 AND 4000000),
  max_tool_calls INTEGER NOT NULL CHECK (max_tool_calls BETWEEN 0 AND 400),
  max_wall_time_ms INTEGER NOT NULL CHECK (max_wall_time_ms BETWEEN 1 AND 7200000),
  required_reservation_micro_usd INTEGER NOT NULL CHECK (required_reservation_micro_usd > 0),
  provider_call_key TEXT NOT NULL UNIQUE,
  provider_call_id TEXT UNIQUE,
  state TEXT NOT NULL CHECK (state IN ('prepared','active','released','expired','unknown')),
  claim_token TEXT,
  claim_until_ms INTEGER,
  created_at_ms INTEGER NOT NULL,
  started_at_ms INTEGER,
  ended_at_ms INTEGER,
  UNIQUE (charge_subject_id, call_no)
) STRICT;

CREATE UNIQUE INDEX one_live_runtime_call_per_charge_subject
ON runtime_call_leases(charge_subject_id)
WHERE state IN ('prepared','active','unknown');

CREATE TABLE resource_reservations (
  id TEXT PRIMARY KEY,
  charge_subject_id TEXT NOT NULL REFERENCES charge_subjects(id),
  reservation_no INTEGER NOT NULL CHECK (reservation_no >= 1),
  runtime_call_lease_id TEXT UNIQUE REFERENCES runtime_call_leases(id),
  resource_profile_digest TEXT NOT NULL REFERENCES resource_profiles(digest),
  reservation_kind TEXT NOT NULL CHECK (reservation_kind IN ('process','active_call')),
  disk_bytes INTEGER NOT NULL CHECK (disk_bytes >= 0),
  rss_bytes INTEGER NOT NULL CHECK (rss_bytes >= 0),
  pid_count INTEGER NOT NULL CHECK (pid_count >= 0),
  fd_count INTEGER NOT NULL CHECK (fd_count >= 0),
  cpu_millis INTEGER NOT NULL CHECK (cpu_millis > 0),
  state TEXT NOT NULL CHECK (state IN ('held','released','breached')),
  breach_attestation_digest TEXT UNIQUE
    REFERENCES resource_breach_attestations(digest),
  breached_at_ms INTEGER,
  created_at_ms INTEGER NOT NULL,
  released_at_ms INTEGER,
  UNIQUE (charge_subject_id, reservation_no),
  CHECK (
    (reservation_kind = 'process'
      AND disk_bytes > 0 AND rss_bytes > 0 AND pid_count > 0 AND fd_count > 0)
    OR (reservation_kind = 'active_call'
      AND disk_bytes = 0 AND rss_bytes = 0 AND pid_count = 0 AND fd_count = 0)
  ),
  CHECK ((breach_attestation_digest IS NULL) = (breached_at_ms IS NULL)),
  CHECK (state <> 'held' OR breach_attestation_digest IS NULL),
  CHECK ((state = 'released') = (released_at_ms IS NOT NULL))
) STRICT;

CREATE TABLE resource_residency_observations (
  id TEXT PRIMARY KEY,
  resource_reservation_id TEXT NOT NULL REFERENCES resource_reservations(id),
  process_identity TEXT NOT NULL,
  active_call_resource_reservation_id TEXT REFERENCES resource_reservations(id),
  effective_cpu_limit_millis INTEGER NOT NULL CHECK (effective_cpu_limit_millis > 0),
  sample_seq INTEGER NOT NULL CHECK (sample_seq >= 1),
  window_start_ms INTEGER NOT NULL,
  resident_rss_bytes INTEGER NOT NULL CHECK (resident_rss_bytes >= 0),
  resident_disk_bytes INTEGER NOT NULL CHECK (resident_disk_bytes >= 0),
  resident_pid_count INTEGER NOT NULL CHECK (resident_pid_count >= 0),
  open_fd_count INTEGER NOT NULL CHECK (open_fd_count >= 0),
  cpu_millis_in_window INTEGER NOT NULL CHECK (cpu_millis_in_window >= 0),
  observed_at_ms INTEGER NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  UNIQUE (resource_reservation_id, observed_at_ms),
  UNIQUE (resource_reservation_id, sample_seq),
  CHECK (window_start_ms <= observed_at_ms)
) STRICT;

CREATE TABLE resource_breach_attestations (
  digest TEXT PRIMARY KEY,
  resource_reservation_id TEXT NOT NULL UNIQUE REFERENCES resource_reservations(id),
  process_identity TEXT NOT NULL,
  resource_profile_digest TEXT NOT NULL REFERENCES resource_profiles(digest),
  breach_dimension TEXT NOT NULL CHECK (
    breach_dimension IN ('rss_bytes','disk_bytes','pid_count','fd_count','cpu_millis')
  ),
  threshold_value INTEGER NOT NULL CHECK (threshold_value >= 0),
  first_observation_id TEXT NOT NULL UNIQUE REFERENCES resource_residency_observations(id),
  last_observation_id TEXT NOT NULL UNIQUE REFERENCES resource_residency_observations(id),
  consecutive_sample_count INTEGER NOT NULL CHECK (consecutive_sample_count >= 2),
  breach_started_at_ms INTEGER NOT NULL,
  breach_confirmed_at_ms INTEGER NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  CHECK (breach_confirmed_at_ms - breach_started_at_ms >= 5000),
  CHECK (breach_started_at_ms <= created_at_ms)
) STRICT;

CREATE TABLE process_termination_receipts (
  digest TEXT PRIMARY KEY,
  resource_reservation_id TEXT NOT NULL UNIQUE REFERENCES resource_reservations(id),
  process_identity TEXT NOT NULL,
  observed_process_state TEXT NOT NULL CHECK (observed_process_state IN ('dead','absent')),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL
) STRICT;

CREATE VIEW fresh_resource_residency_credit AS
SELECT rr.id AS resource_reservation_id,
       m.id AS measurement_id,
       MIN(rr.rss_bytes, ro.resident_rss_bytes) AS credited_rss_bytes,
       MIN(rr.disk_bytes, ro.resident_disk_bytes) AS credited_disk_bytes,
       MIN(rr.pid_count, ro.resident_pid_count) AS observed_pid_count,
       MIN(rr.fd_count, ro.open_fd_count) AS observed_fd_count,
       MIN(rr.cpu_millis, ro.cpu_millis_in_window) AS observed_cpu_millis,
       ro.observed_at_ms
FROM resource_reservations rr
JOIN resource_residency_observations ro
  ON ro.resource_reservation_id = rr.id
JOIN host_capacity hc ON hc.singleton = 1
JOIN host_capacity_measurements m ON m.id = hc.measurement_id
JOIN current_valid_keys observation_key
  ON observation_key.key_id = ro.signer_key_id
 AND observation_key.principal_id = ro.signer_principal_id
 AND observation_key.key_purpose = 'runtime_supervisor'
WHERE rr.reservation_kind = 'process'
  AND rr.state IN ('held','breached')
  AND ro.observed_at_ms = (
    SELECT MAX(newest.observed_at_ms)
    FROM resource_residency_observations newest
    WHERE newest.resource_reservation_id = rr.id
      AND newest.observed_at_ms <= m.measurement_at_ms
  )
  AND ro.observed_at_ms BETWEEN m.measurement_at_ms - 5000 AND m.measurement_at_ms;

CREATE VIEW current_host_capacity AS
SELECT hc.*,
       hc.reserved_rss_bytes - COALESCE(credits.credited_rss_bytes, 0)
         AS pending_reserved_rss_bytes,
       hc.reserved_disk_bytes - COALESCE(credits.credited_disk_bytes, 0)
         AS pending_reserved_disk_bytes
FROM host_capacity hc
JOIN host_capacity_measurements m ON m.id = hc.measurement_id
JOIN current_valid_keys measurement_key
  ON measurement_key.key_id = m.signer_key_id
 AND measurement_key.principal_id = m.signer_principal_id
 AND measurement_key.key_purpose = 'runtime_supervisor'
JOIN artifact_manifests evidence ON evidence.digest = m.evidence_manifest_digest
JOIN current_valid_keys evidence_key
  ON evidence_key.key_id = evidence.signer_key_id
 AND evidence_key.key_purpose = 'artifact_broker'
JOIN policies policy ON policy.digest = hc.resource_policy_digest
JOIN current_valid_keys policy_key
  ON policy_key.key_id = policy.signer_key_id
 AND policy_key.key_purpose = 'control_plane'
LEFT JOIN (
  SELECT measurement_id,
         COALESCE(SUM(credited_rss_bytes), 0) AS credited_rss_bytes,
         COALESCE(SUM(credited_disk_bytes), 0) AS credited_disk_bytes
  FROM fresh_resource_residency_credit
  GROUP BY measurement_id
) credits ON credits.measurement_id = m.id
WHERE hc.singleton = 1
  AND hc.measurement_id = m.id
  AND hc.measurement_at_ms = m.measurement_at_ms
  AND m.measurement_at_ms BETWEEN (unixepoch('subsec') * 1000) - 60000
                              AND (unixepoch('subsec') * 1000) + 5000
  AND hc.measured_free_disk_bytes
      - (hc.reserved_disk_bytes - COALESCE(credits.credited_disk_bytes, 0))
      - hc.clone_log_allowance_bytes >= hc.emergency_reserve_bytes
  AND hc.measured_available_ram_bytes
      - (hc.reserved_rss_bytes - COALESCE(credits.credited_rss_bytes, 0))
      >= hc.emergency_ram_bytes
  AND hc.reserved_pid_count <= hc.max_model_pid_count
  AND hc.reserved_fd_count <= hc.max_model_fd_count
  AND hc.reserved_cpu_millis <= hc.max_model_cpu_millis
  AND NOT EXISTS (
    SELECT 1
    FROM resource_reservations process_reservation
    WHERE process_reservation.reservation_kind = 'process'
      AND process_reservation.state IN ('held','breached')
      AND process_reservation.created_at_ms
            <= (unixepoch('subsec') * 1000) - 5000
      AND EXISTS (
        SELECT 1
        FROM charge_subjects process_subject
        WHERE process_subject.id = process_reservation.charge_subject_id
          AND (
            (process_subject.scope_kind = 'attempt' AND EXISTS (
              SELECT 1 FROM attempts attempt
              JOIN dispatch_receipts dispatch ON dispatch.attempt_id = attempt.id
              WHERE attempt.id = process_subject.attempt_id
                AND dispatch.state IN ('launched','unknown')
            ))
            OR (process_subject.scope_kind IN ('portfolio_runtime','project_runtime')
              AND EXISTS (
                SELECT 1 FROM runtime_intents runtime
                WHERE runtime.id = process_subject.runtime_intent_id
                  AND runtime.state IN ('launched','unknown')
              ))
            OR (process_subject.scope_kind = 'service_operation' AND EXISTS (
              SELECT 1 FROM managed_service_intents managed
              WHERE managed.charge_subject_id = process_subject.id
                AND managed.state IN ('launched','unknown')
            ))
          )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM resource_residency_observations observation
        JOIN current_valid_keys observation_key
          ON observation_key.key_id = observation.signer_key_id
         AND observation_key.principal_id = observation.signer_principal_id
         AND observation_key.key_purpose = 'runtime_supervisor'
        WHERE observation.resource_reservation_id = process_reservation.id
          AND observation.observed_at_ms
                BETWEEN (unixepoch('subsec') * 1000) - 5000
                    AND (unixepoch('subsec') * 1000) + 5000
      )
  )
  AND NOT EXISTS (
    SELECT 1
    FROM resource_reservations active_call
    WHERE active_call.reservation_kind = 'active_call'
      AND active_call.state IN ('held','breached')
      AND active_call.created_at_ms <= (unixepoch('subsec') * 1000) - 5000
      AND (
        (active_call.runtime_call_lease_id IS NOT NULL AND EXISTS (
          SELECT 1 FROM runtime_call_leases call_lease
          WHERE call_lease.id = active_call.runtime_call_lease_id
            AND call_lease.state IN ('active','unknown')
        ))
        OR (active_call.runtime_call_lease_id IS NULL AND EXISTS (
          SELECT 1 FROM charge_subjects call_subject
          JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
          WHERE call_subject.id = active_call.charge_subject_id
            AND call_subject.scope_kind = 'attempt'
            AND call_attempt.state IN ('dispatched','acked','running','result_pending','unknown')
        ))
      )
      AND NOT EXISTS (
        SELECT 1
        FROM resource_residency_observations observation
        JOIN current_valid_keys observation_key
          ON observation_key.key_id = observation.signer_key_id
         AND observation_key.principal_id = observation.signer_principal_id
         AND observation_key.key_purpose = 'runtime_supervisor'
        WHERE observation.active_call_resource_reservation_id = active_call.id
          AND observation.observed_at_ms
                BETWEEN (unixepoch('subsec') * 1000) - 5000
                    AND (unixepoch('subsec') * 1000) + 5000
      )
  )
  AND NOT EXISTS (
    SELECT 1 FROM resource_reservations breached
    WHERE breached.state = 'breached'
  )
  AND NOT EXISTS (
    SELECT 1 FROM policy_invalidations pi
    WHERE pi.policy_digest = hc.resource_policy_digest
  );

CREATE UNIQUE INDEX one_live_process_resource_per_subject
ON resource_reservations(charge_subject_id)
WHERE reservation_kind = 'process' AND state IN ('held','breached');

CREATE UNIQUE INDEX one_live_call_resource_per_subject
ON resource_reservations(charge_subject_id)
WHERE reservation_kind = 'active_call' AND state IN ('held','breached');

CREATE TABLE commands (
  id TEXT PRIMARY KEY,
  source TEXT NOT NULL,
  partition_key TEXT NOT NULL,
  source_sequence INTEGER NOT NULL CHECK (source_sequence >= 1),
  source_command_id TEXT NOT NULL,
  principal_id TEXT NOT NULL REFERENCES principals(id),
  project_id TEXT REFERENCES projects(id),
  command_type TEXT NOT NULL,
  auth_context_digest TEXT NOT NULL,
  nonce TEXT NOT NULL UNIQUE,
  expires_at_ms INTEGER NOT NULL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  payload_digest TEXT NOT NULL,
  ingress_evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('received','authorized','applied','rejected','failed')
  ),
  result_json TEXT CHECK (result_json IS NULL OR json_valid(result_json)),
  received_at_ms INTEGER NOT NULL,
  authorized_at_ms INTEGER,
  completed_at_ms INTEGER,
  UNIQUE (source, source_command_id),
  UNIQUE (source, partition_key, source_sequence)
) STRICT;

CREATE TABLE command_authorizations (
  digest TEXT PRIMARY KEY,
  command_id TEXT NOT NULL UNIQUE REFERENCES commands(id),
  actor_principal_id TEXT NOT NULL REFERENCES principals(id),
  project_id TEXT REFERENCES projects(id),
  command_type TEXT NOT NULL,
  payload_digest TEXT NOT NULL,
  auth_context_digest TEXT NOT NULL,
  nonce TEXT NOT NULL,
  command_expires_at_ms INTEGER NOT NULL,
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  authorized_at_ms INTEGER NOT NULL,
  authorization_expires_at_ms INTEGER NOT NULL,
  CHECK (authorization_expires_at_ms > authorized_at_ms)
) STRICT;

CREATE TABLE command_consumptions (
  digest TEXT PRIMARY KEY,
  command_id TEXT NOT NULL UNIQUE REFERENCES commands(id),
  command_authorization_digest TEXT NOT NULL UNIQUE REFERENCES command_authorizations(digest),
  subject_kind TEXT NOT NULL CHECK (
    subject_kind IN ('project','control_state','budget_account','human_response',
                     'approval_decision','repository','project_repository',
                     'integration_target','authority_change','signing_key',
                     'role_grant','run')
  ),
  subject_id TEXT NOT NULL,
  prior_revision INTEGER CHECK (prior_revision IS NULL OR prior_revision >= 0),
  new_revision INTEGER CHECK (new_revision IS NULL OR new_revision >= 0),
  mutation_digest TEXT NOT NULL,
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  consumed_at_ms INTEGER NOT NULL,
  CHECK ((prior_revision IS NULL AND new_revision IS NULL)
      OR (prior_revision IS NULL AND new_revision = 0)
      OR (prior_revision IS NOT NULL AND new_revision = prior_revision + 1))
) STRICT;

CREATE UNIQUE INDEX one_command_consumption_per_subject_revision
ON command_consumptions(subject_kind, subject_id, COALESCE(new_revision, -1));

CREATE TABLE key_registration_authorizations (
  digest TEXT PRIMARY KEY,
  target_key_id TEXT NOT NULL,
  target_principal_id TEXT NOT NULL REFERENCES principals(id),
  target_public_key TEXT NOT NULL,
  target_public_key_fingerprint TEXT NOT NULL,
  target_key_purpose TEXT NOT NULL CHECK (
    target_key_purpose IN ('key_admin','control_plane','ingress_broker','artifact_broker',
                           'executor_result','runtime_supervisor','provider_observer',
                           'approval_broker','credential_broker','release_broker','schema_validator')
  ),
  target_expires_at_ms INTEGER,
  proof_of_possession_signature TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('register','revoke')),
  command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  installer_manifest_digest TEXT REFERENCES installation_trust_root(installer_manifest_digest),
  leader_term INTEGER REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK ((command_authorization_digest IS NULL) <> (installer_manifest_digest IS NULL)),
  CHECK (
    (installer_manifest_digest IS NOT NULL AND command_authorization_digest IS NULL
      AND leader_term IS NULL AND action = 'register')
    OR
    (command_authorization_digest IS NOT NULL AND installer_manifest_digest IS NULL
      AND leader_term IS NOT NULL)
  ),
  UNIQUE (target_key_id, action)
) STRICT;

CREATE TABLE role_change_authorizations (
  digest TEXT PRIMARY KEY,
  target_grant_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('grant','revoke')),
  role_scope TEXT NOT NULL CHECK (role_scope IN ('global','project')),
  target_principal_id TEXT NOT NULL REFERENCES principals(id),
  project_id TEXT REFERENCES projects(id),
  role TEXT NOT NULL,
  grantor_principal_id TEXT NOT NULL REFERENCES principals(id),
  command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  bootstrap_manifest_digest TEXT REFERENCES bootstrap_manifests(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK ((project_id IS NOT NULL) = (role_scope = 'project')),
  CHECK ((command_authorization_digest IS NULL) <> (bootstrap_manifest_digest IS NULL)),
  UNIQUE (target_grant_id, action)
) STRICT;

CREATE TABLE authority_change_authorizations (
  id TEXT PRIMARY KEY,
  command_id TEXT NOT NULL UNIQUE REFERENCES commands(id),
  target_kind TEXT NOT NULL CHECK (
    target_kind IN ('policy','configuration','runtime_catalog','pricing_catalog',
                    'managed_identity','gate_bundle','approval_request')
  ),
  target_id TEXT NOT NULL,
  replacement_target_id TEXT,
  project_id TEXT REFERENCES projects(id),
  action TEXT NOT NULL CHECK (action IN ('invalidate','revoke','supersede')),
  actor_principal_id TEXT NOT NULL REFERENCES principals(id),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK (
    (target_kind IN ('gate_bundle','approval_request') AND project_id IS NOT NULL)
    OR (target_kind NOT IN ('gate_bundle','approval_request') AND project_id IS NULL)
  )
) STRICT;

CREATE TABLE budget_change_authorizations (
  id TEXT PRIMARY KEY,
  budget_account_id TEXT NOT NULL REFERENCES budget_accounts(id),
  command_id TEXT NOT NULL UNIQUE REFERENCES commands(id),
  actor_principal_id TEXT NOT NULL REFERENCES principals(id),
  action TEXT NOT NULL CHECK (action IN ('cap_change','reactivate','freeze','close')),
  old_cap_micro_usd INTEGER NOT NULL CHECK (old_cap_micro_usd >= 0),
  new_cap_micro_usd INTEGER NOT NULL CHECK (new_cap_micro_usd >= 0),
  old_state TEXT NOT NULL CHECK (old_state IN ('active','breached','frozen','closed')),
  new_state TEXT NOT NULL CHECK (new_state IN ('active','breached','frozen','closed')),
  target_revision INTEGER NOT NULL CHECK (target_revision >= 1),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  UNIQUE (budget_account_id, target_revision)
) STRICT;

CREATE TABLE budget_account_creation_authorizations (
  digest TEXT PRIMARY KEY,
  budget_account_id TEXT NOT NULL UNIQUE,
  project_id TEXT REFERENCES projects(id),
  account_scope TEXT NOT NULL CHECK (account_scope IN ('project','portfolio')),
  currency TEXT NOT NULL CHECK (currency = 'USD'),
  cap_micro_usd INTEGER NOT NULL CHECK (cap_micro_usd >= 0),
  command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  bootstrap_manifest_digest TEXT REFERENCES bootstrap_manifests(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  CHECK (
    (account_scope = 'project' AND project_id IS NOT NULL
      AND command_authorization_digest IS NOT NULL
      AND bootstrap_manifest_digest IS NULL)
    OR (account_scope = 'portfolio' AND project_id IS NULL
      AND command_authorization_digest IS NULL
      AND bootstrap_manifest_digest IS NOT NULL)
  )
) STRICT;

CREATE TABLE project_admission_permits (
  digest TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  source_project_state TEXT NOT NULL CHECK (source_project_state IN ('queued','parked')),
  source_project_revision INTEGER NOT NULL CHECK (source_project_revision >= 0),
  slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  prior_generation INTEGER NOT NULL CHECK (prior_generation >= 0),
  new_generation INTEGER NOT NULL CHECK (new_generation >= 1),
  prior_owner_fence INTEGER NOT NULL CHECK (prior_owner_fence >= 0),
  new_owner_fence INTEGER NOT NULL CHECK (new_owner_fence >= 1),
  planned_run_id TEXT NOT NULL UNIQUE,
  planned_predecessor_run_id TEXT REFERENCES runs(id),
  planned_runtime_intent_id TEXT NOT NULL UNIQUE,
  planned_charge_subject_id TEXT NOT NULL UNIQUE,
  planned_resource_reservation_id TEXT NOT NULL UNIQUE,
  budget_account_id TEXT NOT NULL REFERENCES budget_accounts(id),
  root_request_digest TEXT NOT NULL,
  queue_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  admission_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  resume_command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (new_generation = prior_generation + 1),
  CHECK (new_owner_fence = prior_owner_fence + 1),
  CHECK (expires_at_ms > issued_at_ms),
  CHECK ((source_project_state = 'queued' AND resume_command_authorization_digest IS NULL)
      OR (source_project_state = 'parked' AND resume_command_authorization_digest IS NOT NULL)),
  CHECK ((source_project_state = 'queued' AND planned_predecessor_run_id IS NULL)
      OR (source_project_state = 'parked' AND planned_predecessor_run_id IS NOT NULL)),
  UNIQUE (digest, project_id, source_project_revision)
) STRICT;

CREATE TABLE project_admission_commits (
  digest TEXT PRIMARY KEY,
  admission_permit_digest TEXT NOT NULL UNIQUE REFERENCES project_admission_permits(digest),
  project_id TEXT NOT NULL REFERENCES projects(id),
  slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  owner_fence INTEGER NOT NULL CHECK (owner_fence >= 1),
  run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),
  runtime_intent_id TEXT NOT NULL UNIQUE REFERENCES runtime_intents(id),
  charge_subject_id TEXT NOT NULL UNIQUE REFERENCES charge_subjects(id),
  resource_reservation_id TEXT NOT NULL UNIQUE REFERENCES resource_reservations(id),
  budget_account_id TEXT NOT NULL REFERENCES budget_accounts(id),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  committed_at_ms INTEGER NOT NULL,
  UNIQUE (project_id, project_slot_generation)
) STRICT;

CREATE TABLE project_transition_authorizations (
  digest TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  from_state TEXT NOT NULL,
  to_state TEXT NOT NULL,
  from_revision INTEGER NOT NULL CHECK (from_revision >= 0),
  to_revision INTEGER NOT NULL CHECK (to_revision >= 1),
  authority_kind TEXT NOT NULL CHECK (authority_kind IN ('command','controller')),
  reason_code TEXT NOT NULL,
  command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  evidence_manifest_digest TEXT REFERENCES artifact_manifests(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (to_revision = from_revision + 1),
  CHECK (expires_at_ms > issued_at_ms),
  CHECK ((authority_kind = 'command' AND command_authorization_digest IS NOT NULL)
      OR (authority_kind = 'controller' AND command_authorization_digest IS NULL
        AND evidence_manifest_digest IS NOT NULL))
) STRICT;

CREATE TABLE run_transition_authorizations (
  digest TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES runs(id),
  project_id TEXT NOT NULL REFERENCES projects(id),
  from_state TEXT NOT NULL,
  to_state TEXT NOT NULL,
  from_revision INTEGER NOT NULL CHECK (from_revision >= 0),
  to_revision INTEGER NOT NULL CHECK (to_revision >= 1),
  authority_kind TEXT NOT NULL CHECK (authority_kind IN ('command','controller')),
  reason_code TEXT NOT NULL,
  command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  evidence_manifest_digest TEXT REFERENCES artifact_manifests(digest),
  benchmark_campaign_invalidation_id TEXT
    REFERENCES benchmark_campaign_invalidations(id),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (to_revision = from_revision + 1),
  CHECK (expires_at_ms > issued_at_ms),
  CHECK ((authority_kind = 'command' AND command_authorization_digest IS NOT NULL
        AND evidence_manifest_digest IS NULL
        AND benchmark_campaign_invalidation_id IS NULL)
      OR (authority_kind = 'controller' AND command_authorization_digest IS NULL
        AND evidence_manifest_digest IS NOT NULL)),
  CHECK ((reason_code = 'benchmark_campaign_invalidated')
      = (benchmark_campaign_invalidation_id IS NOT NULL))
) STRICT;

CREATE TABLE ingress_cursors (
  source TEXT NOT NULL,
  partition_key TEXT NOT NULL,
  last_committed_sequence INTEGER NOT NULL CHECK (last_committed_sequence >= 0),
  revision INTEGER NOT NULL CHECK (revision >= 0),
  updated_at_ms INTEGER NOT NULL,
  PRIMARY KEY (source, partition_key)
) STRICT;

CREATE TABLE work_packets (
  digest TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  lineage_digest TEXT NOT NULL,
  input_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  output_schema_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  pricing_catalog_digest TEXT NOT NULL REFERENCES pricing_catalogs(digest),
  max_input_tokens INTEGER NOT NULL,
  max_output_tokens INTEGER NOT NULL,
  max_cache_read_tokens INTEGER NOT NULL,
  max_cache_write_tokens INTEGER NOT NULL,
  max_tool_calls INTEGER NOT NULL,
  max_wall_time_ms INTEGER NOT NULL,
  required_reservation_micro_usd INTEGER NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (attempt_id, digest)
) STRICT;

CREATE TABLE outbox (
  id TEXT PRIMARY KEY,
  topic TEXT NOT NULL CHECK (topic = 'dispatch'),
  aggregate_type TEXT NOT NULL CHECK (aggregate_type = 'attempt'),
  aggregate_id TEXT NOT NULL,
  attempt_id TEXT NOT NULL REFERENCES attempts(id),
  destination_executor_id TEXT NOT NULL REFERENCES executors(id),
  idempotency_key TEXT NOT NULL UNIQUE,
  work_packet_digest TEXT REFERENCES work_packets(digest),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  payload_digest TEXT NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('pending','claimed','sent','acked','unknown','dead','cancelled')
  ),
  claim_token TEXT,
  claim_until_ms INTEGER,
  send_attempts INTEGER NOT NULL DEFAULT 0 CHECK (send_attempts >= 0),
  next_attempt_at_ms INTEGER NOT NULL,
  created_at_ms INTEGER NOT NULL,
  sent_at_ms INTEGER,
  acked_at_ms INTEGER,
  FOREIGN KEY (attempt_id, work_packet_digest)
    REFERENCES work_packets(attempt_id, digest),
  CHECK (aggregate_id = attempt_id)
) STRICT;

CREATE UNIQUE INDEX one_dispatch_message_per_attempt
ON outbox(attempt_id) WHERE topic = 'dispatch';

CREATE TABLE dispatch_bundle_commits (
  digest TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  work_packet_digest TEXT NOT NULL UNIQUE REFERENCES work_packets(digest),
  outbox_id TEXT NOT NULL UNIQUE REFERENCES outbox(id),
  lease_id TEXT NOT NULL UNIQUE REFERENCES leases(id),
  budget_reservation_id TEXT NOT NULL UNIQUE REFERENCES budget_reservations(id),
  process_resource_reservation_id TEXT UNIQUE REFERENCES resource_reservations(id),
  active_call_resource_reservation_id TEXT UNIQUE REFERENCES resource_reservations(id),
  fairness_dispatch_permit_digest TEXT NOT NULL UNIQUE REFERENCES fairness_dispatch_permits(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  committed_at_ms INTEGER NOT NULL,
  UNIQUE (node_version_id, attempt_id)
) STRICT;

CREATE TABLE dispatch_receipts (
  dispatch_key TEXT PRIMARY KEY REFERENCES attempts(dispatch_key),
  attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  payload_digest TEXT NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('received','launch_claimed','launched','completed','unknown')
  ),
  launch_claim_token TEXT,
  launch_claim_until_ms INTEGER,
  model_call_id TEXT UNIQUE,
  process_identity TEXT,
  received_at_ms INTEGER NOT NULL,
  launched_at_ms INTEGER,
  completed_at_ms INTEGER,
  FOREIGN KEY (attempt_id, dispatch_key)
    REFERENCES attempts(id, dispatch_key),
  FOREIGN KEY (attempt_id, executor_id)
    REFERENCES attempts(id, executor_id)
) STRICT;

CREATE TABLE runtime_sessions (
  id TEXT PRIMARY KEY,
  runtime_intent_id TEXT UNIQUE REFERENCES runtime_intents(id),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  executor_slot_id TEXT NOT NULL,
  session_scope TEXT NOT NULL CHECK (
    session_scope IN ('portfolio','project_generation','attempt')
  ),
  project_id TEXT REFERENCES projects(id),
  project_slot_no INTEGER REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER CHECK (project_slot_generation >= 1),
  worker_instance_id TEXT NOT NULL,
  process_identity TEXT NOT NULL UNIQUE,
  provider_session_id TEXT NOT NULL UNIQUE,
  runtime TEXT NOT NULL,
  runtime_version TEXT NOT NULL,
  actual_model TEXT NOT NULL,
  actual_model_family TEXT NOT NULL,
  actual_profile TEXT NOT NULL,
  fresh_context INTEGER NOT NULL CHECK (fresh_context IN (0,1)),
  private_home_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  sandbox_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  handshake_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('starting','running','terminating','terminated','unknown')
  ),
  started_at_ms INTEGER NOT NULL,
  terminated_at_ms INTEGER,
  termination_reason TEXT,
  FOREIGN KEY (executor_slot_id, executor_id)
    REFERENCES executor_slots(id, executor_id),
  CHECK (
    (session_scope = 'portfolio'
      AND runtime_intent_id IS NOT NULL
      AND project_id IS NULL
      AND project_slot_no IS NULL
      AND project_slot_generation IS NULL)
    OR (session_scope IN ('project_generation','attempt')
      AND project_id IS NOT NULL
      AND project_slot_no IS NOT NULL
      AND project_slot_generation IS NOT NULL)
  ),
  CHECK (
    (session_scope IN ('portfolio','project_generation') AND runtime_intent_id IS NOT NULL)
    OR (session_scope = 'attempt' AND runtime_intent_id IS NULL)
  )
) STRICT;

CREATE TABLE plan_author_attestations (
  digest TEXT PRIMARY KEY,
  plan_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),
  planner_runtime_session_id TEXT NOT NULL REFERENCES runtime_sessions(id),
  planner_runtime_intent_id TEXT NOT NULL REFERENCES runtime_intents(id),
  planner_attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  final_usage_event_id TEXT NOT NULL UNIQUE REFERENCES usage_events(id),
  planner_executor_id TEXT NOT NULL REFERENCES executors(id),
  project_slot_no INTEGER NOT NULL REFERENCES project_slots(slot_no),
  project_slot_generation INTEGER NOT NULL CHECK (project_slot_generation >= 1),
  executor_slot_fence INTEGER NOT NULL CHECK (executor_slot_fence >= 1),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE attempt_session_bindings (
  attempt_id TEXT PRIMARY KEY REFERENCES attempts(id),
  runtime_session_id TEXT NOT NULL REFERENCES runtime_sessions(id),
  bound_at_ms INTEGER NOT NULL,
  unbound_at_ms INTEGER,
  UNIQUE (attempt_id, runtime_session_id)
) STRICT;

CREATE UNIQUE INDEX one_live_attempt_per_runtime_session
ON attempt_session_bindings(runtime_session_id)
WHERE unbound_at_ms IS NULL;

CREATE TABLE inbound_submissions (
  id TEXT PRIMARY KEY,
  source TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 64),
  source_message_id TEXT NOT NULL CHECK (length(source_message_id) BETWEEN 1 AND 256),
  claimed_attempt_id TEXT,
  payload_digest TEXT NOT NULL,
  payload_size_bytes INTEGER NOT NULL CHECK (payload_size_bytes BETWEEN 0 AND 1099511627776),
  quarantine_ref TEXT NOT NULL UNIQUE CHECK (
    length(quarantine_ref) = 66
    AND substr(quarantine_ref, 1, 2) = 'q:'
    AND substr(quarantine_ref, 3) NOT GLOB '*[^0-9a-f]*'
  ),
  state TEXT NOT NULL CHECK (
    state IN ('received','parsed','promoted','rejected','quarantined')
  ),
  disposition_code TEXT,
  received_at_ms INTEGER NOT NULL,
  decided_at_ms INTEGER,
  CHECK (
    (state IN ('received','parsed') AND disposition_code IS NULL AND decided_at_ms IS NULL)
    OR (state IN ('promoted','rejected','quarantined')
      AND disposition_code IS NOT NULL AND decided_at_ms IS NOT NULL)
  ),
  UNIQUE (source, source_message_id)
) STRICT;

CREATE TABLE inbound_validation_attestations (
  digest TEXT PRIMARY KEY,
  inbound_submission_id TEXT NOT NULL UNIQUE REFERENCES inbound_submissions(id),
  payload_digest TEXT NOT NULL,
  payload_size_bytes INTEGER NOT NULL CHECK (payload_size_bytes BETWEEN 0 AND 1099511627776),
  validator_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  verdict TEXT NOT NULL CHECK (verdict IN ('pass','fail')),
  disposition_code TEXT,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  validated_at_ms INTEGER NOT NULL,
  CHECK ((verdict = 'pass' AND disposition_code IS NULL)
      OR (verdict = 'fail' AND disposition_code IS NOT NULL))
) STRICT;

CREATE TABLE result_envelopes (
  id TEXT PRIMARY KEY,
  inbound_submission_id TEXT NOT NULL UNIQUE REFERENCES inbound_submissions(id),
  source_result_id TEXT NOT NULL,
  attempt_id TEXT NOT NULL REFERENCES attempts(id),
  dispatch_key TEXT NOT NULL REFERENCES attempts(dispatch_key),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  worker_instance_id TEXT NOT NULL,
  fence INTEGER NOT NULL,
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  project_slot_generation INTEGER NOT NULL,
  input_manifest_digest TEXT NOT NULL,
  output_manifest_digest TEXT,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  payload_digest TEXT NOT NULL,
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  signed_at_ms INTEGER NOT NULL,
  state TEXT NOT NULL CHECK (
    state IN ('received','prevalidated','accepted','rejected','quarantined')
  ),
  disposition_code TEXT,
  received_at_ms INTEGER NOT NULL,
  decided_at_ms INTEGER,
  UNIQUE (executor_id, source_result_id)
) STRICT;

CREATE UNIQUE INDEX one_accepted_result_per_attempt
ON result_envelopes(attempt_id) WHERE state = 'accepted';

CREATE TABLE schema_validation_attestations (
  digest TEXT PRIMARY KEY,
  result_envelope_id TEXT NOT NULL UNIQUE REFERENCES result_envelopes(id),
  output_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  output_schema_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  validator_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  verdict TEXT NOT NULL CHECK (verdict IN ('pass','fail')),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE result_signature_validation_receipts (
  digest TEXT PRIMARY KEY,
  result_envelope_id TEXT NOT NULL UNIQUE REFERENCES result_envelopes(id),
  payload_digest TEXT NOT NULL,
  executor_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  validator_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  verdict TEXT NOT NULL CHECK (verdict IN ('pass','fail')),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE artifact_blobs (
  digest TEXT PRIMARY KEY,
  size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0),
  media_type TEXT NOT NULL,
  storage_ref TEXT NOT NULL UNIQUE,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE artifact_manifests (
  digest TEXT PRIMARY KEY,
  schema_version INTEGER NOT NULL CHECK (schema_version >= 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE sanitization_attestations (
  digest TEXT PRIMARY KEY,
  subject_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  rules_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  allowed_root TEXT NOT NULL,
  realpath_contained INTEGER NOT NULL CHECK (realpath_contained = 1),
  no_symlinks INTEGER NOT NULL CHECK (no_symlinks = 1),
  no_hardlinks INTEGER NOT NULL CHECK (no_hardlinks = 1),
  no_special_files INTEGER NOT NULL CHECK (no_special_files = 1),
  forbidden_path_bytes_absent INTEGER NOT NULL CHECK (forbidden_path_bytes_absent = 1),
  secret_scan_passed INTEGER NOT NULL CHECK (secret_scan_passed = 1),
  file_count INTEGER NOT NULL CHECK (file_count >= 0),
  total_bytes INTEGER NOT NULL CHECK (total_bytes >= 0),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (subject_manifest_digest, rules_digest)
) STRICT;

CREATE TABLE artifact_instances (
  id TEXT PRIMARY KEY,
  blob_digest TEXT NOT NULL REFERENCES artifact_blobs(digest),
  manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT REFERENCES runs(id),
  node_version_id TEXT REFERENCES node_versions(id),
  producer_attempt_id TEXT REFERENCES attempts(id),
  artifact_type TEXT NOT NULL CHECK (
    artifact_type IN ('planning_template','plan_bundle','node_input','node_output','evidence',
                      'runtime_handshake','private_home','sanitized_assets',
                      'provider_response','external_effect_payload',
                      'security_report','other')
  ),
  logical_name TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (producer_attempt_id, logical_name),
  UNIQUE (manifest_digest)
) STRICT;

CREATE TABLE artifact_inputs (
  artifact_instance_id TEXT NOT NULL REFERENCES artifact_instances(id),
  input_artifact_instance_id TEXT NOT NULL REFERENCES artifact_instances(id),
  relation TEXT NOT NULL CHECK (
    relation IN ('declared_dependency','task_seed','evidence','normalized_blind_summary')
  ),
  PRIMARY KEY (artifact_instance_id, input_artifact_instance_id, relation),
  CHECK (artifact_instance_id <> input_artifact_instance_id)
) STRICT;

CREATE TABLE artifact_instance_taints (
  id TEXT PRIMARY KEY,
  artifact_instance_id TEXT NOT NULL REFERENCES artifact_instances(id),
  blob_digest TEXT NOT NULL REFERENCES artifact_blobs(digest),
  preregistration_digest TEXT NOT NULL REFERENCES benchmark_preregistrations(digest),
  task_id TEXT NOT NULL,
  arm TEXT NOT NULL CHECK (arm IN ('A','B','C','D')),
  source_artifact_instance_id TEXT NOT NULL REFERENCES artifact_instances(id),
  source_input_artifact_instance_id TEXT REFERENCES artifact_instances(id),
  reason TEXT NOT NULL CHECK (
    reason IN ('benchmark_output','derived_from_benchmark','benchmark_evaluator_output')
  ),
  created_at_ms INTEGER NOT NULL,
  UNIQUE (artifact_instance_id, preregistration_digest, task_id, arm),
  FOREIGN KEY (preregistration_digest, task_id, arm)
    REFERENCES benchmark_arm_runs(preregistration_digest, task_id, arm)
) STRICT;

CREATE TABLE workspace_commit_taints (
  id TEXT PRIMARY KEY,
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  commit_id TEXT NOT NULL,
  preregistration_digest TEXT NOT NULL REFERENCES benchmark_preregistrations(digest),
  task_id TEXT NOT NULL,
  arm TEXT NOT NULL CHECK (arm IN ('A','B','C','D')),
  source_attempt_id TEXT NOT NULL REFERENCES attempts(id),
  source_kind TEXT NOT NULL CHECK (
    source_kind IN ('benchmark_workspace','artifact_instance')
  ),
  source_artifact_instance_id TEXT REFERENCES artifact_instances(id),
  source_blob_digest TEXT REFERENCES artifact_blobs(digest),
  created_at_ms INTEGER NOT NULL,
  UNIQUE (repository_id, commit_id, preregistration_digest, task_id, arm),
  FOREIGN KEY (preregistration_digest, task_id, arm)
    REFERENCES benchmark_arm_runs(preregistration_digest, task_id, arm),
  CHECK (
    (source_kind = 'benchmark_workspace'
      AND source_artifact_instance_id IS NULL AND source_blob_digest IS NULL)
    OR (source_kind = 'artifact_instance'
      AND source_artifact_instance_id IS NOT NULL AND source_blob_digest IS NOT NULL)
  )
) STRICT;

CREATE TABLE repository_taint_state (
  repository_id TEXT PRIMARY KEY REFERENCES repositories(id),
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  updated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE commit_lineage_attestations (
  digest TEXT PRIMARY KEY,
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  candidate_commit TEXT NOT NULL,
  reachable_commit_set_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  repository_taint_revision INTEGER NOT NULL CHECK (repository_taint_revision >= 0),
  verifier_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  verdict TEXT NOT NULL CHECK (verdict = 'clean'),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (repository_id, candidate_commit, repository_taint_revision)
) STRICT;

CREATE TABLE run_completion_seals (
  digest TEXT PRIMARY KEY,
  run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),
  final_node_version_id TEXT NOT NULL UNIQUE REFERENCES node_versions(id),
  final_artifact_instance_id TEXT NOT NULL UNIQUE REFERENCES artifact_instances(id),
  final_usage_event_id TEXT NOT NULL UNIQUE REFERENCES usage_events(id),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE attestations (
  id TEXT PRIMARY KEY,
  subject_digest TEXT NOT NULL,
  subject_kind TEXT NOT NULL CHECK (
    subject_kind IN ('attempt','artifact','commit','gate_bundle')
  ),
  subject_id TEXT NOT NULL,
  producer_attempt_id TEXT REFERENCES attempts(id),
  producer_executor_id TEXT REFERENCES executors(id),
  producer_model_family TEXT,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  attestation_type TEXT NOT NULL CHECK (
    attestation_type IN ('review','verification','security','risk_acceptance','test')
  ),
  candidate_commit TEXT,
  reviewer_attempt_id TEXT REFERENCES attempts(id),
  reviewer_executor_id TEXT REFERENCES executors(id),
  reviewer_model_family TEXT,
  reviewer_principal_id TEXT NOT NULL REFERENCES principals(id),
  auth_command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  independence_policy TEXT NOT NULL CHECK (
    independence_policy IN ('human','different_attempt',
                            'different_executor','different_model_family')
  ),
  verdict TEXT NOT NULL CHECK (
    verdict IN ('pass','fail','accept','reject','risk_accepted')
  ),
  rubric_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (subject_digest, attestation_type, reviewer_principal_id, rubric_policy_digest)
) STRICT;

CREATE TABLE attestation_subjects (
  attestation_id TEXT NOT NULL REFERENCES attestations(id),
  subject_kind TEXT NOT NULL CHECK (
    subject_kind IN ('attempt','artifact','commit','gate_bundle')
  ),
  subject_id TEXT NOT NULL,
  producer_attempt_id TEXT REFERENCES attempts(id),
  producer_executor_id TEXT REFERENCES executors(id),
  producer_model_family TEXT,
  PRIMARY KEY (attestation_id, subject_kind, subject_id),
  UNIQUE (attestation_id)
) STRICT;

CREATE TABLE gate_bundles (
  digest TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  target_ref TEXT NOT NULL,
  target_fence INTEGER NOT NULL CHECK (target_fence >= 1),
  target_head_observation_id TEXT NOT NULL REFERENCES target_head_observations(id),
  base_commit TEXT NOT NULL,
  candidate_commit TEXT NOT NULL,
  merge_request_id TEXT NOT NULL REFERENCES merge_requests(id),
  primary_producer_attempt_id TEXT NOT NULL REFERENCES attempts(id),
  verification_attestation_id TEXT NOT NULL REFERENCES attestations(id),
  security_attestation_id TEXT NOT NULL REFERENCES attestations(id),
  final_review_attestation_id TEXT NOT NULL REFERENCES attestations(id),
  risk_acceptance_attestation_id TEXT REFERENCES attestations(id),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (merge_request_id, target_fence, target_head_observation_id, policy_digest)
) STRICT;

CREATE TABLE gate_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  gate_bundle_digest TEXT NOT NULL REFERENCES gate_bundles(digest),
  reason TEXT NOT NULL,
  invalidated_by_principal_id TEXT NOT NULL REFERENCES principals(id),
  invalidated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE approval_requests (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  gate_bundle_digest TEXT NOT NULL REFERENCES gate_bundles(digest),
  requested_action TEXT NOT NULL,
  required_role TEXT NOT NULL CHECK (
    required_role IN ('owner','operator','approver','risk_acceptor')
  ),
  payload_digest TEXT NOT NULL,
  requester_principal_id TEXT NOT NULL REFERENCES principals(id),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  requested_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE approval_decisions (
  request_id TEXT PRIMARY KEY REFERENCES approval_requests(id),
  principal_id TEXT NOT NULL REFERENCES principals(id),
  decision TEXT NOT NULL CHECK (decision IN ('approve','reject')),
  decision_digest TEXT NOT NULL UNIQUE,
  auth_command_authorization_digest TEXT NOT NULL UNIQUE REFERENCES command_authorizations(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  decided_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE approval_invalidations (
  id TEXT PRIMARY KEY,
  authorization_id TEXT NOT NULL UNIQUE REFERENCES authority_change_authorizations(id),
  request_id TEXT NOT NULL REFERENCES approval_requests(id),
  reason TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE human_requests (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT REFERENCES runs(id),
  request_type TEXT NOT NULL CHECK (
    request_type IN ('information','decision','credential','physical_action')
  ),
  required_role TEXT NOT NULL CHECK (
    required_role IN ('owner','operator','reviewer','approver','risk_acceptor')
  ),
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  payload_digest TEXT NOT NULL,
  sanitization_attestation_digest TEXT NOT NULL UNIQUE
    REFERENCES content_sanitization_attestations(digest),
  requester_attempt_id TEXT REFERENCES attempts(id),
  requester_runtime_session_id TEXT REFERENCES runtime_sessions(id),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('open','answered','cancelled','expired')),
  created_at_ms INTEGER NOT NULL,
  due_at_ms INTEGER,
  answered_at_ms INTEGER,
  CHECK ((requester_attempt_id IS NULL) <> (requester_runtime_session_id IS NULL))
) STRICT;

CREATE TABLE credential_references (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  request_id TEXT NOT NULL UNIQUE REFERENCES human_requests(id),
  vault_provider TEXT NOT NULL CHECK (length(vault_provider) BETWEEN 1 AND 64),
  vault_object_ref TEXT NOT NULL UNIQUE CHECK (
    length(vault_object_ref) BETWEEN 16 AND 256
    AND vault_object_ref NOT GLOB '*[^A-Za-z0-9._:-]*'
  ),
  purpose TEXT NOT NULL CHECK (length(purpose) BETWEEN 1 AND 128),
  state TEXT NOT NULL CHECK (state = 'active'),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  revoked_at_ms INTEGER,
  CHECK (expires_at_ms > created_at_ms),
  CHECK (revoked_at_ms IS NULL)
) STRICT;

CREATE TABLE human_responses (
  request_id TEXT PRIMARY KEY REFERENCES human_requests(id),
  principal_id TEXT NOT NULL REFERENCES principals(id),
  response_json TEXT NOT NULL CHECK (json_valid(response_json)),
  response_digest TEXT NOT NULL,
  credential_reference_id TEXT UNIQUE REFERENCES credential_references(id),
  sanitization_attestation_digest TEXT NOT NULL UNIQUE
    REFERENCES content_sanitization_attestations(digest),
  auth_command_authorization_digest TEXT NOT NULL UNIQUE REFERENCES command_authorizations(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE content_sanitization_attestations (
  digest TEXT PRIMARY KEY,
  content_kind TEXT NOT NULL CHECK (content_kind IN ('human_request','human_response')),
  subject_id TEXT NOT NULL,
  payload_digest TEXT NOT NULL,
  sanitizer_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  verdict TEXT NOT NULL CHECK (verdict = 'pass'),
  secret_material_detected INTEGER NOT NULL CHECK (secret_material_detected = 0),
  duplicate_keys_rejected INTEGER NOT NULL CHECK (duplicate_keys_rejected = 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (content_kind, subject_id)
) STRICT;

CREATE TABLE repositories (
  id TEXT PRIMARY KEY,
  canonical_path TEXT NOT NULL UNIQUE,
  remote_url TEXT,
  registration_command_authorization_digest TEXT NOT NULL UNIQUE
    REFERENCES command_authorizations(digest),
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE project_repositories (
  project_id TEXT NOT NULL REFERENCES projects(id),
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  access_mode TEXT NOT NULL CHECK (access_mode IN ('read','build','integrate')),
  attach_command_authorization_digest TEXT NOT NULL UNIQUE
    REFERENCES command_authorizations(digest),
  attached_at_ms INTEGER NOT NULL,
  PRIMARY KEY (project_id, repository_id)
) STRICT;

CREATE TABLE integration_targets (
  id TEXT PRIMARY KEY,
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  target_ref TEXT NOT NULL,
  registration_command_authorization_digest TEXT NOT NULL UNIQUE
    REFERENCES command_authorizations(digest),
  fence_counter INTEGER NOT NULL DEFAULT 0 CHECK (fence_counter >= 0),
  state TEXT NOT NULL CHECK (
    state IN ('available','leased','integrating','quarantined')
  ),
  created_at_ms INTEGER NOT NULL,
  UNIQUE (repository_id, target_ref)
) STRICT;

CREATE TABLE target_head_observations (
  id TEXT PRIMARY KEY,
  integration_target_id TEXT NOT NULL REFERENCES integration_targets(id),
  provider TEXT NOT NULL,
  target_fence INTEGER NOT NULL CHECK (target_fence >= 1),
  target_ref TEXT NOT NULL,
  observed_commit TEXT NOT NULL,
  provider_etag TEXT,
  request_digest TEXT NOT NULL,
  response_digest TEXT NOT NULL,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL,
  UNIQUE (integration_target_id, target_fence, observed_commit, observed_at_ms)
) STRICT;

CREATE UNIQUE INDEX one_target_head_observation_per_instant
ON target_head_observations(integration_target_id, target_fence, observed_at_ms);

CREATE TABLE workspaces (
  id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  executor_slot_id TEXT NOT NULL REFERENCES executor_slots(id),
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  isolation_mode TEXT NOT NULL CHECK (
    isolation_mode IN ('full_clone','isolated_git_dir')
  ),
  workspace_path TEXT NOT NULL UNIQUE,
  git_dir_path TEXT NOT NULL UNIQUE,
  base_commit TEXT NOT NULL,
  output_commit TEXT,
  state TEXT NOT NULL CHECK (
    state IN ('provisioning','ready','dirty','sealed','removed','quarantined')
  ),
  created_at_ms INTEGER NOT NULL,
  removed_at_ms INTEGER
  ,CHECK (state <> 'provisioning' OR output_commit IS NULL)
) STRICT;

CREATE TABLE merge_requests (
  id TEXT PRIMARY KEY,
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  integration_target_id TEXT NOT NULL REFERENCES integration_targets(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  candidate_commit TEXT NOT NULL,
  base_commit TEXT NOT NULL,
  merge_subject_digest TEXT NOT NULL UNIQUE,
  provider TEXT NOT NULL,
  provider_idempotency_key TEXT NOT NULL UNIQUE,
  request_digest TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  target_fence INTEGER,
  state TEXT NOT NULL CHECK (
    state IN ('queued','leased','integrating','succeeded',
              'failed','unknown','cancelled')
  ),
  claim_token TEXT,
  claim_until_ms INTEGER,
  claim_leader_term INTEGER REFERENCES leader_terms(term),
  merged_commit TEXT,
  terminal_provider_observation_id TEXT REFERENCES provider_operation_observations(id),
  terminal_head_observation_id TEXT REFERENCES target_head_observations(id),
  created_at_ms INTEGER NOT NULL,
  finished_at_ms INTEGER
) STRICT;

CREATE UNIQUE INDEX one_live_merge_per_target
ON merge_requests(integration_target_id)
WHERE state IN ('leased','integrating','unknown');

CREATE TABLE external_effects (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  effect_type TEXT NOT NULL CHECK (
    effect_type IN ('dry_run','test_pr','test_deploy','production_pr',
                    'deploy','publish','release','client_deliverable')
  ),
  provider TEXT NOT NULL,
  remote_object_type TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  remote_idempotency_key TEXT NOT NULL,
  remote_object_id TEXT,
  gate_bundle_digest TEXT NOT NULL REFERENCES gate_bundles(digest),
  approval_request_id TEXT REFERENCES approval_requests(id),
  payload_artifact_instance_id TEXT NOT NULL UNIQUE REFERENCES artifact_instances(id),
  payload_digest TEXT NOT NULL,
  effect_subject_digest TEXT NOT NULL UNIQUE,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  claim_token TEXT,
  claim_until_ms INTEGER,
  claim_leader_term INTEGER REFERENCES leader_terms(term),
  execution_started_at_ms INTEGER,
  execution_head_observation_id TEXT REFERENCES target_head_observations(id),
  terminal_provider_observation_id TEXT REFERENCES provider_operation_observations(id),
  manual_reconcile_command_authorization_digest TEXT UNIQUE REFERENCES command_authorizations(digest),
  state TEXT NOT NULL CHECK (
    state IN ('prepared','executing','succeeded','failed',
              'unknown','manual_reconcile','cancelled')
  ),
  created_at_ms INTEGER NOT NULL,
  finished_at_ms INTEGER,
  UNIQUE (provider, remote_idempotency_key)
) STRICT;

CREATE UNIQUE INDEX unique_known_remote_object
ON external_effects(provider, remote_object_type, remote_object_id)
WHERE remote_object_id IS NOT NULL;

CREATE TABLE external_effect_attempts (
  id TEXT PRIMARY KEY,
  external_effect_id TEXT NOT NULL REFERENCES external_effects(id),
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  request_digest TEXT NOT NULL,
  egress_permit_id TEXT NOT NULL UNIQUE REFERENCES egress_permits(id),
  response_digest TEXT,
  provider_observation_id TEXT REFERENCES provider_operation_observations(id),
  state TEXT NOT NULL CHECK (
    state IN ('started','succeeded','failed','unknown')
  ),
  started_at_ms INTEGER NOT NULL,
  finished_at_ms INTEGER,
  error_code TEXT,
  UNIQUE (external_effect_id, attempt_no)
) STRICT;

CREATE UNIQUE INDEX one_live_attempt_per_external_effect
ON external_effect_attempts(external_effect_id)
WHERE state IN ('started','unknown');

CREATE TABLE merge_attempts (
  id TEXT PRIMARY KEY,
  merge_request_id TEXT NOT NULL REFERENCES merge_requests(id),
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  request_digest TEXT NOT NULL,
  egress_permit_id TEXT NOT NULL UNIQUE REFERENCES egress_permits(id),
  response_digest TEXT,
  provider_observation_id TEXT REFERENCES provider_operation_observations(id),
  state TEXT NOT NULL CHECK (state IN ('started','succeeded','failed','unknown')),
  started_at_ms INTEGER NOT NULL,
  finished_at_ms INTEGER,
  error_code TEXT,
  UNIQUE (merge_request_id, attempt_no)
) STRICT;

CREATE UNIQUE INDEX one_live_attempt_per_merge_request
ON merge_attempts(merge_request_id)
WHERE state IN ('started','unknown');

CREATE TABLE release_authority_snapshots (
  digest TEXT PRIMARY KEY,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('merge_request','external_effect')),
  subject_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  subject_digest TEXT NOT NULL,
  provider TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  provider_idempotency_key TEXT NOT NULL,
  target_fence INTEGER NOT NULL CHECK (target_fence >= 1),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  gate_bundle_digest TEXT REFERENCES gate_bundles(digest),
  policy_digest TEXT REFERENCES policies(digest),
  approval_request_id TEXT REFERENCES approval_requests(id),
  target_head_observation_id TEXT NOT NULL REFERENCES target_head_observations(id),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > created_at_ms),
  UNIQUE (subject_kind, subject_id, attempt_no, created_at_ms)
) STRICT;

CREATE TABLE egress_permits (
  id TEXT PRIMARY KEY,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('merge_request','external_effect')),
  subject_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  provider TEXT NOT NULL,
  subject_digest TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  provider_idempotency_key TEXT NOT NULL,
  target_fence INTEGER,
  authority_snapshot_digest TEXT NOT NULL REFERENCES release_authority_snapshots(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  state TEXT NOT NULL CHECK (state IN ('issued','consumed','revoked','expired')),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  consumed_at_ms INTEGER,
  CHECK (expires_at_ms > issued_at_ms),
  UNIQUE (subject_kind, subject_id, attempt_no, issued_at_ms),
  UNIQUE (provider, provider_idempotency_key, attempt_no, issued_at_ms)
) STRICT;

CREATE UNIQUE INDEX one_issued_egress_permit_per_subject
ON egress_permits(subject_kind, subject_id)
WHERE state = 'issued';

CREATE TABLE provider_health_observations (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL CHECK (provider IN ('anthropic','openai')),
  model_family TEXT NOT NULL,
  observed_state TEXT NOT NULL CHECK (
    observed_state IN ('healthy','degraded','outage','breaker_open')
  ),
  breaker_epoch INTEGER NOT NULL CHECK (breaker_epoch >= 0),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > observed_at_ms),
  UNIQUE (provider, model_family, breaker_epoch)
) STRICT;

CREATE TABLE provider_operation_observations (
  id TEXT PRIMARY KEY,
  subject_kind TEXT NOT NULL CHECK (
    subject_kind IN ('merge_request','merge_attempt','external_effect','external_effect_attempt')
  ),
  subject_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  provider_lookup_key TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  observed_state TEXT NOT NULL CHECK (
    observed_state IN ('pending','completed','failed','cancelled','absent','unreachable')
  ),
  remote_object_id TEXT,
  remote_commit TEXT,
  response_digest TEXT,
  target_fence INTEGER,
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL,
  UNIQUE (subject_kind, subject_id, observed_at_ms)
) STRICT;

CREATE TABLE provider_consistency_profiles (
  provider TEXT PRIMARY KEY,
  absence_mode TEXT NOT NULL CHECK (absence_mode IN ('strong','bounded_wait')),
  consistency_window_ms INTEGER NOT NULL CHECK (
    consistency_window_ms BETWEEN 0 AND 86400000
  ),
  lookup_key_is_idempotency_scope INTEGER NOT NULL CHECK (lookup_key_is_idempotency_scope = 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE fairness_policies (
  pool TEXT PRIMARY KEY CHECK (pool IN ('fable','codex','opus')),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  policy_digest TEXT NOT NULL REFERENCES policies(digest),
  quantum_units INTEGER NOT NULL CHECK (quantum_units > 0),
  max_deficit_units INTEGER NOT NULL CHECK (max_deficit_units > 0),
  aging_threshold_ms INTEGER NOT NULL CHECK (aging_threshold_ms > 0),
  max_wait_ms INTEGER NOT NULL CHECK (max_wait_ms >= aging_threshold_ms),
  updated_at_ms INTEGER NOT NULL,
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0)
) STRICT;

CREATE TABLE fairness_state (
  project_id TEXT NOT NULL REFERENCES projects(id),
  pool TEXT NOT NULL REFERENCES fairness_policies(pool),
  scheduler_epoch INTEGER NOT NULL DEFAULT 0 CHECK (scheduler_epoch >= 0),
  deficit_units INTEGER NOT NULL DEFAULT 0,
  waiting_since_ms INTEGER,
  last_dispatch_at_ms INTEGER,
  dispatch_count INTEGER NOT NULL DEFAULT 0 CHECK (dispatch_count >= 0),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
  PRIMARY KEY (project_id, pool)
) STRICT;

CREATE TABLE fairness_dispatch_permits (
  digest TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  node_version_id TEXT NOT NULL REFERENCES node_versions(id),
  executor_id TEXT NOT NULL REFERENCES executors(id),
  pool TEXT NOT NULL CHECK (pool IN ('fable','codex','opus')),
  fairness_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  expected_fairness_revision INTEGER NOT NULL CHECK (expected_fairness_revision >= 0),
  expected_scheduler_epoch INTEGER NOT NULL CHECK (expected_scheduler_epoch >= 0),
  estimated_cost_units INTEGER NOT NULL CHECK (estimated_cost_units > 0),
  winner_score_units INTEGER NOT NULL,
  candidate_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > issued_at_ms)
) STRICT;

CREATE TABLE events (
  event_seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  project_id TEXT REFERENCES projects(id),
  leader_term INTEGER REFERENCES leader_terms(term),
  actor_principal_id TEXT NOT NULL REFERENCES principals(id),
  command_id TEXT REFERENCES commands(id),
  correlation_id TEXT NOT NULL,
  causation_event_id TEXT REFERENCES events(id),
  entity_type TEXT NOT NULL CHECK (
    entity_type IN ('project','control_state','budget_account','node_version',
                    'executor_slot','host_capacity','fairness_state')
  ),
  entity_id TEXT NOT NULL,
  entity_revision INTEGER NOT NULL CHECK (entity_revision >= 0),
  event_type TEXT NOT NULL,
  payload_json TEXT NOT NULL CHECK (json_valid(payload_json)),
  payload_digest TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (entity_type, entity_id, entity_revision)
) STRICT;

-- Mutation capture begins with an in-memory SQLite Session changeset; complete
-- replay authority is the sanitized, signed projection_change_batches chain.
-- Raw Session changesets are never persisted or consumed by projectors.
CREATE TABLE projection_change_batches (
  batch_seq INTEGER PRIMARY KEY AUTOINCREMENT,
  digest TEXT NOT NULL UNIQUE,
  transaction_id TEXT NOT NULL UNIQUE,
  prior_batch_digest TEXT REFERENCES projection_change_batches(digest),
  projection_schema_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  transformer_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  table_set_digest TEXT NOT NULL,
  source_changeset_digest TEXT NOT NULL,
  projection_delta_digest TEXT NOT NULL,
  projection_delta_encoding TEXT NOT NULL
    CHECK (projection_delta_encoding = 'cortex-sanitized-delta-v1+zstd'),
  projection_delta_blob BLOB NOT NULL,
  compressed_size_bytes INTEGER NOT NULL CHECK (compressed_size_bytes BETWEEN 1 AND 16777216),
  uncompressed_size_bytes INTEGER NOT NULL CHECK (uncompressed_size_bytes BETWEEN 1 AND 67108864),
  source_row_change_count INTEGER NOT NULL CHECK (source_row_change_count BETWEEN 1 AND 100000),
  projection_record_count INTEGER NOT NULL CHECK (projection_record_count BETWEEN 1 AND 100000),
  project_id TEXT REFERENCES projects(id),
  scope_manifest_json TEXT NOT NULL CHECK (json_valid(scope_manifest_json)),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  actor_principal_id TEXT NOT NULL REFERENCES principals(id),
  command_id TEXT REFERENCES commands(id),
  correlation_id TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  CHECK (length(projection_delta_blob) = compressed_size_bytes)
) STRICT;

CREATE UNIQUE INDEX one_projection_batch_successor
ON projection_change_batches(prior_batch_digest)
WHERE prior_batch_digest IS NOT NULL;

CREATE TABLE benchmark_preregistrations (
  digest TEXT PRIMARY KEY,
  campaign_id TEXT NOT NULL UNIQUE,
  version INTEGER NOT NULL CHECK (version = 1),
  task_set_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  evaluation_rubric_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  randomization_commitment_digest TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_study_protocols (
  digest TEXT PRIMARY KEY,
  preregistration_digest TEXT NOT NULL UNIQUE REFERENCES benchmark_preregistrations(digest),
  study_phase TEXT NOT NULL CHECK (study_phase IN ('pilot','definitive')),
  required_task_count INTEGER NOT NULL CHECK (required_task_count >= 1),
  minimum_tasks_per_risk_stratum INTEGER NOT NULL CHECK (minimum_tasks_per_risk_stratum >= 1),
  power_analysis_manifest_digest TEXT REFERENCES artifact_manifests(digest),
  analysis_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  adoption_rule_policy_digest TEXT NOT NULL REFERENCES policies(digest),
  analysis_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  normalizer_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  leakage_scan_rules_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  adoption_eligible INTEGER NOT NULL CHECK (adoption_eligible IN (0,1)),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL,
  CHECK (
    (study_phase = 'pilot' AND required_task_count = 24
      AND minimum_tasks_per_risk_stratum = 8
      AND power_analysis_manifest_digest IS NULL AND adoption_eligible = 0)
    OR (study_phase = 'definitive' AND adoption_eligible = 1
      AND (required_task_count >= 60 OR power_analysis_manifest_digest IS NOT NULL))
  )
) STRICT;

CREATE TABLE benchmark_treatment_specs (
  preregistration_digest TEXT NOT NULL REFERENCES benchmark_preregistrations(digest),
  arm TEXT NOT NULL CHECK (arm IN ('A','B','C','D')),
  treatment_spec_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  planning_graph_digest TEXT NOT NULL,
  delivery_graph_digest TEXT NOT NULL,
  ordered_model_call_cells_digest TEXT NOT NULL,
  critique_mode TEXT NOT NULL CHECK (
    critique_mode IN ('none','single_blind_challenge','dialectical','independent_summary_control')
  ),
  critique_edge_count INTEGER NOT NULL CHECK (critique_edge_count >= 0),
  refutation_edge_count INTEGER NOT NULL CHECK (refutation_edge_count >= 0),
  normalized_summary_only INTEGER NOT NULL CHECK (normalized_summary_only IN (0,1)),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY (preregistration_digest, arm),
  CHECK (
    (arm = 'A' AND critique_mode = 'none' AND critique_edge_count = 0
      AND refutation_edge_count = 0 AND normalized_summary_only = 0)
    OR (arm = 'B' AND critique_mode = 'single_blind_challenge'
      AND critique_edge_count >= 1 AND refutation_edge_count >= 1
      AND normalized_summary_only = 0)
    OR (arm = 'C' AND critique_mode = 'dialectical'
      AND critique_edge_count >= 2 AND refutation_edge_count >= 1
      AND normalized_summary_only = 0)
    OR (arm = 'D' AND critique_mode = 'independent_summary_control'
      AND critique_edge_count = 0 AND refutation_edge_count = 0
      AND normalized_summary_only = 1)
  )
) STRICT;

CREATE TABLE benchmark_treatment_call_cells (
  id TEXT NOT NULL UNIQUE,
  preregistration_digest TEXT NOT NULL,
  arm TEXT NOT NULL CHECK (arm IN ('A','B','C','D')),
  cell_no INTEGER NOT NULL CHECK (cell_no >= 1),
  phase_no INTEGER NOT NULL CHECK (phase_no IN (1,2)),
  stage TEXT NOT NULL,
  required_pool TEXT NOT NULL CHECK (required_pool IN ('fable','codex','opus')),
  required_capability TEXT NOT NULL,
  expected_provider TEXT NOT NULL CHECK (expected_provider IN ('anthropic','openai')),
  runtime TEXT NOT NULL,
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  expected_model TEXT NOT NULL,
  expected_model_family TEXT NOT NULL,
  expected_profile TEXT NOT NULL,
  max_input_tokens INTEGER NOT NULL CHECK (max_input_tokens BETWEEN 1 AND 2000000),
  max_output_tokens INTEGER NOT NULL CHECK (max_output_tokens BETWEEN 1 AND 2000000),
  max_cache_read_tokens INTEGER NOT NULL CHECK (max_cache_read_tokens BETWEEN 0 AND 4000000),
  max_cache_write_tokens INTEGER NOT NULL CHECK (max_cache_write_tokens BETWEEN 0 AND 4000000),
  max_tool_calls INTEGER NOT NULL CHECK (max_tool_calls BETWEEN 0 AND 400),
  max_wall_time_ms INTEGER NOT NULL CHECK (max_wall_time_ms BETWEEN 1 AND 7200000),
  required_reservation_micro_usd INTEGER NOT NULL CHECK (required_reservation_micro_usd > 0),
  retry_policy TEXT NOT NULL CHECK (retry_policy = 'invalidate_campaign'),
  parity_cell_digest TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY (preregistration_digest, arm, cell_no),
  UNIQUE (preregistration_digest, arm, parity_cell_digest),
  FOREIGN KEY (preregistration_digest, arm)
    REFERENCES benchmark_treatment_specs(preregistration_digest, arm)
) STRICT;

CREATE TABLE benchmark_realized_call_cells (
  digest TEXT PRIMARY KEY,
  arm_execution_id TEXT NOT NULL REFERENCES benchmark_arm_runs(arm_execution_id),
  cell_no INTEGER NOT NULL CHECK (cell_no >= 1),
  treatment_cell_id TEXT NOT NULL REFERENCES benchmark_treatment_call_cells(id),
  attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),
  phase_no INTEGER NOT NULL CHECK (phase_no IN (1,2)),
  stage TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('anthropic','openai')),
  runtime TEXT NOT NULL,
  requested_model TEXT NOT NULL,
  requested_profile TEXT NOT NULL,
  model TEXT NOT NULL,
  model_family TEXT NOT NULL,
  profile TEXT NOT NULL,
  max_input_tokens INTEGER NOT NULL,
  max_output_tokens INTEGER NOT NULL,
  max_cache_read_tokens INTEGER NOT NULL,
  max_cache_write_tokens INTEGER NOT NULL,
  max_tool_calls INTEGER NOT NULL,
  max_wall_time_ms INTEGER NOT NULL,
  required_reservation_micro_usd INTEGER NOT NULL,
  parity_cell_digest TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  bound_at_ms INTEGER NOT NULL,
  UNIQUE (arm_execution_id, cell_no),
  UNIQUE (arm_execution_id, treatment_cell_id)
) STRICT;

CREATE TABLE benchmark_prompt_sources (
  digest TEXT PRIMARY KEY,
  manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  blob_digest TEXT NOT NULL REFERENCES artifact_blobs(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_inference_budgets (
  digest TEXT PRIMARY KEY,
  max_attempts INTEGER NOT NULL CHECK (max_attempts >= 1),
  max_provider_calls INTEGER NOT NULL CHECK (max_provider_calls >= 1),
  max_input_tokens INTEGER NOT NULL CHECK (max_input_tokens >= 1),
  max_output_tokens INTEGER NOT NULL CHECK (max_output_tokens >= 1),
  max_cache_read_tokens INTEGER NOT NULL CHECK (max_cache_read_tokens >= 0),
  max_cache_write_tokens INTEGER NOT NULL CHECK (max_cache_write_tokens >= 0),
  max_tool_calls INTEGER NOT NULL CHECK (max_tool_calls >= 0),
  max_wall_time_ms INTEGER NOT NULL CHECK (max_wall_time_ms >= 1),
  max_cost_micro_usd INTEGER NOT NULL CHECK (max_cost_micro_usd >= 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_arm_budget_breaches (
  arm_execution_id TEXT PRIMARY KEY REFERENCES benchmark_arm_runs(arm_execution_id),
  usage_event_id TEXT NOT NULL UNIQUE REFERENCES usage_events(id),
  provider_call_count INTEGER NOT NULL CHECK (provider_call_count >= 0),
  input_tokens INTEGER NOT NULL CHECK (input_tokens >= 0),
  output_tokens INTEGER NOT NULL CHECK (output_tokens >= 0),
  cache_read_tokens INTEGER NOT NULL CHECK (cache_read_tokens >= 0),
  cache_write_tokens INTEGER NOT NULL CHECK (cache_write_tokens >= 0),
  tool_calls INTEGER NOT NULL CHECK (tool_calls >= 0),
  wall_time_ms INTEGER NOT NULL CHECK (wall_time_ms >= 0),
  cost_micro_usd INTEGER NOT NULL CHECK (cost_micro_usd >= 0),
  breached_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_tasks (
  preregistration_digest TEXT NOT NULL REFERENCES benchmark_preregistrations(digest),
  task_id TEXT NOT NULL,
  project_id TEXT NOT NULL REFERENCES projects(id),
  base_commit TEXT NOT NULL,
  input_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  prompt_digest TEXT NOT NULL REFERENCES benchmark_prompt_sources(digest),
  risk_stratum TEXT NOT NULL CHECK (risk_stratum IN ('low','medium','high')),
  complexity_stratum TEXT NOT NULL CHECK (complexity_stratum IN ('low','medium','high')),
  toolchain_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  PRIMARY KEY (preregistration_digest, task_id)
) STRICT;

CREATE TABLE benchmark_task_sources (
  manifest_digest TEXT PRIMARY KEY REFERENCES artifact_manifests(digest),
  blob_digest TEXT NOT NULL REFERENCES artifact_blobs(digest),
  repository_id TEXT NOT NULL REFERENCES repositories(id),
  base_commit TEXT NOT NULL,
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_arm_runs (
  arm_execution_id TEXT PRIMARY KEY,
  preregistration_digest TEXT NOT NULL,
  task_id TEXT NOT NULL,
  arm TEXT NOT NULL CHECK (arm IN ('A','B','C','D')),
  project_id TEXT NOT NULL REFERENCES projects(id),
  isolation_namespace TEXT NOT NULL UNIQUE,
  base_commit TEXT NOT NULL,
  prompt_digest TEXT NOT NULL REFERENCES benchmark_prompt_sources(digest),
  toolchain_closure_digest TEXT NOT NULL REFERENCES configuration_artifacts(digest),
  inference_budget_digest TEXT NOT NULL REFERENCES benchmark_inference_budgets(digest),
  planning_template_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  treatment_spec_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  randomized_order INTEGER NOT NULL CHECK (randomized_order BETWEEN 1 AND 4),
  release_eligible INTEGER NOT NULL CHECK (release_eligible = 0),
  UNIQUE (preregistration_digest, task_id, arm),
  UNIQUE (preregistration_digest, task_id, randomized_order),
  UNIQUE (preregistration_digest, task_id, project_id),
  FOREIGN KEY (preregistration_digest, task_id)
    REFERENCES benchmark_tasks(preregistration_digest, task_id)
) STRICT;

CREATE TABLE benchmark_arm_run_members (
  arm_execution_id TEXT NOT NULL REFERENCES benchmark_arm_runs(arm_execution_id),
  run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),
  phase_no INTEGER NOT NULL CHECK (phase_no >= 1),
  run_kind TEXT NOT NULL CHECK (run_kind IN ('planning','delivery')),
  PRIMARY KEY (arm_execution_id, phase_no)
) STRICT;

CREATE TABLE benchmark_arm_start_permits (
  digest TEXT PRIMARY KEY,
  arm_execution_id TEXT NOT NULL REFERENCES benchmark_arm_runs(arm_execution_id),
  run_id TEXT NOT NULL REFERENCES runs(id),
  permit_no INTEGER NOT NULL CHECK (permit_no >= 1),
  randomized_order INTEGER NOT NULL CHECK (randomized_order BETWEEN 1 AND 4),
  provider_health_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  runtime_catalog_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  resource_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  fairness_snapshot_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  issued_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  CHECK (expires_at_ms > issued_at_ms),
  UNIQUE (arm_execution_id, permit_no),
  UNIQUE (run_id, permit_no)
) STRICT;

CREATE TABLE benchmark_treatment_execution_receipts (
  digest TEXT PRIMARY KEY,
  arm_execution_id TEXT NOT NULL UNIQUE REFERENCES benchmark_arm_runs(arm_execution_id),
  treatment_spec_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  planning_plan_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  delivery_plan_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  execution_input_manifest_digest TEXT NOT NULL UNIQUE REFERENCES artifact_manifests(digest),
  realized_planning_graph_digest TEXT NOT NULL,
  realized_delivery_graph_digest TEXT NOT NULL,
  realized_ordered_model_call_cells_digest TEXT NOT NULL,
  realized_call_cell_count INTEGER NOT NULL CHECK (realized_call_cell_count >= 1),
  realized_attempt_count INTEGER NOT NULL CHECK (realized_attempt_count >= 1),
  protocol_deviation_count INTEGER NOT NULL CHECK (protocol_deviation_count = 0),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_campaign_invalidations (
  id TEXT PRIMARY KEY,
  preregistration_digest TEXT NOT NULL UNIQUE REFERENCES benchmark_preregistrations(digest),
  task_id TEXT,
  arm TEXT CHECK (arm IS NULL OR arm IN ('A','B','C','D')),
  reason TEXT NOT NULL CHECK (
    reason IN ('provider_outage','breaker_open','capacity_intervention',
               'prohibited_failover','protocol_deviation','isolation_breach',
               'late_usage','post_reveal_mutation','manual_abort')
  ),
  provider_observation_id TEXT REFERENCES provider_health_observations(id),
  host_capacity_revision INTEGER CHECK (host_capacity_revision IS NULL OR host_capacity_revision >= 0),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  invalidated_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_campaign_invalidation_commits (
  digest TEXT PRIMARY KEY,
  transaction_id TEXT NOT NULL UNIQUE,
  invalidation_set_digest TEXT NOT NULL,
  invalidation_count INTEGER NOT NULL CHECK (invalidation_count >= 1),
  cancelled_outbox_count INTEGER NOT NULL CHECK (cancelled_outbox_count >= 0),
  revoked_lease_count INTEGER NOT NULL CHECK (revoked_lease_count >= 0),
  quarantined_attempt_count INTEGER NOT NULL CHECK (quarantined_attempt_count >= 0),
  cancelled_node_count INTEGER NOT NULL CHECK (cancelled_node_count >= 0),
  cancelled_run_count INTEGER NOT NULL CHECK (cancelled_run_count >= 0),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  committed_at_ms INTEGER NOT NULL,
  FOREIGN KEY (transaction_id)
    REFERENCES projection_change_batches(transaction_id)
    DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE benchmark_campaign_invalidation_commit_members (
  commit_digest TEXT NOT NULL,
  invalidation_id TEXT NOT NULL UNIQUE
    REFERENCES benchmark_campaign_invalidations(id),
  PRIMARY KEY (commit_digest, invalidation_id),
  FOREIGN KEY (commit_digest)
    REFERENCES benchmark_campaign_invalidation_commits(digest)
    DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE benchmark_campaign_completion_seals (
  digest TEXT PRIMARY KEY,
  preregistration_digest TEXT NOT NULL UNIQUE REFERENCES benchmark_preregistrations(digest),
  completed_task_count INTEGER NOT NULL CHECK (completed_task_count >= 1),
  completed_arm_count INTEGER NOT NULL CHECK (completed_arm_count >= 4),
  ordered_input_snapshot_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL,
  CHECK (completed_arm_count = completed_task_count * 4)
) STRICT;

CREATE TABLE benchmark_randomization_reveals (
  digest TEXT PRIMARY KEY,
  preregistration_digest TEXT NOT NULL UNIQUE REFERENCES benchmark_preregistrations(digest),
  completion_seal_digest TEXT NOT NULL UNIQUE REFERENCES benchmark_campaign_completion_seals(digest),
  reveal_nonce TEXT NOT NULL,
  algorithm TEXT NOT NULL CHECK (algorithm = 'hmac-sha256-fisher-yates-v1'),
  permutations_json TEXT NOT NULL CHECK (json_valid(permutations_json)),
  commitment_verified INTEGER NOT NULL CHECK (commitment_verified = 1),
  permutation_verified INTEGER NOT NULL CHECK (permutation_verified = 1),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  revealed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_arm_settlement_seals (
  digest TEXT PRIMARY KEY,
  arm_execution_id TEXT NOT NULL UNIQUE REFERENCES benchmark_arm_runs(arm_execution_id),
  reservation_snapshot_json TEXT NOT NULL CHECK (json_valid(reservation_snapshot_json)),
  reservation_count INTEGER NOT NULL CHECK (reservation_count >= 1),
  provider_call_count INTEGER NOT NULL CHECK (provider_call_count >= 0),
  input_tokens INTEGER NOT NULL CHECK (input_tokens >= 0),
  output_tokens INTEGER NOT NULL CHECK (output_tokens >= 0),
  cache_read_tokens INTEGER NOT NULL CHECK (cache_read_tokens >= 0),
  cache_write_tokens INTEGER NOT NULL CHECK (cache_write_tokens >= 0),
  tool_calls INTEGER NOT NULL CHECK (tool_calls >= 0),
  wall_time_ms INTEGER NOT NULL CHECK (wall_time_ms >= 0),
  cost_micro_usd INTEGER NOT NULL CHECK (cost_micro_usd >= 0),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  sealed_at_ms INTEGER NOT NULL
) STRICT;

CREATE TABLE benchmark_arm_settlement_invalidations (
  id TEXT PRIMARY KEY,
  settlement_digest TEXT NOT NULL REFERENCES benchmark_arm_settlement_seals(digest),
  usage_event_id TEXT NOT NULL UNIQUE REFERENCES usage_events(id),
  reason TEXT NOT NULL CHECK (reason = 'late_usage_after_settlement'),
  invalidated_at_ms INTEGER NOT NULL,
  UNIQUE (settlement_digest, usage_event_id)
) STRICT;

CREATE TABLE benchmark_arm_seed_bindings (
  digest TEXT PRIMARY KEY,
  arm_execution_id TEXT NOT NULL REFERENCES benchmark_arm_runs(arm_execution_id),
  node_version_id TEXT NOT NULL UNIQUE REFERENCES node_versions(id),
  input_artifact_instance_id TEXT NOT NULL UNIQUE REFERENCES artifact_instances(id),
  source_manifest_digest TEXT NOT NULL REFERENCES benchmark_task_sources(manifest_digest),
  source_blob_digest TEXT NOT NULL REFERENCES artifact_blobs(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  UNIQUE (arm_execution_id, node_version_id)
) STRICT;

CREATE VIEW benchmark_arm_measured_usage AS
SELECT arm.arm_execution_id,
       COUNT(DISTINCT usage.reservation_id) AS provider_call_count,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.input_tokens ELSE 0 END), 0) AS input_tokens,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.output_tokens ELSE 0 END), 0) AS output_tokens,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.cache_read_tokens ELSE 0 END), 0) AS cache_read_tokens,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.cache_write_tokens ELSE 0 END), 0) AS cache_write_tokens,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.tool_calls ELSE 0 END), 0) AS tool_calls,
       COALESCE(SUM(CASE WHEN usage.sequence_no = (
         SELECT MAX(latest.sequence_no) FROM usage_events latest
         WHERE latest.reservation_id = usage.reservation_id
       ) THEN usage.wall_time_ms ELSE 0 END), 0) AS wall_time_ms,
       COALESCE(SUM(usage.delta_micro_usd), 0) AS cost_micro_usd
FROM benchmark_arm_runs arm
LEFT JOIN benchmark_arm_run_members member ON member.arm_execution_id = arm.arm_execution_id
LEFT JOIN attempts attempt ON attempt.run_id = member.run_id
LEFT JOIN charge_subjects subject
  ON subject.attempt_id = attempt.id AND subject.scope_kind = 'attempt'
LEFT JOIN budget_reservations reservation ON reservation.charge_subject_id = subject.id
LEFT JOIN usage_events usage ON usage.reservation_id = reservation.id
GROUP BY arm.arm_execution_id;

