CREATE TABLE reconciliation_decisions (
  id TEXT PRIMARY KEY,
  subject_kind TEXT NOT NULL CHECK (
    subject_kind IN ('dispatch_receipt','runtime_intent','runtime_session',
                     'managed_intent','managed_session','runtime_call_lease',
                     'budget_reservation','attempt','merge_request',
                     'merge_attempt','external_effect','external_effect_attempt')
  ),
  subject_id TEXT NOT NULL,
  decision_no INTEGER NOT NULL CHECK (decision_no >= 1),
  subject_generation TEXT NOT NULL,
  resolved_state TEXT NOT NULL,
  process_identity TEXT,
  provider_lookup_key TEXT NOT NULL,
  observed_process_state TEXT NOT NULL CHECK (
    observed_process_state IN ('alive','dead','absent','not_applicable')
  ),
  observed_provider_state TEXT NOT NULL CHECK (
    observed_provider_state IN ('active','completed','failed','cancelled','absent','unreachable')
  ),
  provider_observation_id TEXT REFERENCES provider_operation_observations(id),
  subject_leader_term INTEGER NOT NULL,
  leader_term INTEGER NOT NULL REFERENCES leader_terms(term),
  evidence_manifest_digest TEXT NOT NULL REFERENCES artifact_manifests(digest),
  canonical_json TEXT NOT NULL CHECK (json_valid(canonical_json)),
  signer_principal_id TEXT NOT NULL REFERENCES principals(id),
  signer_key_id TEXT NOT NULL REFERENCES signing_keys(key_id),
  signature TEXT NOT NULL,
  observed_at_ms INTEGER NOT NULL,
  UNIQUE (subject_kind, subject_id, decision_no),
  UNIQUE (subject_kind, subject_id, subject_generation),
  CHECK (
    (subject_kind IN ('merge_request','merge_attempt','external_effect','external_effect_attempt'))
      = (provider_observation_id IS NOT NULL)
  )
) STRICT;

CREATE VIEW launch_ready_attempts AS
SELECT DISTINCT a.id AS attempt_id
FROM attempts a
JOIN node_versions nv ON nv.id = a.node_version_id
JOIN runs r ON r.id = a.run_id
JOIN projects p ON p.id = a.project_id
JOIN policies np ON np.digest = nv.policy_digest
JOIN signing_keys nsk ON nsk.key_id = np.signer_key_id
JOIN policies rpp ON rpp.digest = r.pipeline_policy_digest
JOIN signing_keys rpsk ON rpsk.key_id = rpp.signer_key_id
JOIN executors e ON e.id = a.executor_id
JOIN principals ep ON ep.id = e.principal_id
JOIN runtime_catalogs rc ON rc.digest = a.runtime_catalog_digest
JOIN signing_keys rcsk ON rcsk.key_id = rc.signer_key_id
JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
JOIN signing_keys rpask ON rpask.key_id = rpa.signer_key_id
JOIN pricing_catalogs pc ON pc.digest = a.pricing_catalog_digest
JOIN signing_keys pcsk ON pcsk.key_id = pc.signer_key_id
JOIN leases l ON l.attempt_id = a.id
JOIN executor_slots es ON es.id = a.executor_slot_id
JOIN project_slots ps ON ps.slot_no = a.project_slot_no
JOIN leader_terms lt ON lt.term = a.leader_term
JOIN control_state ctl ON ctl.singleton = 1
JOIN current_host_capacity current_hc ON current_hc.singleton = 1
JOIN charge_subjects cost_cs
  ON cost_cs.scope_kind = 'attempt' AND cost_cs.attempt_id = a.id
JOIN work_packets wp ON wp.attempt_id = a.id
JOIN budget_reservations br
  ON br.charge_subject_id = cost_cs.id
 AND br.pricing_catalog_digest = a.pricing_catalog_digest
 AND br.amount_micro_usd = a.required_reservation_micro_usd
JOIN budget_accounts ba ON ba.id = br.budget_account_id
WHERE a.state = 'dispatched'
  AND nv.state = 'dispatched'
  AND nv.current_attempt_id = a.id
  AND r.state = 'active'
  AND p.state IN ('admitted','active')
  AND nsk.state = 'active'
  AND (nsk.expires_at_ms IS NULL OR nsk.expires_at_ms >= (unixepoch('subsec') * 1000))
  AND rpsk.state = 'active'
  AND (rpsk.expires_at_ms IS NULL OR rpsk.expires_at_ms >= (unixepoch('subsec') * 1000))
  AND ep.state = 'active'
  AND EXISTS (
    SELECT 1 FROM executor_capabilities ec
    WHERE ec.executor_id = e.id
      AND ec.capability = nv.required_capability
      AND ec.scope IN ('global', a.project_id)
  )
  AND e.state IN ('healthy','degraded')
  AND e.breaker_state IN ('closed','half_open')
  AND rc.provider = pc.provider
  AND rc.resolved_model = pc.model
  AND rcsk.state = 'active'
  AND (rcsk.expires_at_ms IS NULL OR rcsk.expires_at_ms >= (unixepoch('subsec') * 1000))
  AND rpask.state = 'active'
  AND (rpask.expires_at_ms IS NULL OR rpask.expires_at_ms >= (unixepoch('subsec') * 1000))
  AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                           AND (unixepoch('subsec') * 1000) + 5000
  AND pcsk.state = 'active'
  AND (pcsk.expires_at_ms IS NULL OR pcsk.expires_at_ms >= (unixepoch('subsec') * 1000))
  AND pc.effective_at_ms <= (unixepoch('subsec') * 1000)
  AND NOT EXISTS (
    SELECT 1 FROM runtime_catalog_invalidations x
    WHERE x.runtime_catalog_digest = rc.digest
  )
  AND NOT EXISTS (
    SELECT 1 FROM configuration_artifact_invalidations x
    WHERE x.configuration_digest IN (
      nv.output_schema_digest, e.config_digest, rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
      rc.provider_proxy_profile_digest, rc.io_protocol_digest,
      rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
    )
  )
  AND NOT EXISTS (
    SELECT 1 FROM policy_invalidations x
    WHERE x.policy_digest IN (nv.policy_digest, r.pipeline_policy_digest, e.sandbox_policy_digest)
  )
  AND NOT EXISTS (
    SELECT 1 FROM pricing_catalog_invalidations x
    WHERE x.pricing_catalog_digest = pc.digest
  )
  AND NOT EXISTS (
    SELECT 1 FROM pricing_catalogs newer
    WHERE newer.provider = pc.provider
      AND newer.model = pc.model
      AND newer.effective_at_ms > pc.effective_at_ms
      AND newer.effective_at_ms <= (unixepoch('subsec') * 1000)
      AND NOT EXISTS (
        SELECT 1 FROM pricing_catalog_invalidations npi
        WHERE npi.pricing_catalog_digest = newer.digest
      )
  )
  AND l.state = 'active'
  AND l.fence = a.fence
  AND l.leader_term = a.leader_term
  AND l.expires_at_ms > (unixepoch('subsec') * 1000)
  AND es.state = 'leased'
  AND es.fence_counter = a.fence
  AND ps.project_id = a.project_id
  AND ps.generation = a.project_slot_generation
  AND lt.state = 'active'
  AND ctl.current_term = a.leader_term
  AND ctl.dispatch_enabled = 1
  AND ctl.admission_mode = 'open'
  AND ctl.kill_switch = 0
  AND ba.state = 'active'
  AND br.state = 'held'
  AND EXISTS (
    SELECT 1 FROM dispatch_bundle_commits bundle
    WHERE bundle.attempt_id = a.id
      AND bundle.node_version_id = nv.id
      AND bundle.work_packet_digest = wp.digest
      AND bundle.lease_id = l.id
      AND bundle.budget_reservation_id = br.id
      AND bundle.leader_term = a.leader_term
  )
  AND NOT EXISTS (
    SELECT 1
    FROM benchmark_arm_run_members benchmark_member
    JOIN benchmark_arm_budget_breaches breach
      ON breach.arm_execution_id = benchmark_member.arm_execution_id
    WHERE benchmark_member.run_id = r.id
  )
  AND (
    (e.fresh_session_required = 1 AND EXISTS (
      SELECT 1
      FROM resource_reservations rr
      JOIN resource_profiles prof ON prof.digest = rr.resource_profile_digest
      WHERE rr.charge_subject_id = cost_cs.id
        AND rr.reservation_kind = 'process'
        AND rr.state = 'held'
        AND prof.host_policy_digest = current_hc.resource_policy_digest
        AND NOT EXISTS (
          SELECT 1 FROM policy_invalidations pi
          WHERE pi.policy_digest IN (prof.digest, prof.host_policy_digest)
        )
    ))
    OR (e.fresh_session_required = 0 AND e.id <> 'rick'
      AND EXISTS (
        SELECT 1 FROM resource_reservations call_rr
        JOIN resource_profiles call_prof ON call_prof.digest = call_rr.resource_profile_digest
        WHERE call_rr.charge_subject_id = cost_cs.id
          AND call_rr.reservation_kind = 'active_call'
          AND call_rr.state = 'held'
          AND NOT EXISTS (
            SELECT 1 FROM policy_invalidations pi
            WHERE pi.policy_digest IN (call_prof.digest, call_prof.host_policy_digest)
          )
      )
      AND EXISTS (
        SELECT 1
        FROM runtime_sessions rs
        JOIN charge_subjects runtime_cs ON runtime_cs.runtime_intent_id = rs.runtime_intent_id
        JOIN resource_reservations process_rr ON process_rr.charge_subject_id = runtime_cs.id
        JOIN resource_profiles process_prof ON process_prof.digest = process_rr.resource_profile_digest
        WHERE rs.executor_id = a.executor_id
          AND rs.project_id = a.project_id
          AND rs.project_slot_generation = a.project_slot_generation
          AND rs.state = 'running'
          AND process_rr.reservation_kind = 'process'
          AND process_rr.state = 'held'
          AND NOT EXISTS (
            SELECT 1 FROM policy_invalidations pi
            WHERE pi.policy_digest IN (process_prof.digest, process_prof.host_policy_digest)
          )
      ))
  );

CREATE TRIGGER projects_enter_queued
BEFORE INSERT ON projects
BEGIN
  SELECT RAISE(ABORT, 'project creation requires exact authenticated project.submit authority')
  WHERE NEW.state <> 'queued'
     OR NEW.revision <> 0
     OR NEW.updated_at_ms <> NEW.created_at_ms
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR (SELECT COUNT(*)
         FROM fairness_policies fairness_policy
         JOIN policies signed_policy ON signed_policy.digest = fairness_policy.policy_digest
         JOIN current_valid_keys policy_key
           ON policy_key.key_id = signed_policy.signer_key_id
          AND policy_key.key_purpose = 'control_plane'
         WHERE NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = fairness_policy.policy_digest
         )) <> 3
     OR NOT EXISTS (
       SELECT 1
       FROM command_authorizations authorization
       JOIN commands command ON command.id = authorization.command_id
       JOIN principals owner ON owner.id = NEW.owner_principal_id
       WHERE authorization.digest = NEW.submit_command_authorization_digest
         AND authorization.actor_principal_id = NEW.owner_principal_id
         AND authorization.project_id IS NULL
         AND authorization.command_type = 'project.submit'
         AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
         AND command.state = 'authorized'
         AND command.project_id IS NULL
         AND command.payload_digest = authorization.payload_digest
         AND json_extract(command.payload_json, '$.project_id') = NEW.id
         AND json_extract(command.payload_json, '$.slug') = NEW.slug
         AND json_extract(command.payload_json, '$.owner_principal_id') = NEW.owner_principal_id
         AND json_extract(command.payload_json, '$.priority') = NEW.priority
         AND owner.kind = 'human'
         AND owner.state = 'active'
     );
END;

CREATE TRIGGER project_creation_installs_owner_grant
AFTER INSERT ON projects
BEGIN
  INSERT INTO principal_project_roles(
    grant_id, principal_id, project_id, role, granted_at_ms, revoked_at_ms,
    grant_authorization_id, project_submit_authorization_digest,
    revocation_authorization_id
  ) VALUES (
    'project-owner:' || NEW.id, NEW.owner_principal_id, NEW.id, 'owner',
    NEW.created_at_ms, NULL, NULL, NEW.submit_command_authorization_digest, NULL
  );
END;

CREATE TRIGGER project_creation_installs_current_fairness_state
AFTER INSERT ON projects
BEGIN
  INSERT INTO fairness_state(
    project_id, pool, scheduler_epoch, deficit_units, waiting_since_ms,
    last_dispatch_at_ms, dispatch_count, leader_term, revision
  )
  SELECT NEW.id, policy.pool, 0, 0, NULL, NULL, 0, control.current_term, 0
  FROM fairness_policies policy
  CROSS JOIN control_state control
  WHERE control.singleton = 1
    AND NOT EXISTS (
      SELECT 1 FROM policy_invalidations invalidation
      WHERE invalidation.policy_digest = policy.policy_digest
    );
END;

CREATE TRIGGER principals_enter_active
BEFORE INSERT ON principals
WHEN NEW.state <> 'active'
BEGIN SELECT RAISE(ABORT, 'principals must enter through active'); END;

CREATE TRIGGER principals_disable_once
BEFORE UPDATE OF state ON principals
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'principals only transition active to disabled')
  WHERE NOT (OLD.state = 'active' AND NEW.state = 'disabled');
END;

CREATE TRIGGER principal_disable_requires_signing_keys_revoked
BEFORE UPDATE OF state ON principals
WHEN OLD.state = 'active' AND NEW.state = 'disabled'
BEGIN
  SELECT RAISE(ABORT, 'principal cannot be disabled while a signing key is active')
  WHERE EXISTS (
    SELECT 1 FROM signing_keys sk
    WHERE sk.principal_id = NEW.id AND sk.state = 'active'
  );
END;

CREATE TRIGGER principals_identity_is_immutable
BEFORE UPDATE OF id, kind, auth_subject, created_at_ms ON principals
BEGIN SELECT RAISE(ABORT, 'principal identity is immutable'); END;

CREATE TRIGGER principals_no_delete
BEFORE DELETE ON principals
BEGIN SELECT RAISE(ABORT, 'principal history is append-only'); END;

CREATE TRIGGER installation_trust_root_is_one_time
BEFORE INSERT ON installation_trust_root
BEGIN
  SELECT RAISE(ABORT, 'installation trust root is installed once by the root-owned migrator')
  WHERE EXISTS (SELECT 1 FROM installation_trust_root)
     OR NEW.root_key_fingerprint = ''
     OR NEW.installer_manifest_digest = ''
     OR NEW.installer_signature = ''
     OR json_extract(NEW.installer_manifest_json, '$.manifest_digest') IS NOT NEW.installer_manifest_digest
     OR json_extract(NEW.installer_manifest_json, '$.root_key_fingerprint') IS NOT NEW.root_key_fingerprint
     OR NOT EXISTS (
       SELECT 1 FROM schema_install_receipts install
       WHERE install.schema_version = 21
         AND json_extract(NEW.installer_manifest_json, '$.schema_install_receipt_digest') = install.digest
         AND json_extract(NEW.installer_manifest_json, '$.schema_install_migration_digest') = install.migration_digest
         AND json_extract(NEW.installer_manifest_json, '$.schema_install_installer_key_fingerprint') = install.installer_key_fingerprint
     )
     OR json_type(NEW.installer_manifest_json, '$.bootstrap_keys') <> 'array'
     OR json_type(NEW.installer_manifest_json, '$.bootstrap_artifact_manifests') <> 'array'
     OR EXISTS (
       SELECT required.purpose
       FROM (
         SELECT 'key_admin' AS purpose UNION ALL
         SELECT 'runtime_supervisor' UNION ALL
         SELECT 'artifact_broker' UNION ALL
         SELECT 'control_plane' UNION ALL
         SELECT 'schema_validator'
       ) required
       WHERE NOT EXISTS (
         SELECT 1 FROM json_each(NEW.installer_manifest_json, '$.bootstrap_keys') key
         WHERE json_extract(key.value, '$.key_purpose') = required.purpose
       )
     )
     OR NEW.installed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.installed_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER installation_trust_root_no_update
BEFORE UPDATE ON installation_trust_root
BEGIN SELECT RAISE(ABORT, 'installation trust root is immutable'); END;

CREATE TRIGGER installation_trust_root_no_delete
BEFORE DELETE ON installation_trust_root
BEGIN SELECT RAISE(ABORT, 'installation trust root is immutable'); END;

CREATE TRIGGER signing_keys_enter_active
BEFORE INSERT ON signing_keys
WHEN NEW.state <> 'active'
BEGIN SELECT RAISE(ABORT, 'signing keys must enter through active'); END;

CREATE TRIGGER signing_keys_require_authorized_registration
BEFORE INSERT ON signing_keys
BEGIN
  SELECT RAISE(ABORT, 'signing key principal/purpose is invalid or registration is unauthorized')
  WHERE NOT EXISTS (
      SELECT 1 FROM principals p
      WHERE p.id = NEW.principal_id
        AND p.state = 'active'
        AND (
          (NEW.key_purpose = 'executor_result' AND p.kind = 'executor')
          OR (NEW.key_purpose <> 'executor_result' AND p.kind = 'service')
        )
    )
    OR NOT (
      (
        NOT EXISTS (SELECT 1 FROM signing_keys)
        AND NEW.key_purpose = 'key_admin'
        AND EXISTS (
          SELECT 1
          FROM installation_trust_root root
          JOIN json_each(root.installer_manifest_json, '$.bootstrap_keys') bootstrap_key
          WHERE root.singleton = 1
            AND root.root_key_fingerprint = NEW.public_key_fingerprint
            AND json_extract(bootstrap_key.value, '$.key_id') = NEW.key_id
            AND json_extract(bootstrap_key.value, '$.principal_id') = NEW.principal_id
            AND json_extract(bootstrap_key.value, '$.public_key') = NEW.public_key
            AND json_extract(bootstrap_key.value, '$.public_key_fingerprint') = NEW.public_key_fingerprint
            AND json_extract(bootstrap_key.value, '$.key_purpose') = 'key_admin'
            AND json_extract(bootstrap_key.value, '$.expires_at_ms') IS NEW.expires_at_ms
        )
      )
      OR EXISTS (
        SELECT 1
        FROM key_registration_authorizations a
        JOIN current_valid_keys signer
          ON signer.key_id = a.signer_key_id
         AND signer.principal_id = a.signer_principal_id
         AND signer.key_purpose = 'key_admin'
        WHERE a.target_key_id = NEW.key_id
          AND a.target_principal_id = NEW.principal_id
          AND a.target_public_key = NEW.public_key
          AND a.target_public_key_fingerprint = NEW.public_key_fingerprint
          AND a.target_key_purpose = NEW.key_purpose
          AND a.target_expires_at_ms IS NEW.expires_at_ms
          AND a.action = 'register'
          AND a.proof_of_possession_signature <> ''
          AND a.created_at_ms <= NEW.created_at_ms
          AND a.expires_at_ms >= NEW.created_at_ms
          AND (
            (a.installer_manifest_digest IS NOT NULL
              AND a.leader_term IS NULL
              AND NOT EXISTS (SELECT 1 FROM leader_terms)
              AND NOT EXISTS (SELECT 1 FROM control_state)
              AND EXISTS (
                SELECT 1
                FROM installation_trust_root root
                JOIN json_each(root.installer_manifest_json, '$.bootstrap_keys') bootstrap_key
                WHERE root.installer_manifest_digest = a.installer_manifest_digest
                  AND json_extract(bootstrap_key.value, '$.key_id') = a.target_key_id
                  AND json_extract(bootstrap_key.value, '$.principal_id') = a.target_principal_id
                  AND json_extract(bootstrap_key.value, '$.public_key') = a.target_public_key
                  AND json_extract(bootstrap_key.value, '$.public_key_fingerprint') = a.target_public_key_fingerprint
                  AND json_extract(bootstrap_key.value, '$.key_purpose') = a.target_key_purpose
                  AND json_extract(bootstrap_key.value, '$.expires_at_ms') IS a.target_expires_at_ms
                  AND json_extract(bootstrap_key.value, '$.proof_of_possession_signature') = a.proof_of_possession_signature
              ))
            OR
            (a.command_authorization_digest IS NOT NULL
              AND EXISTS (
                SELECT 1 FROM leader_terms lt
                JOIN control_state ctl ON ctl.current_term = lt.term
                WHERE lt.term = a.leader_term AND lt.state = 'active'
              ))
          )
      )
    );
END;

CREATE TRIGGER key_registration_authorization_is_current_and_exact
BEFORE INSERT ON key_registration_authorizations
BEGIN
  SELECT RAISE(ABORT, 'key registration authorization is not exact, current, or key-admin signed')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR (NEW.target_expires_at_ms IS NOT NULL AND NEW.target_expires_at_ms <= NEW.created_at_ms)
     OR json_extract(NEW.canonical_json, '$.target_key_id') IS NOT NEW.target_key_id
     OR json_extract(NEW.canonical_json, '$.target_principal_id') IS NOT NEW.target_principal_id
     OR json_extract(NEW.canonical_json, '$.target_public_key') IS NOT NEW.target_public_key
     OR json_extract(NEW.canonical_json, '$.target_public_key_fingerprint') IS NOT NEW.target_public_key_fingerprint
     OR json_extract(NEW.canonical_json, '$.target_key_purpose') IS NOT NEW.target_key_purpose
     OR json_extract(NEW.canonical_json, '$.target_expires_at_ms') IS NOT NEW.target_expires_at_ms
     OR json_extract(NEW.canonical_json, '$.proof_of_possession_signature') IS NOT NEW.proof_of_possession_signature
     OR json_extract(NEW.canonical_json, '$.action') IS NOT NEW.action
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.installer_manifest_digest') IS NOT NEW.installer_manifest_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys sk
       JOIN principals p ON p.id = sk.principal_id
       WHERE sk.key_id = NEW.signer_key_id
         AND sk.principal_id = NEW.signer_principal_id
         AND sk.key_purpose = 'key_admin'
         AND p.kind = 'service'
         AND (
           (NEW.installer_manifest_digest IS NOT NULL
             AND NEW.action = 'register'
             AND NEW.leader_term IS NULL
             AND NEW.command_authorization_digest IS NULL
             AND NOT EXISTS (SELECT 1 FROM leader_terms)
             AND NOT EXISTS (SELECT 1 FROM control_state)
             AND EXISTS (
               SELECT 1
               FROM installation_trust_root root
               JOIN json_each(root.installer_manifest_json, '$.bootstrap_keys') bootstrap_key
               WHERE root.installer_manifest_digest = NEW.installer_manifest_digest
                 AND root.root_key_fingerprint = sk.public_key_fingerprint
                 AND json_extract(bootstrap_key.value, '$.key_id') = NEW.target_key_id
                 AND json_extract(bootstrap_key.value, '$.principal_id') = NEW.target_principal_id
                 AND json_extract(bootstrap_key.value, '$.public_key') = NEW.target_public_key
                 AND json_extract(bootstrap_key.value, '$.public_key_fingerprint') = NEW.target_public_key_fingerprint
                 AND json_extract(bootstrap_key.value, '$.key_purpose') = NEW.target_key_purpose
                 AND json_extract(bootstrap_key.value, '$.expires_at_ms') IS NEW.target_expires_at_ms
                 AND json_extract(bootstrap_key.value, '$.proof_of_possession_signature') = NEW.proof_of_possession_signature
             ))
           OR (NEW.command_authorization_digest IS NOT NULL AND EXISTS (
             SELECT 1
             FROM command_authorizations ca
             JOIN commands command ON command.id = ca.command_id
             JOIN leader_terms lt ON lt.term = ca.leader_term AND lt.state = 'active'
             JOIN control_state ctl ON ctl.current_term = ca.leader_term
             JOIN principal_global_roles actor_role
               ON actor_role.principal_id = ca.actor_principal_id
              AND actor_role.role = 'admin'
              AND actor_role.revoked_at_ms IS NULL
             WHERE ca.digest = NEW.command_authorization_digest
               AND ca.command_type = 'key.manage'
               AND ca.project_id IS NULL
               AND ca.leader_term = NEW.leader_term
               AND ca.authorization_expires_at_ms >= NEW.created_at_ms
               AND ca.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
               AND ca.payload_digest = command.payload_digest
               AND command.state = 'authorized'
               AND json_extract(command.payload_json, '$.target_key_id') = NEW.target_key_id
               AND json_extract(command.payload_json, '$.target_principal_id') = NEW.target_principal_id
               AND json_extract(command.payload_json, '$.target_public_key') = NEW.target_public_key
               AND json_extract(command.payload_json, '$.target_public_key_fingerprint') = NEW.target_public_key_fingerprint
               AND json_extract(command.payload_json, '$.target_key_purpose') = NEW.target_key_purpose
               AND json_extract(command.payload_json, '$.target_expires_at_ms') IS NEW.target_expires_at_ms
               AND json_extract(command.payload_json, '$.proof_of_possession_signature') = NEW.proof_of_possession_signature
               AND json_extract(command.payload_json, '$.action') = NEW.action
           ))
         )
     );

  SELECT RAISE(ABORT, 'key registration signature lacks a trusted native verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'key_registration_authorization'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.digest
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER key_registration_authorizations_no_update
BEFORE UPDATE ON key_registration_authorizations
BEGIN SELECT RAISE(ABORT, 'key registration authorizations are immutable'); END;

CREATE TRIGGER key_registration_authorizations_no_delete
BEFORE DELETE ON key_registration_authorizations
BEGIN SELECT RAISE(ABORT, 'key registration authorizations are immutable'); END;

CREATE TRIGGER leader_transition_authorization_is_exact_and_signed
BEFORE INSERT ON leader_transition_authorizations
BEGIN
  SELECT RAISE(ABORT, 'leader transition authorization is not exact, current, or lock-supervisor signed')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.previous_term') IS NOT NEW.previous_term
     OR json_extract(NEW.canonical_json, '$.new_term') IS NOT NEW.new_term
     OR json_extract(NEW.canonical_json, '$.previous_leader_instance_id') IS NOT NEW.previous_leader_instance_id
     OR json_extract(NEW.canonical_json, '$.new_leader_instance_id') IS NOT NEW.new_leader_instance_id
     OR json_extract(NEW.canonical_json, '$.previous_heartbeat_at_ms') IS NOT NEW.previous_heartbeat_at_ms
     OR json_extract(NEW.canonical_json, '$.lock_evidence_manifest_digest') IS NOT NEW.lock_evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys supervisor_key
       JOIN principals supervisor ON supervisor.id = supervisor_key.principal_id
       JOIN artifact_manifests evidence ON evidence.digest = NEW.lock_evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE supervisor_key.key_id = NEW.signer_key_id
         AND supervisor_key.principal_id = NEW.signer_principal_id
         AND supervisor_key.key_purpose = 'runtime_supervisor'
         AND supervisor.kind = 'service'
         AND (
           (NEW.new_term = 1
             AND NEW.previous_term IS NULL
             AND EXISTS (SELECT 1 FROM installation_trust_root WHERE singleton = 1)
             AND NOT EXISTS (SELECT 1 FROM leader_terms))
           OR (NEW.new_term > 1 AND EXISTS (
             SELECT 1 FROM leader_terms prior
             WHERE prior.term = NEW.previous_term
               AND prior.leader_instance_id = NEW.previous_leader_instance_id
               AND prior.heartbeat_at_ms = NEW.previous_heartbeat_at_ms
               AND NEW.created_at_ms >= prior.heartbeat_at_ms + 10000
           ))
         )
     );

  SELECT RAISE(ABORT, 'leader transition signature lacks a trusted native verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'leader_transition_authorization'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.digest
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER leader_transition_authorizations_no_update
BEFORE UPDATE ON leader_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'leader transition authorizations are immutable'); END;

CREATE TRIGGER leader_transition_authorizations_no_delete
BEFORE DELETE ON leader_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'leader transition authorizations are immutable'); END;

CREATE TRIGGER leader_heartbeat_attestation_is_exact_and_signed
BEFORE INSERT ON leader_heartbeat_attestations
BEGIN
  SELECT RAISE(ABORT, 'leader heartbeat is not exact, contiguous, or supervisor signed')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.term') IS NOT NEW.term
     OR json_extract(NEW.canonical_json, '$.heartbeat_seq') IS NOT NEW.heartbeat_seq
     OR json_extract(NEW.canonical_json, '$.leader_instance_id') IS NOT NEW.leader_instance_id
     OR json_extract(NEW.canonical_json, '$.lock_evidence_manifest_digest') IS NOT NEW.lock_evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM leader_terms term
       JOIN current_valid_keys supervisor_key
         ON supervisor_key.key_id = NEW.signer_key_id
        AND supervisor_key.principal_id = NEW.signer_principal_id
        AND supervisor_key.key_purpose = 'runtime_supervisor'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.lock_evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE term.term = NEW.term
         AND term.state = 'active'
         AND term.leader_instance_id = NEW.leader_instance_id
         AND NEW.heartbeat_seq = term.heartbeat_seq + 1
         AND NEW.observed_at_ms > term.heartbeat_at_ms
     );

  SELECT RAISE(ABORT, 'leader heartbeat signature lacks a trusted native verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'leader_heartbeat_attestation'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.digest
      AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
  );
END;

CREATE TRIGGER leader_heartbeat_attestations_no_update
BEFORE UPDATE ON leader_heartbeat_attestations
BEGIN SELECT RAISE(ABORT, 'leader heartbeat attestations are immutable'); END;

CREATE TRIGGER leader_heartbeat_attestations_no_delete
BEFORE DELETE ON leader_heartbeat_attestations
BEGIN SELECT RAISE(ABORT, 'leader heartbeat attestations are immutable'); END;

CREATE TRIGGER leader_terms_enter_active
BEFORE INSERT ON leader_terms
BEGIN
  SELECT RAISE(ABORT, 'leader term requires exact transition authority and initial heartbeat')
  WHERE NEW.state <> 'active'
     OR NEW.heartbeat_seq <> 0
     OR NEW.retirement_authorization_digest IS NOT NULL
     OR NEW.retired_at_ms IS NOT NULL
     OR NEW.heartbeat_at_ms <> NEW.acquired_at_ms
     OR NEW.acquired_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.acquired_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1 FROM leader_transition_authorizations authorization
       WHERE authorization.digest = NEW.transition_authorization_digest
         AND authorization.new_term = NEW.term
         AND authorization.new_leader_instance_id = NEW.leader_instance_id
         AND authorization.created_at_ms <= NEW.acquired_at_ms
         AND authorization.expires_at_ms >= NEW.acquired_at_ms
         AND (
           (NEW.term = 1 AND authorization.previous_term IS NULL)
           OR (NEW.term > 1
             AND authorization.previous_term = NEW.term - 1
             AND EXISTS (
               SELECT 1 FROM leader_terms prior
               WHERE prior.term = authorization.previous_term
                 AND prior.state = 'retired'
                 AND prior.retirement_authorization_digest = authorization.digest
             ))
         )
     );
END;

CREATE TRIGGER leader_terms_are_contiguous
BEFORE INSERT ON leader_terms
BEGIN
  SELECT RAISE(ABORT, 'leader term must be MAX(term)+1')
  WHERE NEW.term <> (SELECT COALESCE(MAX(term), 0) + 1 FROM leader_terms);
END;

CREATE TRIGGER leader_terms_identity_is_immutable
BEFORE UPDATE OF term, leader_instance_id, transition_authorization_digest, acquired_at_ms ON leader_terms
BEGIN SELECT RAISE(ABORT, 'leader-term identity is immutable'); END;

CREATE TRIGGER leader_heartbeat_update_requires_attestation
BEFORE UPDATE OF heartbeat_at_ms, heartbeat_seq ON leader_terms
WHEN OLD.heartbeat_at_ms IS NOT NEW.heartbeat_at_ms OR OLD.heartbeat_seq <> NEW.heartbeat_seq
BEGIN
  SELECT RAISE(ABORT, 'leader heartbeat update requires exact next signed attestation')
  WHERE OLD.state <> 'active'
     OR NEW.state <> 'active'
     OR NEW.heartbeat_seq <> OLD.heartbeat_seq + 1
     OR NOT EXISTS (
       SELECT 1 FROM leader_heartbeat_attestations heartbeat
       WHERE heartbeat.term = NEW.term
         AND heartbeat.heartbeat_seq = NEW.heartbeat_seq
         AND heartbeat.leader_instance_id = NEW.leader_instance_id
         AND heartbeat.observed_at_ms = NEW.heartbeat_at_ms
     );
END;

CREATE TRIGGER leader_terms_retire_once
BEFORE UPDATE OF state ON leader_terms
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'leader terms only transition active to retired')
  WHERE NOT (OLD.state = 'active' AND NEW.state = 'retired')
     OR NEW.retired_at_ms IS NULL
     OR NEW.retired_at_ms < OLD.heartbeat_at_ms + 10000
     OR NEW.retirement_authorization_digest IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM leader_transition_authorizations authorization
       WHERE authorization.digest = NEW.retirement_authorization_digest
         AND authorization.previous_term = OLD.term
         AND authorization.new_term = OLD.term + 1
         AND authorization.previous_leader_instance_id = OLD.leader_instance_id
         AND authorization.previous_heartbeat_at_ms = OLD.heartbeat_at_ms
         AND authorization.created_at_ms <= NEW.retired_at_ms
         AND authorization.expires_at_ms >= NEW.retired_at_ms
     );
END;

CREATE TRIGGER leader_retirement_fields_set_once
BEFORE UPDATE OF retirement_authorization_digest, retired_at_ms ON leader_terms
WHEN OLD.retirement_authorization_digest IS NOT NEW.retirement_authorization_digest
  OR OLD.retired_at_ms IS NOT NEW.retired_at_ms
BEGIN
  SELECT RAISE(ABORT, 'leader retirement evidence is set once with retirement')
  WHERE OLD.retirement_authorization_digest IS NOT NULL
     OR OLD.retired_at_ms IS NOT NULL
     OR NEW.state <> 'retired';
END;

CREATE TRIGGER leader_terms_no_delete
BEFORE DELETE ON leader_terms
BEGIN SELECT RAISE(ABORT, 'leader-term history is append-only'); END;

CREATE TRIGGER control_state_requires_active_term_insert
BEFORE INSERT ON control_state
BEGIN
  SELECT RAISE(ABORT, 'control state requires the active leader term')
  WHERE NOT EXISTS (
    SELECT 1 FROM leader_terms
    WHERE term = NEW.current_term AND state = 'active'
  );
  SELECT RAISE(ABORT, 'control state must bootstrap with dispatch disabled')
  WHERE NEW.dispatch_enabled <> 0 OR NEW.admission_mode <> 'stopped';
  SELECT RAISE(ABORT, 'control state must bootstrap at portfolio epoch one')
  WHERE NEW.portfolio_epoch <> 1;
  SELECT RAISE(ABORT, 'control state must bootstrap at revision zero without a replayed command')
  WHERE NEW.revision <> 0 OR NEW.last_command_authorization_digest IS NOT NULL;
END;

CREATE TRIGGER control_state_requires_revision_and_authority
BEFORE UPDATE ON control_state
BEGIN
  SELECT RAISE(ABORT, 'control mutation requires revision plus one')
  WHERE NEW.revision <> OLD.revision + 1;

  SELECT RAISE(ABORT, 'control mutation lacks fail-safe, failover, or exact authenticated authority')
  WHERE NOT (
    (OLD.kill_switch = 0 AND NEW.kill_switch = 1
      AND NEW.dispatch_enabled = 0
      AND NEW.last_command_authorization_digest IS OLD.last_command_authorization_digest)
    OR (OLD.current_term <> NEW.current_term
      AND NEW.dispatch_enabled = 0
      AND NEW.current_term = OLD.current_term + 1
      AND NEW.last_command_authorization_digest IS OLD.last_command_authorization_digest
      AND EXISTS (
        SELECT 1 FROM leader_terms old_term
        JOIN leader_terms new_term ON new_term.term = NEW.current_term
        WHERE old_term.term = OLD.current_term
          AND old_term.state = 'retired'
          AND new_term.state = 'active'
      ))
    OR (NEW.last_command_authorization_digest IS NOT NULL
      AND NEW.last_command_authorization_digest IS NOT OLD.last_command_authorization_digest
      AND EXISTS (
        SELECT 1
        FROM command_authorizations authorization
        JOIN commands command ON command.id = authorization.command_id
        JOIN principal_global_roles role
          ON role.principal_id = authorization.actor_principal_id
         AND role.role IN ('admin','operator')
         AND role.revoked_at_ms IS NULL
        WHERE authorization.digest = NEW.last_command_authorization_digest
          AND authorization.project_id IS NULL
          AND authorization.command_type = 'dispatch.control'
          AND authorization.leader_term = NEW.current_term
          AND authorization.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
          AND command.state = 'authorized'
          AND json_extract(command.payload_json, '$.expected_revision') = OLD.revision
          AND json_extract(command.payload_json, '$.current_term') = NEW.current_term
          AND json_extract(command.payload_json, '$.bootstrap_manifest_digest') IS NEW.bootstrap_manifest_digest
          AND json_extract(command.payload_json, '$.portfolio_epoch') = NEW.portfolio_epoch
          AND json_extract(command.payload_json, '$.dispatch_enabled') = NEW.dispatch_enabled
          AND json_extract(command.payload_json, '$.admission_mode') = NEW.admission_mode
          AND json_extract(command.payload_json, '$.kill_switch') = NEW.kill_switch
      ))
  );
END;

CREATE TRIGGER control_admission_mode_transition_is_legal
BEFORE UPDATE OF dispatch_enabled, admission_mode, kill_switch ON control_state
BEGIN
  SELECT RAISE(ABORT, 'illegal admission/drain transition')
  WHERE NOT (
    (OLD.admission_mode = NEW.admission_mode
      AND OLD.dispatch_enabled = NEW.dispatch_enabled)
    OR (OLD.admission_mode = 'stopped' AND NEW.admission_mode = 'open'
      AND OLD.dispatch_enabled = 0 AND NEW.dispatch_enabled = 1
      AND NEW.kill_switch = 0)
    OR (OLD.admission_mode = 'open' AND NEW.admission_mode = 'draining'
      AND OLD.dispatch_enabled = 1 AND NEW.dispatch_enabled = 1
      AND NEW.kill_switch = 0)
    OR (OLD.admission_mode = 'draining' AND NEW.admission_mode = 'stopped'
      AND NEW.dispatch_enabled = 0 AND NEW.kill_switch = 0)
    OR (OLD.admission_mode IN ('open','draining') AND NEW.admission_mode = 'stopped'
      AND NEW.dispatch_enabled = 0 AND NEW.kill_switch = 1)
  );
END;

CREATE TRIGGER drain_entry_requires_unsent_work_cancelled
BEFORE UPDATE OF admission_mode ON control_state
WHEN OLD.admission_mode = 'open' AND NEW.admission_mode = 'draining'
BEGIN
  SELECT RAISE(ABORT, 'drain entry requires every not-yet-launched dispatch bundle to be cancelled')
  WHERE EXISTS (
      SELECT 1 FROM attempts attempt
      WHERE attempt.state IN ('created','dispatched')
    )
    OR EXISTS (
      SELECT 1 FROM outbox message
      JOIN attempts attempt ON attempt.id = message.attempt_id
      WHERE message.state IN ('pending','claimed','sent')
        AND attempt.state NOT IN ('acked','running','result_pending')
    )
    OR EXISTS (
      SELECT 1 FROM runtime_call_leases call
      WHERE call.state = 'prepared'
    )
    OR EXISTS (
      SELECT 1 FROM runtime_intents intent
      WHERE intent.session_scope = 'project_generation'
        AND intent.state IN ('prepared','launch_claimed','launch_permitted')
    )
    OR EXISTS (
      SELECT 1 FROM merge_requests merge_request
      WHERE merge_request.state = 'leased'
    );
END;

CREATE TRIGGER graceful_stop_requires_full_nonportfolio_quiescence
BEFORE UPDATE OF admission_mode ON control_state
WHEN OLD.admission_mode = 'draining' AND NEW.admission_mode = 'stopped'
  AND NEW.kill_switch = 0
BEGIN
  SELECT RAISE(ABORT, 'graceful stop requires all nonportfolio execution and egress to quiesce')
  WHERE EXISTS (
      SELECT 1 FROM attempts attempt
      WHERE attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
    )
    OR EXISTS (SELECT 1 FROM leases lease WHERE lease.state = 'active')
    OR EXISTS (
      SELECT 1 FROM runtime_call_leases call WHERE call.state IN ('prepared','active','unknown')
    )
    OR EXISTS (
      SELECT 1 FROM runtime_sessions session
      WHERE session.session_scope <> 'portfolio' AND session.state <> 'terminated'
    )
    OR EXISTS (
      SELECT 1 FROM runtime_intents intent
      WHERE intent.session_scope <> 'portfolio'
        AND intent.state NOT IN ('terminated','cancelled','failed')
    )
    OR EXISTS (
      SELECT 1 FROM merge_requests merge_request
      WHERE merge_request.state IN ('leased','integrating','unknown')
    )
    OR EXISTS (
      SELECT 1 FROM external_effects effect
      WHERE effect.state IN ('executing','unknown','manual_reconcile')
    );
END;

CREATE TRIGGER control_state_requires_active_term_update
BEFORE UPDATE OF current_term, dispatch_enabled, admission_mode ON control_state
BEGIN
  SELECT RAISE(ABORT, 'control state requires the active leader term')
  WHERE NOT EXISTS (
    SELECT 1 FROM leader_terms
    WHERE term = NEW.current_term AND state = 'active'
  );
END;

CREATE TRIGGER control_state_no_delete
BEFORE DELETE ON control_state
BEGIN SELECT RAISE(ABORT, 'control state singleton cannot be deleted'); END;

CREATE TRIGGER control_bootstrap_manifest_change_requires_disabled_dispatch
BEFORE UPDATE OF bootstrap_manifest_digest ON control_state
WHEN OLD.bootstrap_manifest_digest IS NOT NEW.bootstrap_manifest_digest
BEGIN
  SELECT RAISE(ABORT, 'bootstrap manifest may change only in a separate dispatch-disabled transaction')
  WHERE OLD.dispatch_enabled <> 0 OR NEW.dispatch_enabled <> 0;
END;

CREATE TRIGGER control_portfolio_epoch_tracks_leader_term
BEFORE UPDATE OF current_term, portfolio_epoch ON control_state
BEGIN
  SELECT RAISE(ABORT, 'portfolio epoch increments exactly once on leader change')
  WHERE (OLD.current_term <> NEW.current_term AND NEW.portfolio_epoch <> OLD.portfolio_epoch + 1)
     OR (OLD.current_term = NEW.current_term AND NEW.portfolio_epoch <> OLD.portfolio_epoch);
END;

CREATE TRIGGER dispatch_enable_requires_verified_bootstrap
BEFORE UPDATE OF dispatch_enabled ON control_state
WHEN OLD.dispatch_enabled = 0 AND NEW.dispatch_enabled = 1
BEGIN
  SELECT RAISE(ABORT, 'dispatch requires a signed bootstrap manifest')
  WHERE NEW.admission_mode <> 'open'
     OR NEW.bootstrap_manifest_digest IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM bootstrap_manifests bm
       JOIN signing_keys sk ON sk.key_id = bm.signer_key_id
       JOIN current_valid_signature_receipts receipt
         ON receipt.record_kind = 'bootstrap_manifest'
        AND receipt.record_id = bm.digest
        AND receipt.record_canonical_json = bm.canonical_json
        AND receipt.record_signer_key_id = bm.signer_key_id
        AND receipt.record_signature = bm.signature
        AND receipt.referenced_digests_verified = 1
        AND receipt.record_digest_verified = 1
        AND receipt.verified_record_digest = bm.digest
       WHERE bm.digest = NEW.bootstrap_manifest_digest
         AND sk.state = 'active'
         AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= bm.created_at_ms)
     );

  SELECT RAISE(ABORT, 'bootstrap roster must contain exactly 5 Fable, 8 Codex, and 3 Opus seats')
  WHERE (SELECT COUNT(*) FROM executors WHERE pool = 'fable') <> 5
     OR (SELECT COUNT(*) FROM executors WHERE pool = 'codex') <> 8
     OR (SELECT COUNT(*) FROM executors WHERE pool = 'opus') <> 3
     OR (SELECT COUNT(*) FROM executor_slots) <> 16
     OR (SELECT COUNT(*) FROM executors
         WHERE (pool='fable' AND id IN ('rick','f1','f2','f3','f4'))
            OR (pool='codex' AND id IN ('c1','c2','c3','c4','c5','c6','c7','c8'))
            OR (pool='opus' AND id IN ('o1','o2','o3'))) <> 16;

  SELECT RAISE(ABORT, 'signed bootstrap executor projection does not exactly match live executors')
  WHERE (SELECT COUNT(*) FROM bootstrap_executor_bindings
         WHERE bootstrap_manifest_digest = NEW.bootstrap_manifest_digest) <> 16
     OR EXISTS (
       SELECT 1
       FROM executors e
       WHERE NOT EXISTS (
         SELECT 1 FROM bootstrap_executor_bindings b
         WHERE b.bootstrap_manifest_digest = NEW.bootstrap_manifest_digest
           AND b.executor_id = e.id
           AND b.principal_id = e.principal_id
           AND b.pool = e.pool
           AND b.runtime = e.runtime
           AND b.requested_model = e.requested_model
           AND b.requested_profile = e.requested_profile
           AND b.runtime_catalog_digest = e.runtime_catalog_digest
           AND b.model = e.model
           AND b.model_family = e.model_family
           AND b.profile = e.profile
           AND b.host_id = e.host_id
           AND b.config_digest = e.config_digest
           AND b.sandbox_policy_digest = e.sandbox_policy_digest
           AND b.fresh_session_required = e.fresh_session_required
       )
     );

  SELECT RAISE(ABORT, 'bootstrap requires exactly four Fable project slots')
  WHERE (SELECT COUNT(*) FROM project_slots) <> 4
     OR EXISTS (
       SELECT 1 FROM project_slots ps
       JOIN executors e ON e.id = ps.orchestrator_executor_id
       WHERE e.pool <> 'fable'
          OR (ps.slot_no = 1 AND e.id <> 'f1')
          OR (ps.slot_no = 2 AND e.id <> 'f2')
          OR (ps.slot_no = 3 AND e.id <> 'f3')
          OR (ps.slot_no = 4 AND e.id <> 'f4')
     );

  SELECT RAISE(ABORT, 'bootstrap Opus capability split is invalid')
  WHERE NOT EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE executor_id = 'o3' AND capability = 'final-review-only' AND scope = 'global'
    )
    OR NOT EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE executor_id = 'o1' AND capability = 'synthesis' AND scope = 'global'
    )
    OR NOT EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE executor_id = 'o2' AND capability = 'blind-challenge' AND scope = 'global'
    )
    OR EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE executor_id = 'o3' AND capability <> 'final-review-only'
    )
    OR EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE (executor_id = 'o1' AND capability IN ('blind-challenge','final-review-only'))
         OR (executor_id = 'o2' AND capability IN ('synthesis','final-review-only'))
    )
    OR (SELECT COUNT(*) FROM executor_capabilities
        WHERE capability = 'final-review-only' AND scope = 'global') <> 1
    OR EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE capability = 'final-review-only' AND executor_id <> 'o3'
    );

  SELECT RAISE(ABORT, 'bootstrap requires exactly one arm-independent benchmark evaluator')
  WHERE NOT EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE executor_id = 'c8' AND capability = 'benchmark-evaluator' AND scope = 'global'
    )
    OR EXISTS (
      SELECT 1 FROM executor_capabilities
      WHERE capability = 'benchmark-evaluator' AND executor_id <> 'c8'
    );

  SELECT RAISE(ABORT, 'signed bootstrap capability projection does not exactly match live capabilities')
  WHERE EXISTS (
      SELECT 1 FROM executor_capabilities ec
      WHERE NOT EXISTS (
        SELECT 1 FROM bootstrap_capability_bindings b
        WHERE b.bootstrap_manifest_digest = NEW.bootstrap_manifest_digest
          AND b.executor_id = ec.executor_id
          AND b.capability = ec.capability
          AND b.scope = ec.scope
      )
    )
    OR EXISTS (
      SELECT 1 FROM bootstrap_capability_bindings b
      WHERE b.bootstrap_manifest_digest = NEW.bootstrap_manifest_digest
        AND NOT EXISTS (
          SELECT 1 FROM executor_capabilities ec
          WHERE ec.executor_id = b.executor_id
            AND ec.capability = b.capability
            AND ec.scope = b.scope
        )
    );

  SELECT RAISE(ABORT, 'signed bootstrap must bind exactly two current managed identities')
  WHERE (SELECT COUNT(*) FROM bootstrap_managed_identity_bindings
         WHERE bootstrap_manifest_digest = NEW.bootstrap_manifest_digest) <> 2
     OR (SELECT COUNT(DISTINCT service_alias) FROM bootstrap_managed_identity_bindings
         WHERE bootstrap_manifest_digest = NEW.bootstrap_manifest_digest
           AND service_alias IN ('morty','space-beth')) <> 2
     OR EXISTS (
       SELECT 1
       FROM bootstrap_managed_identity_bindings b
       JOIN managed_service_identities msi ON msi.digest = b.managed_identity_digest
       JOIN signing_keys sk ON sk.key_id = msi.signer_key_id
       JOIN sanitization_attestations sa ON sa.digest = msi.sanitization_attestation_digest
       JOIN configuration_artifacts rules ON rules.digest = msi.sanitization_rules_digest
       JOIN signing_keys sak ON sak.key_id = sa.signer_key_id
       WHERE b.bootstrap_manifest_digest = NEW.bootstrap_manifest_digest
         AND (msi.service_alias <> b.service_alias
           OR sk.state <> 'active'
           OR (sk.expires_at_ms IS NOT NULL
               AND sk.expires_at_ms < (unixepoch('subsec') * 1000))
           OR sa.subject_manifest_digest <> msi.asset_manifest_digest
           OR sa.rules_digest <> msi.sanitization_rules_digest
           OR sa.allowed_root <> msi.workspace_root
           OR rules.artifact_kind <> 'sanitization_rules'
           OR sak.state <> 'active'
           OR (sak.expires_at_ms IS NOT NULL
               AND sak.expires_at_ms < (unixepoch('subsec') * 1000))
           OR EXISTS (
             SELECT 1 FROM configuration_artifact_invalidations cai
             WHERE cai.configuration_digest IN (msi.config_digest, msi.sanitization_rules_digest)
           )
           OR EXISTS (
             SELECT 1 FROM managed_service_identity_invalidations x
             WHERE x.managed_identity_digest = msi.digest
           ))
     );

  SELECT RAISE(ABORT, 'bootstrap references inactive or invalidated runtime catalog')
  WHERE EXISTS (
    SELECT 1
    FROM executors e
    JOIN runtime_catalogs rc ON rc.digest = e.runtime_catalog_digest
    JOIN signing_keys sk ON sk.key_id = rc.signer_key_id
    WHERE sk.state <> 'active'
       OR (sk.expires_at_ms IS NOT NULL AND sk.expires_at_ms < rc.effective_at_ms)
       OR EXISTS (
         SELECT 1 FROM runtime_catalog_invalidations rci
         WHERE rci.runtime_catalog_digest = rc.digest
       )
  );

  SELECT RAISE(ABORT, 'bootstrap lacks a fresh exact service-UID runtime probe or uses invalidated configuration')
  WHERE EXISTS (
    SELECT 1
    FROM executors e
    JOIN runtime_catalogs rc ON rc.digest = e.runtime_catalog_digest
    WHERE NOT EXISTS (
        SELECT 1
        FROM runtime_catalog_probe_attestations rpa
        JOIN signing_keys sk ON sk.key_id = rpa.signer_key_id
        WHERE rpa.runtime_catalog_digest = rc.digest
          AND rpa.probe_contract_digest = rc.probe_contract_digest
          AND rpa.binary_digest = rc.binary_digest
          AND rpa.actual_model = rc.resolved_model
          AND rpa.actual_model_family = rc.resolved_model_family
          AND rpa.actual_effort = rc.resolved_effort
          AND rpa.executed_uid = rc.service_uid
          AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                   AND (unixepoch('subsec') * 1000) + 5000
          AND sk.state = 'active'
          AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= (unixepoch('subsec') * 1000))
      )
      OR EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest IN (
          e.config_digest, rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
          rc.provider_proxy_profile_digest, rc.io_protocol_digest,
          rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
        )
      )
  );

  SELECT RAISE(ABORT, 'bootstrap toolchain closures are missing, wrong-kind, or invalidated')
  WHERE NOT EXISTS (
    SELECT 1
    FROM bootstrap_manifests bm
    JOIN configuration_artifacts control
      ON control.digest = bm.control_plane_closure_digest
    JOIN configuration_artifacts cli
      ON cli.digest = bm.cli_runtime_closure_digest
    JOIN configuration_artifacts sandbox
      ON sandbox.digest = bm.sandbox_runtime_closure_digest
    JOIN configuration_artifacts scanner
      ON scanner.digest = bm.scanner_profile_digest
    WHERE bm.digest = NEW.bootstrap_manifest_digest
      AND control.artifact_kind = 'control_plane_closure'
      AND cli.artifact_kind = 'cli_runtime_closure'
      AND sandbox.artifact_kind = 'sandbox_runtime_closure'
      AND scanner.artifact_kind = 'scanner_profile'
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest IN (
          control.digest, cli.digest, sandbox.digest, scanner.digest
        )
      )
  );

  SELECT RAISE(ABORT, 'host capacity is stale or below reserved emergency headroom')
  WHERE NOT EXISTS (
    SELECT 1
    FROM current_host_capacity hc
    JOIN bootstrap_manifests bm ON bm.digest = NEW.bootstrap_manifest_digest
    JOIN policies rp ON rp.digest = hc.resource_policy_digest
    JOIN signing_keys rpk ON rpk.key_id = rp.signer_key_id
    JOIN host_resource_policy_limits lim ON lim.policy_digest = rp.digest
    WHERE hc.singleton = 1
      AND bm.resource_policy_digest = hc.resource_policy_digest
      AND rp.policy_type = 'host_resource'
      AND rpk.state = 'active'
      AND (rpk.expires_at_ms IS NULL OR rpk.expires_at_ms >= (unixepoch('subsec') * 1000))
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = rp.digest
      )
      AND hc.measurement_at_ms >= (unixepoch('subsec') * 1000) - 60000
      AND hc.measurement_at_ms <= (unixepoch('subsec') * 1000) + 5000
      AND hc.measured_free_disk_bytes - hc.pending_reserved_disk_bytes
          - hc.clone_log_allowance_bytes >= hc.emergency_reserve_bytes
      AND hc.reserved_rss_bytes <= hc.max_model_rss_bytes
      AND hc.measured_available_ram_bytes
          - hc.pending_reserved_rss_bytes
          >= hc.emergency_ram_bytes
      AND hc.reserved_pid_count <= hc.max_model_pid_count
      AND hc.reserved_fd_count <= hc.max_model_fd_count
      AND hc.reserved_cpu_millis <= hc.max_model_cpu_millis
  );
END;

CREATE TRIGGER executors_enter_starting
BEFORE INSERT ON executors
WHEN NEW.state <> 'starting'
BEGIN SELECT RAISE(ABORT, 'executors must enter through starting'); END;

CREATE TRIGGER executor_capability_change_requires_dispatch_disabled_insert
BEFORE INSERT ON executor_capabilities
WHEN EXISTS (SELECT 1 FROM control_state WHERE singleton=1 AND dispatch_enabled=1)
BEGIN SELECT RAISE(ABORT, 'capability changes require dispatch disabled and new bootstrap'); END;

CREATE TRIGGER executor_capability_change_requires_dispatch_disabled_update
BEFORE UPDATE ON executor_capabilities
WHEN EXISTS (SELECT 1 FROM control_state WHERE singleton=1 AND dispatch_enabled=1)
BEGIN SELECT RAISE(ABORT, 'capability changes require dispatch disabled and new bootstrap'); END;

CREATE TRIGGER executor_capability_change_requires_dispatch_disabled_delete
BEFORE DELETE ON executor_capabilities
WHEN EXISTS (SELECT 1 FROM control_state WHERE singleton=1 AND dispatch_enabled=1)
BEGIN SELECT RAISE(ABORT, 'capability changes require dispatch disabled and new bootstrap'); END;

CREATE TRIGGER executor_matches_runtime_catalog
BEFORE INSERT ON executors
BEGIN
  SELECT RAISE(ABORT, 'executor requested/resolved runtime does not match catalog')
  WHERE NOT EXISTS (
    SELECT 1 FROM runtime_catalogs rc
    JOIN configuration_artifacts cfg ON cfg.digest = NEW.config_digest
    JOIN policies sp ON sp.digest = NEW.sandbox_policy_digest
    JOIN signing_keys ssk ON ssk.key_id = sp.signer_key_id
    WHERE rc.digest = NEW.runtime_catalog_digest
      AND rc.runtime = NEW.runtime
      AND rc.requested_model = NEW.requested_model
      AND rc.requested_profile = NEW.requested_profile
      AND rc.resolved_model = NEW.model
      AND rc.resolved_model_family = NEW.model_family
      AND rc.resolved_effort = NEW.profile
      AND cfg.artifact_kind = 'executor_config'
      AND sp.policy_type = 'sandbox'
      AND ssk.state = 'active'
      AND (ssk.expires_at_ms IS NULL OR ssk.expires_at_ms >= NEW.created_at_ms)
      AND rc.effective_at_ms <= NEW.created_at_ms
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = rc.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest = cfg.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = sp.digest
      )
      AND EXISTS (
        SELECT 1 FROM signing_keys sk
        WHERE sk.key_id = rc.signer_key_id
          AND sk.state = 'active'
          AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= NEW.created_at_ms)
      )
  );
END;

CREATE TRIGGER executor_config_change_requires_disabled_unbound_bootstrap
BEFORE UPDATE OF principal_id, pool, runtime, requested_model, requested_profile,
  runtime_catalog_digest, model, model_family, profile, host_id, config_digest,
  sandbox_policy_digest, fresh_session_required, created_at_ms
ON executors
BEGIN
  SELECT RAISE(ABORT, 'executor configuration changes require disabled dispatch and a cleared bootstrap binding')
  WHERE EXISTS (
    SELECT 1 FROM control_state
    WHERE singleton = 1
      AND (dispatch_enabled <> 0 OR bootstrap_manifest_digest IS NOT NULL)
  );

  SELECT RAISE(ABORT, 'updated executor requested/resolved runtime does not match catalog')
  WHERE NOT EXISTS (
    SELECT 1 FROM runtime_catalogs rc
    JOIN signing_keys sk ON sk.key_id = rc.signer_key_id
    JOIN configuration_artifacts cfg ON cfg.digest = NEW.config_digest
    JOIN policies sp ON sp.digest = NEW.sandbox_policy_digest
    JOIN signing_keys ssk ON ssk.key_id = sp.signer_key_id
    WHERE rc.digest = NEW.runtime_catalog_digest
      AND rc.runtime = NEW.runtime
      AND rc.requested_model = NEW.requested_model
      AND rc.requested_profile = NEW.requested_profile
      AND rc.resolved_model = NEW.model
      AND rc.resolved_model_family = NEW.model_family
      AND rc.resolved_effort = NEW.profile
      AND cfg.artifact_kind = 'executor_config'
      AND sp.policy_type = 'sandbox'
      AND sk.state = 'active'
      AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= (unixepoch('subsec') * 1000))
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = rc.digest
      )
      AND ssk.state = 'active'
      AND (ssk.expires_at_ms IS NULL OR ssk.expires_at_ms >= (unixepoch('subsec') * 1000))
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest = cfg.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = sp.digest
      )
  );
END;

CREATE TRIGGER executors_no_delete
BEFORE DELETE ON executors
BEGIN SELECT RAISE(ABORT, 'executor identities cannot be deleted'); END;

CREATE TRIGGER executors_legal_state_transition
BEFORE UPDATE OF state ON executors
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal executor state transition')
  WHERE NOT (
    (OLD.state = 'starting' AND NEW.state IN ('healthy','degraded','quarantined','offline'))
    OR (OLD.state = 'healthy' AND NEW.state IN ('degraded','quarantined','offline'))
    OR (OLD.state = 'degraded' AND NEW.state IN ('healthy','quarantined','offline'))
    OR (OLD.state = 'quarantined' AND NEW.state IN ('starting','offline'))
    OR (OLD.state = 'offline' AND NEW.state = 'starting')
  );
END;

CREATE TRIGGER executor_slots_enter_available
BEFORE INSERT ON executor_slots
WHEN NEW.state <> 'available'
BEGIN SELECT RAISE(ABORT, 'executor slots must enter through available'); END;

CREATE TRIGGER executor_slot_identity_is_immutable
BEFORE UPDATE OF id, executor_id, ordinal ON executor_slots
BEGIN SELECT RAISE(ABORT, 'executor-slot identity is immutable'); END;

CREATE TRIGGER executor_slots_no_delete
BEFORE DELETE ON executor_slots
BEGIN SELECT RAISE(ABORT, 'executor-slot history cannot be deleted'); END;

CREATE TRIGGER executor_slot_fence_change_is_scoped
BEFORE UPDATE OF fence_counter ON executor_slots
WHEN NEW.fence_counter <> OLD.fence_counter
BEGIN
  SELECT RAISE(ABORT, 'executor-slot fence change is not an authorized allocation or rotation')
  WHERE NEW.fence_counter <> OLD.fence_counter + 1
     OR NOT (
       (OLD.state = 'available' AND NEW.state = 'leased')
       OR (OLD.state = 'leased' AND NEW.state = 'leased' AND EXISTS (
         SELECT 1 FROM executors e
         WHERE e.id = NEW.executor_id
           AND e.pool = 'fable'
           AND e.fresh_session_required = 0
       ))
     );
END;

CREATE TRIGGER executor_slot_live_refence_is_exact
BEFORE UPDATE OF fence_counter ON executor_slots
WHEN OLD.state = 'leased'
 AND NEW.state = 'leased'
 AND NEW.fence_counter <> OLD.fence_counter
BEGIN
  SELECT RAISE(ABORT, 'live slot re-fence must increment exactly once')
  WHERE NEW.fence_counter <> OLD.fence_counter + 1;
END;

CREATE TRIGGER executor_slot_live_refence_requires_quiescence
BEFORE UPDATE OF fence_counter ON executor_slots
WHEN OLD.state = 'leased'
 AND NEW.state = 'leased'
 AND NEW.fence_counter <> OLD.fence_counter
BEGIN
  SELECT RAISE(ABORT, 'persistent Fable slot cannot re-fence until its old work and process are terminal')
  WHERE EXISTS (
          SELECT 1 FROM runtime_intents ri
          WHERE ri.executor_slot_id = OLD.id
            AND ri.state IN ('prepared','launch_claimed','launch_permitted','launched','unknown')
        )
     OR EXISTS (
          SELECT 1 FROM runtime_sessions rs
          WHERE rs.executor_slot_id = OLD.id
            AND rs.state IN ('starting','running','terminating','unknown')
        )
     OR EXISTS (
          SELECT 1 FROM attempts a
          WHERE a.executor_slot_id = OLD.id
            AND a.state IN ('created','dispatched','acked','running','result_pending','unknown')
        )
     OR EXISTS (
          SELECT 1 FROM leases l
          WHERE l.executor_slot_id = OLD.id AND l.state = 'active'
        )
     OR EXISTS (
          SELECT 1
          FROM runtime_intents ri
          JOIN charge_subjects cs ON cs.runtime_intent_id = ri.id
          JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
          WHERE ri.executor_slot_id = OLD.id
            AND rr.state IN ('held','breached')
        );
END;

CREATE TRIGGER executor_slot_lease_increments_fence
BEFORE UPDATE OF state ON executor_slots
WHEN OLD.state = 'available' AND NEW.state = 'leased'
BEGIN
  SELECT RAISE(ABORT, 'slot allocation must increment the fence exactly once')
  WHERE NEW.fence_counter <> OLD.fence_counter + 1;
END;

CREATE TRIGGER executor_slots_legal_state_transition
BEFORE UPDATE OF state ON executor_slots
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal executor-slot state transition')
  WHERE NOT (
    (OLD.state = 'available' AND NEW.state IN ('leased','draining','quarantined','offline'))
    OR (OLD.state = 'leased' AND NEW.state IN ('available','draining','quarantined','offline'))
    OR (OLD.state = 'draining' AND NEW.state IN ('available','quarantined','offline'))
    OR (OLD.state = 'quarantined' AND NEW.state IN ('available','offline'))
    OR (OLD.state = 'offline' AND NEW.state = 'available')
  );
END;

CREATE TRIGGER plan_author_attestation_is_exact_live_fable_result
BEFORE INSERT ON plan_author_attestations
BEGIN
  SELECT RAISE(ABORT, 'plan author attestation is not an exact live Fable result')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.plan_manifest_digest') IS NOT NEW.plan_manifest_digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.planner_runtime_session_id') IS NOT NEW.planner_runtime_session_id
     OR json_extract(NEW.canonical_json, '$.planner_runtime_intent_id') IS NOT NEW.planner_runtime_intent_id
     OR json_extract(NEW.canonical_json, '$.planner_attempt_id') IS NOT NEW.planner_attempt_id
     OR json_extract(NEW.canonical_json, '$.final_usage_event_id') IS NOT NEW.final_usage_event_id
     OR json_extract(NEW.canonical_json, '$.planner_executor_id') IS NOT NEW.planner_executor_id
     OR json_extract(NEW.canonical_json, '$.project_slot_no') IS NOT NEW.project_slot_no
     OR json_extract(NEW.canonical_json, '$.project_slot_generation') IS NOT NEW.project_slot_generation
     OR json_extract(NEW.canonical_json, '$.executor_slot_fence') IS NOT NEW.executor_slot_fence
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM runs run
       JOIN runtime_sessions session
         ON session.id = NEW.planner_runtime_session_id
        AND session.runtime_intent_id = NEW.planner_runtime_intent_id
       JOIN runtime_intents intent
         ON intent.id = session.runtime_intent_id
       JOIN executors executor
         ON executor.id = session.executor_id
        AND executor.id = NEW.planner_executor_id
        AND executor.pool = 'fable'
        AND executor.principal_id = NEW.signer_principal_id
       JOIN current_valid_keys author_key
         ON author_key.key_id = NEW.signer_key_id
        AND author_key.principal_id = executor.principal_id
        AND author_key.key_purpose = 'executor_result'
       JOIN artifact_manifests plan ON plan.digest = NEW.plan_manifest_digest
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = plan.signer_key_id
        AND broker_key.key_purpose = 'artifact_broker'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN leader_terms term ON term.term = control.current_term AND term.state = 'active'
       JOIN usage_events final_usage
         ON final_usage.id = NEW.final_usage_event_id
        AND final_usage.final_marker = 1
       WHERE run.id = NEW.run_id
         AND run.project_id = NEW.project_id
         AND run.run_kind = 'delivery'
         AND run.state = 'created'
         AND run.project_slot_no = NEW.project_slot_no
         AND run.project_slot_generation = NEW.project_slot_generation
         AND session.session_scope = 'project_generation'
         AND session.project_id = NEW.project_id
         AND session.project_slot_no = NEW.project_slot_no
         AND session.project_slot_generation = NEW.project_slot_generation
         AND session.state = 'running'
         AND intent.state = 'launched'
         AND intent.executor_slot_id = session.executor_slot_id
         AND intent.fence = NEW.executor_slot_fence
         AND intent.leader_term = NEW.leader_term
         AND json_extract(plan.canonical_json, '$.planner_runtime_session_id') = session.id
         AND json_extract(plan.canonical_json, '$.project_id') = NEW.project_id
         AND json_extract(plan.canonical_json, '$.run_id') = NEW.run_id
         AND EXISTS (
               SELECT 1
               FROM attempts planner_attempt
               JOIN node_versions planner_node
                 ON planner_node.id = planner_attempt.node_version_id
               JOIN runs planning_run
                 ON planning_run.id = planner_attempt.run_id
                AND planning_run.id = run.predecessor_run_id
                AND planning_run.run_kind = 'planning'
                AND planning_run.state = 'completed'
               JOIN artifact_manifests planning_template
                 ON planning_template.digest = planning_run.plan_manifest_digest
                AND json_extract(planning_template.canonical_json, '$.plan.final_author_logical_node_id')
                    = planner_node.logical_node_id
               JOIN attempt_session_bindings binding
                 ON binding.attempt_id = planner_attempt.id
                AND binding.runtime_session_id = session.id
               JOIN result_envelopes result
                 ON result.attempt_id = planner_attempt.id
                AND result.state = 'accepted'
               JOIN charge_subjects subject
                 ON subject.attempt_id = planner_attempt.id
                AND subject.scope_kind = 'attempt'
               JOIN budget_reservations reservation
                 ON reservation.charge_subject_id = subject.id
                AND reservation.id = final_usage.reservation_id
               WHERE planner_attempt.id = NEW.planner_attempt_id
                 AND planner_attempt.state = 'accepted'
                 AND planner_attempt.project_id = NEW.project_id
                 AND planner_attempt.executor_id = NEW.planner_executor_id
                 AND planner_attempt.leader_term = NEW.leader_term
                 AND planner_node.required_pool = 'fable'
                 AND planning_run.benchmark_preregistration_digest IS run.benchmark_preregistration_digest
                 AND planning_run.benchmark_task_id IS run.benchmark_task_id
                 AND planning_run.benchmark_arm IS run.benchmark_arm
                 AND (
                   (planning_run.benchmark_preregistration_digest IS NULL
                     AND planner_node.stage = 'finalize_fable')
                   OR (planning_run.benchmark_preregistration_digest IS NOT NULL
                     AND EXISTS (
                       SELECT 1 FROM benchmark_arm_runs arm
                       WHERE arm.preregistration_digest = planning_run.benchmark_preregistration_digest
                         AND arm.task_id = planning_run.benchmark_task_id
                         AND arm.arm = planning_run.benchmark_arm
                         AND arm.planning_template_manifest_digest = planning_template.digest
                     ))
                 )
                 AND json_extract(plan.canonical_json, '$.source_plan_output_manifest_digest')
                     = result.output_manifest_digest
             )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'plan_author_attestation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER plan_author_attestations_no_update
BEFORE UPDATE ON plan_author_attestations
BEGIN SELECT RAISE(ABORT, 'plan author attestations are immutable'); END;

CREATE TRIGGER plan_author_attestations_no_delete
BEFORE DELETE ON plan_author_attestations
BEGIN SELECT RAISE(ABORT, 'plan author attestations are immutable'); END;

CREATE TRIGGER runs_enter_created
BEFORE INSERT ON runs
WHEN NEW.state <> 'created'
  OR NEW.plan_manifest_digest IS NOT NULL
  OR NEW.plan_author_attestation_digest IS NOT NULL
  OR NEW.revision <> 0
BEGIN SELECT RAISE(ABORT, 'runs must enter created with no pre-bound plan'); END;

CREATE TRIGGER run_plan_manifest_set_once_before_activation
BEFORE UPDATE OF plan_manifest_digest, plan_author_attestation_digest ON runs
WHEN OLD.plan_manifest_digest IS NOT NEW.plan_manifest_digest
  OR OLD.plan_author_attestation_digest IS NOT NEW.plan_author_attestation_digest
BEGIN
  SELECT RAISE(ABORT, 'run plan must be one signed planning template or one Fable-authored delivery plan')
  WHERE OLD.state <> 'created'
     OR NEW.state <> 'created'
     OR OLD.plan_manifest_digest IS NOT NULL
     OR OLD.plan_author_attestation_digest IS NOT NULL
     OR NEW.plan_manifest_digest IS NULL
     OR NOT (
       (NEW.run_kind = 'planning'
         AND NEW.plan_author_attestation_digest IS NULL
         AND EXISTS (
           SELECT 1
           FROM artifact_manifests plan
           JOIN current_valid_keys broker_key
             ON broker_key.key_id = plan.signer_key_id
            AND broker_key.key_purpose = 'artifact_broker'
           JOIN artifact_instances instance
             ON instance.manifest_digest = plan.digest
            AND instance.artifact_type = 'planning_template'
            AND instance.project_id = NEW.project_id
            AND instance.run_id = NEW.id
            AND instance.node_version_id IS NULL
            AND instance.producer_attempt_id IS NULL
           WHERE plan.digest = NEW.plan_manifest_digest
             AND json_extract(plan.canonical_json, '$.artifact_type') = 'planning_template'
             AND json_extract(plan.canonical_json, '$.project_id') = NEW.project_id
             AND json_extract(plan.canonical_json, '$.run_id') = NEW.id
             AND json_extract(plan.canonical_json, '$.template_policy_digest') = NEW.pipeline_policy_digest
             AND json_type(plan.canonical_json, '$.plan.root_seed_manifest_digests') = 'array'
             AND json_array_length(plan.canonical_json, '$.plan.root_seed_manifest_digests') >= 1
             AND (
              (NEW.benchmark_preregistration_digest IS NULL
             AND json_type(plan.canonical_json, '$.plan.nodes') = 'array'
             AND json_type(plan.canonical_json, '$.plan.edges') = 'array'
             AND json_array_length(plan.canonical_json, '$.plan.nodes') = 8
             AND json_array_length(plan.canonical_json, '$.plan.edges') = 8
             AND (
               SELECT COUNT(DISTINCT json_extract(node.value, '$.node_version_id'))
               FROM json_each(plan.canonical_json, '$.plan.nodes') node
             ) = 8
             AND (
               SELECT COUNT(DISTINCT json_extract(node.value, '$.logical_node_id'))
               FROM json_each(plan.canonical_json, '$.plan.nodes') node
             ) = 8
             AND (
               SELECT COUNT(*)
               FROM json_each(plan.canonical_json, '$.plan.nodes') final_author
               WHERE json_extract(final_author.value, '$.stage') = 'finalize_fable'
                 AND json_extract(final_author.value, '$.logical_node_id')
                     = json_extract(plan.canonical_json, '$.plan.final_author_logical_node_id')
             ) = 1
             AND (
               SELECT COUNT(*)
               FROM json_each(plan.canonical_json, '$.plan.nodes') node
               WHERE json_extract(node.value, '$.stage') = 'research_codex'
                 AND json_extract(node.value, '$.required_pool') = 'codex'
                 AND json_extract(node.value, '$.required_capability') = 'research'
             ) = 2
             AND NOT EXISTS (
               SELECT 1
               FROM (
                 SELECT 'research_opus' AS stage, 'opus' AS pool, 'synthesis' AS capability UNION ALL
                 SELECT 'synthesis_opus', 'opus', 'synthesis' UNION ALL
                 SELECT 'draft_fable', 'fable', 'project-planning' UNION ALL
                 SELECT 'challenge_codex', 'codex', 'feasibility-review' UNION ALL
                 SELECT 'challenge_opus', 'opus', 'blind-challenge' UNION ALL
                 SELECT 'finalize_fable', 'fable', 'project-planning'
               ) required
               WHERE (
                 SELECT COUNT(*)
                 FROM json_each(plan.canonical_json, '$.plan.nodes') node
                 WHERE json_extract(node.value, '$.stage') = required.stage
                   AND json_extract(node.value, '$.required_pool') = required.pool
                   AND json_extract(node.value, '$.required_capability') = required.capability
               ) <> 1
             )
             AND NOT EXISTS (
               SELECT 1
               FROM json_each(plan.canonical_json, '$.plan.nodes') node
               WHERE NOT (
                 (json_extract(node.value, '$.stage') = 'research_codex'
                   AND json_extract(node.value, '$.required_pool') = 'codex'
                   AND json_extract(node.value, '$.required_capability') = 'research')
                 OR (json_extract(node.value, '$.stage') IN ('research_opus','synthesis_opus','challenge_opus')
                   AND json_extract(node.value, '$.required_pool') = 'opus'
                   AND json_extract(node.value, '$.required_capability') = CASE
                     WHEN json_extract(node.value, '$.stage') = 'challenge_opus'
                       THEN 'blind-challenge' ELSE 'synthesis' END)
                 OR (json_extract(node.value, '$.stage') IN ('draft_fable','finalize_fable')
                   AND json_extract(node.value, '$.required_pool') = 'fable'
                   AND json_extract(node.value, '$.required_capability') = 'project-planning')
                 OR (json_extract(node.value, '$.stage') = 'challenge_codex'
                   AND json_extract(node.value, '$.required_pool') = 'codex'
                   AND json_extract(node.value, '$.required_capability') = 'feasibility-review')
               )
             )
             AND NOT EXISTS (
               SELECT 1
               FROM json_each(plan.canonical_json, '$.plan.edges') edge
               GROUP BY json_extract(edge.value, '$.node_version_id'),
                        json_extract(edge.value, '$.depends_on_node_version_id')
               HAVING COUNT(*) <> 1
             )
             AND NOT EXISTS (
               SELECT 1
               FROM json_each(plan.canonical_json, '$.plan.nodes') child
               JOIN json_each(plan.canonical_json, '$.plan.nodes') parent
               WHERE (
                 (json_extract(child.value, '$.stage') = 'synthesis_opus'
                   AND json_extract(parent.value, '$.stage') IN ('research_codex','research_opus'))
                 OR (json_extract(child.value, '$.stage') = 'draft_fable'
                   AND json_extract(parent.value, '$.stage') = 'synthesis_opus')
                 OR (json_extract(child.value, '$.stage') IN ('challenge_codex','challenge_opus')
                   AND json_extract(parent.value, '$.stage') = 'draft_fable')
                 OR (json_extract(child.value, '$.stage') = 'finalize_fable'
                   AND json_extract(parent.value, '$.stage') IN ('challenge_codex','challenge_opus'))
               )
               AND NOT EXISTS (
                 SELECT 1
                 FROM json_each(plan.canonical_json, '$.plan.edges') edge
                 WHERE json_extract(edge.value, '$.node_version_id')
                         = json_extract(child.value, '$.node_version_id')
                   AND json_extract(edge.value, '$.depends_on_node_version_id')
                         = json_extract(parent.value, '$.node_version_id')
                   AND json_extract(edge.value, '$.dependency_type') = CASE
                     WHEN json_extract(child.value, '$.stage') IN ('challenge_codex','challenge_opus','finalize_fable')
                       THEN 'review'
                     ELSE 'artifact'
                   END
               )
             )
              )
              OR
              (NEW.benchmark_preregistration_digest IS NOT NULL
               AND EXISTS (
                 SELECT 1
                 FROM benchmark_arm_runs arm
                 JOIN benchmark_tasks task
                   ON task.preregistration_digest = arm.preregistration_digest
                  AND task.task_id = arm.task_id
                 WHERE arm.preregistration_digest = NEW.benchmark_preregistration_digest
                   AND arm.task_id = NEW.benchmark_task_id
                   AND arm.arm = NEW.benchmark_arm
                   AND arm.project_id = NEW.project_id
                   AND arm.planning_template_manifest_digest = plan.digest
                   AND json_extract(plan.canonical_json, '$.benchmark.preregistration_digest')
                       = arm.preregistration_digest
                   AND json_extract(plan.canonical_json, '$.benchmark.task_id') = arm.task_id
                   AND json_extract(plan.canonical_json, '$.benchmark.arm') = arm.arm
                   AND json_extract(plan.canonical_json, '$.benchmark.base_commit') = arm.base_commit
                   AND json_extract(plan.canonical_json, '$.benchmark.input_manifest_digest')
                       = task.input_manifest_digest
                   AND json_extract(plan.canonical_json, '$.benchmark.prompt_digest') = arm.prompt_digest
                   AND json_extract(plan.canonical_json, '$.benchmark.toolchain_closure_digest')
                       = arm.toolchain_closure_digest
                   AND json_extract(plan.canonical_json, '$.benchmark.inference_budget_digest')
                       = arm.inference_budget_digest
                   AND json_type(plan.canonical_json, '$.plan.nodes') = 'array'
                   AND json_array_length(plan.canonical_json, '$.plan.nodes') > 0
                   AND json_type(plan.canonical_json, '$.plan.edges') = 'array'
                   AND (
                     SELECT COUNT(*)
                     FROM json_each(plan.canonical_json, '$.plan.nodes') final_author
                     WHERE json_extract(final_author.value, '$.logical_node_id')
                           = json_extract(plan.canonical_json, '$.plan.final_author_logical_node_id')
                       AND json_extract(final_author.value, '$.required_pool') = 'fable'
                   ) = 1
               ))
             )
         ))
       OR
       (NEW.run_kind = 'delivery'
         AND NEW.plan_author_attestation_digest IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM artifact_manifests plan
           JOIN current_valid_keys broker_key
             ON broker_key.key_id = plan.signer_key_id
            AND broker_key.key_purpose = 'artifact_broker'
           JOIN artifact_instances instance
             ON instance.manifest_digest = plan.digest
            AND instance.artifact_type = 'plan_bundle'
            AND instance.project_id = NEW.project_id
            AND instance.run_id = NEW.id
            AND instance.node_version_id IS NULL
           JOIN plan_author_attestations author
             ON author.digest = NEW.plan_author_attestation_digest
            AND author.plan_manifest_digest = plan.digest
            AND author.project_id = NEW.project_id
            AND author.run_id = NEW.id
            AND author.project_slot_no = NEW.project_slot_no
            AND author.project_slot_generation = NEW.project_slot_generation
           WHERE plan.digest = NEW.plan_manifest_digest
             AND json_extract(plan.canonical_json, '$.artifact_type') = 'plan_bundle'
             AND json_extract(plan.canonical_json, '$.project_id') = NEW.project_id
             AND json_extract(plan.canonical_json, '$.run_id') = NEW.id
             AND json_type(plan.canonical_json, '$.plan.nodes') = 'array'
             AND json_type(plan.canonical_json, '$.plan.edges') = 'array'
             AND json_type(plan.canonical_json, '$.plan.root_seed_manifest_digests') = 'array'
             AND json_array_length(plan.canonical_json, '$.plan.root_seed_manifest_digests') >= 1
             AND json_array_length(plan.canonical_json, '$.plan.nodes') > 0
             AND (
               NEW.benchmark_preregistration_digest IS NULL
               OR EXISTS (
                 SELECT 1
                 FROM benchmark_arm_runs arm
                 JOIN artifact_manifests treatment
                   ON treatment.digest = arm.treatment_spec_manifest_digest
                 WHERE arm.preregistration_digest = NEW.benchmark_preregistration_digest
                   AND arm.task_id = NEW.benchmark_task_id
                   AND arm.arm = NEW.benchmark_arm
                   AND arm.project_id = NEW.project_id
                   AND json_extract(plan.canonical_json, '$.benchmark.preregistration_digest')
                         = arm.preregistration_digest
                   AND json_extract(plan.canonical_json, '$.benchmark.task_id') = arm.task_id
                   AND json_extract(plan.canonical_json, '$.benchmark.arm') = arm.arm
                   AND json_extract(plan.canonical_json, '$.benchmark.treatment_spec_manifest_digest')
                         = arm.treatment_spec_manifest_digest
                   AND json_extract(plan.canonical_json, '$.plan.graph_digest')
                         = json_extract(treatment.canonical_json, '$.benchmark_treatment.delivery_graph_digest')
               )
             )
             AND (
               SELECT COUNT(*)
               FROM json_each(plan.canonical_json, '$.plan.nodes') final_node
               WHERE json_extract(final_node.value, '$.logical_node_id')
                     = json_extract(plan.canonical_json, '$.plan.final_output_logical_node_id')
             ) = 1
         ))
     );
END;

CREATE TRIGGER replan_override_authorization_is_exact_and_signed
BEFORE INSERT ON replan_override_authorizations
BEGIN
  SELECT RAISE(ABORT, 'replan override is not an exact fresh ordinal-3-or-4 human authority')
  WHERE NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms > NEW.issued_at_ms + 900000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.predecessor_run_id') IS NOT NEW.predecessor_run_id
     OR json_extract(NEW.canonical_json, '$.planned_run_id') IS NOT NEW.planned_run_id
     OR json_extract(NEW.canonical_json, '$.replan_ordinal') IS NOT NEW.replan_ordinal
     OR json_extract(NEW.canonical_json, '$.justification_manifest_digest') IS NOT NEW.justification_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM runs predecessor
       JOIN artifact_manifests justification
         ON justification.digest = NEW.justification_manifest_digest
       JOIN current_valid_keys justification_key
         ON justification_key.key_id = justification.signer_key_id
        AND justification_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'approval_broker'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE predecessor.id = NEW.predecessor_run_id
         AND predecessor.project_id = NEW.project_id
         AND predecessor.run_kind = 'delivery'
         AND predecessor.state IN ('completed','failed','cancelled')
         AND predecessor.benchmark_preregistration_digest IS NULL
         AND NEW.replan_ordinal = predecessor.replan_ordinal + 1
         AND json_extract(justification.canonical_json, '$.artifact_type') = 'evidence'
         AND json_extract(justification.canonical_json, '$.replan_override.project_id') = NEW.project_id
         AND json_extract(justification.canonical_json, '$.replan_override.predecessor_run_id') = NEW.predecessor_run_id
         AND json_extract(justification.canonical_json, '$.replan_override.planned_run_id') = NEW.planned_run_id
         AND json_extract(justification.canonical_json, '$.replan_override.replan_ordinal') = NEW.replan_ordinal
         AND json_extract(justification.canonical_json, '$.replan_override.human_approved') = 1
         AND NOT EXISTS (
           SELECT 1 FROM runs successor WHERE successor.predecessor_run_id = predecessor.id
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'replan_override_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

CREATE TRIGGER replan_override_authorizations_no_update
BEFORE UPDATE ON replan_override_authorizations
BEGIN SELECT RAISE(ABORT, 'replan override authorizations are immutable'); END;

CREATE TRIGGER replan_override_authorizations_no_delete
BEFORE DELETE ON replan_override_authorizations
BEGIN SELECT RAISE(ABORT, 'replan override authorizations are immutable'); END;

CREATE TRIGGER run_matches_live_project_slot
BEFORE INSERT ON runs
BEGIN
  SELECT RAISE(ABORT, 'run root request lacks an exact one-shot authenticated command')
  WHERE NEW.state <> 'created'
     OR NEW.plan_manifest_digest IS NOT NULL
     OR NEW.plan_author_attestation_digest IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT (
       (NEW.admission_permit_digest IS NOT NULL
         AND NEW.root_command_authorization_digest IS NULL
         AND NEW.run_kind = 'planning'
         AND NEW.replan_ordinal = 0
         AND NEW.replan_override_authorization_digest IS NULL
         AND EXISTS (
           SELECT 1
           FROM project_admission_permits permit
           JOIN project_slots slot
             ON slot.slot_no = permit.slot_no
            AND slot.project_id = permit.project_id
            AND slot.generation = permit.new_generation
            AND slot.owner_fence = permit.new_owner_fence
            AND slot.binding_authorization_digest = permit.digest
           JOIN leader_terms term ON term.term = permit.leader_term AND term.state = 'active'
           JOIN control_state control ON control.current_term = permit.leader_term
           WHERE permit.digest = NEW.admission_permit_digest
             AND permit.project_id = NEW.project_id
             AND permit.planned_run_id = NEW.id
             AND permit.planned_predecessor_run_id IS NEW.predecessor_run_id
             AND permit.root_request_digest = NEW.root_request_digest
             AND permit.slot_no = NEW.project_slot_no
             AND permit.new_generation = NEW.project_slot_generation
             AND permit.expires_at_ms >= NEW.created_at_ms
             AND control.dispatch_enabled = 1
             AND control.admission_mode = 'open'
             AND control.kill_switch = 0
         ))
       OR (NEW.admission_permit_digest IS NULL
         AND NEW.root_command_authorization_digest IS NOT NULL
         AND NEW.predecessor_run_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM command_authorizations authorization
           JOIN commands command ON command.id = authorization.command_id
           JOIN current_valid_keys authorization_key
             ON authorization_key.key_id = authorization.signer_key_id
            AND authorization_key.principal_id = authorization.signer_principal_id
            AND authorization_key.key_purpose = 'control_plane'
           JOIN leader_terms term ON term.term = authorization.leader_term AND term.state = 'active'
           JOIN control_state control ON control.current_term = authorization.leader_term
           JOIN principal_project_roles role
             ON role.principal_id = authorization.actor_principal_id
            AND role.project_id = NEW.project_id
            AND role.role IN ('owner','operator')
            AND role.revoked_at_ms IS NULL
           JOIN runs predecessor ON predecessor.id = NEW.predecessor_run_id
           WHERE authorization.digest = NEW.root_command_authorization_digest
             AND authorization.project_id = NEW.project_id
             AND authorization.command_type = 'project.control'
             AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
             AND authorization.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
             AND command.state = 'authorized'
             AND command.expires_at_ms >= NEW.created_at_ms
             AND command.payload_digest = authorization.payload_digest
             AND json_extract(command.payload_json, '$.root_request_digest') = NEW.root_request_digest
             AND json_extract(command.payload_json, '$.run_id') = NEW.id
             AND json_extract(command.payload_json, '$.project_id') = NEW.project_id
             AND json_extract(command.payload_json, '$.run_kind') = NEW.run_kind
             AND json_extract(command.payload_json, '$.replan_ordinal') = NEW.replan_ordinal
             AND json_extract(command.payload_json, '$.replan_override_authorization_digest')
                 IS NEW.replan_override_authorization_digest
             AND json_extract(command.payload_json, '$.action') = 'start_successor_run'
             AND json_extract(command.payload_json, '$.predecessor_run_id') = NEW.predecessor_run_id
             AND predecessor.project_id = NEW.project_id
             AND (
               (predecessor.run_kind = 'planning' AND predecessor.state = 'completed'
                 AND NEW.run_kind = 'delivery'
                 AND NEW.replan_ordinal = predecessor.replan_ordinal
                 AND NEW.replan_override_authorization_digest IS NULL
                 AND json_extract(command.payload_json, '$.successor_reason') = 'planned_delivery')
               OR (predecessor.run_kind = 'planning'
                 AND predecessor.state IN ('failed','cancelled')
                 AND predecessor.benchmark_preregistration_digest IS NULL
                 AND NEW.run_kind = 'planning'
                 AND NEW.replan_ordinal = predecessor.replan_ordinal
                 AND NEW.replan_override_authorization_digest IS NULL
                 AND json_extract(command.payload_json, '$.successor_reason') = 'planning_recovery')
               OR (predecessor.run_kind = 'delivery'
                 AND predecessor.state IN ('completed','failed','cancelled')
                 AND predecessor.benchmark_preregistration_digest IS NULL
                 AND NEW.run_kind = 'planning'
                 AND NEW.replan_ordinal = predecessor.replan_ordinal + 1
                 AND NEW.replan_ordinal <= 4
                 AND (
                   (NEW.replan_ordinal <= 2
                     AND NEW.replan_override_authorization_digest IS NULL)
                   OR (NEW.replan_ordinal IN (3,4)
                     AND EXISTS (
                       SELECT 1 FROM replan_override_authorizations override
                       WHERE override.digest = NEW.replan_override_authorization_digest
                         AND override.project_id = NEW.project_id
                         AND override.predecessor_run_id = predecessor.id
                         AND override.planned_run_id = NEW.id
                         AND override.replan_ordinal = NEW.replan_ordinal
                         AND override.expires_at_ms >= NEW.created_at_ms
                     ))
                 )
                 AND json_extract(command.payload_json, '$.successor_reason') = 'replan_after_delivery')
             )
         ))
     );

  SELECT RAISE(ABORT, 'benchmark run tuple is not an exact frozen preregistration binding')
  WHERE NEW.benchmark_preregistration_digest IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM benchmark_preregistrations preregistration
      JOIN benchmark_tasks task
        ON task.preregistration_digest = preregistration.digest
       AND task.task_id = NEW.benchmark_task_id
      LEFT JOIN command_authorizations authorization
        ON authorization.digest = NEW.root_command_authorization_digest
      LEFT JOIN commands command ON command.id = authorization.command_id
      LEFT JOIN project_admission_permits permit
        ON permit.digest = NEW.admission_permit_digest
      WHERE preregistration.digest = NEW.benchmark_preregistration_digest
        AND preregistration.sealed_at_ms <= NEW.created_at_ms
        AND COALESCE(
              json_extract(command.payload_json, '$.benchmark_preregistration_digest'),
              json_extract(permit.canonical_json, '$.benchmark.preregistration_digest'))
            = NEW.benchmark_preregistration_digest
        AND COALESCE(json_extract(command.payload_json, '$.benchmark_task_id'),
                     json_extract(permit.canonical_json, '$.benchmark.task_id')) = NEW.benchmark_task_id
        AND COALESCE(json_extract(command.payload_json, '$.benchmark_arm'),
                     json_extract(permit.canonical_json, '$.benchmark.arm')) = NEW.benchmark_arm
    );

  SELECT RAISE(ABORT, 'run does not match the live project-slot generation')
  WHERE NOT EXISTS (
    SELECT 1 FROM project_slots ps
    WHERE ps.slot_no = NEW.project_slot_no
      AND ps.project_id = NEW.project_id
      AND ps.generation = NEW.project_slot_generation
  );

  SELECT RAISE(ABORT, 'predecessor run must be terminal and belong to project')
  WHERE NEW.predecessor_run_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM runs prior
      WHERE prior.id = NEW.predecessor_run_id
        AND prior.project_id = NEW.project_id
        AND prior.state IN ('completed','failed','cancelled')
        AND prior.finished_at_ms IS NOT NULL
        AND NEW.created_at_ms >= prior.finished_at_ms
        AND NOT EXISTS (
          SELECT 1 FROM runs successor
          WHERE successor.predecessor_run_id = prior.id
        )
        AND NOT EXISTS (
          SELECT 1 FROM runs later
          WHERE later.project_id = NEW.project_id
            AND later.created_at_ms > prior.created_at_ms
        )
    );
END;

CREATE TRIGGER run_activation_requires_launched_project_runtime
BEFORE UPDATE OF state ON runs
WHEN OLD.state = 'created' AND NEW.state = 'active'
BEGIN
  SELECT RAISE(ABORT, 'benchmark run is not a unique immutable arm-chain member')
  WHERE NEW.benchmark_preregistration_digest IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM benchmark_arm_runs arm
      JOIN benchmark_arm_run_members member
        ON member.arm_execution_id = arm.arm_execution_id
       AND member.run_id = NEW.id
       AND member.run_kind = NEW.run_kind
      WHERE arm.preregistration_digest = NEW.benchmark_preregistration_digest
        AND arm.task_id = NEW.benchmark_task_id
        AND arm.arm = NEW.benchmark_arm
    );

  SELECT RAISE(ABORT, 'run activation requires the exact launched project-generation runtime')
  WHERE NOT EXISTS (
    SELECT 1
    FROM projects p
    JOIN project_slots ps
      ON ps.project_id = p.id
     AND ps.slot_no = NEW.project_slot_no
     AND ps.generation = NEW.project_slot_generation
    JOIN artifact_manifests plan ON plan.digest = NEW.plan_manifest_digest
    JOIN current_valid_keys plan_key ON plan_key.key_id = plan.signer_key_id
    JOIN artifact_instances plan_instance
      ON plan_instance.manifest_digest = plan.digest
     AND plan_instance.artifact_type = CASE NEW.run_kind
       WHEN 'planning' THEN 'planning_template'
       ELSE 'plan_bundle'
     END
     AND plan_instance.project_id = NEW.project_id
     AND plan_instance.run_id = NEW.id
     AND plan_instance.node_version_id IS NULL
     AND plan_instance.producer_attempt_id IS NULL
    JOIN runtime_sessions rs
      ON rs.project_id = p.id
     AND rs.project_slot_no = ps.slot_no
     AND rs.project_slot_generation = ps.generation
     AND rs.session_scope = 'project_generation'
    JOIN runtime_intents ri ON ri.id = rs.runtime_intent_id
    JOIN charge_subjects cs
      ON cs.runtime_intent_id = ri.id
     AND cs.scope_kind = 'project_runtime'
     AND cs.project_id = p.id
    JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
    WHERE p.id = NEW.project_id
      AND p.state IN ('admitted','blocked')
      AND ps.orchestrator_executor_id = ri.executor_id
      AND rs.executor_id = ri.executor_id
      AND ri.state = 'launched'
      AND rs.state = 'running'
      AND rr.state = 'held'
      AND plan_key.key_purpose = 'artifact_broker'
  );

  SELECT RAISE(ABORT, 'run plan graph projection is incomplete or contains unsigned members')
  WHERE EXISTS (
      SELECT 1
      FROM artifact_manifests plan, json_each(plan.canonical_json, '$.plan.nodes') member
      WHERE plan.digest = NEW.plan_manifest_digest
        AND NOT EXISTS (
          SELECT 1
          FROM node_versions nv
          JOIN logical_nodes ln ON ln.id = nv.logical_node_id
          WHERE nv.run_id = NEW.id
            AND nv.id = json_extract(member.value, '$.node_version_id')
            AND ln.id = json_extract(member.value, '$.logical_node_id')
            AND ln.node_key = json_extract(member.value, '$.node_key')
            AND nv.version_no = json_extract(member.value, '$.version_no')
            AND nv.stage = json_extract(member.value, '$.stage')
            AND nv.role = json_extract(member.value, '$.role')
            AND nv.required_pool = json_extract(member.value, '$.required_pool')
            AND nv.required_capability = json_extract(member.value, '$.required_capability')
            AND nv.output_schema_digest = json_extract(member.value, '$.output_schema_digest')
            AND nv.policy_digest = json_extract(member.value, '$.policy_digest')
            AND nv.retry_limit = json_extract(member.value, '$.retry_limit')
            AND nv.estimated_cost_units = json_extract(member.value, '$.estimated_cost_units')
        )
    )
    OR EXISTS (
      SELECT 1 FROM node_versions nv
      WHERE nv.run_id = NEW.id
        AND NOT EXISTS (
          SELECT 1
          FROM artifact_manifests plan, json_each(plan.canonical_json, '$.plan.nodes') member
          WHERE plan.digest = NEW.plan_manifest_digest
            AND json_extract(member.value, '$.node_version_id') = nv.id
        )
    )
    OR EXISTS (
      SELECT 1
      FROM artifact_manifests plan, json_each(plan.canonical_json, '$.plan.edges') edge
      WHERE plan.digest = NEW.plan_manifest_digest
        AND NOT EXISTS (
          SELECT 1 FROM node_dependencies dependency
          WHERE dependency.node_version_id = json_extract(edge.value, '$.node_version_id')
            AND dependency.depends_on_node_version_id = json_extract(edge.value, '$.depends_on_node_version_id')
            AND dependency.dependency_type = json_extract(edge.value, '$.dependency_type')
        )
    )
    OR EXISTS (
      SELECT 1
      FROM node_dependencies dependency
      JOIN node_versions nv ON nv.id = dependency.node_version_id
      WHERE nv.run_id = NEW.id
        AND NOT EXISTS (
          SELECT 1
          FROM artifact_manifests plan, json_each(plan.canonical_json, '$.plan.edges') edge
          WHERE plan.digest = NEW.plan_manifest_digest
            AND json_extract(edge.value, '$.node_version_id') = dependency.node_version_id
            AND json_extract(edge.value, '$.depends_on_node_version_id') = dependency.depends_on_node_version_id
            AND json_extract(edge.value, '$.dependency_type') = dependency.dependency_type
        )
    )
    OR EXISTS (
      SELECT 1 FROM node_versions nv
      WHERE nv.run_id = NEW.id AND nv.version_no <> 1
    )
    OR (SELECT COUNT(*) FROM node_versions nv WHERE nv.run_id = NEW.id)
       <> (SELECT COUNT(DISTINCT nv.logical_node_id) FROM node_versions nv WHERE nv.run_id = NEW.id);
END;

CREATE TRIGGER logical_node_requires_signed_plan_membership
BEFORE INSERT ON logical_nodes
BEGIN
  SELECT RAISE(ABORT, 'logical node is not a member of a signed created-run plan')
  WHERE NOT EXISTS (
    SELECT 1
    FROM runs run
    JOIN artifact_manifests plan ON plan.digest = run.plan_manifest_digest,
         json_each(plan.canonical_json, '$.plan.nodes') member
    WHERE run.project_id = NEW.project_id
      AND run.state = 'created'
      AND json_extract(member.value, '$.logical_node_id') = NEW.id
      AND json_extract(member.value, '$.node_key') = NEW.node_key
  );
END;

CREATE TRIGGER node_versions_enter_pending
BEFORE INSERT ON node_versions
BEGIN
  SELECT RAISE(ABORT, 'node version must enter pending as an exact signed plan member')
  WHERE NEW.state <> 'pending'
     OR NEW.input_manifest_digest IS NOT NULL
     OR NEW.revision <> 0
     OR NOT (
       EXISTS (
         SELECT 1
         FROM runs run
         JOIN logical_nodes ln ON ln.id = NEW.logical_node_id
         JOIN artifact_manifests plan ON plan.digest = run.plan_manifest_digest,
              json_each(plan.canonical_json, '$.plan.nodes') member
         WHERE run.id = NEW.run_id
           AND run.state = 'created'
           AND ln.project_id = run.project_id
           AND json_extract(member.value, '$.node_version_id') = NEW.id
           AND json_extract(member.value, '$.logical_node_id') = NEW.logical_node_id
           AND json_extract(member.value, '$.node_key') = ln.node_key
           AND json_extract(member.value, '$.version_no') = NEW.version_no
           AND json_extract(member.value, '$.stage') = NEW.stage
           AND json_extract(member.value, '$.role') = NEW.role
           AND json_extract(member.value, '$.required_pool') = NEW.required_pool
           AND json_extract(member.value, '$.required_capability') = NEW.required_capability
           AND json_extract(member.value, '$.output_schema_digest') = NEW.output_schema_digest
           AND json_extract(member.value, '$.policy_digest') = NEW.policy_digest
           AND json_extract(member.value, '$.retry_limit') = NEW.retry_limit
           AND json_extract(member.value, '$.estimated_cost_units') = NEW.estimated_cost_units
       )
       OR EXISTS (
         SELECT 1
         FROM failover_authorizations authorization
         JOIN runs run ON run.id = authorization.run_id
         JOIN logical_nodes ln ON ln.id = authorization.logical_node_id
         JOIN leader_terms term
           ON term.term = authorization.leader_term AND term.state = 'active'
         JOIN control_state control
           ON control.current_term = authorization.leader_term
          AND control.dispatch_enabled = 1
          AND control.admission_mode = 'open'
          AND control.kill_switch = 0
         JOIN project_slots project_slot
           ON project_slot.slot_no = authorization.project_slot_no
          AND project_slot.project_id = run.project_id
          AND project_slot.generation = authorization.project_slot_generation
          AND project_slot.owner_fence = authorization.owner_fence
         JOIN current_valid_keys authorization_key
           ON authorization_key.key_id = authorization.signer_key_id
          AND authorization_key.principal_id = authorization.signer_principal_id
          AND authorization_key.key_purpose = 'control_plane'
         WHERE authorization.to_node_version_id = NEW.id
           AND authorization.logical_node_id = NEW.logical_node_id
           AND authorization.run_id = NEW.run_id
           AND authorization.version_no = NEW.version_no
           AND authorization.stage = NEW.stage
           AND authorization.role = NEW.role
           AND authorization.fallback_pool = NEW.required_pool
           AND authorization.fallback_capability = NEW.required_capability
           AND authorization.output_schema_digest = NEW.output_schema_digest
           AND authorization.policy_digest = NEW.policy_digest
           AND authorization.retry_limit = NEW.retry_limit
           AND authorization.estimated_cost_units = NEW.estimated_cost_units
           AND run.state = 'active'
           AND ln.project_id = run.project_id
           AND authorization.created_at_ms >= (unixepoch('subsec') * 1000) - 30000
           AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
       )
     );
END;

CREATE TRIGGER logical_nodes_no_update
BEFORE UPDATE ON logical_nodes
BEGIN SELECT RAISE(ABORT, 'logical-node identity is immutable'); END;

CREATE TRIGGER logical_nodes_no_delete
BEFORE DELETE ON logical_nodes
BEGIN SELECT RAISE(ABORT, 'logical-node history is append-only'); END;

CREATE TRIGGER runs_identity_is_immutable
BEFORE UPDATE OF id, project_id, predecessor_run_id, run_kind,
  project_slot_no, project_slot_generation, root_request_digest,
  root_command_authorization_digest, admission_permit_digest, pipeline_policy_digest,
  benchmark_preregistration_digest, benchmark_task_id, benchmark_arm, created_at_ms
ON runs
BEGIN SELECT RAISE(ABORT, 'run identity is immutable'); END;

CREATE TRIGGER runs_no_delete
BEFORE DELETE ON runs
BEGIN SELECT RAISE(ABORT, 'run history is append-only'); END;

CREATE TRIGGER node_version_definition_is_immutable
BEFORE UPDATE OF id, logical_node_id, run_id, version_no, stage, role,
  required_pool, required_capability, output_schema_digest, policy_digest, retry_limit,
  estimated_cost_units, created_at_ms
ON node_versions
BEGIN SELECT RAISE(ABORT, 'node-version definition is immutable'); END;

CREATE TRIGGER node_input_manifest_set_once_while_pending
BEFORE UPDATE OF input_manifest_digest ON node_versions
WHEN OLD.input_manifest_digest IS NOT NEW.input_manifest_digest
BEGIN
  SELECT RAISE(ABORT, 'node input manifest may be set once while pending')
  WHERE OLD.state <> 'pending'
     OR NEW.state <> 'pending'
     OR OLD.input_manifest_digest IS NOT NULL
     OR NEW.input_manifest_digest IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM artifact_instances ai
       JOIN current_valid_keys k
       JOIN artifact_manifests am
         ON am.digest = ai.manifest_digest AND am.signer_key_id = k.key_id
       JOIN runs r ON r.id = NEW.run_id
       WHERE ai.manifest_digest = NEW.input_manifest_digest
         AND ai.artifact_type = 'node_input'
         AND ai.project_id = r.project_id
         AND ai.run_id = NEW.run_id
         AND ai.node_version_id = NEW.id
         AND ai.producer_attempt_id IS NULL
         AND k.key_purpose = 'artifact_broker'
     )
     OR EXISTS (
       SELECT 1
       FROM runs run
       WHERE run.id = NEW.run_id
         AND run.benchmark_preregistration_digest IS NOT NULL
         AND NOT EXISTS (
           SELECT 1
           FROM artifact_manifests input_manifest
           JOIN benchmark_arm_runs arm
             ON arm.preregistration_digest = run.benchmark_preregistration_digest
            AND arm.task_id = run.benchmark_task_id
            AND arm.arm = run.benchmark_arm
           JOIN benchmark_tasks task
             ON task.preregistration_digest = arm.preregistration_digest
            AND task.task_id = arm.task_id
           WHERE input_manifest.digest = NEW.input_manifest_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.preregistration_digest')
                 = arm.preregistration_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.task_id') = arm.task_id
             AND json_extract(input_manifest.canonical_json, '$.benchmark.arm') = arm.arm
             AND json_extract(input_manifest.canonical_json, '$.benchmark.source_input_manifest_digest')
                 = task.input_manifest_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.prompt_digest')
                 = arm.prompt_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.toolchain_closure_digest')
                 = arm.toolchain_closure_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.inference_budget_digest')
                 = arm.inference_budget_digest
             AND json_extract(input_manifest.canonical_json, '$.benchmark.isolation_namespace')
                 = arm.isolation_namespace
         )
     )
     OR EXISTS (
       SELECT 1
       FROM runs run
       WHERE run.id = NEW.run_id
         AND run.benchmark_preregistration_digest IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM node_dependencies dependency
           WHERE dependency.node_version_id = NEW.id
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_arm_seed_bindings binding
           JOIN artifact_instances input_instance
             ON input_instance.id = binding.input_artifact_instance_id
           JOIN benchmark_arm_runs arm
             ON arm.arm_execution_id = binding.arm_execution_id
           WHERE binding.node_version_id = NEW.id
             AND input_instance.manifest_digest = NEW.input_manifest_digest
             AND arm.preregistration_digest = run.benchmark_preregistration_digest
             AND arm.task_id = run.benchmark_task_id
             AND arm.arm = run.benchmark_arm
         )
     );
END;

CREATE TRIGGER node_versions_no_delete
BEFORE DELETE ON node_versions
BEGIN SELECT RAISE(ABORT, 'node-version history is append-only'); END;

CREATE TRIGGER node_version_matches_run_and_sequence
BEFORE INSERT ON node_versions
BEGIN
  SELECT RAISE(ABORT, 'node version does not match run project')
  WHERE NOT EXISTS (
    SELECT 1
    FROM logical_nodes ln
    JOIN runs r ON r.id = NEW.run_id
    WHERE ln.id = NEW.logical_node_id
      AND ln.project_id = r.project_id
  );

  SELECT RAISE(ABORT, 'node-version number must be contiguous inside its run')
  WHERE NEW.version_no <> (
    SELECT COALESCE(MAX(version_no), 0) + 1
    FROM node_versions
    WHERE logical_node_id = NEW.logical_node_id
      AND run_id = NEW.run_id
  );

  SELECT RAISE(ABORT, 'node version references an invalidated policy')
  WHERE EXISTS (
    SELECT 1 FROM policy_invalidations
    WHERE policy_digest = NEW.policy_digest
  );

  SELECT RAISE(ABORT, 'node version requires an active immutable output schema')
  WHERE NOT EXISTS (
    SELECT 1 FROM configuration_artifacts schema_artifact
    WHERE schema_artifact.digest = NEW.output_schema_digest
      AND schema_artifact.artifact_kind = 'output_schema'
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest = schema_artifact.digest
      )
  );
END;

CREATE TRIGGER node_dependency_is_same_run_and_acyclic
BEFORE INSERT ON node_dependencies
BEGIN
  SELECT RAISE(ABORT, 'dependency is not an exact signed plan edge')
  WHERE NOT (
    EXISTS (
      SELECT 1
      FROM node_versions child
      JOIN runs run ON run.id = child.run_id
      JOIN artifact_manifests plan ON plan.digest = run.plan_manifest_digest,
           json_each(plan.canonical_json, '$.plan.edges') edge
      WHERE child.id = NEW.node_version_id
        AND run.state = 'created'
        AND json_extract(edge.value, '$.node_version_id') = NEW.node_version_id
        AND json_extract(edge.value, '$.depends_on_node_version_id') = NEW.depends_on_node_version_id
        AND json_extract(edge.value, '$.dependency_type') = NEW.dependency_type
    )
    OR EXISTS (
      SELECT 1
      FROM node_versions child
      JOIN runs run ON run.id = child.run_id
      JOIN failover_authorizations authorization
        ON authorization.to_node_version_id = child.id,
           json_each(authorization.dependencies_json) dependency
      WHERE child.id = NEW.node_version_id
        AND run.state = 'active'
        AND authorization.run_id = child.run_id
        AND json_extract(dependency.value, '$.depends_on_node_version_id')
            = NEW.depends_on_node_version_id
        AND json_extract(dependency.value, '$.dependency_type') = NEW.dependency_type
    )
  );

  SELECT RAISE(ABORT, 'dependency must remain inside one run and project')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions child
    JOIN node_versions parent ON parent.id = NEW.depends_on_node_version_id
    JOIN logical_nodes child_ln ON child_ln.id = child.logical_node_id
    JOIN logical_nodes parent_ln ON parent_ln.id = parent.logical_node_id
    WHERE child.id = NEW.node_version_id
      AND child.run_id = parent.run_id
      AND child_ln.project_id = parent_ln.project_id
      AND child.state = 'pending'
  );

  SELECT RAISE(ABORT, 'dependency would create a cycle')
  WHERE EXISTS (
    WITH RECURSIVE reachable(id) AS (
      SELECT NEW.depends_on_node_version_id
      UNION
      SELECT nd.depends_on_node_version_id
      FROM node_dependencies nd
      JOIN reachable r ON nd.node_version_id = r.id
    )
    SELECT 1 FROM reachable WHERE id = NEW.node_version_id
  );
END;

CREATE TRIGGER node_dependencies_no_update
BEFORE UPDATE ON node_dependencies
BEGIN SELECT RAISE(ABORT, 'versioned dependencies are immutable'); END;

CREATE TRIGGER node_dependencies_no_delete
BEFORE DELETE ON node_dependencies
BEGIN SELECT RAISE(ABORT, 'versioned dependencies are immutable'); END;

CREATE TRIGGER fairness_dispatch_permit_is_exact_current_winner
BEFORE INSERT ON fairness_dispatch_permits
BEGIN
  SELECT RAISE(ABORT, 'fairness dispatch permit is stale, inexact, or not the deterministic eligible winner')
  WHERE NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.issued_at_ms + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.node_version_id') IS NOT NEW.node_version_id
     OR json_extract(NEW.canonical_json, '$.executor_id') IS NOT NEW.executor_id
     OR json_extract(NEW.canonical_json, '$.pool') IS NOT NEW.pool
     OR json_extract(NEW.canonical_json, '$.fairness_policy_digest') IS NOT NEW.fairness_policy_digest
     OR json_extract(NEW.canonical_json, '$.expected_fairness_revision') IS NOT NEW.expected_fairness_revision
     OR json_extract(NEW.canonical_json, '$.expected_scheduler_epoch') IS NOT NEW.expected_scheduler_epoch
     OR json_extract(NEW.canonical_json, '$.estimated_cost_units') IS NOT NEW.estimated_cost_units
     OR json_extract(NEW.canonical_json, '$.winner_score_units') IS NOT NEW.winner_score_units
     OR json_extract(NEW.canonical_json, '$.candidate_snapshot_digest') IS NOT NEW.candidate_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NEW.project_id IS NOT (
       SELECT candidate.id
       FROM projects candidate
       JOIN fairness_state fairness
         ON fairness.project_id = candidate.id AND fairness.pool = NEW.pool
       JOIN fairness_policies policy ON policy.pool = fairness.pool
       WHERE candidate.state IN ('admitted','active')
         AND fairness.leader_term = NEW.leader_term
         AND EXISTS (
           SELECT 1 FROM runs run
           JOIN node_versions ready_node ON ready_node.run_id = run.id
           WHERE run.project_id = candidate.id
             AND run.state = 'active'
             AND ready_node.required_pool = NEW.pool
             AND ready_node.state = 'ready'
             AND EXISTS (
               SELECT 1
               FROM executors candidate_executor
               JOIN executor_capabilities candidate_capability
                 ON candidate_capability.executor_id = candidate_executor.id
                AND candidate_capability.capability = ready_node.required_capability
                AND candidate_capability.scope IN ('global', candidate.id)
               WHERE candidate_executor.pool = NEW.pool
                 AND candidate_executor.state IN ('healthy','degraded')
                 AND candidate_executor.breaker_state IN ('closed','half_open')
                 AND (
                   (candidate_executor.fresh_session_required = 1 AND EXISTS (
                     SELECT 1 FROM executor_slots candidate_slot
                     WHERE candidate_slot.executor_id = candidate_executor.id
                       AND candidate_slot.state = 'available'
                   ))
                   OR (candidate_executor.fresh_session_required = 0 AND EXISTS (
                     SELECT 1 FROM project_slots candidate_project_slot
                     JOIN runtime_sessions candidate_session
                       ON candidate_session.executor_id = candidate_executor.id
                      AND candidate_session.project_id = candidate.id
                      AND candidate_session.project_slot_generation = candidate_project_slot.generation
                      AND candidate_session.state = 'running'
                     JOIN executor_slots persistent_slot
                       ON persistent_slot.executor_id = candidate_executor.id
                      AND persistent_slot.state = 'leased'
                      AND persistent_slot.fence_counter = candidate_project_slot.owner_fence
                     WHERE candidate_project_slot.project_id = candidate.id
                       AND candidate_project_slot.orchestrator_executor_id = candidate_executor.id
                   ))
                 )
             )
         )
         AND EXISTS (
           SELECT 1 FROM budget_accounts budget
           WHERE budget.project_id = candidate.id AND budget.state = 'active'
         )
         AND EXISTS (SELECT 1 FROM project_slots slot WHERE slot.project_id = candidate.id)
         AND (NEW.pool <> 'codex' OR (
           SELECT COUNT(*) FROM attempts capped_attempt
           JOIN executors capped_executor
             ON capped_executor.id = capped_attempt.executor_id
            AND capped_executor.pool = 'codex'
           WHERE capped_attempt.project_id = candidate.id
             AND capped_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
         ) < 4)
         AND (NEW.pool <> 'codex' OR NOT EXISTS (
           SELECT 1
           FROM projects underserved_project
           JOIN runs underserved_run
             ON underserved_run.project_id = underserved_project.id
            AND underserved_run.state = 'active'
           JOIN node_versions underserved_node
             ON underserved_node.run_id = underserved_run.id
            AND underserved_node.required_pool = 'codex'
            AND underserved_node.state = 'ready'
           WHERE underserved_project.state IN ('admitted','active')
             AND EXISTS (
               SELECT 1 FROM budget_accounts underserved_budget
               WHERE underserved_budget.project_id = underserved_project.id
                 AND underserved_budget.state = 'active'
             )
             AND EXISTS (
               SELECT 1 FROM project_slots underserved_project_slot
               WHERE underserved_project_slot.project_id = underserved_project.id
             )
             AND EXISTS (
               SELECT 1
               FROM executors underserved_candidate_executor
               JOIN executor_capabilities underserved_capability
                 ON underserved_capability.executor_id = underserved_candidate_executor.id
                AND underserved_capability.capability = underserved_node.required_capability
                AND underserved_capability.scope IN ('global', underserved_project.id)
               JOIN executor_slots underserved_slot
                 ON underserved_slot.executor_id = underserved_candidate_executor.id
                AND underserved_slot.state = 'available'
               WHERE underserved_candidate_executor.pool = 'codex'
                 AND underserved_candidate_executor.state IN ('healthy','degraded')
                 AND underserved_candidate_executor.breaker_state IN ('closed','half_open')
                 AND NOT EXISTS (
                   SELECT 1 FROM attempts occupied_attempt
                   WHERE occupied_attempt.executor_id = underserved_candidate_executor.id
                     AND occupied_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
                 )
             )
             AND NOT EXISTS (
               SELECT 1 FROM attempts underserved_attempt
               JOIN executors underserved_executor
                 ON underserved_executor.id = underserved_attempt.executor_id
                AND underserved_executor.pool = 'codex'
               WHERE underserved_attempt.project_id = underserved_project.id
                 AND underserved_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
             )
             AND EXISTS (
               SELECT 1 FROM attempts candidate_live
               JOIN executors candidate_live_executor
                 ON candidate_live_executor.id = candidate_live.executor_id
                AND candidate_live_executor.pool = 'codex'
               WHERE candidate_live.project_id = candidate.id
                 AND candidate_live.state IN ('created','dispatched','acked','running','result_pending','unknown')
             )
         ))
       ORDER BY
         CASE WHEN NEW.issued_at_ms - COALESCE(
           fairness.waiting_since_ms,
           (SELECT MIN(ready_node.ready_since_ms)
            FROM runs run JOIN node_versions ready_node ON ready_node.run_id = run.id
            WHERE run.project_id = candidate.id AND run.state = 'active'
              AND ready_node.required_pool = NEW.pool AND ready_node.state = 'ready')
         ) >= policy.max_wait_ms THEN 1 ELSE 0 END DESC,
         CASE WHEN NEW.issued_at_ms - COALESCE(
           fairness.waiting_since_ms,
           (SELECT MIN(ready_node.ready_since_ms)
            FROM runs run JOIN node_versions ready_node ON ready_node.run_id = run.id
            WHERE run.project_id = candidate.id AND run.state = 'active'
              AND ready_node.required_pool = NEW.pool AND ready_node.state = 'ready')
         ) >= policy.max_wait_ms THEN COALESCE(
           fairness.waiting_since_ms,
           (SELECT MIN(ready_node.ready_since_ms)
            FROM runs run JOIN node_versions ready_node ON ready_node.run_id = run.id
            WHERE run.project_id = candidate.id AND run.state = 'active'
              AND ready_node.required_pool = NEW.pool AND ready_node.state = 'ready')
         ) END ASC,
         fairness.deficit_units
           + policy.quantum_units * CASE candidate.priority
               WHEN 0 THEN 8 WHEN 1 THEN 4 WHEN 2 THEN 2 ELSE 1 END
           + min(policy.max_deficit_units,
               max(0, NEW.issued_at_ms - COALESCE(
                 fairness.waiting_since_ms,
                 (SELECT MIN(ready_node.ready_since_ms)
                  FROM runs run JOIN node_versions ready_node ON ready_node.run_id = run.id
                  WHERE run.project_id = candidate.id AND run.state = 'active'
                    AND ready_node.required_pool = NEW.pool AND ready_node.state = 'ready')
               )) / policy.aging_threshold_ms * policy.quantum_units) DESC,
         COALESCE(fairness.waiting_since_ms, candidate.updated_at_ms), candidate.id
       LIMIT 1
     )
     OR NEW.executor_id IS NOT (
       SELECT candidate_executor.id
       FROM executors candidate_executor
       WHERE candidate_executor.pool = NEW.pool
         AND candidate_executor.state IN ('healthy','degraded')
         AND candidate_executor.breaker_state IN ('closed','half_open')
         AND EXISTS (
           SELECT 1
           FROM executor_capabilities capability
           JOIN runs eligible_run
             ON eligible_run.project_id = NEW.project_id AND eligible_run.state = 'active'
           JOIN node_versions eligible_node
             ON eligible_node.run_id = eligible_run.id
            AND eligible_node.state = 'ready'
            AND eligible_node.required_pool = NEW.pool
            AND eligible_node.required_capability = capability.capability
           WHERE capability.executor_id = candidate_executor.id
             AND capability.scope IN ('global', NEW.project_id)
         )
         AND (
           (candidate_executor.fresh_session_required = 1 AND EXISTS (
             SELECT 1 FROM executor_slots candidate_slot
             WHERE candidate_slot.executor_id = candidate_executor.id
               AND candidate_slot.state = 'available'
           ) AND NOT EXISTS (
             SELECT 1 FROM attempts live_attempt
             WHERE live_attempt.executor_id = candidate_executor.id
               AND live_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
           ))
           OR (candidate_executor.fresh_session_required = 0 AND EXISTS (
             SELECT 1 FROM project_slots candidate_project_slot
             JOIN runtime_sessions candidate_session
               ON candidate_session.executor_id = candidate_executor.id
              AND candidate_session.project_id = NEW.project_id
              AND candidate_session.project_slot_generation = candidate_project_slot.generation
              AND candidate_session.state = 'running'
             JOIN executor_slots persistent_slot
               ON persistent_slot.executor_id = candidate_executor.id
              AND persistent_slot.state = 'leased'
              AND persistent_slot.fence_counter = candidate_project_slot.owner_fence
             WHERE candidate_project_slot.project_id = NEW.project_id
               AND candidate_project_slot.orchestrator_executor_id = candidate_executor.id
           ))
         )
       ORDER BY candidate_executor.id
       LIMIT 1
     )
     OR NEW.node_version_id IS NOT (
       SELECT ready_node.id
       FROM runs run
       JOIN node_versions ready_node ON ready_node.run_id = run.id
       WHERE run.project_id = NEW.project_id
         AND run.state = 'active'
         AND ready_node.required_pool = NEW.pool
         AND ready_node.state = 'ready'
         AND EXISTS (
           SELECT 1 FROM executor_capabilities capability
           WHERE capability.executor_id = NEW.executor_id
             AND capability.capability = ready_node.required_capability
             AND capability.scope IN ('global', NEW.project_id)
         )
       ORDER BY ready_node.ready_since_ms, ready_node.id
       LIMIT 1
     )
     OR NOT EXISTS (
       SELECT 1
       FROM node_versions node
       JOIN fairness_state fairness
         ON fairness.project_id = NEW.project_id AND fairness.pool = NEW.pool
       JOIN fairness_policies policy
         ON policy.pool = NEW.pool AND policy.policy_digest = NEW.fairness_policy_digest
       JOIN projects project ON project.id = NEW.project_id
       JOIN executors executor ON executor.id = NEW.executor_id AND executor.pool = NEW.pool
       JOIN artifact_manifests snapshot ON snapshot.digest = NEW.candidate_snapshot_digest
       JOIN current_valid_keys snapshot_key
         ON snapshot_key.key_id = snapshot.signer_key_id
        AND snapshot_key.key_purpose = 'artifact_broker'
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE node.id = NEW.node_version_id
         AND node.estimated_cost_units = NEW.estimated_cost_units
         AND fairness.revision = NEW.expected_fairness_revision
         AND fairness.scheduler_epoch = NEW.expected_scheduler_epoch
         AND fairness.leader_term = NEW.leader_term
         AND NEW.winner_score_units = fairness.deficit_units
           + policy.quantum_units * CASE project.priority
               WHEN 0 THEN 8 WHEN 1 THEN 4 WHEN 2 THEN 2 ELSE 1 END
           + min(policy.max_deficit_units,
               max(0, NEW.issued_at_ms - COALESCE(fairness.waiting_since_ms, node.ready_since_ms))
                 / policy.aging_threshold_ms * policy.quantum_units)
         AND json_extract(snapshot.canonical_json, '$.artifact_type') = 'fairness_candidate_snapshot'
         AND json_extract(snapshot.canonical_json, '$.leader_term') = NEW.leader_term
         AND json_extract(snapshot.canonical_json, '$.pool') = NEW.pool
         AND json_extract(snapshot.canonical_json, '$.winner_project_id') = NEW.project_id
         AND json_extract(snapshot.canonical_json, '$.winner_node_version_id') = NEW.node_version_id
         AND json_extract(snapshot.canonical_json, '$.captured_at_ms') BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND control.dispatch_enabled = 1
         AND control.admission_mode = 'open'
         AND control.kill_switch = 0
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = policy.policy_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'fairness_dispatch_permit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

CREATE TRIGGER fairness_dispatch_permits_no_update
BEFORE UPDATE ON fairness_dispatch_permits
BEGIN SELECT RAISE(ABORT, 'fairness dispatch permits are immutable'); END;

CREATE TRIGGER fairness_dispatch_permits_no_delete
BEFORE DELETE ON fairness_dispatch_permits
BEGIN SELECT RAISE(ABORT, 'fairness dispatch permits are immutable'); END;

CREATE TRIGGER attempts_enter_created
BEFORE INSERT ON attempts
WHEN NEW.state <> 'created'
BEGIN SELECT RAISE(ABORT, 'attempts must enter through created'); END;

CREATE TRIGGER attempt_matches_dispatch_authority
BEFORE INSERT ON attempts
BEGIN
  SELECT RAISE(ABORT, 'attempt timestamps are stale or outside the bounded deadline policy')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 60000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000;

  SELECT RAISE(ABORT, 'dispatch requires durable current-term fairness state')
  WHERE NOT EXISTS (
    SELECT 1
    FROM executors executor
    JOIN fairness_state fairness
      ON fairness.project_id = NEW.project_id
     AND fairness.pool = executor.pool
    JOIN fairness_policies policy ON policy.pool = fairness.pool
    JOIN policies signed_policy ON signed_policy.digest = policy.policy_digest
    JOIN current_valid_keys policy_key
      ON policy_key.key_id = signed_policy.signer_key_id
     AND policy_key.key_purpose = 'control_plane'
    WHERE executor.id = NEW.executor_id
      AND fairness.leader_term = NEW.leader_term
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations invalidation
        WHERE invalidation.policy_digest = policy.policy_digest
      )
  );

  SELECT RAISE(ABORT, 'attempt lacks its exact unconsumed deterministic fairness permit')
  WHERE NOT EXISTS (
    SELECT 1
    FROM fairness_dispatch_permits permit
    JOIN executors executor ON executor.id = NEW.executor_id
    JOIN fairness_state fairness
      ON fairness.project_id = NEW.project_id AND fairness.pool = executor.pool
    WHERE permit.digest = NEW.fairness_dispatch_permit_digest
      AND permit.project_id = NEW.project_id
      AND permit.node_version_id = NEW.node_version_id
      AND permit.executor_id = NEW.executor_id
      AND permit.pool = executor.pool
      AND permit.leader_term = NEW.leader_term
      AND permit.estimated_cost_units = (
        SELECT node.estimated_cost_units FROM node_versions node
        WHERE node.id = NEW.node_version_id
      )
      AND permit.expected_fairness_revision = fairness.revision
      AND permit.expected_scheduler_epoch = fairness.scheduler_epoch
      AND permit.issued_at_ms <= NEW.created_at_ms
      AND permit.expires_at_ms >= NEW.created_at_ms
  );

  SELECT RAISE(ABORT, 'a project may hold at most four live Codex attempts')
  WHERE EXISTS (
      SELECT 1 FROM executors selected
      WHERE selected.id = NEW.executor_id AND selected.pool = 'codex'
    )
    AND (
      SELECT COUNT(*)
      FROM attempts live_attempt
      JOIN executors live_executor ON live_executor.id = live_attempt.executor_id
      WHERE live_attempt.project_id = NEW.project_id
        AND live_executor.pool = 'codex'
        AND live_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
    ) >= 4;

  SELECT RAISE(ABORT, 'Codex overflow seat must wait until every ready live project has one seat')
  WHERE EXISTS (
      SELECT 1 FROM executors selected
      WHERE selected.id = NEW.executor_id AND selected.pool = 'codex'
    )
    AND EXISTS (
      SELECT 1
      FROM attempts current_attempt
      JOIN executors current_executor ON current_executor.id = current_attempt.executor_id
      WHERE current_attempt.project_id = NEW.project_id
        AND current_executor.pool = 'codex'
        AND current_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
    )
    AND EXISTS (
      SELECT 1
      FROM projects waiting_project
      JOIN runs waiting_run
        ON waiting_run.project_id = waiting_project.id AND waiting_run.state = 'active'
      JOIN node_versions waiting_node
        ON waiting_node.run_id = waiting_run.id
       AND waiting_node.required_pool = 'codex'
       AND waiting_node.state = 'ready'
      WHERE waiting_project.id <> NEW.project_id
        AND waiting_project.state IN ('admitted','active','blocked')
        AND NOT EXISTS (
          SELECT 1
          FROM attempts waiting_attempt
          JOIN executors waiting_executor ON waiting_executor.id = waiting_attempt.executor_id
          WHERE waiting_attempt.project_id = waiting_project.id
            AND waiting_executor.pool = 'codex'
            AND waiting_attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
        )
    );

  SELECT RAISE(ABORT, 'benchmark attempt run is not bound to its immutable arm execution')
  WHERE EXISTS (
      SELECT 1 FROM runs run
      WHERE run.id = NEW.run_id
        AND run.benchmark_preregistration_digest IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1
      FROM runs run
      JOIN benchmark_arm_runs arm
        ON arm.preregistration_digest = run.benchmark_preregistration_digest
       AND arm.task_id = run.benchmark_task_id
       AND arm.arm = run.benchmark_arm
      JOIN benchmark_arm_run_members member
        ON member.arm_execution_id = arm.arm_execution_id
       AND member.run_id = run.id
       AND member.run_kind = run.run_kind
      WHERE run.id = NEW.run_id
    );

  SELECT RAISE(ABORT, 'benchmark attempt violates the frozen toolchain or aggregate inference ceiling')
  WHERE EXISTS (
      SELECT 1 FROM runs run
      WHERE run.id = NEW.run_id
        AND run.benchmark_preregistration_digest IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1
      FROM runs run
      JOIN benchmark_arm_runs arm
        ON arm.preregistration_digest = run.benchmark_preregistration_digest
       AND arm.task_id = run.benchmark_task_id
       AND arm.arm = run.benchmark_arm
      JOIN benchmark_inference_budgets budget
        ON budget.digest = arm.inference_budget_digest
      JOIN runtime_catalogs catalog ON catalog.digest = NEW.runtime_catalog_digest
      WHERE run.id = NEW.run_id
        AND NOT EXISTS (
          SELECT 1 FROM benchmark_arm_budget_breaches breach
          WHERE breach.arm_execution_id = arm.arm_execution_id
        )
        AND NOT EXISTS (
          SELECT 1 FROM executor_capabilities evaluator_only
          WHERE evaluator_only.executor_id = NEW.executor_id
            AND evaluator_only.capability = 'benchmark-evaluator'
        )
        AND catalog.toolchain_closure_digest = arm.toolchain_closure_digest
        AND 1 + (
          SELECT COUNT(*)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ) <= budget.max_attempts
        AND NEW.max_input_tokens + COALESCE((
          SELECT SUM(prior_attempt.max_input_tokens)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_input_tokens
        AND NEW.max_output_tokens + COALESCE((
          SELECT SUM(prior_attempt.max_output_tokens)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_output_tokens
        AND NEW.max_cache_read_tokens + COALESCE((
          SELECT SUM(prior_attempt.max_cache_read_tokens)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_cache_read_tokens
        AND NEW.max_cache_write_tokens + COALESCE((
          SELECT SUM(prior_attempt.max_cache_write_tokens)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_cache_write_tokens
        AND NEW.max_tool_calls + COALESCE((
          SELECT SUM(prior_attempt.max_tool_calls)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_tool_calls
        AND NEW.max_wall_time_ms + COALESCE((
          SELECT SUM(prior_attempt.max_wall_time_ms)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_wall_time_ms
        AND NEW.required_reservation_micro_usd + COALESCE((
          SELECT SUM(prior_attempt.required_reservation_micro_usd)
          FROM attempts prior_attempt
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_cost_micro_usd
    );

  SELECT RAISE(ABORT, 'attempt does not match node/run/project/slot/term authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions nv
    JOIN logical_nodes ln ON ln.id = nv.logical_node_id
    JOIN runs r ON r.id = nv.run_id
    JOIN policies np ON np.digest = nv.policy_digest
    JOIN signing_keys nsk ON nsk.key_id = np.signer_key_id
    JOIN policies rpp ON rpp.digest = r.pipeline_policy_digest
    JOIN signing_keys rpsk ON rpsk.key_id = rpp.signer_key_id
    JOIN projects p ON p.id = ln.project_id
    JOIN project_slots ps ON ps.slot_no = NEW.project_slot_no
    JOIN executor_slots es ON es.id = NEW.executor_slot_id
    JOIN executors e ON e.id = NEW.executor_id
    JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
    JOIN pricing_catalogs pc ON pc.digest = NEW.pricing_catalog_digest
    JOIN signing_keys psk ON psk.key_id = pc.signer_key_id
    JOIN principals ep ON ep.id = e.principal_id
    JOIN leader_terms lt ON lt.term = NEW.leader_term
    JOIN control_state cs ON cs.singleton = 1
    WHERE nv.id = NEW.node_version_id
      AND nv.run_id = NEW.run_id
      AND nv.state = 'ready'
      AND ln.project_id = NEW.project_id
      AND p.state IN ('admitted','active')
      AND r.project_id = NEW.project_id
      AND r.state = 'active'
      AND r.project_slot_no = NEW.project_slot_no
      AND r.project_slot_generation = NEW.project_slot_generation
      AND nsk.state = 'active'
      AND (nsk.expires_at_ms IS NULL OR nsk.expires_at_ms >= NEW.created_at_ms)
      AND rpsk.state = 'active'
      AND (rpsk.expires_at_ms IS NULL OR rpsk.expires_at_ms >= NEW.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest IN (nv.policy_digest, r.pipeline_policy_digest)
      )
      AND ps.project_id = NEW.project_id
      AND ps.generation = NEW.project_slot_generation
      AND es.executor_id = NEW.executor_id
      AND es.state = 'leased'
      AND es.fence_counter = NEW.fence
      AND e.pool = nv.required_pool
      AND ep.state = 'active'
      AND EXISTS (
        SELECT 1 FROM executor_capabilities ec
        WHERE ec.executor_id = e.id
          AND ec.capability = nv.required_capability
          AND ec.scope IN ('global', NEW.project_id)
      )
      AND e.state IN ('healthy','degraded')
      AND e.breaker_state IN ('closed','half_open')
      AND e.runtime = NEW.runtime
      AND e.requested_model = NEW.requested_model
      AND e.requested_profile = NEW.requested_profile
      AND e.runtime_catalog_digest = NEW.runtime_catalog_digest
      AND e.model = NEW.model
      AND e.model_family = NEW.model_family
      AND e.profile = NEW.profile
      AND rc.provider = pc.provider
      AND rc.resolved_model = pc.model
      AND pc.model = NEW.model
      AND pc.effective_at_ms <= NEW.created_at_ms
      AND psk.state = 'active'
      AND (psk.expires_at_ms IS NULL OR psk.expires_at_ms >= NEW.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM pricing_catalog_invalidations pci
        WHERE pci.pricing_catalog_digest = pc.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM pricing_catalogs newer
        WHERE newer.provider = pc.provider
          AND newer.model = pc.model
          AND newer.effective_at_ms > pc.effective_at_ms
          AND newer.effective_at_ms <= NEW.created_at_ms
          AND NOT EXISTS (
            SELECT 1 FROM pricing_catalog_invalidations npi
            WHERE npi.pricing_catalog_digest = newer.digest
          )
      )
      AND NEW.max_input_tokens + NEW.max_output_tokens <= 2000000
      AND NEW.required_reservation_micro_usd = (
        NEW.max_input_tokens * pc.input_rate_per_million
        + NEW.max_output_tokens * pc.output_rate_per_million
        + NEW.max_cache_read_tokens * pc.cache_read_rate_per_million
        + NEW.max_cache_write_tokens * pc.cache_write_rate_per_million
        + NEW.max_tool_calls * pc.tool_call_rate_per_million
        + NEW.max_wall_time_ms * pc.millisecond_rate_per_million
        + 999999
      ) / 1000000
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = NEW.runtime_catalog_digest
      )
      AND EXISTS (
        SELECT 1
        FROM runtime_catalogs rc
        JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
        WHERE rc.digest = NEW.runtime_catalog_digest
          AND rc.effective_at_ms <= NEW.created_at_ms
          AND rsk.state = 'active'
          AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= NEW.created_at_ms)
      )
      AND lt.state = 'active'
      AND cs.current_term = NEW.leader_term
      AND cs.dispatch_enabled = 1
      AND cs.admission_mode = 'open'
      AND cs.kill_switch = 0
      AND NEW.attempt_no <= nv.retry_limit + 1
      AND NEW.input_manifest_digest = nv.input_manifest_digest
  );

  SELECT RAISE(ABORT, 'attempt fence is not valid for the executor lifecycle')
  WHERE EXISTS (
      SELECT 1 FROM executors e
      WHERE e.id = NEW.executor_id
        AND e.fresh_session_required = 1
        AND NEW.fence <= COALESCE(
          (SELECT MAX(fence) FROM attempts WHERE executor_slot_id = NEW.executor_slot_id),
          0
        )
    )
    OR EXISTS (
      SELECT 1 FROM executors e
      WHERE e.id = NEW.executor_id
        AND e.fresh_session_required = 0
        AND NOT EXISTS (
          SELECT 1
          FROM runtime_sessions rs
          JOIN runtime_intents ri ON ri.id = rs.runtime_intent_id
          JOIN project_slots ps
            ON ps.slot_no = NEW.project_slot_no
           AND ps.project_id = NEW.project_id
           AND ps.generation = NEW.project_slot_generation
           AND ps.orchestrator_executor_id = NEW.executor_id
          WHERE rs.executor_id = NEW.executor_id
            AND rs.executor_slot_id = NEW.executor_slot_id
            AND rs.project_id = NEW.project_id
            AND rs.project_slot_no = NEW.project_slot_no
            AND rs.project_slot_generation = NEW.project_slot_generation
            AND rs.state = 'running'
            AND ri.state = 'launched'
            AND ri.fence = NEW.fence
        )
    );
END;

CREATE TRIGGER failover_authorization_is_exact_before_replacement
BEFORE INSERT ON failover_authorizations
BEGIN
  SELECT RAISE(ABORT, 'failover authorization is not exact, current, or pre-staged before replacement')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR json_type(NEW.dependencies_json) <> 'array'
     OR EXISTS (
       SELECT 1
       FROM json_each(NEW.dependencies_json) dependency
       WHERE json_type(dependency.value) <> 'object'
          OR json_type(dependency.value, '$.depends_on_node_version_id') <> 'text'
          OR json_type(dependency.value, '$.dependency_type') <> 'text'
          OR json_extract(dependency.value, '$.dependency_type')
               NOT IN ('hard','artifact','review','approval','merge')
          OR EXISTS (
            SELECT 1 FROM json_each(dependency.value) field
            WHERE field.key NOT IN ('depends_on_node_version_id','dependency_type')
          )
     )
     OR EXISTS (
       SELECT 1
       FROM json_each(NEW.dependencies_json) dependency
       GROUP BY json_extract(dependency.value, '$.depends_on_node_version_id'),
                json_extract(dependency.value, '$.dependency_type')
       HAVING COUNT(*) > 1
     )
     OR EXISTS (SELECT 1 FROM node_versions existing WHERE existing.id = NEW.to_node_version_id)
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.from_node_version_id') IS NOT NEW.from_node_version_id
     OR json_extract(NEW.canonical_json, '$.to_node_version_id') IS NOT NEW.to_node_version_id
     OR json_extract(NEW.canonical_json, '$.logical_node_id') IS NOT NEW.logical_node_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.version_no') IS NOT NEW.version_no
     OR json_extract(NEW.canonical_json, '$.stage') IS NOT NEW.stage
     OR json_extract(NEW.canonical_json, '$.role') IS NOT NEW.role
     OR json_extract(NEW.canonical_json, '$.fallback_pool') IS NOT NEW.fallback_pool
     OR json_extract(NEW.canonical_json, '$.fallback_capability') IS NOT NEW.fallback_capability
     OR json_extract(NEW.canonical_json, '$.output_schema_digest') IS NOT NEW.output_schema_digest
     OR json_extract(NEW.canonical_json, '$.policy_digest') IS NOT NEW.policy_digest
     OR json_extract(NEW.canonical_json, '$.retry_limit') IS NOT NEW.retry_limit
     OR json_extract(NEW.canonical_json, '$.estimated_cost_units') IS NOT NEW.estimated_cost_units
     OR json_extract(NEW.canonical_json, '$.dependencies_json') IS NOT NEW.dependencies_json
     OR json_extract(NEW.canonical_json, '$.reason_code') IS NOT NEW.reason_code
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.provider_observation_id') IS NOT NEW.provider_observation_id
     OR json_extract(NEW.canonical_json, '$.host_capacity_revision') IS NOT NEW.host_capacity_revision
     OR json_extract(NEW.canonical_json, '$.required_resource_profile_digest') IS NOT NEW.required_resource_profile_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.project_slot_no') IS NOT NEW.project_slot_no
     OR json_extract(NEW.canonical_json, '$.project_slot_generation') IS NOT NEW.project_slot_generation
     OR json_extract(NEW.canonical_json, '$.owner_fence') IS NOT NEW.owner_fence
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR EXISTS (
       SELECT 1 FROM runs benchmark_run
       WHERE benchmark_run.id = NEW.run_id
         AND benchmark_run.benchmark_preregistration_digest IS NOT NULL
     )
     OR NOT EXISTS (
       SELECT 1
       FROM node_versions old
       JOIN runs run ON run.id = old.run_id
       JOIN project_slots project_slot
         ON project_slot.slot_no = run.project_slot_no
        AND project_slot.project_id = run.project_id
        AND project_slot.generation = run.project_slot_generation
       JOIN executor_slots owner_slot
         ON owner_slot.executor_id = project_slot.orchestrator_executor_id
        AND owner_slot.fence_counter = project_slot.owner_fence
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys control_key
         ON control_key.key_id = NEW.signer_key_id
        AND control_key.principal_id = NEW.signer_principal_id
        AND control_key.key_purpose = 'control_plane'
       JOIN principals signer
         ON signer.id = NEW.signer_principal_id
        AND signer.kind = 'service'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE old.id = NEW.from_node_version_id
         AND old.logical_node_id = NEW.logical_node_id
         AND old.run_id = NEW.run_id
         AND run.state = 'active'
         AND run.project_slot_no = NEW.project_slot_no
         AND run.project_slot_generation = NEW.project_slot_generation
         AND project_slot.owner_fence = NEW.owner_fence
         AND owner_slot.state = 'leased'
         AND control.dispatch_enabled = 1
         AND control.admission_mode = 'open'
         AND control.kill_switch = 0
         AND old.state IN ('ready','dispatched','failed')
         AND NEW.version_no = old.version_no + 1
         AND NEW.stage = old.stage
         AND NEW.role = old.role
         AND NEW.output_schema_digest = old.output_schema_digest
         AND NEW.policy_digest = old.policy_digest
         AND NEW.retry_limit = old.retry_limit
         AND NEW.estimated_cost_units = old.estimated_cost_units
         AND (NEW.fallback_pool <> old.required_pool
              OR NEW.fallback_capability <> old.required_capability)
         AND NEW.fallback_capability NOT IN ('final-review-only','benchmark-evaluator')
         AND EXISTS (
           SELECT 1
           FROM executors fallback_executor
           JOIN executor_capabilities fallback_capability
             ON fallback_capability.executor_id = fallback_executor.id
           WHERE fallback_executor.pool = NEW.fallback_pool
             AND fallback_capability.capability = NEW.fallback_capability
             AND fallback_capability.scope IN ('global', run.project_id)
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = NEW.policy_digest
         )
         AND EXISTS (
           SELECT 1 FROM policies policy
           JOIN json_each(policy.canonical_json, '$.failover_map') mapping
           WHERE policy.digest = NEW.policy_digest
             AND json_extract(mapping.value, '$.from_pool') = old.required_pool
             AND json_extract(mapping.value, '$.from_capability') = old.required_capability
             AND json_extract(mapping.value, '$.reason_code') = NEW.reason_code
             AND json_extract(mapping.value, '$.fallback_pool') = NEW.fallback_pool
             AND json_extract(mapping.value, '$.fallback_capability') = NEW.fallback_capability
             AND NEW.version_no <= json_extract(mapping.value, '$.max_version_no')
         )
         AND (
           (NEW.reason_code IN ('provider_outage','breaker_open') AND EXISTS (
             SELECT 1
             FROM provider_health_observations observation
             JOIN attempts failed_attempt ON failed_attempt.id = old.current_attempt_id
             JOIN runtime_catalogs failed_catalog
               ON failed_catalog.digest = failed_attempt.runtime_catalog_digest
             JOIN executors failed_executor ON failed_executor.id = failed_attempt.executor_id
             WHERE observation.id = NEW.provider_observation_id
               AND observation.provider = failed_catalog.provider
               AND observation.model_family = failed_attempt.model_family
               AND observation.breaker_epoch = failed_executor.health_epoch
               AND observation.observed_state = CASE NEW.reason_code
                 WHEN 'provider_outage' THEN 'outage' ELSE 'breaker_open' END
               AND observation.observed_at_ms <= NEW.created_at_ms
               AND observation.expires_at_ms >= NEW.expires_at_ms
           ))
           OR (NEW.reason_code = 'capacity_exhausted' AND EXISTS (
             SELECT 1 FROM host_capacity capacity
             WHERE capacity.singleton = 1
               AND capacity.revision = NEW.host_capacity_revision
               AND capacity.measurement_at_ms >= NEW.created_at_ms - 60000
               AND EXISTS (
                 SELECT 1 FROM resource_profiles required_profile
                 WHERE required_profile.digest = NEW.required_resource_profile_digest
                   AND required_profile.pool = old.required_pool
                   AND required_profile.profile_name = CASE old.required_pool
                     WHEN 'fable' THEN 'fable_active_call'
                     WHEN 'codex' THEN 'codex_fresh_process'
                     ELSE 'opus_fresh_process' END
                   AND required_profile.host_policy_digest = capacity.resource_policy_digest
                   AND NOT EXISTS (
                     SELECT 1 FROM policy_invalidations invalidation
                     WHERE invalidation.policy_digest IN (
                       required_profile.digest, required_profile.host_policy_digest
                     )
                   )
                   AND (
                     capacity.measured_free_disk_bytes - capacity.reserved_disk_bytes
                       - capacity.emergency_reserve_bytes - capacity.clone_log_allowance_bytes
                       < required_profile.disk_bytes
                     OR capacity.measured_available_ram_bytes - capacity.reserved_rss_bytes
                       - capacity.emergency_ram_bytes < required_profile.rss_bytes
                     OR capacity.max_model_pid_count - capacity.reserved_pid_count
                       < required_profile.pid_count
                     OR capacity.max_model_fd_count - capacity.reserved_fd_count
                       < required_profile.fd_count
                     OR capacity.max_model_cpu_millis - capacity.reserved_cpu_millis
                       < required_profile.cpu_millis
                   )
               )
           ))
           OR NEW.reason_code = 'policy_fallback'
           OR (NEW.reason_code = 'deadline_exhausted' AND EXISTS (
             SELECT 1 FROM attempts expired_attempt
             WHERE expired_attempt.id = old.current_attempt_id
               AND expired_attempt.hard_deadline_ms <= NEW.created_at_ms
               AND expired_attempt.state IN ('failed','expired','stale','unknown')
           ))
         )
         AND json_extract(evidence.canonical_json, '$.artifact_type') = 'failover_evidence'
         AND json_extract(evidence.canonical_json, '$.from_node_version_id') = NEW.from_node_version_id
         AND json_extract(evidence.canonical_json, '$.reason_code') = NEW.reason_code
         AND json_extract(evidence.canonical_json, '$.leader_term') = NEW.leader_term
         AND NOT EXISTS (
           SELECT 1
           FROM node_dependencies old_dependency
           WHERE old_dependency.node_version_id = old.id
             AND NOT EXISTS (
               SELECT 1 FROM json_each(NEW.dependencies_json) dependency
               WHERE json_extract(dependency.value, '$.depends_on_node_version_id')
                       = old_dependency.depends_on_node_version_id
                 AND json_extract(dependency.value, '$.dependency_type')
                       = old_dependency.dependency_type
             )
         )
         AND NOT EXISTS (
           SELECT 1
           FROM json_each(NEW.dependencies_json) dependency
           WHERE json_extract(dependency.value, '$.dependency_type')
                   NOT IN ('hard','artifact','review','approval','merge')
              OR NOT EXISTS (
                SELECT 1 FROM node_versions parent
                WHERE parent.id = json_extract(dependency.value, '$.depends_on_node_version_id')
                  AND parent.run_id = NEW.run_id
              )
         )
         AND NOT EXISTS (
           SELECT 1
           FROM json_each(NEW.dependencies_json) dependency
           WHERE NOT EXISTS (
             SELECT 1 FROM node_dependencies old_dependency
             WHERE old_dependency.node_version_id = old.id
               AND old_dependency.depends_on_node_version_id
                     = json_extract(dependency.value, '$.depends_on_node_version_id')
               AND old_dependency.dependency_type
                     = json_extract(dependency.value, '$.dependency_type')
           )
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'failover_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER failover_authorizations_no_update
BEFORE UPDATE ON failover_authorizations
BEGIN SELECT RAISE(ABORT, 'failover authorizations are immutable'); END;

CREATE TRIGGER failover_authorizations_no_delete
BEFORE DELETE ON failover_authorizations
BEGIN SELECT RAISE(ABORT, 'failover authorizations are immutable'); END;

CREATE TRIGGER failover_decision_matches_superseding_version
BEFORE INSERT ON failover_decisions
BEGIN
  SELECT RAISE(ABORT, 'failover must target a contiguous superseding version')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions old
    JOIN node_versions next
      ON next.logical_node_id = old.logical_node_id
     AND next.run_id = old.run_id
     AND next.version_no = old.version_no + 1
    JOIN failover_authorizations authorization
      ON authorization.digest = NEW.authorization_digest
     AND authorization.from_node_version_id = old.id
     AND authorization.to_node_version_id = next.id
    JOIN leader_terms term ON term.term = authorization.leader_term AND term.state = 'active'
    JOIN control_state control ON control.current_term = authorization.leader_term
    JOIN project_slots project_slot
      ON project_slot.slot_no = authorization.project_slot_no
     AND project_slot.project_id = (SELECT run.project_id FROM runs run WHERE run.id = authorization.run_id)
     AND project_slot.generation = authorization.project_slot_generation
     AND project_slot.owner_fence = authorization.owner_fence
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.principal_id = NEW.signer_principal_id
     AND sk.key_purpose = 'control_plane'
    JOIN principals signer
      ON signer.id = NEW.signer_principal_id
     AND signer.kind = 'service'
    JOIN artifact_manifests evidence
      ON evidence.digest = NEW.evidence_manifest_digest
    JOIN current_valid_keys evidence_key
      ON evidence_key.key_id = evidence.signer_key_id
     AND evidence_key.key_purpose = 'artifact_broker'
    WHERE old.id = NEW.from_node_version_id
      AND next.id = NEW.to_node_version_id
      AND old.state IN ('ready','dispatched','failed')
      AND next.state = 'pending'
      AND next.required_pool = NEW.fallback_pool
      AND next.required_capability = NEW.fallback_capability
      AND authorization.fallback_pool = NEW.fallback_pool
      AND authorization.fallback_capability = NEW.fallback_capability
      AND authorization.reason_code = NEW.reason_code
      AND authorization.policy_digest = NEW.policy_digest
      AND authorization.stage = next.stage
      AND authorization.role = next.role
      AND authorization.output_schema_digest = next.output_schema_digest
      AND authorization.retry_limit = next.retry_limit
      AND authorization.estimated_cost_units = next.estimated_cost_units
      AND authorization.evidence_manifest_digest = NEW.evidence_manifest_digest
      AND authorization.provider_observation_id IS NEW.provider_observation_id
      AND authorization.host_capacity_revision IS NEW.host_capacity_revision
      AND authorization.required_resource_profile_digest IS NEW.required_resource_profile_digest
      AND authorization.leader_term = NEW.leader_term
      AND authorization.project_slot_no = NEW.project_slot_no
      AND authorization.project_slot_generation = NEW.project_slot_generation
      AND authorization.owner_fence = NEW.owner_fence
      AND authorization.created_at_ms <= NEW.created_at_ms
      AND authorization.expires_at_ms >= NEW.created_at_ms
      AND control.dispatch_enabled = 1
      AND control.admission_mode = 'open'
      AND control.kill_switch = 0
      AND NOT EXISTS (
        SELECT 1
        FROM json_each(authorization.dependencies_json) dependency
        WHERE NOT EXISTS (
          SELECT 1 FROM node_dependencies materialized
          WHERE materialized.node_version_id = next.id
            AND materialized.depends_on_node_version_id
                  = json_extract(dependency.value, '$.depends_on_node_version_id')
            AND materialized.dependency_type
                  = json_extract(dependency.value, '$.dependency_type')
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM node_dependencies materialized
        WHERE materialized.node_version_id = next.id
          AND NOT EXISTS (
            SELECT 1 FROM json_each(authorization.dependencies_json) dependency
            WHERE json_extract(dependency.value, '$.depends_on_node_version_id')
                    = materialized.depends_on_node_version_id
              AND json_extract(dependency.value, '$.dependency_type')
                    = materialized.dependency_type
          )
      )
      AND json_extract(NEW.canonical_json, '$.id') = NEW.id
      AND json_extract(NEW.canonical_json, '$.authorization_digest') = NEW.authorization_digest
      AND json_extract(NEW.canonical_json, '$.from_node_version_id') = NEW.from_node_version_id
      AND json_extract(NEW.canonical_json, '$.to_node_version_id') = NEW.to_node_version_id
      AND json_extract(NEW.canonical_json, '$.fallback_pool') = NEW.fallback_pool
      AND json_extract(NEW.canonical_json, '$.fallback_capability') = NEW.fallback_capability
      AND json_extract(NEW.canonical_json, '$.reason_code') = NEW.reason_code
      AND json_extract(NEW.canonical_json, '$.policy_digest') = NEW.policy_digest
      AND json_extract(NEW.canonical_json, '$.evidence_manifest_digest') = NEW.evidence_manifest_digest
      AND json_extract(NEW.canonical_json, '$.provider_observation_id') IS NEW.provider_observation_id
      AND json_extract(NEW.canonical_json, '$.host_capacity_revision') IS NEW.host_capacity_revision
      AND json_extract(NEW.canonical_json, '$.required_resource_profile_digest') IS NEW.required_resource_profile_digest
      AND json_extract(NEW.canonical_json, '$.leader_term') = NEW.leader_term
      AND json_extract(NEW.canonical_json, '$.project_slot_no') = NEW.project_slot_no
      AND json_extract(NEW.canonical_json, '$.project_slot_generation') = NEW.project_slot_generation
      AND json_extract(NEW.canonical_json, '$.owner_fence') = NEW.owner_fence
      AND json_extract(NEW.canonical_json, '$.signer_principal_id') = NEW.signer_principal_id
      AND json_extract(NEW.canonical_json, '$.signer_key_id') = NEW.signer_key_id
      AND json_extract(NEW.canonical_json, '$.created_at_ms') = NEW.created_at_ms
      AND NEW.created_at_ms BETWEEN (unixepoch('subsec') * 1000) - 5000
                                AND (unixepoch('subsec') * 1000) + 5000
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = NEW.policy_digest
      )
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'failover_decision'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.id
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER node_supersede_requires_staged_failover_decision
BEFORE UPDATE OF state ON node_versions
WHEN NEW.state = 'superseded' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'supersession requires a staged signed replacement decision')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions next
    JOIN failover_decisions decision
      ON decision.from_node_version_id = NEW.id
     AND decision.to_node_version_id = next.id
     AND decision.fallback_pool = next.required_pool
     AND decision.fallback_capability = next.required_capability
    JOIN failover_authorizations authorization
      ON authorization.digest = decision.authorization_digest
    JOIN leader_terms term ON term.term = decision.leader_term AND term.state = 'active'
    JOIN control_state control ON control.current_term = decision.leader_term
    JOIN project_slots slot
      ON slot.slot_no = decision.project_slot_no
     AND slot.generation = decision.project_slot_generation
     AND slot.owner_fence = decision.owner_fence
    WHERE next.logical_node_id = NEW.logical_node_id
      AND next.run_id = NEW.run_id
      AND next.version_no = NEW.version_no + 1
      AND slot.project_id = (SELECT run.project_id FROM runs run WHERE run.id = NEW.run_id)
      AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
      AND control.dispatch_enabled = 1
      AND control.admission_mode = 'open'
      AND control.kill_switch = 0
  );
END;

CREATE TRIGGER node_ready_requires_failover_authority
BEFORE UPDATE OF state ON node_versions
WHEN OLD.state = 'pending' AND NEW.state = 'ready' AND NEW.version_no > 1
BEGIN
  SELECT RAISE(ABORT, 'fallback node cannot become ready without current signed failover authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions prior
    JOIN failover_decisions decision
      ON decision.from_node_version_id = prior.id
     AND decision.to_node_version_id = NEW.id
     AND decision.fallback_pool = NEW.required_pool
     AND decision.fallback_capability = NEW.required_capability
    JOIN failover_authorizations authorization
      ON authorization.digest = decision.authorization_digest
    JOIN leader_terms term ON term.term = decision.leader_term AND term.state = 'active'
    JOIN control_state control ON control.current_term = decision.leader_term
    JOIN project_slots slot
      ON slot.slot_no = decision.project_slot_no
     AND slot.generation = decision.project_slot_generation
     AND slot.owner_fence = decision.owner_fence
    JOIN current_valid_keys key
      ON key.key_id = decision.signer_key_id
     AND key.principal_id = decision.signer_principal_id
     AND key.key_purpose = 'control_plane'
    WHERE prior.logical_node_id = NEW.logical_node_id
      AND prior.run_id = NEW.run_id
      AND prior.version_no = NEW.version_no - 1
      AND prior.state IN ('superseded','failed')
      AND slot.project_id = (SELECT run.project_id FROM runs run WHERE run.id = NEW.run_id)
      AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
      AND control.dispatch_enabled = 1
      AND control.admission_mode = 'open'
      AND control.kill_switch = 0
      AND NOT EXISTS (
        SELECT 1 FROM attempts attempt
        WHERE attempt.node_version_id = prior.id
          AND attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations invalidation
        WHERE invalidation.policy_digest = decision.policy_digest
      )
  );
END;

CREATE TRIGGER leases_enter_active
BEFORE INSERT ON leases
WHEN NEW.state <> 'active'
BEGIN SELECT RAISE(ABORT, 'leases must enter through active'); END;

CREATE TRIGGER lease_matches_current_authority
BEFORE INSERT ON leases
BEGIN
  SELECT RAISE(ABORT, 'lease does not match current slot/attempt/term authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN node_versions node ON node.id = a.node_version_id
    JOIN executors executor ON executor.id = a.executor_id
    JOIN executor_slots es ON es.id = a.executor_slot_id
    JOIN leader_terms lt ON lt.term = a.leader_term
    JOIN control_state cs ON cs.singleton = 1
    WHERE a.id = NEW.attempt_id
      AND (
        a.state = 'dispatched'
        OR (a.state = 'created'
          AND node.state = 'ready'
          AND EXISTS (
            SELECT 1 FROM fairness_dispatch_permits permit
            WHERE permit.digest = a.fairness_dispatch_permit_digest
              AND permit.node_version_id = node.id
              AND permit.expires_at_ms >= NEW.acquired_at_ms
          ))
      )
      AND a.executor_slot_id = NEW.executor_slot_id
      AND a.fence = NEW.fence
      AND a.leader_term = NEW.leader_term
      AND es.state = 'leased'
      AND es.fence_counter = NEW.fence
      AND lt.state = 'active'
      AND cs.current_term = NEW.leader_term
      AND cs.dispatch_enabled = 1
      AND cs.admission_mode = 'open'
      AND cs.kill_switch = 0
      AND NEW.heartbeat_seq = 0
      AND NEW.released_at_ms IS NULL
      AND NEW.acquired_at_ms >= a.created_at_ms
      AND NEW.acquired_at_ms <= (unixepoch('subsec') * 1000) + 5000
      AND NEW.expires_at_ms > NEW.acquired_at_ms
      AND NEW.expires_at_ms <= a.lease_deadline_ms
      AND NEW.expires_at_ms <= a.hard_deadline_ms
      AND (
        executor.fresh_session_required = 1
        OR (executor.fresh_session_required = 0 AND EXISTS (
          SELECT 1 FROM runtime_sessions session
          WHERE session.executor_id = a.executor_id
            AND session.project_id = a.project_id
            AND session.project_slot_no = a.project_slot_no
            AND session.project_slot_generation = a.project_slot_generation
            AND session.worker_instance_id = NEW.worker_instance_id
            AND session.state = 'running'
        ))
      )
  );
END;

CREATE TRIGGER budget_reservations_enter_held
BEFORE INSERT ON budget_reservations
WHEN NEW.state <> 'held'
  OR NEW.consumed_micro_usd <> 0
  OR NEW.closed_at_ms IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'budget reservations must enter pristine through held'); END;

CREATE TRIGGER budget_ledger_entries_are_exact_domain_projections
BEFORE INSERT ON budget_ledger
BEGIN
  SELECT RAISE(ABORT, 'budget ledger row is not an exact domain projection')
  WHERE NOT (
    (NEW.entry_type = 'reserve' AND NEW.usage_event_id IS NULL AND EXISTS (
      SELECT 1 FROM budget_reservations reservation
      WHERE reservation.id = NEW.reservation_id
        AND NEW.id = 'reserve:' || reservation.id
        AND NEW.budget_account_id = reservation.budget_account_id
        AND NEW.delta_reserved_micro_usd = reservation.amount_micro_usd
        AND NEW.delta_spent_micro_usd = 0
        AND NEW.source_key = 'reserve:' || reservation.id
        AND NEW.created_at_ms = reservation.created_at_ms
    ))
    OR
    (NEW.entry_type = 'spend' AND EXISTS (
      SELECT 1
      FROM usage_events usage
      JOIN budget_reservations reservation ON reservation.id = usage.reservation_id
      WHERE usage.id = NEW.usage_event_id
        AND reservation.id = NEW.reservation_id
        AND NEW.id = 'usage:' || usage.id
        AND NEW.budget_account_id = reservation.budget_account_id
        AND NEW.delta_reserved_micro_usd = -CASE
          WHEN reservation.closed_at_ms IS NOT NULL THEN 0
          WHEN usage.final_marker = 1
            THEN max(reservation.amount_micro_usd - reservation.consumed_micro_usd, 0)
          ELSE min(usage.delta_micro_usd,
                   max(reservation.amount_micro_usd - reservation.consumed_micro_usd, 0))
        END
        AND NEW.delta_spent_micro_usd = usage.delta_micro_usd
        AND NEW.source_key = 'usage:' || usage.id
        AND NEW.created_at_ms = usage.observed_at_ms
    ))
    OR
    (NEW.entry_type = 'release' AND NEW.usage_event_id IS NULL AND EXISTS (
      SELECT 1 FROM budget_reservations reservation
      WHERE reservation.id = NEW.reservation_id
        AND reservation.state = 'released'
        AND NEW.id = 'release:' || reservation.id
        AND NEW.budget_account_id = reservation.budget_account_id
        AND NEW.delta_reserved_micro_usd =
            -max(reservation.amount_micro_usd - reservation.consumed_micro_usd, 0)
        AND NEW.delta_spent_micro_usd = 0
        AND NEW.source_key = 'release:' || reservation.id
        AND NEW.created_at_ms = reservation.closed_at_ms
    ))
  );
END;

CREATE TRIGGER charge_subject_matches_scope
BEFORE INSERT ON charge_subjects
BEGIN
  SELECT RAISE(ABORT, 'attempt charge subject does not match its project')
  WHERE NEW.scope_kind = 'attempt'
    AND NOT EXISTS (
      SELECT 1
      FROM attempts a
      JOIN runtime_catalogs rc ON rc.digest = a.runtime_catalog_digest
      WHERE a.id = NEW.attempt_id
        AND a.project_id = NEW.project_id
        AND rc.provider = NEW.billing_provider
        AND rc.resolved_model = NEW.billing_model
    );

  SELECT RAISE(ABORT, 'portfolio runtime charge subject must identify F0 prelaunch intent')
  WHERE NEW.scope_kind = 'portfolio_runtime'
    AND NOT EXISTS (
      SELECT 1
      FROM runtime_intents ri
      JOIN runtime_catalogs rc ON rc.digest = ri.runtime_catalog_digest
      WHERE ri.id = NEW.runtime_intent_id
        AND ri.executor_id = 'rick'
        AND ri.session_scope = 'portfolio'
        AND ri.state = 'prepared'
        AND rc.provider = NEW.billing_provider
        AND rc.resolved_model = NEW.billing_model
    );

  SELECT RAISE(ABORT, 'project runtime charge subject must match a Fable project-generation intent')
  WHERE NEW.scope_kind = 'project_runtime'
    AND NOT EXISTS (
      SELECT 1
      FROM runtime_intents ri
      JOIN executors e ON e.id = ri.executor_id
      JOIN runtime_catalogs rc ON rc.digest = ri.runtime_catalog_digest
      WHERE ri.id = NEW.runtime_intent_id
        AND ri.project_id = NEW.project_id
        AND ri.session_scope = 'project_generation'
        AND ri.state = 'prepared'
        AND e.pool = 'fable'
        AND e.id <> 'rick'
        AND rc.provider = NEW.billing_provider
        AND rc.resolved_model = NEW.billing_model
    );

  SELECT RAISE(ABORT, 'service-operation charge subject requires a known billable provider/model')
  WHERE NEW.scope_kind = 'service_operation'
    AND NOT EXISTS (
      SELECT 1 FROM runtime_catalogs rc
      WHERE rc.provider = NEW.billing_provider
        AND rc.resolved_model = NEW.billing_model
        AND NOT EXISTS (
          SELECT 1 FROM runtime_catalog_invalidations rci
          WHERE rci.runtime_catalog_digest = rc.digest
        )
    );
END;

CREATE TRIGGER budget_reservation_matches_charge_scope
BEFORE INSERT ON budget_reservations
BEGIN
  SELECT RAISE(ABORT, 'reservation number must be contiguous for charge subject')
  WHERE NEW.reservation_no <> (
    SELECT COALESCE(MAX(reservation_no), 0) + 1
    FROM budget_reservations
    WHERE charge_subject_id = NEW.charge_subject_id
  );

  SELECT RAISE(ABORT, 'settled benchmark arm cannot create another budget reservation')
  WHERE EXISTS (
    SELECT 1
    FROM charge_subjects subject
    JOIN attempts attempt ON attempt.id = subject.attempt_id
    JOIN benchmark_arm_run_members member ON member.run_id = attempt.run_id
    JOIN benchmark_arm_settlement_seals settlement
      ON settlement.arm_execution_id = member.arm_execution_id
    WHERE subject.id = NEW.charge_subject_id
      AND subject.scope_kind = 'attempt'
  );

  SELECT RAISE(ABORT, 'reservation account does not match charge subject scope')
  WHERE NOT EXISTS (
    SELECT 1
    FROM charge_subjects cs
    JOIN budget_accounts ba ON ba.id = NEW.budget_account_id
    JOIN pricing_catalogs pc ON pc.digest = NEW.pricing_catalog_digest
    JOIN signing_keys psk ON psk.key_id = pc.signer_key_id
    WHERE cs.id = NEW.charge_subject_id
      AND ba.state = 'active'
      AND pc.provider = cs.billing_provider
      AND pc.model = cs.billing_model
      AND pc.effective_at_ms <= NEW.created_at_ms
      AND psk.state = 'active'
      AND (psk.expires_at_ms IS NULL OR psk.expires_at_ms >= NEW.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM pricing_catalog_invalidations pci
        WHERE pci.pricing_catalog_digest = pc.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM pricing_catalogs newer
        WHERE newer.provider = pc.provider
          AND newer.model = pc.model
          AND newer.effective_at_ms > pc.effective_at_ms
          AND newer.effective_at_ms <= NEW.created_at_ms
          AND NOT EXISTS (
            SELECT 1 FROM pricing_catalog_invalidations npi
            WHERE npi.pricing_catalog_digest = newer.digest
          )
      )
      AND (
        (cs.scope_kind = 'attempt'
          AND ba.account_scope = 'project'
          AND ba.project_id = cs.project_id
          AND NEW.runtime_call_lease_id IS NULL
          AND EXISTS (
            SELECT 1 FROM attempts a
            WHERE a.id = cs.attempt_id
              AND a.pricing_catalog_digest = NEW.pricing_catalog_digest
              AND a.required_reservation_micro_usd = NEW.amount_micro_usd
          ))
        OR (cs.scope_kind IN ('portfolio_runtime','service_operation')
          AND ba.account_scope = 'portfolio'
          AND ba.project_id IS NULL
          AND NEW.runtime_call_lease_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM runtime_call_leases rcl
            WHERE rcl.id = NEW.runtime_call_lease_id
              AND rcl.charge_subject_id = cs.id
              AND rcl.pricing_catalog_digest = NEW.pricing_catalog_digest
              AND rcl.required_reservation_micro_usd = NEW.amount_micro_usd
              AND rcl.state = 'prepared'
          ))
        OR (cs.scope_kind = 'project_runtime'
          AND ba.account_scope = 'project'
          AND ba.project_id = cs.project_id
          AND NEW.runtime_call_lease_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM runtime_call_leases rcl
            WHERE rcl.id = NEW.runtime_call_lease_id
              AND rcl.charge_subject_id = cs.id
              AND rcl.pricing_catalog_digest = NEW.pricing_catalog_digest
              AND rcl.required_reservation_micro_usd = NEW.amount_micro_usd
              AND rcl.state = 'prepared'
          ))
      )
      AND ba.spent_micro_usd + ba.reserved_micro_usd
          + NEW.amount_micro_usd <= ba.cap_micro_usd
  );
END;

CREATE TRIGGER usage_event_matches_reservation_and_pricing
BEFORE INSERT ON usage_events
BEGIN
  SELECT RAISE(ABORT, 'usage event must be contiguous cumulative usage priced exactly against its own envelope')
  WHERE NEW.reservation_id IS NULL
     OR NEW.provider_usage_id IS NULL
     OR NEW.provider_usage_id = ''
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.charge_subject_id') IS NOT NEW.charge_subject_id
     OR json_extract(NEW.canonical_json, '$.reservation_id') IS NOT NEW.reservation_id
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.provider_usage_id') IS NOT NEW.provider_usage_id
     OR json_extract(NEW.canonical_json, '$.sequence_no') IS NOT NEW.sequence_no
     OR json_extract(NEW.canonical_json, '$.pricing_catalog_digest') IS NOT NEW.pricing_catalog_digest
     OR json_extract(NEW.canonical_json, '$.delta_micro_usd') IS NOT NEW.delta_micro_usd
     OR json_extract(NEW.canonical_json, '$.input_tokens') IS NOT NEW.input_tokens
     OR json_extract(NEW.canonical_json, '$.output_tokens') IS NOT NEW.output_tokens
     OR json_extract(NEW.canonical_json, '$.cache_read_tokens') IS NOT NEW.cache_read_tokens
     OR json_extract(NEW.canonical_json, '$.cache_write_tokens') IS NOT NEW.cache_write_tokens
     OR json_extract(NEW.canonical_json, '$.tool_calls') IS NOT NEW.tool_calls
     OR json_extract(NEW.canonical_json, '$.wall_time_ms') IS NOT NEW.wall_time_ms
     OR json_extract(NEW.canonical_json, '$.final_marker') IS NOT NEW.final_marker
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys observer_key
       JOIN principals observer ON observer.id = observer_key.principal_id
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key ON evidence_key.key_id = evidence.signer_key_id
       WHERE observer_key.key_id = NEW.signer_key_id
         AND observer_key.principal_id = NEW.signer_principal_id
         AND observer_key.key_purpose = 'provider_observer'
         AND observer.kind = 'service'
         AND evidence_key.key_purpose = 'artifact_broker'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'usage_event'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.payload_digest
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
     )
     OR NEW.sequence_no <> (
       SELECT COALESCE(MAX(sequence_no),0) + 1
       FROM usage_events WHERE reservation_id = NEW.reservation_id
     )
     OR EXISTS (
       SELECT 1 FROM usage_events prior
       WHERE prior.reservation_id = NEW.reservation_id
         AND prior.sequence_no = NEW.sequence_no - 1
         AND (
           NEW.input_tokens < prior.input_tokens
           OR NEW.output_tokens < prior.output_tokens
           OR NEW.cache_read_tokens < prior.cache_read_tokens
           OR NEW.cache_write_tokens < prior.cache_write_tokens
           OR NEW.tool_calls < prior.tool_calls
           OR NEW.wall_time_ms < prior.wall_time_ms
           OR NEW.observed_at_ms <= prior.observed_at_ms
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM budget_reservations br
       JOIN pricing_catalogs pc ON pc.digest = NEW.pricing_catalog_digest
       WHERE br.id = NEW.reservation_id
         AND br.charge_subject_id = NEW.charge_subject_id
         AND br.pricing_catalog_digest = NEW.pricing_catalog_digest
         AND br.state IN ('held','partially_consumed','consumed','released','breached')
         AND NEW.observed_at_ms >= br.created_at_ms
         AND NEW.observed_at_ms <= (unixepoch('subsec') * 1000) + 5000
         AND pc.provider = NEW.provider
         AND NEW.delta_micro_usd = (
           (NEW.input_tokens * pc.input_rate_per_million
            + NEW.output_tokens * pc.output_rate_per_million
            + NEW.cache_read_tokens * pc.cache_read_rate_per_million
            + NEW.cache_write_tokens * pc.cache_write_rate_per_million
            + NEW.tool_calls * pc.tool_call_rate_per_million
            + NEW.wall_time_ms * pc.millisecond_rate_per_million
            + 999999) / 1000000
           - COALESCE((
               SELECT SUM(prior.delta_micro_usd)
               FROM usage_events prior
               WHERE prior.reservation_id = NEW.reservation_id
             ),0)
         )
         AND (
           (br.runtime_call_lease_id IS NULL AND EXISTS (
             SELECT 1
             FROM charge_subjects cs
             JOIN attempts a ON a.id = cs.attempt_id
             WHERE cs.id = NEW.charge_subject_id
               AND cs.scope_kind = 'attempt'
           ))
           OR (br.runtime_call_lease_id IS NOT NULL AND EXISTS (
             SELECT 1 FROM runtime_call_leases rcl
             WHERE rcl.id = br.runtime_call_lease_id
               AND rcl.charge_subject_id = NEW.charge_subject_id
           ))
         )
     );

  -- Accounting is never rejected after provider spend. The AFTER trigger below
  -- persists a fail-closed arm breach and future admission checks consume it.
  SELECT 1
  WHERE EXISTS (
      SELECT 1
      FROM charge_subjects subject
      JOIN attempts attempt ON attempt.id = subject.attempt_id
      JOIN runs run ON run.id = attempt.run_id
      WHERE subject.id = NEW.charge_subject_id
        AND run.benchmark_preregistration_digest IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1
      FROM charge_subjects subject
      JOIN attempts attempt ON attempt.id = subject.attempt_id
      JOIN runs run ON run.id = attempt.run_id
      JOIN benchmark_arm_runs arm
        ON arm.preregistration_digest = run.benchmark_preregistration_digest
       AND arm.task_id = run.benchmark_task_id
       AND arm.arm = run.benchmark_arm
      JOIN benchmark_inference_budgets budget
        ON budget.digest = arm.inference_budget_digest
      WHERE subject.id = NEW.charge_subject_id
        AND (
          SELECT COUNT(DISTINCT prior_usage.reservation_id)
          FROM usage_events prior_usage
          JOIN budget_reservations prior_reservation
            ON prior_reservation.id = prior_usage.reservation_id
          JOIN charge_subjects prior_subject
            ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ) + CASE WHEN EXISTS (
          SELECT 1 FROM usage_events existing
          WHERE existing.reservation_id = NEW.reservation_id
        ) THEN 0 ELSE 1 END <= budget.max_provider_calls
        AND NEW.input_tokens + COALESCE((
          SELECT SUM(latest.input_tokens)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation
            ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject
            ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member
            ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (
              SELECT MAX(newest.sequence_no) FROM usage_events newest
              WHERE newest.reservation_id = latest.reservation_id
            )
        ), 0) <= budget.max_input_tokens
        AND NEW.output_tokens + COALESCE((
          SELECT SUM(latest.output_tokens)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (SELECT MAX(newest.sequence_no) FROM usage_events newest
                                      WHERE newest.reservation_id = latest.reservation_id)
        ), 0) <= budget.max_output_tokens
        AND NEW.cache_read_tokens + COALESCE((
          SELECT SUM(latest.cache_read_tokens)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (SELECT MAX(newest.sequence_no) FROM usage_events newest
                                      WHERE newest.reservation_id = latest.reservation_id)
        ), 0) <= budget.max_cache_read_tokens
        AND NEW.cache_write_tokens + COALESCE((
          SELECT SUM(latest.cache_write_tokens)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (SELECT MAX(newest.sequence_no) FROM usage_events newest
                                      WHERE newest.reservation_id = latest.reservation_id)
        ), 0) <= budget.max_cache_write_tokens
        AND NEW.tool_calls + COALESCE((
          SELECT SUM(latest.tool_calls)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (SELECT MAX(newest.sequence_no) FROM usage_events newest
                                      WHERE newest.reservation_id = latest.reservation_id)
        ), 0) <= budget.max_tool_calls
        AND NEW.wall_time_ms + COALESCE((
          SELECT SUM(latest.wall_time_ms)
          FROM usage_events latest
          JOIN budget_reservations prior_reservation ON prior_reservation.id = latest.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
            AND latest.reservation_id <> NEW.reservation_id
            AND latest.sequence_no = (SELECT MAX(newest.sequence_no) FROM usage_events newest
                                      WHERE newest.reservation_id = latest.reservation_id)
        ), 0) <= budget.max_wall_time_ms
        AND NEW.delta_micro_usd + COALESCE((
          SELECT SUM(prior_usage.delta_micro_usd)
          FROM usage_events prior_usage
          JOIN budget_reservations prior_reservation ON prior_reservation.id = prior_usage.reservation_id
          JOIN charge_subjects prior_subject ON prior_subject.id = prior_reservation.charge_subject_id
          JOIN attempts prior_attempt ON prior_attempt.id = prior_subject.attempt_id
          JOIN benchmark_arm_run_members prior_member ON prior_member.run_id = prior_attempt.run_id
          WHERE prior_member.arm_execution_id = arm.arm_execution_id
        ), 0) <= budget.max_cost_micro_usd
    );
END;

CREATE TRIGGER benchmark_arm_budget_breach_is_exact_derived_usage
BEFORE INSERT ON benchmark_arm_budget_breaches
BEGIN
  SELECT RAISE(ABORT, 'benchmark budget breach is not the exact measured overage projection')
  WHERE NOT EXISTS (
    SELECT 1
    FROM benchmark_arm_measured_usage measured
    JOIN benchmark_arm_runs arm ON arm.arm_execution_id = measured.arm_execution_id
    JOIN benchmark_inference_budgets budget ON budget.digest = arm.inference_budget_digest
    JOIN usage_events source_usage ON source_usage.id = NEW.usage_event_id
    JOIN budget_reservations source_reservation
      ON source_reservation.id = source_usage.reservation_id
    JOIN charge_subjects source_subject
      ON source_subject.id = source_reservation.charge_subject_id
    JOIN attempts source_attempt ON source_attempt.id = source_subject.attempt_id
    JOIN benchmark_arm_run_members source_member
      ON source_member.run_id = source_attempt.run_id
     AND source_member.arm_execution_id = measured.arm_execution_id
    WHERE measured.arm_execution_id = NEW.arm_execution_id
      AND NEW.provider_call_count = measured.provider_call_count
      AND NEW.input_tokens = measured.input_tokens
      AND NEW.output_tokens = measured.output_tokens
      AND NEW.cache_read_tokens = measured.cache_read_tokens
      AND NEW.cache_write_tokens = measured.cache_write_tokens
      AND NEW.tool_calls = measured.tool_calls
      AND NEW.wall_time_ms = measured.wall_time_ms
      AND NEW.cost_micro_usd = measured.cost_micro_usd
      AND NEW.breached_at_ms = source_usage.observed_at_ms
      AND (
        measured.provider_call_count > budget.max_provider_calls
        OR measured.input_tokens > budget.max_input_tokens
        OR measured.output_tokens > budget.max_output_tokens
        OR measured.cache_read_tokens > budget.max_cache_read_tokens
        OR measured.cache_write_tokens > budget.max_cache_write_tokens
        OR measured.tool_calls > budget.max_tool_calls
        OR measured.wall_time_ms > budget.max_wall_time_ms
        OR measured.cost_micro_usd > budget.max_cost_micro_usd
      )
  );
END;

CREATE TRIGGER benchmark_usage_overage_is_recorded_not_discarded
AFTER INSERT ON usage_events
BEGIN
  INSERT OR IGNORE INTO benchmark_arm_budget_breaches(
    arm_execution_id, usage_event_id, provider_call_count,
    input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
    tool_calls, wall_time_ms, cost_micro_usd, breached_at_ms
  )
  SELECT measured.arm_execution_id, NEW.id, measured.provider_call_count,
         measured.input_tokens, measured.output_tokens,
         measured.cache_read_tokens, measured.cache_write_tokens,
         measured.tool_calls, measured.wall_time_ms, measured.cost_micro_usd,
         NEW.observed_at_ms
  FROM (
    SELECT arm.arm_execution_id,
           COUNT(DISTINCT usage.reservation_id) AS provider_call_count,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.input_tokens ELSE 0 END), 0) AS input_tokens,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.output_tokens ELSE 0 END), 0) AS output_tokens,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.cache_read_tokens ELSE 0 END), 0) AS cache_read_tokens,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.cache_write_tokens ELSE 0 END), 0) AS cache_write_tokens,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.tool_calls ELSE 0 END), 0) AS tool_calls,
           COALESCE(SUM(CASE WHEN usage.sequence_no = (
             SELECT MAX(latest.sequence_no) FROM usage_events latest
             WHERE latest.reservation_id = usage.reservation_id
           ) THEN usage.wall_time_ms ELSE 0 END), 0) AS wall_time_ms,
           COALESCE(SUM(usage.delta_micro_usd), 0) AS cost_micro_usd
    FROM usage_events usage
    JOIN budget_reservations reservation ON reservation.id = usage.reservation_id
    JOIN charge_subjects subject ON subject.id = reservation.charge_subject_id
    JOIN attempts attempt ON attempt.id = subject.attempt_id
    JOIN benchmark_arm_run_members member ON member.run_id = attempt.run_id
    JOIN benchmark_arm_runs arm ON arm.arm_execution_id = member.arm_execution_id
    WHERE arm.arm_execution_id = (
      SELECT current_arm.arm_execution_id
      FROM charge_subjects current_subject
      JOIN attempts current_attempt ON current_attempt.id = current_subject.attempt_id
      JOIN benchmark_arm_run_members current_member ON current_member.run_id = current_attempt.run_id
      JOIN benchmark_arm_runs current_arm ON current_arm.arm_execution_id = current_member.arm_execution_id
      WHERE current_subject.id = NEW.charge_subject_id
    )
    GROUP BY arm.arm_execution_id
  ) measured
  JOIN benchmark_arm_runs arm ON arm.arm_execution_id = measured.arm_execution_id
  JOIN benchmark_inference_budgets budget ON budget.digest = arm.inference_budget_digest
  WHERE measured.provider_call_count > budget.max_provider_calls
     OR measured.input_tokens > budget.max_input_tokens
     OR measured.output_tokens > budget.max_output_tokens
     OR measured.cache_read_tokens > budget.max_cache_read_tokens
     OR measured.cache_write_tokens > budget.max_cache_write_tokens
     OR measured.tool_calls > budget.max_tool_calls
     OR measured.wall_time_ms > budget.max_wall_time_ms
     OR measured.cost_micro_usd > budget.max_cost_micro_usd;
END;

CREATE TRIGGER benchmark_arm_budget_breaches_no_update
BEFORE UPDATE ON benchmark_arm_budget_breaches
BEGIN SELECT RAISE(ABORT, 'benchmark arm budget breaches are immutable'); END;

CREATE TRIGGER benchmark_arm_budget_breaches_no_delete
BEFORE DELETE ON benchmark_arm_budget_breaches
BEGIN SELECT RAISE(ABORT, 'benchmark arm budget breaches are immutable'); END;

CREATE TRIGGER budget_reservation_posts_hold
AFTER INSERT ON budget_reservations
BEGIN
  INSERT INTO budget_ledger
    (id,budget_account_id,reservation_id,entry_type,
     delta_reserved_micro_usd,delta_spent_micro_usd,source_key,created_at_ms)
  VALUES
    ('reserve:' || NEW.id,NEW.budget_account_id,NEW.id,'reserve',
     NEW.amount_micro_usd,0,'reserve:' || NEW.id,NEW.created_at_ms);

  UPDATE budget_accounts
  SET reserved_micro_usd = reserved_micro_usd + NEW.amount_micro_usd,
      revision = revision + 1
  WHERE id = NEW.budget_account_id;
END;

CREATE TRIGGER usage_event_posts_exact_settlement
AFTER INSERT ON usage_events
BEGIN
  INSERT INTO budget_ledger
    (id,budget_account_id,reservation_id,usage_event_id,entry_type,
     delta_reserved_micro_usd,delta_spent_micro_usd,source_key,created_at_ms)
  SELECT
    'usage:' || NEW.id,br.budget_account_id,br.id,NEW.id,'spend',
    -CASE
       WHEN br.closed_at_ms IS NOT NULL THEN 0
       WHEN NEW.final_marker = 1
       THEN max(br.amount_micro_usd - br.consumed_micro_usd, 0)
       ELSE min(NEW.delta_micro_usd,
                max(br.amount_micro_usd - br.consumed_micro_usd, 0))
     END,
    NEW.delta_micro_usd,'usage:' || NEW.id,NEW.observed_at_ms
  FROM budget_reservations br WHERE br.id = NEW.reservation_id;

  UPDATE budget_accounts
  SET reserved_micro_usd = reserved_micro_usd - (
        SELECT CASE
          WHEN br.closed_at_ms IS NOT NULL THEN 0
          WHEN NEW.final_marker = 1 THEN max(br.amount_micro_usd - br.consumed_micro_usd, 0)
          ELSE min(NEW.delta_micro_usd,
                   max(br.amount_micro_usd - br.consumed_micro_usd, 0))
        END
        FROM budget_reservations br WHERE br.id = NEW.reservation_id
      ),
      spent_micro_usd = spent_micro_usd + NEW.delta_micro_usd,
      state = CASE
        WHEN state IN ('active','breached')
         AND (
           spent_micro_usd + NEW.delta_micro_usd > cap_micro_usd
           OR (SELECT consumed_micro_usd + NEW.delta_micro_usd > amount_micro_usd
               FROM budget_reservations WHERE id = NEW.reservation_id)
           OR EXISTS (
                SELECT 1 FROM budget_reservations
                WHERE id = NEW.reservation_id AND closed_at_ms IS NOT NULL
              )
           OR EXISTS (
                SELECT 1
                FROM budget_reservations br
                LEFT JOIN runtime_call_leases rcl ON rcl.id = br.runtime_call_lease_id
                LEFT JOIN charge_subjects cs ON cs.id = br.charge_subject_id
                LEFT JOIN attempts a ON a.id = cs.attempt_id
                WHERE br.id = NEW.reservation_id
                  AND (
                    (br.runtime_call_lease_id IS NULL AND (
                      NEW.input_tokens > a.max_input_tokens
                      OR NEW.output_tokens > a.max_output_tokens
                      OR NEW.cache_read_tokens > a.max_cache_read_tokens
                      OR NEW.cache_write_tokens > a.max_cache_write_tokens
                      OR NEW.tool_calls > a.max_tool_calls
                      OR NEW.wall_time_ms > a.max_wall_time_ms
                    ))
                    OR (br.runtime_call_lease_id IS NOT NULL AND (
                      NEW.input_tokens > rcl.max_input_tokens
                      OR NEW.output_tokens > rcl.max_output_tokens
                      OR NEW.cache_read_tokens > rcl.max_cache_read_tokens
                      OR NEW.cache_write_tokens > rcl.max_cache_write_tokens
                      OR NEW.tool_calls > rcl.max_tool_calls
                      OR NEW.wall_time_ms > rcl.max_wall_time_ms
                    ))
                  )
              )
         )
        THEN 'breached'
        ELSE state
      END,
      revision = revision + 1
  WHERE id = (
    SELECT budget_account_id FROM budget_reservations WHERE id = NEW.reservation_id
  );

  UPDATE budget_reservations
  SET consumed_micro_usd = consumed_micro_usd + NEW.delta_micro_usd,
      state = CASE
        WHEN closed_at_ms IS NOT NULL THEN 'breached'
        WHEN EXISTS (
          SELECT 1
          FROM budget_reservations br
          LEFT JOIN runtime_call_leases rcl ON rcl.id = br.runtime_call_lease_id
          LEFT JOIN charge_subjects cs ON cs.id = br.charge_subject_id
          LEFT JOIN attempts a ON a.id = cs.attempt_id
          WHERE br.id = NEW.reservation_id
            AND (
              (br.runtime_call_lease_id IS NULL AND (
                NEW.input_tokens > a.max_input_tokens
                OR NEW.output_tokens > a.max_output_tokens
                OR NEW.cache_read_tokens > a.max_cache_read_tokens
                OR NEW.cache_write_tokens > a.max_cache_write_tokens
                OR NEW.tool_calls > a.max_tool_calls
                OR NEW.wall_time_ms > a.max_wall_time_ms
              ))
              OR (br.runtime_call_lease_id IS NOT NULL AND (
                NEW.input_tokens > rcl.max_input_tokens
                OR NEW.output_tokens > rcl.max_output_tokens
                OR NEW.cache_read_tokens > rcl.max_cache_read_tokens
                OR NEW.cache_write_tokens > rcl.max_cache_write_tokens
                OR NEW.tool_calls > rcl.max_tool_calls
                OR NEW.wall_time_ms > rcl.max_wall_time_ms
              ))
            )
        ) THEN 'breached'
        WHEN closed_at_ms IS NOT NULL THEN state
        WHEN consumed_micro_usd + NEW.delta_micro_usd > amount_micro_usd THEN 'breached'
        WHEN NEW.final_marker = 1 THEN 'consumed'
        WHEN NEW.delta_micro_usd = 0 THEN state
        ELSE 'partially_consumed'
      END,
      closed_at_ms = CASE
        WHEN NEW.final_marker = 1 THEN COALESCE(closed_at_ms, NEW.observed_at_ms)
        ELSE closed_at_ms
      END
  WHERE id = NEW.reservation_id;
END;

CREATE TRIGGER resource_reservations_enter_held
BEFORE INSERT ON resource_reservations
WHEN NEW.state <> 'held' OR NEW.released_at_ms IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'resource reservations must enter pristine through held'); END;

CREATE TRIGGER runtime_call_leases_enter_prepared
BEFORE INSERT ON runtime_call_leases
WHEN NEW.state <> 'prepared'
BEGIN SELECT RAISE(ABORT, 'runtime call leases must enter through prepared'); END;

CREATE TRIGGER runtime_call_lease_matches_persistent_scope
BEFORE INSERT ON runtime_call_leases
BEGIN
  SELECT RAISE(ABORT, 'runtime call lease does not match a live persistent scope')
  WHERE NOT EXISTS (
      SELECT 1 FROM control_state control
      WHERE control.singleton = 1
        AND control.admission_mode = 'open'
        AND control.dispatch_enabled = 1
        AND control.kill_switch = 0
    )
    OR NEW.call_no <> (
      SELECT COALESCE(MAX(call_no),0) + 1
      FROM runtime_call_leases WHERE charge_subject_id = NEW.charge_subject_id
    )
    OR NOT EXISTS (
      SELECT 1
      FROM charge_subjects cs
      JOIN pricing_catalogs pc ON pc.digest = NEW.pricing_catalog_digest
      JOIN signing_keys psk ON psk.key_id = pc.signer_key_id
      WHERE cs.id = NEW.charge_subject_id
        AND cs.billing_provider = pc.provider
        AND cs.billing_model = pc.model
        AND pc.effective_at_ms <= NEW.created_at_ms
        AND psk.state = 'active'
        AND (psk.expires_at_ms IS NULL OR psk.expires_at_ms >= NEW.created_at_ms)
        AND NOT EXISTS (
          SELECT 1 FROM pricing_catalog_invalidations pci
          WHERE pci.pricing_catalog_digest = pc.digest
        )
        AND NOT EXISTS (
          SELECT 1 FROM pricing_catalogs newer
          WHERE newer.provider = pc.provider
            AND newer.model = pc.model
            AND newer.effective_at_ms > pc.effective_at_ms
            AND newer.effective_at_ms <= NEW.created_at_ms
            AND NOT EXISTS (
              SELECT 1 FROM pricing_catalog_invalidations npi
              WHERE npi.pricing_catalog_digest = newer.digest
            )
        )
        AND NEW.max_input_tokens + NEW.max_output_tokens <= 2000000
        AND NEW.required_reservation_micro_usd = (
          NEW.max_input_tokens * pc.input_rate_per_million
          + NEW.max_output_tokens * pc.output_rate_per_million
          + NEW.max_cache_read_tokens * pc.cache_read_rate_per_million
          + NEW.max_cache_write_tokens * pc.cache_write_rate_per_million
          + NEW.max_tool_calls * pc.tool_call_rate_per_million
          + NEW.max_wall_time_ms * pc.millisecond_rate_per_million
          + 999999
        ) / 1000000
        AND (
          (cs.scope_kind = 'portfolio_runtime' AND EXISTS (
            SELECT 1
            FROM runtime_intents ri
            JOIN runtime_sessions rs ON rs.runtime_intent_id = ri.id
            WHERE ri.id = cs.runtime_intent_id
              AND ri.session_scope = 'portfolio'
              AND ri.state = 'launched'
              AND rs.state = 'running'
          ))
          OR (cs.scope_kind = 'project_runtime' AND EXISTS (
            SELECT 1
            FROM runtime_intents ri
            JOIN runtime_sessions rs ON rs.runtime_intent_id = ri.id
            JOIN executors executor ON executor.id = ri.executor_id
            WHERE ri.id = cs.runtime_intent_id
              AND ri.session_scope = 'project_generation'
              AND ri.project_id = cs.project_id
              AND ri.state = 'launched'
              AND rs.state = 'running'
              AND executor.pool = 'fable'
              AND executor.id <> 'rick'
          ))
          OR (cs.scope_kind = 'service_operation' AND EXISTS (
            SELECT 1
            FROM managed_service_intents mi
            JOIN managed_service_sessions ms
              ON ms.managed_service_intent_id = mi.id
            WHERE mi.charge_subject_id = cs.id
              AND mi.state = 'launched'
              AND ms.state = 'running'
          ))
        )
    );
END;

CREATE TRIGGER runtime_call_lease_activation_requires_resource_and_authority
BEFORE UPDATE OF state ON runtime_call_leases
WHEN OLD.state = 'prepared' AND NEW.state = 'active'
BEGIN
  SELECT RAISE(ABORT, 'runtime call activation requires current budget, pricing, runtime probe, identity, and resource authority')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_until_ms IS NULL
     OR NEW.started_at_ms IS NULL
     OR NEW.started_at_ms > NEW.claim_until_ms
     OR NEW.claim_until_ms > NEW.started_at_ms + NEW.max_wall_time_ms
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM charge_subjects cs
       JOIN control_state ctl ON ctl.singleton = 1
       JOIN current_host_capacity hc ON hc.singleton = 1
       JOIN budget_reservations br
         ON br.runtime_call_lease_id = NEW.id
        AND br.charge_subject_id = NEW.charge_subject_id
        AND br.pricing_catalog_digest = NEW.pricing_catalog_digest
        AND br.amount_micro_usd = NEW.required_reservation_micro_usd
       JOIN budget_accounts ba ON ba.id = br.budget_account_id
       JOIN pricing_catalogs pc ON pc.digest = NEW.pricing_catalog_digest
       JOIN current_valid_keys psk
         ON psk.key_id = pc.signer_key_id
        AND psk.key_purpose = 'control_plane'
       WHERE cs.id = NEW.charge_subject_id
         AND ctl.kill_switch = 0
         AND ctl.admission_mode = 'open'
         AND br.state = 'held'
         AND ba.state = 'active'
         AND pc.provider = cs.billing_provider
         AND pc.model = cs.billing_model
         AND pc.effective_at_ms <= (unixepoch('subsec') * 1000)
         AND NOT EXISTS (
           SELECT 1 FROM pricing_catalog_invalidations pci
           WHERE pci.pricing_catalog_digest = pc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM pricing_catalogs newer
           WHERE newer.provider = pc.provider
             AND newer.model = pc.model
             AND newer.effective_at_ms > pc.effective_at_ms
             AND newer.effective_at_ms <= (unixepoch('subsec') * 1000)
             AND NOT EXISTS (
               SELECT 1 FROM pricing_catalog_invalidations npi
               WHERE npi.pricing_catalog_digest = newer.digest
             )
         )
         AND (
           (cs.scope_kind IN ('portfolio_runtime','project_runtime') AND EXISTS (
             SELECT 1
             FROM runtime_intents ri
             JOIN runtime_sessions rs ON rs.runtime_intent_id = ri.id
             JOIN executors e ON e.id = ri.executor_id
             JOIN runtime_catalogs rc ON rc.digest = ri.runtime_catalog_digest
             JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
             JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
             JOIN signing_keys rpask ON rpask.key_id = rpa.signer_key_id
             JOIN leader_terms lt ON lt.term = ri.leader_term
             JOIN resource_reservations rr
               ON rr.runtime_call_lease_id = NEW.id
              AND rr.charge_subject_id = NEW.charge_subject_id
             JOIN resource_profiles rprof ON rprof.digest = rr.resource_profile_digest
             WHERE ri.id = cs.runtime_intent_id
               AND ri.state = 'launched'
               AND rs.state = 'running'
               AND (
                 (cs.scope_kind = 'portfolio_runtime'
                   AND ri.session_scope = 'portfolio'
                   AND ri.project_id IS NULL
                   AND e.id = 'rick')
                 OR
                 (cs.scope_kind = 'project_runtime'
                   AND ri.session_scope = 'project_generation'
                   AND ri.project_id = cs.project_id
                   AND e.pool = 'fable'
                   AND e.id <> 'rick')
               )
               AND lt.state = 'active'
               AND ctl.current_term = ri.leader_term
               AND rr.reservation_kind = 'active_call'
               AND rr.state = 'held'
               AND rprof.profile_name = 'fable_active_call'
               AND rprof.host_policy_digest = hc.resource_policy_digest
               AND NOT EXISTS (
                 SELECT 1 FROM policy_invalidations pi
                 WHERE pi.policy_digest IN (e.sandbox_policy_digest, rprof.digest, rprof.host_policy_digest)
               )
               AND rsk.state = 'active'
               AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND rpask.state = 'active'
               AND (rpask.expires_at_ms IS NULL OR rpask.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND rpa.probe_contract_digest = rc.probe_contract_digest
               AND rpa.binary_digest = rc.binary_digest
               AND rpa.actual_model = rc.resolved_model
               AND rpa.actual_model_family = rc.resolved_model_family
               AND rpa.actual_effort = rc.resolved_effort
               AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                        AND (unixepoch('subsec') * 1000) + 5000
               AND NOT EXISTS (
                 SELECT 1 FROM runtime_catalog_invalidations rci
                 WHERE rci.runtime_catalog_digest = rc.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM configuration_artifact_invalidations cai
                 WHERE cai.configuration_digest IN (
                   e.config_digest, rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
                   rc.provider_proxy_profile_digest, rc.io_protocol_digest,
                   rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
                 )
               )
           ))
           OR (cs.scope_kind = 'service_operation' AND EXISTS (
             SELECT 1
             FROM managed_service_intents mi
             JOIN managed_service_sessions ms
               ON ms.managed_service_intent_id = mi.id
             JOIN managed_service_identities msi ON msi.digest = mi.managed_identity_digest
             JOIN runtime_catalogs rc ON rc.digest = mi.runtime_catalog_digest
             JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
             JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
             JOIN signing_keys rpask ON rpask.key_id = rpa.signer_key_id
             JOIN leader_terms lt ON lt.term = mi.leader_term
             JOIN resource_reservations rr
               ON rr.charge_subject_id = cs.id
              AND rr.reservation_kind = 'process'
             JOIN resource_profiles rprof ON rprof.digest = rr.resource_profile_digest
             WHERE mi.charge_subject_id = cs.id
               AND mi.state = 'launched'
               AND ms.state = 'running'
               AND lt.state = 'active'
               AND ctl.current_term = mi.leader_term
               AND rr.state = 'held'
               AND rprof.profile_name = 'managed_opus_process'
               AND rprof.host_policy_digest = hc.resource_policy_digest
               AND NOT EXISTS (
                 SELECT 1 FROM policy_invalidations pi
                 WHERE pi.policy_digest IN (msi.sandbox_policy_digest, rprof.digest, rprof.host_policy_digest)
               )
               AND rsk.state = 'active'
               AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND rpask.state = 'active'
               AND (rpask.expires_at_ms IS NULL OR rpask.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND rpa.probe_contract_digest = rc.probe_contract_digest
               AND rpa.binary_digest = rc.binary_digest
               AND rpa.actual_model = rc.resolved_model
               AND rpa.actual_model_family = rc.resolved_model_family
               AND rpa.actual_effort = rc.resolved_effort
               AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                        AND (unixepoch('subsec') * 1000) + 5000
               AND NOT EXISTS (
                 SELECT 1 FROM runtime_catalog_invalidations rci
                 WHERE rci.runtime_catalog_digest = rc.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM managed_service_identity_invalidations mii
                 WHERE mii.managed_identity_digest = msi.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM configuration_artifact_invalidations cai
                 WHERE cai.configuration_digest IN (
                   msi.config_digest, msi.sanitization_rules_digest,
                   rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
                   rc.provider_proxy_profile_digest, rc.io_protocol_digest,
                   rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
                 )
               )
           ))
         )
     );
END;

CREATE TRIGGER runtime_call_leases_legal_state_transition
BEFORE UPDATE OF state ON runtime_call_leases
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal runtime-call lease transition')
  WHERE NOT (
    (OLD.state = 'prepared' AND NEW.state IN ('active','expired','unknown'))
    OR (OLD.state = 'active' AND NEW.state IN ('released','expired','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('released','expired'))
  );
END;

CREATE TRIGGER runtime_call_lease_terminal_requires_time
BEFORE UPDATE OF state ON runtime_call_leases
WHEN NEW.state IN ('released','expired') AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'terminal runtime-call lease requires end time')
  WHERE NEW.ended_at_ms IS NULL
     OR NOT (
       EXISTS (
         SELECT 1
         FROM budget_reservations br
         JOIN usage_events u ON u.reservation_id = br.id
         WHERE br.runtime_call_lease_id = NEW.id
           AND u.final_marker = 1
           AND u.sequence_no = (
             SELECT MAX(sequence_no) FROM usage_events WHERE reservation_id = br.id
           )
           AND u.observed_at_ms <= NEW.ended_at_ms
       )
       OR EXISTS (
         SELECT 1 FROM reconciliation_decisions d
         WHERE d.subject_kind = 'runtime_call_lease'
           AND d.subject_id = NEW.id
           AND d.provider_lookup_key = NEW.provider_call_key
           AND d.resolved_state = NEW.state
           AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
           AND d.observed_at_ms <= NEW.ended_at_ms
       )
     );
END;

CREATE TRIGGER runtime_call_lease_identity_is_immutable
BEFORE UPDATE OF id, charge_subject_id, call_no, pricing_catalog_digest,
  max_input_tokens, max_output_tokens, max_cache_read_tokens,
  max_cache_write_tokens, max_tool_calls, max_wall_time_ms,
  required_reservation_micro_usd, provider_call_key, created_at_ms ON runtime_call_leases
BEGIN SELECT RAISE(ABORT, 'runtime-call lease identity is immutable'); END;

CREATE TRIGGER runtime_call_provider_identity_is_set_once
BEFORE UPDATE OF provider_call_id ON runtime_call_leases
WHEN OLD.provider_call_id IS NOT NEW.provider_call_id
BEGIN
  SELECT RAISE(ABORT, 'runtime provider call identity is set once while active')
  WHERE OLD.provider_call_id IS NOT NULL
     OR NEW.provider_call_id IS NULL
     OR NEW.state NOT IN ('active','released','expired','unknown');
END;

CREATE TRIGGER runtime_call_lease_claim_identity_is_set_once
BEFORE UPDATE OF claim_token, claim_until_ms ON runtime_call_leases
WHEN (OLD.claim_token IS NOT NULL AND OLD.claim_token IS NOT NEW.claim_token)
  OR (OLD.claim_until_ms IS NOT NULL AND OLD.claim_until_ms IS NOT NEW.claim_until_ms)
BEGIN SELECT RAISE(ABORT, 'runtime-call claim identity is immutable once set'); END;

CREATE TRIGGER runtime_call_leases_no_delete
BEFORE DELETE ON runtime_call_leases
BEGIN SELECT RAISE(ABORT, 'runtime-call lease history is append-only'); END;

CREATE TRIGGER host_capacity_enters_unreserved
BEFORE INSERT ON host_capacity
BEGIN
  SELECT RAISE(ABORT, 'host capacity must bootstrap with zero reservations')
  WHERE NEW.measurement_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.reserved_disk_bytes <> 0
     OR NEW.reserved_rss_bytes <> 0
     OR NEW.reserved_pid_count <> 0
     OR NEW.reserved_fd_count <> 0
     OR NEW.reserved_cpu_millis <> 0;

  SELECT RAISE(ABORT, 'host capacity does not match its signed resource policy or measurements')
  WHERE NOT EXISTS (
    SELECT 1
    FROM policies p
    JOIN signing_keys sk ON sk.key_id = p.signer_key_id
    JOIN host_resource_policy_limits lim ON lim.policy_digest = p.digest
    JOIN host_capacity_measurements m ON m.id = NEW.measurement_id
    WHERE p.digest = NEW.resource_policy_digest
      AND p.policy_type = 'host_resource'
      AND sk.state = 'active'
      AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= NEW.measurement_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = p.digest
      )
      AND m.host_id = NEW.host_id
      AND m.measured_free_disk_bytes = NEW.measured_free_disk_bytes
      AND m.measured_physical_ram_bytes = NEW.measured_physical_ram_bytes
      AND m.measured_available_ram_bytes = NEW.measured_available_ram_bytes
      AND m.observed_platform_rss_bytes = NEW.observed_platform_rss_bytes
      AND m.measured_logical_cpu_millis = NEW.measured_logical_cpu_millis
      AND m.measurement_at_ms = NEW.measurement_at_ms
      AND NEW.emergency_reserve_bytes = lim.emergency_disk_bytes
      AND NEW.clone_log_allowance_bytes >= lim.clone_log_allowance_bytes
      AND NEW.emergency_ram_bytes = lim.emergency_ram_bytes
      AND NEW.observed_platform_rss_bytes >= lim.min_platform_baseline_rss_bytes
      AND NEW.max_model_rss_bytes =
          (NEW.measured_physical_ram_bytes * lim.max_model_rss_fraction_ppm) / 1000000
      AND NEW.measured_logical_cpu_millis > lim.control_cpu_millis
      AND NEW.max_model_cpu_millis =
          ((NEW.measured_logical_cpu_millis - lim.control_cpu_millis)
            * lim.cpu_oversubscription_ppm) / 1000000
      AND NEW.max_model_pid_count = lim.max_model_pid_count
      AND NEW.max_model_fd_count = lim.max_model_fd_count
  );
END;

CREATE TRIGGER host_capacity_updates_match_bound_policy
BEFORE UPDATE ON host_capacity
BEGIN
  SELECT RAISE(ABORT, 'updated host capacity does not match its bound resource policy')
  WHERE NEW.measurement_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
    SELECT 1
    FROM host_resource_policy_limits lim
    JOIN host_capacity_measurements m ON m.id = NEW.measurement_id
    WHERE lim.policy_digest = NEW.resource_policy_digest
      AND m.host_id = NEW.host_id
      AND m.measured_free_disk_bytes = NEW.measured_free_disk_bytes
      AND m.measured_physical_ram_bytes = NEW.measured_physical_ram_bytes
      AND m.measured_available_ram_bytes = NEW.measured_available_ram_bytes
      AND m.observed_platform_rss_bytes = NEW.observed_platform_rss_bytes
      AND m.measured_logical_cpu_millis = NEW.measured_logical_cpu_millis
      AND m.measurement_at_ms = NEW.measurement_at_ms
      AND NEW.emergency_reserve_bytes = lim.emergency_disk_bytes
      AND NEW.clone_log_allowance_bytes >= lim.clone_log_allowance_bytes
      AND NEW.emergency_ram_bytes = lim.emergency_ram_bytes
      AND NEW.observed_platform_rss_bytes >= lim.min_platform_baseline_rss_bytes
      AND NEW.max_model_rss_bytes =
          (NEW.measured_physical_ram_bytes * lim.max_model_rss_fraction_ppm) / 1000000
      AND NEW.measured_logical_cpu_millis > lim.control_cpu_millis
      AND NEW.max_model_cpu_millis =
          ((NEW.measured_logical_cpu_millis - lim.control_cpu_millis)
            * lim.cpu_oversubscription_ppm) / 1000000
      AND NEW.max_model_pid_count = lim.max_model_pid_count
      AND NEW.max_model_fd_count = lim.max_model_fd_count
  );
END;

CREATE TRIGGER host_capacity_measurement_requires_signed_service_observation
BEFORE INSERT ON host_capacity_measurements
BEGIN
  SELECT RAISE(ABORT, 'host measurement requires exact signed service observation')
  WHERE NEW.measurement_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.host_id') IS NOT NEW.host_id
     OR json_extract(NEW.canonical_json, '$.measured_free_disk_bytes') IS NOT NEW.measured_free_disk_bytes
     OR json_extract(NEW.canonical_json, '$.measured_physical_ram_bytes') IS NOT NEW.measured_physical_ram_bytes
     OR json_extract(NEW.canonical_json, '$.measured_available_ram_bytes') IS NOT NEW.measured_available_ram_bytes
     OR json_extract(NEW.canonical_json, '$.observed_platform_rss_bytes') IS NOT NEW.observed_platform_rss_bytes
     OR json_extract(NEW.canonical_json, '$.measured_logical_cpu_millis') IS NOT NEW.measured_logical_cpu_millis
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.measurement_at_ms') IS NOT NEW.measurement_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM principals p
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'runtime_supervisor'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       JOIN principal_global_roles pgr
         ON pgr.principal_id = p.id
        AND pgr.role = 'operator'
        AND pgr.revoked_at_ms IS NULL
       WHERE p.id = NEW.signer_principal_id
         AND p.kind = 'service'
         AND p.state = 'active'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'host_capacity_measurement'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.measurement_at_ms - 5000 AND NEW.measurement_at_ms
     );
END;

CREATE TRIGGER host_capacity_measurements_no_update
BEFORE UPDATE ON host_capacity_measurements
BEGIN SELECT RAISE(ABORT, 'host capacity measurements are append-only'); END;

CREATE TRIGGER host_capacity_measurements_no_delete
BEFORE DELETE ON host_capacity_measurements
BEGIN SELECT RAISE(ABORT, 'host capacity measurements are append-only'); END;

CREATE TRIGGER host_capacity_measurement_pointer_is_monotonic
BEFORE UPDATE OF measurement_id, measured_free_disk_bytes, measured_physical_ram_bytes,
  measured_available_ram_bytes, observed_platform_rss_bytes,
  measured_logical_cpu_millis, measurement_at_ms ON host_capacity
BEGIN
  SELECT RAISE(ABORT, 'host measurement refresh requires a newer signed measurement row')
  WHERE NEW.measurement_id = OLD.measurement_id
     OR NEW.measurement_at_ms <= OLD.measurement_at_ms;
END;

CREATE TRIGGER host_capacity_revision_increments_once
BEFORE UPDATE ON host_capacity
BEGIN
  SELECT RAISE(ABORT, 'host-capacity revision must increment exactly once')
  WHERE NEW.revision <> OLD.revision + 1;
END;

CREATE TRIGGER host_capacity_host_identity_is_immutable
BEFORE UPDATE OF singleton, host_id ON host_capacity
BEGIN SELECT RAISE(ABORT, 'host-capacity identity is immutable'); END;

CREATE TRIGGER host_capacity_policy_change_requires_disabled_unbound_bootstrap
BEFORE UPDATE OF resource_policy_digest, measured_physical_ram_bytes,
  emergency_reserve_bytes, clone_log_allowance_bytes, max_model_rss_bytes,
  emergency_ram_bytes, max_model_pid_count, max_model_fd_count,
  measured_logical_cpu_millis, max_model_cpu_millis
ON host_capacity
WHEN OLD.resource_policy_digest IS NOT NEW.resource_policy_digest
  OR OLD.measured_physical_ram_bytes <> NEW.measured_physical_ram_bytes
  OR OLD.emergency_reserve_bytes <> NEW.emergency_reserve_bytes
  OR OLD.clone_log_allowance_bytes <> NEW.clone_log_allowance_bytes
  OR OLD.max_model_rss_bytes <> NEW.max_model_rss_bytes
  OR OLD.emergency_ram_bytes <> NEW.emergency_ram_bytes
  OR OLD.max_model_pid_count <> NEW.max_model_pid_count
  OR OLD.max_model_fd_count <> NEW.max_model_fd_count
  OR OLD.measured_logical_cpu_millis <> NEW.measured_logical_cpu_millis
  OR OLD.max_model_cpu_millis <> NEW.max_model_cpu_millis
BEGIN
  SELECT RAISE(ABORT, 'host policy/derived limits change requires disabled dispatch and cleared bootstrap')
  WHERE EXISTS (
    SELECT 1 FROM control_state
    WHERE singleton = 1
      AND (dispatch_enabled <> 0 OR bootstrap_manifest_digest IS NOT NULL)
  );
END;

CREATE TRIGGER resource_reservation_requires_capacity
BEFORE INSERT ON resource_reservations
BEGIN
  SELECT RAISE(ABORT, 'resource reservation must enter held with pristine outcome fields')
  WHERE NEW.state <> 'held'
     OR NEW.breach_attestation_digest IS NOT NULL
     OR NEW.breached_at_ms IS NOT NULL
     OR NEW.released_at_ms IS NOT NULL
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000;

  SELECT RAISE(ABORT, 'settled benchmark arm cannot create another resource reservation')
  WHERE EXISTS (
    SELECT 1
    FROM charge_subjects subject
    JOIN attempts attempt ON attempt.id = subject.attempt_id
    JOIN benchmark_arm_run_members member ON member.run_id = attempt.run_id
    JOIN benchmark_arm_settlement_seals settlement
      ON settlement.arm_execution_id = member.arm_execution_id
    WHERE subject.id = NEW.charge_subject_id
      AND subject.scope_kind = 'attempt'
  );

  SELECT RAISE(ABORT, 'resource reservation number must be contiguous per charge subject')
  WHERE NEW.reservation_no <> (
    SELECT COALESCE(MAX(reservation_no), 0) + 1
    FROM resource_reservations WHERE charge_subject_id = NEW.charge_subject_id
  );

  SELECT RAISE(ABORT, 'resource reservation kind does not match its charge scope')
  WHERE NOT EXISTS (
    SELECT 1
    FROM charge_subjects cs
    JOIN resource_profiles prof ON prof.digest = NEW.resource_profile_digest
    WHERE cs.id = NEW.charge_subject_id
      AND prof.reservation_kind = NEW.reservation_kind
      AND prof.disk_bytes = NEW.disk_bytes
      AND prof.rss_bytes = NEW.rss_bytes
      AND prof.pid_count = NEW.pid_count
      AND prof.fd_count = NEW.fd_count
      AND prof.cpu_millis = NEW.cpu_millis
      AND (
        (NEW.reservation_kind = 'active_call'
          AND cs.scope_kind = 'attempt'
          AND NEW.runtime_call_lease_id IS NULL
          AND prof.profile_name = 'fable_active_call'
          AND EXISTS (
            SELECT 1
            FROM attempts a
            JOIN executors e ON e.id = a.executor_id
            WHERE a.id = cs.attempt_id
              AND e.pool = 'fable'
              AND e.fresh_session_required = 0
              AND e.id <> 'rick'
          ))
        OR (NEW.reservation_kind = 'active_call'
          AND cs.scope_kind = 'portfolio_runtime'
          AND prof.profile_name = 'fable_active_call'
          AND EXISTS (
            SELECT 1
            FROM runtime_intents ri
            JOIN executors e ON e.id = ri.executor_id
            JOIN runtime_call_leases rcl
              ON rcl.id = NEW.runtime_call_lease_id
             AND rcl.charge_subject_id = cs.id
             AND rcl.state = 'prepared'
            WHERE ri.id = cs.runtime_intent_id
              AND ri.session_scope = 'portfolio'
              AND e.id = 'rick'
          ))
        OR (NEW.reservation_kind = 'active_call'
          AND cs.scope_kind = 'project_runtime'
          AND prof.profile_name = 'fable_active_call'
          AND EXISTS (
            SELECT 1
            FROM runtime_intents ri
            JOIN executors e ON e.id = ri.executor_id
            JOIN runtime_call_leases rcl
              ON rcl.id = NEW.runtime_call_lease_id
             AND rcl.charge_subject_id = cs.id
             AND rcl.state = 'prepared'
            WHERE ri.id = cs.runtime_intent_id
              AND ri.session_scope = 'project_generation'
              AND ri.project_id = cs.project_id
              AND e.pool = 'fable'
              AND e.id <> 'rick'
          ))
        OR (NEW.reservation_kind = 'process' AND (
          (cs.scope_kind = 'portfolio_runtime'
            AND NEW.runtime_call_lease_id IS NULL
            AND prof.profile_name = 'fable_portfolio_process')
          OR (cs.scope_kind = 'project_runtime'
            AND NEW.runtime_call_lease_id IS NULL
            AND prof.profile_name = 'fable_project_process')
          OR (cs.scope_kind = 'service_operation'
            AND NEW.runtime_call_lease_id IS NULL
            AND prof.profile_name = 'managed_opus_process'
            AND EXISTS (
              SELECT 1 FROM managed_service_intents mi
              WHERE mi.charge_subject_id = cs.id
            ))
          OR (cs.scope_kind = 'attempt' AND EXISTS (
            SELECT 1
            FROM attempts a
            JOIN executors e ON e.id = a.executor_id
            WHERE a.id = cs.attempt_id
              AND e.fresh_session_required = 1
              AND NEW.runtime_call_lease_id IS NULL
              AND prof.profile_name = CASE e.pool
                WHEN 'codex' THEN 'codex_fresh_process'
                WHEN 'opus' THEN 'opus_fresh_process'
              END
          ))
        ))
      )
  );

  SELECT RAISE(ABORT, 'resource reservation exceeds measured disk headroom')
  WHERE NOT EXISTS (
    SELECT 1
    FROM current_host_capacity hc
    JOIN policies p ON p.digest = hc.resource_policy_digest
    JOIN signing_keys sk ON sk.key_id = p.signer_key_id
    JOIN host_resource_policy_limits lim ON lim.policy_digest = p.digest
    JOIN resource_profiles prof ON prof.digest = NEW.resource_profile_digest
    WHERE hc.singleton = 1
      AND p.policy_type = 'host_resource'
      AND sk.state = 'active'
      AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= NEW.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = p.digest
      )
      AND prof.host_policy_digest = p.digest
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = prof.digest
      )
      AND hc.measurement_at_ms >= NEW.created_at_ms - 60000
      AND hc.measurement_at_ms <= NEW.created_at_ms + 5000
      AND hc.measured_free_disk_bytes - hc.pending_reserved_disk_bytes
          - NEW.disk_bytes - hc.clone_log_allowance_bytes
          >= hc.emergency_reserve_bytes
      AND hc.reserved_rss_bytes + NEW.rss_bytes <= hc.max_model_rss_bytes
      AND hc.measured_available_ram_bytes
          - hc.pending_reserved_rss_bytes
          - NEW.rss_bytes >= hc.emergency_ram_bytes
      AND hc.reserved_pid_count + NEW.pid_count <= hc.max_model_pid_count
      AND hc.reserved_fd_count + NEW.fd_count <= hc.max_model_fd_count
      AND hc.reserved_cpu_millis + NEW.cpu_millis <= hc.max_model_cpu_millis
      AND (
        (NEW.reservation_kind = 'process'
          AND NEW.cpu_millis >= lim.persistent_idle_cpu_millis)
        OR (NEW.reservation_kind = 'active_call'
          AND NEW.cpu_millis = lim.active_call_cpu_millis)
      )
  );
END;

CREATE TRIGGER resource_reservation_debits_capacity
AFTER INSERT ON resource_reservations
BEGIN
  UPDATE host_capacity
  SET reserved_disk_bytes = reserved_disk_bytes + NEW.disk_bytes,
      reserved_rss_bytes = reserved_rss_bytes + NEW.rss_bytes,
      reserved_pid_count = reserved_pid_count + NEW.pid_count,
      reserved_fd_count = reserved_fd_count + NEW.fd_count,
      reserved_cpu_millis = reserved_cpu_millis + NEW.cpu_millis,
      revision = revision + 1
  WHERE singleton = 1;
END;

CREATE TRIGGER resource_reservation_releases_capacity
AFTER UPDATE OF state ON resource_reservations
WHEN OLD.state IN ('held','breached') AND NEW.state = 'released'
BEGIN
  UPDATE host_capacity
  SET reserved_disk_bytes = reserved_disk_bytes - OLD.disk_bytes,
      reserved_rss_bytes = reserved_rss_bytes - OLD.rss_bytes,
      reserved_pid_count = reserved_pid_count - OLD.pid_count,
      reserved_fd_count = reserved_fd_count - OLD.fd_count,
      reserved_cpu_millis = reserved_cpu_millis - OLD.cpu_millis,
      revision = revision + 1
  WHERE singleton = 1;
END;

CREATE TRIGGER host_capacity_reserved_totals_match_live_reservations
BEFORE UPDATE OF reserved_disk_bytes, reserved_rss_bytes, reserved_pid_count,
  reserved_fd_count, reserved_cpu_millis ON host_capacity
BEGIN
  SELECT RAISE(ABORT, 'host reserved totals must equal held/breached reservations')
  WHERE NEW.reserved_disk_bytes <> (
          SELECT COALESCE(SUM(disk_bytes),0) FROM resource_reservations
          WHERE state IN ('held','breached')
        )
     OR NEW.reserved_rss_bytes <> (
          SELECT COALESCE(SUM(rss_bytes),0) FROM resource_reservations
          WHERE state IN ('held','breached')
        )
     OR NEW.reserved_pid_count <> (
          SELECT COALESCE(SUM(pid_count),0) FROM resource_reservations
          WHERE state IN ('held','breached')
        )
     OR NEW.reserved_fd_count <> (
          SELECT COALESCE(SUM(fd_count),0) FROM resource_reservations
          WHERE state IN ('held','breached')
        )
     OR NEW.reserved_cpu_millis <> (
          SELECT COALESCE(SUM(cpu_millis),0) FROM resource_reservations
          WHERE state IN ('held','breached')
        );
END;

CREATE TRIGGER resource_residency_observation_requires_live_signed_process
BEFORE INSERT ON resource_residency_observations
BEGIN
  SELECT RAISE(ABORT, 'residency observation is stale, unsigned, out of order, or not bound to the live process')
  WHERE NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 10000
     OR NEW.sample_seq <> COALESCE((
          SELECT MAX(sample_seq) FROM resource_residency_observations
          WHERE resource_reservation_id = NEW.resource_reservation_id
        ), 0) + 1
     OR NEW.observed_at_ms <= COALESCE((
          SELECT MAX(observed_at_ms)
          FROM resource_residency_observations
          WHERE resource_reservation_id = NEW.resource_reservation_id
        ), 0)
     OR json_extract(NEW.canonical_json, '$.resource_reservation_id') IS NOT NEW.resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.active_call_resource_reservation_id')
          IS NOT NEW.active_call_resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.effective_cpu_limit_millis')
          IS NOT NEW.effective_cpu_limit_millis
     OR json_extract(NEW.canonical_json, '$.sample_seq') IS NOT NEW.sample_seq
     OR json_extract(NEW.canonical_json, '$.window_start_ms') IS NOT NEW.window_start_ms
     OR json_extract(NEW.canonical_json, '$.resident_rss_bytes') IS NOT NEW.resident_rss_bytes
     OR json_extract(NEW.canonical_json, '$.resident_disk_bytes') IS NOT NEW.resident_disk_bytes
     OR json_extract(NEW.canonical_json, '$.resident_pid_count') IS NOT NEW.resident_pid_count
     OR json_extract(NEW.canonical_json, '$.open_fd_count') IS NOT NEW.open_fd_count
     OR json_extract(NEW.canonical_json, '$.cpu_millis_in_window') IS NOT NEW.cpu_millis_in_window
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM resource_reservations rr
       JOIN charge_subjects cs ON cs.id = rr.charge_subject_id
       JOIN resource_profiles profile ON profile.digest = rr.resource_profile_digest
       JOIN host_resource_policy_limits limits
         ON limits.policy_digest = profile.host_policy_digest
       JOIN principals p ON p.id = NEW.signer_principal_id
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'runtime_supervisor'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       JOIN principal_global_roles pgr
         ON pgr.principal_id = NEW.signer_principal_id
        AND pgr.role = 'operator'
        AND pgr.revoked_at_ms IS NULL
       WHERE rr.id = NEW.resource_reservation_id
         AND rr.reservation_kind = 'process'
         AND rr.state IN ('held','breached')
         AND NEW.observed_at_ms >= rr.created_at_ms
         AND NEW.observed_at_ms - NEW.window_start_ms = limits.cpu_window_ms
         AND (
           NEW.sample_seq = 1
           OR NEW.window_start_ms >= (
             SELECT prior.observed_at_ms
             FROM resource_residency_observations prior
             WHERE prior.resource_reservation_id = rr.id
             AND prior.sample_seq = NEW.sample_seq - 1
           )
         )
         AND NOT EXISTS (
           SELECT 1
           FROM resource_reservations mid_window_call
           WHERE mid_window_call.reservation_kind = 'active_call'
             AND mid_window_call.state IN ('held','breached','released')
             AND mid_window_call.created_at_ms < NEW.observed_at_ms
             AND COALESCE(mid_window_call.released_at_ms, 9223372036854775807)
                   > NEW.window_start_ms
             AND NOT (
               mid_window_call.created_at_ms <= NEW.window_start_ms
               AND COALESCE(mid_window_call.released_at_ms, 9223372036854775807)
                     >= NEW.observed_at_ms
             )
             AND (
               mid_window_call.charge_subject_id = rr.charge_subject_id
               OR EXISTS (
                 SELECT 1
                 FROM charge_subjects call_subject
                 JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
                 JOIN attempt_session_bindings binding ON binding.attempt_id = call_attempt.id
                 JOIN runtime_sessions session ON session.id = binding.runtime_session_id
                 WHERE call_subject.id = mid_window_call.charge_subject_id
                   AND call_subject.scope_kind = 'attempt'
                   AND cs.scope_kind IN ('portfolio_runtime','project_runtime')
                   AND session.runtime_intent_id = cs.runtime_intent_id
               )
             )
         )
         AND NEW.effective_cpu_limit_millis = rr.cpu_millis + COALESCE((
           SELECT active_call.cpu_millis
           FROM resource_reservations active_call
             WHERE active_call.id = NEW.active_call_resource_reservation_id
               AND active_call.reservation_kind = 'active_call'
               AND active_call.state IN ('held','breached','released')
               AND active_call.created_at_ms <= NEW.window_start_ms
               AND COALESCE(active_call.released_at_ms, 9223372036854775807)
                     >= NEW.observed_at_ms
             AND (
               active_call.charge_subject_id = rr.charge_subject_id
               OR EXISTS (
                 SELECT 1
                 FROM charge_subjects call_subject
                 JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
                 JOIN attempt_session_bindings binding ON binding.attempt_id = call_attempt.id
                 JOIN runtime_sessions session ON session.id = binding.runtime_session_id
                 WHERE call_subject.id = active_call.charge_subject_id
                   AND call_subject.scope_kind = 'attempt'
                   AND cs.scope_kind IN ('portfolio_runtime','project_runtime')
                   AND session.runtime_intent_id = cs.runtime_intent_id
               )
             )
         ), 0)
         AND (
           (NEW.active_call_resource_reservation_id IS NULL AND NOT EXISTS (
             SELECT 1
             FROM resource_reservations active_call
             WHERE active_call.reservation_kind = 'active_call'
               AND active_call.state IN ('held','breached','released')
               AND active_call.created_at_ms < NEW.observed_at_ms
               AND COALESCE(active_call.released_at_ms, 9223372036854775807)
                     > NEW.window_start_ms
               AND (
                 active_call.charge_subject_id = rr.charge_subject_id
                 OR EXISTS (
                   SELECT 1
                   FROM charge_subjects call_subject
                   JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
                   JOIN attempt_session_bindings binding ON binding.attempt_id = call_attempt.id
                   JOIN runtime_sessions session ON session.id = binding.runtime_session_id
                   WHERE call_subject.id = active_call.charge_subject_id
                     AND call_subject.scope_kind = 'attempt'
                     AND cs.scope_kind IN ('portfolio_runtime','project_runtime')
                     AND session.runtime_intent_id = cs.runtime_intent_id
                 )
               )
           ))
           OR (NEW.active_call_resource_reservation_id IS NOT NULL
             AND EXISTS (
               SELECT 1
               FROM resource_reservations active_call
               WHERE active_call.id = NEW.active_call_resource_reservation_id
                 AND active_call.reservation_kind = 'active_call'
                 AND active_call.state IN ('held','breached','released')
                 AND active_call.created_at_ms <= NEW.window_start_ms
                 AND COALESCE(active_call.released_at_ms, 9223372036854775807)
                       >= NEW.observed_at_ms
                 AND (
                   active_call.charge_subject_id = rr.charge_subject_id
                   OR EXISTS (
                     SELECT 1
                     FROM charge_subjects call_subject
                     JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
                     JOIN attempt_session_bindings binding ON binding.attempt_id = call_attempt.id
                     JOIN runtime_sessions session ON session.id = binding.runtime_session_id
                     WHERE call_subject.id = active_call.charge_subject_id
                       AND call_subject.scope_kind = 'attempt'
                       AND cs.scope_kind IN ('portfolio_runtime','project_runtime')
                       AND session.runtime_intent_id = cs.runtime_intent_id
                   )
                 )
             )
             AND NOT EXISTS (
               SELECT 1
               FROM resource_reservations other_call
               WHERE other_call.id <> NEW.active_call_resource_reservation_id
                 AND other_call.reservation_kind = 'active_call'
                 AND other_call.state IN ('held','breached','released')
                 AND other_call.created_at_ms < NEW.observed_at_ms
                 AND COALESCE(other_call.released_at_ms, 9223372036854775807)
                       > NEW.window_start_ms
                 AND (
                   other_call.charge_subject_id = rr.charge_subject_id
                   OR EXISTS (
                     SELECT 1
                     FROM charge_subjects call_subject
                     JOIN attempts call_attempt ON call_attempt.id = call_subject.attempt_id
                     JOIN attempt_session_bindings binding ON binding.attempt_id = call_attempt.id
                     JOIN runtime_sessions session ON session.id = binding.runtime_session_id
                     WHERE call_subject.id = other_call.charge_subject_id
                       AND call_subject.scope_kind = 'attempt'
                       AND cs.scope_kind IN ('portfolio_runtime','project_runtime')
                       AND session.runtime_intent_id = cs.runtime_intent_id
                   )
                 )
             ))
         )
         AND p.kind = 'service'
         AND p.state = 'active'
         AND (
           (cs.scope_kind = 'attempt' AND EXISTS (
             SELECT 1 FROM dispatch_receipts dr
             WHERE dr.attempt_id = cs.attempt_id
               AND dr.process_identity = NEW.process_identity
               AND dr.state IN ('launched','completed','unknown')
           ))
           OR (cs.scope_kind IN ('portfolio_runtime','project_runtime') AND EXISTS (
             SELECT 1 FROM runtime_intents ri
             WHERE ri.id = cs.runtime_intent_id
               AND ri.process_identity = NEW.process_identity
               AND ri.state IN ('launch_permitted','launched','unknown')
           ))
           OR (cs.scope_kind = 'service_operation' AND EXISTS (
             SELECT 1 FROM managed_service_intents mi
             WHERE mi.charge_subject_id = cs.id
               AND mi.process_identity = NEW.process_identity
               AND mi.state IN ('launch_permitted','launched','unknown')
           ))
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'resource_residency_observation'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
     );
END;

CREATE TRIGGER resource_residency_observations_no_update
BEFORE UPDATE ON resource_residency_observations
BEGIN SELECT RAISE(ABORT, 'resource residency observations are append-only'); END;

CREATE TRIGGER resource_residency_observations_no_delete
BEFORE DELETE ON resource_residency_observations
BEGIN SELECT RAISE(ABORT, 'resource residency observations are append-only'); END;

CREATE TRIGGER resource_breach_attestation_is_exact_signed_window
BEFORE INSERT ON resource_breach_attestations
BEGIN
  SELECT RAISE(ABORT, 'resource breach is not an exact signed contiguous five-second over-limit window')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.breach_confirmed_at_ms > NEW.created_at_ms
     OR NEW.created_at_ms - NEW.breach_confirmed_at_ms > 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.resource_reservation_id') IS NOT NEW.resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.resource_profile_digest') IS NOT NEW.resource_profile_digest
     OR json_extract(NEW.canonical_json, '$.breach_dimension') IS NOT NEW.breach_dimension
     OR json_extract(NEW.canonical_json, '$.threshold_value') IS NOT NEW.threshold_value
     OR json_extract(NEW.canonical_json, '$.first_observation_id') IS NOT NEW.first_observation_id
     OR json_extract(NEW.canonical_json, '$.last_observation_id') IS NOT NEW.last_observation_id
     OR json_extract(NEW.canonical_json, '$.consecutive_sample_count') IS NOT NEW.consecutive_sample_count
     OR json_extract(NEW.canonical_json, '$.breach_started_at_ms') IS NOT NEW.breach_started_at_ms
     OR json_extract(NEW.canonical_json, '$.breach_confirmed_at_ms') IS NOT NEW.breach_confirmed_at_ms
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM resource_reservations reservation
       JOIN resource_residency_observations first_sample
         ON first_sample.id = NEW.first_observation_id
        AND first_sample.resource_reservation_id = reservation.id
        AND first_sample.process_identity = NEW.process_identity
       JOIN resource_residency_observations last_sample
         ON last_sample.id = NEW.last_observation_id
        AND last_sample.resource_reservation_id = reservation.id
        AND last_sample.process_identity = NEW.process_identity
       JOIN current_valid_keys supervisor_key
         ON supervisor_key.key_id = NEW.signer_key_id
        AND supervisor_key.principal_id = NEW.signer_principal_id
        AND supervisor_key.key_purpose = 'runtime_supervisor'
       JOIN principals supervisor
         ON supervisor.id = NEW.signer_principal_id
        AND supervisor.kind = 'service'
        AND supervisor.state = 'active'
       JOIN principal_global_roles operator_role
         ON operator_role.principal_id = supervisor.id
        AND operator_role.role = 'operator'
        AND operator_role.revoked_at_ms IS NULL
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE reservation.id = NEW.resource_reservation_id
         AND reservation.state = 'held'
         AND reservation.reservation_kind = 'process'
         AND reservation.resource_profile_digest = NEW.resource_profile_digest
         AND first_sample.sample_seq < last_sample.sample_seq
         AND first_sample.observed_at_ms = NEW.breach_started_at_ms
         AND last_sample.observed_at_ms = NEW.breach_confirmed_at_ms
         AND last_sample.observed_at_ms - first_sample.observed_at_ms >= 5000
         AND NEW.consecutive_sample_count = last_sample.sample_seq - first_sample.sample_seq + 1
         AND NEW.threshold_value = CASE NEW.breach_dimension
           WHEN 'rss_bytes' THEN reservation.rss_bytes
           WHEN 'disk_bytes' THEN reservation.disk_bytes
           WHEN 'pid_count' THEN reservation.pid_count
           WHEN 'fd_count' THEN reservation.fd_count
           WHEN 'cpu_millis' THEN 0
         END
         AND (
           SELECT COUNT(*)
           FROM resource_residency_observations sample
           WHERE sample.resource_reservation_id = reservation.id
             AND sample.sample_seq BETWEEN first_sample.sample_seq AND last_sample.sample_seq
         ) = NEW.consecutive_sample_count
         AND NOT EXISTS (
           SELECT 1
           FROM resource_residency_observations sample
           WHERE sample.resource_reservation_id = reservation.id
             AND sample.sample_seq BETWEEN first_sample.sample_seq AND last_sample.sample_seq
             AND (
               (NEW.breach_dimension = 'cpu_millis'
                 AND NOT (sample.cpu_millis_in_window
                          > sample.effective_cpu_limit_millis))
               OR (NEW.breach_dimension <> 'cpu_millis'
                 AND NOT (CASE NEW.breach_dimension
                   WHEN 'rss_bytes' THEN sample.resident_rss_bytes
                   WHEN 'disk_bytes' THEN sample.resident_disk_bytes
                   WHEN 'pid_count' THEN sample.resident_pid_count
                   WHEN 'fd_count' THEN sample.open_fd_count
                 END > NEW.threshold_value))
             )
         )
         AND NOT EXISTS (
           SELECT 1
           FROM resource_residency_observations sample
           JOIN resource_residency_observations prior_sample
             ON prior_sample.resource_reservation_id = sample.resource_reservation_id
            AND prior_sample.sample_seq = sample.sample_seq - 1
           WHERE sample.resource_reservation_id = reservation.id
             AND sample.sample_seq BETWEEN first_sample.sample_seq + 1 AND last_sample.sample_seq
             AND sample.observed_at_ms - prior_sample.observed_at_ms > 3000
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'resource_breach_attestation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER resource_breach_attestations_no_update
BEFORE UPDATE ON resource_breach_attestations
BEGIN SELECT RAISE(ABORT, 'resource breach attestations are immutable'); END;

CREATE TRIGGER resource_breach_attestations_no_delete
BEFORE DELETE ON resource_breach_attestations
BEGIN SELECT RAISE(ABORT, 'resource breach attestations are immutable'); END;

CREATE TRIGGER process_termination_receipt_is_exact_and_signed
BEFORE INSERT ON process_termination_receipts
BEGIN
  SELECT RAISE(ABORT, 'process termination receipt is not exact, current, or subject-bound')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 60000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.resource_reservation_id') IS NOT NEW.resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.observed_process_state') IS NOT NEW.observed_process_state
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM resource_reservations reservation
       JOIN charge_subjects subject ON subject.id = reservation.charge_subject_id
       JOIN current_valid_keys supervisor_key
         ON supervisor_key.key_id = NEW.signer_key_id
        AND supervisor_key.principal_id = NEW.signer_principal_id
        AND supervisor_key.key_purpose = 'runtime_supervisor'
       JOIN principals supervisor
         ON supervisor.id = NEW.signer_principal_id
        AND supervisor.kind = 'service'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE reservation.id = NEW.resource_reservation_id
         AND reservation.reservation_kind = 'process'
         AND reservation.state IN ('held','breached')
         AND NEW.observed_at_ms >= reservation.created_at_ms
         AND NEW.observed_at_ms >= COALESCE((
           SELECT MAX(observation.observed_at_ms)
           FROM resource_residency_observations observation
           WHERE observation.resource_reservation_id = reservation.id
         ), reservation.created_at_ms)
         AND (
           (subject.scope_kind = 'attempt' AND EXISTS (
             SELECT 1 FROM dispatch_receipts receipt
             WHERE receipt.attempt_id = subject.attempt_id
               AND receipt.process_identity = NEW.process_identity
           ))
           OR (subject.scope_kind IN ('portfolio_runtime','project_runtime') AND EXISTS (
             SELECT 1 FROM runtime_intents intent
             WHERE intent.id = subject.runtime_intent_id
               AND intent.process_identity = NEW.process_identity
           ))
           OR (subject.scope_kind = 'service_operation' AND EXISTS (
             SELECT 1 FROM managed_service_intents intent
             WHERE intent.charge_subject_id = subject.id
               AND intent.process_identity = NEW.process_identity
           ))
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'process_termination_receipt'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
     );
END;

CREATE TRIGGER process_termination_receipts_no_update
BEFORE UPDATE ON process_termination_receipts
BEGIN SELECT RAISE(ABORT, 'process termination receipts are immutable'); END;

CREATE TRIGGER process_termination_receipts_no_delete
BEFORE DELETE ON process_termination_receipts
BEGIN SELECT RAISE(ABORT, 'process termination receipts are immutable'); END;

CREATE TRIGGER resource_reservations_legal_state_transition
BEFORE UPDATE OF state ON resource_reservations
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal resource-reservation state transition')
  WHERE NOT (
    (OLD.state = 'held' AND NEW.state IN ('released','breached'))
    OR (OLD.state = 'breached' AND NEW.state = 'released')
  );
END;

CREATE TRIGGER resource_reservation_breach_requires_exact_attestation
BEFORE UPDATE OF state, breach_attestation_digest, breached_at_ms ON resource_reservations
WHEN NEW.state = 'breached'
  OR OLD.breach_attestation_digest IS NOT NEW.breach_attestation_digest
  OR OLD.breached_at_ms IS NOT NEW.breached_at_ms
BEGIN
  SELECT RAISE(ABORT, 'held-to-breached requires the exact current signed breach window')
  WHERE OLD.state <> 'held'
     OR NEW.state <> 'breached'
     OR OLD.breach_attestation_digest IS NOT NULL
     OR OLD.breached_at_ms IS NOT NULL
     OR NEW.breach_attestation_digest IS NULL
     OR NEW.breached_at_ms IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM resource_breach_attestations breach
       WHERE breach.digest = NEW.breach_attestation_digest
         AND breach.resource_reservation_id = NEW.id
         AND breach.resource_profile_digest = NEW.resource_profile_digest
         AND breach.breach_confirmed_at_ms = NEW.breached_at_ms
         AND breach.created_at_ms BETWEEN NEW.breached_at_ms AND NEW.breached_at_ms + 5000
     );
END;

CREATE TRIGGER resource_reservation_release_time_is_set_once
BEFORE UPDATE OF released_at_ms ON resource_reservations
WHEN OLD.released_at_ms IS NOT NEW.released_at_ms
BEGIN
  SELECT RAISE(ABORT, 'resource release time is set once on the released transition')
  WHERE OLD.released_at_ms IS NOT NULL
     OR NEW.released_at_ms IS NULL
     OR OLD.state NOT IN ('held','breached')
     OR NEW.state <> 'released'
     OR NEW.released_at_ms < OLD.created_at_ms
     OR NEW.released_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER resource_release_requires_process_termination
BEFORE UPDATE OF state ON resource_reservations
WHEN OLD.state IN ('held','breached') AND NEW.state = 'released'
BEGIN
  SELECT RAISE(ABORT, 'resource reservation cannot release while scoped process is live')
  WHERE (NEW.reservation_kind = 'process' AND NOT EXISTS (
      SELECT 1 FROM process_termination_receipts receipt
      WHERE receipt.resource_reservation_id = NEW.id
        AND receipt.observed_at_ms = NEW.released_at_ms
    ))
    OR NEW.released_at_ms IS NULL
    OR NEW.released_at_ms < OLD.created_at_ms
    OR EXISTS (
    SELECT 1
    FROM charge_subjects cs
    WHERE cs.id = NEW.charge_subject_id
      AND (
        (NEW.reservation_kind = 'active_call'
          AND cs.scope_kind = 'attempt'
          AND NEW.runtime_call_lease_id IS NULL
          AND (
            EXISTS (
              SELECT 1 FROM attempts a
              WHERE a.id = cs.attempt_id
                AND a.state IN ('created','dispatched','acked','running','result_pending','unknown')
            )
            OR EXISTS (
              SELECT 1 FROM leases l
              WHERE l.attempt_id = cs.attempt_id AND l.state = 'active'
            )
          ))
        OR (NEW.reservation_kind = 'active_call'
          AND NEW.runtime_call_lease_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM runtime_call_leases rcl
            WHERE rcl.id = NEW.runtime_call_lease_id
              AND rcl.state NOT IN ('released','expired')
          ))
        OR (NEW.reservation_kind = 'process' AND cs.scope_kind = 'attempt' AND (
          EXISTS (
            SELECT 1 FROM attempts a
            WHERE a.id = cs.attempt_id
              AND a.state IN ('created','dispatched','acked','running','result_pending','unknown')
          )
          OR EXISTS (
            SELECT 1 FROM dispatch_receipts dr
            WHERE dr.attempt_id = cs.attempt_id
              AND dr.state IN ('launch_claimed','launched','unknown')
          )
          OR EXISTS (
            SELECT 1
            FROM attempt_session_bindings b
            JOIN runtime_sessions s ON s.id = b.runtime_session_id
            WHERE b.attempt_id = cs.attempt_id AND s.state <> 'terminated'
          )
        ))
        OR (NEW.reservation_kind = 'process'
          AND cs.scope_kind IN ('portfolio_runtime','project_runtime') AND (
          EXISTS (
            SELECT 1 FROM runtime_intents ri
            WHERE ri.id = cs.runtime_intent_id
              AND ri.state IN ('prepared','launch_claimed','launch_permitted','launched','unknown')
          )
          OR EXISTS (
            SELECT 1 FROM runtime_sessions s
            WHERE s.runtime_intent_id = cs.runtime_intent_id
              AND s.state <> 'terminated'
          )
        ))
        OR (NEW.reservation_kind = 'process' AND cs.scope_kind = 'service_operation' AND (
          EXISTS (
            SELECT 1 FROM managed_service_intents mi
            WHERE mi.charge_subject_id = cs.id
              AND mi.state IN ('prepared','launch_claimed','launch_permitted','launched','unknown')
          )
          OR EXISTS (
            SELECT 1
            FROM managed_service_intents mi
            JOIN managed_service_sessions ms
              ON ms.managed_service_intent_id = mi.id
            WHERE mi.charge_subject_id = cs.id AND ms.state <> 'terminated'
          )
        ))
      )
  );
END;

CREATE TRIGGER budget_account_creation_authorization_is_exact_and_signed
BEFORE INSERT ON budget_account_creation_authorizations
BEGIN
  SELECT RAISE(ABORT, 'budget-account creation authority is stale, inexact, or unsigned')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.budget_account_id') IS NOT NEW.budget_account_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.account_scope') IS NOT NEW.account_scope
     OR json_extract(NEW.canonical_json, '$.currency') IS NOT NEW.currency
     OR json_extract(NEW.canonical_json, '$.cap_micro_usd') IS NOT NEW.cap_micro_usd
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.bootstrap_manifest_digest') IS NOT NEW.bootstrap_manifest_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys signer_key
       JOIN principals signer ON signer.id = signer_key.principal_id
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       WHERE signer_key.key_id = NEW.signer_key_id
         AND signer_key.principal_id = NEW.signer_principal_id
         AND signer_key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
     )
     OR NOT (
       (NEW.account_scope = 'project' AND EXISTS (
         SELECT 1
         FROM command_authorizations authorization
         JOIN commands command ON command.id = authorization.command_id
         JOIN projects project ON project.id = NEW.project_id
         WHERE authorization.digest = NEW.command_authorization_digest
           AND authorization.command_type = 'project.submit'
           AND authorization.project_id IS NULL
           AND authorization.leader_term = NEW.leader_term
           AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
           AND NEW.expires_at_ms <= authorization.authorization_expires_at_ms
           AND NEW.expires_at_ms <= command.expires_at_ms
           AND command.state = 'authorized'
           AND project.submit_command_authorization_digest = authorization.digest
           AND json_extract(command.payload_json, '$.project_id') = NEW.project_id
           AND json_extract(command.payload_json, '$.budget_account_id') = NEW.budget_account_id
           AND json_extract(command.payload_json, '$.budget_cap_micro_usd') = NEW.cap_micro_usd
           AND json_extract(command.payload_json, '$.budget_currency') = NEW.currency
       ))
       OR (NEW.account_scope = 'portfolio' AND EXISTS (
         SELECT 1
         FROM bootstrap_manifests manifest
         JOIN current_valid_keys manifest_key
           ON manifest_key.key_id = manifest.signer_key_id
          AND manifest_key.key_purpose = 'control_plane'
         WHERE manifest.digest = NEW.bootstrap_manifest_digest
           AND json_extract(manifest.canonical_json, '$.portfolio_budget.account_id') = NEW.budget_account_id
           AND json_extract(manifest.canonical_json, '$.portfolio_budget.currency') = NEW.currency
           AND json_extract(manifest.canonical_json, '$.portfolio_budget.cap_micro_usd') = NEW.cap_micro_usd
       ))
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'budget_account_creation_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER budget_account_creation_authorizations_no_update
BEFORE UPDATE ON budget_account_creation_authorizations
BEGIN SELECT RAISE(ABORT, 'budget-account creation authorizations are immutable'); END;

CREATE TRIGGER budget_account_creation_authorizations_no_delete
BEFORE DELETE ON budget_account_creation_authorizations
BEGIN SELECT RAISE(ABORT, 'budget-account creation authorizations are immutable'); END;

CREATE TRIGGER budget_accounts_enter_active
BEFORE INSERT ON budget_accounts
BEGIN
  SELECT RAISE(ABORT, 'budget accounts must enter active with zero totals and exact creation authority')
  WHERE NEW.state <> 'active'
     OR NEW.reserved_micro_usd <> 0
     OR NEW.spent_micro_usd <> 0
     OR NEW.revision <> 0
     OR NOT EXISTS (
       SELECT 1 FROM budget_account_creation_authorizations authorization
       WHERE authorization.digest = NEW.creation_authorization_digest
         AND authorization.budget_account_id = NEW.id
         AND authorization.project_id IS NEW.project_id
         AND authorization.account_scope = NEW.account_scope
         AND authorization.currency = NEW.currency
         AND authorization.cap_micro_usd = NEW.cap_micro_usd
         AND authorization.created_at_ms = NEW.created_at_ms
         AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
     );
END;

CREATE TRIGGER budget_account_totals_match_append_only_ledger
BEFORE UPDATE OF reserved_micro_usd, spent_micro_usd ON budget_accounts
BEGIN
  SELECT RAISE(ABORT, 'budget totals must equal append-only ledger')
  WHERE NEW.reserved_micro_usd <> (
          SELECT COALESCE(SUM(delta_reserved_micro_usd),0)
          FROM budget_ledger WHERE budget_account_id = NEW.id
        )
     OR NEW.spent_micro_usd <> (
          SELECT COALESCE(SUM(delta_spent_micro_usd),0)
          FROM budget_ledger WHERE budget_account_id = NEW.id
        );
END;

CREATE TRIGGER budget_accounts_legal_state_transition
BEFORE UPDATE OF state ON budget_accounts
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal budget-account state transition')
  WHERE NOT (
    (OLD.state = 'active' AND NEW.state IN ('breached','frozen','closed'))
    OR (OLD.state = 'breached' AND NEW.state IN ('active','frozen','closed'))
    OR (OLD.state = 'frozen' AND NEW.state IN ('active','closed'))
  );

  SELECT RAISE(ABORT, 'budget state change lacks signed command authorization')
  WHERE NOT (OLD.state = 'active' AND NEW.state = 'breached')
    AND NOT EXISTS (
      SELECT 1 FROM budget_change_authorizations a
      WHERE a.budget_account_id = NEW.id
        AND a.old_cap_micro_usd = OLD.cap_micro_usd
        AND a.new_cap_micro_usd = NEW.cap_micro_usd
        AND a.old_state = OLD.state
        AND a.new_state = NEW.state
        AND a.target_revision = NEW.revision
        AND a.leader_term = (SELECT current_term FROM control_state WHERE singleton = 1)
        AND a.expires_at_ms >= (unixepoch('subsec') * 1000)
    );
END;

CREATE TRIGGER budget_account_identity_is_immutable
BEFORE UPDATE OF id, project_id, account_scope, creation_authorization_digest, currency, created_at_ms ON budget_accounts
BEGIN SELECT RAISE(ABORT, 'budget-account scope identity is immutable'); END;

CREATE TRIGGER budget_accounts_no_delete
BEFORE DELETE ON budget_accounts
BEGIN SELECT RAISE(ABORT, 'budget-account history cannot be deleted'); END;

CREATE TRIGGER budget_account_revision_increments_once
BEFORE UPDATE ON budget_accounts
BEGIN
  SELECT RAISE(ABORT, 'budget-account update must increment revision exactly once')
  WHERE NEW.revision <> OLD.revision + 1;
END;

CREATE TRIGGER budget_account_cap_change_requires_authorization
BEFORE UPDATE OF cap_micro_usd ON budget_accounts
WHEN OLD.cap_micro_usd <> NEW.cap_micro_usd
BEGIN
  SELECT RAISE(ABORT, 'budget cap change lacks signed command authorization')
  WHERE NEW.cap_micro_usd < NEW.spent_micro_usd + NEW.reserved_micro_usd
     OR NOT EXISTS (
       SELECT 1 FROM budget_change_authorizations a
       WHERE a.budget_account_id = NEW.id
         AND a.action = 'cap_change'
         AND a.old_cap_micro_usd = OLD.cap_micro_usd
         AND a.new_cap_micro_usd = NEW.cap_micro_usd
         AND a.old_state = OLD.state
         AND a.new_state = NEW.state
         AND a.target_revision = NEW.revision
         AND a.leader_term = (SELECT current_term FROM control_state WHERE singleton = 1)
         AND a.expires_at_ms >= (unixepoch('subsec') * 1000)
     );
END;

CREATE TRIGGER budget_change_authorization_is_current_and_signed
BEFORE INSERT ON budget_change_authorizations
BEGIN
  SELECT RAISE(ABORT, 'budget authorization is stale, unsigned, or unauthorized')
  WHERE json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.budget_account_id') IS NOT NEW.budget_account_id
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.actor_principal_id') IS NOT NEW.actor_principal_id
     OR json_extract(NEW.canonical_json, '$.action') IS NOT NEW.action
     OR json_extract(NEW.canonical_json, '$.old_cap_micro_usd') IS NOT NEW.old_cap_micro_usd
     OR json_extract(NEW.canonical_json, '$.new_cap_micro_usd') IS NOT NEW.new_cap_micro_usd
     OR json_extract(NEW.canonical_json, '$.old_state') IS NOT NEW.old_state
     OR json_extract(NEW.canonical_json, '$.new_state') IS NOT NEW.new_state
     OR json_extract(NEW.canonical_json, '$.target_revision') IS NOT NEW.target_revision
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR NOT EXISTS (
    SELECT 1
    FROM budget_accounts ba
    JOIN commands c ON c.id = NEW.command_id
    JOIN command_authorizations ca ON ca.command_id = c.id
    JOIN principals actor ON actor.id = NEW.actor_principal_id
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.principal_id = NEW.signer_principal_id
     AND sk.key_purpose = 'control_plane'
    JOIN principals signer ON signer.id = NEW.signer_principal_id
    JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
    JOIN control_state control ON control.current_term = NEW.leader_term
    WHERE ba.id = NEW.budget_account_id
      AND c.principal_id = NEW.actor_principal_id
      AND c.command_type = 'budget.change'
      AND c.state = 'authorized'
      AND ca.actor_principal_id = NEW.actor_principal_id
      AND ca.command_type = c.command_type
      AND ca.project_id IS ba.project_id
      AND ca.payload_digest = c.payload_digest
      AND ca.leader_term = NEW.leader_term
      AND ca.authorization_expires_at_ms >= NEW.created_at_ms
      AND NEW.expires_at_ms <= ca.authorization_expires_at_ms
      AND NEW.expires_at_ms <= c.expires_at_ms
      AND actor.state = 'active'
      AND signer.kind = 'service'
      AND NEW.old_cap_micro_usd = ba.cap_micro_usd
      AND NEW.old_state = ba.state
      AND NEW.target_revision = ba.revision + 1
      AND NEW.new_cap_micro_usd >= ba.spent_micro_usd + ba.reserved_micro_usd
      AND (
        (ba.account_scope = 'project' AND EXISTS (
          SELECT 1 FROM principal_project_roles ppr
          WHERE ppr.principal_id = NEW.actor_principal_id
            AND ppr.project_id = ba.project_id
            AND ppr.role IN ('owner','operator','approver')
            AND ppr.revoked_at_ms IS NULL
        ))
        OR (ba.account_scope = 'portfolio' AND EXISTS (
          SELECT 1 FROM principal_global_roles pgr
          WHERE pgr.principal_id = NEW.actor_principal_id
            AND pgr.role IN ('admin','operator')
            AND pgr.revoked_at_ms IS NULL
        ))
      )
      AND (
        (NEW.action = 'cap_change'
          AND NEW.old_cap_micro_usd <> NEW.new_cap_micro_usd
          AND NEW.old_state = NEW.new_state)
        OR (NEW.action = 'reactivate'
          AND NEW.old_state IN ('breached','frozen') AND NEW.new_state = 'active'
          AND NEW.old_cap_micro_usd = NEW.new_cap_micro_usd)
        OR (NEW.action = 'freeze'
          AND NEW.old_state IN ('active','breached') AND NEW.new_state = 'frozen'
          AND NEW.old_cap_micro_usd = NEW.new_cap_micro_usd)
        OR (NEW.action = 'close'
          AND NEW.old_state IN ('active','breached','frozen') AND NEW.new_state = 'closed'
          AND NEW.old_cap_micro_usd = NEW.new_cap_micro_usd)
      )
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'budget_change_authorization'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.id
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER budget_change_authorizations_no_update
BEFORE UPDATE ON budget_change_authorizations
BEGIN SELECT RAISE(ABORT, 'budget change authorizations are immutable'); END;

CREATE TRIGGER budget_change_authorizations_no_delete
BEFORE DELETE ON budget_change_authorizations
BEGIN SELECT RAISE(ABORT, 'budget change authorizations are immutable'); END;

CREATE TRIGGER budget_reservations_legal_state_transition
BEFORE UPDATE OF state ON budget_reservations
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal budget-reservation state transition')
  WHERE NOT (
    (OLD.state = 'held' AND NEW.state IN ('partially_consumed','consumed','released','breached'))
    OR (OLD.state = 'partially_consumed' AND NEW.state IN ('consumed','released','breached'))
    OR (OLD.state = 'breached' AND NEW.state IN ('consumed','released'))
    OR (OLD.state IN ('consumed','released') AND NEW.state = 'breached')
  );
END;

CREATE TRIGGER budget_reservation_consumed_requires_final_usage
BEFORE UPDATE OF state ON budget_reservations
WHEN NEW.state = 'consumed' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'consumed reservation requires exact latest final usage and closed settlement')
  WHERE NEW.closed_at_ms IS NULL
     OR NEW.consumed_micro_usd <> (
       SELECT COALESCE(SUM(usage.delta_micro_usd),0)
       FROM usage_events usage WHERE usage.reservation_id = NEW.id
     )
     OR NOT EXISTS (
       SELECT 1 FROM usage_events final_usage
       WHERE final_usage.reservation_id = NEW.id
         AND final_usage.final_marker = 1
         AND final_usage.sequence_no = (
           SELECT MAX(latest.sequence_no) FROM usage_events latest
           WHERE latest.reservation_id = NEW.id
         )
         AND final_usage.observed_at_ms = NEW.closed_at_ms
     );
END;

CREATE TRIGGER budget_reservation_consumption_matches_usage
BEFORE UPDATE OF consumed_micro_usd ON budget_reservations
WHEN OLD.consumed_micro_usd <> NEW.consumed_micro_usd
BEGIN
  SELECT RAISE(ABORT, 'reservation consumption must equal append-only usage events')
  WHERE NEW.consumed_micro_usd <> (
    SELECT COALESCE(SUM(delta_micro_usd),0)
    FROM usage_events WHERE reservation_id = NEW.id
  );
END;

CREATE TRIGGER budget_reservation_close_time_is_set_once_by_terminal_evidence
BEFORE UPDATE OF closed_at_ms ON budget_reservations
WHEN OLD.closed_at_ms IS NOT NEW.closed_at_ms
BEGIN
  SELECT RAISE(ABORT, 'budget close time is set once by final usage or release evidence')
  WHERE OLD.closed_at_ms IS NOT NULL
     OR NEW.closed_at_ms IS NULL
     OR NEW.closed_at_ms < OLD.created_at_ms
     OR NOT (
       (EXISTS (
          SELECT 1 FROM usage_events usage
          WHERE usage.reservation_id = NEW.id
            AND usage.final_marker = 1
            AND usage.observed_at_ms = NEW.closed_at_ms
            AND usage.sequence_no = (
              SELECT MAX(sequence_no) FROM usage_events
              WHERE reservation_id = NEW.id
            )
        ))
       OR (OLD.state IN ('held','partially_consumed','breached')
           AND NEW.state = 'released')
     );
END;

CREATE TRIGGER budget_reservation_release_requires_close_time
BEFORE UPDATE OF state ON budget_reservations
WHEN NEW.state = 'released' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'reservation release requires final usage or terminal grace plus signed provider reconciliation')
  WHERE NEW.closed_at_ms IS NULL
     OR NEW.closed_at_ms < NEW.created_at_ms
     OR NOT (
       EXISTS (
         SELECT 1 FROM usage_events u
         WHERE u.reservation_id = NEW.id
           AND u.final_marker = 1
           AND u.observed_at_ms <= NEW.closed_at_ms
           AND u.sequence_no = (
             SELECT MAX(sequence_no) FROM usage_events WHERE reservation_id = NEW.id
           )
       )
       OR (
         EXISTS (
           SELECT 1
           FROM charge_subjects cs
           LEFT JOIN attempts a ON a.id = cs.attempt_id
           LEFT JOIN runtime_call_leases rcl ON rcl.id = NEW.runtime_call_lease_id
           WHERE cs.id = NEW.charge_subject_id
             AND (
               (NEW.runtime_call_lease_id IS NULL
                 AND a.state IN ('accepted','failed','expired','cancelled','stale','quarantined')
                 AND a.finished_at_ms IS NOT NULL
                 AND (unixepoch('subsec') * 1000) >= a.finished_at_ms + 900000)
               OR (NEW.runtime_call_lease_id IS NOT NULL
                 AND rcl.state IN ('released','expired')
                 AND rcl.ended_at_ms IS NOT NULL
                 AND (unixepoch('subsec') * 1000) >= rcl.ended_at_ms + 900000)
             )
         )
         AND EXISTS (
           SELECT 1 FROM reconciliation_decisions d
           WHERE d.subject_kind = 'budget_reservation'
             AND d.subject_id = NEW.id
             AND d.resolved_state = 'released'
             AND d.process_identity IS NULL
             AND d.provider_lookup_key = NEW.id
             AND d.observed_process_state = 'not_applicable'
             AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
             AND d.observed_at_ms <= NEW.closed_at_ms
         )
       )
     );
END;

CREATE TRIGGER budget_reservation_posts_release
AFTER UPDATE OF state ON budget_reservations
WHEN NEW.state = 'released' AND OLD.state <> NEW.state
BEGIN
  INSERT INTO budget_ledger
    (id,budget_account_id,reservation_id,entry_type,
     delta_reserved_micro_usd,delta_spent_micro_usd,source_key,created_at_ms)
  VALUES
    ('release:' || NEW.id,NEW.budget_account_id,NEW.id,'release',
     -max(NEW.amount_micro_usd - NEW.consumed_micro_usd, 0),0,
     'release:' || NEW.id,NEW.closed_at_ms);

  UPDATE budget_accounts
  SET reserved_micro_usd = reserved_micro_usd
        - max(NEW.amount_micro_usd - NEW.consumed_micro_usd, 0),
      revision = revision + 1
  WHERE id = NEW.budget_account_id;
END;

CREATE TRIGGER budget_reservation_identity_is_immutable
BEFORE UPDATE OF id, budget_account_id, charge_subject_id, runtime_call_lease_id, reservation_no,
  pricing_catalog_digest, amount_micro_usd, created_at_ms ON budget_reservations
BEGIN SELECT RAISE(ABORT, 'budget reservation identity and amount are immutable'); END;

CREATE TRIGGER budget_reservations_no_delete
BEFORE DELETE ON budget_reservations
BEGIN SELECT RAISE(ABORT, 'budget reservations are retained for audit'); END;

CREATE TRIGGER commands_enter_received
BEFORE INSERT ON commands
BEGIN
  SELECT RAISE(ABORT, 'command ingress envelope is not exact, current, or ingress-broker signed')
  WHERE NEW.state <> 'received'
     OR NEW.authorized_at_ms IS NOT NULL
     OR NEW.completed_at_ms IS NOT NULL
     OR NEW.result_json IS NOT NULL
     OR NEW.received_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.received_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= NEW.received_at_ms
     OR NEW.expires_at_ms > NEW.received_at_ms + 30000
     OR NEW.command_type NOT IN (
          'project.submit','project.control','human.respond','approval.decide',
          'budget.change','authority.invalidate','effect.reconcile','risk.accept',
          'dispatch.control','key.manage','role.manage','repository.register',
          'project.repository.attach','integration_target.register'
        )
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.source') IS NOT NEW.source
     OR json_extract(NEW.canonical_json, '$.partition_key') IS NOT NEW.partition_key
     OR json_extract(NEW.canonical_json, '$.source_sequence') IS NOT NEW.source_sequence
     OR json_extract(NEW.canonical_json, '$.source_command_id') IS NOT NEW.source_command_id
     OR json_extract(NEW.canonical_json, '$.principal_id') IS NOT NEW.principal_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.command_type') IS NOT NEW.command_type
     OR json_extract(NEW.canonical_json, '$.auth_context_digest') IS NOT NEW.auth_context_digest
     OR json_extract(NEW.canonical_json, '$.nonce') IS NOT NEW.nonce
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR json_extract(NEW.canonical_json, '$.payload_json') IS NOT NEW.payload_json
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.ingress_evidence_manifest_digest') IS NOT NEW.ingress_evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.received_at_ms') IS NOT NEW.received_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys ingress_key
       JOIN principals ingress ON ingress.id = ingress_key.principal_id
       JOIN principals actor ON actor.id = NEW.principal_id
       JOIN artifact_manifests evidence
         ON evidence.digest = NEW.ingress_evidence_manifest_digest
       JOIN current_valid_keys evidence_key ON evidence_key.key_id = evidence.signer_key_id
       WHERE ingress_key.key_id = NEW.signer_key_id
         AND ingress_key.principal_id = NEW.signer_principal_id
         AND ingress_key.key_purpose = 'ingress_broker'
         AND ingress.kind = 'service'
         AND actor.state = 'active'
         AND evidence_key.key_purpose = 'artifact_broker'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'command'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.payload_digest
         AND receipt.verified_at_ms BETWEEN NEW.received_at_ms - 5000 AND NEW.received_at_ms
     );
END;

CREATE TRIGGER command_authorization_is_current_exact_and_scoped
BEFORE INSERT ON command_authorizations
BEGIN
  SELECT RAISE(ABORT, 'command authorization is not exact, current, or role scoped')
  WHERE NEW.authorized_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.authorized_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.authorization_expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.authorization_expires_at_ms > NEW.authorized_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.actor_principal_id') IS NOT NEW.actor_principal_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.command_type') IS NOT NEW.command_type
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.auth_context_digest') IS NOT NEW.auth_context_digest
     OR json_extract(NEW.canonical_json, '$.nonce') IS NOT NEW.nonce
     OR json_extract(NEW.canonical_json, '$.command_expires_at_ms') IS NOT NEW.command_expires_at_ms
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.authorized_at_ms') IS NOT NEW.authorized_at_ms
     OR json_extract(NEW.canonical_json, '$.authorization_expires_at_ms') IS NOT NEW.authorization_expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM commands c
       JOIN principals actor ON actor.id = NEW.actor_principal_id
       JOIN current_valid_keys control_key
         ON control_key.key_id = NEW.signer_key_id
        AND control_key.principal_id = NEW.signer_principal_id
        AND control_key.key_purpose = 'control_plane'
       JOIN principals control ON control.id = NEW.signer_principal_id
       JOIN leader_terms lt ON lt.term = NEW.leader_term AND lt.state = 'active'
       JOIN control_state ctl ON ctl.current_term = NEW.leader_term
       WHERE c.id = NEW.command_id
         AND c.state = 'received'
         AND c.principal_id = NEW.actor_principal_id
         AND c.project_id IS NEW.project_id
         AND c.command_type = NEW.command_type
         AND c.payload_digest = NEW.payload_digest
         AND c.auth_context_digest = NEW.auth_context_digest
         AND c.nonce = NEW.nonce
         AND c.expires_at_ms = NEW.command_expires_at_ms
         AND c.expires_at_ms >= NEW.authorized_at_ms
         AND NEW.authorization_expires_at_ms <= c.expires_at_ms
         AND actor.state = 'active'
         AND control.kind = 'service'
         AND (
           (NEW.command_type = 'project.submit')
           OR (NEW.project_id IS NOT NULL AND EXISTS (
             SELECT 1 FROM principal_project_roles pr
             WHERE pr.principal_id = NEW.actor_principal_id
               AND pr.project_id = NEW.project_id
               AND pr.revoked_at_ms IS NULL
               AND (
                 (NEW.command_type = 'project.control' AND pr.role IN ('owner','operator'))
                 OR (NEW.command_type = 'human.respond' AND pr.role IN ('owner','operator','reviewer','approver','risk_acceptor'))
                 OR (NEW.command_type = 'approval.decide' AND pr.role IN ('owner','operator','approver','risk_acceptor'))
                 OR (NEW.command_type = 'risk.accept' AND pr.role = 'risk_acceptor')
                 OR (NEW.command_type = 'effect.reconcile' AND pr.role IN ('owner','operator','risk_acceptor'))
                 OR (NEW.command_type IN ('budget.change','authority.invalidate','role.manage')
                     AND pr.role IN ('owner','operator'))
                 OR (NEW.command_type = 'project.repository.attach'
                     AND pr.role IN ('owner','operator'))
               )
           ))
           OR (NEW.project_id IS NULL AND NEW.command_type IN (
                 'budget.change','authority.invalidate','dispatch.control','key.manage','role.manage',
                 'repository.register','integration_target.register'
               ) AND EXISTS (
             SELECT 1 FROM principal_global_roles gr
             WHERE gr.principal_id = NEW.actor_principal_id
               AND gr.role IN ('admin','operator')
               AND gr.revoked_at_ms IS NULL
           ))
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'command_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.authorized_at_ms - 5000 AND NEW.authorized_at_ms
     );
END;

CREATE TRIGGER command_consumption_is_exact_current_and_signed
BEFORE INSERT ON command_consumptions
BEGIN
  SELECT RAISE(ABORT, 'command consumption is stale, inexact, or not bound to the committed mutation')
  WHERE NEW.consumed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.consumed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.prior_revision') IS NOT NEW.prior_revision
     OR json_extract(NEW.canonical_json, '$.new_revision') IS NOT NEW.new_revision
     OR json_extract(NEW.canonical_json, '$.mutation_digest') IS NOT NEW.mutation_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.consumed_at_ms') IS NOT NEW.consumed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM commands command
       JOIN command_authorizations authorization
         ON authorization.command_id = command.id
        AND authorization.digest = NEW.command_authorization_digest
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE command.id = NEW.command_id
         AND command.state = 'authorized'
         AND authorization.leader_term = NEW.leader_term
         AND authorization.authorization_expires_at_ms >= NEW.consumed_at_ms
         AND command.expires_at_ms >= NEW.consumed_at_ms
     )
     OR NOT (
       (NEW.subject_kind = 'project' AND EXISTS (
         SELECT 1 FROM projects subject
         WHERE subject.id = NEW.subject_id
           AND subject.revision = NEW.new_revision
       ))
       OR (NEW.subject_kind = 'control_state' AND NEW.subject_id = '1' AND EXISTS (
         SELECT 1 FROM control_state subject
         WHERE subject.singleton = 1 AND subject.revision = NEW.new_revision
       ))
       OR (NEW.subject_kind = 'budget_account' AND EXISTS (
         SELECT 1 FROM budget_accounts subject
         WHERE subject.id = NEW.subject_id AND subject.revision = NEW.new_revision
       ))
       OR (NEW.subject_kind = 'run' AND EXISTS (
         SELECT 1 FROM runs subject
         WHERE subject.id = NEW.subject_id AND subject.revision = NEW.new_revision
       ))
       OR (NEW.subject_kind = 'human_response' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM human_responses subject WHERE subject.request_id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'approval_decision' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM approval_decisions subject WHERE subject.request_id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'repository' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM repositories subject WHERE subject.id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'project_repository' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM project_repositories subject
         WHERE subject.project_id || ':' || subject.repository_id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'integration_target' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM integration_targets subject WHERE subject.id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'authority_change' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM authority_change_authorizations subject WHERE subject.id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'signing_key' AND NEW.prior_revision IS NULL AND EXISTS (
         SELECT 1 FROM signing_keys subject WHERE subject.key_id = NEW.subject_id
       ))
       OR (NEW.subject_kind = 'role_grant' AND NEW.prior_revision IS NULL AND (
         EXISTS (SELECT 1 FROM principal_project_roles subject WHERE subject.grant_id = NEW.subject_id)
         OR EXISTS (SELECT 1 FROM principal_global_roles subject WHERE subject.grant_id = NEW.subject_id)
       ))
     )
     OR NOT (
       (NEW.subject_kind = 'project' AND (
         (NEW.prior_revision IS NULL AND NEW.new_revision = 0 AND EXISTS (
           SELECT 1 FROM projects subject
           WHERE subject.id = NEW.subject_id
             AND subject.submit_command_authorization_digest = NEW.command_authorization_digest
         ))
         OR EXISTS (
           SELECT 1 FROM project_transition_authorizations transition
           WHERE transition.project_id = NEW.subject_id
             AND transition.from_revision = NEW.prior_revision
             AND transition.to_revision = NEW.new_revision
             AND transition.command_authorization_digest = NEW.command_authorization_digest
         )
       ))
       OR (NEW.subject_kind = 'control_state' AND EXISTS (
         SELECT 1 FROM control_state subject
         WHERE subject.singleton = 1
           AND subject.revision = NEW.new_revision
           AND subject.last_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'budget_account' AND EXISTS (
         SELECT 1 FROM budget_change_authorizations change_authority
         JOIN command_authorizations authorization
           ON authorization.command_id = change_authority.command_id
         WHERE change_authority.budget_account_id = NEW.subject_id
           AND change_authority.target_revision = NEW.new_revision
           AND authorization.digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'run' AND (
         (NEW.prior_revision IS NULL AND NEW.new_revision = 0 AND EXISTS (
           SELECT 1 FROM runs subject
           WHERE subject.id = NEW.subject_id
             AND subject.root_command_authorization_digest = NEW.command_authorization_digest
         ))
         OR EXISTS (
           SELECT 1 FROM run_transition_authorizations transition
           WHERE transition.run_id = NEW.subject_id
             AND transition.from_revision = NEW.prior_revision
             AND transition.to_revision = NEW.new_revision
             AND transition.command_authorization_digest = NEW.command_authorization_digest
         )
       ))
       OR (NEW.subject_kind = 'human_response' AND EXISTS (
         SELECT 1 FROM human_responses subject
         WHERE subject.request_id = NEW.subject_id
           AND subject.auth_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'approval_decision' AND EXISTS (
         SELECT 1 FROM approval_decisions subject
         WHERE subject.request_id = NEW.subject_id
           AND subject.auth_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'repository' AND EXISTS (
         SELECT 1 FROM repositories subject
         WHERE subject.id = NEW.subject_id
           AND subject.registration_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'project_repository' AND EXISTS (
         SELECT 1 FROM project_repositories subject
         WHERE subject.project_id || ':' || subject.repository_id = NEW.subject_id
           AND subject.attach_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'integration_target' AND EXISTS (
         SELECT 1 FROM integration_targets subject
         WHERE subject.id = NEW.subject_id
           AND subject.registration_command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'authority_change' AND EXISTS (
         SELECT 1 FROM authority_change_authorizations subject
         JOIN command_authorizations authorization ON authorization.command_id = subject.command_id
         WHERE subject.id = NEW.subject_id
           AND authorization.digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'signing_key' AND EXISTS (
         SELECT 1 FROM key_registration_authorizations subject
         WHERE subject.target_key_id = NEW.subject_id
           AND subject.command_authorization_digest = NEW.command_authorization_digest
       ))
       OR (NEW.subject_kind = 'role_grant' AND EXISTS (
         SELECT 1 FROM role_change_authorizations subject
         WHERE subject.target_grant_id = NEW.subject_id
           AND subject.command_authorization_digest = NEW.command_authorization_digest
       ))
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts mutation_receipt
       WHERE mutation_receipt.record_kind = 'domain_mutation'
         AND mutation_receipt.record_id = NEW.mutation_digest
         AND mutation_receipt.record_digest_verified = 1
         AND mutation_receipt.verified_record_digest = NEW.mutation_digest
         AND json_extract(mutation_receipt.record_canonical_json, '$.command_id') = NEW.command_id
         AND json_extract(mutation_receipt.record_canonical_json, '$.command_authorization_digest') = NEW.command_authorization_digest
         AND json_extract(mutation_receipt.record_canonical_json, '$.subject_kind') = NEW.subject_kind
         AND json_extract(mutation_receipt.record_canonical_json, '$.subject_id') = NEW.subject_id
         AND json_extract(mutation_receipt.record_canonical_json, '$.prior_revision') IS NEW.prior_revision
         AND json_extract(mutation_receipt.record_canonical_json, '$.new_revision') IS NEW.new_revision
         AND mutation_receipt.verified_at_ms BETWEEN NEW.consumed_at_ms - 5000 AND NEW.consumed_at_ms
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'command_consumption'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.consumed_at_ms - 5000 AND NEW.consumed_at_ms
     );
END;

CREATE TRIGGER command_consumptions_no_update
BEFORE UPDATE ON command_consumptions
BEGIN SELECT RAISE(ABORT, 'command consumptions are immutable'); END;

CREATE TRIGGER command_consumptions_no_delete
BEFORE DELETE ON command_consumptions
BEGIN SELECT RAISE(ABORT, 'command consumptions are immutable'); END;

CREATE TRIGGER command_authorizations_no_update
BEFORE UPDATE ON command_authorizations
BEGIN SELECT RAISE(ABORT, 'command authorizations are immutable'); END;

CREATE TRIGGER command_authorizations_no_delete
BEFORE DELETE ON command_authorizations
BEGIN SELECT RAISE(ABORT, 'command authorizations are immutable'); END;

CREATE TRIGGER commands_legal_state_transition
BEFORE UPDATE OF state ON commands
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal command state transition')
  WHERE NOT (
    (OLD.state = 'received' AND NEW.state IN ('authorized','rejected','failed'))
    OR (OLD.state = 'authorized' AND NEW.state IN ('applied','rejected','failed'))
  );

  SELECT RAISE(ABORT, 'received command can become authorized only from its exact signed authorization')
  WHERE NEW.state = 'authorized'
    AND (
      NEW.authorized_at_ms IS NULL
      OR NEW.authorized_at_ms > NEW.expires_at_ms
      OR NEW.expires_at_ms < (unixepoch('subsec') * 1000)
      OR NOT EXISTS (
        SELECT 1 FROM command_authorizations a
        JOIN leader_terms term ON term.term = a.leader_term AND term.state = 'active'
        JOIN control_state control ON control.current_term = a.leader_term
        WHERE a.command_id = NEW.id
          AND a.actor_principal_id = NEW.principal_id
          AND a.project_id IS NEW.project_id
          AND a.command_type = NEW.command_type
          AND a.payload_digest = NEW.payload_digest
          AND a.auth_context_digest = NEW.auth_context_digest
          AND a.nonce = NEW.nonce
          AND a.command_expires_at_ms = NEW.expires_at_ms
          AND a.authorized_at_ms = NEW.authorized_at_ms
          AND a.authorization_expires_at_ms >= NEW.authorized_at_ms
          AND a.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
      )
    );

  SELECT RAISE(ABORT, 'applied command is expired or lacks a still-current one-shot authorization')
  WHERE NEW.state = 'applied'
    AND (
      NEW.expires_at_ms < (unixepoch('subsec') * 1000)
      OR NOT EXISTS (
        SELECT 1 FROM command_authorizations authorization
        JOIN leader_terms term ON term.term = authorization.leader_term AND term.state = 'active'
        JOIN control_state control ON control.current_term = authorization.leader_term
        WHERE authorization.command_id = NEW.id
          AND authorization.command_expires_at_ms = NEW.expires_at_ms
          AND authorization.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
          AND NEW.completed_at_ms <= authorization.command_expires_at_ms
          AND NEW.completed_at_ms <= authorization.authorization_expires_at_ms
      )
    );

  SELECT RAISE(ABORT, 'applied command lacks one exact committed subject consumption')
  WHERE NEW.state = 'applied'
    AND NOT EXISTS (
      SELECT 1 FROM command_consumptions consumption
      WHERE consumption.command_id = NEW.id
        AND consumption.command_authorization_digest = (
          SELECT authorization.digest FROM command_authorizations authorization
          WHERE authorization.command_id = NEW.id
        )
        AND consumption.consumed_at_ms = NEW.completed_at_ms
        AND json_extract(NEW.result_json, '$.mutation_digest') = consumption.mutation_digest
        AND json_extract(NEW.result_json, '$.subject_kind') = consumption.subject_kind
        AND json_extract(NEW.result_json, '$.subject_id') = consumption.subject_id
        AND json_extract(NEW.result_json, '$.new_revision') IS consumption.new_revision
    );

  SELECT RAISE(ABORT, 'terminal command transition requires completion time')
  WHERE NEW.state IN ('applied','rejected','failed')
    AND (NEW.completed_at_ms IS NULL
      OR NEW.result_json IS NULL
      OR NEW.completed_at_ms < OLD.received_at_ms
      OR NEW.completed_at_ms < (unixepoch('subsec') * 1000) - 5000
      OR NEW.completed_at_ms > (unixepoch('subsec') * 1000) + 5000);
END;

CREATE TRIGGER commands_identity_is_immutable
BEFORE UPDATE OF id, source, partition_key, source_sequence, source_command_id,
  principal_id, project_id, command_type, auth_context_digest, nonce, expires_at_ms,
  payload_json, payload_digest, ingress_evidence_manifest_digest, canonical_json,
  signer_principal_id, signer_key_id, signature, received_at_ms
ON commands
BEGIN SELECT RAISE(ABORT, 'command ingress identity is immutable'); END;

CREATE TRIGGER commands_authorization_time_set_once
BEFORE UPDATE OF authorized_at_ms ON commands
WHEN OLD.authorized_at_ms IS NOT NEW.authorized_at_ms
BEGIN
  SELECT RAISE(ABORT, 'command authorization time is set once with authorized state')
  WHERE OLD.authorized_at_ms IS NOT NULL
     OR NEW.authorized_at_ms IS NULL
     OR OLD.state <> 'received'
     OR NEW.state <> 'authorized';
END;

CREATE TRIGGER commands_terminal_fields_are_transition_bound
BEFORE UPDATE OF completed_at_ms, result_json ON commands
WHEN OLD.completed_at_ms IS NOT NEW.completed_at_ms
  OR OLD.result_json IS NOT NEW.result_json
BEGIN
  SELECT RAISE(ABORT, 'command completion fields may be written once only on a terminal transition')
  WHERE OLD.completed_at_ms IS NOT NULL
     OR OLD.result_json IS NOT NULL
     OR OLD.state NOT IN ('received','authorized')
     OR NEW.state NOT IN ('applied','rejected','failed')
     OR NEW.completed_at_ms IS NULL
     OR NEW.completed_at_ms < OLD.received_at_ms
     OR NEW.completed_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER commands_no_delete
BEFORE DELETE ON commands
BEGIN SELECT RAISE(ABORT, 'command history is append-only'); END;

CREATE TRIGGER authority_change_authorization_requires_command_role_and_term
BEFORE INSERT ON authority_change_authorizations
BEGIN
  SELECT RAISE(ABORT, 'authority change lacks a current signed command and authorized role')
  WHERE NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.target_kind') IS NOT NEW.target_kind
     OR json_extract(NEW.canonical_json, '$.target_id') IS NOT NEW.target_id
     OR json_extract(NEW.canonical_json, '$.replacement_target_id') IS NOT NEW.replacement_target_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.action') IS NOT NEW.action
     OR json_extract(NEW.canonical_json, '$.actor_principal_id') IS NOT NEW.actor_principal_id
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM commands c
       JOIN command_authorizations ca ON ca.command_id = c.id
       JOIN principals p ON p.id = NEW.actor_principal_id
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'control_plane'
       JOIN principals signer ON signer.id = NEW.signer_principal_id
       JOIN leader_terms lt ON lt.term = NEW.leader_term
       JOIN control_state ctl ON ctl.singleton = 1
       WHERE c.id = NEW.command_id
         AND c.command_type = 'authority.invalidate'
         AND c.state = 'authorized'
         AND c.principal_id = NEW.actor_principal_id
         AND c.project_id IS NEW.project_id
         AND c.expires_at_ms >= NEW.created_at_ms
         AND ca.actor_principal_id = NEW.actor_principal_id
         AND ca.project_id IS NEW.project_id
         AND ca.command_type = c.command_type
         AND ca.payload_digest = c.payload_digest
         AND ca.leader_term = NEW.leader_term
         AND ca.authorization_expires_at_ms >= NEW.created_at_ms
         AND ca.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
         AND json_extract(c.payload_json, '$.target_kind') = NEW.target_kind
         AND json_extract(c.payload_json, '$.target_id') = NEW.target_id
         AND json_extract(c.payload_json, '$.replacement_target_id') IS NEW.replacement_target_id
         AND json_extract(c.payload_json, '$.project_id') IS NEW.project_id
         AND json_extract(c.payload_json, '$.action') = NEW.action
         AND p.state = 'active'
         AND signer.kind = 'service'
         AND lt.state = 'active'
         AND ctl.current_term = NEW.leader_term
         AND (
           (NEW.project_id IS NULL AND EXISTS (
             SELECT 1 FROM principal_global_roles pgr
             WHERE pgr.principal_id = NEW.actor_principal_id
               AND pgr.role IN ('admin','operator')
               AND pgr.revoked_at_ms IS NULL
           ))
           OR (NEW.project_id IS NOT NULL AND EXISTS (
             SELECT 1 FROM principal_project_roles ppr
             WHERE ppr.principal_id = NEW.actor_principal_id
               AND ppr.project_id = NEW.project_id
               AND ppr.role IN ('owner','operator','approver','risk_acceptor')
               AND ppr.revoked_at_ms IS NULL
           ))
         )
     );
END;

CREATE TRIGGER authority_change_authorizations_no_update
BEFORE UPDATE ON authority_change_authorizations
BEGIN SELECT RAISE(ABORT, 'authority change authorizations are immutable'); END;

CREATE TRIGGER authority_change_authorizations_no_delete
BEFORE DELETE ON authority_change_authorizations
BEGIN SELECT RAISE(ABORT, 'authority change authorizations are immutable'); END;

CREATE TRIGGER reconciliation_decision_requires_current_signed_observation
BEFORE INSERT ON reconciliation_decisions
BEGIN
  SELECT RAISE(ABORT, 'reconciliation decision requires exact current subject-scoped evidence')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 60000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.decision_no') IS NOT NEW.decision_no
     OR json_extract(NEW.canonical_json, '$.subject_generation') IS NOT NEW.subject_generation
     OR json_extract(NEW.canonical_json, '$.resolved_state') IS NOT NEW.resolved_state
     OR json_extract(NEW.canonical_json, '$.provider_lookup_key') IS NOT NEW.provider_lookup_key
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.observed_process_state') IS NOT NEW.observed_process_state
     OR json_extract(NEW.canonical_json, '$.observed_provider_state') IS NOT NEW.observed_provider_state
     OR json_extract(NEW.canonical_json, '$.provider_observation_id') IS NOT NEW.provider_observation_id
     OR json_extract(NEW.canonical_json, '$.subject_leader_term') IS NOT NEW.subject_leader_term
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NEW.decision_no <> COALESCE((
       SELECT MAX(prior.decision_no) + 1
       FROM reconciliation_decisions prior
       WHERE prior.subject_kind = NEW.subject_kind
         AND prior.subject_id = NEW.subject_id
     ), 1)
     OR (NEW.subject_kind IN ('merge_request','merge_attempt','external_effect','external_effect_attempt')
       AND (
         NEW.process_identity IS NOT NULL
         OR NEW.observed_process_state <> 'not_applicable'
         OR NOT EXISTS (
           SELECT 1
           FROM provider_operation_observations observation
           WHERE observation.id = NEW.provider_observation_id
             AND observation.subject_kind = NEW.subject_kind
             AND observation.subject_id = NEW.subject_id
             AND observation.provider_lookup_key = NEW.provider_lookup_key
             AND observation.observed_state = NEW.observed_provider_state
             AND observation.evidence_manifest_digest = NEW.evidence_manifest_digest
             AND observation.observed_at_ms <= NEW.observed_at_ms
             AND (
               (observation.observed_state = 'completed' AND NEW.resolved_state = 'succeeded')
               OR (observation.observed_state IN ('failed','cancelled') AND NEW.resolved_state = 'failed')
               OR (observation.observed_state = 'absent'
                   AND NEW.resolved_state IN ('failed','integrating','executing'))
               OR (observation.observed_state = 'unreachable'
                   AND NEW.resolved_state IN ('unknown','manual_reconcile'))
             )
         )
         OR NOT (
           (NEW.subject_kind = 'merge_request' AND EXISTS (
             SELECT 1 FROM merge_requests subject
             WHERE subject.id = NEW.subject_id
               AND subject.state = 'unknown'
               AND subject.provider_idempotency_key = NEW.provider_lookup_key
               AND subject.claim_token = NEW.subject_generation
               AND subject.claim_leader_term = NEW.subject_leader_term
               AND NEW.observed_at_ms >= subject.finished_at_ms
           ))
           OR (NEW.subject_kind = 'merge_attempt' AND EXISTS (
             SELECT 1 FROM merge_attempts subject
             JOIN merge_requests parent ON parent.id = subject.merge_request_id
             WHERE subject.id = NEW.subject_id
               AND subject.state = 'unknown'
               AND parent.provider_idempotency_key = NEW.provider_lookup_key
               AND CAST(subject.attempt_no AS TEXT) = NEW.subject_generation
               AND parent.claim_leader_term = NEW.subject_leader_term
               AND NEW.observed_at_ms >= subject.finished_at_ms
           ))
           OR (NEW.subject_kind = 'external_effect' AND EXISTS (
             SELECT 1 FROM external_effects subject
             WHERE subject.id = NEW.subject_id
               AND subject.state = 'unknown'
               AND subject.remote_idempotency_key = NEW.provider_lookup_key
               AND subject.claim_token = NEW.subject_generation
               AND subject.claim_leader_term = NEW.subject_leader_term
               AND NEW.observed_at_ms >= subject.finished_at_ms
           ))
           OR (NEW.subject_kind = 'external_effect_attempt' AND EXISTS (
             SELECT 1 FROM external_effect_attempts subject
             JOIN external_effects parent ON parent.id = subject.external_effect_id
             WHERE subject.id = NEW.subject_id
               AND subject.state = 'unknown'
               AND parent.remote_idempotency_key = NEW.provider_lookup_key
               AND CAST(subject.attempt_no AS TEXT) = NEW.subject_generation
               AND parent.claim_leader_term = NEW.subject_leader_term
               AND NEW.observed_at_ms >= subject.finished_at_ms
           ))
         )
       ))
     OR NOT EXISTS (
       SELECT 1
       FROM principals p
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
       JOIN principal_global_roles pgr
         ON pgr.principal_id = p.id
        AND pgr.role = 'operator'
        AND pgr.revoked_at_ms IS NULL
       JOIN leader_terms lt ON lt.term = NEW.leader_term
       JOIN control_state ctl ON ctl.current_term = NEW.leader_term
       JOIN artifact_manifests am ON am.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = am.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE p.id = NEW.signer_principal_id
         AND p.kind = 'service'
         AND p.state = 'active'
         AND (
           (NEW.subject_kind IN ('dispatch_receipt','runtime_intent','runtime_session',
                                 'managed_intent','managed_session','attempt')
             AND sk.key_purpose = 'runtime_supervisor')
           OR
           (NEW.subject_kind IN ('runtime_call_lease','budget_reservation',
                                 'merge_request','merge_attempt',
                                 'external_effect','external_effect_attempt')
             AND sk.key_purpose = 'provider_observer')
         )
         AND lt.state = 'active'
         AND NEW.leader_term >= NEW.subject_leader_term
     );

  SELECT RAISE(ABORT, 'reconciliation decision signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'reconciliation_decision'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
  );
END;

