CREATE TRIGGER dispatch_receipt_unknown_exit_requires_reconciliation
BEFORE UPDATE OF state ON dispatch_receipts
WHEN OLD.state = 'unknown' AND NEW.state <> OLD.state
BEGIN
  SELECT RAISE(ABORT, 'unknown dispatch receipt needs signed terminal reconciliation')
  WHERE NOT EXISTS (
    SELECT 1 FROM reconciliation_decisions d
    WHERE d.subject_kind = 'dispatch_receipt'
      AND d.subject_id = NEW.dispatch_key
      AND d.resolved_state = NEW.state
      AND d.process_identity IS NEW.process_identity
      AND d.provider_lookup_key = NEW.model_call_id
      AND d.observed_at_ms >= NEW.received_at_ms
      AND d.subject_leader_term = (SELECT leader_term FROM attempts WHERE id = NEW.attempt_id)
      AND d.observed_process_state IN ('dead','absent')
      AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
  );
END;

