      AND d.process_identity = NEW.process_identity
      AND d.provider_lookup_key = NEW.provider_idempotency_key
      AND d.observed_at_ms >= NEW.created_at_ms
      AND d.subject_leader_term = NEW.leader_term
      AND d.observed_process_state IN ('dead','absent')
      AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
