    WHERE d.subject_kind = 'runtime_call_lease'
      AND d.subject_id = NEW.id
      AND d.resolved_state = NEW.state
      AND d.process_identity IS NULL
      AND d.provider_lookup_key = NEW.provider_call_key
      AND d.observed_at_ms >= NEW.created_at_ms
      AND d.observed_process_state = 'not_applicable'
      AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
      AND NOT EXISTS (
        SELECT 1 FROM reconciliation_decisions later
        WHERE later.subject_kind = d.subject_kind
          AND later.subject_id = d.subject_id
          AND later.decision_no > d.decision_no
      )
  );
END;

CREATE TRIGGER ingress_cursor_is_monotonic
BEFORE UPDATE OF last_committed_sequence, revision ON ingress_cursors
BEGIN
  SELECT RAISE(ABORT, 'ingress cursor must advance monotonically with one revision')
  WHERE NEW.last_committed_sequence <> OLD.last_committed_sequence + 1
     OR NEW.revision <> OLD.revision + 1
     OR NEW.updated_at_ms < OLD.updated_at_ms
     OR NEW.updated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.updated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1 FROM commands c
       WHERE c.source = NEW.source
         AND c.partition_key = NEW.partition_key
         AND c.source_sequence = NEW.last_committed_sequence
         AND c.received_at_ms <= NEW.updated_at_ms
         AND c.state IN ('applied','rejected','failed')
         AND c.completed_at_ms IS NOT NULL
         AND c.completed_at_ms <= NEW.updated_at_ms
         AND c.result_json IS NOT NULL
         AND (c.state <> 'applied' OR EXISTS (
           SELECT 1 FROM command_consumptions consumption
           WHERE consumption.command_id = c.id
             AND consumption.consumed_at_ms = c.completed_at_ms
         ))
     );
END;

CREATE TRIGGER ingress_cursors_enter_zero
BEFORE INSERT ON ingress_cursors
WHEN NEW.last_committed_sequence <> 0 OR NEW.revision <> 0
BEGIN SELECT RAISE(ABORT, 'ingress cursor must enter at sequence/revision zero'); END;

CREATE TRIGGER ingress_cursor_identity_is_immutable
BEFORE UPDATE OF source, partition_key ON ingress_cursors
BEGIN SELECT RAISE(ABORT, 'ingress cursor identity is immutable'); END;

CREATE TRIGGER ingress_cursors_no_delete
BEFORE DELETE ON ingress_cursors
BEGIN SELECT RAISE(ABORT, 'ingress cursor history cannot be deleted'); END;

CREATE TRIGGER dispatch_bundle_commit_is_exact_complete_and_signed
BEFORE INSERT ON dispatch_bundle_commits
BEGIN
  SELECT RAISE(ABORT, 'dispatch bundle commit is stale, incomplete, or not exact')
  WHERE NEW.committed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.committed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.attempt_id') IS NOT NEW.attempt_id
     OR json_extract(NEW.canonical_json, '$.node_version_id') IS NOT NEW.node_version_id
     OR json_extract(NEW.canonical_json, '$.work_packet_digest') IS NOT NEW.work_packet_digest
     OR json_extract(NEW.canonical_json, '$.outbox_id') IS NOT NEW.outbox_id
     OR json_extract(NEW.canonical_json, '$.lease_id') IS NOT NEW.lease_id
     OR json_extract(NEW.canonical_json, '$.budget_reservation_id') IS NOT NEW.budget_reservation_id
     OR json_extract(NEW.canonical_json, '$.process_resource_reservation_id') IS NOT NEW.process_resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.active_call_resource_reservation_id') IS NOT NEW.active_call_resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.fairness_dispatch_permit_digest') IS NOT NEW.fairness_dispatch_permit_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.committed_at_ms') IS NOT NEW.committed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM attempts attempt
       JOIN node_versions node
         ON node.id = attempt.node_version_id AND node.state = 'ready'
       JOIN work_packets packet
         ON packet.digest = NEW.work_packet_digest AND packet.attempt_id = attempt.id
       JOIN outbox message
         ON message.id = NEW.outbox_id
        AND message.attempt_id = attempt.id
        AND message.topic = 'dispatch'
        AND message.aggregate_type = 'attempt'
        AND message.aggregate_id = attempt.id
        AND message.destination_executor_id = attempt.executor_id
        AND message.idempotency_key = attempt.dispatch_key
        AND message.work_packet_digest = packet.digest
        AND message.state = 'pending'
       JOIN leases lease
         ON lease.id = NEW.lease_id
        AND lease.attempt_id = attempt.id
        AND lease.executor_slot_id = attempt.executor_slot_id
        AND lease.fence = attempt.fence
        AND lease.leader_term = attempt.leader_term
        AND lease.state = 'active'
       JOIN charge_subjects subject
         ON subject.attempt_id = attempt.id AND subject.scope_kind = 'attempt'
       JOIN budget_reservations budget
         ON budget.id = NEW.budget_reservation_id
        AND budget.charge_subject_id = subject.id
        AND budget.amount_micro_usd = attempt.required_reservation_micro_usd
        AND budget.state = 'held'
       JOIN fairness_dispatch_permits fairness_permit
         ON fairness_permit.digest = NEW.fairness_dispatch_permit_digest
        AND fairness_permit.project_id = attempt.project_id
        AND fairness_permit.node_version_id = node.id
        AND fairness_permit.executor_id = attempt.executor_id
        AND fairness_permit.leader_term = attempt.leader_term
       JOIN executors executor ON executor.id = attempt.executor_id
       JOIN fairness_state fairness
         ON fairness.project_id = attempt.project_id
        AND fairness.pool = executor.pool
        AND fairness.revision = fairness_permit.expected_fairness_revision
        AND fairness.scheduler_epoch = fairness_permit.expected_scheduler_epoch
        AND fairness.leader_term = attempt.leader_term
       JOIN fairness_policies fairness_policy
         ON fairness_policy.pool = executor.pool
        AND fairness_policy.policy_digest = fairness_permit.fairness_policy_digest
       JOIN leader_terms term ON term.term = attempt.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = attempt.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE attempt.id = NEW.attempt_id
         AND attempt.state = 'created'
         AND attempt.fairness_dispatch_permit_digest = fairness_permit.digest
         AND fairness_permit.pool = executor.pool
         AND fairness_permit.estimated_cost_units = node.estimated_cost_units
         AND node.id = NEW.node_version_id
         AND NEW.leader_term = attempt.leader_term
         AND fairness_permit.expires_at_ms >= NEW.committed_at_ms
         AND lease.expires_at_ms > NEW.committed_at_ms
         AND control.dispatch_enabled = 1
         AND control.admission_mode = 'open'
         AND control.kill_switch = 0
         AND (
           (executor.fresh_session_required = 1
             AND NEW.process_resource_reservation_id IS NOT NULL
             AND NEW.active_call_resource_reservation_id IS NULL
             AND EXISTS (
               SELECT 1 FROM resource_reservations resource
               WHERE resource.id = NEW.process_resource_reservation_id
                 AND resource.charge_subject_id = subject.id
                 AND resource.reservation_kind = 'process'
                 AND resource.state = 'held'
             ))
           OR (executor.fresh_session_required = 0 AND executor.id <> 'rick'
             AND NEW.process_resource_reservation_id IS NOT NULL
             AND NEW.active_call_resource_reservation_id IS NOT NULL
             AND EXISTS (
               SELECT 1
               FROM runtime_sessions session
               JOIN charge_subjects process_subject
                 ON process_subject.runtime_intent_id = session.runtime_intent_id
                AND process_subject.scope_kind = 'project_runtime'
               JOIN resource_reservations process_resource
                 ON process_resource.charge_subject_id = process_subject.id
               WHERE session.executor_id = attempt.executor_id
                 AND session.project_id = attempt.project_id
                 AND session.project_slot_generation = attempt.project_slot_generation
                 AND session.state IN ('starting','running')
                 AND process_resource.id = NEW.process_resource_reservation_id
                 AND process_resource.reservation_kind = 'process'
                 AND process_resource.state = 'held'
             )
             AND EXISTS (
               SELECT 1 FROM resource_reservations call_resource
               WHERE call_resource.id = NEW.active_call_resource_reservation_id
                 AND call_resource.charge_subject_id = subject.id
                 AND call_resource.reservation_kind = 'active_call'
                 AND call_resource.state = 'held'
             ))
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'dispatch_bundle_commit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.committed_at_ms - 5000 AND NEW.committed_at_ms
     );
END;

CREATE TRIGGER dispatch_bundle_commit_consumes_fairness_turn
AFTER INSERT ON dispatch_bundle_commits
BEGIN
  UPDATE fairness_state
  SET scheduler_epoch = scheduler_epoch + 1,
      deficit_units = min(
        (SELECT policy.max_deficit_units FROM fairness_policies policy
         WHERE policy.pool = fairness_state.pool),
        max(
          -(SELECT policy.max_deficit_units FROM fairness_policies policy
            WHERE policy.pool = fairness_state.pool),
          deficit_units
            + (SELECT policy.quantum_units FROM fairness_policies policy
               WHERE policy.pool = fairness_state.pool)
              * (SELECT CASE project.priority
                   WHEN 0 THEN 8 WHEN 1 THEN 4 WHEN 2 THEN 2 ELSE 1 END
                 FROM projects project WHERE project.id = fairness_state.project_id)
            - CASE WHEN fairness_state.project_id = (
                SELECT attempt.project_id FROM attempts attempt WHERE attempt.id = NEW.attempt_id
              ) THEN (
                SELECT node.estimated_cost_units FROM node_versions node
                WHERE node.id = NEW.node_version_id
              ) ELSE 0 END
        )
      ),
      last_dispatch_at_ms = CASE WHEN project_id = (
        SELECT attempt.project_id FROM attempts attempt WHERE attempt.id = NEW.attempt_id
      ) THEN NEW.committed_at_ms ELSE last_dispatch_at_ms END,
      dispatch_count = dispatch_count + CASE WHEN project_id = (
        SELECT attempt.project_id FROM attempts attempt WHERE attempt.id = NEW.attempt_id
      ) THEN 1 ELSE 0 END,
      leader_term = NEW.leader_term,
      revision = revision + 1
  WHERE pool = (
      SELECT executor.pool FROM attempts attempt
      JOIN executors executor ON executor.id = attempt.executor_id
      WHERE attempt.id = NEW.attempt_id
    )
    AND EXISTS (
      SELECT 1 FROM runs backlog_run
      JOIN node_versions backlog_node ON backlog_node.run_id = backlog_run.id
      JOIN projects backlog_project ON backlog_project.id = backlog_run.project_id
      WHERE backlog_run.project_id = fairness_state.project_id
        AND backlog_run.state = 'active'
        AND backlog_project.state IN ('admitted','active')
        AND backlog_node.required_pool = fairness_state.pool
        AND backlog_node.state = 'ready'
    );
END;

