CREATE TRIGGER outbox_enters_pending
BEFORE INSERT ON outbox
WHEN NEW.state <> 'pending'
BEGIN SELECT RAISE(ABORT, 'outbox messages must enter through pending'); END;

CREATE TRIGGER dispatch_outbox_matches_attempt
BEFORE INSERT ON outbox
WHEN NEW.topic = 'dispatch'
BEGIN
  SELECT RAISE(ABORT, 'dispatch outbox row does not match attempt/packet/executor')
  WHERE NEW.attempt_id IS NULL
     OR NEW.destination_executor_id IS NULL
     OR NEW.work_packet_digest IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM attempts a
       JOIN work_packets wp ON wp.attempt_id = a.id
       WHERE a.id = NEW.attempt_id
         AND a.executor_id = NEW.destination_executor_id
         AND a.dispatch_key = NEW.idempotency_key
         AND wp.digest = NEW.work_packet_digest
         AND NEW.payload_json = wp.canonical_json
         AND NEW.payload_digest = wp.digest
     );
END;

CREATE TRIGGER dispatch_receipts_enter_received
BEFORE INSERT ON dispatch_receipts
WHEN NEW.state <> 'received'
BEGIN SELECT RAISE(ABORT, 'dispatch receipts must enter through received'); END;

CREATE TRIGGER dispatch_receipts_enter_without_launch_identity
BEFORE INSERT ON dispatch_receipts
WHEN NEW.launch_claim_token IS NOT NULL
  OR NEW.launch_claim_until_ms IS NOT NULL
  OR NEW.model_call_id IS NOT NULL
  OR NEW.process_identity IS NOT NULL
  OR NEW.launched_at_ms IS NOT NULL
  OR NEW.completed_at_ms IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'received dispatch cannot preclaim a launch identity'); END;

CREATE TRIGGER dispatch_receipt_matches_outbox
BEFORE INSERT ON dispatch_receipts
BEGIN
  SELECT RAISE(ABORT, 'dispatch receipt does not match committed outbox payload')
  WHERE NOT EXISTS (
    SELECT 1 FROM outbox o
    WHERE o.topic = 'dispatch'
      AND o.attempt_id = NEW.attempt_id
      AND o.destination_executor_id = NEW.executor_id
      AND o.idempotency_key = NEW.dispatch_key
      AND o.payload_digest = NEW.payload_digest
      AND o.state IN ('sent','unknown','acked')
  );
END;

CREATE TRIGGER dispatch_receipt_process_identity_is_globally_unique
BEFORE UPDATE OF process_identity ON dispatch_receipts
WHEN NEW.process_identity IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'receipt process identity is not valid for the executor lifecycle')
  WHERE NOT EXISTS (
      SELECT 1 FROM executors e
      WHERE e.id = NEW.executor_id
        AND (
          (e.fresh_session_required = 1
            AND NOT EXISTS (
              SELECT 1 FROM dispatch_receipts prior
              WHERE prior.process_identity = NEW.process_identity
                AND prior.dispatch_key <> NEW.dispatch_key
            )
            AND NOT EXISTS (
              SELECT 1 FROM runtime_intents ri
              WHERE ri.process_identity = NEW.process_identity
            )
            AND NOT EXISTS (
              SELECT 1 FROM managed_service_intents mi
              WHERE mi.process_identity = NEW.process_identity
            ))
          OR (e.fresh_session_required = 0 AND EXISTS (
            SELECT 1
            FROM attempts a
            JOIN runtime_sessions rs
              ON rs.executor_id = a.executor_id
             AND rs.project_id = a.project_id
             AND rs.project_slot_generation = a.project_slot_generation
            JOIN runtime_intents ri ON ri.id = rs.runtime_intent_id
            WHERE a.id = NEW.attempt_id
              AND rs.process_identity = NEW.process_identity
              AND ri.process_identity = NEW.process_identity
              AND rs.state = 'running'
              AND ri.state = 'launched'
          ))
        )
    );
END;

CREATE TRIGGER runtime_intents_enter_prepared
BEFORE INSERT ON runtime_intents
WHEN NEW.state <> 'prepared'
BEGIN SELECT RAISE(ABORT, 'runtime intents must enter through prepared'); END;

CREATE TRIGGER runtime_intent_process_identity_is_globally_unique
BEFORE INSERT ON runtime_intents
BEGIN
  SELECT RAISE(ABORT, 'persistent process identity collides with a fresh or managed launch')
  WHERE EXISTS (
      SELECT 1 FROM dispatch_receipts dr
      WHERE dr.process_identity = NEW.process_identity
    )
    OR EXISTS (
      SELECT 1 FROM managed_service_intents mi
      WHERE mi.process_identity = NEW.process_identity
    );
END;

CREATE TRIGGER runtime_intent_matches_persistent_executor_scope
BEFORE INSERT ON runtime_intents
BEGIN
  SELECT RAISE(ABORT, 'runtime intent does not match persistent executor scope/catalog')
  WHERE NOT EXISTS (
    SELECT 1
    FROM executors e
    JOIN executor_slots es ON es.executor_id = e.id
    JOIN leader_terms lt ON lt.term = NEW.leader_term
    JOIN control_state cs ON cs.singleton = 1
    WHERE e.id = NEW.executor_id
      AND es.id = NEW.executor_slot_id
      AND e.pool = 'fable'
      AND e.fresh_session_required = 0
      AND e.runtime_catalog_digest = NEW.runtime_catalog_digest
      AND es.state = 'leased'
      AND es.fence_counter = NEW.fence
      AND lt.state = 'active'
      AND cs.current_term = NEW.leader_term
      AND cs.kill_switch = 0
      AND (
        (NEW.session_scope = 'portfolio' AND e.id = 'rick'
          AND NEW.scope_epoch = cs.portfolio_epoch)
        OR (NEW.session_scope = 'project_generation' AND e.id <> 'rick'
          AND cs.dispatch_enabled = 1
          AND cs.admission_mode = 'open'
          AND NEW.scope_epoch = NEW.project_slot_generation
          AND EXISTS (
            SELECT 1 FROM project_slots ps
            WHERE ps.slot_no = NEW.project_slot_no
              AND ps.project_id = NEW.project_id
              AND ps.generation = NEW.project_slot_generation
              AND ps.orchestrator_executor_id = NEW.executor_id
          ))
      )
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = NEW.runtime_catalog_digest
      )
  );
END;

CREATE TRIGGER runtime_intent_claim_requires_resource
BEFORE UPDATE OF state ON runtime_intents
WHEN OLD.state = 'prepared' AND NEW.state = 'launch_claimed'
BEGIN
  SELECT RAISE(ABORT, 'runtime launch claim requires token/deadline and held resource')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM leader_terms lt
       JOIN control_state cs ON cs.singleton = 1
       JOIN executor_slots es ON es.id = NEW.executor_slot_id
       WHERE lt.term = NEW.leader_term
         AND lt.state = 'active'
         AND cs.current_term = NEW.leader_term
         AND (
           (cs.dispatch_enabled = 1 AND cs.admission_mode = 'open')
           OR (NEW.session_scope = 'portfolio' AND EXISTS (
             SELECT 1
             FROM bootstrap_manifests bm
             JOIN signing_keys bsk ON bsk.key_id = bm.signer_key_id
             JOIN bootstrap_executor_bindings beb
               ON beb.bootstrap_manifest_digest = bm.digest
              AND beb.executor_id = 'rick'
             WHERE bm.digest = cs.bootstrap_manifest_digest
               AND bsk.state = 'active'
               AND (bsk.expires_at_ms IS NULL OR bsk.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND beb.executor_id = NEW.executor_id
               AND beb.runtime_catalog_digest = NEW.runtime_catalog_digest
           ))
         )
         AND cs.kill_switch = 0
         AND es.fence_counter = NEW.fence
         AND es.state = 'leased'
     )
     OR NOT EXISTS (
       SELECT 1
       FROM runtime_catalogs rc
       JOIN executors e ON e.id = NEW.executor_id
       JOIN signing_keys sk ON sk.key_id = rc.signer_key_id
       JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
       JOIN signing_keys rpask ON rpask.key_id = rpa.signer_key_id
       WHERE rc.digest = NEW.runtime_catalog_digest
         AND e.runtime_catalog_digest = rc.digest
         AND rc.effective_at_ms <= (unixepoch('subsec') * 1000)
         AND sk.state = 'active'
         AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= (unixepoch('subsec') * 1000))
         AND rpask.state = 'active'
         AND (rpask.expires_at_ms IS NULL OR rpask.expires_at_ms >= (unixepoch('subsec') * 1000))
         AND rpa.probe_contract_digest = rc.probe_contract_digest
         AND rpa.binary_digest = rc.binary_digest
         AND rpa.actual_model = rc.resolved_model
         AND rpa.actual_model_family = rc.resolved_model_family
         AND rpa.actual_effort = rc.resolved_effort
         AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                  AND (unixepoch('subsec') * 1000) + 5000
         AND NOT EXISTS (
           SELECT 1 FROM runtime_catalog_invalidations rci
           WHERE rci.runtime_catalog_digest = rc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (
             e.config_digest, rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
             rc.provider_proxy_profile_digest, rc.io_protocol_digest,
             rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
           )
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM charge_subjects cs
       JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
       WHERE cs.runtime_intent_id = NEW.id
         AND cs.scope_kind = CASE NEW.session_scope
           WHEN 'portfolio' THEN 'portfolio_runtime'
           ELSE 'project_runtime'
         END
         AND rr.state = 'held'
     );
END;

CREATE TRIGGER runtime_intent_final_permit_revalidates_authority
BEFORE UPDATE OF state ON runtime_intents
WHEN OLD.state = 'launch_claimed' AND NEW.state = 'launch_permitted'
BEGIN
  SELECT RAISE(ABORT, 'persistent launch permit lost term, fence, bootstrap, catalog, or resource authority')
  WHERE OLD.claim_until_ms IS NULL
     OR OLD.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM leader_terms lt
       JOIN control_state ctl ON ctl.singleton = 1
       JOIN executor_slots es ON es.id = NEW.executor_slot_id
       JOIN executors e ON e.id = NEW.executor_id
       JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
       JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
       JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
       JOIN signing_keys rpask ON rpask.key_id = rpa.signer_key_id
       JOIN charge_subjects cs ON cs.runtime_intent_id = NEW.id
       JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
       JOIN resource_profiles prof ON prof.digest = rr.resource_profile_digest
       JOIN current_host_capacity hc ON hc.singleton = 1
       WHERE lt.term = NEW.leader_term
         AND lt.state = 'active'
         AND ctl.current_term = NEW.leader_term
         AND ctl.kill_switch = 0
         AND es.state = 'leased'
         AND es.fence_counter = NEW.fence
         AND rsk.state = 'active'
         AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= (unixepoch('subsec') * 1000))
         AND rpask.state = 'active'
         AND (rpask.expires_at_ms IS NULL OR rpask.expires_at_ms >= (unixepoch('subsec') * 1000))
         AND rpa.probe_contract_digest = rc.probe_contract_digest
         AND rpa.binary_digest = rc.binary_digest
         AND rpa.actual_model = rc.resolved_model
         AND rpa.actual_model_family = rc.resolved_model_family
         AND rpa.actual_effort = rc.resolved_effort
         AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                  AND (unixepoch('subsec') * 1000) + 5000
         AND NOT EXISTS (
           SELECT 1 FROM runtime_catalog_invalidations rci
           WHERE rci.runtime_catalog_digest = rc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (
             e.config_digest, rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
             rc.provider_proxy_profile_digest, rc.io_protocol_digest,
             rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
           )
         )
         AND rr.reservation_kind = 'process'
         AND rr.state = 'held'
         AND prof.host_policy_digest = hc.resource_policy_digest
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations pi
           WHERE pi.policy_digest IN (prof.digest, prof.host_policy_digest)
         )
         AND (
           (NEW.session_scope = 'project_generation'
             AND ctl.dispatch_enabled = 1 AND ctl.admission_mode = 'open')
           OR (NEW.session_scope = 'portfolio' AND EXISTS (
             SELECT 1
             FROM bootstrap_manifests bm
             JOIN signing_keys bsk ON bsk.key_id = bm.signer_key_id
             JOIN bootstrap_executor_bindings beb
               ON beb.bootstrap_manifest_digest = bm.digest
              AND beb.executor_id = NEW.executor_id
             WHERE bm.digest = ctl.bootstrap_manifest_digest
               AND bsk.state = 'active'
               AND (bsk.expires_at_ms IS NULL OR bsk.expires_at_ms >= (unixepoch('subsec') * 1000))
               AND beb.runtime_catalog_digest = NEW.runtime_catalog_digest
           ))
         )
     );

END;

CREATE TRIGGER runtime_intents_legal_state_transition
BEFORE UPDATE OF state ON runtime_intents
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal runtime-intent state transition')
  WHERE NOT (
    (OLD.state = 'prepared' AND NEW.state IN ('launch_claimed','cancelled','failed'))
    OR (OLD.state = 'launch_claimed' AND NEW.state IN ('launch_permitted','unknown','cancelled','failed'))
    OR (OLD.state = 'launch_permitted' AND NEW.state IN ('launched','unknown'))
    OR (OLD.state = 'launched' AND NEW.state IN ('terminated','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('terminated','failed','cancelled'))
  );
END;

CREATE TRIGGER runtime_intent_claim_identity_set_once
BEFORE UPDATE OF claim_token, claim_until_ms ON runtime_intents
WHEN (OLD.claim_token IS NOT NULL AND OLD.claim_token IS NOT NEW.claim_token)
  OR (OLD.claim_until_ms IS NOT NULL AND OLD.claim_until_ms IS NOT NEW.claim_until_ms)
BEGIN SELECT RAISE(ABORT, 'runtime-intent claim is immutable once set'); END;

CREATE TRIGGER runtime_intent_launch_requires_session
BEFORE UPDATE OF state ON runtime_intents
WHEN NEW.state = 'launched' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'runtime intent cannot become launched without recorded session')
  WHERE NOT EXISTS (
    SELECT 1 FROM runtime_sessions s
    WHERE s.runtime_intent_id = NEW.id AND s.state IN ('starting','running')
  );
END;

CREATE TRIGGER runtime_intent_termination_requires_dead_session
BEFORE UPDATE OF state ON runtime_intents
WHEN NEW.state = 'terminated' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'runtime intent cannot terminate before its session')
  WHERE NOT EXISTS (
    SELECT 1 FROM runtime_sessions s
    WHERE s.runtime_intent_id = NEW.id AND s.state = 'terminated'
  );
END;

CREATE TRIGGER runtime_intent_identity_is_immutable
BEFORE UPDATE OF id, executor_id, executor_slot_id, session_scope, project_id,
  project_slot_no, project_slot_generation, fence, leader_term,
  worker_instance_id, launch_identity, process_identity, provider_idempotency_key,
  scope_epoch, runtime_catalog_digest, created_at_ms
ON runtime_intents
BEGIN SELECT RAISE(ABORT, 'runtime intent identity is immutable'); END;

CREATE TRIGGER runtime_intents_no_delete
BEFORE DELETE ON runtime_intents
BEGIN SELECT RAISE(ABORT, 'runtime intent history is append-only'); END;

CREATE TRIGGER runtime_sessions_enter_starting
BEFORE INSERT ON runtime_sessions
WHEN NEW.state <> 'starting'
BEGIN SELECT RAISE(ABORT, 'runtime sessions must enter through starting'); END;

CREATE TRIGGER runtime_session_matches_executor_and_generation
BEFORE INSERT ON runtime_sessions
BEGIN
  SELECT RAISE(ABORT, 'runtime session does not match executor/generation/handshake')
  WHERE json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.runtime_intent_id') IS NOT NEW.runtime_intent_id
     OR json_extract(NEW.canonical_json, '$.executor_id') IS NOT NEW.executor_id
     OR json_extract(NEW.canonical_json, '$.executor_slot_id') IS NOT NEW.executor_slot_id
     OR json_extract(NEW.canonical_json, '$.session_scope') IS NOT NEW.session_scope
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.project_slot_no') IS NOT NEW.project_slot_no
     OR json_extract(NEW.canonical_json, '$.project_slot_generation') IS NOT NEW.project_slot_generation
     OR json_extract(NEW.canonical_json, '$.worker_instance_id') IS NOT NEW.worker_instance_id
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.provider_session_id') IS NOT NEW.provider_session_id
     OR json_extract(NEW.canonical_json, '$.runtime') IS NOT NEW.runtime
     OR json_extract(NEW.canonical_json, '$.runtime_version') IS NOT NEW.runtime_version
     OR json_extract(NEW.canonical_json, '$.actual_model') IS NOT NEW.actual_model
     OR json_extract(NEW.canonical_json, '$.actual_model_family') IS NOT NEW.actual_model_family
     OR json_extract(NEW.canonical_json, '$.actual_profile') IS NOT NEW.actual_profile
     OR json_extract(NEW.canonical_json, '$.fresh_context') IS NOT NEW.fresh_context
     OR json_extract(NEW.canonical_json, '$.private_home_digest') IS NOT NEW.private_home_digest
     OR json_extract(NEW.canonical_json, '$.sandbox_policy_digest') IS NOT NEW.sandbox_policy_digest
     OR json_extract(NEW.canonical_json, '$.handshake_digest') IS NOT NEW.handshake_digest
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.started_at_ms') IS NOT NEW.started_at_ms
     OR NOT EXISTS (
    SELECT 1
    FROM executors e
    JOIN executor_slots es ON es.executor_id = e.id
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.key_purpose = 'runtime_supervisor'
    JOIN principals supervisor ON supervisor.id = sk.principal_id
    JOIN principal_global_roles supervisor_role
      ON supervisor_role.principal_id = supervisor.id
     AND supervisor_role.role = 'operator'
     AND supervisor_role.revoked_at_ms IS NULL
    JOIN policies sp ON sp.digest = NEW.sandbox_policy_digest
    JOIN current_valid_keys ssk
      ON ssk.key_id = sp.signer_key_id
     AND ssk.key_purpose = 'control_plane'
    JOIN artifact_manifests home_manifest ON home_manifest.digest = NEW.private_home_digest
    JOIN artifact_manifests handshake_manifest ON handshake_manifest.digest = NEW.handshake_digest
    JOIN current_valid_keys home_key
      ON home_key.key_id = home_manifest.signer_key_id
     AND home_key.key_purpose = 'artifact_broker'
    JOIN current_valid_keys handshake_key
      ON handshake_key.key_id = handshake_manifest.signer_key_id
     AND handshake_key.key_purpose = 'artifact_broker'
    WHERE e.id = NEW.executor_id
      AND es.id = NEW.executor_slot_id
      AND e.runtime = NEW.runtime
      AND e.model = NEW.actual_model
      AND e.model_family = NEW.actual_model_family
      AND e.profile = NEW.actual_profile
      AND e.sandbox_policy_digest = NEW.sandbox_policy_digest
      AND sp.policy_type = 'sandbox'
      AND supervisor.kind = 'service'
      AND supervisor.state = 'active'
      AND (
        (NEW.session_scope = 'attempt' AND NEW.runtime_intent_id IS NULL)
        OR (NEW.session_scope IN ('portfolio','project_generation') AND EXISTS (
          SELECT 1 FROM runtime_intents ri
          WHERE ri.id = NEW.runtime_intent_id
            AND ri.executor_id = NEW.executor_id
            AND ri.executor_slot_id = NEW.executor_slot_id
            AND ri.session_scope = NEW.session_scope
            AND ri.project_id IS NEW.project_id
            AND ri.project_slot_no IS NEW.project_slot_no
            AND ri.project_slot_generation IS NEW.project_slot_generation
            AND ri.worker_instance_id = NEW.worker_instance_id
            AND ri.process_identity = NEW.process_identity
            AND ri.runtime_catalog_digest = e.runtime_catalog_digest
            AND ri.state = 'launch_permitted'
            AND NEW.started_at_ms <= ri.claim_until_ms
            AND (
              NEW.session_scope = 'portfolio'
              OR EXISTS (
                SELECT 1 FROM project_slots owner_slot
                WHERE owner_slot.slot_no = NEW.project_slot_no
                  AND owner_slot.project_id = NEW.project_id
                  AND owner_slot.generation = NEW.project_slot_generation
                  AND owner_slot.orchestrator_executor_id = NEW.executor_id
              )
            )
            AND EXISTS (
              SELECT 1
              FROM leader_terms lt
              JOIN control_state cs ON cs.singleton = 1
              JOIN executor_slots current_slot ON current_slot.id = ri.executor_slot_id
              WHERE lt.term = ri.leader_term
                AND lt.state = 'active'
                AND cs.current_term = ri.leader_term
                AND cs.kill_switch = 0
                AND current_slot.fence_counter = ri.fence
                AND current_slot.state = 'leased'
            )
        ))
      )
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = e.runtime_catalog_digest
      )
      AND EXISTS (
        SELECT 1
        FROM runtime_catalogs rc
        JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
        WHERE rc.digest = e.runtime_catalog_digest
          AND rc.effective_at_ms <= NEW.started_at_ms
          AND rsk.state = 'active'
          AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= NEW.started_at_ms)
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = NEW.sandbox_policy_digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest = e.config_digest
      )
      AND (
        (
          NEW.session_scope = 'portfolio'
          AND e.id = 'rick'
          AND e.pool = 'fable'
          AND e.fresh_session_required = 0
          AND NEW.fresh_context = 0
          AND es.state = 'leased'
        )
        OR (
          NEW.session_scope = 'project_generation'
          AND e.fresh_session_required = 0
          AND e.id <> 'rick'
          AND es.state = 'leased'
          AND EXISTS (
            SELECT 1 FROM project_slots ps
            WHERE ps.slot_no = NEW.project_slot_no
              AND ps.project_id = NEW.project_id
              AND ps.generation = NEW.project_slot_generation
          )
        )
        OR (
          NEW.session_scope = 'attempt'
          AND e.fresh_session_required = 1
          AND NEW.fresh_context = 1
          AND EXISTS (
            SELECT 1 FROM project_slots ps
            WHERE ps.slot_no = NEW.project_slot_no
              AND ps.project_id = NEW.project_id
              AND ps.generation = NEW.project_slot_generation
          )
          AND EXISTS (
            SELECT 1
            FROM attempts a
            JOIN leases l ON l.attempt_id = a.id
            JOIN dispatch_receipts dr ON dr.attempt_id = a.id
            WHERE a.executor_id = NEW.executor_id
              AND a.executor_slot_id = NEW.executor_slot_id
              AND a.project_id = NEW.project_id
              AND a.project_slot_no = NEW.project_slot_no
              AND a.project_slot_generation = NEW.project_slot_generation
              AND l.worker_instance_id = NEW.worker_instance_id
              AND l.state = 'active'
              AND dr.executor_id = NEW.executor_id
              AND dr.process_identity = NEW.process_identity
              AND dr.state = 'launched'
          )
        )
      )
  );
END;

CREATE TRIGGER attempt_session_binding_matches_authority
BEFORE INSERT ON attempt_session_bindings
BEGIN
  SELECT RAISE(ABORT, 'new attempt/session binding cannot already be unbound')
  WHERE NEW.unbound_at_ms IS NOT NULL;

  SELECT RAISE(ABORT, 'attempt/session binding does not match authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN runtime_sessions s ON s.id = NEW.runtime_session_id
    JOIN executors e ON e.id = a.executor_id
    JOIN dispatch_receipts dr ON dr.attempt_id = a.id
    WHERE a.id = NEW.attempt_id
      AND s.executor_id = a.executor_id
      AND s.executor_slot_id = a.executor_slot_id
      AND s.project_id = a.project_id
      AND s.project_slot_no = a.project_slot_no
      AND s.project_slot_generation = a.project_slot_generation
      AND s.worker_instance_id = (
        SELECT l.worker_instance_id FROM leases l WHERE l.attempt_id = a.id
      )
      AND s.runtime = a.runtime
      AND s.actual_model = a.model
      AND s.actual_model_family = a.model_family
      AND s.actual_profile = a.profile
      AND dr.executor_id = a.executor_id
      AND dr.process_identity = s.process_identity
      AND dr.state = 'launched'
      AND s.state IN ('starting','running')
      AND (
        (e.fresh_session_required = 1 AND s.fresh_context = 1)
        OR e.fresh_session_required = 0
      )
  );

  SELECT RAISE(ABORT, 'fresh executor session cannot bind more than one attempt')
  WHERE EXISTS (
    SELECT 1
    FROM executors e
    JOIN attempts a ON a.id = NEW.attempt_id AND a.executor_id = e.id
    JOIN attempt_session_bindings prior
      ON prior.runtime_session_id = NEW.runtime_session_id
    WHERE e.fresh_session_required = 1
  );
END;

CREATE TRIGGER attempt_session_binding_unbinds_once_after_terminal_attempt
BEFORE UPDATE OF unbound_at_ms ON attempt_session_bindings
BEGIN
  SELECT RAISE(ABORT, 'attempt/session binding can unbind once after attempt termination')
  WHERE OLD.unbound_at_ms IS NOT NULL
     OR NEW.unbound_at_ms IS NULL
     OR NEW.unbound_at_ms < OLD.bound_at_ms
     OR NEW.unbound_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1 FROM attempts a
       WHERE a.id = NEW.attempt_id
         AND a.state IN ('accepted','failed','expired','cancelled','stale','quarantined')
     )
     OR NOT EXISTS (
       SELECT 1
       FROM dispatch_receipts dr
       WHERE dr.attempt_id = NEW.attempt_id
         AND (
           dr.state = 'completed'
           OR EXISTS (
             SELECT 1 FROM reconciliation_decisions d
             WHERE d.subject_kind = 'dispatch_receipt'
               AND d.subject_id = dr.dispatch_key
               AND d.resolved_state = 'completed'
               AND d.observed_provider_state IN ('completed','failed','cancelled','absent')
           )
         )
     );
END;

CREATE TRIGGER runtime_sessions_legal_state_transition
BEFORE UPDATE OF state ON runtime_sessions
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal runtime-session state transition')
  WHERE NOT (
    (OLD.state = 'starting' AND NEW.state IN ('running','terminated','unknown'))
    OR (OLD.state = 'running' AND NEW.state IN ('terminating','terminated','unknown'))
    OR (OLD.state = 'terminating' AND NEW.state IN ('terminated','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state = 'terminated')
  );
END;

CREATE TRIGGER runtime_session_running_requires_resource_reservation
BEFORE UPDATE OF state ON runtime_sessions
WHEN OLD.state = 'starting' AND NEW.state = 'running'
BEGIN
  SELECT RAISE(ABORT, 'runtime session cannot run without its scoped resource reservation')
  WHERE NOT EXISTS (
    SELECT 1
    FROM charge_subjects cs
    JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
    WHERE rr.state = 'held'
      AND (
        (NEW.session_scope = 'portfolio'
          AND cs.scope_kind = 'portfolio_runtime'
          AND cs.runtime_intent_id = NEW.runtime_intent_id)
        OR (NEW.session_scope = 'project_generation'
          AND cs.scope_kind = 'project_runtime'
          AND cs.runtime_intent_id = NEW.runtime_intent_id
          AND cs.project_id = NEW.project_id)
        OR (NEW.session_scope = 'attempt'
          AND cs.scope_kind = 'attempt'
          AND EXISTS (
            SELECT 1 FROM attempt_session_bindings b
            WHERE b.runtime_session_id = NEW.id
              AND b.attempt_id = cs.attempt_id
          ))
      )
  );
END;

CREATE TRIGGER managed_service_sessions_enter_starting
BEFORE INSERT ON managed_service_sessions
WHEN NEW.state <> 'starting'
BEGIN SELECT RAISE(ABORT, 'managed service sessions must enter through starting'); END;

CREATE TRIGGER managed_service_intents_enter_prepared
BEFORE INSERT ON managed_service_intents
WHEN NEW.state <> 'prepared'
BEGIN SELECT RAISE(ABORT, 'managed service intents must enter through prepared'); END;

CREATE TRIGGER managed_service_process_identity_is_globally_unique
BEFORE INSERT ON managed_service_intents
BEGIN
  SELECT RAISE(ABORT, 'managed process identity collides with a fresh or persistent launch')
  WHERE EXISTS (
      SELECT 1 FROM dispatch_receipts dr
      WHERE dr.process_identity = NEW.process_identity
    )
    OR EXISTS (
      SELECT 1 FROM runtime_intents ri
      WHERE ri.process_identity = NEW.process_identity
    );
END;

CREATE TRIGGER managed_service_identity_is_signed_and_service_owned
BEFORE INSERT ON managed_service_identities
BEGIN
  SELECT RAISE(ABORT, 'managed service identity is not signed, active, or service-owned')
  WHERE NEW.workspace_root NOT LIKE '/usr/local/var/cortex-harness/%'
     OR instr(NEW.workspace_root, '..') <> 0
     OR instr(NEW.canonical_json, '/Users/') <> 0
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NEW.version <> (
       SELECT COALESCE(MAX(version),0) + 1
       FROM managed_service_identities WHERE service_alias = NEW.service_alias
     )
     OR NOT EXISTS (
       SELECT 1
       FROM principals p
       JOIN principals supervisor ON supervisor.id = NEW.signer_principal_id
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'control_plane'
       JOIN principal_global_roles supervisor_role
         ON supervisor_role.principal_id = supervisor.id
        AND supervisor_role.role = 'operator'
        AND supervisor_role.revoked_at_ms IS NULL
       JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
       JOIN current_valid_keys rsk
         ON rsk.key_id = rc.signer_key_id
        AND rsk.key_purpose = 'control_plane'
       JOIN policies sp ON sp.digest = NEW.sandbox_policy_digest
       JOIN current_valid_keys ssk
         ON ssk.key_id = sp.signer_key_id
        AND ssk.key_purpose = 'control_plane'
       JOIN configuration_artifacts cfg ON cfg.digest = NEW.config_digest
       JOIN artifact_manifests am ON am.digest = NEW.asset_manifest_digest
       JOIN current_valid_keys amk
         ON amk.key_id = am.signer_key_id
        AND amk.key_purpose = 'artifact_broker'
       JOIN sanitization_attestations sa
         ON sa.digest = NEW.sanitization_attestation_digest
        AND sa.subject_manifest_digest = NEW.asset_manifest_digest
        AND sa.rules_digest = NEW.sanitization_rules_digest
        AND sa.allowed_root = NEW.workspace_root
       JOIN current_valid_keys sak
         ON sak.key_id = sa.signer_key_id
        AND sak.key_purpose = 'schema_validator'
       WHERE p.id = NEW.principal_id
         AND p.state = 'active'
         AND supervisor.kind = 'service'
         AND supervisor.state = 'active'
         AND sp.policy_type = 'sandbox'
         AND cfg.artifact_kind = 'managed_service_config'
         AND NOT EXISTS (
           SELECT 1 FROM runtime_catalog_invalidations rci
           WHERE rci.runtime_catalog_digest = rc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations pi
           WHERE pi.policy_digest = sp.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (NEW.config_digest, sa.rules_digest)
         )
         AND json_extract(NEW.canonical_json, '$.service_alias') IS NEW.service_alias
         AND json_extract(NEW.canonical_json, '$.version') IS NEW.version
         AND json_extract(NEW.canonical_json, '$.principal_id') IS NEW.principal_id
         AND json_extract(NEW.canonical_json, '$.runtime_catalog_digest') IS NEW.runtime_catalog_digest
         AND json_extract(NEW.canonical_json, '$.sandbox_policy_digest') IS NEW.sandbox_policy_digest
         AND json_extract(NEW.canonical_json, '$.config_digest') IS NEW.config_digest
         AND json_extract(NEW.canonical_json, '$.workspace_root') IS NEW.workspace_root
         AND json_extract(NEW.canonical_json, '$.asset_manifest_digest') IS NEW.asset_manifest_digest
         AND json_extract(NEW.canonical_json, '$.sanitization_attestation_digest') IS NEW.sanitization_attestation_digest
         AND json_extract(NEW.canonical_json, '$.sanitization_rules_digest') IS NEW.sanitization_rules_digest
     );
END;

CREATE TRIGGER managed_service_identities_no_update
BEFORE UPDATE ON managed_service_identities
BEGIN SELECT RAISE(ABORT, 'managed service identities are immutable'); END;

CREATE TRIGGER managed_service_identities_no_delete
BEFORE DELETE ON managed_service_identities
BEGIN SELECT RAISE(ABORT, 'managed service identities are immutable'); END;

CREATE TRIGGER managed_service_identity_invalidation_is_authorized_rotation
BEFORE INSERT ON managed_service_identity_invalidations
BEGIN
  SELECT RAISE(ABORT, 'managed identity invalidation is unauthorized or not a forward rotation')
  WHERE NOT EXISTS (
      SELECT 1 FROM authority_change_authorizations a
      JOIN control_state ctl ON ctl.current_term = a.leader_term
      JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
      WHERE a.id = NEW.authorization_id
        AND a.target_kind = 'managed_identity'
        AND a.target_id = NEW.managed_identity_digest
        AND a.replacement_target_id IS NEW.replacement_identity_digest
        AND a.actor_principal_id = NEW.invalidated_by_principal_id
        AND a.action = CASE WHEN NEW.replacement_identity_digest IS NULL
                            THEN 'revoke' ELSE 'supersede' END
        AND a.expires_at_ms >= NEW.invalidated_at_ms
    )
    OR NOT EXISTS (
      SELECT 1 FROM principals p
      WHERE p.id = NEW.invalidated_by_principal_id AND p.state = 'active'
    )
    OR EXISTS (
      SELECT 1 FROM managed_service_intents mi
      WHERE mi.managed_identity_digest = NEW.managed_identity_digest
        AND mi.state IN ('prepared','launch_claimed','launch_permitted','launched','unknown')
    )
    OR (NEW.replacement_identity_digest IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM managed_service_identities old
      JOIN managed_service_identities next
        ON next.service_alias = old.service_alias
       AND next.version > old.version
       AND next.principal_id = old.principal_id
      WHERE old.digest = NEW.managed_identity_digest
        AND next.digest = NEW.replacement_identity_digest
    ));
END;

CREATE TRIGGER managed_service_identity_invalidations_no_update
BEFORE UPDATE ON managed_service_identity_invalidations
BEGIN SELECT RAISE(ABORT, 'managed identity invalidations are immutable'); END;

CREATE TRIGGER managed_service_identity_invalidations_no_delete
BEFORE DELETE ON managed_service_identity_invalidations
BEGIN SELECT RAISE(ABORT, 'managed identity invalidations are immutable'); END;

CREATE TRIGGER managed_service_intent_matches_scope
BEFORE INSERT ON managed_service_intents
BEGIN
  SELECT RAISE(ABORT, 'managed service intent does not match charge, authority, or catalog')
  WHERE NOT EXISTS (
    SELECT 1
    FROM charge_subjects cs
    JOIN principals p ON p.id = NEW.principal_id
    JOIN managed_service_identities msi
      ON msi.digest = NEW.managed_identity_digest
     AND msi.service_alias = NEW.service_alias
     AND msi.principal_id = NEW.principal_id
     AND msi.runtime_catalog_digest = NEW.runtime_catalog_digest
    JOIN policies sp ON sp.digest = msi.sandbox_policy_digest
    JOIN signing_keys ssk ON ssk.key_id = sp.signer_key_id
    JOIN leader_terms lt ON lt.term = NEW.leader_term
    JOIN control_state ctl ON ctl.singleton = 1
    JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
    JOIN signing_keys rsk ON rsk.key_id = rc.signer_key_id
    WHERE cs.id = NEW.charge_subject_id
      AND cs.scope_kind = 'service_operation'
      AND cs.service_operation_key = 'managed-runtime:' || NEW.id
      AND cs.billing_provider = rc.provider
      AND cs.billing_model = rc.resolved_model
      AND p.state = 'active'
      AND lt.state = 'active'
      AND ctl.current_term = NEW.leader_term
      AND ctl.portfolio_epoch = NEW.service_epoch
      AND ctl.kill_switch = 0
      AND ssk.state = 'active'
      AND (ssk.expires_at_ms IS NULL OR ssk.expires_at_ms >= NEW.created_at_ms)
      AND rsk.state = 'active'
      AND (rsk.expires_at_ms IS NULL OR rsk.expires_at_ms >= NEW.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = rc.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = msi.sandbox_policy_digest
      )
  );
END;

CREATE TRIGGER managed_service_intent_claim_requires_resource
BEFORE UPDATE OF state ON managed_service_intents
WHEN OLD.state = 'prepared' AND NEW.state = 'launch_claimed'
BEGIN
  SELECT RAISE(ABORT, 'managed launch claim requires current authority, expiry, and resource')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM leader_terms lt
       JOIN control_state ctl ON ctl.singleton = 1
       JOIN bootstrap_manifests bm ON bm.digest = ctl.bootstrap_manifest_digest
       JOIN current_valid_keys bsk
         ON bsk.key_id = bm.signer_key_id
        AND bsk.key_purpose = 'control_plane'
       JOIN bootstrap_managed_identity_bindings bmi
         ON bmi.bootstrap_manifest_digest = bm.digest
        AND bmi.service_alias = NEW.service_alias
        AND bmi.managed_identity_digest = NEW.managed_identity_digest
       JOIN managed_service_identities msi
         ON msi.digest = NEW.managed_identity_digest
        AND msi.service_alias = NEW.service_alias
        AND msi.principal_id = NEW.principal_id
        AND msi.runtime_catalog_digest = NEW.runtime_catalog_digest
       JOIN current_valid_keys msi_key
         ON msi_key.key_id = msi.signer_key_id
        AND msi_key.principal_id = msi.signer_principal_id
        AND msi_key.key_purpose = 'control_plane'
       JOIN artifact_manifests asset ON asset.digest = msi.asset_manifest_digest
       JOIN current_valid_keys asset_key
         ON asset_key.key_id = asset.signer_key_id
        AND asset_key.key_purpose = 'artifact_broker'
       JOIN sanitization_attestations sa
         ON sa.digest = msi.sanitization_attestation_digest
        AND sa.subject_manifest_digest = msi.asset_manifest_digest
        AND sa.rules_digest = msi.sanitization_rules_digest
        AND sa.allowed_root = msi.workspace_root
       JOIN current_valid_keys sa_key
         ON sa_key.key_id = sa.signer_key_id
        AND sa_key.principal_id = sa.signer_principal_id
        AND sa_key.key_purpose = 'schema_validator'
       JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
       JOIN current_valid_keys rsk
         ON rsk.key_id = rc.signer_key_id
        AND rsk.key_purpose = 'control_plane'
       JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
       JOIN current_valid_keys rpask
         ON rpask.key_id = rpa.signer_key_id
        AND rpask.key_purpose = 'runtime_supervisor'
       JOIN resource_reservations rr ON rr.charge_subject_id = NEW.charge_subject_id
       WHERE lt.term = NEW.leader_term
         AND lt.state = 'active'
         AND ctl.current_term = NEW.leader_term
         AND ctl.portfolio_epoch = NEW.service_epoch
         AND ctl.kill_switch = 0
         AND rr.state = 'held'
         AND rpa.probe_contract_digest = rc.probe_contract_digest
         AND rpa.binary_digest = rc.binary_digest
         AND rpa.actual_model = rc.resolved_model
         AND rpa.actual_model_family = rc.resolved_model_family
         AND rpa.actual_effort = rc.resolved_effort
         AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                  AND (unixepoch('subsec') * 1000) + 5000
         AND NOT EXISTS (
           SELECT 1 FROM runtime_catalog_invalidations rci
           WHERE rci.runtime_catalog_digest = rc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM managed_service_identity_invalidations mii
           WHERE mii.managed_identity_digest = msi.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (
             msi.config_digest, msi.sanitization_rules_digest,
             rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
             rc.provider_proxy_profile_digest, rc.io_protocol_digest,
             rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
           )
         )
     );
END;

CREATE TRIGGER managed_service_final_permit_revalidates_authority
BEFORE UPDATE OF state ON managed_service_intents
WHEN OLD.state = 'launch_claimed' AND NEW.state = 'launch_permitted'
BEGIN
  SELECT RAISE(ABORT, 'managed launch permit lost bootstrap, identity, catalog, policy, or resource authority')
  WHERE OLD.claim_until_ms IS NULL
     OR OLD.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM leader_terms lt
       JOIN control_state ctl ON ctl.singleton = 1
       JOIN bootstrap_manifests bm ON bm.digest = ctl.bootstrap_manifest_digest
       JOIN current_valid_keys bsk
         ON bsk.key_id = bm.signer_key_id
        AND bsk.key_purpose = 'control_plane'
       JOIN bootstrap_managed_identity_bindings bmi
         ON bmi.bootstrap_manifest_digest = bm.digest
        AND bmi.service_alias = NEW.service_alias
        AND bmi.managed_identity_digest = NEW.managed_identity_digest
       JOIN managed_service_identities msi
         ON msi.digest = NEW.managed_identity_digest
        AND msi.service_alias = NEW.service_alias
        AND msi.principal_id = NEW.principal_id
        AND msi.runtime_catalog_digest = NEW.runtime_catalog_digest
       JOIN current_valid_keys msi_key
         ON msi_key.key_id = msi.signer_key_id
        AND msi_key.principal_id = msi.signer_principal_id
        AND msi_key.key_purpose = 'control_plane'
       JOIN artifact_manifests asset ON asset.digest = msi.asset_manifest_digest
       JOIN current_valid_keys asset_key
         ON asset_key.key_id = asset.signer_key_id
        AND asset_key.key_purpose = 'artifact_broker'
       JOIN sanitization_attestations sa
         ON sa.digest = msi.sanitization_attestation_digest
        AND sa.subject_manifest_digest = msi.asset_manifest_digest
        AND sa.rules_digest = msi.sanitization_rules_digest
        AND sa.allowed_root = msi.workspace_root
       JOIN current_valid_keys sa_key
         ON sa_key.key_id = sa.signer_key_id
        AND sa_key.principal_id = sa.signer_principal_id
        AND sa_key.key_purpose = 'schema_validator'
       JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
       JOIN current_valid_keys rsk
         ON rsk.key_id = rc.signer_key_id
        AND rsk.key_purpose = 'control_plane'
       JOIN runtime_catalog_probe_attestations rpa ON rpa.runtime_catalog_digest = rc.digest
       JOIN current_valid_keys rpask
         ON rpask.key_id = rpa.signer_key_id
        AND rpask.key_purpose = 'runtime_supervisor'
       JOIN policies sp ON sp.digest = msi.sandbox_policy_digest
       JOIN current_valid_keys ssk
         ON ssk.key_id = sp.signer_key_id
        AND ssk.key_purpose = 'control_plane'
       JOIN resource_reservations rr ON rr.charge_subject_id = NEW.charge_subject_id
       JOIN resource_profiles prof ON prof.digest = rr.resource_profile_digest
       JOIN current_host_capacity hc ON hc.singleton = 1
       WHERE lt.term = NEW.leader_term
         AND lt.state = 'active'
         AND ctl.current_term = NEW.leader_term
         AND ctl.portfolio_epoch = NEW.service_epoch
         AND ctl.kill_switch = 0
         AND rpa.probe_contract_digest = rc.probe_contract_digest
         AND rpa.binary_digest = rc.binary_digest
         AND rpa.actual_model = rc.resolved_model
         AND rpa.actual_model_family = rc.resolved_model_family
         AND rpa.actual_effort = rc.resolved_effort
         AND rpa.probed_at_ms BETWEEN (unixepoch('subsec') * 1000) - 900000
                                  AND (unixepoch('subsec') * 1000) + 5000
         AND NOT EXISTS (
           SELECT 1 FROM runtime_catalog_invalidations rci
           WHERE rci.runtime_catalog_digest = rc.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM managed_service_identity_invalidations mii
           WHERE mii.managed_identity_digest = msi.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (
             msi.config_digest, msi.sanitization_rules_digest,
             rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
             rc.provider_proxy_profile_digest, rc.io_protocol_digest,
             rc.system_prompt_digest, rc.toolchain_closure_digest, rc.probe_contract_digest
           )
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations pi
           WHERE pi.policy_digest IN (msi.sandbox_policy_digest, prof.digest, prof.host_policy_digest)
         )
         AND rr.reservation_kind = 'process'
         AND rr.state = 'held'
         AND prof.profile_name = 'managed_opus_process'
         AND prof.host_policy_digest = hc.resource_policy_digest
     );
END;

CREATE TRIGGER managed_service_intents_legal_state_transition
BEFORE UPDATE OF state ON managed_service_intents
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal managed-service-intent state transition')
  WHERE NOT (
    (OLD.state = 'prepared' AND NEW.state IN ('launch_claimed','cancelled','failed'))
    OR (OLD.state = 'launch_claimed' AND NEW.state IN ('launch_permitted','unknown','cancelled','failed'))
    OR (OLD.state = 'launch_permitted' AND NEW.state IN ('launched','unknown'))
    OR (OLD.state = 'launched' AND NEW.state IN ('terminated','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('terminated','failed','cancelled'))
  );
END;

CREATE TRIGGER managed_service_intent_claim_is_set_once
BEFORE UPDATE OF claim_token, claim_until_ms ON managed_service_intents
WHEN (OLD.claim_token IS NOT NULL AND OLD.claim_token IS NOT NEW.claim_token)
  OR (OLD.claim_until_ms IS NOT NULL AND OLD.claim_until_ms IS NOT NEW.claim_until_ms)
BEGIN SELECT RAISE(ABORT, 'managed service claim is immutable once set'); END;

CREATE TRIGGER managed_service_intent_launch_requires_session
BEFORE UPDATE OF state ON managed_service_intents
WHEN NEW.state = 'launched' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'managed intent cannot launch without recorded session')
  WHERE NOT EXISTS (
    SELECT 1 FROM managed_service_sessions ms
    WHERE ms.managed_service_intent_id = NEW.id AND ms.state IN ('starting','running')
  );
END;

CREATE TRIGGER managed_service_intent_termination_requires_dead_session
BEFORE UPDATE OF state ON managed_service_intents
WHEN NEW.state = 'terminated' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'managed intent cannot terminate before session death')
  WHERE NOT EXISTS (
    SELECT 1 FROM managed_service_sessions ms
    WHERE ms.managed_service_intent_id = NEW.id AND ms.state = 'terminated'
  );
END;

CREATE TRIGGER managed_service_intent_identity_is_immutable
BEFORE UPDATE OF id, service_alias, managed_identity_digest, principal_id, charge_subject_id,
  runtime_catalog_digest, leader_term, service_epoch, launch_identity,
  process_identity, provider_idempotency_key, created_at_ms
ON managed_service_intents
BEGIN SELECT RAISE(ABORT, 'managed service-intent identity is immutable'); END;

CREATE TRIGGER managed_service_intents_no_delete
BEFORE DELETE ON managed_service_intents
BEGIN SELECT RAISE(ABORT, 'managed service-intent history is append-only'); END;

CREATE TRIGGER managed_service_session_matches_charge_and_signer
BEFORE INSERT ON managed_service_sessions
BEGIN
  SELECT RAISE(ABORT, 'managed service session requires scoped service charge and active signer')
  WHERE json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.service_alias') IS NOT NEW.service_alias
     OR json_extract(NEW.canonical_json, '$.managed_identity_digest') IS NOT NEW.managed_identity_digest
     OR json_extract(NEW.canonical_json, '$.principal_id') IS NOT NEW.principal_id
     OR json_extract(NEW.canonical_json, '$.managed_service_intent_id') IS NOT NEW.managed_service_intent_id
     OR json_extract(NEW.canonical_json, '$.process_identity') IS NOT NEW.process_identity
     OR json_extract(NEW.canonical_json, '$.provider_session_id') IS NOT NEW.provider_session_id
     OR json_extract(NEW.canonical_json, '$.runtime_catalog_digest') IS NOT NEW.runtime_catalog_digest
     OR json_extract(NEW.canonical_json, '$.runtime') IS NOT NEW.runtime
     OR json_extract(NEW.canonical_json, '$.actual_model') IS NOT NEW.actual_model
     OR json_extract(NEW.canonical_json, '$.actual_model_family') IS NOT NEW.actual_model_family
     OR json_extract(NEW.canonical_json, '$.actual_profile') IS NOT NEW.actual_profile
     OR json_extract(NEW.canonical_json, '$.sandbox_policy_digest') IS NOT NEW.sandbox_policy_digest
     OR json_extract(NEW.canonical_json, '$.private_home_manifest_digest') IS NOT NEW.private_home_manifest_digest
     OR json_extract(NEW.canonical_json, '$.handshake_manifest_digest') IS NOT NEW.handshake_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.started_at_ms') IS NOT NEW.started_at_ms
     OR NOT EXISTS (
    SELECT 1
    FROM managed_service_intents mi
    JOIN charge_subjects cs ON cs.id = mi.charge_subject_id
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.key_purpose = 'runtime_supervisor'
    JOIN principals supervisor ON supervisor.id = sk.principal_id
    JOIN principal_global_roles supervisor_role
      ON supervisor_role.principal_id = supervisor.id
     AND supervisor_role.role = 'operator'
     AND supervisor_role.revoked_at_ms IS NULL
    JOIN artifact_manifests home_manifest
      ON home_manifest.digest = NEW.private_home_manifest_digest
    JOIN artifact_manifests handshake_manifest
      ON handshake_manifest.digest = NEW.handshake_manifest_digest
    JOIN current_valid_keys home_key
      ON home_key.key_id = home_manifest.signer_key_id
     AND home_key.key_purpose = 'artifact_broker'
    JOIN current_valid_keys handshake_key
      ON handshake_key.key_id = handshake_manifest.signer_key_id
     AND handshake_key.key_purpose = 'artifact_broker'
    JOIN runtime_catalogs rc ON rc.digest = NEW.runtime_catalog_digest
    JOIN managed_service_identities msi
      ON msi.digest = NEW.managed_identity_digest
     AND msi.service_alias = NEW.service_alias
     AND msi.principal_id = NEW.principal_id
     AND msi.runtime_catalog_digest = NEW.runtime_catalog_digest
    JOIN policies sp ON sp.digest = msi.sandbox_policy_digest
    JOIN current_valid_keys ssk
      ON ssk.key_id = sp.signer_key_id
     AND ssk.key_purpose = 'control_plane'
    JOIN current_valid_keys rsk
      ON rsk.key_id = rc.signer_key_id
     AND rsk.key_purpose = 'control_plane'
    JOIN leader_terms lt ON lt.term = mi.leader_term
    JOIN control_state ctl ON ctl.singleton = 1
    WHERE mi.id = NEW.managed_service_intent_id
      AND mi.service_alias = NEW.service_alias
      AND mi.managed_identity_digest = NEW.managed_identity_digest
      AND mi.principal_id = NEW.principal_id
      AND mi.runtime_catalog_digest = NEW.runtime_catalog_digest
      AND mi.process_identity = NEW.process_identity
      AND mi.state = 'launch_permitted'
      AND NEW.started_at_ms <= mi.claim_until_ms
      AND cs.scope_kind = 'service_operation'
      AND cs.service_operation_key = 'managed-runtime:' || mi.id
      AND supervisor.kind = 'service'
      AND supervisor.state = 'active'
      AND rc.runtime = NEW.runtime
      AND rc.resolved_model = NEW.actual_model
      AND rc.resolved_model_family = NEW.actual_model_family
      AND rc.resolved_effort = NEW.actual_profile
      AND NEW.sandbox_policy_digest = msi.sandbox_policy_digest
      AND rc.effective_at_ms <= NEW.started_at_ms
      AND lt.state = 'active'
      AND ctl.current_term = mi.leader_term
      AND ctl.portfolio_epoch = mi.service_epoch
      AND ctl.kill_switch = 0
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = rc.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM managed_service_identity_invalidations mii
        WHERE mii.managed_identity_digest = msi.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = msi.sandbox_policy_digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest IN (msi.config_digest, msi.sanitization_rules_digest)
      )
  );
END;

CREATE TRIGGER managed_service_session_running_requires_resource
BEFORE UPDATE OF state ON managed_service_sessions
WHEN OLD.state = 'starting' AND NEW.state = 'running'
BEGIN
  SELECT RAISE(ABORT, 'managed service session requires held resource reservation')
  WHERE NOT EXISTS (
    SELECT 1
    FROM managed_service_intents mi
    JOIN resource_reservations rr ON rr.charge_subject_id = mi.charge_subject_id
    WHERE mi.id = NEW.managed_service_intent_id
      AND rr.reservation_kind = 'process'
      AND rr.state = 'held'
  );
END;

CREATE TRIGGER managed_service_sessions_legal_state_transition
BEFORE UPDATE OF state ON managed_service_sessions
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal managed-service-session state transition')
  WHERE NOT (
    (OLD.state = 'starting' AND NEW.state IN ('running','terminated','unknown'))
    OR (OLD.state = 'running' AND NEW.state IN ('terminating','terminated','unknown'))
    OR (OLD.state = 'terminating' AND NEW.state IN ('terminated','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state = 'terminated')
  );
END;

CREATE TRIGGER runtime_session_termination_requires_evidence
BEFORE UPDATE OF state ON runtime_sessions
WHEN NEW.state = 'terminated' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'terminated runtime session requires signed supervisor process-death evidence')
  WHERE NEW.terminated_at_ms IS NULL
     OR NEW.termination_reason IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM reconciliation_decisions d
       WHERE d.subject_kind = 'runtime_session'
         AND d.subject_id = NEW.id
         AND d.resolved_state = 'terminated'
         AND d.process_identity = NEW.process_identity
         AND d.provider_lookup_key = NEW.provider_session_id
         AND d.observed_process_state IN ('dead','absent')
         AND d.observed_provider_state IN ('completed','failed','cancelled','absent','unreachable')
         AND d.observed_at_ms <= NEW.terminated_at_ms
     );
END;

CREATE TRIGGER managed_session_termination_requires_evidence
BEFORE UPDATE OF state ON managed_service_sessions
WHEN NEW.state = 'terminated' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'terminated managed session requires signed supervisor process-death evidence')
  WHERE NEW.terminated_at_ms IS NULL
     OR NEW.termination_reason IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM reconciliation_decisions d
       WHERE d.subject_kind = 'managed_session'
         AND d.subject_id = NEW.id
         AND d.resolved_state = 'terminated'
         AND d.process_identity = NEW.process_identity
         AND d.provider_lookup_key = NEW.provider_session_id
         AND d.observed_process_state IN ('dead','absent')
         AND d.observed_provider_state IN ('completed','failed','cancelled','absent','unreachable')
         AND d.observed_at_ms <= NEW.terminated_at_ms
     );
END;

