CREATE TRIGGER slot_available_requires_process_termination
BEFORE UPDATE OF state ON executor_slots
WHEN NEW.state = 'available' AND OLD.state <> 'available'
BEGIN
  SELECT RAISE(ABORT, 'slot cannot become available while a live lease exists')
  WHERE EXISTS (
    SELECT 1 FROM leases
    WHERE executor_slot_id = NEW.id AND state = 'active'
  );

  SELECT RAISE(ABORT, 'slot cannot become available before process termination')
  WHERE EXISTS (
    SELECT 1
    FROM runtime_sessions s
    WHERE s.executor_slot_id = NEW.id
      AND s.state <> 'terminated'
  );
END;

CREATE TRIGGER result_envelopes_enter_received
BEFORE INSERT ON result_envelopes
WHEN NEW.state <> 'received'
BEGIN SELECT RAISE(ABORT, 'result envelopes must enter through received'); END;

CREATE TRIGGER result_envelope_matches_inbound_submission
BEFORE INSERT ON result_envelopes
BEGIN
  SELECT RAISE(ABORT, 'result envelope is not an exact executor-signed canonical submission')
  WHERE NEW.output_manifest_digest IS NULL
     OR NEW.received_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.received_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.signed_at_ms > NEW.received_at_ms
     OR NEW.signed_at_ms < NEW.received_at_ms - 300000
     OR json_extract(NEW.payload_json, '$.source_result_id') IS NOT NEW.source_result_id
     OR json_extract(NEW.payload_json, '$.attempt_id') IS NOT NEW.attempt_id
     OR json_extract(NEW.payload_json, '$.dispatch_key') IS NOT NEW.dispatch_key
     OR json_extract(NEW.payload_json, '$.executor_id') IS NOT NEW.executor_id
     OR json_extract(NEW.payload_json, '$.worker_instance_id') IS NOT NEW.worker_instance_id
     OR json_extract(NEW.payload_json, '$.fence') IS NOT NEW.fence
     OR json_extract(NEW.payload_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.payload_json, '$.project_slot_generation') IS NOT NEW.project_slot_generation
     OR json_extract(NEW.payload_json, '$.input_manifest_digest') IS NOT NEW.input_manifest_digest
     OR json_extract(NEW.payload_json, '$.output_manifest_digest') IS NOT NEW.output_manifest_digest
     OR json_extract(NEW.payload_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.payload_json, '$.signed_at_ms') IS NOT NEW.signed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM inbound_submissions i
       JOIN attempts a
         ON a.id = NEW.attempt_id
        AND a.dispatch_key = NEW.dispatch_key
        AND a.executor_id = NEW.executor_id
        AND a.fence = NEW.fence
        AND a.leader_term = NEW.leader_term
        AND a.project_slot_generation = NEW.project_slot_generation
        AND a.input_manifest_digest = NEW.input_manifest_digest
       JOIN leases l
         ON l.attempt_id = a.id
        AND l.worker_instance_id = NEW.worker_instance_id
        AND l.fence = a.fence
        AND l.leader_term = a.leader_term
        AND l.state = 'active'
       JOIN executors e ON e.id = a.executor_id
       JOIN current_valid_keys executor_key
         ON executor_key.key_id = NEW.signer_key_id
        AND executor_key.principal_id = e.principal_id
        AND executor_key.key_purpose = 'executor_result'
       WHERE i.id = NEW.inbound_submission_id
         AND i.state = 'parsed'
         AND i.payload_digest = NEW.payload_digest
         AND NEW.received_at_ms >= i.received_at_ms
         AND NEW.received_at_ms <= i.received_at_ms + 300000
         AND (i.claimed_attempt_id IS NULL OR i.claimed_attempt_id = NEW.attempt_id)
     );
END;

CREATE TRIGGER result_signature_validation_receipt_is_exact_and_trusted
BEFORE INSERT ON result_signature_validation_receipts
BEGIN
  SELECT RAISE(ABORT, 'result signature validation receipt is not exact or trusted')
  WHERE NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.result_envelope_id') IS NOT NEW.result_envelope_id
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.executor_key_id') IS NOT NEW.executor_key_id
     OR json_extract(NEW.canonical_json, '$.validator_closure_digest') IS NOT NEW.validator_closure_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM result_envelopes re
       JOIN configuration_artifacts validator
         ON validator.digest = NEW.validator_closure_digest
        AND validator.artifact_kind = 'toolchain_closure'
       JOIN current_valid_keys executor_key
         ON executor_key.key_id = re.signer_key_id
        AND executor_key.key_id = NEW.executor_key_id
        AND executor_key.key_purpose = 'executor_result'
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE re.id = NEW.result_envelope_id
         AND re.state = 'received'
         AND re.payload_digest = NEW.payload_digest
         AND NEW.created_at_ms >= re.received_at_ms
         AND NEW.created_at_ms <= re.received_at_ms + 60000
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest = validator.digest
         )
     );
END;

CREATE TRIGGER result_signature_validation_receipts_no_update
BEFORE UPDATE ON result_signature_validation_receipts
BEGIN SELECT RAISE(ABORT, 'result signature validation receipts are immutable'); END;

CREATE TRIGGER result_signature_validation_receipts_no_delete
BEFORE DELETE ON result_signature_validation_receipts
BEGIN SELECT RAISE(ABORT, 'result signature validation receipts are immutable'); END;

CREATE TRIGGER inbound_validation_attestation_is_exact_and_trusted
BEFORE INSERT ON inbound_validation_attestations
BEGIN
  SELECT RAISE(ABORT, 'inbound validation attestation is stale, inexact, or untrusted')
  WHERE NEW.validated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.validated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.inbound_submission_id') IS NOT NEW.inbound_submission_id
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.payload_size_bytes') IS NOT NEW.payload_size_bytes
     OR json_extract(NEW.canonical_json, '$.validator_closure_digest') IS NOT NEW.validator_closure_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.disposition_code') IS NOT NEW.disposition_code
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.validated_at_ms') IS NOT NEW.validated_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM inbound_submissions submission
       JOIN configuration_artifacts validator
         ON validator.digest = NEW.validator_closure_digest
        AND validator.artifact_kind = 'toolchain_closure'
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE submission.id = NEW.inbound_submission_id
         AND submission.state = 'received'
         AND submission.payload_digest = NEW.payload_digest
         AND submission.payload_size_bytes = NEW.payload_size_bytes
         AND NEW.validated_at_ms >= submission.received_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = validator.digest
         )
         AND (
           (NEW.verdict = 'pass' AND NEW.payload_size_bytes BETWEEN 1 AND 16777216)
           OR NEW.verdict = 'fail'
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'inbound_validation_attestation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.validated_at_ms - 5000 AND NEW.validated_at_ms
     );
END;

CREATE TRIGGER inbound_validation_attestations_no_update
BEFORE UPDATE ON inbound_validation_attestations
BEGIN SELECT RAISE(ABORT, 'inbound validation attestations are immutable'); END;

CREATE TRIGGER inbound_validation_attestations_no_delete
BEFORE DELETE ON inbound_validation_attestations
BEGIN SELECT RAISE(ABORT, 'inbound validation attestations are immutable'); END;

CREATE TRIGGER inbound_submissions_enter_received
BEFORE INSERT ON inbound_submissions
BEGIN
  SELECT RAISE(ABORT, 'inbound submissions must enter fresh through received')
  WHERE NEW.state <> 'received'
     OR NEW.disposition_code IS NOT NULL
     OR NEW.decided_at_ms IS NOT NULL
     OR NEW.received_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.received_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER inbound_submissions_legal_state_transition
BEFORE UPDATE OF state ON inbound_submissions
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal inbound-submission state transition')
  WHERE NOT (
    (OLD.state = 'received' AND NEW.state IN ('parsed','rejected','quarantined'))
    OR (OLD.state = 'parsed' AND NEW.state IN ('promoted','rejected','quarantined'))
  )
  OR (NEW.state IN ('rejected','quarantined','promoted') AND (
    NEW.disposition_code IS NULL
    OR NEW.decided_at_ms IS NULL
    OR NEW.decided_at_ms < OLD.received_at_ms
    OR NEW.decided_at_ms < (unixepoch('subsec') * 1000) - 5000
    OR NEW.decided_at_ms > (unixepoch('subsec') * 1000) + 5000
  ));

  SELECT RAISE(ABORT, 'parsed submission requires one exact passing validation attestation')
  WHERE NEW.state = 'parsed'
    AND NOT EXISTS (
      SELECT 1 FROM inbound_validation_attestations attestation
      WHERE attestation.inbound_submission_id = NEW.id
        AND attestation.payload_digest = NEW.payload_digest
        AND attestation.payload_size_bytes = NEW.payload_size_bytes
        AND attestation.verdict = 'pass'
        AND attestation.validated_at_ms <= (unixepoch('subsec') * 1000) + 5000
    );

  SELECT RAISE(ABORT, 'rejected/quarantined submission requires its exact failing attestation')
  WHERE NEW.state IN ('rejected','quarantined')
    AND NOT EXISTS (
      SELECT 1 FROM inbound_validation_attestations attestation
      WHERE attestation.inbound_submission_id = NEW.id
        AND attestation.payload_digest = NEW.payload_digest
        AND attestation.payload_size_bytes = NEW.payload_size_bytes
        AND attestation.verdict = 'fail'
        AND attestation.disposition_code = NEW.disposition_code
        AND attestation.validated_at_ms <= NEW.decided_at_ms
    );

  SELECT RAISE(ABORT, 'promotion requires one accepted exact result envelope')
  WHERE NEW.state = 'promoted'
    AND NOT EXISTS (
      SELECT 1 FROM result_envelopes result
      WHERE result.inbound_submission_id = NEW.id
        AND result.payload_digest = NEW.payload_digest
        AND result.state = 'accepted'
        AND result.decided_at_ms <= NEW.decided_at_ms
    );
END;

CREATE TRIGGER inbound_submission_disposition_is_transition_bound
BEFORE UPDATE OF disposition_code, decided_at_ms ON inbound_submissions
WHEN OLD.disposition_code IS NOT NEW.disposition_code
  OR OLD.decided_at_ms IS NOT NEW.decided_at_ms
BEGIN
  SELECT RAISE(ABORT, 'inbound disposition is set once on a terminal transition')
  WHERE OLD.disposition_code IS NOT NULL
     OR OLD.decided_at_ms IS NOT NULL
     OR OLD.state = NEW.state
     OR NEW.state NOT IN ('promoted','rejected','quarantined');
END;

