BEFORE UPDATE OF id, source, source_message_id, claimed_attempt_id,
  payload_digest, payload_size_bytes, quarantine_ref, received_at_ms
ON inbound_submissions
BEGIN SELECT RAISE(ABORT, 'inbound-submission payload is immutable'); END;

