BEFORE DELETE ON inbound_submissions
BEGIN SELECT RAISE(ABORT, 'inbound-submission history is append-only'); END;

CREATE TRIGGER content_sanitization_attestation_is_exact_and_trusted
BEFORE INSERT ON content_sanitization_attestations
BEGIN
  SELECT RAISE(ABORT, 'content sanitization attestation is stale, inexact, or untrusted')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.content_kind') IS NOT NEW.content_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.sanitizer_closure_digest') IS NOT NEW.sanitizer_closure_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.secret_material_detected') IS NOT NEW.secret_material_detected
     OR json_extract(NEW.canonical_json, '$.duplicate_keys_rejected') IS NOT NEW.duplicate_keys_rejected
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM configuration_artifacts sanitizer
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE sanitizer.digest = NEW.sanitizer_closure_digest
         AND sanitizer.artifact_kind = 'sanitization_rules'
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = sanitizer.digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'content_sanitization_attestation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER content_sanitization_attestations_no_update
BEFORE UPDATE ON content_sanitization_attestations
BEGIN SELECT RAISE(ABORT, 'content sanitization attestations are immutable'); END;

CREATE TRIGGER content_sanitization_attestations_no_delete
BEFORE DELETE ON content_sanitization_attestations
BEGIN SELECT RAISE(ABORT, 'content sanitization attestations are immutable'); END;

CREATE TRIGGER credential_reference_is_exact_brokered_metadata
BEFORE INSERT ON credential_references
BEGIN
  SELECT RAISE(ABORT, 'credential reference is stale, inexact, untrusted, or contains vault data')
  WHERE NEW.state <> 'active'
     OR NEW.revoked_at_ms IS NOT NULL
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= NEW.created_at_ms
     OR NEW.expires_at_ms > NEW.created_at_ms + 86400000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.request_id') IS NOT NEW.request_id
     OR json_extract(NEW.canonical_json, '$.vault_provider') IS NOT NEW.vault_provider
     OR json_extract(NEW.canonical_json, '$.vault_object_ref') IS NOT NEW.vault_object_ref
     OR json_extract(NEW.canonical_json, '$.purpose') IS NOT NEW.purpose
     OR json_extract(NEW.canonical_json, '$.state') IS NOT NEW.state
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM human_requests request
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'credential_broker'
       JOIN principals broker ON broker.id = NEW.signer_principal_id AND broker.kind = 'service'
       WHERE request.id = NEW.request_id
         AND request.project_id = NEW.project_id
         AND request.request_type = 'credential'
         AND request.state = 'open'
         AND (request.due_at_ms IS NULL OR NEW.created_at_ms <= request.due_at_ms)
         AND (request.due_at_ms IS NULL OR NEW.expires_at_ms <= request.due_at_ms)
         AND json_extract(request.payload_json, '$.credential_purpose') = NEW.purpose
         AND json_extract(request.payload_json, '$.vault_provider') = NEW.vault_provider
     )
     OR EXISTS (
       SELECT 1 FROM json_tree(NEW.canonical_json) member
       WHERE member.key IS NOT NULL
         AND lower(CAST(member.key AS TEXT)) IN (
           'secret','password','token','credential','credential_value',
           'api_key','apikey','private_key','authorization','cookie','value'
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'credential_reference'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER credential_references_no_update
BEFORE UPDATE ON credential_references
BEGIN SELECT RAISE(ABORT, 'credential references are immutable; append a revocation'); END;

CREATE TRIGGER credential_references_no_delete
BEFORE DELETE ON credential_references
BEGIN SELECT RAISE(ABORT, 'credential references are immutable metadata'); END;

CREATE TRIGGER credential_reference_revocation_is_exact_and_signed
BEFORE INSERT ON credential_reference_revocations
BEGIN
  SELECT RAISE(ABORT, 'credential-reference revocation is stale, inexact, or unsigned')
  WHERE NEW.revoked_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.revoked_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.credential_reference_id') IS NOT NEW.credential_reference_id
     OR json_extract(NEW.canonical_json, '$.reason') IS NOT NEW.reason
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.revoked_at_ms') IS NOT NEW.revoked_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM credential_references reference
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'credential_broker'
       WHERE reference.id = NEW.credential_reference_id
         AND reference.created_at_ms <= NEW.revoked_at_ms
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'credential_reference_revocation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.revoked_at_ms - 5000 AND NEW.revoked_at_ms
     );
END;

CREATE TRIGGER credential_reference_revocations_no_update
BEFORE UPDATE ON credential_reference_revocations
BEGIN SELECT RAISE(ABORT, 'credential-reference revocations are immutable'); END;

CREATE TRIGGER credential_reference_revocations_no_delete
BEFORE DELETE ON credential_reference_revocations
BEGIN SELECT RAISE(ABORT, 'credential-reference revocations are immutable'); END;

CREATE TRIGGER human_requests_enter_open
BEFORE INSERT ON human_requests
BEGIN
  SELECT RAISE(ABORT, 'human request must be exact, provenance-bound, and approval-broker signed')
  WHERE NEW.state <> 'open'
     OR NEW.answered_at_ms IS NOT NULL
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR (NEW.due_at_ms IS NOT NULL AND NEW.due_at_ms <= NEW.created_at_ms)
     OR EXISTS (
       SELECT 1 FROM json_tree(NEW.payload_json) member
       WHERE member.key IS NOT NULL
         AND lower(CAST(member.key AS TEXT)) IN (
           'secret','password','token','credential','credential_value',
           'api_key','apikey','private_key','authorization','cookie'
         )
     )
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.request_type') IS NOT NEW.request_type
     OR json_extract(NEW.canonical_json, '$.required_role') IS NOT NEW.required_role
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.sanitization_attestation_digest') IS NOT NEW.sanitization_attestation_digest
     OR json(NEW.payload_json) <> json(json_extract(NEW.canonical_json, '$.payload'))
     OR json_extract(NEW.canonical_json, '$.requester_attempt_id') IS NOT NEW.requester_attempt_id
     OR json_extract(NEW.canonical_json, '$.requester_runtime_session_id') IS NOT NEW.requester_runtime_session_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.due_at_ms') IS NOT NEW.due_at_ms
     OR (NEW.run_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM runs r
       WHERE r.id = NEW.run_id AND r.project_id = NEW.project_id
     ))
     OR NOT EXISTS (
       SELECT 1 FROM content_sanitization_attestations attestation
       WHERE attestation.digest = NEW.sanitization_attestation_digest
         AND attestation.content_kind = 'human_request'
         AND attestation.subject_id = NEW.id
         AND attestation.payload_digest = NEW.payload_digest
         AND attestation.created_at_ms <= NEW.created_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = attestation.sanitizer_closure_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys broker_key
       JOIN principals broker
         ON broker.id = NEW.signer_principal_id AND broker.kind = 'service'
       WHERE broker_key.key_id = NEW.signer_key_id
         AND broker_key.principal_id = NEW.signer_principal_id
         AND broker_key.key_purpose = 'approval_broker'
         AND (
           (NEW.requester_attempt_id IS NOT NULL AND EXISTS (
             SELECT 1 FROM attempts attempt
             WHERE attempt.id = NEW.requester_attempt_id
               AND attempt.project_id = NEW.project_id
               AND (NEW.run_id IS NULL OR attempt.run_id = NEW.run_id)
               AND attempt.state IN ('dispatched','acked','running','result_pending')
           ))
           OR (NEW.requester_runtime_session_id IS NOT NULL AND EXISTS (
             SELECT 1 FROM runtime_sessions session
             WHERE session.id = NEW.requester_runtime_session_id
               AND session.project_id = NEW.project_id
               AND session.state = 'running'
           ))
         )
     );

  SELECT RAISE(ABORT, 'human request signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'human_request'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER human_requests_legal_state_transition
BEFORE UPDATE OF state ON human_requests
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal human-request state transition')
  WHERE NOT (
    OLD.state = 'open' AND NEW.state IN ('answered','cancelled','expired')
  );

  SELECT RAISE(ABORT, 'answered human request requires its authenticated response and answer time')
  WHERE NEW.state = 'answered'
    AND (
      NEW.answered_at_ms IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM human_responses hr
        WHERE hr.request_id = NEW.id
          AND hr.created_at_ms <= NEW.answered_at_ms
      )
    );

  SELECT RAISE(ABORT, 'only answered requests may set answered_at')
  WHERE NEW.state <> 'answered' AND NEW.answered_at_ms IS NOT NULL;
END;

CREATE TRIGGER human_requests_identity_is_immutable
BEFORE UPDATE OF id, project_id, run_id, request_type, required_role,
  payload_json, payload_digest, requester_attempt_id, requester_runtime_session_id,
  canonical_json, signer_principal_id, signer_key_id, signature,
  created_at_ms, due_at_ms
ON human_requests
BEGIN SELECT RAISE(ABORT, 'human request identity and payload are immutable'); END;

CREATE TRIGGER human_request_answer_time_is_set_once
BEFORE UPDATE OF answered_at_ms ON human_requests
WHEN OLD.answered_at_ms IS NOT NEW.answered_at_ms
BEGIN
  SELECT RAISE(ABORT, 'human answer time is set once on the answered transition')
  WHERE OLD.answered_at_ms IS NOT NULL
     OR NEW.answered_at_ms IS NULL
     OR OLD.state <> 'open'
     OR NEW.state <> 'answered'
     OR NEW.answered_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER human_requests_no_delete
BEFORE DELETE ON human_requests
BEGIN SELECT RAISE(ABORT, 'human request history is append-only'); END;

CREATE TRIGGER integration_targets_enter_available
BEFORE INSERT ON integration_targets
BEGIN
  SELECT RAISE(ABORT, 'integration target must enter available through an exact current global command')
  WHERE NEW.state <> 'available'
     OR NEW.fence_counter <> 0
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.target_ref = ''
     OR NOT EXISTS (
       SELECT 1
       FROM command_authorizations authorization
       JOIN commands command ON command.id = authorization.command_id
       JOIN principal_global_roles role
         ON role.principal_id = authorization.actor_principal_id
        AND role.role IN ('admin','operator')
        AND role.revoked_at_ms IS NULL
       JOIN control_state control ON control.current_term = authorization.leader_term
       WHERE authorization.digest = NEW.registration_command_authorization_digest
         AND authorization.project_id IS NULL
         AND authorization.command_type = 'integration_target.register'
         AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
         AND command.state = 'authorized'
         AND json_extract(command.payload_json, '$.integration_target_id') = NEW.id
         AND json_extract(command.payload_json, '$.repository_id') = NEW.repository_id
         AND json_extract(command.payload_json, '$.target_ref') = NEW.target_ref
     );
END;

CREATE TRIGGER integration_target_fence_change_is_scoped
BEFORE UPDATE OF fence_counter ON integration_targets
WHEN NEW.fence_counter <> OLD.fence_counter
BEGIN
  SELECT RAISE(ABORT, 'integration-target fence changes only on an available-to-leased claim')
  WHERE OLD.state <> 'available'
     OR NEW.state <> 'leased'
     OR NEW.fence_counter <> OLD.fence_counter + 1;
END;

CREATE TRIGGER integration_target_claim_increments_fence
BEFORE UPDATE OF state ON integration_targets
WHEN OLD.state = 'available' AND NEW.state = 'leased'
BEGIN
  SELECT RAISE(ABORT, 'integration claim must increment fence exactly once')
  WHERE NEW.fence_counter <> OLD.fence_counter + 1;
END;

CREATE TRIGGER integration_targets_legal_state_transition
BEFORE UPDATE OF state ON integration_targets
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal integration-target state transition')
  WHERE NOT (
    (OLD.state = 'available' AND NEW.state IN ('leased','quarantined'))
    OR (OLD.state = 'leased' AND NEW.state IN ('integrating','available','quarantined'))
    OR (OLD.state = 'integrating' AND NEW.state IN ('available','quarantined'))
    OR (OLD.state = 'quarantined' AND NEW.state = 'available')
  );
END;

CREATE TRIGGER integration_target_identity_is_immutable
BEFORE UPDATE OF id, repository_id, target_ref,
  registration_command_authorization_digest, created_at_ms ON integration_targets
BEGIN SELECT RAISE(ABORT, 'integration-target identity is immutable'); END;

CREATE TRIGGER integration_targets_no_delete
BEFORE DELETE ON integration_targets
BEGIN SELECT RAISE(ABORT, 'integration-target history cannot be deleted'); END;

CREATE TRIGGER target_head_observation_is_current_and_signed
BEFORE INSERT ON target_head_observations
BEGIN
  SELECT RAISE(ABORT, 'target-head observation is not exact, current, or provider-observer signed')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 60000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.observed_at_ms <= COALESCE((
       SELECT MAX(prior.observed_at_ms)
       FROM target_head_observations prior
       WHERE prior.integration_target_id = NEW.integration_target_id
         AND prior.target_fence = NEW.target_fence
     ), 0)
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.integration_target_id') IS NOT NEW.integration_target_id
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.target_fence') IS NOT NEW.target_fence
     OR json_extract(NEW.canonical_json, '$.target_ref') IS NOT NEW.target_ref
     OR json_extract(NEW.canonical_json, '$.observed_commit') IS NOT NEW.observed_commit
     OR json_extract(NEW.canonical_json, '$.provider_etag') IS NOT NEW.provider_etag
     OR json_extract(NEW.canonical_json, '$.request_digest') IS NOT NEW.request_digest
     OR json_extract(NEW.canonical_json, '$.response_digest') IS NOT NEW.response_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NOT EXISTS (
    SELECT 1
    FROM integration_targets t
    JOIN repositories repo ON repo.id = t.repository_id
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.principal_id = NEW.signer_principal_id
     AND sk.key_purpose = 'provider_observer'
    JOIN principals observer ON observer.id = NEW.signer_principal_id
    JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
    JOIN current_valid_keys evidence_key
      ON evidence_key.key_id = evidence.signer_key_id
     AND evidence_key.key_purpose = 'artifact_broker'
    WHERE t.id = NEW.integration_target_id
      AND t.target_ref = NEW.target_ref
      AND t.fence_counter = NEW.target_fence
      AND t.state IN ('integrating','available')
      AND observer.kind = 'service'
      AND json_extract(NEW.canonical_json, '$.repository_id') = repo.id
  );
END;

CREATE TRIGGER target_head_observations_no_update
BEFORE UPDATE ON target_head_observations
BEGIN SELECT RAISE(ABORT, 'target-head observations are immutable'); END;

CREATE TRIGGER target_head_observations_no_delete
BEFORE DELETE ON target_head_observations
BEGIN SELECT RAISE(ABORT, 'target-head observations are immutable'); END;

CREATE TRIGGER workspaces_enter_provisioning
BEFORE INSERT ON workspaces
WHEN NEW.state <> 'provisioning'
BEGIN SELECT RAISE(ABORT, 'workspaces must enter through provisioning'); END;

CREATE TRIGGER workspace_matches_attempt_slot_and_repository
BEFORE INSERT ON workspaces
BEGIN
  SELECT RAISE(ABORT, 'workspace does not match attempt slot or authorized repository')
  WHERE NEW.output_commit IS NOT NULL
     OR NOT EXISTS (
       SELECT 1
       FROM attempts a
       JOIN project_repositories pr ON pr.project_id = a.project_id
       WHERE a.id = NEW.attempt_id
         AND a.executor_slot_id = NEW.executor_slot_id
         AND pr.repository_id = NEW.repository_id
         AND pr.access_mode IN ('build','integrate')
     );

  SELECT RAISE(ABORT, 'workspace base commit is benchmark-tainted')
  WHERE EXISTS (
    SELECT 1 FROM workspace_commit_taints taint
    WHERE taint.repository_id = NEW.repository_id
      AND taint.commit_id = NEW.base_commit
  );

  SELECT RAISE(ABORT, 'workspace base lacks a current clean reachable-commit attestation')
  WHERE NOT EXISTS (
    SELECT 1
    FROM repository_taint_state taint_state
    JOIN commit_lineage_attestations lineage
      ON lineage.repository_id = taint_state.repository_id
     AND lineage.repository_taint_revision = taint_state.revision
     AND lineage.candidate_commit = NEW.base_commit
     AND lineage.verdict = 'clean'
    WHERE taint_state.repository_id = NEW.repository_id
  );

  SELECT RAISE(ABORT, 'benchmark workspace violates the frozen base or arm namespace')
  WHERE EXISTS (
      SELECT 1
      FROM attempts attempt
      JOIN runs run ON run.id = attempt.run_id
      WHERE attempt.id = NEW.attempt_id
        AND run.benchmark_preregistration_digest IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1
      FROM attempts attempt
      JOIN runs run ON run.id = attempt.run_id
      JOIN benchmark_arm_runs arm
        ON arm.preregistration_digest = run.benchmark_preregistration_digest
       AND arm.task_id = run.benchmark_task_id
       AND arm.arm = run.benchmark_arm
      WHERE attempt.id = NEW.attempt_id
        AND NEW.base_commit = arm.base_commit
        AND substr(NEW.workspace_path, 1, length(arm.isolation_namespace) + 1)
            = arm.isolation_namespace || '/'
        AND substr(NEW.git_dir_path, 1, length(arm.isolation_namespace) + 1)
            = arm.isolation_namespace || '/'
        AND instr(NEW.workspace_path, '..') = 0
        AND instr(NEW.git_dir_path, '..') = 0
    );
END;

CREATE TRIGGER workspaces_legal_state_transition
BEFORE UPDATE OF state ON workspaces
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal workspace state transition')
  WHERE NOT (
    (OLD.state = 'provisioning' AND NEW.state IN ('ready','quarantined','removed'))
    OR (OLD.state = 'ready' AND NEW.state IN ('dirty','sealed','quarantined','removed'))
    OR (OLD.state = 'dirty' AND NEW.state IN ('sealed','quarantined','removed'))
    OR (OLD.state = 'sealed' AND NEW.state IN ('quarantined','removed'))
    OR (OLD.state = 'quarantined' AND NEW.state = 'removed')
  );
END;

CREATE TRIGGER workspace_output_commit_set_only_when_sealed
BEFORE UPDATE OF output_commit ON workspaces
WHEN OLD.output_commit IS NOT NEW.output_commit
BEGIN
  SELECT RAISE(ABORT, 'workspace output commit is set once by sealing transition')
  WHERE OLD.output_commit IS NOT NULL
     OR NEW.output_commit IS NULL
     OR NEW.state <> 'sealed'
     OR OLD.state NOT IN ('ready','dirty');
END;

CREATE TRIGGER merge_requests_enter_queued
BEFORE INSERT ON merge_requests
WHEN NEW.state <> 'queued'
BEGIN SELECT RAISE(ABORT, 'merge requests must enter through queued'); END;

CREATE TRIGGER benchmark_merge_requests_cannot_transition
BEFORE UPDATE OF state ON merge_requests
WHEN OLD.state <> NEW.state
  AND EXISTS (
    SELECT 1 FROM runs benchmark_run
    WHERE benchmark_run.id = NEW.run_id
      AND benchmark_run.benchmark_preregistration_digest IS NOT NULL
  )
BEGIN SELECT RAISE(ABORT, 'benchmark runs are permanently remote-merge ineligible'); END;

CREATE TRIGGER merge_request_matches_accepted_workspace_lineage
BEFORE INSERT ON merge_requests
BEGIN
  SELECT RAISE(ABORT, 'merge intent is not exact, pristine, or control-plane signed')
  WHERE NEW.target_fence IS NOT NULL
     OR NEW.claim_token IS NOT NULL
     OR NEW.claim_until_ms IS NOT NULL
     OR NEW.claim_leader_term IS NOT NULL
     OR NEW.merged_commit IS NOT NULL
     OR NEW.terminal_provider_observation_id IS NOT NULL
     OR NEW.terminal_head_observation_id IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.repository_id') IS NOT NEW.repository_id
     OR json_extract(NEW.canonical_json, '$.integration_target_id') IS NOT NEW.integration_target_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.node_version_id') IS NOT NEW.node_version_id
     OR json_extract(NEW.canonical_json, '$.candidate_commit') IS NOT NEW.candidate_commit
     OR json_extract(NEW.canonical_json, '$.base_commit') IS NOT NEW.base_commit
     OR json_extract(NEW.canonical_json, '$.merge_subject_digest') IS NOT NEW.merge_subject_digest
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.provider_idempotency_key') IS NOT NEW.provider_idempotency_key
     OR json_extract(NEW.canonical_json, '$.request_digest') IS NOT NEW.request_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR EXISTS (
       SELECT 1 FROM runs benchmark_run
       WHERE benchmark_run.id = NEW.run_id
         AND benchmark_run.benchmark_preregistration_digest IS NOT NULL
     )
     OR EXISTS (
       SELECT 1 FROM workspace_commit_taints taint
       WHERE taint.repository_id = NEW.repository_id
         AND taint.commit_id = NEW.candidate_commit
     )
     OR NOT EXISTS (
       SELECT 1
       FROM repository_taint_state taint_state
       JOIN commit_lineage_attestations lineage
         ON lineage.repository_id = taint_state.repository_id
        AND lineage.repository_taint_revision = taint_state.revision
        AND lineage.candidate_commit = NEW.candidate_commit
        AND lineage.verdict = 'clean'
       WHERE taint_state.repository_id = NEW.repository_id
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys key
       JOIN principals signer ON signer.id = key.principal_id
       WHERE key.key_id = NEW.signer_key_id
         AND key.principal_id = NEW.signer_principal_id
         AND key.key_purpose = 'release_broker'
         AND signer.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'merge_request'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.request_digest
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );

  SELECT RAISE(ABORT, 'merge request does not match accepted producer workspace and target')
  WHERE NOT EXISTS (
    SELECT 1
    FROM node_versions nv
    JOIN attempts a ON a.id = nv.accepted_attempt_id
    JOIN workspaces w ON w.attempt_id = a.id
    JOIN runs r ON r.id = nv.run_id
    JOIN project_repositories pr
      ON pr.project_id = a.project_id
     AND pr.repository_id = NEW.repository_id
     AND pr.access_mode = 'integrate'
    JOIN integration_targets t
      ON t.id = NEW.integration_target_id
     AND t.repository_id = NEW.repository_id
    WHERE nv.id = NEW.node_version_id
      AND nv.run_id = NEW.run_id
      AND nv.state = 'accepted'
      AND r.project_id = a.project_id
      AND w.repository_id = NEW.repository_id
      AND w.executor_slot_id = a.executor_slot_id
      AND w.state = 'sealed'
      AND w.output_commit = NEW.candidate_commit
      AND w.base_commit = NEW.base_commit
  );
END;

CREATE TRIGGER external_effects_enter_prepared
BEFORE INSERT ON external_effects
WHEN NEW.state <> 'prepared'
BEGIN SELECT RAISE(ABORT, 'external effects must enter through prepared'); END;

CREATE TRIGGER external_effect_intent_matches_gate_and_approval
BEFORE INSERT ON external_effects
BEGIN
  SELECT RAISE(ABORT, 'external-effect intent is not exact, pristine, or control-plane signed')
  WHERE NEW.remote_object_id IS NOT NULL
     OR NEW.claim_token IS NOT NULL
     OR NEW.claim_until_ms IS NOT NULL
     OR NEW.claim_leader_term IS NOT NULL
     OR NEW.execution_started_at_ms IS NOT NULL
     OR NEW.execution_head_observation_id IS NOT NULL
     OR NEW.terminal_provider_observation_id IS NOT NULL
     OR NEW.manual_reconcile_command_authorization_digest IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.effect_type') IS NOT NEW.effect_type
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.remote_object_type') IS NOT NEW.remote_object_type
     OR json_extract(NEW.canonical_json, '$.idempotency_key') IS NOT NEW.idempotency_key
     OR json_extract(NEW.canonical_json, '$.remote_idempotency_key') IS NOT NEW.remote_idempotency_key
     OR json_extract(NEW.canonical_json, '$.gate_bundle_digest') IS NOT NEW.gate_bundle_digest
     OR json_extract(NEW.canonical_json, '$.approval_request_id') IS NOT NEW.approval_request_id
     OR json_extract(NEW.canonical_json, '$.payload_artifact_instance_id') IS NOT NEW.payload_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.effect_subject_digest') IS NOT NEW.effect_subject_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys key
       JOIN principals signer ON signer.id = key.principal_id
       WHERE key.key_id = NEW.signer_key_id
         AND key.principal_id = NEW.signer_principal_id
         AND key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'external_effect'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.payload_digest
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );

  SELECT RAISE(ABORT, 'external-effect payload is not the exact scanned immutable artifact')
  WHERE NOT EXISTS (
    SELECT 1
    FROM artifact_instances payload
    JOIN artifact_blobs blob ON blob.digest = payload.blob_digest
    JOIN artifact_manifests manifest ON manifest.digest = payload.manifest_digest
    JOIN current_valid_keys manifest_key
      ON manifest_key.key_id = manifest.signer_key_id
     AND manifest_key.key_purpose = 'artifact_broker'
    JOIN sanitization_attestations scan
      ON scan.subject_manifest_digest = manifest.digest
    WHERE payload.id = NEW.payload_artifact_instance_id
      AND payload.artifact_type = 'external_effect_payload'
      AND payload.project_id = NEW.project_id
      AND payload.run_id = NEW.run_id
      AND blob.digest = NEW.payload_digest
      AND json_extract(manifest.canonical_json, '$.effect_intent.effect_id') = NEW.id
      AND json_extract(manifest.canonical_json, '$.effect_intent.effect_type') = NEW.effect_type
      AND json_extract(manifest.canonical_json, '$.effect_intent.provider') = NEW.provider
      AND json_extract(manifest.canonical_json, '$.effect_intent.gate_bundle_digest') = NEW.gate_bundle_digest
      AND scan.secret_scan_passed = 1
      AND scan.realpath_contained = 1
  );

  SELECT RAISE(ABORT, 'benchmark-tainted artifact instance can never become an external-effect payload')
  WHERE EXISTS (
    SELECT 1
    FROM artifact_instances payload
    JOIN artifact_instance_taints taint ON taint.artifact_instance_id = payload.id
    WHERE payload.id = NEW.payload_artifact_instance_id
  );

  SELECT RAISE(ABORT, 'external effect does not match a currently valid project/run gate')
  WHERE NOT EXISTS (
    SELECT 1
    FROM gate_bundles g
    JOIN merge_requests mr ON mr.id = g.merge_request_id
    JOIN integration_targets it ON it.id = mr.integration_target_id
    WHERE g.digest = NEW.gate_bundle_digest
      AND g.project_id = NEW.project_id
      AND g.run_id = NEW.run_id
      AND mr.target_fence = g.target_fence
      AND it.fence_counter = g.target_fence
      AND it.target_ref = g.target_ref
      AND NOT EXISTS (
        SELECT 1 FROM gate_invalidations gi
        WHERE gi.gate_bundle_digest = g.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest = g.policy_digest
      )
  );

  SELECT RAISE(ABORT, 'gate release policy has no rule for this effect type')
  WHERE NOT EXISTS (
    SELECT 1
    FROM gate_bundles g
    JOIN release_policy_effect_rules r
      ON r.policy_digest = g.policy_digest
     AND r.effect_type = NEW.effect_type
    WHERE g.digest = NEW.gate_bundle_digest
  );

  SELECT RAISE(ABORT, 'release policy requires a human approval request')
  WHERE EXISTS (
      SELECT 1
      FROM gate_bundles g
      JOIN release_policy_effect_rules r
        ON r.policy_digest = g.policy_digest
       AND r.effect_type = NEW.effect_type
      WHERE g.digest = NEW.gate_bundle_digest
        AND r.human_approval_required = 1
    )
    AND NEW.approval_request_id IS NULL;

  SELECT RAISE(ABORT, 'external effect references an invalid approval')
  WHERE NEW.approval_request_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM approval_requests ar
      JOIN approval_decisions ad ON ad.request_id = ar.id
      JOIN gate_bundles g ON g.digest = NEW.gate_bundle_digest
      JOIN release_policy_effect_rules r
        ON r.policy_digest = g.policy_digest
       AND r.effect_type = NEW.effect_type
      WHERE ar.id = NEW.approval_request_id
        AND ar.project_id = NEW.project_id
        AND ar.gate_bundle_digest = NEW.gate_bundle_digest
        AND ar.requested_action = NEW.effect_type
        AND ar.payload_digest = NEW.payload_digest
        AND (r.human_approval_required = 0 OR ar.required_role = r.required_role)
        AND ad.decision = 'approve'
        AND NEW.created_at_ms <= ar.expires_at_ms
        AND NOT EXISTS (
          SELECT 1 FROM approval_invalidations ai
          WHERE ai.request_id = ar.id
        )
    );
END;

CREATE TRIGGER release_policy_effect_rules_are_authorized
BEFORE INSERT ON release_policy_effect_rules
BEGIN
  SELECT RAISE(ABORT, 'effect rule requires a signed release policy')
  WHERE NOT EXISTS (
    SELECT 1 FROM policies p, json_each(p.canonical_json, '$.effect_rules') rule
    WHERE p.digest = NEW.policy_digest
      AND p.policy_type = 'release'
      AND json_extract(rule.value, '$.effect_type') = NEW.effect_type
      AND json_extract(rule.value, '$.human_approval_required') = NEW.human_approval_required
      AND json_extract(rule.value, '$.required_role') IS NEW.required_role
  );

  SELECT RAISE(ABORT, 'production-bound effects always require human approval')
  WHERE NEW.effect_type IN ('production_pr','deploy','publish','release','client_deliverable')
    AND (NEW.human_approval_required <> 1 OR NEW.required_role NOT IN ('owner','approver'));
END;

