BEFORE UPDATE ON release_policy_effect_rules
BEGIN SELECT RAISE(ABORT, 'release policy effect rules are immutable'); END;

CREATE TRIGGER release_policy_effect_rules_no_delete
BEFORE DELETE ON release_policy_effect_rules
BEGIN SELECT RAISE(ABORT, 'release policy effect rules are immutable'); END;

CREATE TRIGGER host_resource_policy_limits_are_authorized
BEFORE INSERT ON host_resource_policy_limits
BEGIN
  SELECT RAISE(ABORT, 'host-resource limits require a signed host_resource policy')
  WHERE NOT EXISTS (
    SELECT 1 FROM policies p
    WHERE p.digest = NEW.policy_digest
      AND p.policy_type = 'host_resource'
      AND json_extract(p.canonical_json, '$.limits.max_model_rss_fraction_ppm') = NEW.max_model_rss_fraction_ppm
      AND json_extract(p.canonical_json, '$.limits.emergency_disk_bytes') = NEW.emergency_disk_bytes
      AND json_extract(p.canonical_json, '$.limits.clone_log_allowance_bytes') = NEW.clone_log_allowance_bytes
      AND json_extract(p.canonical_json, '$.limits.emergency_ram_bytes') = NEW.emergency_ram_bytes
      AND json_extract(p.canonical_json, '$.limits.min_platform_baseline_rss_bytes') = NEW.min_platform_baseline_rss_bytes
      AND json_extract(p.canonical_json, '$.limits.control_cpu_millis') = NEW.control_cpu_millis
      AND json_extract(p.canonical_json, '$.limits.cpu_oversubscription_ppm') = NEW.cpu_oversubscription_ppm
      AND json_extract(p.canonical_json, '$.limits.persistent_idle_cpu_millis') = NEW.persistent_idle_cpu_millis
      AND json_extract(p.canonical_json, '$.limits.active_call_cpu_millis') = NEW.active_call_cpu_millis
      AND json_extract(p.canonical_json, '$.limits.cpu_window_ms') = NEW.cpu_window_ms
      AND json_extract(p.canonical_json, '$.limits.max_model_pid_count') = NEW.max_model_pid_count
      AND json_extract(p.canonical_json, '$.limits.max_model_fd_count') = NEW.max_model_fd_count
  );
END;

