BEFORE UPDATE ON host_resource_policy_limits
BEGIN SELECT RAISE(ABORT, 'host-resource policy limits are immutable'); END;

CREATE TRIGGER host_resource_policy_limits_no_delete
BEFORE DELETE ON host_resource_policy_limits
BEGIN SELECT RAISE(ABORT, 'host-resource policy limits are immutable'); END;

CREATE TRIGGER resource_profiles_are_authorized
BEFORE INSERT ON resource_profiles
BEGIN
  SELECT RAISE(ABORT, 'resource profile requires active signed policies and valid role dimensions')
  WHERE NOT EXISTS (
    SELECT 1
    FROM policies pp
    JOIN signing_keys psk ON psk.key_id = pp.signer_key_id
    JOIN policies hp ON hp.digest = NEW.host_policy_digest
    JOIN host_resource_policy_limits lim ON lim.policy_digest = hp.digest
    WHERE pp.digest = NEW.digest
      AND pp.policy_type = 'resource_profile'
      AND json_extract(pp.canonical_json, '$.host_policy_digest') = NEW.host_policy_digest
      AND json_extract(pp.canonical_json, '$.profile_name') = NEW.profile_name
      AND json_extract(pp.canonical_json, '$.pool') = NEW.pool
      AND json_extract(pp.canonical_json, '$.reservation_kind') = NEW.reservation_kind
      AND json_extract(pp.canonical_json, '$.disk_bytes') = NEW.disk_bytes
      AND json_extract(pp.canonical_json, '$.rss_bytes') = NEW.rss_bytes
      AND json_extract(pp.canonical_json, '$.pid_count') = NEW.pid_count
      AND json_extract(pp.canonical_json, '$.fd_count') = NEW.fd_count
      AND json_extract(pp.canonical_json, '$.cpu_millis') = NEW.cpu_millis
      AND hp.policy_type = 'host_resource'
      AND psk.state = 'active'
      AND (psk.expires_at_ms IS NULL OR psk.expires_at_ms >= pp.created_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest IN (pp.digest, hp.digest)
      )
      AND (
        (NEW.profile_name IN ('fable_portfolio_process','fable_project_process')
          AND NEW.pool = 'fable'
          AND NEW.reservation_kind = 'process'
          AND NEW.disk_bytes BETWEEN 5368709120 AND 8589934592
          AND NEW.rss_bytes BETWEEN 4294967296 AND 6442450944
          AND NEW.pid_count BETWEEN 32 AND 64
          AND NEW.fd_count BETWEEN 1024 AND 2048
          AND NEW.cpu_millis = lim.persistent_idle_cpu_millis)
        OR (NEW.profile_name = 'fable_active_call'
          AND NEW.pool = 'fable'
          AND NEW.reservation_kind = 'active_call'
          AND NEW.disk_bytes = 0 AND NEW.rss_bytes = 0
          AND NEW.pid_count = 0 AND NEW.fd_count = 0
          AND NEW.cpu_millis = lim.active_call_cpu_millis)
        OR (NEW.profile_name = 'codex_fresh_process'
          AND NEW.pool = 'codex'
          AND NEW.reservation_kind = 'process'
          AND NEW.disk_bytes BETWEEN 5368709120 AND 8589934592
          AND NEW.rss_bytes BETWEEN 3221225472 AND 4294967296
          AND NEW.pid_count BETWEEN 32 AND 64
          AND NEW.fd_count BETWEEN 1024 AND 2048
          AND NEW.cpu_millis = lim.active_call_cpu_millis)
        OR (NEW.profile_name IN ('opus_fresh_process','managed_opus_process')
          AND NEW.pool = 'opus'
          AND NEW.reservation_kind = 'process'
          AND NEW.disk_bytes BETWEEN 5368709120 AND 8589934592
          AND NEW.rss_bytes BETWEEN 4294967296 AND 6442450944
          AND NEW.pid_count BETWEEN 32 AND 64
          AND NEW.fd_count BETWEEN 1024 AND 2048
          AND NEW.cpu_millis = lim.active_call_cpu_millis)
      )
  );
END;

CREATE TRIGGER resource_profiles_no_update
BEFORE UPDATE ON resource_profiles
BEGIN SELECT RAISE(ABORT, 'resource profiles are immutable'); END;

CREATE TRIGGER resource_profiles_no_delete
BEFORE DELETE ON resource_profiles
BEGIN SELECT RAISE(ABORT, 'resource profiles are immutable'); END;

CREATE TRIGGER release_authority_snapshot_is_exact_current_and_signed
BEFORE INSERT ON release_authority_snapshots
BEGIN
  SELECT RAISE(ABORT, 'release authority snapshot is not an exact current authority projection')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.attempt_no') IS NOT NEW.attempt_no
     OR json_extract(NEW.canonical_json, '$.subject_digest') IS NOT NEW.subject_digest
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.request_digest') IS NOT NEW.request_digest
     OR json_extract(NEW.canonical_json, '$.provider_idempotency_key') IS NOT NEW.provider_idempotency_key
     OR json_extract(NEW.canonical_json, '$.target_fence') IS NOT NEW.target_fence
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.gate_bundle_digest') IS NOT NEW.gate_bundle_digest
     OR json_extract(NEW.canonical_json, '$.policy_digest') IS NOT NEW.policy_digest
     OR json_extract(NEW.canonical_json, '$.approval_request_id') IS NOT NEW.approval_request_id
     OR json_extract(NEW.canonical_json, '$.target_head_observation_id') IS NOT NEW.target_head_observation_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM gate_bundles current_gate
       JOIN repository_taint_state taint_state
         ON taint_state.repository_id = current_gate.repository_id
       JOIN commit_lineage_attestations lineage
         ON lineage.repository_id = current_gate.repository_id
        AND lineage.repository_taint_revision = taint_state.revision
        AND lineage.candidate_commit = current_gate.candidate_commit
        AND lineage.verdict = 'clean'
       WHERE current_gate.digest = NEW.gate_bundle_digest
     )
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys release_key
       JOIN principals signer ON signer.id = release_key.principal_id
       JOIN control_state ctl
         ON ctl.current_term = NEW.leader_term
        AND ctl.admission_mode = 'open'
        AND ctl.dispatch_enabled = 1
        AND ctl.kill_switch = 0
       JOIN leader_terms lt ON lt.term = NEW.leader_term AND lt.state = 'active'
       JOIN target_head_observations head ON head.id = NEW.target_head_observation_id
       WHERE release_key.key_id = NEW.signer_key_id
         AND release_key.principal_id = NEW.signer_principal_id
         AND release_key.key_purpose = 'release_broker'
         AND signer.kind = 'service'
         AND (
           (NEW.subject_kind = 'merge_request' AND EXISTS (
             SELECT 1
             FROM merge_requests mr
             JOIN integration_targets target ON target.id = mr.integration_target_id
             JOIN gate_bundles gate
               ON gate.merge_request_id = mr.id
              AND gate.run_id = mr.run_id
              AND gate.repository_id = mr.repository_id
              AND gate.candidate_commit = mr.candidate_commit
              AND gate.base_commit = mr.base_commit
              AND gate.target_fence = mr.target_fence
              AND gate.target_head_observation_id = head.id
              AND gate.target_ref = target.target_ref
             WHERE mr.id = NEW.subject_id
               AND mr.state = 'integrating'
               AND mr.merge_subject_digest = NEW.subject_digest
               AND mr.provider = NEW.provider
               AND mr.request_digest = NEW.request_digest
               AND mr.provider_idempotency_key = NEW.provider_idempotency_key
               AND mr.target_fence = NEW.target_fence
               AND mr.claim_leader_term = NEW.leader_term
               AND NEW.gate_bundle_digest = gate.digest
               AND NEW.policy_digest = gate.policy_digest
               AND NEW.approval_request_id IS NULL
               AND head.integration_target_id = target.id
               AND head.target_fence = mr.target_fence
               AND head.target_ref = target.target_ref
               AND head.provider = mr.provider
               AND head.observed_commit = mr.base_commit
               AND NOT EXISTS (
                 SELECT 1 FROM gate_invalidations invalidation
                 WHERE invalidation.gate_bundle_digest = gate.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM policy_invalidations invalidation
                 WHERE invalidation.policy_digest = gate.policy_digest
               )
           ))
           OR (NEW.subject_kind = 'external_effect' AND EXISTS (
             SELECT 1
             FROM external_effects effect
             JOIN gate_bundles gate ON gate.digest = effect.gate_bundle_digest
             JOIN merge_requests merged ON merged.id = gate.merge_request_id
             WHERE effect.id = NEW.subject_id
               AND effect.state = 'executing'
               AND merged.state = 'succeeded'
               AND merged.merged_commit = gate.candidate_commit
               AND merged.terminal_head_observation_id IS NOT NULL
               AND effect.effect_subject_digest = NEW.subject_digest
               AND effect.provider = NEW.provider
               AND effect.payload_digest = NEW.request_digest
               AND effect.remote_idempotency_key = NEW.provider_idempotency_key
               AND effect.claim_leader_term = NEW.leader_term
               AND gate.target_fence = NEW.target_fence
               AND gate.digest = NEW.gate_bundle_digest
               AND gate.policy_digest = NEW.policy_digest
               AND effect.approval_request_id IS NEW.approval_request_id
               AND head.id = effect.execution_head_observation_id
               AND head.target_fence = gate.target_fence
               AND head.target_ref = gate.target_ref
               AND head.provider = effect.provider
               AND head.observed_commit = gate.candidate_commit
               AND NOT EXISTS (
                 SELECT 1 FROM gate_invalidations gi WHERE gi.gate_bundle_digest = gate.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = gate.policy_digest
               )
               AND (
                 NOT EXISTS (
                   SELECT 1 FROM release_policy_effect_rules rule
                   WHERE rule.policy_digest = gate.policy_digest
                     AND rule.effect_type = effect.effect_type
                     AND rule.human_approval_required = 1
                 )
                 OR EXISTS (
                   SELECT 1
                   FROM approval_requests request
                   JOIN approval_decisions decision
                     ON decision.request_id = request.id AND decision.decision = 'approve'
                   JOIN principals human
                     ON human.id = decision.principal_id AND human.state = 'active'
                   JOIN principal_project_roles role
                     ON role.principal_id = decision.principal_id
                    AND role.project_id = effect.project_id
                    AND role.role = request.required_role
                    AND role.revoked_at_ms IS NULL
                   JOIN current_valid_keys approval_key
                     ON approval_key.key_id = decision.signer_key_id
                    AND approval_key.principal_id = decision.signer_principal_id
                    AND approval_key.key_purpose = 'approval_broker'
                   WHERE request.id = effect.approval_request_id
                     AND request.gate_bundle_digest = gate.digest
                     AND request.requested_action = effect.effect_type
                     AND request.payload_digest = effect.payload_digest
                     AND request.expires_at_ms >= NEW.expires_at_ms
                     AND NOT EXISTS (
                       SELECT 1 FROM approval_invalidations invalidation
                       WHERE invalidation.request_id = request.id
                     )
                 )
               )
           ))
         )
         AND head.observed_at_ms BETWEEN NEW.created_at_ms - 60000 AND NEW.created_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM target_head_observations later
           WHERE later.integration_target_id = head.integration_target_id
             AND later.target_fence = head.target_fence
             AND later.observed_at_ms > head.observed_at_ms
         )
     );

  SELECT RAISE(ABORT, 'release-authority snapshot signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'release_authority_snapshot'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.record_digest_verified = 1
      AND receipt.verified_record_digest = NEW.digest
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER release_authority_snapshots_no_update
BEFORE UPDATE ON release_authority_snapshots
BEGIN SELECT RAISE(ABORT, 'release authority snapshots are immutable'); END;

CREATE TRIGGER release_authority_snapshots_no_delete
BEFORE DELETE ON release_authority_snapshots
BEGIN SELECT RAISE(ABORT, 'release authority snapshots are immutable'); END;

CREATE TRIGGER egress_permit_is_exact_current_and_release_broker_signed
BEFORE INSERT ON egress_permits
BEGIN
  SELECT RAISE(ABORT, 'egress permit is not exact, current, or release-broker signed')
  WHERE NEW.state <> 'issued'
     OR NEW.consumed_at_ms IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM resource_reservations reservation
       WHERE reservation.state = 'breached'
     )
     OR NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms > NEW.issued_at_ms + 30000
     OR (NEW.subject_kind = 'merge_request' AND EXISTS (
       SELECT 1
       FROM merge_requests merge_request
       JOIN runs benchmark_run ON benchmark_run.id = merge_request.run_id
       WHERE merge_request.id = NEW.subject_id
         AND benchmark_run.benchmark_preregistration_digest IS NOT NULL
     ))
     OR NEW.attempt_no <> CASE NEW.subject_kind
       WHEN 'merge_request' THEN COALESCE((
         SELECT MAX(attempt_no) + 1 FROM merge_attempts
         WHERE merge_request_id = NEW.subject_id
       ), 1)
       ELSE COALESCE((
         SELECT MAX(attempt_no) + 1 FROM external_effect_attempts
         WHERE external_effect_id = NEW.subject_id
       ), 1)
     END
     OR (NEW.attempt_no > 1 AND NOT (
       (NEW.subject_kind = 'merge_request' AND EXISTS (
         SELECT 1
         FROM merge_attempts prior_attempt
         JOIN egress_permits prior_permit
           ON prior_permit.id = prior_attempt.egress_permit_id
          AND prior_permit.attempt_no = NEW.attempt_no - 1
         JOIN provider_operation_observations prior_observation
           ON prior_observation.id = prior_attempt.provider_observation_id
         WHERE prior_attempt.merge_request_id = NEW.subject_id
           AND prior_attempt.attempt_no = NEW.attempt_no - 1
           AND prior_attempt.state = 'failed'
           AND prior_permit.state = 'consumed'
           AND prior_observation.observed_state IN ('failed','cancelled','absent')
       ))
       OR (NEW.subject_kind = 'external_effect' AND EXISTS (
         SELECT 1
         FROM external_effect_attempts prior_attempt
         JOIN egress_permits prior_permit
           ON prior_permit.id = prior_attempt.egress_permit_id
          AND prior_permit.attempt_no = NEW.attempt_no - 1
         JOIN provider_operation_observations prior_observation
           ON prior_observation.id = prior_attempt.provider_observation_id
         WHERE prior_attempt.external_effect_id = NEW.subject_id
           AND prior_attempt.attempt_no = NEW.attempt_no - 1
           AND prior_attempt.state = 'failed'
           AND prior_permit.state = 'consumed'
           AND prior_observation.observed_state IN ('failed','cancelled','absent')
       ))
     ))
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.attempt_no') IS NOT NEW.attempt_no
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.subject_digest') IS NOT NEW.subject_digest
     OR json_extract(NEW.canonical_json, '$.request_digest') IS NOT NEW.request_digest
     OR json_extract(NEW.canonical_json, '$.provider_idempotency_key') IS NOT NEW.provider_idempotency_key
     OR json_extract(NEW.canonical_json, '$.target_fence') IS NOT NEW.target_fence
     OR json_extract(NEW.canonical_json, '$.authority_snapshot_digest') IS NOT NEW.authority_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM release_authority_snapshots snapshot
       JOIN current_valid_keys snapshot_key
         ON snapshot_key.key_id = snapshot.signer_key_id
        AND snapshot_key.principal_id = snapshot.signer_principal_id
        AND snapshot_key.key_purpose = 'release_broker'
       WHERE snapshot.digest = NEW.authority_snapshot_digest
         AND snapshot.subject_kind = NEW.subject_kind
         AND snapshot.subject_id = NEW.subject_id
         AND snapshot.attempt_no = NEW.attempt_no
         AND snapshot.subject_digest = NEW.subject_digest
         AND snapshot.provider = NEW.provider
         AND snapshot.request_digest = NEW.request_digest
         AND snapshot.provider_idempotency_key = NEW.provider_idempotency_key
         AND snapshot.target_fence = NEW.target_fence
         AND snapshot.leader_term = NEW.leader_term
         AND snapshot.created_at_ms <= NEW.issued_at_ms
         AND snapshot.expires_at_ms >= NEW.expires_at_ms
     )
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys release_key
       JOIN principals broker ON broker.id = release_key.principal_id
       JOIN leader_terms lt ON lt.term = NEW.leader_term AND lt.state = 'active'
       JOIN control_state ctl
         ON ctl.current_term = NEW.leader_term
        AND ctl.admission_mode = 'open'
        AND ctl.dispatch_enabled = 1
        AND ctl.kill_switch = 0
       WHERE release_key.key_id = NEW.signer_key_id
         AND release_key.principal_id = NEW.signer_principal_id
         AND release_key.key_purpose = 'release_broker'
         AND broker.kind = 'service'
         AND (
           (NEW.subject_kind = 'merge_request' AND EXISTS (
             SELECT 1
             FROM merge_requests mr
             JOIN integration_targets target ON target.id = mr.integration_target_id
             WHERE mr.id = NEW.subject_id
               AND mr.state = 'integrating'
               AND mr.provider = NEW.provider
               AND mr.merge_subject_digest = NEW.subject_digest
               AND mr.request_digest = NEW.request_digest
               AND mr.provider_idempotency_key = NEW.provider_idempotency_key
               AND mr.target_fence = NEW.target_fence
               AND mr.claim_leader_term = NEW.leader_term
               AND mr.claim_until_ms >= NEW.expires_at_ms
               AND target.state = 'integrating'
               AND target.fence_counter = mr.target_fence
               AND EXISTS (
                 SELECT 1 FROM target_head_observations head
                 WHERE head.integration_target_id = target.id
                   AND head.target_fence = mr.target_fence
                   AND head.target_ref = target.target_ref
                   AND head.provider = mr.provider
                   AND head.observed_commit = mr.base_commit
                   AND head.observed_at_ms BETWEEN NEW.issued_at_ms - 60000 AND NEW.issued_at_ms
                   AND NOT EXISTS (
                     SELECT 1 FROM target_head_observations later
                     WHERE later.integration_target_id = head.integration_target_id
                       AND later.target_fence = head.target_fence
                       AND later.observed_at_ms > head.observed_at_ms
                   )
               )
           ))
           OR (NEW.subject_kind = 'external_effect' AND EXISTS (
             SELECT 1
             FROM external_effects effect
             JOIN gate_bundles gate ON gate.digest = effect.gate_bundle_digest
             JOIN merge_requests merged ON merged.id = gate.merge_request_id
             WHERE effect.id = NEW.subject_id
               AND effect.state = 'executing'
               AND merged.state = 'succeeded'
               AND merged.merged_commit = gate.candidate_commit
               AND merged.terminal_provider_observation_id IS NOT NULL
               AND merged.terminal_head_observation_id IS NOT NULL
               AND effect.provider = NEW.provider
               AND effect.effect_subject_digest = NEW.subject_digest
               AND effect.payload_digest = NEW.request_digest
               AND effect.remote_idempotency_key = NEW.provider_idempotency_key
               AND effect.claim_leader_term = NEW.leader_term
               AND gate.target_fence = NEW.target_fence
               AND effect.claim_until_ms >= NEW.expires_at_ms
               AND EXISTS (
                 SELECT 1
                 FROM target_head_observations head
                 WHERE head.id = effect.execution_head_observation_id
                   AND head.provider = effect.provider
                   AND head.target_fence = gate.target_fence
                   AND head.target_ref = gate.target_ref
                   AND head.observed_commit = gate.candidate_commit
                   AND head.observed_at_ms BETWEEN NEW.issued_at_ms - 60000 AND NEW.issued_at_ms
                   AND NOT EXISTS (
                     SELECT 1 FROM target_head_observations later
                     WHERE later.integration_target_id = head.integration_target_id
                       AND later.target_fence = head.target_fence
                       AND later.observed_at_ms > head.observed_at_ms
                   )
               )
               AND NOT EXISTS (
                 SELECT 1 FROM gate_invalidations gi WHERE gi.gate_bundle_digest = gate.digest
               )
               AND NOT EXISTS (
                 SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = gate.policy_digest
               )
               AND (effect.approval_request_id IS NULL OR NOT EXISTS (
                 SELECT 1 FROM approval_invalidations ai
                 WHERE ai.request_id = effect.approval_request_id
               ))
           ))
         )
     );

  SELECT RAISE(ABORT, 'egress-permit signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'egress_permit'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
  );
END;

CREATE TRIGGER egress_permits_legal_state_transition
BEFORE UPDATE OF state ON egress_permits
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal or stale egress-permit transition')
  WHERE OLD.state <> 'issued'
     OR NEW.state NOT IN ('consumed','revoked','expired')
     OR (NEW.state = 'consumed' AND (
       NEW.consumed_at_ms IS NULL
       OR NEW.consumed_at_ms < OLD.issued_at_ms
       OR NEW.consumed_at_ms > OLD.expires_at_ms
       OR NEW.consumed_at_ms < (unixepoch('subsec') * 1000) - 5000
       OR NEW.consumed_at_ms > (unixepoch('subsec') * 1000) + 5000
       OR (unixepoch('subsec') * 1000) > OLD.expires_at_ms
       OR (OLD.subject_kind = 'merge_request' AND EXISTS (
         SELECT 1
         FROM merge_requests merge_request
         JOIN runs benchmark_run ON benchmark_run.id = merge_request.run_id
         WHERE merge_request.id = OLD.subject_id
           AND benchmark_run.benchmark_preregistration_digest IS NOT NULL
       ))
       OR EXISTS (
         SELECT 1 FROM resource_reservations reservation
         WHERE reservation.state = 'breached'
       )
       OR NOT EXISTS (
         SELECT 1 FROM control_state ctl
         JOIN leader_terms lt ON lt.term = OLD.leader_term AND lt.state = 'active'
         WHERE ctl.current_term = OLD.leader_term
           AND ctl.admission_mode = 'open'
           AND ctl.dispatch_enabled = 1
           AND ctl.kill_switch = 0
       )
       OR NOT EXISTS (
         SELECT 1
         FROM release_authority_snapshots snapshot
         JOIN current_valid_keys snapshot_key
           ON snapshot_key.key_id = snapshot.signer_key_id
          AND snapshot_key.principal_id = snapshot.signer_principal_id
          AND snapshot_key.key_purpose = 'release_broker'
         JOIN current_valid_keys permit_key
           ON permit_key.key_id = OLD.signer_key_id
          AND permit_key.principal_id = OLD.signer_principal_id
          AND permit_key.key_purpose = 'release_broker'
         WHERE snapshot.digest = OLD.authority_snapshot_digest
           AND snapshot.subject_kind = OLD.subject_kind
           AND snapshot.subject_id = OLD.subject_id
           AND snapshot.attempt_no = OLD.attempt_no
           AND snapshot.subject_digest = OLD.subject_digest
           AND snapshot.provider = OLD.provider
           AND snapshot.request_digest = OLD.request_digest
           AND snapshot.provider_idempotency_key = OLD.provider_idempotency_key
           AND snapshot.target_fence = OLD.target_fence
           AND snapshot.leader_term = OLD.leader_term
           AND snapshot.expires_at_ms >= NEW.consumed_at_ms
       )
       OR NOT (
         (OLD.subject_kind = 'merge_request' AND EXISTS (
           SELECT 1 FROM merge_requests mr
           JOIN integration_targets t ON t.id = mr.integration_target_id
           JOIN release_authority_snapshots authority
             ON authority.digest = OLD.authority_snapshot_digest
            AND authority.subject_kind = 'merge_request'
            AND authority.subject_id = mr.id
           JOIN gate_bundles gate
             ON gate.digest = authority.gate_bundle_digest
            AND gate.merge_request_id = mr.id
            AND gate.repository_id = mr.repository_id
            AND gate.target_ref = t.target_ref
            AND gate.target_fence = mr.target_fence
            AND gate.base_commit = mr.base_commit
            AND gate.candidate_commit = mr.candidate_commit
           WHERE mr.id = OLD.subject_id
             AND mr.state = 'integrating'
             AND mr.provider = OLD.provider
             AND mr.merge_subject_digest = OLD.subject_digest
             AND mr.request_digest = OLD.request_digest
             AND mr.provider_idempotency_key = OLD.provider_idempotency_key
             AND mr.target_fence = OLD.target_fence
             AND mr.claim_leader_term = OLD.leader_term
             AND t.state = 'integrating'
             AND t.fence_counter = OLD.target_fence
             AND NOT EXISTS (
               SELECT 1 FROM gate_invalidations invalidation
               WHERE invalidation.gate_bundle_digest = gate.digest
             )
             AND NOT EXISTS (
               SELECT 1 FROM policy_invalidations invalidation
               WHERE invalidation.policy_digest = gate.policy_digest
             )
             AND EXISTS (
               SELECT 1 FROM target_head_observations head
               WHERE head.integration_target_id = t.id
                 AND head.target_fence = mr.target_fence
                 AND head.target_ref = t.target_ref
                 AND head.provider = mr.provider
                 AND head.observed_commit = mr.base_commit
                 AND head.observed_at_ms BETWEEN NEW.consumed_at_ms - 60000 AND NEW.consumed_at_ms
                 AND NOT EXISTS (
                   SELECT 1 FROM target_head_observations later
                   WHERE later.integration_target_id = head.integration_target_id
                     AND later.target_fence = head.target_fence
                     AND later.observed_at_ms > head.observed_at_ms
                 )
             )
         ))
         OR (OLD.subject_kind = 'external_effect' AND EXISTS (
           SELECT 1 FROM external_effects effect
           JOIN gate_bundles gate ON gate.digest = effect.gate_bundle_digest
           JOIN merge_requests merged ON merged.id = gate.merge_request_id
           WHERE effect.id = OLD.subject_id
             AND effect.state = 'executing'
             AND merged.state = 'succeeded'
             AND merged.merged_commit = gate.candidate_commit
             AND merged.terminal_provider_observation_id IS NOT NULL
             AND merged.terminal_head_observation_id IS NOT NULL
             AND effect.provider = OLD.provider
             AND effect.effect_subject_digest = OLD.subject_digest
             AND effect.payload_digest = OLD.request_digest
             AND effect.remote_idempotency_key = OLD.provider_idempotency_key
             AND effect.claim_leader_term = OLD.leader_term
             AND gate.target_fence = OLD.target_fence
             AND EXISTS (
               SELECT 1 FROM target_head_observations head
               WHERE head.id = effect.execution_head_observation_id
                 AND head.provider = effect.provider
                 AND head.target_fence = gate.target_fence
                 AND head.target_ref = gate.target_ref
                 AND head.observed_commit = gate.candidate_commit
                 AND head.observed_at_ms BETWEEN NEW.consumed_at_ms - 60000 AND NEW.consumed_at_ms
                 AND NOT EXISTS (
                   SELECT 1 FROM target_head_observations later
                   WHERE later.integration_target_id = head.integration_target_id
                     AND later.target_fence = head.target_fence
                     AND later.observed_at_ms > head.observed_at_ms
                 )
             )
             AND NOT EXISTS (
               SELECT 1 FROM gate_invalidations gi WHERE gi.gate_bundle_digest = gate.digest
             )
             AND NOT EXISTS (
               SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = gate.policy_digest
             )
             AND (
               NOT EXISTS (
                 SELECT 1 FROM release_policy_effect_rules rule
                 WHERE rule.policy_digest = gate.policy_digest
                   AND rule.effect_type = effect.effect_type
                   AND rule.human_approval_required = 1
               )
               OR EXISTS (
                 SELECT 1
                 FROM approval_requests request
                 JOIN approval_decisions decision
                   ON decision.request_id = request.id AND decision.decision = 'approve'
                 JOIN principals human
                   ON human.id = decision.principal_id AND human.state = 'active'
                 JOIN principal_project_roles role
                   ON role.principal_id = decision.principal_id
                  AND role.project_id = effect.project_id
                  AND role.role = request.required_role
                  AND role.revoked_at_ms IS NULL
                 JOIN current_valid_keys approval_key
                   ON approval_key.key_id = decision.signer_key_id
                  AND approval_key.principal_id = decision.signer_principal_id
                  AND approval_key.key_purpose = 'approval_broker'
                 WHERE request.id = effect.approval_request_id
                   AND request.gate_bundle_digest = gate.digest
                   AND request.requested_action = effect.effect_type
                   AND request.payload_digest = effect.payload_digest
                   AND request.expires_at_ms >= NEW.consumed_at_ms
                   AND NOT EXISTS (
                     SELECT 1 FROM approval_invalidations invalidation
                     WHERE invalidation.request_id = request.id
                   )
               )
             )
         ))
       )
     ))
     OR (NEW.state <> 'consumed' AND NEW.consumed_at_ms IS NOT NULL)
     OR (NEW.state = 'expired' AND (unixepoch('subsec') * 1000) < OLD.expires_at_ms);
END;

CREATE TRIGGER egress_permit_identity_is_immutable
BEFORE UPDATE OF id, subject_kind, subject_id, attempt_no, provider, subject_digest,
  request_digest, provider_idempotency_key, target_fence, authority_snapshot_digest,
  leader_term, canonical_json, signer_principal_id, signer_key_id, signature,
  issued_at_ms, expires_at_ms
ON egress_permits
BEGIN SELECT RAISE(ABORT, 'egress permit identity is immutable'); END;

CREATE TRIGGER egress_permit_consumption_is_set_once
BEFORE UPDATE OF consumed_at_ms ON egress_permits
WHEN OLD.consumed_at_ms IS NOT NEW.consumed_at_ms
BEGIN
  SELECT RAISE(ABORT, 'egress permit consumption is set once with consume transition')
  WHERE OLD.consumed_at_ms IS NOT NULL
     OR NEW.consumed_at_ms IS NULL
     OR OLD.state <> 'issued'
     OR NEW.state <> 'consumed';
END;

CREATE TRIGGER consumed_egress_permit_creates_attempt_before_commit
AFTER UPDATE OF state ON egress_permits
WHEN OLD.state = 'issued' AND NEW.state = 'consumed'
BEGIN
  INSERT INTO merge_attempts(
    id, merge_request_id, attempt_no, request_digest, egress_permit_id,
    response_digest, provider_observation_id, state, started_at_ms,
    finished_at_ms, error_code
  )
  SELECT 'merge-attempt:' || NEW.id, NEW.subject_id, NEW.attempt_no,
         NEW.request_digest, NEW.id, NULL, NULL, 'started',
         NEW.consumed_at_ms, NULL, NULL
  WHERE NEW.subject_kind = 'merge_request';

  INSERT INTO external_effect_attempts(
    id, external_effect_id, attempt_no, request_digest, egress_permit_id,
    response_digest, provider_observation_id, state, started_at_ms,
    finished_at_ms, error_code
  )
  SELECT 'effect-attempt:' || NEW.id, NEW.subject_id, NEW.attempt_no,
         NEW.request_digest, NEW.id, NULL, NULL, 'started',
         NEW.consumed_at_ms, NULL, NULL
  WHERE NEW.subject_kind = 'external_effect';
END;

CREATE TRIGGER egress_permits_no_delete
BEFORE DELETE ON egress_permits
BEGIN SELECT RAISE(ABORT, 'egress permits are append-only'); END;

CREATE TRIGGER provider_consistency_profile_is_exact_and_signed
BEFORE INSERT ON provider_consistency_profiles
BEGIN
  SELECT RAISE(ABORT, 'provider consistency profile is not exact or control-plane signed')
  WHERE NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR (NEW.absence_mode = 'strong' AND NEW.consistency_window_ms <> 0)
     OR (NEW.absence_mode = 'bounded_wait' AND NEW.consistency_window_ms = 0)
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.absence_mode') IS NOT NEW.absence_mode
     OR json_extract(NEW.canonical_json, '$.consistency_window_ms') IS NOT NEW.consistency_window_ms
     OR json_extract(NEW.canonical_json, '$.lookup_key_is_idempotency_scope') IS NOT NEW.lookup_key_is_idempotency_scope
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys key
       JOIN principals signer ON signer.id = key.principal_id
       WHERE key.key_id = NEW.signer_key_id
         AND key.principal_id = NEW.signer_principal_id
         AND key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
     );
END;

CREATE TRIGGER provider_consistency_profiles_no_update
BEFORE UPDATE ON provider_consistency_profiles
BEGIN SELECT RAISE(ABORT, 'provider consistency profiles are immutable'); END;

CREATE TRIGGER provider_consistency_profiles_no_delete
BEFORE DELETE ON provider_consistency_profiles
BEGIN SELECT RAISE(ABORT, 'provider consistency profiles are immutable'); END;

CREATE TRIGGER provider_health_observation_is_exact_and_signed
BEFORE INSERT ON provider_health_observations
BEGIN
  SELECT RAISE(ABORT, 'provider health observation is stale, inexact, or unsigned')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.observed_at_ms + 60000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.model_family') IS NOT NEW.model_family
     OR json_extract(NEW.canonical_json, '$.observed_state') IS NOT NEW.observed_state
     OR json_extract(NEW.canonical_json, '$.breaker_epoch') IS NOT NEW.breaker_epoch
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys observer_key
       JOIN principals observer ON observer.id = observer_key.principal_id
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE observer_key.key_id = NEW.signer_key_id
         AND observer_key.principal_id = NEW.signer_principal_id
         AND observer_key.key_purpose = 'provider_observer'
         AND observer.kind = 'service'
         AND json_extract(evidence.canonical_json, '$.artifact_type') = 'provider_health_evidence'
         AND json_extract(evidence.canonical_json, '$.provider') = NEW.provider
         AND json_extract(evidence.canonical_json, '$.model_family') = NEW.model_family
         AND json_extract(evidence.canonical_json, '$.observed_state') = NEW.observed_state
         AND json_extract(evidence.canonical_json, '$.breaker_epoch') = NEW.breaker_epoch
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'provider_health_observation'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
     );
END;

CREATE TRIGGER provider_health_observations_no_update
BEFORE UPDATE ON provider_health_observations
BEGIN SELECT RAISE(ABORT, 'provider health observations are immutable'); END;

CREATE TRIGGER provider_health_observations_no_delete
BEFORE DELETE ON provider_health_observations
BEGIN SELECT RAISE(ABORT, 'provider health observations are immutable'); END;

CREATE TRIGGER provider_operation_observation_is_exact_and_signed
BEFORE INSERT ON provider_operation_observations
BEGIN
  SELECT RAISE(ABORT, 'provider observation is not exact, fresh, typed, or provider-observer signed')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 60000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.observed_at_ms <= COALESCE((
       SELECT MAX(observed_at_ms) FROM provider_operation_observations prior
       WHERE prior.subject_kind = NEW.subject_kind AND prior.subject_id = NEW.subject_id
     ), 0)
     OR EXISTS (
       SELECT 1 FROM provider_operation_observations prior
       WHERE prior.subject_kind = NEW.subject_kind
         AND prior.subject_id = NEW.subject_id
         AND prior.observed_state IN ('completed','failed','cancelled','absent')
     )
     OR (NEW.observed_state = 'completed' AND NEW.remote_object_id IS NULL)
     OR (NEW.observed_state IN ('completed','failed','cancelled','absent')
         AND NEW.response_digest IS NULL)
     OR (NEW.subject_kind IN ('merge_request','merge_attempt') AND NEW.observed_state = 'completed'
         AND NEW.remote_commit IS NULL)
     OR (NEW.observed_state = 'absent' AND (
       NEW.subject_kind NOT IN ('merge_attempt','external_effect_attempt')
       OR
       NEW.remote_object_id IS NOT NULL
       OR NEW.remote_commit IS NOT NULL
       OR NOT EXISTS (
         SELECT 1 FROM provider_consistency_profiles profile
         JOIN current_valid_keys profile_key
           ON profile_key.key_id = profile.signer_key_id
          AND profile_key.principal_id = profile.signer_principal_id
          AND profile_key.key_purpose = 'control_plane'
         WHERE profile.provider = NEW.provider
           AND NEW.observed_at_ms >= COALESCE(
             (SELECT started_at_ms + profile.consistency_window_ms
              FROM merge_attempts WHERE id = NEW.subject_id
                AND NEW.subject_kind = 'merge_attempt'),
             (SELECT started_at_ms + profile.consistency_window_ms
              FROM external_effect_attempts WHERE id = NEW.subject_id
                AND NEW.subject_kind = 'external_effect_attempt')
           )
       )
     ))
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.provider_lookup_key') IS NOT NEW.provider_lookup_key
     OR json_extract(NEW.canonical_json, '$.request_digest') IS NOT NEW.request_digest
     OR json_extract(NEW.canonical_json, '$.observed_state') IS NOT NEW.observed_state
     OR json_extract(NEW.canonical_json, '$.remote_object_id') IS NOT NEW.remote_object_id
     OR json_extract(NEW.canonical_json, '$.remote_commit') IS NOT NEW.remote_commit
     OR json_extract(NEW.canonical_json, '$.response_digest') IS NOT NEW.response_digest
     OR json_extract(NEW.canonical_json, '$.target_fence') IS NOT NEW.target_fence
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys observer_key
       JOIN principals observer ON observer.id = observer_key.principal_id
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE observer_key.key_id = NEW.signer_key_id
         AND observer_key.principal_id = NEW.signer_principal_id
         AND observer_key.key_purpose = 'provider_observer'
         AND observer.kind = 'service'
         AND (
           (NEW.subject_kind = 'merge_request' AND EXISTS (
             SELECT 1 FROM merge_requests mr
             WHERE mr.id = NEW.subject_id
               AND mr.provider = NEW.provider
               AND mr.provider_idempotency_key = NEW.provider_lookup_key
               AND mr.request_digest = NEW.request_digest
               AND mr.target_fence = NEW.target_fence
           ))
           OR (NEW.subject_kind = 'merge_attempt' AND EXISTS (
             SELECT 1
             FROM merge_attempts attempt
             JOIN merge_requests mr ON mr.id = attempt.merge_request_id
             WHERE attempt.id = NEW.subject_id
               AND mr.provider = NEW.provider
               AND mr.provider_idempotency_key = NEW.provider_lookup_key
               AND attempt.request_digest = NEW.request_digest
               AND mr.target_fence = NEW.target_fence
           ))
           OR (NEW.subject_kind = 'external_effect' AND EXISTS (
             SELECT 1 FROM external_effects effect
             JOIN gate_bundles gate ON gate.digest = effect.gate_bundle_digest
             WHERE effect.id = NEW.subject_id
               AND effect.provider = NEW.provider
               AND effect.remote_idempotency_key = NEW.provider_lookup_key
               AND effect.payload_digest = NEW.request_digest
               AND gate.target_fence = NEW.target_fence
           ))
           OR (NEW.subject_kind = 'external_effect_attempt' AND EXISTS (
             SELECT 1
             FROM external_effect_attempts attempt
             JOIN external_effects effect ON effect.id = attempt.external_effect_id
             JOIN gate_bundles gate ON gate.digest = effect.gate_bundle_digest
             JOIN egress_permits permit ON permit.id = attempt.egress_permit_id
             WHERE attempt.id = NEW.subject_id
               AND effect.provider = NEW.provider
               AND effect.remote_idempotency_key = NEW.provider_lookup_key
               AND attempt.request_digest = NEW.request_digest
               AND gate.target_fence = NEW.target_fence
               AND permit.target_fence = NEW.target_fence
               AND permit.request_digest = NEW.request_digest
           ))
         )
     );

  SELECT RAISE(ABORT, 'provider observation signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'provider_operation_observation'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
  );
END;

CREATE TRIGGER provider_operation_observations_no_update
BEFORE UPDATE ON provider_operation_observations
BEGIN SELECT RAISE(ABORT, 'provider observations are append-only'); END;

CREATE TRIGGER provider_operation_observations_no_delete
BEFORE DELETE ON provider_operation_observations
BEGIN SELECT RAISE(ABORT, 'provider observations are append-only'); END;

CREATE TRIGGER merge_attempts_enter_started
BEFORE INSERT ON merge_attempts
BEGIN
  SELECT RAISE(ABORT, 'merge attempt requires the exact consumed one-shot permit and live parent')
  WHERE NEW.state <> 'started'
     OR NEW.response_digest IS NOT NULL
     OR NEW.provider_observation_id IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.error_code IS NOT NULL
     OR NEW.started_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.started_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.attempt_no <> COALESCE((
       SELECT MAX(prior.attempt_no) + 1
       FROM merge_attempts prior
       WHERE prior.merge_request_id = NEW.merge_request_id
     ), 1)
     OR NOT EXISTS (
       SELECT 1
       FROM merge_requests mr
       JOIN egress_permits permit
         ON permit.id = NEW.egress_permit_id
        AND permit.subject_kind = 'merge_request'
        AND permit.subject_id = mr.id
        AND permit.attempt_no = NEW.attempt_no
        AND permit.provider = mr.provider
        AND permit.subject_digest = mr.merge_subject_digest
        AND permit.request_digest = NEW.request_digest
        AND permit.request_digest = mr.request_digest
        AND permit.provider_idempotency_key = mr.provider_idempotency_key
        AND permit.target_fence = mr.target_fence
        AND permit.state = 'consumed'
        AND permit.consumed_at_ms IS NOT NULL
       JOIN integration_targets target ON target.id = mr.integration_target_id
       WHERE mr.id = NEW.merge_request_id
         AND mr.state = 'integrating'
         AND mr.claim_until_ms >= NEW.started_at_ms
         AND target.state = 'integrating'
         AND target.fence_counter = mr.target_fence
         AND permit.consumed_at_ms <= NEW.started_at_ms
         AND NEW.started_at_ms <= permit.expires_at_ms
     );
END;

CREATE TRIGGER merge_attempts_legal_state_transition
BEFORE UPDATE OF state ON merge_attempts
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal merge-attempt state transition')
  WHERE NOT (
    (OLD.state = 'started' AND NEW.state IN ('succeeded','failed','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('succeeded','failed'))
  );

  SELECT RAISE(ABORT, 'terminal merge attempt requires exact signed provider observation')
  WHERE NEW.provider_observation_id IS NULL
     OR NEW.response_digest IS NULL
     OR NEW.finished_at_ms IS NULL
     OR NEW.finished_at_ms < OLD.started_at_ms
     OR NEW.finished_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1
       FROM provider_operation_observations observation
       JOIN merge_requests mr ON mr.id = NEW.merge_request_id
       WHERE observation.id = NEW.provider_observation_id
         AND observation.subject_kind = 'merge_attempt'
         AND observation.subject_id = NEW.id
         AND observation.provider = mr.provider
         AND observation.provider_lookup_key = mr.provider_idempotency_key
         AND observation.request_digest = NEW.request_digest
         AND observation.response_digest = NEW.response_digest
         AND observation.target_fence = mr.target_fence
         AND observation.observed_at_ms BETWEEN OLD.started_at_ms AND NEW.finished_at_ms
         AND (
           (NEW.state = 'succeeded' AND observation.observed_state = 'completed')
           OR (NEW.state = 'failed' AND observation.observed_state IN ('failed','cancelled'))
           OR (OLD.state = 'unknown' AND NEW.state = 'failed' AND observation.observed_state = 'absent')
           OR (NEW.state = 'unknown' AND observation.observed_state IN ('unreachable','absent'))
         )
         AND NOT EXISTS (
           SELECT 1 FROM provider_operation_observations later
           WHERE later.subject_kind = observation.subject_kind
             AND later.subject_id = observation.subject_id
             AND later.observed_at_ms > observation.observed_at_ms
         )
     );

  SELECT RAISE(ABORT, 'unknown merge attempt may exit only through exact signed reconciliation')
  WHERE OLD.state = 'unknown'
    AND NOT EXISTS (
      SELECT 1 FROM reconciliation_decisions d
      WHERE d.subject_kind = 'merge_attempt'
        AND d.subject_id = NEW.id
        AND d.subject_generation = CAST(NEW.attempt_no AS TEXT)
        AND d.resolved_state = NEW.state
        AND d.provider_observation_id = NEW.provider_observation_id
        AND d.provider_lookup_key = (
          SELECT mr.provider_idempotency_key
          FROM merge_requests mr WHERE mr.id = NEW.merge_request_id
        )
        AND d.observed_provider_state = CASE NEW.state
          WHEN 'succeeded' THEN 'completed'
          ELSE 'absent'
        END
        AND d.observed_at_ms >= OLD.finished_at_ms
        AND NOT EXISTS (
          SELECT 1 FROM reconciliation_decisions later
          WHERE later.subject_kind = d.subject_kind
            AND later.subject_id = d.subject_id
            AND later.decision_no > d.decision_no
        )
    );
END;

CREATE TRIGGER merge_attempt_identity_is_immutable
BEFORE UPDATE OF id, merge_request_id, attempt_no, request_digest,
  egress_permit_id, started_at_ms
ON merge_attempts
BEGIN SELECT RAISE(ABORT, 'merge-attempt identity is immutable'); END;

CREATE TRIGGER merge_attempt_terminal_fields_set_with_transition
BEFORE UPDATE OF response_digest, provider_observation_id, finished_at_ms, error_code
ON merge_attempts
WHEN OLD.response_digest IS NOT NEW.response_digest
  OR OLD.provider_observation_id IS NOT NEW.provider_observation_id
  OR OLD.finished_at_ms IS NOT NEW.finished_at_ms
  OR OLD.error_code IS NOT NEW.error_code
BEGIN
  SELECT RAISE(ABORT, 'merge-attempt terminal evidence is set only with its terminal transition')
  WHERE NOT (
    (OLD.state = 'started'
      AND NEW.state IN ('succeeded','failed','unknown')
      AND OLD.response_digest IS NULL
      AND OLD.provider_observation_id IS NULL
      AND OLD.finished_at_ms IS NULL)
    OR
    (OLD.state = 'unknown'
      AND NEW.state IN ('succeeded','failed')
      AND OLD.response_digest IS NOT NULL
      AND OLD.provider_observation_id IS NOT NULL
      AND OLD.finished_at_ms IS NOT NULL
      AND NEW.finished_at_ms >= OLD.finished_at_ms)
  );
END;

CREATE TRIGGER merge_attempts_no_delete
BEFORE DELETE ON merge_attempts
BEGIN SELECT RAISE(ABORT, 'merge attempts are append-only'); END;

CREATE TRIGGER external_effect_attempts_enter_started
BEFORE INSERT ON external_effect_attempts
BEGIN
  SELECT RAISE(ABORT, 'effect attempt requires the exact consumed one-shot permit and live parent')
  WHERE NEW.state <> 'started'
     OR NEW.response_digest IS NOT NULL
     OR NEW.provider_observation_id IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.error_code IS NOT NULL
     OR NEW.started_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.started_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.attempt_no <> COALESCE((
       SELECT MAX(prior.attempt_no) + 1
       FROM external_effect_attempts prior
       WHERE prior.external_effect_id = NEW.external_effect_id
     ), 1)
     OR NOT EXISTS (
       SELECT 1
       FROM external_effects effect
       JOIN egress_permits permit
         ON permit.id = NEW.egress_permit_id
        AND permit.subject_kind = 'external_effect'
        AND permit.subject_id = effect.id
        AND permit.attempt_no = NEW.attempt_no
        AND permit.provider = effect.provider
        AND permit.subject_digest = effect.effect_subject_digest
        AND permit.request_digest = NEW.request_digest
        AND permit.request_digest = effect.payload_digest
        AND permit.provider_idempotency_key = effect.remote_idempotency_key
        AND permit.state = 'consumed'
        AND permit.consumed_at_ms IS NOT NULL
       WHERE effect.id = NEW.external_effect_id
         AND effect.state = 'executing'
         AND effect.claim_until_ms >= NEW.started_at_ms
         AND permit.consumed_at_ms <= NEW.started_at_ms
         AND NEW.started_at_ms <= permit.expires_at_ms
     );
END;

