      AND NEW.state IN ('succeeded','failed','unknown')
      AND OLD.response_digest IS NULL
      AND OLD.provider_observation_id IS NULL
      AND OLD.finished_at_ms IS NULL)
    OR
    (OLD.state = 'unknown'
      AND NEW.state IN ('succeeded','failed')
      AND OLD.response_digest IS NOT NULL
