CREATE TRIGGER project_admission_permit_is_exact_current_winner
BEFORE INSERT ON project_admission_permits
BEGIN
  SELECT RAISE(ABORT, 'project admission permit is stale, inexact, or not the deterministic queue winner')
  WHERE NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.issued_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.source_project_state') IS NOT NEW.source_project_state
     OR json_extract(NEW.canonical_json, '$.source_project_revision') IS NOT NEW.source_project_revision
     OR json_extract(NEW.canonical_json, '$.slot_no') IS NOT NEW.slot_no
     OR json_extract(NEW.canonical_json, '$.prior_generation') IS NOT NEW.prior_generation
     OR json_extract(NEW.canonical_json, '$.new_generation') IS NOT NEW.new_generation
     OR json_extract(NEW.canonical_json, '$.prior_owner_fence') IS NOT NEW.prior_owner_fence
     OR json_extract(NEW.canonical_json, '$.new_owner_fence') IS NOT NEW.new_owner_fence
     OR json_extract(NEW.canonical_json, '$.planned_run_id') IS NOT NEW.planned_run_id
     OR json_extract(NEW.canonical_json, '$.planned_predecessor_run_id') IS NOT NEW.planned_predecessor_run_id
     OR json_extract(NEW.canonical_json, '$.planned_runtime_intent_id') IS NOT NEW.planned_runtime_intent_id
     OR json_extract(NEW.canonical_json, '$.planned_charge_subject_id') IS NOT NEW.planned_charge_subject_id
     OR json_extract(NEW.canonical_json, '$.planned_resource_reservation_id') IS NOT NEW.planned_resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.budget_account_id') IS NOT NEW.budget_account_id
     OR json_extract(NEW.canonical_json, '$.root_request_digest') IS NOT NEW.root_request_digest
     OR json_extract(NEW.canonical_json, '$.queue_snapshot_digest') IS NOT NEW.queue_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.admission_policy_digest') IS NOT NEW.admission_policy_digest
     OR json_extract(NEW.canonical_json, '$.resume_command_authorization_digest') IS NOT NEW.resume_command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NEW.project_id IS NOT (
       SELECT candidate.id
       FROM projects candidate
       WHERE NOT EXISTS (
           SELECT 1 FROM project_slots occupied WHERE occupied.project_id = candidate.id
         )
         AND (
           candidate.state = 'queued'
           OR (candidate.state = 'parked' AND EXISTS (
             SELECT 1
             FROM command_authorizations resume_authorization
             JOIN commands resume_command ON resume_command.id = resume_authorization.command_id
             JOIN control_state resume_control ON resume_control.current_term = resume_authorization.leader_term
             WHERE resume_authorization.project_id = candidate.id
               AND resume_authorization.command_type = 'project.control'
               AND resume_authorization.authorization_expires_at_ms >= NEW.issued_at_ms
               AND resume_command.state = 'authorized'
               AND json_extract(resume_command.payload_json, '$.action') = 'resume'
           ))
         )
       ORDER BY candidate.priority ASC,
                CASE candidate.state WHEN 'queued' THEN candidate.created_at_ms ELSE candidate.updated_at_ms END,
                candidate.id
       LIMIT 1
     )
     OR NOT EXISTS (
       SELECT 1
       FROM projects project
       JOIN project_slots slot ON slot.slot_no = NEW.slot_no
       JOIN executors owner ON owner.id = slot.orchestrator_executor_id
       JOIN executor_slots owner_slot ON owner_slot.executor_id = owner.id
       JOIN budget_accounts budget ON budget.id = NEW.budget_account_id
       JOIN policies admission_policy ON admission_policy.digest = NEW.admission_policy_digest
       JOIN current_valid_keys policy_key
         ON policy_key.key_id = admission_policy.signer_key_id
        AND policy_key.key_purpose = 'control_plane'
       JOIN artifact_manifests queue_snapshot ON queue_snapshot.digest = NEW.queue_snapshot_digest
       JOIN current_valid_keys snapshot_key
         ON snapshot_key.key_id = queue_snapshot.signer_key_id
        AND snapshot_key.key_purpose = 'artifact_broker'
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE project.id = NEW.project_id
         AND project.state = NEW.source_project_state
         AND project.revision = NEW.source_project_revision
         AND slot.project_id IS NULL
         AND slot.generation = NEW.prior_generation
         AND slot.owner_fence = NEW.prior_owner_fence
         AND owner.pool = 'fable'
         AND owner.id <> 'rick'
         AND owner_slot.state = 'available'
         AND owner_slot.fence_counter = NEW.prior_owner_fence
         AND budget.project_id = NEW.project_id
         AND budget.account_scope = 'project'
         AND budget.state = 'active'
         AND admission_policy.policy_type = 'project_admission'
         AND json_extract(queue_snapshot.canonical_json, '$.artifact_type') = 'admission_queue_snapshot'
         AND json_extract(queue_snapshot.canonical_json, '$.leader_term') = NEW.leader_term
         AND json_extract(queue_snapshot.canonical_json, '$.selected_project_id') = NEW.project_id
         AND json_extract(queue_snapshot.canonical_json, '$.selected_slot_no') = NEW.slot_no
         AND json_extract(queue_snapshot.canonical_json, '$.captured_at_ms') BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND control.dispatch_enabled = 1
         AND control.admission_mode = 'open'
         AND control.kill_switch = 0
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = admission_policy.digest
         )
     )
     OR (NEW.source_project_state = 'queued' AND NOT EXISTS (
       SELECT 1
       FROM projects project
       JOIN command_authorizations submit_authorization
         ON submit_authorization.digest = project.submit_command_authorization_digest
       JOIN commands submit_command ON submit_command.id = submit_authorization.command_id
       WHERE project.id = NEW.project_id
         AND submit_authorization.command_type = 'project.submit'
         AND json_extract(submit_command.payload_json, '$.root_request_digest') = NEW.root_request_digest
     ))
     OR (NEW.source_project_state = 'parked' AND NOT EXISTS (
       SELECT 1
       FROM command_authorizations authorization
       JOIN commands command ON command.id = authorization.command_id
       WHERE authorization.digest = NEW.resume_command_authorization_digest
         AND authorization.project_id = NEW.project_id
         AND authorization.command_type = 'project.control'
         AND authorization.leader_term = NEW.leader_term
         AND authorization.authorization_expires_at_ms >= NEW.expires_at_ms
         AND command.state = 'authorized'
         AND command.expires_at_ms >= NEW.expires_at_ms
         AND json_extract(command.payload_json, '$.action') = 'resume'
         AND json_extract(command.payload_json, '$.expected_revision') = NEW.source_project_revision
         AND json_extract(command.payload_json, '$.root_request_digest') = NEW.root_request_digest
     ))
     OR (NEW.source_project_state = 'parked' AND NOT EXISTS (
       SELECT 1 FROM runs predecessor
       WHERE predecessor.id = NEW.planned_predecessor_run_id
         AND predecessor.project_id = NEW.project_id
         AND predecessor.state IN ('completed','failed','cancelled')
         AND predecessor.finished_at_ms IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM runs later
           WHERE later.project_id = predecessor.project_id
             AND (later.created_at_ms > predecessor.created_at_ms
                  OR (later.created_at_ms = predecessor.created_at_ms AND later.id > predecessor.id))
         )
     ))
     OR (SELECT COUNT(*) FROM fairness_policies policy
         WHERE NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = policy.policy_digest
         )) <> 3
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'project_admission_permit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

CREATE TRIGGER project_admission_permits_no_update
BEFORE UPDATE ON project_admission_permits
BEGIN SELECT RAISE(ABORT, 'project admission permits are immutable'); END;

CREATE TRIGGER project_admission_permits_no_delete
BEFORE DELETE ON project_admission_permits
BEGIN SELECT RAISE(ABORT, 'project admission permits are immutable'); END;

CREATE TRIGGER project_admission_commit_is_exact_complete_bundle
BEFORE INSERT ON project_admission_commits
BEGIN
  SELECT RAISE(ABORT, 'project admission commit does not seal one complete current bundle')
  WHERE NEW.committed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.committed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.admission_permit_digest') IS NOT NEW.admission_permit_digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.slot_no') IS NOT NEW.slot_no
     OR json_extract(NEW.canonical_json, '$.project_slot_generation') IS NOT NEW.project_slot_generation
     OR json_extract(NEW.canonical_json, '$.owner_fence') IS NOT NEW.owner_fence
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.runtime_intent_id') IS NOT NEW.runtime_intent_id
     OR json_extract(NEW.canonical_json, '$.charge_subject_id') IS NOT NEW.charge_subject_id
     OR json_extract(NEW.canonical_json, '$.resource_reservation_id') IS NOT NEW.resource_reservation_id
     OR json_extract(NEW.canonical_json, '$.budget_account_id') IS NOT NEW.budget_account_id
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.committed_at_ms') IS NOT NEW.committed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM project_admission_permits permit
       JOIN projects project ON project.id = permit.project_id
       JOIN project_slots slot
         ON slot.slot_no = permit.slot_no
        AND slot.project_id = permit.project_id
        AND slot.generation = permit.new_generation
        AND slot.owner_fence = permit.new_owner_fence
        AND slot.binding_authorization_digest = permit.digest
       JOIN executors owner ON owner.id = slot.orchestrator_executor_id
       JOIN executor_slots owner_slot
         ON owner_slot.executor_id = owner.id
        AND owner_slot.state = 'leased'
        AND owner_slot.fence_counter = permit.new_owner_fence
       JOIN runs run
         ON run.id = permit.planned_run_id
        AND run.project_id = permit.project_id
        AND run.run_kind = 'planning'
        AND run.state = 'created'
        AND run.admission_permit_digest = permit.digest
        AND run.project_slot_no = slot.slot_no
        AND run.project_slot_generation = slot.generation
       JOIN runtime_intents intent
         ON intent.id = permit.planned_runtime_intent_id
        AND intent.project_id = permit.project_id
        AND intent.project_slot_no = slot.slot_no
        AND intent.project_slot_generation = slot.generation
        AND intent.executor_id = owner.id
        AND intent.executor_slot_id = owner_slot.id
        AND intent.fence = owner_slot.fence_counter
        AND intent.leader_term = permit.leader_term
        AND intent.session_scope = 'project_generation'
        AND intent.state = 'prepared'
       JOIN charge_subjects subject
         ON subject.id = permit.planned_charge_subject_id
        AND subject.runtime_intent_id = intent.id
        AND subject.project_id = permit.project_id
        AND subject.scope_kind = 'project_runtime'
       JOIN resource_reservations resource
         ON resource.id = permit.planned_resource_reservation_id
        AND resource.charge_subject_id = subject.id
        AND resource.reservation_kind = 'process'
        AND resource.state = 'held'
       JOIN budget_accounts budget
         ON budget.id = permit.budget_account_id
        AND budget.project_id = permit.project_id
        AND budget.state = 'active'
       JOIN leader_terms term ON term.term = permit.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = permit.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE permit.digest = NEW.admission_permit_digest
         AND project.state = permit.source_project_state
         AND project.revision = permit.source_project_revision
         AND permit.expires_at_ms >= NEW.committed_at_ms
         AND control.dispatch_enabled = 1
         AND control.admission_mode = 'open'
         AND control.kill_switch = 0
         AND NEW.project_id = permit.project_id
         AND NEW.slot_no = permit.slot_no
         AND NEW.project_slot_generation = permit.new_generation
         AND NEW.owner_fence = permit.new_owner_fence
         AND NEW.run_id = run.id
         AND NEW.runtime_intent_id = intent.id
         AND NEW.charge_subject_id = subject.id
         AND NEW.resource_reservation_id = resource.id
         AND NEW.budget_account_id = budget.id
         AND NEW.leader_term = permit.leader_term
         AND (SELECT COUNT(*) FROM fairness_state fairness
              WHERE fairness.project_id = project.id
                AND fairness.leader_term = permit.leader_term) = 3
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'project_admission_commit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.committed_at_ms - 5000 AND NEW.committed_at_ms
     );
END;

CREATE TRIGGER project_admission_commits_no_update
BEFORE UPDATE ON project_admission_commits
BEGIN SELECT RAISE(ABORT, 'project admission commits are immutable'); END;

CREATE TRIGGER project_admission_commits_no_delete
BEFORE DELETE ON project_admission_commits
BEGIN SELECT RAISE(ABORT, 'project admission commits are immutable'); END;

CREATE TRIGGER project_transition_authorization_is_exact_and_signed
BEFORE INSERT ON project_transition_authorizations
BEGIN
  SELECT RAISE(ABORT, 'project transition authority is stale, inexact, or unauthorized')
  WHERE NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.issued_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.from_state') IS NOT NEW.from_state
     OR json_extract(NEW.canonical_json, '$.to_state') IS NOT NEW.to_state
     OR json_extract(NEW.canonical_json, '$.from_revision') IS NOT NEW.from_revision
     OR json_extract(NEW.canonical_json, '$.to_revision') IS NOT NEW.to_revision
     OR json_extract(NEW.canonical_json, '$.authority_kind') IS NOT NEW.authority_kind
     OR json_extract(NEW.canonical_json, '$.reason_code') IS NOT NEW.reason_code
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM projects project
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE project.id = NEW.project_id
         AND project.state = NEW.from_state
         AND project.revision = NEW.from_revision
     )
     OR NOT (
       (NEW.authority_kind = 'command' AND EXISTS (
         SELECT 1 FROM command_authorizations authorization
         JOIN commands command ON command.id = authorization.command_id
         WHERE authorization.digest = NEW.command_authorization_digest
           AND authorization.project_id = NEW.project_id
           AND authorization.command_type = 'project.control'
           AND authorization.leader_term = NEW.leader_term
           AND authorization.authorization_expires_at_ms >= NEW.expires_at_ms
           AND command.state = 'authorized'
           AND command.expires_at_ms >= NEW.expires_at_ms
           AND json_extract(command.payload_json, '$.action') = 'transition'
           AND json_extract(command.payload_json, '$.from_state') = NEW.from_state
           AND json_extract(command.payload_json, '$.to_state') = NEW.to_state
           AND json_extract(command.payload_json, '$.expected_revision') = NEW.from_revision
           AND NEW.to_state IN ('paused','parked','cancelled')
       ))
       OR (NEW.authority_kind = 'controller'
         AND (
           (NEW.reason_code IN ('runtime_ready','block_cleared') AND NEW.to_state = 'active')
           OR (NEW.reason_code IN ('dependency_blocked','capacity_blocked') AND NEW.to_state = 'blocked')
           OR (NEW.reason_code = 'delivery_complete' AND NEW.to_state = 'done')
         )
         AND EXISTS (
           SELECT 1 FROM artifact_manifests evidence
           JOIN current_valid_keys evidence_key
             ON evidence_key.key_id = evidence.signer_key_id
            AND evidence_key.key_purpose = 'artifact_broker'
           WHERE evidence.digest = NEW.evidence_manifest_digest
             AND json_extract(evidence.canonical_json, '$.artifact_type') = 'project_transition_evidence'
             AND json_extract(evidence.canonical_json, '$.project_id') = NEW.project_id
             AND json_extract(evidence.canonical_json, '$.from_state') = NEW.from_state
             AND json_extract(evidence.canonical_json, '$.to_state') = NEW.to_state
             AND json_extract(evidence.canonical_json, '$.from_revision') = NEW.from_revision
             AND json_extract(evidence.canonical_json, '$.reason_code') = NEW.reason_code
             AND json_extract(evidence.canonical_json, '$.leader_term') = NEW.leader_term
         ))
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'project_transition_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

CREATE TRIGGER project_transition_authorizations_no_update
BEFORE UPDATE ON project_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'project transition authorizations are immutable'); END;

CREATE TRIGGER project_transition_authorizations_no_delete
BEFORE DELETE ON project_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'project transition authorizations are immutable'); END;

CREATE TRIGGER project_slot_owner_must_be_fable_insert
BEFORE INSERT ON project_slots
BEGIN
  SELECT RAISE(ABORT, 'project slots must be bootstrapped empty at generation zero')
  WHERE NEW.project_id IS NOT NULL OR NEW.generation <> 0
     OR NEW.binding_authorization_digest IS NOT NULL
     OR NEW.assigned_at_ms IS NOT NULL OR NEW.released_at_ms IS NOT NULL;

  SELECT RAISE(ABORT, 'project slot owner must be Fable')
  WHERE NOT EXISTS (
    SELECT 1
    FROM executors executor
    JOIN executor_slots executor_slot ON executor_slot.executor_id = executor.id
    WHERE executor.id = NEW.orchestrator_executor_id
      AND executor.pool = 'fable'
      AND executor_slot.fence_counter = NEW.owner_fence
  );
END;

CREATE TRIGGER project_slot_owner_is_immutable
BEFORE UPDATE OF orchestrator_executor_id ON project_slots
BEGIN
  SELECT RAISE(ABORT, 'project slot owner is immutable after bootstrap');
END;

CREATE TRIGGER project_slots_no_delete
BEFORE DELETE ON project_slots
BEGIN
  SELECT RAISE(ABORT, 'the four project-slot rows are permanent');
END;

CREATE TRIGGER project_slot_generation_must_advance
BEFORE UPDATE OF project_id ON project_slots
WHEN OLD.project_id IS NOT NEW.project_id
BEGIN
  SELECT RAISE(ABORT, 'project slot generation must increase exactly once')
  WHERE NEW.generation <> OLD.generation + 1
     OR NEW.owner_fence <> OLD.owner_fence + 1
     OR NOT EXISTS (
       SELECT 1 FROM executor_slots owner_slot
       WHERE owner_slot.executor_id = NEW.orchestrator_executor_id
         AND owner_slot.fence_counter = NEW.owner_fence
     );

  SELECT RAISE(ABORT, 'project-slot binding lacks its exact current admission permit')
  WHERE NEW.project_id IS NOT NULL
    AND (
      NEW.binding_authorization_digest IS NULL
      OR NEW.assigned_at_ms IS NULL
      OR NEW.assigned_at_ms < (unixepoch('subsec') * 1000) - 5000
      OR NEW.assigned_at_ms > (unixepoch('subsec') * 1000) + 5000
      OR NEW.released_at_ms IS NOT NULL
      OR NOT EXISTS (
        SELECT 1
        FROM project_admission_permits permit
        JOIN leader_terms term ON term.term = permit.leader_term AND term.state = 'active'
        JOIN control_state control ON control.current_term = permit.leader_term
        WHERE permit.digest = NEW.binding_authorization_digest
          AND permit.project_id = NEW.project_id
          AND permit.slot_no = NEW.slot_no
          AND permit.prior_generation = OLD.generation
          AND permit.new_generation = NEW.generation
          AND permit.prior_owner_fence = OLD.owner_fence
          AND permit.new_owner_fence = NEW.owner_fence
          AND permit.expires_at_ms >= NEW.assigned_at_ms
          AND control.dispatch_enabled = 1
          AND control.admission_mode = 'open'
          AND control.kill_switch = 0
      )
    );

  SELECT RAISE(ABORT, 'project-slot release has incoherent immutable timing/authority')
  WHERE NEW.project_id IS NULL
    AND (
      NEW.binding_authorization_digest IS NOT NULL
      OR NEW.assigned_at_ms IS NOT OLD.assigned_at_ms
      OR NEW.released_at_ms IS NULL
      OR NEW.released_at_ms < OLD.assigned_at_ms
      OR NEW.released_at_ms < (unixepoch('subsec') * 1000) - 5000
      OR NEW.released_at_ms > (unixepoch('subsec') * 1000) + 5000
    );

  SELECT RAISE(ABORT, 'only queued or parked projects may be admitted')
  WHERE NEW.project_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM projects
      WHERE id = NEW.project_id AND state IN ('queued','parked')
    );

  SELECT RAISE(ABORT, 'project must be terminal or parked before slot release')
  WHERE OLD.project_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM projects
      WHERE id = OLD.project_id AND state IN ('parked','done','cancelled')
    );
END;

CREATE TRIGGER project_slot_binding_fields_change_only_on_rebind
BEFORE UPDATE OF binding_authorization_digest, assigned_at_ms, released_at_ms ON project_slots
WHEN OLD.project_id IS NEW.project_id
  AND (OLD.binding_authorization_digest IS NOT NEW.binding_authorization_digest
    OR OLD.assigned_at_ms IS NOT NEW.assigned_at_ms
    OR OLD.released_at_ms IS NOT NEW.released_at_ms)
BEGIN SELECT RAISE(ABORT, 'project-slot binding fields change only with project rebind'); END;

CREATE TRIGGER slot_change_cannot_orphan_live_project
BEFORE UPDATE OF project_id ON project_slots
WHEN OLD.project_id IS NOT NEW.project_id
BEGIN
  SELECT RAISE(ABORT, 'slot change would orphan a live project')
  WHERE OLD.project_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM projects
      WHERE id = OLD.project_id
        AND state IN ('admitted','active','blocked','paused')
    );
END;

CREATE TRIGGER live_project_requires_slot
BEFORE UPDATE OF state ON projects
WHEN NEW.state IN ('admitted','active','blocked','paused')
BEGIN
  SELECT RAISE(ABORT, 'live project requires project slot')
  WHERE NOT EXISTS (
    SELECT 1 FROM project_slots WHERE project_id = NEW.id
  );

  SELECT RAISE(ABORT, 'live project requires active budget')
  WHERE NOT EXISTS (
    SELECT 1 FROM budget_accounts
    WHERE project_id = NEW.id AND state = 'active'
  );

  SELECT RAISE(ABORT, 'live project requires all three current-term fairness states')
  WHERE (SELECT COUNT(*)
         FROM fairness_state fairness
         JOIN control_state control ON control.current_term = fairness.leader_term
         JOIN fairness_policies policy ON policy.pool = fairness.pool
         WHERE fairness.project_id = NEW.id
           AND NOT EXISTS (
             SELECT 1 FROM policy_invalidations invalidation
             WHERE invalidation.policy_digest = policy.policy_digest
           )) <> 3;
END;

CREATE TRIGGER project_activation_requires_active_bound_run
BEFORE UPDATE OF state ON projects
WHEN NEW.state = 'active' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'project activation requires its exact generation run to be active')
  WHERE NOT EXISTS (
    SELECT 1
    FROM project_slots ps
    JOIN runs r
      ON r.project_id = NEW.id
     AND r.project_slot_no = ps.slot_no
     AND r.project_slot_generation = ps.generation
    JOIN runtime_sessions rs
      ON rs.project_id = NEW.id
     AND rs.project_slot_no = ps.slot_no
     AND rs.project_slot_generation = ps.generation
     AND rs.session_scope = 'project_generation'
    JOIN runtime_intents ri ON ri.id = rs.runtime_intent_id
    WHERE ps.project_id = NEW.id
      AND ps.orchestrator_executor_id = ri.executor_id
      AND rs.executor_id = ri.executor_id
      AND r.state = 'active'
      AND ri.state = 'launched'
      AND rs.state = 'running'
  );
END;

CREATE TRIGGER project_slot_generation_changes_only_on_rebind
BEFORE UPDATE OF generation ON project_slots
WHEN OLD.project_id IS NEW.project_id AND NEW.generation <> OLD.generation
BEGIN
  SELECT RAISE(ABORT, 'project-slot generation changes only with a binding change');
END;

CREATE TRIGGER project_slot_owner_fence_changes_only_on_rebind
BEFORE UPDATE OF owner_fence ON project_slots
WHEN OLD.project_id IS NEW.project_id AND NEW.owner_fence <> OLD.owner_fence
BEGIN
  SELECT RAISE(ABORT, 'project-slot owner fence changes only with a binding change');
END;

CREATE TRIGGER project_exit_requires_no_live_attempts
BEFORE UPDATE OF state ON projects
WHEN NEW.state IN ('parked','done','cancelled') AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'project must drain or terminate live attempts before exit')
  WHERE EXISTS (
    SELECT 1 FROM attempts
    WHERE project_id = NEW.id
      AND state IN ('created','dispatched','acked','running','result_pending','unknown')
  );


  SELECT RAISE(ABORT, 'project must release leases before exit')
  WHERE EXISTS (
    SELECT 1
    FROM attempts a
    JOIN leases l ON l.attempt_id = a.id
    WHERE a.project_id = NEW.id AND l.state = 'active'
  );

  SELECT RAISE(ABORT, 'project must close all budget and resource reservations before exit')
  WHERE EXISTS (
      SELECT 1
      FROM charge_subjects subject
      JOIN budget_reservations reservation ON reservation.charge_subject_id = subject.id
      WHERE subject.project_id = NEW.id
        AND reservation.state NOT IN ('consumed','released')
    )
    OR EXISTS (
      SELECT 1
      FROM charge_subjects subject
      JOIN resource_reservations reservation ON reservation.charge_subject_id = subject.id
      WHERE subject.project_id = NEW.id
        AND reservation.state IN ('held','breached')
    );

  SELECT RAISE(ABORT, 'project must confirm process termination before exit')
  WHERE EXISTS (
    SELECT 1
    FROM attempts a
    JOIN attempt_session_bindings b ON b.attempt_id = a.id
    JOIN runtime_sessions s ON s.id = b.runtime_session_id
    WHERE a.project_id = NEW.id AND s.state <> 'terminated'
  );

  SELECT RAISE(ABORT, 'project-generation runtime must terminate before project exit')
  WHERE EXISTS (
    SELECT 1 FROM runtime_sessions s
    WHERE s.project_id = NEW.id
      AND s.session_scope = 'project_generation'
      AND s.state <> 'terminated'
  );

  SELECT RAISE(ABORT, 'project-generation runtime intent must terminalize before project exit')
  WHERE EXISTS (
    SELECT 1 FROM runtime_intents intent
    WHERE intent.project_id = NEW.id
      AND intent.session_scope = 'project_generation'
      AND intent.state NOT IN ('terminated','cancelled','failed')
  );

  SELECT RAISE(ABORT, 'project must terminalize its open run before exit')
  WHERE EXISTS (
    SELECT 1 FROM runs
    WHERE project_id = NEW.id
      AND state IN ('created','active','blocked','paused')
  );

  SELECT RAISE(ABORT, 'done requires the latest run to be a successfully sealed delivery')
  WHERE NEW.state = 'done'
    AND NOT EXISTS (
      SELECT 1
      FROM runs run
      JOIN run_completion_seals seal ON seal.run_id = run.id
      WHERE run.project_id = NEW.id
        AND run.run_kind = 'delivery'
        AND run.state = 'completed'
        AND NOT EXISTS (
          SELECT 1 FROM runs successor
          WHERE successor.predecessor_run_id = run.id
        )
    );
END;

CREATE TRIGGER project_state_change_requires_exact_one_shot_authority
BEFORE UPDATE OF state ON projects
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'project admission lacks the exact complete admission commit')
  WHERE NEW.state = 'admitted'
    AND NOT EXISTS (
      SELECT 1
      FROM project_admission_commits commit_record
      JOIN project_admission_permits permit
        ON permit.digest = commit_record.admission_permit_digest
      JOIN project_slots slot
        ON slot.slot_no = commit_record.slot_no
       AND slot.project_id = NEW.id
       AND slot.generation = commit_record.project_slot_generation
       AND slot.owner_fence = commit_record.owner_fence
       AND slot.binding_authorization_digest = permit.digest
      JOIN leader_terms term ON term.term = commit_record.leader_term AND term.state = 'active'
      JOIN control_state control ON control.current_term = commit_record.leader_term
      WHERE commit_record.project_id = NEW.id
        AND permit.source_project_state = OLD.state
        AND permit.source_project_revision = OLD.revision
        AND commit_record.committed_at_ms = NEW.updated_at_ms
        AND control.dispatch_enabled = 1
        AND control.admission_mode = 'open'
        AND control.kill_switch = 0
    );

  SELECT RAISE(ABORT, 'project state transition lacks exact current one-shot authority')
  WHERE NEW.state <> 'admitted'
    AND NOT EXISTS (
      SELECT 1
      FROM project_transition_authorizations authorization
      JOIN leader_terms term ON term.term = authorization.leader_term AND term.state = 'active'
      JOIN control_state control ON control.current_term = authorization.leader_term
      WHERE authorization.project_id = NEW.id
        AND authorization.from_state = OLD.state
        AND authorization.to_state = NEW.state
        AND authorization.from_revision = OLD.revision
        AND authorization.to_revision = NEW.revision
        AND authorization.issued_at_ms = NEW.updated_at_ms
        AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
        AND (NEW.state <> 'active' OR (
          control.admission_mode = 'open'
          AND control.dispatch_enabled = 1
          AND control.kill_switch = 0
        ))
    );
END;

CREATE TRIGGER projects_legal_state_transition
BEFORE UPDATE OF state ON projects
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal project state transition')
  WHERE NOT (
    (OLD.state = 'queued' AND NEW.state IN ('admitted','cancelled'))
    OR (OLD.state = 'admitted' AND NEW.state IN ('active','blocked','parked','cancelled'))
    OR (OLD.state = 'active' AND NEW.state IN ('blocked','paused','parked','done','cancelled'))
    OR (OLD.state = 'blocked' AND NEW.state IN ('active','paused','parked','cancelled'))
    OR (OLD.state = 'paused' AND NEW.state IN ('active','parked','cancelled'))
    OR (OLD.state = 'parked' AND NEW.state IN ('admitted','cancelled'))
  );
END;

CREATE TRIGGER projects_require_revision_cas
BEFORE UPDATE ON projects
BEGIN
  SELECT RAISE(ABORT, 'project mutation requires revision plus one and monotonic current time')
  WHERE NEW.revision <> OLD.revision + 1
     OR NEW.updated_at_ms <= OLD.updated_at_ms
     OR NEW.updated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.updated_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER projects_identity_is_immutable
BEFORE UPDATE OF id, slug, owner_principal_id, priority,
  submit_command_authorization_digest, created_at_ms
ON projects
BEGIN SELECT RAISE(ABORT, 'project identity and submit authority are immutable'); END;

CREATE TRIGGER projects_no_delete
BEFORE DELETE ON projects
BEGIN SELECT RAISE(ABORT, 'project history is append-only'); END;

CREATE TRIGGER run_completion_seal_is_exact_and_signed
BEFORE INSERT ON run_completion_seals
BEGIN
  SELECT RAISE(ABORT, 'run completion seal is not exact, final, metered, or signed')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.final_node_version_id') IS NOT NEW.final_node_version_id
     OR json_extract(NEW.canonical_json, '$.final_artifact_instance_id') IS NOT NEW.final_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.final_usage_event_id') IS NOT NEW.final_usage_event_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM runs run
       JOIN artifact_manifests plan ON plan.digest = run.plan_manifest_digest
       JOIN node_versions final_node
         ON final_node.id = NEW.final_node_version_id
        AND final_node.run_id = run.id
        AND final_node.state = 'accepted'
       JOIN attempts final_attempt
         ON final_attempt.id = final_node.accepted_attempt_id
        AND final_attempt.state = 'accepted'
       JOIN artifact_instances final_artifact
         ON final_artifact.id = NEW.final_artifact_instance_id
        AND final_artifact.project_id = run.project_id
        AND final_artifact.run_id = run.id
        AND final_artifact.node_version_id = final_node.id
        AND final_artifact.producer_attempt_id = final_attempt.id
        AND final_artifact.artifact_type = 'node_output'
       JOIN result_envelopes result
         ON result.attempt_id = final_attempt.id
        AND result.output_manifest_digest = final_artifact.manifest_digest
        AND result.state = 'accepted'
       JOIN charge_subjects subject
         ON subject.attempt_id = final_attempt.id
        AND subject.scope_kind = 'attempt'
       JOIN budget_reservations reservation
         ON reservation.charge_subject_id = subject.id
       JOIN usage_events final_usage
         ON final_usage.id = NEW.final_usage_event_id
        AND final_usage.reservation_id = reservation.id
        AND final_usage.final_marker = 1
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       JOIN principals signer
         ON signer.id = NEW.signer_principal_id
        AND signer.kind = 'service'
       WHERE run.id = NEW.run_id
         AND run.state = 'active'
         AND NEW.sealed_at_ms >= final_usage.observed_at_ms
         AND final_node.logical_node_id = CASE run.run_kind
           WHEN 'planning' THEN json_extract(plan.canonical_json, '$.plan.final_author_logical_node_id')
           ELSE json_extract(plan.canonical_json, '$.plan.final_output_logical_node_id')
         END
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'run_completion_seal'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

CREATE TRIGGER run_completion_seals_no_update
BEFORE UPDATE ON run_completion_seals
BEGIN SELECT RAISE(ABORT, 'run completion seals are immutable'); END;

CREATE TRIGGER run_completion_seals_no_delete
BEFORE DELETE ON run_completion_seals
BEGIN SELECT RAISE(ABORT, 'run completion seals are immutable'); END;

CREATE TRIGGER benchmark_invalidated_campaign_rejects_completion_seal
BEFORE INSERT ON run_completion_seals
WHEN EXISTS (
  SELECT 1
  FROM runs run
  JOIN benchmark_campaign_invalidations invalidation
    ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
  WHERE run.id = NEW.run_id
)
OR EXISTS (
  SELECT 1
  FROM attempts evaluator
  JOIN benchmark_blind_assignments assignment ON assignment.evaluator_attempt_id = evaluator.id
  JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
  JOIN benchmark_campaign_invalidations invalidation
    ON invalidation.preregistration_digest = arm.preregistration_digest
  WHERE evaluator.run_id = NEW.run_id
)
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot create a run completion seal');
END;

CREATE TRIGGER run_transition_authorization_is_exact_and_signed
BEFORE INSERT ON run_transition_authorizations
BEGIN
  SELECT RAISE(ABORT, 'run transition authority is stale, inexact, or unauthorized')
  WHERE NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.issued_at_ms + 30000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.from_state') IS NOT NEW.from_state
     OR json_extract(NEW.canonical_json, '$.to_state') IS NOT NEW.to_state
     OR json_extract(NEW.canonical_json, '$.from_revision') IS NOT NEW.from_revision
     OR json_extract(NEW.canonical_json, '$.to_revision') IS NOT NEW.to_revision
     OR json_extract(NEW.canonical_json, '$.authority_kind') IS NOT NEW.authority_kind
     OR json_extract(NEW.canonical_json, '$.reason_code') IS NOT NEW.reason_code
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.benchmark_campaign_invalidation_id') IS NOT NEW.benchmark_campaign_invalidation_id
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM runs run
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE run.id = NEW.run_id
         AND run.project_id = NEW.project_id
         AND run.state = NEW.from_state
         AND run.revision = NEW.from_revision
     )
     OR (NEW.reason_code = 'benchmark_campaign_invalidated' AND NOT EXISTS (
       SELECT 1
       FROM runs run
       JOIN benchmark_campaign_invalidations invalidation
         ON invalidation.id = NEW.benchmark_campaign_invalidation_id
       WHERE run.id = NEW.run_id
         AND invalidation.evidence_manifest_digest = NEW.evidence_manifest_digest
         AND NEW.authority_kind = 'controller'
         AND NEW.to_state = 'cancelled'
         AND NEW.issued_at_ms = invalidation.invalidated_at_ms
         AND (
           run.benchmark_preregistration_digest = invalidation.preregistration_digest
           OR EXISTS (
             SELECT 1
             FROM attempts evaluator
             JOIN benchmark_blind_assignments assignment
               ON assignment.evaluator_attempt_id = evaluator.id
             JOIN benchmark_arm_runs arm
               ON arm.arm_execution_id = assignment.arm_execution_id
             WHERE evaluator.run_id = run.id
               AND arm.preregistration_digest = invalidation.preregistration_digest
           )
         )
     ))
     OR (NEW.reason_code <> 'benchmark_campaign_invalidated'
         AND NEW.benchmark_campaign_invalidation_id IS NOT NULL)
     OR NOT (
       (NEW.authority_kind = 'command' AND NEW.to_state IN ('paused','cancelled') AND EXISTS (
         SELECT 1 FROM command_authorizations authorization
         JOIN commands command ON command.id = authorization.command_id
         WHERE authorization.digest = NEW.command_authorization_digest
           AND authorization.project_id = NEW.project_id
           AND authorization.command_type = 'project.control'
           AND authorization.leader_term = NEW.leader_term
           AND authorization.authorization_expires_at_ms >= NEW.expires_at_ms
           AND command.state = 'authorized'
           AND command.expires_at_ms >= NEW.expires_at_ms
           AND json_extract(command.payload_json, '$.action') = 'transition_run'
           AND json_extract(command.payload_json, '$.run_id') = NEW.run_id
           AND json_extract(command.payload_json, '$.from_state') = NEW.from_state
           AND json_extract(command.payload_json, '$.to_state') = NEW.to_state
           AND json_extract(command.payload_json, '$.expected_revision') = NEW.from_revision
       ))
       OR (NEW.authority_kind = 'controller'
         AND (
           (NEW.reason_code IN ('plan_ready','resume_ready') AND NEW.to_state = 'active')
           OR (NEW.reason_code IN ('dependency_blocked','capacity_blocked') AND NEW.to_state = 'blocked')
           OR (NEW.reason_code = 'run_sealed' AND NEW.to_state = 'completed')
           OR (NEW.reason_code = 'execution_failed' AND NEW.to_state = 'failed')
           OR (NEW.reason_code = 'benchmark_campaign_invalidated'
               AND NEW.to_state = 'cancelled')
         )
         AND (
           (NEW.reason_code = 'benchmark_campaign_invalidated'
             AND NEW.benchmark_campaign_invalidation_id IS NOT NULL)
           OR (NEW.reason_code <> 'benchmark_campaign_invalidated' AND EXISTS (
             SELECT 1 FROM artifact_manifests evidence
             JOIN current_valid_keys evidence_key
               ON evidence_key.key_id = evidence.signer_key_id
              AND evidence_key.key_purpose = 'artifact_broker'
             WHERE evidence.digest = NEW.evidence_manifest_digest
               AND json_extract(evidence.canonical_json, '$.artifact_type') = 'run_transition_evidence'
               AND json_extract(evidence.canonical_json, '$.run_id') = NEW.run_id
               AND json_extract(evidence.canonical_json, '$.project_id') = NEW.project_id
               AND json_extract(evidence.canonical_json, '$.from_state') = NEW.from_state
               AND json_extract(evidence.canonical_json, '$.to_state') = NEW.to_state
               AND json_extract(evidence.canonical_json, '$.from_revision') = NEW.from_revision
               AND json_extract(evidence.canonical_json, '$.reason_code') = NEW.reason_code
               AND json_extract(evidence.canonical_json, '$.leader_term') = NEW.leader_term
           ))
         ))
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'run_transition_authorization'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

CREATE TRIGGER run_transition_authorizations_no_update
BEFORE UPDATE ON run_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'run transition authorizations are immutable'); END;

CREATE TRIGGER run_transition_authorizations_no_delete
BEFORE DELETE ON run_transition_authorizations
BEGIN SELECT RAISE(ABORT, 'run transition authorizations are immutable'); END;

CREATE TRIGGER run_state_change_requires_exact_one_shot_authority
BEFORE UPDATE OF state ON runs
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'run state transition lacks exact current one-shot authority')
  WHERE NOT EXISTS (
    SELECT 1 FROM run_transition_authorizations authorization
    JOIN leader_terms term ON term.term = authorization.leader_term AND term.state = 'active'
    JOIN control_state control ON control.current_term = authorization.leader_term
    WHERE authorization.run_id = NEW.id
      AND authorization.project_id = NEW.project_id
      AND authorization.from_state = OLD.state
      AND authorization.to_state = NEW.state
      AND authorization.from_revision = OLD.revision
      AND authorization.to_revision = NEW.revision
      AND authorization.expires_at_ms >= (unixepoch('subsec') * 1000)
      AND (NEW.finished_at_ms IS NULL OR authorization.issued_at_ms = NEW.finished_at_ms)
      AND (NEW.state <> 'active' OR (
        control.admission_mode = 'open'
        AND control.dispatch_enabled = 1
        AND control.kill_switch = 0
      ))
  );
END;

CREATE TRIGGER runs_require_revision_cas
BEFORE UPDATE ON runs
BEGIN
  SELECT RAISE(ABORT, 'run mutation requires revision plus one')
  WHERE NEW.revision <> OLD.revision + 1;
END;

CREATE TRIGGER runs_legal_state_transition
BEFORE UPDATE OF state ON runs
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal run state transition')
  WHERE NOT (
    (OLD.state = 'created' AND NEW.state IN ('active','cancelled'))
    OR (OLD.state = 'active' AND NEW.state IN ('blocked','paused','completed','failed','cancelled'))
    OR (OLD.state = 'blocked' AND NEW.state IN ('active','paused','failed','cancelled'))
    OR (OLD.state = 'paused' AND NEW.state IN ('active','failed','cancelled'))
  );

  SELECT RAISE(ABORT, 'terminal run transition requires a bounded finish time')
  WHERE NEW.state IN ('completed','failed','cancelled')
    AND (NEW.finished_at_ms IS NULL
      OR NEW.finished_at_ms < OLD.created_at_ms
      OR NEW.finished_at_ms > (unixepoch('subsec') * 1000) + 5000);

  SELECT RAISE(ABORT, 'nonterminal run cannot carry a finish time')
  WHERE NEW.state NOT IN ('completed','failed','cancelled')
    AND NEW.finished_at_ms IS NOT NULL;

  SELECT RAISE(ABORT, 'completed run requires every planned node accepted, an exact final seal, and no live authority')
  WHERE NEW.state = 'completed'
    AND (
      NOT EXISTS (
        SELECT 1 FROM run_completion_seals seal
        WHERE seal.run_id = NEW.id AND seal.sealed_at_ms <= NEW.finished_at_ms
      )
      OR EXISTS (
        SELECT 1
        FROM logical_nodes logical_node
        WHERE EXISTS (
            SELECT 1 FROM node_versions member
            WHERE member.logical_node_id = logical_node.id AND member.run_id = NEW.id
          )
          AND (
            (SELECT COUNT(*) FROM node_versions winner
             WHERE winner.logical_node_id = logical_node.id
               AND winner.run_id = NEW.id
               AND winner.state = 'accepted') <> 1
            OR EXISTS (
              SELECT 1 FROM node_versions member
              WHERE member.logical_node_id = logical_node.id
                AND member.run_id = NEW.id
                AND member.state NOT IN ('accepted','superseded','failed','cancelled')
            )
            OR EXISTS (
              SELECT 1
              FROM node_versions winner
              WHERE winner.logical_node_id = logical_node.id
                AND winner.run_id = NEW.id
                AND winner.state = 'accepted'
                AND winner.version_no > 1
                AND NOT EXISTS (
                  WITH RECURSIVE replacement_chain(version_id) AS (
                    SELECT initial.id
                    FROM node_versions initial
                    WHERE initial.logical_node_id = logical_node.id
                      AND initial.run_id = NEW.id
                      AND initial.version_no = 1
                    UNION ALL
                    SELECT decision.to_node_version_id
                    FROM failover_decisions decision
                    JOIN replacement_chain chain
                      ON chain.version_id = decision.from_node_version_id
                    JOIN node_versions replacement
                      ON replacement.id = decision.to_node_version_id
                     AND replacement.logical_node_id = logical_node.id
                     AND replacement.run_id = NEW.id
                  )
                  SELECT 1 FROM replacement_chain WHERE version_id = winner.id
                )
            )
          )
      )
      OR EXISTS (
        SELECT 1 FROM attempts attempt
        WHERE attempt.run_id = NEW.id
          AND attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
      )
      OR EXISTS (
        SELECT 1
        FROM leases lease
        JOIN attempts attempt ON attempt.id = lease.attempt_id
        WHERE attempt.run_id = NEW.id AND lease.state = 'active'
      )
      OR EXISTS (
        SELECT 1
        FROM attempts attempt
        WHERE attempt.run_id = NEW.id
          AND NOT EXISTS (
            SELECT 1
            FROM charge_subjects subject
            JOIN budget_reservations reservation
              ON reservation.charge_subject_id = subject.id
            WHERE subject.scope_kind = 'attempt'
              AND subject.attempt_id = attempt.id
          )
      )
      OR EXISTS (
        SELECT 1
        FROM attempts attempt
        JOIN charge_subjects subject
          ON subject.attempt_id = attempt.id
         AND subject.scope_kind = 'attempt'
        JOIN budget_reservations reservation
          ON reservation.charge_subject_id = subject.id
        WHERE attempt.run_id = NEW.id
          AND (
            reservation.state NOT IN ('consumed','released')
            OR reservation.closed_at_ms IS NULL
            OR (
              reservation.state = 'consumed'
              AND NOT EXISTS (
                SELECT 1 FROM usage_events final_usage
                WHERE final_usage.reservation_id = reservation.id
                  AND final_usage.final_marker = 1
                  AND final_usage.sequence_no = (
                    SELECT MAX(latest.sequence_no)
                    FROM usage_events latest
                    WHERE latest.reservation_id = reservation.id
                  )
                  AND final_usage.observed_at_ms = reservation.closed_at_ms
              )
            )
          )
      )
      OR EXISTS (
        SELECT 1
        FROM attempts attempt
        JOIN charge_subjects subject
          ON subject.attempt_id = attempt.id
         AND subject.scope_kind = 'attempt'
        JOIN resource_reservations reservation
          ON reservation.charge_subject_id = subject.id
        WHERE attempt.run_id = NEW.id
          AND reservation.state IN ('held','breached')
      )
    );
END;

CREATE TRIGGER benchmark_invalidated_campaign_cannot_complete_run
BEFORE UPDATE OF state ON runs
WHEN OLD.state <> NEW.state
 AND NEW.state = 'completed'
 AND EXISTS (
   SELECT 1 FROM benchmark_campaign_invalidations invalidation
   WHERE invalidation.preregistration_digest = NEW.benchmark_preregistration_digest
 )
 OR (OLD.state <> NEW.state
   AND NEW.state = 'completed'
   AND EXISTS (
     SELECT 1
     FROM attempts evaluator
     JOIN benchmark_blind_assignments assignment ON assignment.evaluator_attempt_id = evaluator.id
     JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = arm.preregistration_digest
     WHERE evaluator.run_id = NEW.id
   ))
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot complete a run');
END;

CREATE TRIGGER run_finish_time_is_set_once
BEFORE UPDATE OF finished_at_ms ON runs
WHEN OLD.finished_at_ms IS NOT NEW.finished_at_ms
BEGIN
  SELECT RAISE(ABORT, 'run finish time is set once on its terminal transition')
  WHERE OLD.finished_at_ms IS NOT NULL
     OR NEW.finished_at_ms IS NULL
     OR OLD.state = NEW.state
     OR NEW.state NOT IN ('completed','failed','cancelled');
END;

CREATE TRIGGER node_versions_legal_state_transition
BEFORE UPDATE OF state ON node_versions
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal node-version state transition')
  WHERE NOT (
    (OLD.state = 'pending' AND NEW.state IN ('ready','superseded','cancelled'))
    OR (OLD.state = 'ready' AND NEW.state IN ('dispatched','superseded','cancelled'))
    OR (OLD.state = 'dispatched' AND NEW.state IN ('accepted','ready','failed','superseded','cancelled'))
  );
END;

CREATE TRIGGER node_versions_require_revision_cas
BEFORE UPDATE ON node_versions
BEGIN
  SELECT RAISE(ABORT, 'node-version mutation requires revision plus one')
  WHERE NEW.revision <> OLD.revision + 1;
END;

CREATE TRIGGER executor_slots_require_revision_cas
BEFORE UPDATE ON executor_slots
BEGIN
  SELECT RAISE(ABORT, 'executor-slot mutation requires revision plus one')
  WHERE NEW.revision <> OLD.revision + 1;
END;

CREATE TRIGGER node_ready_requires_satisfied_dependencies
BEFORE UPDATE OF state ON node_versions
WHEN NEW.state = 'ready' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'node cannot become ready with unsatisfied dependencies')
  WHERE EXISTS (
    SELECT 1
    FROM node_dependencies nd
    WHERE nd.node_version_id = NEW.id
      AND (
        SELECT COUNT(*)
        FROM resolved_dependency_winners winner
        WHERE winner.node_version_id = nd.node_version_id
          AND winner.declared_parent_node_version_id = nd.depends_on_node_version_id
          AND winner.dependency_type = nd.dependency_type
      ) <> 1
  );

  SELECT RAISE(ABORT, 'ready node requires ready_since_ms')
  WHERE NEW.ready_since_ms IS NULL
     OR NEW.ready_since_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.ready_since_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.input_manifest_digest IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM artifact_manifests am
       JOIN current_valid_keys sk ON sk.key_id = am.signer_key_id
       JOIN artifact_instances ai ON ai.manifest_digest = am.digest
       JOIN runs r ON r.id = NEW.run_id
       WHERE am.digest = NEW.input_manifest_digest
         AND sk.key_purpose = 'artifact_broker'
         AND ai.artifact_type = 'node_input'
         AND ai.project_id = r.project_id
         AND ai.run_id = NEW.run_id
         AND ai.node_version_id = NEW.id
         AND ai.producer_attempt_id IS NULL
     )
     OR EXISTS (
       SELECT 1 FROM configuration_artifact_invalidations cai
       WHERE cai.configuration_digest = NEW.output_schema_digest
     );

  SELECT RAISE(ABORT, 'node input lacks declared artifact provenance from an accepted dependency')
  WHERE EXISTS (
    SELECT 1
    FROM node_dependencies nd
    WHERE nd.node_version_id = NEW.id
      AND nd.dependency_type IN ('artifact','review')
      AND NOT EXISTS (
        SELECT 1
        FROM resolved_dependency_winners winner
        CROSS JOIN artifact_instances child_input
        JOIN artifact_inputs edge ON edge.artifact_instance_id = child_input.id
        JOIN artifact_instances parent_output ON parent_output.id = edge.input_artifact_instance_id
        WHERE winner.node_version_id = nd.node_version_id
          AND winner.declared_parent_node_version_id = nd.depends_on_node_version_id
          AND winner.dependency_type = nd.dependency_type
          AND child_input.manifest_digest = NEW.input_manifest_digest
          AND child_input.artifact_type = 'node_input'
          AND child_input.run_id = NEW.run_id
          AND child_input.node_version_id = NEW.id
          AND edge.relation = 'declared_dependency'
          AND parent_output.run_id = NEW.run_id
          AND parent_output.node_version_id = winner.accepted_parent_node_version_id
          AND parent_output.producer_attempt_id = winner.accepted_parent_attempt_id
          AND parent_output.artifact_type = 'node_output'
      )
  );

  SELECT RAISE(ABORT, 'node input contains undeclared or non-seed provenance')
  WHERE EXISTS (
    SELECT 1
    FROM artifact_instances child_input
    JOIN artifact_inputs edge ON edge.artifact_instance_id = child_input.id
    JOIN artifact_instances parent ON parent.id = edge.input_artifact_instance_id
    WHERE child_input.manifest_digest = NEW.input_manifest_digest
      AND child_input.artifact_type = 'node_input'
      AND child_input.run_id = NEW.run_id
      AND child_input.node_version_id = NEW.id
      AND (
        (parent.node_version_id IS NOT NULL AND (
          edge.relation <> 'declared_dependency'
          OR NOT EXISTS (
            SELECT 1 FROM resolved_dependency_winners dependency
            WHERE dependency.node_version_id = NEW.id
              AND dependency.accepted_parent_node_version_id = parent.node_version_id
              AND dependency.dependency_type IN ('artifact','review')
          )
        ))
        OR (parent.node_version_id IS NULL AND (
          edge.relation <> 'task_seed'
          OR parent.artifact_type NOT IN ('sanitized_assets','evidence')
          OR parent.producer_attempt_id IS NOT NULL
        ))
      )
  );

  SELECT RAISE(ABORT, 'root node input does not exactly consume the frozen signed seed set')
  WHERE NOT EXISTS (
      SELECT 1 FROM node_dependencies dependency
      WHERE dependency.node_version_id = NEW.id
    )
    AND EXISTS (
      SELECT 1 FROM runs run
      WHERE run.id = NEW.run_id
        AND (
          (run.benchmark_preregistration_digest IS NULL AND (
            EXISTS (
              SELECT 1
              FROM artifact_manifests plan,
                   json_each(plan.canonical_json, '$.plan.root_seed_manifest_digests') declared_seed
              WHERE plan.digest = run.plan_manifest_digest
                AND NOT EXISTS (
                  SELECT 1
                  FROM artifact_instances child_input
                  JOIN artifact_inputs edge ON edge.artifact_instance_id = child_input.id
                  JOIN artifact_instances seed ON seed.id = edge.input_artifact_instance_id
                  WHERE child_input.manifest_digest = NEW.input_manifest_digest
                    AND edge.relation = 'task_seed'
                    AND seed.manifest_digest = declared_seed.value
                )
            )
            OR EXISTS (
              SELECT 1
              FROM artifact_instances child_input
              JOIN artifact_inputs edge ON edge.artifact_instance_id = child_input.id
              JOIN artifact_instances seed ON seed.id = edge.input_artifact_instance_id
              JOIN artifact_manifests plan ON plan.digest = run.plan_manifest_digest
              WHERE child_input.manifest_digest = NEW.input_manifest_digest
                AND edge.relation = 'task_seed'
                AND NOT EXISTS (
                  SELECT 1
                  FROM json_each(plan.canonical_json, '$.plan.root_seed_manifest_digests') declared_seed
                  WHERE declared_seed.value = seed.manifest_digest
                )
            )
          ))
          OR (run.benchmark_preregistration_digest IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM benchmark_arm_seed_bindings binding
            JOIN artifact_instances input_instance
              ON input_instance.id = binding.input_artifact_instance_id
            JOIN benchmark_arm_runs arm ON arm.arm_execution_id = binding.arm_execution_id
            WHERE binding.node_version_id = NEW.id
              AND input_instance.manifest_digest = NEW.input_manifest_digest
              AND arm.preregistration_digest = run.benchmark_preregistration_digest
              AND arm.task_id = run.benchmark_task_id
              AND arm.arm = run.benchmark_arm
          ))
        )
    );
END;

CREATE TRIGGER node_ready_timestamp_changes_only_on_ready_entry
BEFORE UPDATE OF ready_since_ms ON node_versions
WHEN OLD.ready_since_ms IS NOT NEW.ready_since_ms
BEGIN
  SELECT RAISE(ABORT, 'ready timestamp is immutable except on an exact transition into ready')
  WHERE NEW.state <> 'ready'
     OR OLD.state = 'ready'
     OR NEW.ready_since_ms IS NULL
     OR NEW.ready_since_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.ready_since_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER node_dispatch_requires_current_attempt
BEFORE UPDATE OF state ON node_versions
WHEN OLD.state = 'ready' AND NEW.state = 'dispatched'
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm is quarantined after measured budget breach')
  WHERE EXISTS (
    SELECT 1
    FROM benchmark_arm_run_members member
    JOIN benchmark_arm_budget_breaches breach
      ON breach.arm_execution_id = member.arm_execution_id
    WHERE member.run_id = NEW.run_id
  );

  SELECT RAISE(ABORT, 'dispatched node must point at its created attempt')
  WHERE NEW.current_attempt_id IS NULL
    OR NOT EXISTS (
      SELECT 1 FROM attempts
      WHERE id = NEW.current_attempt_id
        AND node_version_id = NEW.id
        AND state = 'created'
    );

  SELECT RAISE(ABORT, 'node dispatch requires the exact immutable complete dispatch bundle')
  WHERE NOT EXISTS (
    SELECT 1 FROM dispatch_bundle_commits bundle
    WHERE bundle.node_version_id = NEW.id
      AND bundle.attempt_id = NEW.current_attempt_id
      AND bundle.leader_term = (
        SELECT attempt.leader_term FROM attempts attempt
        WHERE attempt.id = NEW.current_attempt_id
      )
  );

  SELECT RAISE(ABORT, 'dispatch requires a held budget reservation for current attempt')
  WHERE NOT EXISTS (
      SELECT 1
      FROM charge_subjects cs
      JOIN budget_reservations br ON br.charge_subject_id = cs.id
      WHERE cs.attempt_id = NEW.current_attempt_id
        AND cs.scope_kind = 'attempt'
        AND br.state = 'held'
    );

  SELECT RAISE(ABORT, 'dispatch requires the correct held process-resource reservation')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN executors e ON e.id = a.executor_id
    WHERE a.id = NEW.current_attempt_id
      AND (
        (e.fresh_session_required = 1 AND EXISTS (
          SELECT 1
          FROM charge_subjects cs
          JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
          WHERE cs.scope_kind = 'attempt'
            AND cs.attempt_id = a.id
            AND rr.reservation_kind = 'process'
            AND rr.state = 'held'
        ))
        OR (e.fresh_session_required = 0 AND e.id <> 'rick'
          AND EXISTS (
            SELECT 1
            FROM runtime_sessions s
            JOIN project_slots ps
              ON ps.slot_no = a.project_slot_no
             AND ps.project_id = a.project_id
             AND ps.generation = a.project_slot_generation
             AND ps.orchestrator_executor_id = a.executor_id
            JOIN charge_subjects cs
              ON cs.runtime_intent_id = s.runtime_intent_id
             AND cs.scope_kind = 'project_runtime'
             AND cs.project_id = a.project_id
            JOIN resource_reservations rr ON rr.charge_subject_id = cs.id
            WHERE s.executor_id = a.executor_id
              AND s.project_slot_no = a.project_slot_no
              AND s.project_slot_generation = a.project_slot_generation
              AND s.state IN ('starting','running')
              AND rr.reservation_kind = 'process'
              AND rr.state = 'held'
          )
          AND EXISTS (
            SELECT 1
            FROM charge_subjects call_cs
            JOIN resource_reservations call_rr
              ON call_rr.charge_subject_id = call_cs.id
            WHERE call_cs.scope_kind = 'attempt'
              AND call_cs.attempt_id = a.id
              AND call_rr.reservation_kind = 'active_call'
              AND call_rr.state = 'held'
          ))
      )
  );
END;

CREATE TRIGGER node_retry_and_failure_require_terminal_attempts
BEFORE UPDATE OF state ON node_versions
WHEN OLD.state = 'dispatched' AND NEW.state IN ('ready','failed')
BEGIN
  SELECT RAISE(ABORT, 'node retry/failure requires current attempt to be terminal')
  WHERE EXISTS (
    SELECT 1 FROM attempts
    WHERE node_version_id = NEW.id
      AND state IN ('created','dispatched','acked','running','result_pending','unknown')
  );

  SELECT RAISE(ABORT, 'node retry must clear current attempt and retain retry budget')
  WHERE NEW.state = 'ready'
    AND (
      NEW.current_attempt_id IS NOT NULL
      OR (SELECT COUNT(*) FROM attempts WHERE node_version_id = NEW.id) > NEW.retry_limit
    );

  SELECT RAISE(ABORT, 'node failure requires retry exhaustion and no current attempt')
  WHERE NEW.state = 'failed'
    AND (
      NEW.current_attempt_id IS NOT NULL
      OR (SELECT COUNT(*) FROM attempts WHERE node_version_id = NEW.id) < NEW.retry_limit + 1
    );
END;

CREATE TRIGGER node_acceptance_requires_accepted_attempt
BEFORE UPDATE OF state ON node_versions
WHEN NEW.state = 'accepted' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'accepted node must point at its accepted current attempt')
  WHERE NEW.accepted_attempt_id IS NULL
    OR NEW.current_attempt_id IS NOT NEW.accepted_attempt_id
    OR NOT EXISTS (
      SELECT 1 FROM attempts
      WHERE id = NEW.accepted_attempt_id
        AND node_version_id = NEW.id
        AND state = 'accepted'
    );
END;

CREATE TRIGGER attempts_legal_state_transition
BEFORE UPDATE OF state ON attempts
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal attempt state transition')
  WHERE NOT (
    (OLD.state = 'created' AND NEW.state = 'dispatched')
    OR (OLD.state = 'dispatched' AND NEW.state = 'acked')
    OR (OLD.state = 'acked' AND NEW.state = 'running')
    OR (OLD.state = 'running' AND NEW.state = 'result_pending')
    OR (OLD.state = 'result_pending' AND NEW.state = 'accepted')
    OR (OLD.state IN ('created','dispatched','acked','running','result_pending')
        AND NEW.state IN ('failed','expired','cancelled','stale','quarantined','unknown'))
    OR (OLD.state = 'unknown'
        AND NEW.state IN ('accepted','failed','stale','quarantined'))
  );

  SELECT RAISE(ABORT, 'attempt dispatch does not match the current node pointer or ack deadline')
  WHERE NEW.state = 'dispatched'
    AND (
      (unixepoch('subsec') * 1000) > NEW.ack_deadline_ms
      OR NOT EXISTS (
        SELECT 1 FROM node_versions nv
        WHERE nv.id = NEW.node_version_id
          AND nv.state = 'dispatched'
          AND nv.current_attempt_id = NEW.id
      )
    );

  SELECT RAISE(ABORT, 'attempt dispatch requires its exact immutable complete bundle')
  WHERE NEW.state = 'dispatched'
    AND NOT EXISTS (
      SELECT 1 FROM dispatch_bundle_commits bundle
      WHERE bundle.attempt_id = NEW.id
        AND bundle.node_version_id = NEW.node_version_id
        AND bundle.leader_term = NEW.leader_term
    );

  SELECT RAISE(ABORT, 'benchmark evaluator dispatch requires a prior current blind assignment')
  WHERE NEW.state = 'dispatched'
    AND EXISTS (
      SELECT 1 FROM executor_capabilities capability
      WHERE capability.executor_id = NEW.executor_id
        AND capability.capability = 'benchmark-evaluator'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM benchmark_blind_assignments assignment
      JOIN benchmark_arm_settlement_seals settlement
        ON settlement.arm_execution_id = assignment.arm_execution_id
      WHERE assignment.evaluator_attempt_id = NEW.id
        AND assignment.assigned_at_ms <= (unixepoch('subsec') * 1000)
        AND NOT EXISTS (
          SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
          WHERE invalidation.settlement_digest = settlement.digest
        )
    );

  SELECT RAISE(ABORT, 'attempt ack lacks a current receipt and lease before its deadline')
  WHERE NEW.state = 'acked'
    AND (
      (unixepoch('subsec') * 1000) > NEW.ack_deadline_ms
      OR NOT EXISTS (
        SELECT 1
        FROM dispatch_receipts dr
        JOIN leases l ON l.attempt_id = NEW.id
        WHERE dr.attempt_id = NEW.id
          AND dr.dispatch_key = NEW.dispatch_key
          AND dr.executor_id = NEW.executor_id
          AND dr.state IN ('received','launch_claimed','launched','completed')
          AND l.state = 'active'
          AND l.fence = NEW.fence
          AND l.leader_term = NEW.leader_term
          AND l.expires_at_ms >= (unixepoch('subsec') * 1000)
      )
    );

  SELECT RAISE(ABORT, 'attempt running lacks a live exact lease/session binding or start time')
  WHERE NEW.state = 'running'
    AND (
      NEW.started_at_ms IS NULL
      OR NEW.started_at_ms > NEW.lease_deadline_ms
      OR NEW.started_at_ms > NEW.hard_deadline_ms
      OR NOT EXISTS (
        SELECT 1
        FROM leases l
        JOIN dispatch_receipts dr ON dr.attempt_id = NEW.id
        JOIN attempt_session_bindings b
          ON b.attempt_id = NEW.id AND b.unbound_at_ms IS NULL
        JOIN runtime_sessions s
          ON s.id = b.runtime_session_id AND s.state = 'running'
        WHERE l.attempt_id = NEW.id
          AND l.state = 'active'
          AND l.worker_instance_id = s.worker_instance_id
          AND l.expires_at_ms >= NEW.started_at_ms
          AND dr.state = 'launched'
          AND dr.process_identity = s.process_identity
      )
    );

  SELECT RAISE(ABORT, 'attempt result-pending lacks an immutable inbound result before hard deadline')
  WHERE NEW.state = 'result_pending'
    AND (
      (unixepoch('subsec') * 1000) > NEW.hard_deadline_ms
      OR NOT EXISTS (
        SELECT 1 FROM result_envelopes re
        WHERE re.attempt_id = NEW.id
          AND re.state IN ('received','prevalidated')
      )
    );

  SELECT RAISE(ABORT, 'terminal attempt requires a bounded finish time')
  WHERE NEW.state IN ('accepted','failed','expired','cancelled','stale','quarantined','unknown')
    AND (
      NEW.finished_at_ms IS NULL
      OR NEW.finished_at_ms < NEW.created_at_ms
      OR NEW.finished_at_ms > (unixepoch('subsec') * 1000) + 5000
    );

  SELECT RAISE(ABORT, 'attempt cannot expire before its applicable deadline')
  WHERE NEW.state = 'expired'
    AND (unixepoch('subsec') * 1000) <= CASE OLD.state
      WHEN 'dispatched' THEN NEW.ack_deadline_ms
      WHEN 'acked' THEN NEW.lease_deadline_ms
      ELSE NEW.hard_deadline_ms
    END;

  SELECT RAISE(ABORT, 'failed or ambiguous attempt requires a stable diagnostic code')
  WHERE NEW.state IN ('failed','expired','cancelled','stale','quarantined','unknown')
    AND NEW.error_code IS NULL;
END;

CREATE TRIGGER attempt_start_time_is_set_once_with_running
BEFORE UPDATE OF started_at_ms ON attempts
WHEN OLD.started_at_ms IS NOT NEW.started_at_ms
BEGIN
  SELECT RAISE(ABORT, 'attempt start time is set once with running state')
  WHERE OLD.started_at_ms IS NOT NULL
     OR NEW.started_at_ms IS NULL
     OR NEW.state <> 'running';
END;

CREATE TRIGGER attempt_finish_time_is_set_once_with_terminal_state
BEFORE UPDATE OF finished_at_ms ON attempts
WHEN OLD.finished_at_ms IS NOT NEW.finished_at_ms
BEGIN
  SELECT RAISE(ABORT, 'attempt finish time is set once with terminal state')
  WHERE OLD.finished_at_ms IS NOT NULL
     OR NEW.finished_at_ms IS NULL
     OR NEW.state NOT IN ('accepted','failed','expired','cancelled','stale','quarantined','unknown');
END;

CREATE TRIGGER attempt_error_code_is_transition_bound
BEFORE UPDATE OF error_code ON attempts
WHEN OLD.error_code IS NOT NEW.error_code
BEGIN
  SELECT RAISE(ABORT, 'attempt diagnostic is set once with a failure or ambiguity transition')
  WHERE OLD.error_code IS NOT NULL
     OR NEW.error_code IS NULL
     OR OLD.state = NEW.state
     OR NEW.state NOT IN ('failed','expired','cancelled','stale','quarantined','unknown');
END;

CREATE TRIGGER node_attempt_pointers_change_only_with_state
BEFORE UPDATE OF current_attempt_id, accepted_attempt_id ON node_versions
WHEN OLD.state = NEW.state
  AND (
    OLD.current_attempt_id IS NOT NEW.current_attempt_id
    OR OLD.accepted_attempt_id IS NOT NEW.accepted_attempt_id
  )
BEGIN
  SELECT RAISE(ABORT, 'node attempt pointers change only with the state CAS');
END;

CREATE TRIGGER leases_legal_state_transition
BEFORE UPDATE OF state ON leases
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal lease state transition')
  WHERE NOT (
    OLD.state = 'active'
    AND NEW.state IN ('released','expired','revoked','quarantined')
  );

  SELECT RAISE(ABORT, 'terminal lease transition requires one terminal timestamp')
  WHERE NEW.released_at_ms IS NULL
     OR NEW.released_at_ms < OLD.acquired_at_ms
     OR NEW.released_at_ms > (unixepoch('subsec') * 1000) + 5000;
END;

CREATE TRIGGER lease_renewal_requires_live_exact_authority
BEFORE UPDATE OF heartbeat_seq, expires_at_ms ON leases
WHEN OLD.heartbeat_seq IS NOT NEW.heartbeat_seq OR OLD.expires_at_ms IS NOT NEW.expires_at_ms
BEGIN
  SELECT RAISE(ABORT, 'lease renewal lost exact worker/attempt/slot/project/term authority')
  WHERE OLD.state <> 'active'
     OR NEW.state <> 'active'
     OR NEW.released_at_ms IS NOT NULL
     OR NEW.heartbeat_seq <> OLD.heartbeat_seq + 1
     OR NEW.expires_at_ms <= OLD.expires_at_ms
     OR OLD.expires_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NOT EXISTS (
       SELECT 1
       FROM attempts a
       JOIN node_versions nv
         ON nv.id = a.node_version_id
        AND nv.current_attempt_id = a.id
        AND nv.state = 'dispatched'
       JOIN executor_slots es
         ON es.id = a.executor_slot_id
        AND es.fence_counter = a.fence
        AND es.state = 'leased'
       JOIN project_slots ps
         ON ps.slot_no = a.project_slot_no
        AND ps.project_id = a.project_id
        AND ps.generation = a.project_slot_generation
       JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
       JOIN control_state ctl ON ctl.current_term = a.leader_term
       WHERE a.id = NEW.attempt_id
         AND a.state IN ('dispatched','acked','running','result_pending')
         AND a.executor_slot_id = NEW.executor_slot_id
         AND a.fence = NEW.fence
         AND a.leader_term = NEW.leader_term
         AND NEW.worker_instance_id = OLD.worker_instance_id
         AND NEW.expires_at_ms <= a.hard_deadline_ms
         AND ctl.dispatch_enabled = 1
         AND (
           ctl.admission_mode = 'open'
           OR (ctl.admission_mode = 'draining'
             AND a.state IN ('acked','running','result_pending'))
         )
         AND ctl.kill_switch = 0
     );
END;

CREATE TRIGGER lease_terminal_fields_freeze
BEFORE UPDATE OF heartbeat_seq, expires_at_ms, released_at_ms ON leases
WHEN OLD.state <> 'active'
BEGIN SELECT RAISE(ABORT, 'terminal lease timing fields are immutable'); END;

CREATE TRIGGER outbox_legal_state_transition
BEFORE UPDATE OF state ON outbox
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal outbox state transition')
  WHERE NOT (
    (OLD.state = 'pending' AND NEW.state IN ('claimed','cancelled','dead'))
    OR (OLD.state = 'claimed' AND NEW.state IN ('pending','sent','cancelled','dead'))
    OR (OLD.state = 'sent' AND NEW.state IN ('acked','unknown','cancelled','dead'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('sent','acked','cancelled','dead'))
  );
END;

CREATE TRIGGER dispatch_outbox_send_requires_dispatched_attempt
BEFORE UPDATE OF state ON outbox
WHEN NEW.topic = 'dispatch'
  AND NEW.state IN ('claimed','sent')
  AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'dispatch sender lost full launch authority')
  WHERE NOT EXISTS (
    SELECT 1 FROM launch_ready_attempts WHERE attempt_id = NEW.attempt_id
  );

  SELECT RAISE(ABORT, 'dispatch sender cannot claim/send before attempt dispatch')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN node_versions nv ON nv.id = a.node_version_id
    JOIN leases l ON l.attempt_id = a.id
    JOIN executor_slots es ON es.id = a.executor_slot_id
    JOIN project_slots ps ON ps.slot_no = a.project_slot_no
    JOIN leader_terms lt ON lt.term = a.leader_term
    JOIN control_state ctl ON ctl.singleton = 1
    WHERE a.id = NEW.attempt_id
      AND a.state = 'dispatched'
      AND nv.current_attempt_id = a.id
      AND nv.state = 'dispatched'
      AND l.state = 'active'
      AND l.fence = a.fence
      AND l.leader_term = a.leader_term
      AND l.expires_at_ms > (unixepoch('subsec') * 1000)
      AND es.state = 'leased'
      AND es.fence_counter = a.fence
      AND ps.project_id = a.project_id
      AND ps.generation = a.project_slot_generation
      AND lt.state = 'active'
      AND ctl.current_term = a.leader_term
      AND ctl.dispatch_enabled = 1
      AND ctl.kill_switch = 0
  );

  SELECT RAISE(ABORT, 'outbox claim requires token and visibility deadline')
  WHERE NEW.state = 'claimed'
    AND (NEW.claim_token IS NULL
      OR NEW.claim_until_ms IS NULL
      OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000));

  SELECT RAISE(ABORT, 'outbox send claim expired')
  WHERE NEW.state = 'sent'
    AND (NEW.claim_token IS NULL
      OR NEW.claim_until_ms IS NULL
      OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000));
END;

CREATE TRIGGER dispatch_receipts_legal_state_transition
BEFORE UPDATE OF state ON dispatch_receipts
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal dispatch-receipt state transition')
  WHERE NOT (
    (OLD.state = 'received' AND NEW.state = 'launch_claimed')
    OR (OLD.state = 'launch_claimed' AND NEW.state IN ('launched','unknown'))
    OR (OLD.state = 'launched' AND NEW.state IN ('completed','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state = 'completed')
  );
END;

CREATE TRIGGER dispatch_receipt_claim_requires_stable_launch_identity
BEFORE UPDATE OF state ON dispatch_receipts
WHEN OLD.state = 'received' AND NEW.state = 'launch_claimed'
BEGIN
  SELECT RAISE(ABORT, 'launch claim lost full policy, budget, resource, or catalog authority')
  WHERE NOT EXISTS (
    SELECT 1 FROM launch_ready_attempts WHERE attempt_id = NEW.attempt_id
  );

  SELECT RAISE(ABORT, 'launch claim requires token, model call, and process identity')
  WHERE NEW.launch_claim_token IS NULL
     OR NEW.launch_claim_until_ms IS NULL
     OR NEW.launch_claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.model_call_id IS NULL
     OR NEW.process_identity IS NULL;

  SELECT RAISE(ABORT, 'launch claim lost current attempt authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN node_versions nv ON nv.id = a.node_version_id
    JOIN leases l ON l.attempt_id = a.id
    JOIN executor_slots es ON es.id = a.executor_slot_id
    JOIN project_slots ps ON ps.slot_no = a.project_slot_no
    JOIN leader_terms lt ON lt.term = a.leader_term
    JOIN control_state ctl ON ctl.singleton = 1
    JOIN outbox o
      ON o.attempt_id = a.id
     AND o.topic = 'dispatch'
     AND o.idempotency_key = a.dispatch_key
    WHERE a.id = NEW.attempt_id
      AND a.executor_id = NEW.executor_id
      AND a.state = 'dispatched'
      AND nv.current_attempt_id = a.id
      AND nv.state = 'dispatched'
      AND l.state = 'active'
      AND l.fence = a.fence
      AND l.leader_term = a.leader_term
      AND l.expires_at_ms > (unixepoch('subsec') * 1000)
      AND es.state = 'leased'
      AND es.fence_counter = a.fence
      AND ps.project_id = a.project_id
      AND ps.generation = a.project_slot_generation
      AND lt.state = 'active'
      AND ctl.current_term = a.leader_term
      AND ctl.dispatch_enabled = 1
      AND ctl.kill_switch = 0
      AND o.state IN ('sent','unknown')
  );
END;

CREATE TRIGGER dispatch_receipt_launch_requires_timestamp
BEFORE UPDATE OF state ON dispatch_receipts
WHEN NEW.state = 'launched' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'final launch permit lost full policy, budget, resource, or catalog authority')
  WHERE NOT EXISTS (
    SELECT 1 FROM launch_ready_attempts WHERE attempt_id = NEW.attempt_id
  );

  SELECT RAISE(ABORT, 'launched dispatch requires timestamp and stable identity')
  WHERE NEW.launched_at_ms IS NULL
     OR NEW.launch_claim_token IS NULL
     OR NEW.launch_claim_until_ms IS NULL
     OR NEW.launched_at_ms > NEW.launch_claim_until_ms
     OR NEW.launch_claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.model_call_id IS NULL
     OR NEW.process_identity IS NULL;

  SELECT RAISE(ABORT, 'final launch permit lost current attempt authority')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN node_versions nv ON nv.id = a.node_version_id
    JOIN leases l ON l.attempt_id = a.id
    JOIN executor_slots es ON es.id = a.executor_slot_id
    JOIN project_slots ps ON ps.slot_no = a.project_slot_no
    JOIN leader_terms lt ON lt.term = a.leader_term
    JOIN control_state ctl ON ctl.singleton = 1
    WHERE a.id = NEW.attempt_id
      AND a.state = 'dispatched'
      AND nv.current_attempt_id = a.id
      AND nv.state = 'dispatched'
      AND l.state = 'active'
      AND l.expires_at_ms > NEW.launched_at_ms
      AND es.state = 'leased'
      AND es.fence_counter = a.fence
      AND ps.project_id = a.project_id
      AND ps.generation = a.project_slot_generation
      AND lt.state = 'active'
      AND ctl.current_term = a.leader_term
      AND ctl.dispatch_enabled = 1
      AND ctl.kill_switch = 0
  );
END;

CREATE TRIGGER dispatch_receipt_completion_requires_timestamp
BEFORE UPDATE OF state ON dispatch_receipts
WHEN NEW.state = 'completed' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'completed dispatch requires launch identity and completion time')
  WHERE NEW.completed_at_ms IS NULL
     OR NEW.launched_at_ms IS NULL
     OR NEW.model_call_id IS NULL
     OR NEW.process_identity IS NULL
     OR EXISTS (
       SELECT 1 FROM executors e
       WHERE e.id = NEW.executor_id
         AND e.fresh_session_required = 1
         AND NOT EXISTS (
           SELECT 1
           FROM attempt_session_bindings b
           JOIN runtime_sessions rs ON rs.id = b.runtime_session_id
           WHERE b.attempt_id = NEW.attempt_id
             AND rs.process_identity = NEW.process_identity
             AND rs.state = 'terminated'
         )
         AND NOT EXISTS (
           SELECT 1 FROM reconciliation_decisions d
           WHERE d.subject_kind = 'dispatch_receipt'
             AND d.subject_id = NEW.dispatch_key
             AND d.resolved_state = 'completed'
             AND d.process_identity = NEW.process_identity
             AND d.provider_lookup_key = NEW.model_call_id
             AND d.observed_process_state IN ('dead','absent')
         )
     );
END;

CREATE TRIGGER dispatch_receipt_launch_identity_set_once
BEFORE UPDATE OF launch_claim_token, launch_claim_until_ms, model_call_id, process_identity
ON dispatch_receipts
WHEN (OLD.launch_claim_token IS NOT NULL AND OLD.launch_claim_token IS NOT NEW.launch_claim_token)
  OR (OLD.launch_claim_until_ms IS NOT NULL
      AND OLD.launch_claim_until_ms IS NOT NEW.launch_claim_until_ms)
  OR (OLD.model_call_id IS NOT NULL AND OLD.model_call_id IS NOT NEW.model_call_id)
  OR (OLD.process_identity IS NOT NULL AND OLD.process_identity IS NOT NEW.process_identity)
BEGIN SELECT RAISE(ABORT, 'dispatch launch identity is immutable once claimed'); END;

CREATE TRIGGER result_envelopes_legal_state_transition
BEFORE UPDATE OF state ON result_envelopes
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal result-envelope state transition')
  WHERE NOT (
    (OLD.state = 'received' AND NEW.state = 'prevalidated')
    OR (OLD.state = 'prevalidated' AND NEW.state IN ('accepted','rejected','quarantined'))
  );

  SELECT RAISE(ABORT, 'prevalidation requires an exact passing signature-verification receipt')
  WHERE OLD.state = 'received'
    AND NEW.state = 'prevalidated'
    AND NOT EXISTS (
      SELECT 1
      FROM result_signature_validation_receipts receipt
      JOIN current_valid_keys validator_key
        ON validator_key.key_id = receipt.signer_key_id
       AND validator_key.principal_id = receipt.signer_principal_id
       AND validator_key.key_purpose = 'schema_validator'
      JOIN current_valid_keys executor_key
        ON executor_key.key_id = receipt.executor_key_id
       AND executor_key.key_purpose = 'executor_result'
      JOIN configuration_artifacts validator
        ON validator.digest = receipt.validator_closure_digest
       AND validator.artifact_kind = 'toolchain_closure'
      WHERE receipt.result_envelope_id = NEW.id
        AND receipt.payload_digest = NEW.payload_digest
        AND receipt.executor_key_id = NEW.signer_key_id
        AND receipt.verdict = 'pass'
        AND NOT EXISTS (
          SELECT 1 FROM configuration_artifact_invalidations cai
          WHERE cai.configuration_digest = receipt.validator_closure_digest
        )
    );
END;

CREATE TRIGGER accepted_result_requires_current_authority
BEFORE UPDATE OF state ON result_envelopes
WHEN OLD.state = 'prevalidated' AND NEW.state = 'accepted'
BEGIN
  SELECT RAISE(ABORT, 'result acceptance failed term/fence/generation/lineage checks')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attempts a
    JOIN node_versions nv
      ON nv.id = a.node_version_id
    JOIN runs r ON r.id = a.run_id
    JOIN policies np ON np.digest = nv.policy_digest
    JOIN signing_keys nsk ON nsk.key_id = np.signer_key_id
    JOIN policies rpp ON rpp.digest = r.pipeline_policy_digest
    JOIN signing_keys rpsk ON rpsk.key_id = rpp.signer_key_id
    JOIN leases l
      ON l.attempt_id = a.id
    JOIN executor_slots es
      ON es.id = a.executor_slot_id
    JOIN project_slots ps
      ON ps.slot_no = a.project_slot_no
    JOIN leader_terms lt
      ON lt.term = a.leader_term
    JOIN control_state cs
      ON cs.singleton = 1
    JOIN executors e
      ON e.id = a.executor_id
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.principal_id = e.principal_id
     AND sk.key_purpose = 'executor_result'
    JOIN result_signature_validation_receipts signature_receipt
      ON signature_receipt.result_envelope_id = NEW.id
     AND signature_receipt.payload_digest = NEW.payload_digest
     AND signature_receipt.executor_key_id = NEW.signer_key_id
     AND signature_receipt.verdict = 'pass'
    JOIN current_valid_keys signature_validator_key
      ON signature_validator_key.key_id = signature_receipt.signer_key_id
     AND signature_validator_key.principal_id = signature_receipt.signer_principal_id
     AND signature_validator_key.key_purpose = 'schema_validator'
    JOIN dispatch_receipts dr
      ON dr.attempt_id = a.id
     AND dr.dispatch_key = a.dispatch_key
     AND dr.executor_id = a.executor_id
     AND dr.process_identity IS NOT NULL
     AND dr.state IN ('launched','completed')
    JOIN attempt_session_bindings asb
      ON asb.attempt_id = a.id
    JOIN schema_validation_attestations sva
      ON sva.result_envelope_id = NEW.id
     AND sva.output_manifest_digest = NEW.output_manifest_digest
     AND sva.output_schema_digest = nv.output_schema_digest
     AND sva.verdict = 'pass'
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = sva.signer_key_id
     AND validator_key.principal_id = sva.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    JOIN artifact_manifests validation_evidence
      ON validation_evidence.digest = sva.evidence_manifest_digest
    JOIN current_valid_keys validation_evidence_key
      ON validation_evidence_key.key_id = validation_evidence.signer_key_id
     AND validation_evidence_key.key_purpose = 'artifact_broker'
    JOIN runtime_sessions rs
      ON rs.id = asb.runtime_session_id
     AND rs.executor_id = a.executor_id
     AND rs.executor_slot_id = a.executor_slot_id
     AND rs.worker_instance_id = NEW.worker_instance_id
     AND rs.process_identity = dr.process_identity
     AND rs.runtime = a.runtime
     AND rs.actual_model = a.model
     AND rs.actual_model_family = a.model_family
     AND rs.actual_profile = a.profile
     AND rs.state IN ('running','terminating','terminated')
    JOIN artifact_manifests am
      ON am.digest = NEW.output_manifest_digest
    JOIN signing_keys amk
      ON amk.key_id = am.signer_key_id
     AND amk.state = 'active'
     AND (amk.expires_at_ms IS NULL OR amk.expires_at_ms >= NEW.received_at_ms)
    JOIN artifact_instances ai
      ON ai.manifest_digest = am.digest
     AND ai.project_id = a.project_id
     AND ai.run_id = a.run_id
     AND ai.node_version_id = a.node_version_id
     AND ai.producer_attempt_id = a.id
    WHERE a.id = NEW.attempt_id
      AND a.dispatch_key = NEW.dispatch_key
      AND a.executor_id = NEW.executor_id
      AND a.fence = NEW.fence
      AND a.leader_term = NEW.leader_term
      AND a.project_slot_generation = NEW.project_slot_generation
      AND a.input_manifest_digest = NEW.input_manifest_digest
      AND asb.unbound_at_ms IS NULL
      AND a.state IN ('result_pending','unknown')
      AND nv.current_attempt_id = a.id
      AND nv.state = 'dispatched'
      AND nsk.state = 'active'
      AND (nsk.expires_at_ms IS NULL OR nsk.expires_at_ms >= NEW.received_at_ms)
      AND rpsk.state = 'active'
      AND (rpsk.expires_at_ms IS NULL OR rpsk.expires_at_ms >= NEW.received_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi
        WHERE pi.policy_digest IN (nv.policy_digest, r.pipeline_policy_digest)
      )
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest IN (
          nv.output_schema_digest, sva.validator_closure_digest
        )
      )
      AND l.executor_slot_id = a.executor_slot_id
      AND l.worker_instance_id = NEW.worker_instance_id
      AND l.fence = a.fence
      AND l.leader_term = a.leader_term
      AND l.state = 'active'
      AND NEW.received_at_ms <= l.expires_at_ms
      AND es.fence_counter = a.fence
      AND ps.project_id = a.project_id
      AND ps.generation = a.project_slot_generation
      AND lt.state = 'active'
      AND cs.current_term = a.leader_term
      AND cs.kill_switch = 0
      AND (
        e.fresh_session_required = 0
        OR (rs.session_scope = 'attempt' AND rs.fresh_context = 1)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM charge_subjects cs_cost
        JOIN budget_reservations br_cost ON br_cost.charge_subject_id = cs_cost.id
        WHERE cs_cost.attempt_id = a.id
          AND br_cost.state IN ('held','partially_consumed')
      )
  );
END;

CREATE TRIGGER benchmark_evaluator_result_acceptance_requires_private_output_binding
BEFORE UPDATE OF state ON result_envelopes
WHEN OLD.state = 'prevalidated' AND NEW.state = 'accepted'
 AND EXISTS (
   SELECT 1 FROM benchmark_evaluator_inputs input
   WHERE input.evaluator_attempt_id = NEW.attempt_id
 )
BEGIN
  SELECT RAISE(ABORT, 'benchmark evaluator result lacks its signed private output binding and monotonic taint')
  WHERE NOT EXISTS (
    SELECT 1
    FROM benchmark_evaluator_output_bindings binding
    JOIN artifact_instance_taints taint
      ON taint.artifact_instance_id = binding.output_artifact_instance_id
     AND taint.blob_digest = binding.output_blob_digest
     AND taint.preregistration_digest = binding.preregistration_digest
     AND taint.task_id = binding.task_id
     AND taint.arm = binding.arm
     AND taint.source_artifact_instance_id = binding.output_artifact_instance_id
     AND taint.source_input_artifact_instance_id = binding.source_normalized_artifact_instance_id
     AND taint.reason = 'benchmark_evaluator_output'
    WHERE binding.result_envelope_id = NEW.id
      AND binding.evaluator_attempt_id = NEW.attempt_id
      AND binding.output_manifest_digest = NEW.output_manifest_digest
  );
END;

CREATE TRIGGER schema_validation_attestation_matches_result_and_trusted_validator
BEFORE INSERT ON schema_validation_attestations
BEGIN
  SELECT RAISE(ABORT, 'schema validation attestation does not match result/schema or trusted validator')
  WHERE json_extract(NEW.canonical_json, '$.result_envelope_id') IS NOT NEW.result_envelope_id
     OR json_extract(NEW.canonical_json, '$.output_manifest_digest') IS NOT NEW.output_manifest_digest
     OR json_extract(NEW.canonical_json, '$.output_schema_digest') IS NOT NEW.output_schema_digest
     OR json_extract(NEW.canonical_json, '$.validator_closure_digest') IS NOT NEW.validator_closure_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1
       FROM result_envelopes re
       JOIN attempts a ON a.id = re.attempt_id
       JOIN node_versions nv ON nv.id = a.node_version_id
       JOIN configuration_artifacts schema_artifact ON schema_artifact.digest = nv.output_schema_digest
       JOIN configuration_artifacts validator ON validator.digest = NEW.validator_closure_digest
       JOIN principals p ON p.id = NEW.signer_principal_id
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'schema_validator'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       JOIN principal_global_roles pgr
         ON pgr.principal_id = p.id
        AND pgr.role = 'operator'
        AND pgr.revoked_at_ms IS NULL
       WHERE re.id = NEW.result_envelope_id
         AND re.output_manifest_digest = NEW.output_manifest_digest
         AND nv.output_schema_digest = NEW.output_schema_digest
         AND schema_artifact.artifact_kind = 'output_schema'
         AND validator.artifact_kind = 'toolchain_closure'
         AND p.kind = 'service'
         AND p.state = 'active'
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest IN (schema_artifact.digest, validator.digest)
         )
     );
END;

CREATE TRIGGER schema_validation_attestations_no_update
BEFORE UPDATE ON schema_validation_attestations
BEGIN SELECT RAISE(ABORT, 'schema validation attestations are immutable'); END;

CREATE TRIGGER schema_validation_attestations_no_delete
BEFORE DELETE ON schema_validation_attestations
BEGIN SELECT RAISE(ABORT, 'schema validation attestations are immutable'); END;

CREATE TRIGGER attempt_acceptance_requires_accepted_result
BEFORE UPDATE OF state ON attempts
WHEN NEW.state = 'accepted' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'attempt acceptance requires an accepted result envelope')
  WHERE NOT EXISTS (
    SELECT 1 FROM result_envelopes
    WHERE attempt_id = NEW.id AND state = 'accepted'
  );
END;

CREATE TRIGGER merge_requests_legal_state_transition
BEFORE UPDATE OF state ON merge_requests
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal merge-request state transition')
  WHERE NOT (
    (OLD.state = 'queued' AND NEW.state IN ('leased','cancelled'))
    OR (OLD.state = 'leased' AND NEW.state IN ('integrating','cancelled'))
    OR (OLD.state = 'integrating' AND NEW.state IN ('succeeded','failed','unknown'))
    OR (OLD.state = 'unknown' AND NEW.state IN ('succeeded','failed','integrating'))
  );
END;

CREATE TRIGGER merge_claim_matches_target_fence
BEFORE UPDATE OF state ON merge_requests
WHEN OLD.state = 'queued' AND NEW.state = 'leased'
BEGIN
  SELECT RAISE(ABORT, 'merge claim requires token, deadline, and current target fence')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.claim_until_ms > (unixepoch('subsec') * 1000) + 30000
     OR NEW.claim_leader_term IS NULL
     OR NEW.target_fence IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM control_state ctl
       JOIN leader_terms lt ON lt.term = ctl.current_term AND lt.state = 'active'
       WHERE ctl.singleton = 1
         AND ctl.current_term = NEW.claim_leader_term
         AND ctl.admission_mode = 'open'
         AND ctl.kill_switch = 0
     )
     OR NOT EXISTS (
       SELECT 1 FROM integration_targets t
       WHERE t.id = NEW.integration_target_id
         AND t.repository_id = NEW.repository_id
         AND t.state = 'leased'
         AND t.fence_counter = NEW.target_fence
     );
END;

CREATE TRIGGER merge_integration_requires_live_claim
BEFORE UPDATE OF state ON merge_requests
WHEN OLD.state = 'leased' AND NEW.state = 'integrating'
BEGIN
  SELECT RAISE(ABORT, 'merge integration requires unexpired claim and integrating target')
  WHERE NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1 FROM control_state ctl
       JOIN leader_terms lt ON lt.term = ctl.current_term AND lt.state = 'active'
       WHERE ctl.singleton = 1
         AND ctl.current_term = NEW.claim_leader_term
         AND ctl.admission_mode = 'open'
         AND ctl.kill_switch = 0
     )
     OR NOT EXISTS (
       SELECT 1 FROM integration_targets t
       WHERE t.id = NEW.integration_target_id
         AND t.state = 'integrating'
         AND t.fence_counter = NEW.target_fence
     );
END;

CREATE TRIGGER merge_success_requires_commit
BEFORE UPDATE OF state ON merge_requests
WHEN NEW.state IN ('succeeded','failed','unknown') AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'merge outcome requires exact latest attempt and signed provider evidence')
  WHERE NEW.finished_at_ms IS NULL
     OR NEW.finished_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.terminal_provider_observation_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM merge_attempts attempt
       JOIN provider_operation_observations observation
         ON observation.id = attempt.provider_observation_id
        AND observation.id = NEW.terminal_provider_observation_id
        AND observation.subject_kind = 'merge_attempt'
        AND observation.subject_id = attempt.id
       WHERE attempt.merge_request_id = NEW.id
         AND attempt.state = CASE NEW.state
           WHEN 'succeeded' THEN 'succeeded'
           WHEN 'failed' THEN 'failed'
           ELSE 'unknown'
         END
         AND attempt.finished_at_ms <= NEW.finished_at_ms
         AND observation.provider = NEW.provider
         AND observation.provider_lookup_key = NEW.provider_idempotency_key
         AND observation.request_digest = NEW.request_digest
         AND observation.target_fence = NEW.target_fence
         AND (
           (NEW.state = 'succeeded' AND observation.observed_state = 'completed')
           OR (NEW.state = 'failed' AND observation.observed_state IN ('failed','cancelled','absent'))
           OR (NEW.state = 'unknown' AND observation.observed_state = 'unreachable')
         )
         AND NOT EXISTS (
           SELECT 1 FROM merge_attempts later
           WHERE later.merge_request_id = attempt.merge_request_id
             AND later.attempt_no > attempt.attempt_no
         )
     );

  SELECT RAISE(ABORT, 'successful merge requires exact provider commit and signed current target head')
  WHERE NEW.state = 'succeeded'
    AND (
      NEW.merged_commit IS NULL
      OR NEW.merged_commit <> NEW.candidate_commit
      OR NEW.terminal_head_observation_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM merge_attempts attempt
        JOIN provider_operation_observations provider_observation
          ON provider_observation.id = NEW.terminal_provider_observation_id
         AND provider_observation.id = attempt.provider_observation_id
         AND provider_observation.remote_commit = NEW.merged_commit
        JOIN target_head_observations head
          ON head.id = NEW.terminal_head_observation_id
         AND head.integration_target_id = NEW.integration_target_id
         AND head.target_fence = NEW.target_fence
         AND head.observed_commit = NEW.merged_commit
         AND head.provider = NEW.provider
        JOIN integration_targets target
          ON target.id = NEW.integration_target_id
         AND target.target_ref = head.target_ref
         AND target.fence_counter = NEW.target_fence
         AND target.state = 'integrating'
        WHERE attempt.merge_request_id = NEW.id
          AND attempt.state = 'succeeded'
          AND head.observed_at_ms >= provider_observation.observed_at_ms
          AND head.observed_at_ms <= NEW.finished_at_ms
          AND NOT EXISTS (
            SELECT 1 FROM target_head_observations later_head
            WHERE later_head.integration_target_id = head.integration_target_id
              AND later_head.target_fence = head.target_fence
              AND later_head.observed_at_ms > head.observed_at_ms
          )
      )
    );

  SELECT RAISE(ABORT, 'non-success merge cannot carry a commit or target-head proof')
  WHERE NEW.state IN ('failed','unknown')
    AND (NEW.merged_commit IS NOT NULL OR NEW.terminal_head_observation_id IS NOT NULL);
END;

CREATE TRIGGER merge_unknown_retry_requires_absence_and_new_fence
BEFORE UPDATE OF state ON merge_requests
WHEN OLD.state = 'unknown' AND NEW.state = 'integrating'
BEGIN
  SELECT RAISE(ABORT, 'unknown merge retry requires signed absence, a terminal prior attempt, and a new fenced claim')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_token = OLD.claim_token
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.claim_until_ms > (unixepoch('subsec') * 1000) + 30000
     OR NEW.claim_leader_term IS NULL
     OR NEW.target_fence IS NULL
     OR NEW.target_fence = OLD.target_fence
     OR NEW.merged_commit IS NOT NULL
     OR NEW.terminal_provider_observation_id IS NOT NULL
     OR NEW.terminal_head_observation_id IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NOT EXISTS (
       SELECT 1 FROM control_state ctl
       JOIN leader_terms lt ON lt.term = ctl.current_term AND lt.state = 'active'
       WHERE ctl.singleton = 1
         AND ctl.current_term = NEW.claim_leader_term
         AND ctl.admission_mode = 'open'
         AND ctl.kill_switch = 0
     )
     OR NOT EXISTS (
       SELECT 1 FROM reconciliation_decisions d
       WHERE d.subject_kind = 'merge_request'
         AND d.subject_id = NEW.id
         AND d.subject_generation = OLD.claim_token
         AND d.resolved_state = 'integrating'
         AND d.provider_lookup_key = NEW.provider_idempotency_key
         AND d.observed_provider_state = 'absent'
         AND d.observed_at_ms >= OLD.finished_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM reconciliation_decisions later
           WHERE later.subject_kind = d.subject_kind
             AND later.subject_id = d.subject_id
             AND later.decision_no > d.decision_no
         )
     )
     OR EXISTS (
       SELECT 1 FROM merge_attempts attempt
       WHERE attempt.merge_request_id = NEW.id
         AND attempt.state IN ('started','unknown')
     )
     OR NOT EXISTS (
       SELECT 1
       FROM merge_attempts attempt
       JOIN provider_operation_observations observation
         ON observation.id = attempt.provider_observation_id
       WHERE attempt.merge_request_id = NEW.id
         AND attempt.state = 'failed'
         AND observation.observed_state = 'absent'
         AND NOT EXISTS (
           SELECT 1 FROM merge_attempts later
           WHERE later.merge_request_id = attempt.merge_request_id
             AND later.attempt_no > attempt.attempt_no
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM integration_targets target
       WHERE target.id = NEW.integration_target_id
         AND target.state = 'integrating'
         AND target.fence_counter = NEW.target_fence
     );
END;

CREATE TRIGGER merge_claim_identity_is_set_once
BEFORE UPDATE OF claim_token, claim_leader_term, target_fence ON merge_requests
WHEN (OLD.claim_token IS NOT NULL AND OLD.claim_token IS NOT NEW.claim_token)
  OR (OLD.claim_leader_term IS NOT NULL AND OLD.claim_leader_term IS NOT NEW.claim_leader_term)
  OR (OLD.target_fence IS NOT NULL AND OLD.target_fence IS NOT NEW.target_fence)
BEGIN
  SELECT RAISE(ABORT, 'merge claim identity changes only on reconciled unknown retry')
  WHERE NOT (OLD.state = 'unknown' AND NEW.state = 'integrating');
END;

CREATE TRIGGER merge_claim_deadline_is_monotonic
BEFORE UPDATE OF claim_until_ms ON merge_requests
WHEN OLD.claim_until_ms IS NOT NEW.claim_until_ms
BEGIN
  SELECT RAISE(ABORT, 'merge claim deadline changes only with initial claim or reconciled retry')
  WHERE NOT (
    (OLD.state = 'queued' AND NEW.state = 'leased')
    OR (OLD.state = 'unknown' AND NEW.state = 'integrating')
  );
END;

CREATE TRIGGER merge_terminal_fields_freeze
BEFORE UPDATE OF merged_commit, terminal_provider_observation_id,
  terminal_head_observation_id, finished_at_ms
ON merge_requests
WHEN OLD.merged_commit IS NOT NEW.merged_commit
  OR OLD.terminal_provider_observation_id IS NOT NEW.terminal_provider_observation_id
  OR OLD.terminal_head_observation_id IS NOT NEW.terminal_head_observation_id
  OR OLD.finished_at_ms IS NOT NEW.finished_at_ms
BEGIN
  SELECT RAISE(ABORT, 'merge terminal fields are set only with first outcome transition')
  WHERE NOT (
    (OLD.state = 'integrating'
      AND NEW.state IN ('succeeded','failed','unknown')
      AND OLD.merged_commit IS NULL
      AND OLD.terminal_provider_observation_id IS NULL
      AND OLD.terminal_head_observation_id IS NULL
      AND OLD.finished_at_ms IS NULL)
    OR (OLD.state = 'unknown' AND NEW.state IN ('succeeded','failed'))
    OR (OLD.state = 'unknown' AND NEW.state = 'integrating'
      AND NEW.merged_commit IS NULL
      AND NEW.terminal_provider_observation_id IS NULL
      AND NEW.terminal_head_observation_id IS NULL
      AND NEW.finished_at_ms IS NULL)
  );
END;

CREATE TRIGGER external_effects_legal_state_transition
BEFORE UPDATE OF state ON external_effects
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'illegal external-effect state transition')
  WHERE NOT (
    (OLD.state = 'prepared' AND NEW.state IN ('executing','cancelled'))
    OR (OLD.state = 'executing' AND NEW.state IN ('succeeded','failed','unknown'))
    OR (OLD.state = 'unknown'
        AND NEW.state IN ('executing','succeeded','failed','manual_reconcile'))
  );
END;

CREATE TRIGGER external_effect_execution_requires_claim
BEFORE UPDATE OF state ON external_effects
WHEN NEW.state = 'executing' AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'external-effect execution requires a claim token, deadline, and execution time')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_leader_term IS NULL
     OR NEW.execution_started_at_ms IS NULL
     OR NEW.execution_head_observation_id IS NULL
     OR NEW.execution_started_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.execution_started_at_ms > NEW.claim_until_ms
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.claim_until_ms > (unixepoch('subsec') * 1000) + 30000
     OR NOT EXISTS (
       SELECT 1 FROM control_state ctl
       JOIN leader_terms lt ON lt.term = ctl.current_term AND lt.state = 'active'
       WHERE ctl.singleton = 1
         AND ctl.current_term = NEW.claim_leader_term
         AND ctl.admission_mode = 'open'
         AND ctl.dispatch_enabled = 1
         AND ctl.kill_switch = 0
     );

  SELECT RAISE(ABORT, 'gate or policy became invalid before execution')
  WHERE NOT EXISTS (
    SELECT 1
    FROM gate_bundles g
    JOIN merge_requests mr ON mr.id = g.merge_request_id
    JOIN integration_targets it ON it.id = mr.integration_target_id
    JOIN signing_keys gk ON gk.key_id = g.signer_key_id
    JOIN policies gp ON gp.digest = g.policy_digest
    JOIN signing_keys gpk ON gpk.key_id = gp.signer_key_id
    WHERE g.digest = NEW.gate_bundle_digest
      AND g.project_id = NEW.project_id
      AND g.run_id = NEW.run_id
      AND mr.state = 'succeeded'
      AND mr.merged_commit = g.candidate_commit
      AND mr.terminal_provider_observation_id IS NOT NULL
      AND mr.terminal_head_observation_id IS NOT NULL
      AND mr.target_fence = g.target_fence
      AND it.fence_counter = g.target_fence
      AND it.target_ref = g.target_ref
      AND gk.state = 'active'
      AND (gk.expires_at_ms IS NULL OR gk.expires_at_ms >= NEW.execution_started_at_ms)
      AND gpk.state = 'active'
      AND (gpk.expires_at_ms IS NULL OR gpk.expires_at_ms >= NEW.execution_started_at_ms)
      AND NOT EXISTS (
        SELECT 1 FROM gate_invalidations gi WHERE gi.gate_bundle_digest = g.digest
      )
      AND NOT EXISTS (
        SELECT 1 FROM policy_invalidations pi WHERE pi.policy_digest = g.policy_digest
      )
  );

  SELECT RAISE(ABORT, 'remote target head is stale or no longer equals the gated candidate')
  WHERE NOT EXISTS (
    SELECT 1
    FROM gate_bundles g
    JOIN merge_requests mr ON mr.id = g.merge_request_id
    JOIN target_head_observations o
      ON o.id = NEW.execution_head_observation_id
     AND o.integration_target_id = mr.integration_target_id
     AND o.target_fence = g.target_fence
     AND o.target_ref = g.target_ref
     AND o.observed_commit = g.candidate_commit
     AND o.provider = mr.provider
    JOIN signing_keys sk ON sk.key_id = o.signer_key_id
    WHERE g.digest = NEW.gate_bundle_digest
      AND o.observed_at_ms <= NEW.execution_started_at_ms
      AND o.observed_at_ms >= NEW.execution_started_at_ms - 60000
      AND sk.state = 'active'
      AND (sk.expires_at_ms IS NULL OR sk.expires_at_ms >= NEW.execution_started_at_ms)
  );

  SELECT RAISE(ABORT, 'gate attestation or evidence signer became invalid before execution')
  WHERE (
    SELECT COUNT(*)
    FROM gate_bundles g
    JOIN attestations a
      ON a.id IN (g.verification_attestation_id,g.security_attestation_id,
                  g.final_review_attestation_id)
    JOIN signing_keys ak ON ak.key_id = a.signer_key_id
    JOIN artifact_manifests am ON am.digest = a.evidence_manifest_digest
    JOIN signing_keys mk ON mk.key_id = am.signer_key_id
    WHERE g.digest = NEW.gate_bundle_digest
      AND ak.state = 'active'
      AND (ak.expires_at_ms IS NULL OR ak.expires_at_ms >= NEW.execution_started_at_ms)
      AND mk.state = 'active'
      AND (mk.expires_at_ms IS NULL OR mk.expires_at_ms >= NEW.execution_started_at_ms)
  ) <> 3;

  SELECT RAISE(ABORT, 'risk-acceptance signer became invalid before execution')
  WHERE EXISTS (
      SELECT 1 FROM gate_bundles g
      WHERE g.digest = NEW.gate_bundle_digest
        AND g.risk_acceptance_attestation_id IS NOT NULL
    )
    AND NOT EXISTS (
      SELECT 1
      FROM gate_bundles g
      JOIN attestations a ON a.id = g.risk_acceptance_attestation_id
      JOIN principals rp
        ON rp.id = a.reviewer_principal_id
       AND rp.state = 'active'
      JOIN principal_project_roles ppr
        ON ppr.principal_id = a.reviewer_principal_id
       AND ppr.project_id = NEW.project_id
       AND ppr.role = 'risk_acceptor'
       AND ppr.revoked_at_ms IS NULL
      JOIN signing_keys ak ON ak.key_id = a.signer_key_id
      JOIN artifact_manifests am ON am.digest = a.evidence_manifest_digest
      JOIN signing_keys mk ON mk.key_id = am.signer_key_id
      WHERE g.digest = NEW.gate_bundle_digest
        AND a.attestation_type = 'risk_acceptance'
        AND a.verdict = 'risk_accepted'
        AND a.candidate_commit = g.candidate_commit
        AND ak.state = 'active'
        AND (ak.expires_at_ms IS NULL OR ak.expires_at_ms >= NEW.execution_started_at_ms)
        AND mk.state = 'active'
        AND (mk.expires_at_ms IS NULL OR mk.expires_at_ms >= NEW.execution_started_at_ms)
    );

  SELECT RAISE(ABORT, 'release policy rule is missing or was changed before execution')
  WHERE NOT EXISTS (
    SELECT 1
    FROM gate_bundles g
    JOIN release_policy_effect_rules r
      ON r.policy_digest = g.policy_digest
     AND r.effect_type = NEW.effect_type
    WHERE g.digest = NEW.gate_bundle_digest
  );

  SELECT RAISE(ABORT, 'required approval is missing, expired, revoked, or unauthorized at execution')
  WHERE EXISTS (
      SELECT 1
      FROM gate_bundles g
      JOIN release_policy_effect_rules r
        ON r.policy_digest = g.policy_digest
       AND r.effect_type = NEW.effect_type
      WHERE g.digest = NEW.gate_bundle_digest
        AND r.human_approval_required = 1
    )
    AND NOT EXISTS (
      SELECT 1
      FROM approval_requests ar
      JOIN approval_decisions ad ON ad.request_id = ar.id AND ad.decision = 'approve'
      JOIN principals p ON p.id = ad.principal_id AND p.state = 'active'
      JOIN principal_project_roles ppr
        ON ppr.project_id = ar.project_id
       AND ppr.principal_id = ad.principal_id
       AND ppr.role = ar.required_role
       AND ppr.revoked_at_ms IS NULL
      JOIN signing_keys ak
        ON ak.key_id = ad.signer_key_id
       AND ak.principal_id = ad.signer_principal_id
       AND ak.state = 'active'
      JOIN gate_bundles g ON g.digest = NEW.gate_bundle_digest
      JOIN release_policy_effect_rules r
        ON r.policy_digest = g.policy_digest
       AND r.effect_type = NEW.effect_type
       AND r.human_approval_required = 1
      WHERE ar.id = NEW.approval_request_id
        AND ar.project_id = NEW.project_id
        AND ar.gate_bundle_digest = NEW.gate_bundle_digest
        AND ar.requested_action = NEW.effect_type
        AND ar.payload_digest = NEW.payload_digest
        AND ar.required_role = r.required_role
        AND NEW.execution_started_at_ms <= ar.expires_at_ms
        AND (ak.expires_at_ms IS NULL OR ak.expires_at_ms >= NEW.execution_started_at_ms)
        AND NOT EXISTS (
          SELECT 1 FROM approval_invalidations ai WHERE ai.request_id = ar.id
        )
    );
END;

CREATE TRIGGER external_effect_claim_identity_is_set_once
BEFORE UPDATE OF claim_token, claim_leader_term, execution_started_at_ms, execution_head_observation_id
ON external_effects
WHEN (OLD.claim_token IS NOT NULL AND OLD.claim_token IS NOT NEW.claim_token)
  OR (OLD.claim_leader_term IS NOT NULL AND OLD.claim_leader_term IS NOT NEW.claim_leader_term)
  OR (OLD.execution_started_at_ms IS NOT NULL
      AND OLD.execution_started_at_ms IS NOT NEW.execution_started_at_ms)
  OR (OLD.execution_head_observation_id IS NOT NULL
      AND OLD.execution_head_observation_id IS NOT NEW.execution_head_observation_id)
BEGIN
  SELECT RAISE(ABORT, 'external-effect claim identity changes only on reconciled unknown retry')
  WHERE NOT (OLD.state = 'unknown' AND NEW.state = 'executing');
END;

CREATE TRIGGER external_effect_claim_deadline_is_monotonic
BEFORE UPDATE OF claim_until_ms ON external_effects
WHEN OLD.claim_until_ms IS NOT NEW.claim_until_ms
BEGIN
  SELECT RAISE(ABORT, 'external-effect claim deadline changes only on initial claim or reconciled retry')
  WHERE NOT (
    (OLD.state = 'prepared' AND NEW.state = 'executing')
    OR (OLD.state = 'unknown' AND NEW.state = 'executing')
  );
END;

CREATE TRIGGER external_effect_outcome_requires_exact_attempt
BEFORE UPDATE OF state ON external_effects
WHEN NEW.state IN ('succeeded','failed','unknown') AND OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'external-effect outcome requires exact latest attempt and signed provider evidence')
  WHERE NEW.finished_at_ms IS NULL
     OR NEW.finished_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.terminal_provider_observation_id IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM external_effect_attempts attempt
       JOIN provider_operation_observations observation
         ON observation.id = attempt.provider_observation_id
        AND observation.id = NEW.terminal_provider_observation_id
        AND observation.subject_kind = 'external_effect_attempt'
        AND observation.subject_id = attempt.id
       JOIN gate_bundles gate ON gate.digest = NEW.gate_bundle_digest
       WHERE attempt.external_effect_id = NEW.id
         AND attempt.state = CASE NEW.state
           WHEN 'succeeded' THEN 'succeeded'
           WHEN 'failed' THEN 'failed'
           ELSE 'unknown'
         END
         AND attempt.finished_at_ms <= NEW.finished_at_ms
         AND observation.provider = NEW.provider
         AND observation.provider_lookup_key = NEW.remote_idempotency_key
         AND observation.request_digest = NEW.payload_digest
         AND observation.target_fence = gate.target_fence
         AND (
           (NEW.state = 'succeeded' AND observation.observed_state = 'completed')
           OR (NEW.state = 'failed' AND observation.observed_state IN ('failed','cancelled','absent'))
           OR (NEW.state = 'unknown' AND observation.observed_state = 'unreachable')
         )
         AND NOT EXISTS (
           SELECT 1 FROM external_effect_attempts later
           WHERE later.external_effect_id = attempt.external_effect_id
             AND later.attempt_no > attempt.attempt_no
         )
     );

  SELECT RAISE(ABORT, 'successful external effect requires exact provider remote identity')
  WHERE NEW.state = 'succeeded'
    AND (
      NEW.remote_object_id IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM provider_operation_observations observation
        WHERE observation.id = NEW.terminal_provider_observation_id
          AND observation.observed_state = 'completed'
          AND observation.remote_object_id = NEW.remote_object_id
      )
    );

  SELECT RAISE(ABORT, 'unknown effect cannot claim a known remote object')
  WHERE NEW.state = 'unknown' AND NEW.remote_object_id IS NOT NULL;
END;

CREATE TRIGGER external_effect_unknown_retry_requires_absence
BEFORE UPDATE OF state ON external_effects
WHEN OLD.state = 'unknown' AND NEW.state = 'executing'
BEGIN
  SELECT RAISE(ABORT, 'unknown external-effect retry requires exact absence and a fresh current-term claim')
  WHERE NEW.claim_token IS NULL
     OR NEW.claim_token = OLD.claim_token
     OR NEW.claim_until_ms IS NULL
     OR NEW.claim_until_ms <= (unixepoch('subsec') * 1000)
     OR NEW.claim_until_ms > (unixepoch('subsec') * 1000) + 30000
     OR NEW.claim_leader_term IS NULL
     OR NEW.execution_started_at_ms IS NULL
     OR NEW.execution_started_at_ms <= OLD.execution_started_at_ms
     OR NEW.execution_head_observation_id IS NULL
     OR NEW.execution_head_observation_id = OLD.execution_head_observation_id
     OR NEW.remote_object_id IS NOT NULL
     OR NEW.terminal_provider_observation_id IS NOT NULL
     OR NEW.finished_at_ms IS NOT NULL
     OR NEW.manual_reconcile_command_authorization_digest IS NOT NULL
     OR NOT EXISTS (
       SELECT 1 FROM reconciliation_decisions d
       WHERE d.subject_kind = 'external_effect'
         AND d.subject_id = NEW.id
         AND d.subject_generation = OLD.claim_token
         AND d.resolved_state = 'executing'
         AND d.provider_lookup_key = NEW.remote_idempotency_key
         AND d.observed_provider_state = 'absent'
         AND d.observed_process_state = 'not_applicable'
         AND d.observed_at_ms >= OLD.finished_at_ms
         AND d.subject_leader_term = OLD.claim_leader_term
         AND NOT EXISTS (
           SELECT 1 FROM reconciliation_decisions later
           WHERE later.subject_kind = d.subject_kind
             AND later.subject_id = d.subject_id
             AND later.decision_no > d.decision_no
         )
     )
     OR EXISTS (
       SELECT 1 FROM external_effect_attempts attempt
       WHERE attempt.external_effect_id = NEW.id
         AND attempt.state IN ('started','unknown','succeeded')
     );
END;

CREATE TRIGGER external_effect_manual_reconcile_requires_authenticated_command
BEFORE UPDATE OF state ON external_effects
WHEN OLD.state = 'unknown' AND NEW.state = 'manual_reconcile'
BEGIN
  SELECT RAISE(ABORT, 'manual reconciliation requires one exact authenticated operator command')
  WHERE NEW.manual_reconcile_command_authorization_digest IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM command_authorizations authorization
       JOIN commands command ON command.id = authorization.command_id
       WHERE authorization.digest = NEW.manual_reconcile_command_authorization_digest
         AND authorization.project_id = NEW.project_id
         AND authorization.command_type = 'effect.reconcile'
         AND authorization.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
         AND command.state = 'authorized'
         AND json_extract(command.payload_json, '$.external_effect_id') = NEW.id
         AND json_extract(command.payload_json, '$.action') = 'manual_reconcile'
     );
END;

CREATE TRIGGER external_effect_terminal_fields_freeze
BEFORE UPDATE OF remote_object_id, terminal_provider_observation_id,
  manual_reconcile_command_authorization_digest, finished_at_ms
ON external_effects
WHEN OLD.remote_object_id IS NOT NEW.remote_object_id
  OR OLD.terminal_provider_observation_id IS NOT NEW.terminal_provider_observation_id
  OR OLD.manual_reconcile_command_authorization_digest IS NOT NEW.manual_reconcile_command_authorization_digest
  OR OLD.finished_at_ms IS NOT NEW.finished_at_ms
BEGIN
  SELECT RAISE(ABORT, 'external-effect outcome fields change only with exact outcome, retry reset, or manual reconcile')
  WHERE NOT (
    (OLD.state = 'executing'
      AND NEW.state IN ('succeeded','failed','unknown')
      AND OLD.remote_object_id IS NULL
      AND OLD.terminal_provider_observation_id IS NULL
      AND OLD.finished_at_ms IS NULL)
    OR (OLD.state = 'unknown' AND NEW.state IN ('succeeded','failed'))
    OR (OLD.state = 'unknown' AND NEW.state = 'executing'
      AND NEW.remote_object_id IS NULL
      AND NEW.terminal_provider_observation_id IS NULL
      AND NEW.finished_at_ms IS NULL)
    OR (OLD.state = 'unknown' AND NEW.state = 'manual_reconcile'
      AND NEW.manual_reconcile_command_authorization_digest IS NOT NULL)
  );
END;

CREATE TRIGGER prevent_self_attestation
BEFORE INSERT ON attestation_subjects
BEGIN
  SELECT RAISE(ABORT, 'reviewer attempt cannot review itself')
  WHERE NEW.producer_attempt_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM attestations a
      WHERE a.id = NEW.attestation_id
        AND a.reviewer_attempt_id = NEW.producer_attempt_id
    );

  SELECT RAISE(ABORT, 'reviewer executor violates independence policy')
  WHERE NEW.producer_executor_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM attestations a
      WHERE a.id = NEW.attestation_id
        AND a.independence_policy IN ('different_executor','different_model_family')
        AND a.reviewer_executor_id = NEW.producer_executor_id
    );

  SELECT RAISE(ABORT, 'reviewer model family violates independence policy')
  WHERE NEW.producer_model_family IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM attestations a
      WHERE a.id = NEW.attestation_id
        AND a.independence_policy = 'different_model_family'
        AND a.reviewer_model_family = NEW.producer_model_family
    );
END;

CREATE TRIGGER validate_gate_bundle
BEFORE INSERT ON gate_bundles
BEGIN
  SELECT RAISE(ABORT, 'benchmark runs and artifacts are never release eligible')
  WHERE EXISTS (
    SELECT 1 FROM runs run
    WHERE run.id = NEW.run_id
      AND run.benchmark_preregistration_digest IS NOT NULL
  );

  SELECT RAISE(ABORT, 'gate bundle does not match a pre-egress integrating merge and accepted producer lineage')
  WHERE NOT EXISTS (
    SELECT 1
    FROM merge_requests mr
    JOIN integration_targets it ON it.id = mr.integration_target_id
    JOIN target_head_observations tho
      ON tho.id = NEW.target_head_observation_id
     AND tho.integration_target_id = it.id
    JOIN signing_keys thk ON thk.key_id = tho.signer_key_id
    JOIN node_versions nv ON nv.id = mr.node_version_id
    JOIN attempts producer ON producer.id = nv.accepted_attempt_id
    JOIN runs r ON r.id = mr.run_id
    WHERE mr.id = NEW.merge_request_id
      AND mr.state = 'integrating'
      AND mr.repository_id = NEW.repository_id
      AND mr.run_id = NEW.run_id
      AND mr.base_commit = NEW.base_commit
      AND mr.candidate_commit = NEW.candidate_commit
      AND mr.merged_commit IS NULL
      AND it.target_ref = NEW.target_ref
      AND mr.target_fence = NEW.target_fence
      AND it.fence_counter = NEW.target_fence
      AND tho.target_fence = NEW.target_fence
      AND tho.target_ref = NEW.target_ref
      AND tho.observed_commit = NEW.base_commit
      AND tho.observed_at_ms <= NEW.created_at_ms
      AND tho.observed_at_ms >= NEW.created_at_ms - 60000
      AND thk.state = 'active'
      AND (thk.expires_at_ms IS NULL OR thk.expires_at_ms >= NEW.created_at_ms)
      AND r.project_id = NEW.project_id
      AND producer.id = NEW.primary_producer_attempt_id
      AND producer.project_id = NEW.project_id
  );

  SELECT RAISE(ABORT, 'benchmark-tainted commit can never enter a release gate')
  WHERE EXISTS (
    SELECT 1 FROM workspace_commit_taints taint
    WHERE taint.repository_id = NEW.repository_id
      AND taint.commit_id = NEW.candidate_commit
  );

  SELECT RAISE(ABORT, 'release gate candidate lacks a current clean reachable-commit attestation')
  WHERE NOT EXISTS (
    SELECT 1
    FROM repository_taint_state taint_state
    JOIN commit_lineage_attestations lineage
      ON lineage.repository_id = taint_state.repository_id
     AND lineage.repository_taint_revision = taint_state.revision
     AND lineage.candidate_commit = NEW.candidate_commit
     AND lineage.verdict = 'clean'
    WHERE taint_state.repository_id = NEW.repository_id
  );

  SELECT RAISE(ABORT, 'gate references inactive attestation or evidence signer')
  WHERE (
    SELECT COUNT(*)
    FROM attestations a
    JOIN signing_keys ak
      ON ak.key_id = a.signer_key_id
     AND ak.state = 'active'
     AND (ak.expires_at_ms IS NULL OR ak.expires_at_ms >= NEW.created_at_ms)
    JOIN artifact_manifests am
      ON am.digest = a.evidence_manifest_digest
    JOIN signing_keys mk
      ON mk.key_id = am.signer_key_id
     AND mk.state = 'active'
     AND (mk.expires_at_ms IS NULL OR mk.expires_at_ms >= NEW.created_at_ms)
    WHERE a.id IN (
      NEW.verification_attestation_id,
      NEW.security_attestation_id,
      NEW.final_review_attestation_id
    )
  ) <> 3;

  SELECT RAISE(ABORT, 'risk acceptance signer is inactive')
  WHERE NEW.risk_acceptance_attestation_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM attestations r
      JOIN signing_keys rk
        ON rk.key_id = r.signer_key_id
       AND rk.state = 'active'
       AND (rk.expires_at_ms IS NULL OR rk.expires_at_ms >= NEW.created_at_ms)
      JOIN artifact_manifests rm
        ON rm.digest = r.evidence_manifest_digest
      JOIN signing_keys rmk
        ON rmk.key_id = rm.signer_key_id
       AND rmk.state = 'active'
       AND (rmk.expires_at_ms IS NULL OR rmk.expires_at_ms >= NEW.created_at_ms)
      WHERE r.id = NEW.risk_acceptance_attestation_id
    );

  SELECT RAISE(ABORT, 'missing passing verification attestation')
  WHERE NOT EXISTS (
    SELECT 1 FROM attestations
    WHERE id = NEW.verification_attestation_id
      AND attestation_type = 'verification'
      AND verdict = 'pass'
      AND candidate_commit = NEW.candidate_commit
      AND EXISTS (
        SELECT 1 FROM attestation_subjects s
        WHERE s.attestation_id = NEW.verification_attestation_id
          AND s.subject_kind = 'commit'
          AND s.subject_id = NEW.candidate_commit
      )
  );

  SELECT RAISE(ABORT, 'missing acceptable security disposition')
  WHERE NOT EXISTS (
    SELECT 1 FROM attestations s
    WHERE s.id = NEW.security_attestation_id
      AND s.attestation_type = 'security'
      AND s.candidate_commit = NEW.candidate_commit
      AND EXISTS (
        SELECT 1 FROM attestation_subjects ss
        WHERE ss.attestation_id = NEW.security_attestation_id
          AND ss.subject_kind = 'commit'
          AND ss.subject_id = NEW.candidate_commit
      )
      AND (
        s.verdict = 'pass'
        OR (
          NEW.risk_acceptance_attestation_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM attestations r
            JOIN principals rp
              ON rp.id = r.reviewer_principal_id
             AND rp.state = 'active'
            JOIN principal_project_roles ppr
              ON ppr.principal_id = r.reviewer_principal_id
             AND ppr.project_id = NEW.project_id
             AND ppr.role = 'risk_acceptor'
             AND ppr.revoked_at_ms IS NULL
            WHERE r.id = NEW.risk_acceptance_attestation_id
              AND r.attestation_type = 'risk_acceptance'
              AND r.verdict = 'risk_accepted'
              AND r.candidate_commit = NEW.candidate_commit
              AND EXISTS (
                SELECT 1 FROM attestation_subjects rs
                WHERE rs.attestation_id = NEW.risk_acceptance_attestation_id
                  AND rs.subject_kind = 'commit'
                  AND rs.subject_id = NEW.candidate_commit
              )
          )
        )
      )
  );

  SELECT RAISE(ABORT, 'missing accepting final review')
  WHERE NOT EXISTS (
    SELECT 1
    FROM attestations a
    JOIN attempts ra ON ra.id = a.reviewer_attempt_id
    JOIN executors re ON re.id = ra.executor_id
    JOIN principals reviewer_principal
      ON reviewer_principal.id = re.principal_id
     AND reviewer_principal.state = 'active'
    JOIN executor_capabilities ec
      ON ec.executor_id = re.id
     AND ec.capability = 'final-review-only'
     AND ec.scope = 'global'
    JOIN attempt_session_bindings rb ON rb.attempt_id = ra.id
    JOIN runtime_sessions rs ON rs.id = rb.runtime_session_id
    WHERE a.id = NEW.final_review_attestation_id
      AND re.id = 'o3'
      AND re.pool = 'opus'
      AND re.fresh_session_required = 1
      AND a.attestation_type = 'review'
      AND a.verdict = 'accept'
      AND a.candidate_commit = NEW.candidate_commit
      AND a.independence_policy = 'different_model_family'
      AND rs.fresh_context = 1
      AND rs.session_scope = 'attempt'
      AND EXISTS (
        SELECT 1 FROM attestation_subjects fs
        WHERE fs.attestation_id = NEW.final_review_attestation_id
          AND fs.subject_kind = 'commit'
          AND fs.subject_id = NEW.candidate_commit
          AND fs.producer_attempt_id = NEW.primary_producer_attempt_id
      )
  );
END;

CREATE TRIGGER validate_approval_decision
BEFORE INSERT ON approval_decisions
BEGIN
  SELECT RAISE(ABORT, 'unauthorized, expired, or invalid approval')
  WHERE NOT EXISTS (
    SELECT 1
    FROM approval_requests ar
    JOIN principals p ON p.id = NEW.principal_id AND p.state = 'active' AND p.kind = 'human'
    JOIN principal_project_roles ppr
      ON ppr.project_id = ar.project_id
     AND ppr.principal_id = NEW.principal_id
     AND ppr.role = ar.required_role
     AND ppr.revoked_at_ms IS NULL
    WHERE ar.id = NEW.request_id
      AND NEW.decided_at_ms <= ar.expires_at_ms
      AND NOT EXISTS (
        SELECT 1 FROM approval_invalidations ai
        WHERE ai.request_id = ar.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM gate_invalidations gi
        WHERE gi.gate_bundle_digest = ar.gate_bundle_digest
      )
  );
END;

CREATE TRIGGER signature_verification_receipt_is_exact_and_trusted
BEFORE INSERT ON signature_verification_receipts
BEGIN
  SELECT RAISE(ABORT, 'signature verification receipt is not exact, current, or trusted')
  WHERE NEW.record_signature = ''
     OR NEW.signature = ''
     OR NEW.verified_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.verified_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.record_kind') IS NOT NEW.record_kind
     OR json_extract(NEW.canonical_json, '$.record_id') IS NOT NEW.record_id
     OR json_extract(NEW.canonical_json, '$.record_canonical_json') IS NOT NEW.record_canonical_json
     OR json_extract(NEW.canonical_json, '$.record_signer_key_id') IS NOT NEW.record_signer_key_id
     OR json_extract(NEW.canonical_json, '$.record_signature') IS NOT NEW.record_signature
     OR json_extract(NEW.canonical_json, '$.validator_closure_digest') IS NOT NEW.validator_closure_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.canonical_encoding_verified') IS NOT NEW.canonical_encoding_verified
     OR json_extract(NEW.canonical_json, '$.duplicate_keys_rejected') IS NOT NEW.duplicate_keys_rejected
     OR json_extract(NEW.canonical_json, '$.referenced_digests_verified') IS NOT NEW.referenced_digests_verified
     OR json_extract(NEW.canonical_json, '$.payload_digest_verified') IS NOT NEW.payload_digest_verified
     OR json_extract(NEW.canonical_json, '$.verified_payload_digest') IS NOT NEW.verified_payload_digest
     OR json_extract(NEW.canonical_json, '$.record_digest_verified') IS NOT NEW.record_digest_verified
     OR json_extract(NEW.canonical_json, '$.verified_record_digest') IS NOT NEW.verified_record_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.verified_at_ms') IS NOT NEW.verified_at_ms
     OR (NEW.record_kind = 'command' AND (
          NEW.payload_digest_verified IS NOT 1
          OR NEW.verified_payload_digest IS NOT json_extract(NEW.record_canonical_json, '$.payload_digest')
        ))
     OR (NEW.record_kind = 'projection_change_batch' AND (
          NEW.payload_digest_verified IS NOT 1
          OR NEW.verified_payload_digest IS NOT json_extract(NEW.record_canonical_json, '$.projection_delta_digest')
          OR NEW.record_digest_verified IS NOT 1
          OR NEW.verified_record_digest IS NOT NEW.record_id
        ))
     OR (NEW.record_kind IN ('artifact_blob','artifact_manifest','work_packet') AND (
          NEW.record_digest_verified IS NOT 1
          OR NEW.verified_record_digest IS NOT NEW.record_id
        ))
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys record_key
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN configuration_artifacts validator
         ON validator.digest = NEW.validator_closure_digest
        AND validator.artifact_kind = 'toolchain_closure'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE record_key.key_id = NEW.record_signer_key_id
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = validator.digest
         )
     );
END;

