CREATE TRIGGER policies_require_active_signing_key
BEFORE INSERT ON policies
BEGIN
  SELECT RAISE(ABORT, 'policy requires an active control-plane service key')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.policy_type') IS NOT NEW.policy_type
     OR json_extract(NEW.canonical_json, '$.version') IS NOT NEW.version
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
    SELECT 1 FROM current_valid_keys sk
    JOIN principals p ON p.id = sk.principal_id
    WHERE sk.key_id = NEW.signer_key_id
      AND sk.principal_id = NEW.signer_principal_id
      AND sk.key_purpose = 'control_plane'
      AND p.kind = 'service'
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'policy'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms <= NEW.created_at_ms
      AND receipt.verified_at_ms >= NEW.created_at_ms - 5000
  );
END;

CREATE TRIGGER configuration_artifacts_require_root_owned_signed_manifest
BEFORE INSERT ON configuration_artifacts
BEGIN
  SELECT RAISE(ABORT, 'configuration artifact is not a signed root-owned content-addressed closure')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR instr(NEW.object_path, substr(NEW.object_digest, 8)) = 0
     OR length(NEW.object_digest) <> 71
     OR substr(NEW.object_digest, 1, 7) <> 'sha256:'
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.artifact_manifest_digest') IS NOT NEW.artifact_manifest_digest
     OR json_extract(NEW.canonical_json, '$.artifact_kind') IS NOT NEW.artifact_kind
     OR json_extract(NEW.canonical_json, '$.object_path') IS NOT NEW.object_path
     OR json_extract(NEW.canonical_json, '$.object_digest') IS NOT NEW.object_digest
     OR json_extract(NEW.canonical_json, '$.path_inventory_digest') IS NOT NEW.path_inventory_digest
     OR json_extract(NEW.canonical_json, '$.dependency_closure_digest') IS NOT NEW.dependency_closure_digest
     OR json_extract(NEW.canonical_json, '$.sbom_digest') IS NOT NEW.sbom_digest
     OR json_extract(NEW.canonical_json, '$.owner_uid') IS NOT NEW.owner_uid
     OR json_extract(NEW.canonical_json, '$.owner_gid') IS NOT NEW.owner_gid
     OR json_extract(NEW.canonical_json, '$.service_writable') IS NOT NEW.service_writable
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM artifact_manifests am
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.key_purpose = 'control_plane'
       JOIN current_valid_keys manifest_key
         ON manifest_key.key_id = am.signer_key_id
        AND manifest_key.key_purpose = 'artifact_broker'
       WHERE am.digest = NEW.artifact_manifest_digest
         AND instr(am.canonical_json, '/Users/') = 0
         AND json_extract(am.canonical_json, '$.configuration_digest') = NEW.digest
         AND json_extract(am.canonical_json, '$.object_digest') = NEW.object_digest
         AND json_extract(am.canonical_json, '$.path_inventory_digest') = NEW.path_inventory_digest
         AND json_extract(am.canonical_json, '$.dependency_closure_digest') = NEW.dependency_closure_digest
         AND json_extract(am.canonical_json, '$.sbom_digest') = NEW.sbom_digest
     )
     OR NOT (
       EXISTS (
         SELECT 1 FROM current_valid_signature_receipts receipt
         JOIN current_valid_keys validator_key
           ON validator_key.key_id = receipt.signer_key_id
          AND validator_key.principal_id = receipt.signer_principal_id
          AND validator_key.key_purpose = 'schema_validator'
         WHERE receipt.record_kind = 'configuration_artifact'
           AND receipt.record_id = NEW.digest
           AND receipt.record_canonical_json = NEW.canonical_json
           AND receipt.record_signer_key_id = NEW.signer_key_id
           AND receipt.record_signature = NEW.signature
           AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
       )
       OR (
         NEW.artifact_kind = 'toolchain_closure'
         AND json_extract(NEW.canonical_json, '$.bootstrap_validator') = 1
         AND EXISTS (
           SELECT 1 FROM installation_trust_root root
           WHERE root.singleton = 1
             AND json_extract(root.installer_manifest_json, '$.validator_closure_digest') = NEW.digest
             AND json_extract(root.installer_manifest_json, '$.validator_object_digest') = NEW.object_digest
             AND json_extract(root.installer_manifest_json, '$.validator_signer_key_id') = NEW.signer_key_id
             AND json_extract(root.installer_manifest_json, '$.validator_signature') = NEW.signature
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifacts WHERE artifact_kind = 'toolchain_closure'
         )
       )
     );
END;

