CREATE TRIGGER configuration_artifact_invalidation_requires_detached_dependents
BEFORE INSERT ON configuration_artifact_invalidations
BEGIN
  SELECT RAISE(ABORT, 'configuration invalidation requires active principal and every dependent authority detached first')
  WHERE NOT EXISTS (
      SELECT 1 FROM authority_change_authorizations a
      JOIN control_state ctl ON ctl.current_term = a.leader_term
      JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
      WHERE a.id = NEW.authorization_id
        AND a.target_kind = 'configuration'
        AND a.target_id = NEW.configuration_digest
        AND a.replacement_target_id IS NEW.replacement_configuration_digest
        AND a.actor_principal_id = NEW.invalidated_by_principal_id
        AND a.action = CASE WHEN NEW.replacement_configuration_digest IS NULL
                            THEN 'revoke' ELSE 'supersede' END
        AND a.expires_at_ms >= NEW.invalidated_at_ms
    )
    OR NOT EXISTS (
      SELECT 1 FROM principals p
      WHERE p.id = NEW.invalidated_by_principal_id AND p.state = 'active'
    )
    OR EXISTS (
      SELECT 1 FROM control_state ctl
      JOIN bootstrap_manifests bm ON bm.digest = ctl.bootstrap_manifest_digest
      WHERE ctl.dispatch_enabled = 1
         OR NEW.configuration_digest IN (
           bm.control_plane_closure_digest, bm.cli_runtime_closure_digest,
           bm.sandbox_runtime_closure_digest, bm.scanner_profile_digest
         )
    )
    OR EXISTS (
      SELECT 1 FROM runtime_catalogs rc
      WHERE NEW.configuration_digest IN (
          rc.binary_artifact_digest, rc.settings_digest, rc.environment_allowlist_digest,
          rc.provider_proxy_profile_digest, rc.io_protocol_digest,
          rc.system_prompt_digest, rc.toolchain_closure_digest,
          rc.probe_contract_digest
        )
        AND NOT EXISTS (
          SELECT 1 FROM runtime_catalog_invalidations rci
          WHERE rci.runtime_catalog_digest = rc.digest
        )
    )
    OR EXISTS (
      SELECT 1 FROM executors e
      WHERE e.config_digest = NEW.configuration_digest
        AND e.state <> 'offline'
    )
    OR EXISTS (
      SELECT 1 FROM managed_service_identities msi
      WHERE NEW.configuration_digest IN (msi.config_digest, msi.sanitization_rules_digest)
        AND NOT EXISTS (
          SELECT 1 FROM managed_service_identity_invalidations mii
          WHERE mii.managed_identity_digest = msi.digest
        )
    );
END;

