CREATE TRIGGER runtime_catalogs_require_active_signing_key
BEFORE INSERT ON runtime_catalogs
BEGIN
  SELECT RAISE(ABORT, 'runtime catalog requires active signer, immutable contracts, and root-owned binary')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
  OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
  OR NEW.effective_at_ms > NEW.created_at_ms + 300000
  OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
  OR json_extract(NEW.canonical_json, '$.version') IS NOT NEW.version
  OR json_extract(NEW.canonical_json, '$.runtime') IS NOT NEW.runtime
  OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
  OR json_extract(NEW.canonical_json, '$.requested_model') IS NOT NEW.requested_model
  OR json_extract(NEW.canonical_json, '$.requested_profile') IS NOT NEW.requested_profile
  OR json_extract(NEW.canonical_json, '$.resolved_model') IS NOT NEW.resolved_model
  OR json_extract(NEW.canonical_json, '$.resolved_model_family') IS NOT NEW.resolved_model_family
  OR json_extract(NEW.canonical_json, '$.resolved_effort') IS NOT NEW.resolved_effort
  OR json_extract(NEW.canonical_json, '$.binary_path') IS NOT NEW.binary_path
  OR json_extract(NEW.canonical_json, '$.binary_digest') IS NOT NEW.binary_digest
  OR json_extract(NEW.canonical_json, '$.binary_artifact_digest') IS NOT NEW.binary_artifact_digest
  OR json_extract(NEW.canonical_json, '$.settings_digest') IS NOT NEW.settings_digest
  OR json_extract(NEW.canonical_json, '$.environment_allowlist_digest') IS NOT NEW.environment_allowlist_digest
  OR json_extract(NEW.canonical_json, '$.provider_proxy_profile_digest') IS NOT NEW.provider_proxy_profile_digest
  OR json_extract(NEW.canonical_json, '$.io_protocol_digest') IS NOT NEW.io_protocol_digest
  OR json_extract(NEW.canonical_json, '$.system_prompt_digest') IS NOT NEW.system_prompt_digest
  OR json_extract(NEW.canonical_json, '$.toolchain_closure_digest') IS NOT NEW.toolchain_closure_digest
  OR json_extract(NEW.canonical_json, '$.permission_mode') IS NOT NEW.permission_mode
  OR json_extract(NEW.canonical_json, '$.service_uid') IS NOT NEW.service_uid
  OR json_extract(NEW.canonical_json, '$.probe_contract_digest') IS NOT NEW.probe_contract_digest
  OR json(NEW.argv_json) <> json(json_extract(NEW.canonical_json, '$.argv'))
  OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
  OR json_extract(NEW.canonical_json, '$.effective_at_ms') IS NOT NEW.effective_at_ms
  OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_keys sk
    JOIN principals p ON p.id = sk.principal_id
    WHERE sk.key_id = NEW.signer_key_id
      AND sk.key_purpose = 'control_plane'
      AND p.kind = 'service'
  )
  OR NEW.binary_path NOT LIKE '/usr/local/libexec/cortex-harness/objects/sha256/%'
  OR instr(NEW.binary_path, substr(NEW.binary_digest, 8)) = 0
  OR instr(NEW.binary_path, '..') <> 0
  OR instr(NEW.argv_json, 'dangerously-skip-permissions') <> 0
  OR instr(NEW.argv_json, '--continue') <> 0
  OR instr(NEW.canonical_json, '/Users/') <> 0
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'runtime_catalog'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  )
  OR NOT EXISTS (
    SELECT 1
    FROM configuration_artifacts binary
    JOIN configuration_artifacts settings ON settings.digest = NEW.settings_digest
    JOIN configuration_artifacts env ON env.digest = NEW.environment_allowlist_digest
    JOIN configuration_artifacts proxy ON proxy.digest = NEW.provider_proxy_profile_digest
    JOIN configuration_artifacts io ON io.digest = NEW.io_protocol_digest
    JOIN configuration_artifacts prompt ON prompt.digest = NEW.system_prompt_digest
    JOIN configuration_artifacts tools ON tools.digest = NEW.toolchain_closure_digest
    JOIN configuration_artifacts probe ON probe.digest = NEW.probe_contract_digest
    WHERE binary.digest = NEW.binary_artifact_digest
      AND binary.artifact_kind = 'runtime_binary'
      AND json_extract(binary.canonical_json, '$.executable_path') = NEW.binary_path
      AND json_extract(binary.canonical_json, '$.executable_digest') = NEW.binary_digest
      AND settings.artifact_kind = 'runtime_settings'
      AND env.artifact_kind = 'environment_allowlist'
      AND proxy.artifact_kind = 'provider_proxy_profile'
      AND io.artifact_kind = 'io_protocol'
      AND prompt.artifact_kind = 'system_prompt'
      AND tools.artifact_kind = 'toolchain_closure'
      AND probe.artifact_kind = 'runtime_probe_contract'
      AND NOT EXISTS (
        SELECT 1 FROM configuration_artifact_invalidations cai
        WHERE cai.configuration_digest IN (
          binary.digest, settings.digest, env.digest, proxy.digest, io.digest, prompt.digest,
          tools.digest, probe.digest
        )
      )
  );
END;

CREATE TRIGGER runtime_catalog_probe_attestation_matches_catalog
BEFORE INSERT ON runtime_catalog_probe_attestations
BEGIN
  SELECT RAISE(ABORT, 'runtime probe does not prove the exact catalog under the service identity')
  WHERE NEW.probed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.probed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR NOT EXISTS (
    SELECT 1
    FROM runtime_catalogs rc
    JOIN current_valid_keys sk
      ON sk.key_id = NEW.signer_key_id
     AND sk.key_purpose = 'runtime_supervisor'
    JOIN principals p ON p.id = sk.principal_id
    JOIN principal_global_roles pgr
      ON pgr.principal_id = p.id
     AND pgr.role = 'operator'
     AND pgr.revoked_at_ms IS NULL
    WHERE rc.digest = NEW.runtime_catalog_digest
      AND NEW.probe_contract_digest = rc.probe_contract_digest
      AND NEW.binary_digest = rc.binary_digest
      AND NEW.actual_model = rc.resolved_model
      AND NEW.actual_model_family = rc.resolved_model_family
      AND NEW.actual_effort = rc.resolved_effort
      AND json_extract(NEW.canonical_json, '$.runtime_catalog_digest') = NEW.runtime_catalog_digest
      AND json_extract(NEW.canonical_json, '$.probe_contract_digest') = NEW.probe_contract_digest
      AND json_extract(NEW.canonical_json, '$.executed_uid') = NEW.executed_uid
      AND json_extract(NEW.canonical_json, '$.clean_environment') = NEW.clean_environment
      AND json_extract(NEW.canonical_json, '$.parser_verified') = NEW.parser_verified
      AND json_extract(NEW.canonical_json, '$.authentication_verified') = NEW.authentication_verified
      AND json_extract(NEW.canonical_json, '$.proxy_scope_verified') = NEW.proxy_scope_verified
      AND json_extract(NEW.canonical_json, '$.io_round_trip_verified') = NEW.io_round_trip_verified
      AND json_extract(NEW.canonical_json, '$.binary_digest') = NEW.binary_digest
      AND json_extract(NEW.canonical_json, '$.actual_model') = NEW.actual_model
      AND json_extract(NEW.canonical_json, '$.actual_model_family') = NEW.actual_model_family
      AND json_extract(NEW.canonical_json, '$.actual_effort') = NEW.actual_effort
      AND json_extract(NEW.canonical_json, '$.evidence_manifest_digest') = NEW.evidence_manifest_digest
      AND json_extract(NEW.canonical_json, '$.signer_key_id') = NEW.signer_key_id
      AND json_extract(NEW.canonical_json, '$.probed_at_ms') = NEW.probed_at_ms
      AND p.kind = 'service'
      AND p.state = 'active'
      AND EXISTS (
        SELECT 1
        FROM artifact_manifests evidence
        JOIN current_valid_keys evidence_key ON evidence_key.key_id = evidence.signer_key_id
        WHERE evidence.digest = NEW.evidence_manifest_digest
          AND evidence_key.key_purpose = 'artifact_broker'
      )
      AND NOT EXISTS (
        SELECT 1 FROM runtime_catalog_invalidations rci
        WHERE rci.runtime_catalog_digest = rc.digest
      )
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'runtime_probe'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.probed_at_ms - 5000 AND NEW.probed_at_ms
  );
END;

