CREATE TRIGGER runtime_catalog_versions_are_contiguous
BEFORE INSERT ON runtime_catalogs
BEGIN
  SELECT RAISE(ABORT, 'runtime catalog version must be contiguous for logical mapping')
  WHERE NEW.version <> (
    SELECT COALESCE(MAX(version), 0) + 1
    FROM runtime_catalogs
    WHERE runtime = NEW.runtime
      AND requested_model = NEW.requested_model
      AND requested_profile = NEW.requested_profile
  );
END;

