BEFORE UPDATE ON runtime_catalog_invalidations
BEGIN SELECT RAISE(ABORT, 'runtime catalog invalidations are immutable'); END;

CREATE TRIGGER runtime_catalog_invalidation_is_authorized_rotation
BEFORE INSERT ON runtime_catalog_invalidations
BEGIN
  SELECT RAISE(ABORT, 'runtime catalog invalidation is not currently authorized')
  WHERE NOT EXISTS (
    SELECT 1 FROM authority_change_authorizations a
    JOIN control_state ctl ON ctl.current_term = a.leader_term
    JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
    WHERE a.id = NEW.authorization_id
      AND a.target_kind = 'runtime_catalog'
      AND a.target_id = NEW.runtime_catalog_digest
      AND a.replacement_target_id IS NEW.replacement_runtime_catalog_digest
      AND a.actor_principal_id = NEW.invalidated_by_principal_id
      AND a.action = CASE WHEN NEW.replacement_runtime_catalog_digest IS NULL
                          THEN 'revoke' ELSE 'supersede' END
      AND a.expires_at_ms >= NEW.invalidated_at_ms
  )
  OR NOT EXISTS (
    SELECT 1 FROM principals p
    WHERE p.id = NEW.invalidated_by_principal_id AND p.state = 'active'
  );

  SELECT RAISE(ABORT, 'replacement runtime catalog must be a newer equivalent logical mapping')
  WHERE NEW.replacement_runtime_catalog_digest IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM runtime_catalogs old
      JOIN runtime_catalogs next
        ON next.runtime = old.runtime
       AND next.requested_model = old.requested_model
       AND next.requested_profile = old.requested_profile
       AND next.version > old.version
      WHERE old.digest = NEW.runtime_catalog_digest
        AND next.digest = NEW.replacement_runtime_catalog_digest
    );
END;

CREATE TRIGGER runtime_catalog_invalidations_no_delete
BEFORE DELETE ON runtime_catalog_invalidations
BEGIN SELECT RAISE(ABORT, 'runtime catalog invalidations are immutable'); END;

CREATE TRIGGER bootstrap_manifests_require_active_signing_key
BEFORE INSERT ON bootstrap_manifests
BEGIN
  SELECT RAISE(ABORT, 'bootstrap manifest requires active signer and current schema')
  WHERE NEW.schema_version <> (SELECT MAX(schema_version) FROM schema_meta)
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.schema_version') IS NOT NEW.schema_version
     OR json_extract(NEW.canonical_json, '$.roster_digest') IS NOT NEW.roster_digest
     OR json_extract(NEW.canonical_json, '$.runtime_catalog_set_digest') IS NOT NEW.runtime_catalog_set_digest
     OR json_extract(NEW.canonical_json, '$.resource_policy_digest') IS NOT NEW.resource_policy_digest
     OR json_extract(NEW.canonical_json, '$.control_plane_closure_digest') IS NOT NEW.control_plane_closure_digest
     OR json_extract(NEW.canonical_json, '$.cli_runtime_closure_digest') IS NOT NEW.cli_runtime_closure_digest
     OR json_extract(NEW.canonical_json, '$.sandbox_runtime_closure_digest') IS NOT NEW.sandbox_runtime_closure_digest
     OR json_extract(NEW.canonical_json, '$.scanner_profile_digest') IS NOT NEW.scanner_profile_digest
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM schema_install_receipts install
       JOIN installation_trust_root root ON root.singleton = 1
       WHERE install.schema_version = NEW.schema_version
         AND json_extract(root.installer_manifest_json, '$.schema_install_receipt_digest') = install.digest
         AND json_extract(root.installer_manifest_json, '$.schema_install_migration_digest') = install.migration_digest
         AND json_extract(root.installer_manifest_json, '$.schema_install_installer_key_fingerprint') = install.installer_key_fingerprint
         AND json_extract(NEW.canonical_json, '$.schema_install_receipt_digest') = install.digest
         AND json_extract(NEW.canonical_json, '$.schema_install_migration_digest') = install.migration_digest
         AND json_extract(NEW.canonical_json, '$.installer_manifest_digest') = root.installer_manifest_digest
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys sk
       JOIN principals p ON p.id = sk.principal_id
       WHERE sk.key_id = NEW.signer_key_id
         AND sk.key_purpose = 'control_plane'
         AND p.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'bootstrap_manifest'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

