CREATE TRIGGER bootstrap_executor_binding_is_exact_signed_member
BEFORE INSERT ON bootstrap_executor_bindings
BEGIN
  SELECT RAISE(ABORT, 'bootstrap executor binding is not in the signed manifest')
  WHERE NOT EXISTS (
    SELECT 1
    FROM bootstrap_manifests manifest,
         json_each(manifest.canonical_json, '$.executors') member
    WHERE manifest.digest = NEW.bootstrap_manifest_digest
      AND json_extract(member.value, '$.executor_id') = NEW.executor_id
      AND json_extract(member.value, '$.principal_id') = NEW.principal_id
      AND json_extract(member.value, '$.pool') = NEW.pool
      AND json_extract(member.value, '$.runtime') = NEW.runtime
      AND json_extract(member.value, '$.requested_model') = NEW.requested_model
      AND json_extract(member.value, '$.requested_profile') = NEW.requested_profile
      AND json_extract(member.value, '$.runtime_catalog_digest') = NEW.runtime_catalog_digest
      AND json_extract(member.value, '$.model') = NEW.model
      AND json_extract(member.value, '$.model_family') = NEW.model_family
      AND json_extract(member.value, '$.profile') = NEW.profile
      AND json_extract(member.value, '$.host_id') = NEW.host_id
      AND json_extract(member.value, '$.config_digest') = NEW.config_digest
      AND json_extract(member.value, '$.sandbox_policy_digest') = NEW.sandbox_policy_digest
      AND json_extract(member.value, '$.fresh_session_required') = NEW.fresh_session_required
  );
END;

