CREATE TRIGGER pricing_catalogs_require_active_signing_key
BEFORE INSERT ON pricing_catalogs
BEGIN
  SELECT RAISE(ABORT, 'pricing catalog requires an active control-plane service key')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.model') IS NOT NEW.model
     OR json_extract(NEW.canonical_json, '$.input_rate_per_million') IS NOT NEW.input_rate_per_million
     OR json_extract(NEW.canonical_json, '$.output_rate_per_million') IS NOT NEW.output_rate_per_million
     OR json_extract(NEW.canonical_json, '$.cache_read_rate_per_million') IS NOT NEW.cache_read_rate_per_million
     OR json_extract(NEW.canonical_json, '$.cache_write_rate_per_million') IS NOT NEW.cache_write_rate_per_million
     OR json_extract(NEW.canonical_json, '$.tool_call_rate_per_million') IS NOT NEW.tool_call_rate_per_million
     OR json_extract(NEW.canonical_json, '$.millisecond_rate_per_million') IS NOT NEW.millisecond_rate_per_million
     OR json_extract(NEW.canonical_json, '$.effective_at_ms') IS NOT NEW.effective_at_ms
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
    SELECT 1 FROM current_valid_keys sk
    JOIN principals p ON p.id = sk.principal_id
    WHERE sk.key_id = NEW.signer_key_id
      AND sk.key_purpose = 'control_plane'
      AND p.kind = 'service'
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'pricing_catalog'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );

  SELECT RAISE(ABORT, 'pricing catalog must price at least one bounded unit')
  WHERE NEW.input_rate_per_million + NEW.output_rate_per_million
      + NEW.cache_read_rate_per_million + NEW.cache_write_rate_per_million
      + NEW.tool_call_rate_per_million + NEW.millisecond_rate_per_million = 0;
END;

CREATE TRIGGER pricing_catalog_invalidation_requires_active_principal
BEFORE INSERT ON pricing_catalog_invalidations
BEGIN
  SELECT RAISE(ABORT, 'pricing invalidation is not currently authorized')
  WHERE NOT EXISTS (
    SELECT 1 FROM authority_change_authorizations a
    JOIN control_state ctl ON ctl.current_term = a.leader_term
    JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
    WHERE a.id = NEW.authorization_id
      AND a.target_kind = 'pricing_catalog'
      AND a.target_id = NEW.pricing_catalog_digest
      AND a.replacement_target_id IS NULL
      AND a.actor_principal_id = NEW.invalidated_by_principal_id
      AND a.action IN ('invalidate','revoke')
      AND a.expires_at_ms >= NEW.invalidated_at_ms
  )
  OR NOT EXISTS (
    SELECT 1 FROM principals p
    WHERE p.id = NEW.invalidated_by_principal_id AND p.state = 'active'
  );
END;

