CREATE TRIGGER work_packets_require_active_signing_key
BEFORE INSERT ON work_packets
BEGIN
  SELECT RAISE(ABORT, 'work packet requires active signer and exact attempt lineage/schema/cost envelope')
  WHERE json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.attempt_id') IS NOT NEW.attempt_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
    SELECT 1
    FROM current_valid_keys sk
    JOIN attempts a ON a.id = NEW.attempt_id
    JOIN node_versions nv ON nv.id = a.node_version_id
    WHERE sk.key_id = NEW.signer_key_id
      AND sk.key_purpose = 'control_plane'
      AND NEW.lineage_digest = a.lineage_digest
      AND NEW.input_manifest_digest = a.input_manifest_digest
      AND NEW.output_schema_digest = nv.output_schema_digest
      AND NEW.pricing_catalog_digest = a.pricing_catalog_digest
      AND NEW.max_input_tokens = a.max_input_tokens
      AND NEW.max_output_tokens = a.max_output_tokens
      AND NEW.max_cache_read_tokens = a.max_cache_read_tokens
      AND NEW.max_cache_write_tokens = a.max_cache_write_tokens
      AND NEW.max_tool_calls = a.max_tool_calls
      AND NEW.max_wall_time_ms = a.max_wall_time_ms
      AND NEW.required_reservation_micro_usd = a.required_reservation_micro_usd
      AND json_extract(NEW.canonical_json, '$.lineage.lineage_digest') = NEW.lineage_digest
      AND json_extract(NEW.canonical_json, '$.lineage.input_manifest_digest') = NEW.input_manifest_digest
      AND json_extract(NEW.canonical_json, '$.lineage.output_schema_digest') = NEW.output_schema_digest
      AND json_extract(NEW.canonical_json, '$.cost_envelope.pricing_catalog_digest')
          = NEW.pricing_catalog_digest
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_input_tokens')
          = NEW.max_input_tokens
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_output_tokens')
          = NEW.max_output_tokens
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_cache_read_tokens')
          = NEW.max_cache_read_tokens
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_cache_write_tokens')
          = NEW.max_cache_write_tokens
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_tool_calls')
          = NEW.max_tool_calls
      AND json_extract(NEW.canonical_json, '$.cost_envelope.max_wall_time_ms')
          = NEW.max_wall_time_ms
      AND json_extract(NEW.canonical_json, '$.cost_envelope.required_reservation_micro_usd')
          = NEW.required_reservation_micro_usd
  )
  OR NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    WHERE receipt.record_kind = 'work_packet'
      AND receipt.record_id = NEW.digest
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.referenced_digests_verified = 1
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  )
  OR EXISTS (
    SELECT 1
    FROM attempts attempt
    JOIN runs run ON run.id = attempt.run_id
    WHERE attempt.id = NEW.attempt_id
      AND run.benchmark_preregistration_digest IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM benchmark_arm_runs arm
        JOIN benchmark_tasks task
          ON task.preregistration_digest = arm.preregistration_digest
         AND task.task_id = arm.task_id
        WHERE arm.preregistration_digest = run.benchmark_preregistration_digest
          AND arm.task_id = run.benchmark_task_id
          AND arm.arm = run.benchmark_arm
          AND json_extract(NEW.canonical_json, '$.benchmark.preregistration_digest')
              = arm.preregistration_digest
          AND json_extract(NEW.canonical_json, '$.benchmark.task_id') = arm.task_id
          AND json_extract(NEW.canonical_json, '$.benchmark.arm') = arm.arm
          AND json_extract(NEW.canonical_json, '$.benchmark.base_commit') = arm.base_commit
          AND json_extract(NEW.canonical_json, '$.benchmark.source_input_manifest_digest')
              = task.input_manifest_digest
          AND json_extract(NEW.canonical_json, '$.benchmark.prompt_digest') = arm.prompt_digest
          AND json_extract(NEW.canonical_json, '$.benchmark.toolchain_closure_digest')
              = arm.toolchain_closure_digest
          AND json_extract(NEW.canonical_json, '$.benchmark.inference_budget_digest')
              = arm.inference_budget_digest
          AND json_extract(NEW.canonical_json, '$.benchmark.isolation_namespace')
              = arm.isolation_namespace
      )
  );
END;

CREATE TRIGGER artifact_blobs_require_exact_broker_hash_receipt
BEFORE INSERT ON artifact_blobs
BEGIN
  SELECT RAISE(ABORT, 'artifact blob is not an exact content-addressed broker object')
  WHERE length(NEW.digest) <> 71
     OR substr(NEW.digest, 1, 7) <> 'sha256:'
     OR NEW.storage_ref NOT LIKE '/usr/local/var/cortex-harness/artifacts/objects/sha256/%'
     OR instr(NEW.storage_ref, '..') <> 0
     OR instr(NEW.storage_ref, substr(NEW.digest, 8)) = 0
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.size_bytes') IS NOT NEW.size_bytes
     OR json_extract(NEW.canonical_json, '$.media_type') IS NOT NEW.media_type
     OR json_extract(NEW.canonical_json, '$.storage_ref') IS NOT NEW.storage_ref
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys broker_key
       JOIN principals broker ON broker.id = broker_key.principal_id
       WHERE broker_key.key_id = NEW.signer_key_id
         AND broker_key.principal_id = NEW.signer_principal_id
         AND broker_key.key_purpose = 'artifact_broker'
         AND broker.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'artifact_blob'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER artifact_manifests_require_signer_key
BEFORE INSERT ON artifact_manifests
BEGIN
  SELECT RAISE(ABORT, 'manifest is not exact or artifact-broker signed')
  WHERE length(NEW.digest) <> 71
     OR substr(NEW.digest, 1, 7) <> 'sha256:'
     OR NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.schema_version') IS NOT NEW.schema_version
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys sk
       JOIN principals p ON p.id = sk.principal_id
       WHERE sk.key_id = NEW.signer_key_id
         AND sk.principal_id = NEW.signer_principal_id
         AND sk.key_purpose = 'artifact_broker'
         AND p.kind = 'service'
     )
     OR NOT (
       EXISTS (
         SELECT 1 FROM current_valid_signature_receipts receipt
         WHERE receipt.record_kind = CASE json_extract(NEW.canonical_json, '$.artifact_type')
           WHEN 'benchmark_evaluator_input' THEN 'benchmark_evaluator_input_manifest_v1'
           WHEN 'benchmark_execution_input' THEN 'benchmark_execution_input_manifest'
           ELSE 'artifact_manifest' END
           AND receipt.record_id = NEW.digest
           AND receipt.record_canonical_json = NEW.canonical_json
           AND receipt.record_signer_key_id = NEW.signer_key_id
           AND receipt.record_signature = NEW.signature
           AND receipt.referenced_digests_verified = 1
           AND receipt.record_digest_verified = 1
           AND receipt.verified_record_digest = NEW.digest
           AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
       )
       OR (
         NOT EXISTS (SELECT 1 FROM leader_terms)
         AND NOT EXISTS (SELECT 1 FROM control_state)
         AND EXISTS (
           SELECT 1
           FROM installation_trust_root root
           JOIN json_each(root.installer_manifest_json, '$.bootstrap_artifact_manifests') entry
           WHERE json_extract(entry.value, '$.digest') = NEW.digest
             AND json_extract(entry.value, '$.schema_version') = NEW.schema_version
             AND json_extract(entry.value, '$.canonical_json') = NEW.canonical_json
             AND json_extract(entry.value, '$.signer_principal_id') = NEW.signer_principal_id
             AND json_extract(entry.value, '$.signer_key_id') = NEW.signer_key_id
             AND json_extract(entry.value, '$.signature') = NEW.signature
             AND json_extract(entry.value, '$.created_at_ms') = NEW.created_at_ms
         )
       )
     );
END;

CREATE TRIGGER sanitization_attestation_requires_trusted_rules_and_signer
BEFORE INSERT ON sanitization_attestations
BEGIN
  SELECT RAISE(ABORT, 'sanitization attestation is not bound to trusted rules, service root, or signer')
  WHERE NEW.allowed_root NOT LIKE '/usr/local/var/cortex-harness/%'
     OR instr(NEW.allowed_root, '..') <> 0
     OR instr(NEW.canonical_json, '/Users/') <> 0
     OR json_extract(NEW.canonical_json, '$.subject_manifest_digest') IS NOT NEW.subject_manifest_digest
     OR json_extract(NEW.canonical_json, '$.rules_digest') IS NOT NEW.rules_digest
     OR json_extract(NEW.canonical_json, '$.allowed_root') IS NOT NEW.allowed_root
     OR json_extract(NEW.canonical_json, '$.realpath_contained') IS NOT NEW.realpath_contained
     OR json_extract(NEW.canonical_json, '$.no_symlinks') IS NOT NEW.no_symlinks
     OR json_extract(NEW.canonical_json, '$.no_hardlinks') IS NOT NEW.no_hardlinks
     OR json_extract(NEW.canonical_json, '$.no_special_files') IS NOT NEW.no_special_files
     OR json_extract(NEW.canonical_json, '$.forbidden_path_bytes_absent') IS NOT NEW.forbidden_path_bytes_absent
     OR json_extract(NEW.canonical_json, '$.secret_scan_passed') IS NOT NEW.secret_scan_passed
     OR json_extract(NEW.canonical_json, '$.file_count') IS NOT NEW.file_count
     OR json_extract(NEW.canonical_json, '$.total_bytes') IS NOT NEW.total_bytes
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM configuration_artifacts rules
       JOIN principals p ON p.id = NEW.signer_principal_id
       JOIN current_valid_keys sk
         ON sk.key_id = NEW.signer_key_id
        AND sk.principal_id = NEW.signer_principal_id
        AND sk.key_purpose = 'schema_validator'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       JOIN principal_global_roles pgr
         ON pgr.principal_id = p.id
        AND pgr.role = 'operator'
        AND pgr.revoked_at_ms IS NULL
       WHERE rules.digest = NEW.rules_digest
         AND rules.artifact_kind = 'sanitization_rules'
         AND p.kind = 'service'
         AND p.state = 'active'
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations cai
           WHERE cai.configuration_digest = rules.digest
         )
     );
END;

