CREATE TRIGGER artifact_instance_lineage_must_match_project
BEFORE INSERT ON artifact_instances
BEGIN
  SELECT RAISE(ABORT, 'artifact instance is not an exact signed broker binding')
  WHERE NOT EXISTS (
    SELECT 1
    FROM artifact_manifests am
    JOIN current_valid_keys k ON k.key_id = am.signer_key_id
    WHERE am.digest = NEW.manifest_digest
      AND k.key_purpose = 'artifact_broker'
      AND json_extract(am.canonical_json, '$.binding.project_id') IS NEW.project_id
      AND json_extract(am.canonical_json, '$.binding.run_id') IS NEW.run_id
      AND json_extract(am.canonical_json, '$.binding.node_version_id') IS NEW.node_version_id
      AND json_extract(am.canonical_json, '$.binding.producer_attempt_id') IS NEW.producer_attempt_id
      AND json_extract(am.canonical_json, '$.binding.artifact_type') IS NEW.artifact_type
      AND json_extract(am.canonical_json, '$.binding.logical_name') IS NEW.logical_name
      AND json_extract(am.canonical_json, '$.blob_digest') IS NEW.blob_digest
  );

  SELECT RAISE(ABORT, 'artifact run does not belong to artifact project')
  WHERE NEW.run_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM runs
      WHERE id = NEW.run_id AND project_id = NEW.project_id
    );

  SELECT RAISE(ABORT, 'artifact node does not belong to artifact project/run')
  WHERE NEW.node_version_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM node_versions nv
      JOIN logical_nodes ln ON ln.id = nv.logical_node_id
      WHERE nv.id = NEW.node_version_id
        AND ln.project_id = NEW.project_id
        AND (NEW.run_id IS NULL OR nv.run_id = NEW.run_id)
    );

  SELECT RAISE(ABORT, 'artifact producer does not belong to artifact lineage')
  WHERE NEW.producer_attempt_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM attempts a
      WHERE a.id = NEW.producer_attempt_id
        AND a.project_id = NEW.project_id
        AND (NEW.run_id IS NULL OR a.run_id = NEW.run_id)
        AND (NEW.node_version_id IS NULL OR a.node_version_id = NEW.node_version_id)
    );
END;

CREATE TRIGGER artifact_input_edges_stay_in_project
BEFORE INSERT ON artifact_inputs
BEGIN
  SELECT RAISE(ABORT, 'artifact provenance is sealed once its consumer becomes executable or terminal')
  WHERE EXISTS (
    SELECT 1
    FROM artifact_instances child
    LEFT JOIN node_versions node ON node.id = child.node_version_id
    LEFT JOIN attempts producer ON producer.id = child.producer_attempt_id
    WHERE child.id = NEW.artifact_instance_id
      AND (
        (child.artifact_type = 'node_input'
          AND (node.id IS NULL OR node.state <> 'pending'))
        OR (child.producer_attempt_id IS NOT NULL
          AND producer.state NOT IN ('created','dispatched','acked','running','result_pending'))
        OR EXISTS (
          SELECT 1 FROM run_completion_seals completion
          WHERE completion.final_artifact_instance_id = child.id
        )
        OR EXISTS (
          SELECT 1 FROM external_effects effect
          WHERE effect.payload_artifact_instance_id = child.id
        )
      )
  );

  SELECT RAISE(ABORT, 'artifact provenance edge crosses project boundary')
  WHERE NOT EXISTS (
    SELECT 1
    FROM artifact_instances child
    JOIN artifact_instances parent
      ON parent.id = NEW.input_artifact_instance_id
    WHERE child.id = NEW.artifact_instance_id
      AND child.project_id = parent.project_id
  );

  SELECT RAISE(ABORT, 'benchmark-tainted artifact provenance cannot cross an arm boundary')
  WHERE EXISTS (
      SELECT 1
      FROM artifact_instances parent
      JOIN artifact_instance_taints taint ON taint.artifact_instance_id = parent.id
      WHERE parent.id = NEW.input_artifact_instance_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM artifact_instances child
      JOIN runs child_run ON child_run.id = child.run_id
      JOIN artifact_instances parent ON parent.id = NEW.input_artifact_instance_id
      JOIN artifact_instance_taints taint ON taint.artifact_instance_id = parent.id
      WHERE child.id = NEW.artifact_instance_id
        AND child_run.benchmark_preregistration_digest = taint.preregistration_digest
        AND child_run.benchmark_task_id = taint.task_id
        AND child_run.benchmark_arm = taint.arm
    );

  SELECT RAISE(ABORT, 'node-input provenance is not an exact declared dependency or immutable seed')
  WHERE EXISTS (
      SELECT 1 FROM artifact_instances child
      WHERE child.id = NEW.artifact_instance_id
        AND child.artifact_type = 'node_input'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM artifact_instances child
      JOIN artifact_instances parent ON parent.id = NEW.input_artifact_instance_id
      WHERE child.id = NEW.artifact_instance_id
        AND (
          (NEW.relation = 'declared_dependency'
            AND parent.artifact_type = 'node_output'
            AND parent.producer_attempt_id IS NOT NULL
            AND EXISTS (
              SELECT 1 FROM resolved_dependency_winners dependency
              WHERE dependency.node_version_id = child.node_version_id
                AND dependency.accepted_parent_node_version_id = parent.node_version_id
                AND dependency.accepted_parent_attempt_id = parent.producer_attempt_id
                AND dependency.dependency_type IN ('artifact','review')
            ))
          OR (NEW.relation = 'task_seed'
            AND parent.artifact_type IN ('sanitized_assets','evidence')
            AND parent.node_version_id IS NULL
            AND parent.producer_attempt_id IS NULL
            AND NOT EXISTS (
              SELECT 1 FROM node_dependencies dependency
              WHERE dependency.node_version_id = child.node_version_id
            )
            AND EXISTS (
              SELECT 1
              FROM node_versions child_node
              JOIN runs child_run ON child_run.id = child_node.run_id
              WHERE child_node.id = child.node_version_id
                AND (
                  (child_run.benchmark_preregistration_digest IS NULL
                    AND EXISTS (
                      SELECT 1
                      FROM artifact_manifests plan,
                           json_each(plan.canonical_json, '$.plan.root_seed_manifest_digests') seed
                      WHERE plan.digest = child_run.plan_manifest_digest
                        AND seed.value = parent.manifest_digest
                    ))
                  OR (child_run.benchmark_preregistration_digest IS NOT NULL
                    AND EXISTS (
                      SELECT 1
                      FROM benchmark_tasks task
                      JOIN benchmark_task_sources source
                        ON source.manifest_digest = task.input_manifest_digest
                      WHERE task.preregistration_digest = child_run.benchmark_preregistration_digest
                        AND task.task_id = child_run.benchmark_task_id
                        AND source.blob_digest = parent.blob_digest
                        AND source.manifest_digest = parent.manifest_digest
                    ))
                )
            ))
        )
    );

  SELECT RAISE(ABORT, 'benchmark artifact provenance crosses arm execution')
  WHERE EXISTS (
    SELECT 1
    FROM artifact_instances child
    JOIN artifact_instances parent ON parent.id = NEW.input_artifact_instance_id
    JOIN runs child_run ON child_run.id = child.run_id
    JOIN runs parent_run ON parent_run.id = parent.run_id
    WHERE child.id = NEW.artifact_instance_id
      AND (
        child_run.benchmark_preregistration_digest IS NOT parent_run.benchmark_preregistration_digest
        OR child_run.benchmark_task_id IS NOT parent_run.benchmark_task_id
        OR child_run.benchmark_arm IS NOT parent_run.benchmark_arm
      )
  );

  SELECT RAISE(ABORT, 'artifact provenance edge would create a cycle')
  WHERE EXISTS (
    WITH RECURSIVE ancestors(id) AS (
      SELECT NEW.input_artifact_instance_id
      UNION
      SELECT ai.input_artifact_instance_id
      FROM artifact_inputs ai
      JOIN ancestors a ON ai.artifact_instance_id = a.id
    )
    SELECT 1 FROM ancestors WHERE id = NEW.artifact_instance_id
  );
END;

CREATE TRIGGER attestations_require_signer_key
BEFORE INSERT ON attestations
BEGIN
  SELECT RAISE(ABORT, 'attestation is not exactly bound or approval-broker signed')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.subject_digest') IS NOT NEW.subject_digest
     OR json_extract(NEW.canonical_json, '$.subject_kind') IS NOT NEW.subject_kind
     OR json_extract(NEW.canonical_json, '$.subject_id') IS NOT NEW.subject_id
     OR json_extract(NEW.canonical_json, '$.producer_attempt_id') IS NOT NEW.producer_attempt_id
     OR json_extract(NEW.canonical_json, '$.producer_executor_id') IS NOT NEW.producer_executor_id
     OR json_extract(NEW.canonical_json, '$.producer_model_family') IS NOT NEW.producer_model_family
     OR json_extract(NEW.canonical_json, '$.attestation_type') IS NOT NEW.attestation_type
     OR json_extract(NEW.canonical_json, '$.candidate_commit') IS NOT NEW.candidate_commit
     OR json_extract(NEW.canonical_json, '$.reviewer_attempt_id') IS NOT NEW.reviewer_attempt_id
     OR json_extract(NEW.canonical_json, '$.reviewer_executor_id') IS NOT NEW.reviewer_executor_id
     OR json_extract(NEW.canonical_json, '$.reviewer_model_family') IS NOT NEW.reviewer_model_family
     OR json_extract(NEW.canonical_json, '$.reviewer_principal_id') IS NOT NEW.reviewer_principal_id
     OR json_extract(NEW.canonical_json, '$.auth_command_authorization_digest') IS NOT NEW.auth_command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.independence_policy') IS NOT NEW.independence_policy
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.rubric_policy_digest') IS NOT NEW.rubric_policy_digest
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys signer_key
       JOIN principals signer ON signer.id = signer_key.principal_id
       JOIN principals reviewer ON reviewer.id = NEW.reviewer_principal_id
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key ON evidence_key.key_id = evidence.signer_key_id
       WHERE signer_key.key_id = NEW.signer_key_id
         AND signer_key.principal_id = NEW.signer_principal_id
         AND signer_key.key_purpose = 'approval_broker'
         AND signer.kind = 'service'
         AND reviewer.state = 'active'
         AND evidence_key.key_purpose = 'artifact_broker'
         AND (
           (NEW.independence_policy = 'human'
             AND reviewer.kind = 'human'
             AND NEW.reviewer_attempt_id IS NULL
             AND NEW.reviewer_executor_id IS NULL
             AND NEW.reviewer_model_family IS NULL)
           OR (NEW.independence_policy <> 'human' AND reviewer.kind = 'executor')
         )
         AND (
           (NEW.attestation_type = 'risk_acceptance'
             AND NEW.verdict = 'risk_accepted'
             AND NEW.auth_command_authorization_digest IS NOT NULL
             AND EXISTS (
               SELECT 1
               FROM command_authorizations ca
               JOIN attempts producer ON producer.id = NEW.producer_attempt_id
               JOIN leader_terms term ON term.term = ca.leader_term AND term.state = 'active'
               JOIN control_state control ON control.current_term = ca.leader_term
               JOIN principal_project_roles risk_role
                 ON risk_role.principal_id = NEW.reviewer_principal_id
                AND risk_role.project_id = producer.project_id
                AND risk_role.role = 'risk_acceptor'
                AND risk_role.revoked_at_ms IS NULL
               WHERE ca.digest = NEW.auth_command_authorization_digest
                 AND ca.actor_principal_id = NEW.reviewer_principal_id
                 AND ca.project_id = producer.project_id
                 AND ca.command_type = 'risk.accept'
                 AND ca.authorization_expires_at_ms >= NEW.created_at_ms
                 AND ca.authorization_expires_at_ms >= (unixepoch('subsec') * 1000)
                 AND EXISTS (
                   SELECT 1 FROM commands command
                   WHERE command.id = ca.command_id
                     AND command.state = 'authorized'
                     AND json_extract(command.payload_json, '$.subject_kind') = NEW.subject_kind
                     AND json_extract(command.payload_json, '$.subject_id') = NEW.subject_id
                     AND json_extract(command.payload_json, '$.subject_digest') = NEW.subject_digest
                     AND json_extract(command.payload_json, '$.candidate_commit') IS NEW.candidate_commit
                     AND json_extract(command.payload_json, '$.producer_attempt_id') IS NEW.producer_attempt_id
                     AND json_extract(command.payload_json, '$.producer_executor_id') IS NEW.producer_executor_id
                     AND json_extract(command.payload_json, '$.producer_model_family') IS NEW.producer_model_family
                     AND json_extract(command.payload_json, '$.independence_policy') = NEW.independence_policy
                     AND json_extract(command.payload_json, '$.rubric_policy_digest') = NEW.rubric_policy_digest
                     AND json_extract(command.payload_json, '$.evidence_manifest_digest') = NEW.evidence_manifest_digest
                     AND json_extract(command.payload_json, '$.verdict') = 'risk_accepted'
                 )
             ))
           OR (NEW.attestation_type <> 'risk_acceptance'
             AND NEW.auth_command_authorization_digest IS NULL)
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'attestation'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND json_extract(receipt.canonical_json, '$.subject_digest_verified') = 1
         AND json_extract(receipt.canonical_json, '$.verified_subject_digest') = NEW.subject_digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER attestation_reviewer_tuple_matches_attempt
BEFORE INSERT ON attestations
WHEN NEW.reviewer_attempt_id IS NOT NULL OR NEW.attestation_type = 'review'
BEGIN
  SELECT RAISE(ABORT, 'model reviewer identity must match an accepted attempt and fresh session')
  WHERE NEW.reviewer_attempt_id IS NULL
     OR NEW.reviewer_executor_id IS NULL
     OR NEW.reviewer_model_family IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM attempts a
       JOIN executors e ON e.id = a.executor_id
       JOIN attempt_session_bindings b ON b.attempt_id = a.id
       JOIN runtime_sessions s ON s.id = b.runtime_session_id
       JOIN result_envelopes reviewer_result
         ON reviewer_result.attempt_id = a.id
        AND reviewer_result.state = 'accepted'
       JOIN work_packets packet ON packet.attempt_id = a.id
       JOIN attempts producer ON producer.id = NEW.producer_attempt_id
       WHERE a.id = NEW.reviewer_attempt_id
         AND a.state = 'accepted'
         AND a.project_id = producer.project_id
         AND a.run_id = producer.run_id
         AND a.executor_id = NEW.reviewer_executor_id
         AND a.model_family = NEW.reviewer_model_family
         AND e.principal_id = NEW.reviewer_principal_id
         AND s.executor_id = a.executor_id
         AND s.fresh_context = 1
         AND reviewer_result.output_manifest_digest = NEW.evidence_manifest_digest
         AND json_extract(packet.canonical_json, '$.review.subject_kind') = NEW.subject_kind
         AND json_extract(packet.canonical_json, '$.review.subject_id') = NEW.subject_id
         AND json_extract(packet.canonical_json, '$.review.subject_digest') = NEW.subject_digest
         AND json_extract(packet.canonical_json, '$.review.rubric_policy_digest') = NEW.rubric_policy_digest
     );
END;

CREATE TRIGGER attestation_subject_requires_verified_lineage
BEFORE INSERT ON attestation_subjects
BEGIN
  SELECT RAISE(ABORT, 'attestation subject projection differs from its signed parent')
  WHERE NOT EXISTS (
    SELECT 1 FROM attestations a
    WHERE a.id = NEW.attestation_id
      AND a.subject_kind = NEW.subject_kind
      AND a.subject_id = NEW.subject_id
      AND a.producer_attempt_id IS NEW.producer_attempt_id
      AND a.producer_executor_id IS NEW.producer_executor_id
      AND a.producer_model_family IS NEW.producer_model_family
  );

  SELECT RAISE(ABORT, 'attestation subject requires complete producer lineage')
  WHERE NEW.subject_kind IN ('attempt','artifact','commit')
    AND (NEW.producer_attempt_id IS NULL
     OR NEW.producer_executor_id IS NULL
     OR NEW.producer_model_family IS NULL);

  SELECT RAISE(ABORT, 'attestation producer lineage does not match attempt')
  WHERE NEW.subject_kind IN ('attempt','artifact','commit')
    AND NOT EXISTS (
    SELECT 1 FROM attempts a
    WHERE a.id = NEW.producer_attempt_id
      AND a.executor_id = NEW.producer_executor_id
      AND a.model_family = NEW.producer_model_family
  );

  SELECT RAISE(ABORT, 'attempt subject does not match producer attempt')
  WHERE NEW.subject_kind = 'attempt'
    AND NEW.subject_id <> NEW.producer_attempt_id;

  SELECT RAISE(ABORT, 'artifact subject does not match producer attempt')
  WHERE NEW.subject_kind = 'artifact'
    AND NOT EXISTS (
      SELECT 1 FROM artifact_instances ai
      WHERE ai.id = NEW.subject_id
        AND ai.producer_attempt_id = NEW.producer_attempt_id
    );

  SELECT RAISE(ABORT, 'commit subject is not attributable to producer attempt')
  WHERE NEW.subject_kind = 'commit'
    AND NOT EXISTS (
      SELECT 1 FROM workspaces w
      WHERE w.attempt_id = NEW.producer_attempt_id
        AND w.output_commit = NEW.subject_id
      UNION ALL
      SELECT 1
      FROM merge_requests mr
      JOIN node_versions nv ON nv.id = mr.node_version_id
      WHERE nv.accepted_attempt_id = NEW.producer_attempt_id
        AND NEW.subject_id IN (mr.candidate_commit, mr.merged_commit)
    );
END;

CREATE TRIGGER gate_bundles_require_active_signing_key
BEFORE INSERT ON gate_bundles
BEGIN
  SELECT RAISE(ABORT, 'gate bundle is not exact, current, control-plane signed, or signature-verified')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.repository_id') IS NOT NEW.repository_id
     OR json_extract(NEW.canonical_json, '$.target_ref') IS NOT NEW.target_ref
     OR json_extract(NEW.canonical_json, '$.target_fence') IS NOT NEW.target_fence
     OR json_extract(NEW.canonical_json, '$.target_head_observation_id') IS NOT NEW.target_head_observation_id
     OR json_extract(NEW.canonical_json, '$.base_commit') IS NOT NEW.base_commit
     OR json_extract(NEW.canonical_json, '$.candidate_commit') IS NOT NEW.candidate_commit
     OR json_extract(NEW.canonical_json, '$.merge_request_id') IS NOT NEW.merge_request_id
     OR json_extract(NEW.canonical_json, '$.primary_producer_attempt_id') IS NOT NEW.primary_producer_attempt_id
     OR json_extract(NEW.canonical_json, '$.verification_attestation_id') IS NOT NEW.verification_attestation_id
     OR json_extract(NEW.canonical_json, '$.security_attestation_id') IS NOT NEW.security_attestation_id
     OR json_extract(NEW.canonical_json, '$.final_review_attestation_id') IS NOT NEW.final_review_attestation_id
     OR json_extract(NEW.canonical_json, '$.risk_acceptance_attestation_id') IS NOT NEW.risk_acceptance_attestation_id
     OR json_extract(NEW.canonical_json, '$.policy_digest') IS NOT NEW.policy_digest
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys key
       JOIN principals signer ON signer.id = key.principal_id
       WHERE key.key_id = NEW.signer_key_id
         AND key.key_purpose = 'release_broker'
         AND signer.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = receipt.signer_key_id
        AND validator_key.principal_id = receipt.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       WHERE receipt.record_kind = 'gate_bundle'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );

  SELECT RAISE(ABORT, 'gate bundle references an invalidated policy')
  WHERE EXISTS (
    SELECT 1 FROM policy_invalidations
    WHERE policy_digest = NEW.policy_digest
  );
END;

CREATE TRIGGER approval_request_is_exact_current_and_broker_signed
BEFORE INSERT ON approval_requests
BEGIN
  SELECT RAISE(ABORT, 'approval request is not exact, current, policy-required, or broker signed')
  WHERE NEW.requested_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.requested_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= NEW.requested_at_ms
     OR NEW.expires_at_ms > NEW.requested_at_ms + 3600000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.gate_bundle_digest') IS NOT NEW.gate_bundle_digest
     OR json_extract(NEW.canonical_json, '$.requested_action') IS NOT NEW.requested_action
     OR json_extract(NEW.canonical_json, '$.required_role') IS NOT NEW.required_role
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.requester_principal_id') IS NOT NEW.requester_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.requested_at_ms') IS NOT NEW.requested_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM gate_bundles gate
       JOIN release_policy_effect_rules rule
         ON rule.policy_digest = gate.policy_digest
        AND rule.effect_type = NEW.requested_action
        AND rule.human_approval_required = 1
        AND rule.required_role = NEW.required_role
       JOIN principals requester
         ON requester.id = NEW.requester_principal_id
        AND requester.kind = 'service'
        AND requester.state = 'active'
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       JOIN principals broker
         ON broker.id = NEW.signer_principal_id AND broker.kind = 'service'
       JOIN current_valid_keys gate_key
         ON gate_key.key_id = gate.signer_key_id
        AND gate_key.key_purpose = 'release_broker'
       WHERE gate.digest = NEW.gate_bundle_digest
         AND gate.project_id = NEW.project_id
         AND NOT EXISTS (
           SELECT 1 FROM gate_invalidations invalidation
           WHERE invalidation.gate_bundle_digest = gate.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = gate.policy_digest
         )
     );

  SELECT RAISE(ABORT, 'approval request signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'approval_request'
      AND receipt.record_id = NEW.id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.requested_at_ms - 5000 AND NEW.requested_at_ms
  );
END;

CREATE TRIGGER approval_decisions_require_signer_key
BEFORE INSERT ON approval_decisions
BEGIN
  SELECT RAISE(ABORT, 'approval decision is not exact or approval-broker signed')
  WHERE NEW.decided_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.decided_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.request_id') IS NOT NEW.request_id
     OR json_extract(NEW.canonical_json, '$.principal_id') IS NOT NEW.principal_id
     OR json_extract(NEW.canonical_json, '$.decision') IS NOT NEW.decision
     OR json_extract(NEW.canonical_json, '$.decision_digest') IS NOT NEW.decision_digest
     OR json_extract(NEW.canonical_json, '$.auth_command_authorization_digest') IS NOT NEW.auth_command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.decided_at_ms') IS NOT NEW.decided_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys sk
       JOIN principals broker ON broker.id = NEW.signer_principal_id
       JOIN principals actor ON actor.id = NEW.principal_id
       JOIN approval_requests ar ON ar.id = NEW.request_id
       JOIN gate_bundles g ON g.digest = ar.gate_bundle_digest
       JOIN command_authorizations ca ON ca.digest = NEW.auth_command_authorization_digest
       JOIN commands command ON command.id = ca.command_id
       JOIN control_state ctl ON ctl.current_term = ca.leader_term
       WHERE sk.key_id = NEW.signer_key_id
         AND sk.principal_id = NEW.signer_principal_id
         AND sk.key_purpose = 'approval_broker'
         AND broker.kind = 'service'
         AND actor.kind = 'human'
         AND actor.state = 'active'
         AND ca.actor_principal_id = NEW.principal_id
         AND ca.project_id = ar.project_id
         AND ca.command_type = 'approval.decide'
         AND ca.authorization_expires_at_ms >= NEW.decided_at_ms
         AND command.state = 'authorized'
         AND json_extract(command.payload_json, '$.request_id') = NEW.request_id
         AND json_extract(command.payload_json, '$.decision') = NEW.decision
         AND json_extract(command.payload_json, '$.decision_digest') = NEW.decision_digest
         AND json_extract(command.payload_json, '$.request_payload_digest') = ar.payload_digest
         AND json_extract(NEW.canonical_json, '$.project_id') = ar.project_id
         AND json_extract(NEW.canonical_json, '$.requested_action') = ar.requested_action
         AND json_extract(NEW.canonical_json, '$.required_role') = ar.required_role
         AND json_extract(NEW.canonical_json, '$.request_payload_digest') = ar.payload_digest
         AND json_extract(NEW.canonical_json, '$.candidate_commit') = g.candidate_commit
         AND json_extract(NEW.canonical_json, '$.request_expires_at_ms') = ar.expires_at_ms
     );

  SELECT RAISE(ABORT, 'approval decision signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'approval_decision'
      AND receipt.record_id = NEW.request_id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.decided_at_ms - 5000 AND NEW.decided_at_ms
  );
END;

CREATE TRIGGER human_responses_require_signer_key
BEFORE INSERT ON human_responses
BEGIN
  SELECT RAISE(ABORT, 'human response is not exact, authenticated, role-scoped, or broker-signed')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.request_id') IS NOT NEW.request_id
     OR json_extract(NEW.canonical_json, '$.principal_id') IS NOT NEW.principal_id
     OR json(NEW.response_json) <> json(json_extract(NEW.canonical_json, '$.response'))
     OR json_extract(NEW.canonical_json, '$.response_digest') IS NOT NEW.response_digest
     OR json_extract(NEW.canonical_json, '$.credential_reference_id') IS NOT NEW.credential_reference_id
     OR json_extract(NEW.canonical_json, '$.sanitization_attestation_digest') IS NOT NEW.sanitization_attestation_digest
     OR json_extract(NEW.canonical_json, '$.auth_command_authorization_digest') IS NOT NEW.auth_command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR EXISTS (
       SELECT 1 FROM json_tree(NEW.response_json) member
       WHERE member.key IS NOT NULL
         AND lower(CAST(member.key AS TEXT)) IN (
           'secret','password','token','credential','credential_value',
           'api_key','apikey','private_key','authorization','cookie'
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM content_sanitization_attestations attestation
       WHERE attestation.digest = NEW.sanitization_attestation_digest
         AND attestation.content_kind = 'human_response'
         AND attestation.subject_id = NEW.request_id
         AND attestation.payload_digest = NEW.response_digest
         AND attestation.created_at_ms <= NEW.created_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = attestation.sanitizer_closure_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM human_requests hr
       JOIN principals actor
         ON actor.id = NEW.principal_id
        AND actor.kind = 'human'
        AND actor.state = 'active'
       JOIN principal_project_roles role
         ON role.principal_id = NEW.principal_id
        AND role.project_id = hr.project_id
        AND role.role = hr.required_role
        AND role.revoked_at_ms IS NULL
       JOIN command_authorizations ca ON ca.digest = NEW.auth_command_authorization_digest
       JOIN commands command ON command.id = ca.command_id
       JOIN control_state ctl ON ctl.current_term = ca.leader_term
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       JOIN principals broker
         ON broker.id = NEW.signer_principal_id AND broker.kind = 'service'
       WHERE hr.id = NEW.request_id
         AND hr.state = 'open'
         AND (hr.due_at_ms IS NULL OR NEW.created_at_ms <= hr.due_at_ms)
         AND ca.actor_principal_id = NEW.principal_id
         AND ca.project_id = hr.project_id
         AND ca.command_type = 'human.respond'
         AND ca.authorization_expires_at_ms >= NEW.created_at_ms
         AND command.state = 'authorized'
         AND json_extract(command.payload_json, '$.request_id') = NEW.request_id
         AND json_extract(command.payload_json, '$.response_digest') = NEW.response_digest
         AND json_extract(NEW.canonical_json, '$.project_id') = hr.project_id
         AND json_extract(NEW.canonical_json, '$.required_role') = hr.required_role
         AND json_extract(NEW.canonical_json, '$.request_payload_digest') = hr.payload_digest
         AND (
           (hr.request_type <> 'credential' AND NEW.credential_reference_id IS NULL)
           OR (hr.request_type = 'credential'
             AND NEW.credential_reference_id IS NOT NULL
             AND json_type(NEW.response_json, '$.credential_reference_id') = 'text'
             AND json_extract(NEW.response_json, '$.credential_reference_id') = NEW.credential_reference_id
             AND json_extract(NEW.response_json, '$.status') = 'stored'
             AND (SELECT COUNT(*) FROM json_each(NEW.response_json)) = 2
             AND EXISTS (
               SELECT 1 FROM credential_references reference
               WHERE reference.id = NEW.credential_reference_id
                 AND reference.request_id = NEW.request_id
                 AND reference.project_id = hr.project_id
                 AND reference.state = 'active'
                 AND reference.expires_at_ms >= NEW.created_at_ms
                 AND NOT EXISTS (
                   SELECT 1 FROM credential_reference_revocations revocation
                   WHERE revocation.credential_reference_id = reference.id
                     AND revocation.revoked_at_ms <= NEW.created_at_ms
                 )
             ))
         )
     );

  SELECT RAISE(ABORT, 'human response signature lacks a trusted verification receipt')
  WHERE NOT EXISTS (
    SELECT 1 FROM current_valid_signature_receipts receipt
    JOIN current_valid_keys validator_key
      ON validator_key.key_id = receipt.signer_key_id
     AND validator_key.principal_id = receipt.signer_principal_id
     AND validator_key.key_purpose = 'schema_validator'
    WHERE receipt.record_kind = 'human_response'
      AND receipt.record_id = NEW.request_id
      AND receipt.record_canonical_json = NEW.canonical_json
      AND receipt.record_signer_key_id = NEW.signer_key_id
      AND receipt.record_signature = NEW.signature
      AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
  );
END;

CREATE TRIGGER signing_keys_identity_is_immutable
BEFORE UPDATE OF key_id, principal_id, algorithm, public_key, public_key_fingerprint,
  key_purpose, created_at_ms, expires_at_ms
ON signing_keys
BEGIN SELECT RAISE(ABORT, 'signing-key identity is immutable'); END;

CREATE TRIGGER signing_keys_legal_state_transition
BEFORE UPDATE OF state ON signing_keys
WHEN OLD.state <> NEW.state
BEGIN
  SELECT RAISE(ABORT, 'signing keys cannot be reactivated')
  WHERE NOT (OLD.state = 'active' AND NEW.state IN ('revoked','expired'))
     OR (NEW.state = 'expired' AND (
          NEW.expires_at_ms IS NULL
          OR NEW.expires_at_ms > (unixepoch('subsec') * 1000)
          OR NEW.revoked_at_ms IS NOT NULL
        ))
     OR (NEW.state = 'revoked' AND (
          NEW.revoked_at_ms IS NULL
          OR NEW.revoked_at_ms < OLD.created_at_ms
          OR NEW.revoked_at_ms > (unixepoch('subsec') * 1000) + 5000
          OR NOT EXISTS (
            SELECT 1
            FROM key_registration_authorizations a
            JOIN current_valid_keys admin_key
              ON admin_key.key_id = a.signer_key_id
             AND admin_key.principal_id = a.signer_principal_id
             AND admin_key.key_purpose = 'key_admin'
            WHERE a.target_key_id = NEW.key_id
              AND a.target_principal_id = NEW.principal_id
              AND a.target_public_key_fingerprint = NEW.public_key_fingerprint
              AND a.action = 'revoke'
              AND a.created_at_ms = NEW.revoked_at_ms
              AND a.expires_at_ms >= NEW.revoked_at_ms
          )
        ));
END;

CREATE TRIGGER signing_key_revoked_at_changes_only_with_revocation
BEFORE UPDATE OF revoked_at_ms ON signing_keys
WHEN OLD.revoked_at_ms IS NOT NEW.revoked_at_ms
BEGIN
  SELECT RAISE(ABORT, 'revocation timestamp is set once by the authorized state transition')
  WHERE OLD.revoked_at_ms IS NOT NULL
     OR NEW.revoked_at_ms IS NULL
     OR OLD.state <> 'active'
     OR NEW.state <> 'revoked';
END;

CREATE TRIGGER signing_key_loss_trips_global_kill_switch
AFTER UPDATE OF state ON signing_keys
WHEN OLD.state = 'active' AND NEW.state IN ('revoked','expired')
BEGIN
  UPDATE control_state
  SET dispatch_enabled = 0,
      admission_mode = 'stopped',
      kill_switch = 1,
      revision = revision + 1
  WHERE singleton = 1;
END;

CREATE TRIGGER signing_keys_no_delete
BEFORE DELETE ON signing_keys
BEGIN SELECT RAISE(ABORT, 'signing-key history is append-only'); END;

CREATE TRIGGER principal_project_roles_no_delete
BEFORE DELETE ON principal_project_roles
BEGIN SELECT RAISE(ABORT, 'role grants are revoked, never deleted'); END;

CREATE TRIGGER principal_project_role_requires_authorized_grant
BEFORE INSERT ON principal_project_roles
BEGIN
  SELECT RAISE(ABORT, 'project role grant lacks exact signed authority')
  WHERE NEW.revoked_at_ms IS NOT NULL
     OR NEW.revocation_authorization_id IS NOT NULL
     OR NOT (
       (NEW.grant_authorization_id IS NOT NULL AND EXISTS (
         SELECT 1 FROM role_change_authorizations a
         WHERE a.digest = NEW.grant_authorization_id
           AND a.target_grant_id = NEW.grant_id
           AND a.action = 'grant'
           AND a.role_scope = 'project'
           AND a.target_principal_id = NEW.principal_id
           AND a.project_id = NEW.project_id
           AND a.role = NEW.role
           AND a.created_at_ms = NEW.granted_at_ms
           AND a.expires_at_ms >= NEW.granted_at_ms
       ))
       OR (NEW.project_submit_authorization_digest IS NOT NULL
         AND NEW.role = 'owner'
         AND NEW.grant_id = 'project-owner:' || NEW.project_id
         AND EXISTS (
           SELECT 1
           FROM projects project
           JOIN command_authorizations authorization
             ON authorization.digest = project.submit_command_authorization_digest
           WHERE project.id = NEW.project_id
             AND project.owner_principal_id = NEW.principal_id
             AND project.created_at_ms = NEW.granted_at_ms
             AND authorization.digest = NEW.project_submit_authorization_digest
             AND authorization.actor_principal_id = NEW.principal_id
             AND authorization.command_type = 'project.submit'
         )
       )
     );
END;

CREATE TRIGGER principal_project_roles_identity_is_immutable
BEFORE UPDATE OF grant_id, principal_id, project_id, role, granted_at_ms,
  grant_authorization_id, project_submit_authorization_digest
ON principal_project_roles
BEGIN SELECT RAISE(ABORT, 'role-grant identity is immutable'); END;

CREATE TRIGGER principal_project_roles_revoke_once
BEFORE UPDATE OF revoked_at_ms ON principal_project_roles
BEGIN
  SELECT RAISE(ABORT, 'role revocation is one-way and requires exact signed authority')
  WHERE OLD.revoked_at_ms IS NOT NULL
     OR NEW.revoked_at_ms IS NULL
     OR OLD.revocation_authorization_id IS NOT NULL
     OR NEW.revocation_authorization_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM role_change_authorizations a
       WHERE a.digest = NEW.revocation_authorization_id
         AND a.target_grant_id = NEW.grant_id
         AND a.action = 'revoke'
         AND a.role_scope = 'project'
         AND a.target_principal_id = NEW.principal_id
         AND a.project_id = NEW.project_id
         AND a.role = NEW.role
         AND a.created_at_ms = NEW.revoked_at_ms
         AND a.expires_at_ms >= NEW.revoked_at_ms
     );
END;

CREATE TRIGGER principal_project_role_revocation_authority_changes_with_time
BEFORE UPDATE OF revocation_authorization_id ON principal_project_roles
WHEN OLD.revocation_authorization_id IS NOT NEW.revocation_authorization_id
BEGIN
  SELECT RAISE(ABORT, 'project-role revocation authorization is set once with revoked_at')
  WHERE OLD.revocation_authorization_id IS NOT NULL
     OR NEW.revocation_authorization_id IS NULL
     OR OLD.revoked_at_ms IS NOT NULL
     OR NEW.revoked_at_ms IS NULL;
END;

