CREATE TRIGGER principal_global_role_requires_authorized_grant
BEFORE INSERT ON principal_global_roles
BEGIN
  SELECT RAISE(ABORT, 'global role grant lacks exact signed authority')
  WHERE NEW.revoked_at_ms IS NOT NULL
     OR NEW.revocation_authorization_id IS NOT NULL
     OR NOT EXISTS (
       SELECT 1 FROM role_change_authorizations a
       WHERE a.digest = NEW.grant_authorization_id
         AND a.target_grant_id = NEW.grant_id
         AND a.action = 'grant'
         AND a.role_scope = 'global'
         AND a.target_principal_id = NEW.principal_id
         AND a.project_id IS NULL
         AND a.role = NEW.role
         AND a.created_at_ms = NEW.granted_at_ms
         AND a.expires_at_ms >= NEW.granted_at_ms
     );
END;

CREATE TRIGGER principal_global_roles_identity_is_immutable
BEFORE UPDATE OF grant_id, principal_id, role, granted_at_ms, grant_authorization_id
ON principal_global_roles
BEGIN SELECT RAISE(ABORT, 'global role-grant identity is immutable'); END;

CREATE TRIGGER principal_global_roles_revoke_once
BEFORE UPDATE OF revoked_at_ms ON principal_global_roles
BEGIN
  SELECT RAISE(ABORT, 'role revocation is one-way and requires exact signed authority')
  WHERE OLD.revoked_at_ms IS NOT NULL
