     OR NEW.revocation_authorization_id IS NULL
     OR NOT EXISTS (
       SELECT 1 FROM role_change_authorizations a
       WHERE a.digest = NEW.revocation_authorization_id
         AND a.target_grant_id = NEW.grant_id
         AND a.action = 'revoke'
         AND a.role_scope = 'global'
         AND a.target_principal_id = NEW.principal_id
         AND a.project_id IS NULL
         AND a.role = NEW.role
         AND a.created_at_ms = NEW.revoked_at_ms
         AND a.expires_at_ms >= NEW.revoked_at_ms
     );
END;

CREATE TRIGGER principal_global_role_revocation_authority_changes_with_time
BEFORE UPDATE OF revocation_authorization_id ON principal_global_roles
WHEN OLD.revocation_authorization_id IS NOT NEW.revocation_authorization_id
BEGIN
  SELECT RAISE(ABORT, 'global-role revocation authorization is set once with revoked_at')
  WHERE OLD.revocation_authorization_id IS NOT NULL
     OR NEW.revocation_authorization_id IS NULL
     OR OLD.revoked_at_ms IS NOT NULL
     OR NEW.revoked_at_ms IS NULL;
END;

CREATE TRIGGER role_change_authorization_is_current_exact_and_non_escalating
BEFORE INSERT ON role_change_authorizations
BEGIN
  SELECT RAISE(ABORT, 'role authorization is not exact, current, or permitted')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms <= (unixepoch('subsec') * 1000)
     OR NEW.expires_at_ms > NEW.created_at_ms + 30000
     OR NEW.grantor_principal_id = NEW.target_principal_id
     OR (NEW.role_scope = 'global' AND NEW.role NOT IN ('admin','operator','auditor'))
     OR (NEW.role_scope = 'project' AND NEW.role NOT IN ('owner','operator','reviewer','approver','risk_acceptor','viewer'))
     OR json_extract(NEW.canonical_json, '$.target_grant_id') IS NOT NEW.target_grant_id
     OR json_extract(NEW.canonical_json, '$.action') IS NOT NEW.action
     OR json_extract(NEW.canonical_json, '$.role_scope') IS NOT NEW.role_scope
     OR json_extract(NEW.canonical_json, '$.target_principal_id') IS NOT NEW.target_principal_id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.role') IS NOT NEW.role
     OR json_extract(NEW.canonical_json, '$.grantor_principal_id') IS NOT NEW.grantor_principal_id
     OR json_extract(NEW.canonical_json, '$.command_authorization_digest') IS NOT NEW.command_authorization_digest
     OR json_extract(NEW.canonical_json, '$.bootstrap_manifest_digest') IS NOT NEW.bootstrap_manifest_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys sk
       JOIN principals signer ON signer.id = sk.principal_id
       JOIN leader_terms lt ON lt.term = NEW.leader_term AND lt.state = 'active'
       JOIN control_state ctl ON ctl.current_term = NEW.leader_term
       WHERE sk.key_id = NEW.signer_key_id
         AND sk.principal_id = NEW.signer_principal_id
         AND sk.key_purpose = 'control_plane'
         AND signer.kind = 'service'
         AND (
           (NEW.bootstrap_manifest_digest IS NOT NULL AND NEW.action = 'grant' AND EXISTS (
             SELECT 1
             FROM bootstrap_manifests bm
             JOIN current_valid_keys bmk
               ON bmk.key_id = bm.signer_key_id
              AND bmk.key_id = NEW.signer_key_id
              AND bmk.principal_id = NEW.signer_principal_id
              AND bmk.key_purpose = 'control_plane'
             JOIN control_state boot_ctl
               ON boot_ctl.bootstrap_manifest_digest = bm.digest
              AND boot_ctl.dispatch_enabled = 0
             JOIN json_each(bm.canonical_json, '$.role_bindings') binding
             WHERE bm.digest = NEW.bootstrap_manifest_digest
               AND json_extract(binding.value, '$.role_scope') = NEW.role_scope
               AND json_extract(binding.value, '$.target_grant_id') = NEW.target_grant_id
               AND json_extract(binding.value, '$.target_principal_id') = NEW.target_principal_id
               AND json_extract(binding.value, '$.project_id') IS NEW.project_id
               AND json_extract(binding.value, '$.role') = NEW.role
               AND json_extract(binding.value, '$.grantor_principal_id') = NEW.grantor_principal_id
           ))
           OR (NEW.command_authorization_digest IS NOT NULL AND EXISTS (
             SELECT 1 FROM command_authorizations ca
             JOIN commands command ON command.id = ca.command_id
             WHERE ca.digest = NEW.command_authorization_digest
               AND ca.actor_principal_id = NEW.grantor_principal_id
               AND ca.command_type = 'role.manage'
               AND ca.project_id IS NEW.project_id
               AND ca.leader_term = NEW.leader_term
               AND ca.authorization_expires_at_ms >= NEW.created_at_ms
               AND command.state = 'authorized'
               AND json_extract(command.payload_json, '$.target_grant_id') = NEW.target_grant_id
               AND json_extract(command.payload_json, '$.action') = NEW.action
               AND json_extract(command.payload_json, '$.role_scope') = NEW.role_scope
               AND json_extract(command.payload_json, '$.target_principal_id') = NEW.target_principal_id
               AND json_extract(command.payload_json, '$.project_id') IS NEW.project_id
               AND json_extract(command.payload_json, '$.role') = NEW.role
               AND json_extract(command.payload_json, '$.leader_term') = NEW.leader_term
           ))
         )
         AND (
           NEW.bootstrap_manifest_digest IS NOT NULL
           OR (NEW.role_scope = 'global' AND EXISTS (
             SELECT 1 FROM principal_global_roles g
             WHERE g.principal_id = NEW.grantor_principal_id
               AND g.role = 'admin' AND g.revoked_at_ms IS NULL
           ))
           OR (NEW.role_scope = 'project' AND (
             EXISTS (
               SELECT 1 FROM principal_global_roles g
               WHERE g.principal_id = NEW.grantor_principal_id
                 AND g.role IN ('admin','operator') AND g.revoked_at_ms IS NULL
             )
             OR EXISTS (
               SELECT 1 FROM principal_project_roles p
               WHERE p.principal_id = NEW.grantor_principal_id
                 AND p.project_id = NEW.project_id
                 AND p.role = 'owner' AND p.revoked_at_ms IS NULL
             )
           ))
         )
     );
END;

