CREATE TRIGGER project_repository_attachment_is_exact_authorized_command
BEFORE INSERT ON project_repositories
BEGIN
  SELECT RAISE(ABORT, 'project repository attachment is not an exact current owner/operator command')
  WHERE NEW.attached_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.attached_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1
       FROM command_authorizations authorization
       JOIN commands command ON command.id = authorization.command_id
       JOIN principal_project_roles role
         ON role.principal_id = authorization.actor_principal_id
        AND role.project_id = NEW.project_id
        AND role.role IN ('owner','operator')
        AND role.revoked_at_ms IS NULL
       JOIN control_state control ON control.current_term = authorization.leader_term
       WHERE authorization.digest = NEW.attach_command_authorization_digest
         AND authorization.project_id = NEW.project_id
         AND authorization.command_type = 'project.repository.attach'
         AND authorization.authorization_expires_at_ms >= NEW.attached_at_ms
         AND command.state = 'authorized'
         AND json_extract(command.payload_json, '$.project_id') = NEW.project_id
         AND json_extract(command.payload_json, '$.repository_id') = NEW.repository_id
         AND json_extract(command.payload_json, '$.access_mode') = NEW.access_mode
     );
END;

