CREATE TRIGGER policy_invalidation_requires_exact_authorization
BEFORE INSERT ON policy_invalidations
BEGIN
  SELECT RAISE(ABORT, 'policy invalidation does not match its current authorization')
  WHERE NOT EXISTS (
    SELECT 1 FROM authority_change_authorizations a
    JOIN control_state ctl ON ctl.current_term = a.leader_term
    JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
    WHERE a.id = NEW.authorization_id
      AND a.target_kind = 'policy'
      AND a.target_id = NEW.policy_digest
      AND a.replacement_target_id IS NEW.replacement_policy_digest
      AND a.actor_principal_id = NEW.invalidated_by_principal_id
      AND a.action = CASE NEW.invalidation_type WHEN 'superseded' THEN 'supersede' ELSE 'revoke' END
      AND a.expires_at_ms >= NEW.invalidated_at_ms
      AND NEW.invalidated_at_ms <= (unixepoch('subsec') * 1000) + 5000
  );
END;

