CREATE TRIGGER artifact_instance_taint_is_exact_monotonic_lineage
BEFORE INSERT ON artifact_instance_taints
BEGIN
  SELECT RAISE(ABORT, 'artifact-instance taint is not an exact benchmark origin or provenance-derived lineage')
  WHERE NEW.id <> 'artifact-taint:' || NEW.artifact_instance_id || ':'
                    || NEW.preregistration_digest || ':' || NEW.task_id || ':' || NEW.arm
     OR NEW.source_artifact_instance_id <> NEW.artifact_instance_id
     OR NOT (
       (NEW.reason = 'benchmark_output'
         AND NEW.source_input_artifact_instance_id IS NULL
         AND EXISTS (
           SELECT 1
           FROM artifact_instances source
           JOIN attempts producer ON producer.id = source.producer_attempt_id
           JOIN runs run ON run.id = producer.run_id
           WHERE source.id = NEW.artifact_instance_id
             AND source.blob_digest = NEW.blob_digest
             AND run.benchmark_preregistration_digest = NEW.preregistration_digest
             AND run.benchmark_task_id = NEW.task_id
             AND run.benchmark_arm = NEW.arm
             AND NEW.created_at_ms = source.created_at_ms
         ))
       OR (NEW.reason = 'derived_from_benchmark'
         AND NEW.source_input_artifact_instance_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM artifact_instances child
           JOIN artifact_inputs edge ON edge.artifact_instance_id = child.id
           JOIN artifact_instance_taints parent_taint
             ON parent_taint.artifact_instance_id = NEW.source_input_artifact_instance_id
           WHERE child.id = NEW.artifact_instance_id
             AND child.blob_digest = NEW.blob_digest
             AND edge.input_artifact_instance_id = NEW.source_input_artifact_instance_id
             AND parent_taint.preregistration_digest = NEW.preregistration_digest
             AND parent_taint.task_id = NEW.task_id
             AND parent_taint.arm = NEW.arm
             AND NEW.created_at_ms = child.created_at_ms
         ))
       OR (NEW.reason = 'benchmark_evaluator_output'
         AND NEW.source_input_artifact_instance_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM benchmark_evaluator_output_bindings binding
           JOIN artifact_instances output
             ON output.id = binding.output_artifact_instance_id
            AND output.blob_digest = binding.output_blob_digest
           JOIN artifact_instance_taints source_taint
             ON source_taint.artifact_instance_id = binding.source_normalized_artifact_instance_id
            AND source_taint.preregistration_digest = binding.preregistration_digest
            AND source_taint.task_id = binding.task_id
            AND source_taint.arm = binding.arm
           WHERE binding.output_artifact_instance_id = NEW.artifact_instance_id
             AND binding.output_blob_digest = NEW.blob_digest
             AND binding.source_normalized_artifact_instance_id = NEW.source_input_artifact_instance_id
             AND binding.preregistration_digest = NEW.preregistration_digest
             AND binding.task_id = NEW.task_id
             AND binding.arm = NEW.arm
             AND NEW.created_at_ms = output.created_at_ms
         ))
     );
END;

CREATE TRIGGER benchmark_output_artifact_instance_is_tainted
AFTER INSERT ON artifact_instances
WHEN NEW.producer_attempt_id IS NOT NULL
BEGIN
  INSERT OR IGNORE INTO artifact_instance_taints(
    id, artifact_instance_id, blob_digest, preregistration_digest, task_id, arm,
    source_artifact_instance_id, source_input_artifact_instance_id,
    reason, created_at_ms
  )
  SELECT 'artifact-taint:' || NEW.id || ':'
           || run.benchmark_preregistration_digest || ':'
           || run.benchmark_task_id || ':' || run.benchmark_arm,
         NEW.id, NEW.blob_digest, run.benchmark_preregistration_digest,
         run.benchmark_task_id, run.benchmark_arm,
         NEW.id, NULL, 'benchmark_output', NEW.created_at_ms
  FROM attempts producer
  JOIN runs run ON run.id = producer.run_id
  WHERE producer.id = NEW.producer_attempt_id
    AND run.benchmark_preregistration_digest IS NOT NULL;
END;

CREATE TRIGGER artifact_input_propagates_benchmark_instance_taint
AFTER INSERT ON artifact_inputs
BEGIN
  INSERT OR IGNORE INTO artifact_instance_taints(
    id, artifact_instance_id, blob_digest, preregistration_digest, task_id, arm,
    source_artifact_instance_id, source_input_artifact_instance_id,
    reason, created_at_ms
  )
  SELECT 'artifact-taint:' || child.id || ':'
           || parent_taint.preregistration_digest || ':'
           || parent_taint.task_id || ':' || parent_taint.arm,
         child.id, child.blob_digest, parent_taint.preregistration_digest,
         parent_taint.task_id, parent_taint.arm,
         child.id, parent.id, 'derived_from_benchmark', child.created_at_ms
  FROM artifact_instances child
  JOIN artifact_instances parent ON parent.id = NEW.input_artifact_instance_id
  JOIN artifact_instance_taints parent_taint
    ON parent_taint.artifact_instance_id = parent.id
  WHERE child.id = NEW.artifact_instance_id;
END;

