CREATE TRIGGER workspace_commit_taint_is_exact_monotonic_lineage
BEFORE INSERT ON workspace_commit_taints
BEGIN
  SELECT RAISE(ABORT, 'workspace commit taint is not exact benchmark-derived lineage')
  WHERE NEW.id <> 'commit-taint:' || NEW.repository_id || ':' || NEW.commit_id || ':'
                    || NEW.preregistration_digest || ':' || NEW.task_id || ':' || NEW.arm
     OR NOT (
       (NEW.source_kind = 'benchmark_workspace' AND EXISTS (
         SELECT 1
         FROM workspaces workspace
         JOIN attempts attempt ON attempt.id = workspace.attempt_id
         JOIN runs run ON run.id = attempt.run_id
         WHERE workspace.repository_id = NEW.repository_id
           AND workspace.output_commit = NEW.commit_id
           AND workspace.state = 'sealed'
           AND attempt.id = NEW.source_attempt_id
           AND run.benchmark_preregistration_digest = NEW.preregistration_digest
           AND run.benchmark_task_id = NEW.task_id
           AND run.benchmark_arm = NEW.arm
           AND NEW.created_at_ms >= workspace.created_at_ms
       ))
       OR (NEW.source_kind = 'artifact_instance' AND EXISTS (
         SELECT 1
         FROM workspaces workspace
         JOIN attempts attempt ON attempt.id = workspace.attempt_id
         JOIN artifact_instance_taints taint
           ON taint.artifact_instance_id = NEW.source_artifact_instance_id
          AND taint.blob_digest = NEW.source_blob_digest
          AND taint.preregistration_digest = NEW.preregistration_digest
          AND taint.task_id = NEW.task_id
          AND taint.arm = NEW.arm
         WHERE workspace.repository_id = NEW.repository_id
           AND workspace.output_commit = NEW.commit_id
           AND workspace.state = 'sealed'
           AND attempt.id = NEW.source_attempt_id
           AND NEW.created_at_ms >= workspace.created_at_ms
           AND (
             EXISTS (
               SELECT 1 FROM artifact_instances output
               WHERE output.producer_attempt_id = attempt.id
                 AND output.id = taint.artifact_instance_id
             )
             OR EXISTS (
               SELECT 1
               FROM artifact_instances node_input
               JOIN artifact_inputs edge ON edge.artifact_instance_id = node_input.id
               JOIN artifact_instances parent ON parent.id = edge.input_artifact_instance_id
               WHERE node_input.node_version_id = attempt.node_version_id
                 AND node_input.artifact_type = 'node_input'
                 AND parent.id = taint.artifact_instance_id
             )
           )
       ))
     );
END;

CREATE TRIGGER sealed_workspace_records_all_benchmark_commit_taints
AFTER UPDATE OF state, output_commit ON workspaces
WHEN NEW.state = 'sealed' AND OLD.state <> 'sealed'
BEGIN
  INSERT OR IGNORE INTO workspace_commit_taints(
    id, repository_id, commit_id, preregistration_digest, task_id, arm,
    source_attempt_id, source_kind, source_artifact_instance_id,
    source_blob_digest, created_at_ms
  )
  SELECT 'commit-taint:' || NEW.repository_id || ':' || NEW.output_commit || ':'
           || taint.preregistration_digest || ':' || taint.task_id || ':' || taint.arm,
         NEW.repository_id, NEW.output_commit, taint.preregistration_digest,
         taint.task_id, taint.arm, NEW.attempt_id,
         'artifact_instance', taint.artifact_instance_id, taint.blob_digest,
         (unixepoch('subsec') * 1000)
  FROM artifact_instance_taints taint
  WHERE EXISTS (
      SELECT 1 FROM artifact_instances output
      WHERE output.producer_attempt_id = NEW.attempt_id
        AND output.id = taint.artifact_instance_id
    )
    OR EXISTS (
      SELECT 1
      FROM attempts attempt
      JOIN artifact_instances node_input ON node_input.node_version_id = attempt.node_version_id
      JOIN artifact_inputs edge ON edge.artifact_instance_id = node_input.id
      JOIN artifact_instances parent ON parent.id = edge.input_artifact_instance_id
      WHERE attempt.id = NEW.attempt_id
        AND node_input.artifact_type = 'node_input'
        AND parent.id = taint.artifact_instance_id
    );
END;

CREATE TRIGGER sealed_benchmark_workspace_is_unconditionally_tainted
AFTER UPDATE OF state, output_commit ON workspaces
WHEN NEW.state = 'sealed' AND OLD.state <> 'sealed'
BEGIN
  INSERT OR IGNORE INTO workspace_commit_taints(
    id, repository_id, commit_id, preregistration_digest, task_id, arm,
    source_attempt_id, source_kind, source_artifact_instance_id,
    source_blob_digest, created_at_ms
  )
  SELECT 'commit-taint:' || NEW.repository_id || ':' || NEW.output_commit || ':'
           || run.benchmark_preregistration_digest || ':'
           || run.benchmark_task_id || ':' || run.benchmark_arm,
         NEW.repository_id, NEW.output_commit,
         run.benchmark_preregistration_digest, run.benchmark_task_id, run.benchmark_arm,
         NEW.attempt_id, 'benchmark_workspace', NULL, NULL,
         (unixepoch('subsec') * 1000)
  FROM attempts attempt
  JOIN runs run ON run.id = attempt.run_id
  WHERE attempt.id = NEW.attempt_id
    AND run.benchmark_preregistration_digest IS NOT NULL;
END;

CREATE TRIGGER tainted_instance_records_existing_sealed_workspace
AFTER INSERT ON artifact_instance_taints
BEGIN
  INSERT OR IGNORE INTO workspace_commit_taints(
    id, repository_id, commit_id, preregistration_digest, task_id, arm,
    source_attempt_id, source_kind, source_artifact_instance_id,
    source_blob_digest, created_at_ms
  )
  SELECT 'commit-taint:' || workspace.repository_id || ':' || workspace.output_commit || ':'
           || NEW.preregistration_digest || ':' || NEW.task_id || ':' || NEW.arm,
         workspace.repository_id, workspace.output_commit,
         NEW.preregistration_digest, NEW.task_id, NEW.arm,
         workspace.attempt_id, 'artifact_instance', NEW.artifact_instance_id,
         NEW.blob_digest, (unixepoch('subsec') * 1000)
  FROM workspaces workspace
  WHERE workspace.state = 'sealed'
    AND (
      EXISTS (
        SELECT 1 FROM artifact_instances output
        WHERE output.id = NEW.artifact_instance_id
          AND output.producer_attempt_id = workspace.attempt_id
      )
      OR EXISTS (
        SELECT 1
        FROM attempts attempt
        JOIN artifact_instances node_input ON node_input.node_version_id = attempt.node_version_id
        JOIN artifact_inputs edge ON edge.artifact_instance_id = node_input.id
        WHERE attempt.id = workspace.attempt_id
          AND node_input.artifact_type = 'node_input'
          AND edge.input_artifact_instance_id = NEW.artifact_instance_id
      )
    );
END;

