CREATE TRIGGER repository_creates_taint_state
AFTER INSERT ON repositories
BEGIN
  INSERT INTO repository_taint_state(repository_id, revision, updated_at_ms)
  VALUES(NEW.id, 0, NEW.created_at_ms);
END;

CREATE TRIGGER workspace_commit_taint_advances_repository_revision
AFTER INSERT ON workspace_commit_taints
BEGIN
  UPDATE repository_taint_state
  SET revision = revision + 1,
      updated_at_ms = NEW.created_at_ms
  WHERE repository_id = NEW.repository_id;
END;

CREATE TRIGGER repository_taint_state_updates_are_monotonic
BEFORE UPDATE ON repository_taint_state
BEGIN
  SELECT RAISE(ABORT, 'repository taint revision must advance exactly once per committed taint')
  WHERE NEW.repository_id <> OLD.repository_id
     OR NEW.revision <> OLD.revision + 1
     OR NEW.updated_at_ms < OLD.updated_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM workspace_commit_taints taint
       WHERE taint.repository_id = NEW.repository_id
         AND taint.created_at_ms = NEW.updated_at_ms
     );
END;

CREATE TRIGGER repository_taint_state_no_delete
BEFORE DELETE ON repository_taint_state
BEGIN SELECT RAISE(ABORT, 'repository taint state is durable'); END;

CREATE TRIGGER commit_lineage_attestation_is_exact_current_and_clean
BEFORE INSERT ON commit_lineage_attestations
BEGIN
  SELECT RAISE(ABORT, 'commit-lineage attestation is stale, incomplete, tainted, or unverified')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.repository_id') IS NOT NEW.repository_id
     OR json_extract(NEW.canonical_json, '$.candidate_commit') IS NOT NEW.candidate_commit
     OR json_extract(NEW.canonical_json, '$.reachable_commit_set_manifest_digest') IS NOT NEW.reachable_commit_set_manifest_digest
     OR json_extract(NEW.canonical_json, '$.repository_taint_revision') IS NOT NEW.repository_taint_revision
     OR json_extract(NEW.canonical_json, '$.verifier_closure_digest') IS NOT NEW.verifier_closure_digest
     OR json_extract(NEW.canonical_json, '$.verdict') IS NOT NEW.verdict
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM repository_taint_state taint_state
       JOIN artifact_manifests reachable
         ON reachable.digest = NEW.reachable_commit_set_manifest_digest
       JOIN current_valid_keys reachable_key
         ON reachable_key.key_id = reachable.signer_key_id
        AND reachable_key.key_purpose = 'artifact_broker'
       JOIN configuration_artifacts verifier
         ON verifier.digest = NEW.verifier_closure_digest
        AND verifier.artifact_kind = 'git_lineage_verifier_closure'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       WHERE taint_state.repository_id = NEW.repository_id
         AND taint_state.revision = NEW.repository_taint_revision
         AND json_extract(reachable.canonical_json, '$.artifact_type') = 'reachable_commit_set'
         AND json_extract(reachable.canonical_json, '$.repository_id') = NEW.repository_id
         AND json_extract(reachable.canonical_json, '$.candidate_commit') = NEW.candidate_commit
         AND json_type(reachable.canonical_json, '$.reachable_commits') = 'array'
         AND EXISTS (
           SELECT 1 FROM json_each(reachable.canonical_json, '$.reachable_commits') commit_member
           WHERE commit_member.value = NEW.candidate_commit
         )
         AND NOT EXISTS (
           SELECT 1
           FROM json_each(reachable.canonical_json, '$.reachable_commits') commit_member
           JOIN workspace_commit_taints taint
             ON taint.repository_id = NEW.repository_id
            AND taint.commit_id = commit_member.value
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = verifier.digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'commit_lineage_attestation'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.validator_closure_digest = json_extract(
           (SELECT verifier.canonical_json FROM configuration_artifacts verifier
            WHERE verifier.digest = NEW.verifier_closure_digest),
           '$.validator_closure_digest'
         )
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

