CREATE TRIGGER gate_invalidation_requires_exact_authorization
BEFORE INSERT ON gate_invalidations
BEGIN
  SELECT RAISE(ABORT, 'gate invalidation does not match its current project authorization')
  WHERE NOT EXISTS (
    SELECT 1
    FROM authority_change_authorizations a
    JOIN gate_bundles gb ON gb.digest = NEW.gate_bundle_digest
    JOIN control_state ctl ON ctl.current_term = a.leader_term
    JOIN leader_terms lt ON lt.term = a.leader_term AND lt.state = 'active'
    WHERE a.id = NEW.authorization_id
      AND a.target_kind = 'gate_bundle'
      AND a.target_id = NEW.gate_bundle_digest
      AND a.project_id = gb.project_id
      AND a.actor_principal_id = NEW.invalidated_by_principal_id
      AND a.action = 'invalidate'
      AND a.expires_at_ms >= NEW.invalidated_at_ms
  );
END;

