CREATE TRIGGER fairness_policy_is_exact_signed_projection
BEFORE INSERT ON fairness_policies
BEGIN
  SELECT RAISE(ABORT, 'fairness policy is not an exact current signed policy projection')
  WHERE NEW.version <> 1
     OR NEW.revision <> 0
     OR NEW.updated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.updated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1
       FROM policies policy
       JOIN current_valid_keys policy_key
         ON policy_key.key_id = policy.signer_key_id
        AND policy_key.key_purpose = 'control_plane'
       JOIN json_each(policy.canonical_json, '$.fairness_pools') member
       WHERE policy.digest = NEW.policy_digest
         AND policy.policy_type = 'scheduler_fairness'
         AND policy.version = NEW.version
         AND json_extract(member.value, '$.pool') = NEW.pool
         AND json_extract(member.value, '$.quantum_units') = NEW.quantum_units
         AND json_extract(member.value, '$.max_deficit_units') = NEW.max_deficit_units
         AND json_extract(member.value, '$.aging_threshold_ms') = NEW.aging_threshold_ms
         AND json_extract(member.value, '$.max_wait_ms') = NEW.max_wait_ms
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = policy.digest
         )
     );
END;

CREATE TRIGGER benchmark_preregistration_is_frozen_and_signed
BEFORE INSERT ON benchmark_preregistrations
BEGIN
  SELECT RAISE(ABORT, 'benchmark preregistration is not frozen, exact, or control-plane signed')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.campaign_id') IS NOT NEW.campaign_id
     OR json_extract(NEW.canonical_json, '$.version') IS NOT NEW.version
     OR json_extract(NEW.canonical_json, '$.task_set_manifest_digest') IS NOT NEW.task_set_manifest_digest
     OR json_extract(NEW.canonical_json, '$.evaluation_rubric_policy_digest') IS NOT NEW.evaluation_rubric_policy_digest
     OR json_extract(NEW.canonical_json, '$.randomization_commitment_digest') IS NOT NEW.randomization_commitment_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR json_type(NEW.canonical_json, '$.tasks') <> 'array'
     OR json_array_length(NEW.canonical_json, '$.tasks') < 1
     OR json_array_length(NEW.canonical_json, '$.tasks') <> (
       SELECT COUNT(DISTINCT json_extract(task.value, '$.task_id'))
       FROM json_each(NEW.canonical_json, '$.tasks') task
       WHERE json_type(task.value, '$.task_id') = 'text'
     )
     OR length(NEW.randomization_commitment_digest) <> 71
     OR substr(NEW.randomization_commitment_digest, 1, 7) <> 'sha256:'
     OR substr(NEW.randomization_commitment_digest, 8) GLOB '*[^0-9a-f]*'
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys signer_key
       JOIN principals signer ON signer.id = signer_key.principal_id
       JOIN policies rubric ON rubric.digest = NEW.evaluation_rubric_policy_digest
       JOIN current_valid_keys rubric_key
         ON rubric_key.key_id = rubric.signer_key_id
        AND rubric_key.key_purpose = 'control_plane'
       WHERE signer_key.key_id = NEW.signer_key_id
         AND signer_key.principal_id = NEW.signer_principal_id
         AND signer_key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
         AND rubric.policy_type = 'benchmark_evaluation'
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = rubric.digest
         )
         AND EXISTS (
           SELECT 1
           FROM artifact_manifests task_set
           JOIN current_valid_keys task_set_key
             ON task_set_key.key_id = task_set.signer_key_id
            AND task_set_key.key_purpose = 'artifact_broker'
           WHERE task_set.digest = NEW.task_set_manifest_digest
             AND json_extract(task_set.canonical_json, '$.artifact_type') = 'sanitized_assets'
             AND json_extract(task_set.canonical_json, '$.benchmark.preregistration_digest')
                   = NEW.digest
             AND json(json_extract(task_set.canonical_json, '$.benchmark.tasks'))
                   = json(json_extract(NEW.canonical_json, '$.tasks'))
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_preregistration'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

CREATE TRIGGER benchmark_prompt_source_is_exact_content_addressed_input
BEFORE INSERT ON benchmark_prompt_sources
BEGIN
  SELECT RAISE(ABORT, 'benchmark prompt is not an exact immutable content-addressed input')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.manifest_digest') IS NOT NEW.manifest_digest
     OR json_extract(NEW.canonical_json, '$.blob_digest') IS NOT NEW.blob_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM artifact_manifests prompt
       JOIN artifact_blobs blob ON blob.digest = NEW.blob_digest
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'artifact_broker'
       WHERE prompt.digest = NEW.manifest_digest
         AND json_extract(prompt.canonical_json, '$.artifact_type') = 'sanitized_assets'
         AND json_extract(prompt.canonical_json, '$.blob_digest') = blob.digest
         AND json_extract(prompt.canonical_json, '$.benchmark_prompt.digest') = NEW.digest
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_prompt_source'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

