CREATE TRIGGER benchmark_task_is_exact_preregistered_projection
BEFORE INSERT ON benchmark_tasks
BEGIN
  SELECT RAISE(ABORT, 'benchmark task differs from frozen preregistration')
  WHERE NOT EXISTS (
    SELECT 1
    FROM benchmark_preregistrations preregistration,
         json_each(preregistration.canonical_json, '$.tasks') task
    WHERE preregistration.digest = NEW.preregistration_digest
      AND json_extract(task.value, '$.task_id') = NEW.task_id
      AND json_extract(task.value, '$.project_id') = NEW.project_id
      AND json_extract(task.value, '$.base_commit') = NEW.base_commit
      AND json_extract(task.value, '$.input_manifest_digest') = NEW.input_manifest_digest
      AND json_extract(task.value, '$.prompt_digest') = NEW.prompt_digest
      AND json_extract(task.value, '$.risk_stratum') = NEW.risk_stratum
      AND json_extract(task.value, '$.complexity_stratum') = NEW.complexity_stratum
      AND json_extract(task.value, '$.toolchain_closure_digest') = NEW.toolchain_closure_digest
      AND EXISTS (
        SELECT 1 FROM benchmark_prompt_sources prompt
        WHERE prompt.digest = NEW.prompt_digest
      )
      AND EXISTS (
        SELECT 1 FROM benchmark_task_sources source
        WHERE source.manifest_digest = NEW.input_manifest_digest
          AND source.base_commit = NEW.base_commit
      )
      AND json_type(task.value, '$.arms') = 'array'
      AND json_array_length(task.value, '$.arms') = 4
      AND (
        SELECT COUNT(DISTINCT json_extract(arm.value, '$.arm'))
        FROM json_each(task.value, '$.arms') arm
        WHERE json_extract(arm.value, '$.arm') IN ('A','B','C','D')
      ) = 4
  );
END;

