CREATE TRIGGER benchmark_arm_run_is_exact_isolated_projection
BEFORE INSERT ON benchmark_arm_runs
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm run differs from preregistration or isolation contract')
  WHERE NEW.isolation_namespace NOT LIKE '/usr/local/var/cortex-harness/benchmarks/%'
     OR instr(NEW.isolation_namespace, '..') <> 0
     OR instr(NEW.isolation_namespace, '%') <> 0
     OR instr(NEW.isolation_namespace, '_') <> 0
     OR instr(NEW.isolation_namespace, '//') <> 0
     OR substr(NEW.isolation_namespace, -1) = '/'
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_tasks task
       JOIN benchmark_preregistrations preregistration
         ON preregistration.digest = task.preregistration_digest
       JOIN json_each(preregistration.canonical_json, '$.tasks') task_json
       JOIN json_each(task_json.value, '$.arms') arm_json
       WHERE task.preregistration_digest = NEW.preregistration_digest
         AND task.task_id = NEW.task_id
         AND NEW.base_commit = task.base_commit
         AND NEW.prompt_digest = task.prompt_digest
         AND NEW.toolchain_closure_digest = task.toolchain_closure_digest
         AND json_extract(task_json.value, '$.task_id') = NEW.task_id
         AND json_extract(arm_json.value, '$.arm') = NEW.arm
         AND json_extract(arm_json.value, '$.arm_execution_id') = NEW.arm_execution_id
         AND json_extract(arm_json.value, '$.project_id') = NEW.project_id
         AND json_extract(arm_json.value, '$.inference_budget_digest') = NEW.inference_budget_digest
         AND json_extract(arm_json.value, '$.planning_template_manifest_digest')
             = NEW.planning_template_manifest_digest
         AND json_extract(arm_json.value, '$.treatment_spec_manifest_digest')
             = NEW.treatment_spec_manifest_digest
         AND json_extract(arm_json.value, '$.randomized_order') = NEW.randomized_order
         AND json_extract(arm_json.value, '$.release_eligible') = 0
         AND EXISTS (
           SELECT 1
           FROM artifact_manifests template
           JOIN current_valid_keys template_key
             ON template_key.key_id = template.signer_key_id
            AND template_key.key_purpose = 'artifact_broker'
           WHERE template.digest = NEW.planning_template_manifest_digest
             AND json_extract(template.canonical_json, '$.artifact_type') = 'planning_template'
             AND json_extract(template.canonical_json, '$.project_id') = NEW.project_id
             AND json_extract(template.canonical_json, '$.benchmark.preregistration_digest')
                 = NEW.preregistration_digest
             AND json_extract(template.canonical_json, '$.benchmark.task_id') = NEW.task_id
             AND json_extract(template.canonical_json, '$.benchmark.arm') = NEW.arm
             AND json_extract(template.canonical_json, '$.benchmark.base_commit') = NEW.base_commit
             AND json_extract(template.canonical_json, '$.benchmark.input_manifest_digest')
                 = task.input_manifest_digest
             AND json_extract(template.canonical_json, '$.benchmark.prompt_digest') = NEW.prompt_digest
             AND json_extract(template.canonical_json, '$.benchmark.toolchain_closure_digest')
                 = NEW.toolchain_closure_digest
             AND json_extract(template.canonical_json, '$.benchmark.inference_budget_digest')
                 = NEW.inference_budget_digest
             AND json_extract(template.canonical_json, '$.benchmark.treatment_spec_manifest_digest')
                 = NEW.treatment_spec_manifest_digest
             AND json_type(template.canonical_json, '$.plan.nodes') = 'array'
             AND json_type(template.canonical_json, '$.plan.edges') = 'array'
             AND json_extract(template.canonical_json, '$.plan.final_author_logical_node_id') IS NOT NULL
             AND EXISTS (
               SELECT 1
               FROM artifact_manifests treatment
               JOIN current_valid_keys treatment_key
                 ON treatment_key.key_id = treatment.signer_key_id
                AND treatment_key.key_purpose = 'artifact_broker'
               WHERE treatment.digest = NEW.treatment_spec_manifest_digest
                 AND json_extract(treatment.canonical_json, '$.artifact_type') = 'evidence'
                 AND json_extract(treatment.canonical_json, '$.benchmark_treatment.arm') = NEW.arm
                 AND json_extract(treatment.canonical_json, '$.benchmark_treatment.planning_graph_digest')
                       = json_extract(template.canonical_json, '$.plan.graph_digest')
                 AND json_extract(treatment.canonical_json, '$.benchmark_treatment.critique_mode')
                       = CASE NEW.arm
                         WHEN 'A' THEN 'none'
                         WHEN 'B' THEN 'single_blind_challenge'
                         WHEN 'C' THEN 'dialectical'
                         WHEN 'D' THEN 'independent_summary_control'
                       END
                 AND json_type(treatment.canonical_json, '$.benchmark_treatment.delivery_graph_digest') = 'text'
                 AND json_type(treatment.canonical_json, '$.benchmark_treatment.ordered_model_call_cells_digest') = 'text'
             )
         )
     )
     OR (NEW.arm IN ('C','D') AND NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration,
            json_each(preregistration.canonical_json, '$.tasks') task_json,
            json_each(task_json.value, '$.arms') arm_c,
            json_each(task_json.value, '$.arms') arm_d
       WHERE preregistration.digest = NEW.preregistration_digest
         AND json_extract(task_json.value, '$.task_id') = NEW.task_id
         AND json_extract(arm_c.value, '$.arm') = 'C'
         AND json_extract(arm_d.value, '$.arm') = 'D'
         AND json_extract(arm_c.value, '$.inference_budget_digest')
             = json_extract(arm_d.value, '$.inference_budget_digest')
         AND EXISTS (
           SELECT 1
           FROM artifact_manifests treatment_c
           JOIN artifact_manifests treatment_d
           WHERE treatment_c.digest = json_extract(arm_c.value, '$.treatment_spec_manifest_digest')
             AND treatment_d.digest = json_extract(arm_d.value, '$.treatment_spec_manifest_digest')
             AND json_extract(treatment_c.canonical_json, '$.benchmark_treatment.ordered_model_call_cells_digest')
                   = json_extract(treatment_d.canonical_json, '$.benchmark_treatment.ordered_model_call_cells_digest')
         )
     ));
END;

