BEFORE UPDATE ON benchmark_arm_runs
BEGIN SELECT RAISE(ABORT, 'benchmark arm bindings are immutable'); END;

CREATE TRIGGER benchmark_arm_runs_no_delete
BEFORE DELETE ON benchmark_arm_runs
BEGIN SELECT RAISE(ABORT, 'benchmark arm bindings are immutable'); END;

CREATE TRIGGER benchmark_arm_run_member_is_contiguous_and_exact
BEFORE INSERT ON benchmark_arm_run_members
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm run member is not a contiguous isolated phase')
  WHERE NEW.phase_no <> COALESCE((
      SELECT MAX(member.phase_no) + 1
      FROM benchmark_arm_run_members member
      WHERE member.arm_execution_id = NEW.arm_execution_id
    ), 1)
     OR NEW.phase_no > 2
     OR NEW.run_kind <> CASE WHEN NEW.phase_no % 2 = 1 THEN 'planning' ELSE 'delivery' END
     OR (NEW.phase_no = 1 AND EXISTS (
       SELECT 1
       FROM benchmark_arm_runs current_arm
       JOIN benchmark_arm_runs earlier_arm
         ON earlier_arm.preregistration_digest = current_arm.preregistration_digest
        AND earlier_arm.task_id = current_arm.task_id
        AND earlier_arm.randomized_order < current_arm.randomized_order
       WHERE current_arm.arm_execution_id = NEW.arm_execution_id
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_run_members earlier_member
           WHERE earlier_member.arm_execution_id = earlier_arm.arm_execution_id
             AND earlier_member.phase_no = 1
         )
     ))
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN runs run ON run.id = NEW.run_id
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND run.project_id = arm.project_id
         AND run.run_kind = NEW.run_kind
         AND run.benchmark_preregistration_digest = arm.preregistration_digest
         AND run.benchmark_task_id = arm.task_id
         AND run.benchmark_arm = arm.arm
         AND (
           (NEW.phase_no = 1 AND run.predecessor_run_id IS NULL)
           OR (NEW.phase_no > 1 AND run.predecessor_run_id = (
             SELECT prior.run_id
             FROM benchmark_arm_run_members prior
             WHERE prior.arm_execution_id = NEW.arm_execution_id
               AND prior.phase_no = NEW.phase_no - 1
           ))
         )
     );
END;

