CREATE TRIGGER benchmark_attempt_must_consume_next_frozen_call_cell
BEFORE INSERT ON attempts
BEGIN
  SELECT RAISE(ABORT, 'benchmark attempt is not the next exact frozen treatment call cell')
  WHERE (
    EXISTS (SELECT 1 FROM runs run
            WHERE run.id = NEW.run_id
              AND run.benchmark_preregistration_digest IS NOT NULL)
    AND (
      NEW.attempt_no <> 1
      OR NEW.benchmark_treatment_cell_id IS NULL
      OR NOT EXISTS (
        SELECT 1
        FROM benchmark_arm_run_members member
        JOIN benchmark_arm_runs arm ON arm.arm_execution_id = member.arm_execution_id
        JOIN benchmark_treatment_call_cells cell
          ON cell.id = NEW.benchmark_treatment_cell_id
         AND cell.preregistration_digest = arm.preregistration_digest
         AND cell.arm = arm.arm
         AND cell.phase_no = member.phase_no
        JOIN node_versions node ON node.id = NEW.node_version_id
        JOIN executors executor ON executor.id = NEW.executor_id
        JOIN pricing_catalogs catalog ON catalog.digest = NEW.pricing_catalog_digest
        WHERE member.run_id = NEW.run_id
          AND arm.task_id = (SELECT run.benchmark_task_id FROM runs run WHERE run.id = NEW.run_id)
          AND cell.cell_no = COALESCE((
            SELECT COUNT(*) + 1
            FROM benchmark_realized_call_cells prior
            WHERE prior.arm_execution_id = arm.arm_execution_id
          ), 1)
          AND node.run_id = NEW.run_id
          AND node.stage = cell.stage
          AND node.required_pool = cell.required_pool
          AND node.required_capability = cell.required_capability
          AND executor.pool = cell.required_pool
          AND catalog.provider = cell.expected_provider
          AND NEW.runtime = cell.runtime
          AND NEW.requested_model = cell.requested_model
          AND NEW.requested_profile = cell.requested_profile
          AND NEW.model = cell.expected_model
          AND NEW.model_family = cell.expected_model_family
          AND NEW.profile = cell.expected_profile
          AND NEW.max_input_tokens = cell.max_input_tokens
          AND NEW.max_output_tokens = cell.max_output_tokens
          AND NEW.max_cache_read_tokens = cell.max_cache_read_tokens
          AND NEW.max_cache_write_tokens = cell.max_cache_write_tokens
          AND NEW.max_tool_calls = cell.max_tool_calls
          AND NEW.max_wall_time_ms = cell.max_wall_time_ms
          AND NEW.required_reservation_micro_usd = cell.required_reservation_micro_usd
          AND NOT EXISTS (
            SELECT 1 FROM benchmark_campaign_invalidations invalidation
            WHERE invalidation.preregistration_digest = arm.preregistration_digest
          )
      )
    )
  )
  OR (
    NOT EXISTS (SELECT 1 FROM runs run
                WHERE run.id = NEW.run_id
                  AND run.benchmark_preregistration_digest IS NOT NULL)
    AND NEW.benchmark_treatment_cell_id IS NOT NULL
  );
END;

CREATE TRIGGER benchmark_realized_call_cell_is_exact_authoritative_binding
BEFORE INSERT ON benchmark_realized_call_cells
BEGIN
  SELECT RAISE(ABORT, 'realized benchmark call cell is not derived from its actual attempt')
  WHERE NEW.bound_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.bound_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.cell_no <> COALESCE((
       SELECT MAX(prior.cell_no) + 1 FROM benchmark_realized_call_cells prior
       WHERE prior.arm_execution_id = NEW.arm_execution_id
     ), 1)
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.cell_no') IS NOT NEW.cell_no
     OR json_extract(NEW.canonical_json, '$.treatment_cell_id') IS NOT NEW.treatment_cell_id
     OR json_extract(NEW.canonical_json, '$.attempt_id') IS NOT NEW.attempt_id
     OR json_extract(NEW.canonical_json, '$.phase_no') IS NOT NEW.phase_no
     OR json_extract(NEW.canonical_json, '$.stage') IS NOT NEW.stage
     OR json_extract(NEW.canonical_json, '$.provider') IS NOT NEW.provider
     OR json_extract(NEW.canonical_json, '$.runtime') IS NOT NEW.runtime
     OR json_extract(NEW.canonical_json, '$.requested_model') IS NOT NEW.requested_model
     OR json_extract(NEW.canonical_json, '$.requested_profile') IS NOT NEW.requested_profile
     OR json_extract(NEW.canonical_json, '$.model') IS NOT NEW.model
     OR json_extract(NEW.canonical_json, '$.model_family') IS NOT NEW.model_family
     OR json_extract(NEW.canonical_json, '$.profile') IS NOT NEW.profile
     OR json_extract(NEW.canonical_json, '$.max_input_tokens') IS NOT NEW.max_input_tokens
     OR json_extract(NEW.canonical_json, '$.max_output_tokens') IS NOT NEW.max_output_tokens
     OR json_extract(NEW.canonical_json, '$.max_cache_read_tokens') IS NOT NEW.max_cache_read_tokens
     OR json_extract(NEW.canonical_json, '$.max_cache_write_tokens') IS NOT NEW.max_cache_write_tokens
     OR json_extract(NEW.canonical_json, '$.max_tool_calls') IS NOT NEW.max_tool_calls
     OR json_extract(NEW.canonical_json, '$.max_wall_time_ms') IS NOT NEW.max_wall_time_ms
     OR json_extract(NEW.canonical_json, '$.required_reservation_micro_usd') IS NOT NEW.required_reservation_micro_usd
     OR json_extract(NEW.canonical_json, '$.parity_cell_digest') IS NOT NEW.parity_cell_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.bound_at_ms') IS NOT NEW.bound_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_arm_run_members member
         ON member.arm_execution_id = arm.arm_execution_id
       JOIN attempts attempt ON attempt.id = NEW.attempt_id AND attempt.run_id = member.run_id
       JOIN node_versions node ON node.id = attempt.node_version_id
       JOIN executors executor ON executor.id = attempt.executor_id
       JOIN pricing_catalogs catalog ON catalog.digest = attempt.pricing_catalog_digest
       JOIN benchmark_treatment_call_cells cell
         ON cell.id = NEW.treatment_cell_id
        AND cell.id = attempt.benchmark_treatment_cell_id
        AND cell.preregistration_digest = arm.preregistration_digest
        AND cell.arm = arm.arm AND cell.cell_no = NEW.cell_no
        AND cell.phase_no = member.phase_no
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND attempt.state = 'created'
         AND node.stage = NEW.stage AND node.stage = cell.stage
         AND node.required_pool = cell.required_pool
         AND node.required_capability = cell.required_capability
         AND executor.pool = cell.required_pool
         AND catalog.provider = NEW.provider AND NEW.provider = cell.expected_provider
         AND attempt.runtime = NEW.runtime AND NEW.runtime = cell.runtime
         AND attempt.requested_model = NEW.requested_model AND NEW.requested_model = cell.requested_model
         AND attempt.requested_profile = NEW.requested_profile AND NEW.requested_profile = cell.requested_profile
         AND attempt.model = NEW.model AND NEW.model = cell.expected_model
         AND attempt.model_family = NEW.model_family AND NEW.model_family = cell.expected_model_family
         AND attempt.profile = NEW.profile AND NEW.profile = cell.expected_profile
         AND attempt.max_input_tokens = NEW.max_input_tokens AND NEW.max_input_tokens = cell.max_input_tokens
         AND attempt.max_output_tokens = NEW.max_output_tokens AND NEW.max_output_tokens = cell.max_output_tokens
         AND attempt.max_cache_read_tokens = NEW.max_cache_read_tokens AND NEW.max_cache_read_tokens = cell.max_cache_read_tokens
         AND attempt.max_cache_write_tokens = NEW.max_cache_write_tokens AND NEW.max_cache_write_tokens = cell.max_cache_write_tokens
         AND attempt.max_tool_calls = NEW.max_tool_calls AND NEW.max_tool_calls = cell.max_tool_calls
         AND attempt.max_wall_time_ms = NEW.max_wall_time_ms AND NEW.max_wall_time_ms = cell.max_wall_time_ms
         AND attempt.required_reservation_micro_usd = NEW.required_reservation_micro_usd
         AND NEW.required_reservation_micro_usd = cell.required_reservation_micro_usd
         AND NEW.phase_no = member.phase_no
         AND NEW.parity_cell_digest = cell.parity_cell_digest
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_realized_call_cell'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.parity_cell_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.bound_at_ms - 5000 AND NEW.bound_at_ms
     );
END;

