CREATE TRIGGER benchmark_attempt_dispatch_requires_realized_call_cell
BEFORE UPDATE OF state ON attempts
WHEN OLD.state = 'created' AND NEW.state = 'dispatched'
 AND EXISTS (SELECT 1 FROM runs run
             WHERE run.id = NEW.run_id
               AND run.benchmark_preregistration_digest IS NOT NULL)
BEGIN
  SELECT RAISE(ABORT, 'benchmark dispatch lacks its exact realized call-cell binding')
  WHERE NOT EXISTS (
    SELECT 1 FROM benchmark_realized_call_cells realized
    WHERE realized.attempt_id = NEW.id
      AND realized.treatment_cell_id = NEW.benchmark_treatment_cell_id
  );
END;

CREATE TRIGGER benchmark_attempt_nonacceptance_requires_campaign_invalidation
BEFORE UPDATE OF state ON attempts
WHEN OLD.state <> NEW.state
 AND NEW.state IN ('failed','expired','cancelled','stale','quarantined','unknown')
 AND (
   EXISTS (SELECT 1 FROM runs run
           WHERE run.id = NEW.run_id
             AND run.benchmark_preregistration_digest IS NOT NULL)
   OR EXISTS (SELECT 1 FROM benchmark_blind_assignments assignment
              WHERE assignment.evaluator_attempt_id = NEW.id)
 )
BEGIN
  SELECT RAISE(ABORT, 'benchmark attempt failure is a whole-campaign protocol invalidation')
  WHERE EXISTS (
      SELECT 1 FROM runs run
      WHERE run.id = NEW.run_id
        AND run.benchmark_preregistration_digest IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM benchmark_campaign_invalidations invalidation
          WHERE invalidation.preregistration_digest = run.benchmark_preregistration_digest
        )
    )
     OR EXISTS (
      SELECT 1
      FROM benchmark_blind_assignments assignment
      JOIN benchmark_arm_runs arm
        ON arm.arm_execution_id = assignment.arm_execution_id
      WHERE assignment.evaluator_attempt_id = NEW.id
        AND NOT EXISTS (
          SELECT 1 FROM benchmark_campaign_invalidations invalidation
          WHERE invalidation.preregistration_digest = arm.preregistration_digest
        )
    );
END;

CREATE TRIGGER benchmark_arm_seed_binding_is_exact_and_signed
BEFORE INSERT ON benchmark_arm_seed_bindings
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm seed is not an exact arm-local copy of the frozen task source')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.node_version_id') IS NOT NEW.node_version_id
     OR json_extract(NEW.canonical_json, '$.input_artifact_instance_id') IS NOT NEW.input_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.source_manifest_digest') IS NOT NEW.source_manifest_digest
     OR json_extract(NEW.canonical_json, '$.source_blob_digest') IS NOT NEW.source_blob_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_tasks task
         ON task.preregistration_digest = arm.preregistration_digest
        AND task.task_id = arm.task_id
       JOIN benchmark_task_sources source
         ON source.manifest_digest = task.input_manifest_digest
        AND source.blob_digest = NEW.source_blob_digest
       JOIN benchmark_arm_run_members member
         ON member.arm_execution_id = arm.arm_execution_id
       JOIN node_versions node
         ON node.id = NEW.node_version_id
        AND node.run_id = member.run_id
       JOIN runs run ON run.id = node.run_id
       JOIN artifact_instances input_instance
         ON input_instance.id = NEW.input_artifact_instance_id
        AND input_instance.blob_digest = source.blob_digest
        AND input_instance.project_id = arm.project_id
        AND input_instance.run_id = run.id
        AND input_instance.node_version_id = node.id
        AND input_instance.producer_attempt_id IS NULL
        AND input_instance.artifact_type = 'node_input'
       JOIN artifact_manifests input_manifest
         ON input_manifest.digest = input_instance.manifest_digest
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'artifact_broker'
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND NEW.source_manifest_digest = source.manifest_digest
         AND run.benchmark_preregistration_digest = arm.preregistration_digest
         AND run.benchmark_task_id = arm.task_id
         AND run.benchmark_arm = arm.arm
         AND NOT EXISTS (
           SELECT 1 FROM node_dependencies dependency
           WHERE dependency.node_version_id = node.id
         )
         AND json_extract(input_manifest.canonical_json, '$.benchmark.source_input_manifest_digest')
             = source.manifest_digest
         AND json_extract(input_manifest.canonical_json, '$.benchmark.source_blob_digest')
             = source.blob_digest
         AND json_extract(input_manifest.canonical_json, '$.benchmark.arm_execution_id')
             = arm.arm_execution_id
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_arm_seed_binding'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

