CREATE TRIGGER benchmark_arm_settlement_is_complete_exact_and_signed
BEFORE INSERT ON benchmark_arm_settlement_seals
BEGIN
  SELECT RAISE(ABORT, 'benchmark settlement is not a complete grace-aged immutable arm snapshot')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_type(NEW.reservation_snapshot_json) <> 'array'
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.reservation_snapshot_json') IS NOT NEW.reservation_snapshot_json
     OR json_extract(NEW.canonical_json, '$.reservation_count') IS NOT NEW.reservation_count
     OR json_extract(NEW.canonical_json, '$.provider_call_count') IS NOT NEW.provider_call_count
     OR json_extract(NEW.canonical_json, '$.input_tokens') IS NOT NEW.input_tokens
     OR json_extract(NEW.canonical_json, '$.output_tokens') IS NOT NEW.output_tokens
     OR json_extract(NEW.canonical_json, '$.cache_read_tokens') IS NOT NEW.cache_read_tokens
     OR json_extract(NEW.canonical_json, '$.cache_write_tokens') IS NOT NEW.cache_write_tokens
     OR json_extract(NEW.canonical_json, '$.tool_calls') IS NOT NEW.tool_calls
     OR json_extract(NEW.canonical_json, '$.wall_time_ms') IS NOT NEW.wall_time_ms
     OR json_extract(NEW.canonical_json, '$.cost_micro_usd') IS NOT NEW.cost_micro_usd
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR NEW.reservation_count <> json_array_length(NEW.reservation_snapshot_json)
     OR EXISTS (
       SELECT 1
       FROM json_each(NEW.reservation_snapshot_json) item
       WHERE json_type(item.value) <> 'object'
          OR json_type(item.value, '$.reservation_id') <> 'text'
          OR json_type(item.value, '$.reservation_state') <> 'text'
          OR json_type(item.value, '$.closed_at_ms') <> 'integer'
          OR EXISTS (
            SELECT 1 FROM json_each(item.value) field
            WHERE field.key NOT IN (
              'reservation_id','reservation_state','closed_at_ms',
              'final_usage_event_id','final_sequence_no'
            )
          )
     )
     OR EXISTS (
       SELECT 1 FROM json_each(NEW.reservation_snapshot_json) item
       GROUP BY json_extract(item.value, '$.reservation_id')
       HAVING COUNT(*) > 1
     )
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_measured_usage measured
       JOIN current_valid_keys observer_key
         ON observer_key.key_id = NEW.signer_key_id
        AND observer_key.principal_id = NEW.signer_principal_id
        AND observer_key.key_purpose = 'provider_observer'
       JOIN principals observer
         ON observer.id = NEW.signer_principal_id
        AND observer.kind = 'service'
       WHERE measured.arm_execution_id = NEW.arm_execution_id
         AND measured.provider_call_count = NEW.provider_call_count
         AND measured.input_tokens = NEW.input_tokens
         AND measured.output_tokens = NEW.output_tokens
         AND measured.cache_read_tokens = NEW.cache_read_tokens
         AND measured.cache_write_tokens = NEW.cache_write_tokens
         AND measured.tool_calls = NEW.tool_calls
         AND measured.wall_time_ms = NEW.wall_time_ms
         AND measured.cost_micro_usd = NEW.cost_micro_usd
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_budget_breaches breach
           WHERE breach.arm_execution_id = NEW.arm_execution_id
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_arm_run_members member
           JOIN runs run ON run.id = member.run_id
           WHERE member.arm_execution_id = NEW.arm_execution_id
             AND (member.phase_no NOT IN (1,2)
               OR run.state <> 'completed'
               OR NOT EXISTS (
                 SELECT 1 FROM run_completion_seals completion
                 WHERE completion.run_id = run.id
               ))
         )
         AND (SELECT COUNT(*) FROM benchmark_arm_run_members member
              WHERE member.arm_execution_id = NEW.arm_execution_id) = 2
     )
     OR NEW.reservation_count <> (
       SELECT COUNT(*)
       FROM benchmark_arm_run_members member
       JOIN attempts attempt ON attempt.run_id = member.run_id
       JOIN charge_subjects subject
         ON subject.attempt_id = attempt.id AND subject.scope_kind = 'attempt'
       JOIN budget_reservations reservation ON reservation.charge_subject_id = subject.id
       WHERE member.arm_execution_id = NEW.arm_execution_id
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_arm_run_members member
       JOIN attempts attempt ON attempt.run_id = member.run_id
       JOIN charge_subjects subject
         ON subject.attempt_id = attempt.id AND subject.scope_kind = 'attempt'
       JOIN budget_reservations reservation ON reservation.charge_subject_id = subject.id
       WHERE member.arm_execution_id = NEW.arm_execution_id
         AND (
           reservation.state NOT IN ('consumed','released')
           OR reservation.closed_at_ms IS NULL
           OR NEW.sealed_at_ms < reservation.closed_at_ms + 900000
           OR NOT EXISTS (
             SELECT 1 FROM json_each(NEW.reservation_snapshot_json) item
             WHERE json_extract(item.value, '$.reservation_id') = reservation.id
               AND json_extract(item.value, '$.reservation_state') = reservation.state
               AND json_extract(item.value, '$.closed_at_ms') = reservation.closed_at_ms
               AND (
                 (EXISTS (SELECT 1 FROM usage_events any_usage
                          WHERE any_usage.reservation_id = reservation.id)
                   AND EXISTS (
                     SELECT 1 FROM usage_events final_usage
                     WHERE final_usage.reservation_id = reservation.id
                       AND final_usage.sequence_no = (
                         SELECT MAX(latest.sequence_no) FROM usage_events latest
                         WHERE latest.reservation_id = reservation.id
                       )
                       AND final_usage.final_marker = 1
                       AND json_extract(item.value, '$.final_usage_event_id') = final_usage.id
                       AND json_extract(item.value, '$.final_sequence_no') = final_usage.sequence_no
                   ))
                 OR (NOT EXISTS (SELECT 1 FROM usage_events any_usage
                                 WHERE any_usage.reservation_id = reservation.id)
                   AND json_type(item.value, '$.final_usage_event_id') = 'null'
                   AND json_type(item.value, '$.final_sequence_no') = 'null'
                   AND EXISTS (
                     SELECT 1 FROM reconciliation_decisions reconciliation
                     WHERE reconciliation.subject_kind = 'budget_reservation'
                       AND reconciliation.subject_id = reservation.id
                       AND reconciliation.resolved_state = 'released'
                   ))
               )
           )
         )
     )
     OR EXISTS (
       SELECT 1
       FROM json_each(NEW.reservation_snapshot_json) item
       WHERE NOT EXISTS (
         SELECT 1
         FROM benchmark_arm_run_members member
         JOIN attempts attempt ON attempt.run_id = member.run_id
         JOIN charge_subjects subject
           ON subject.attempt_id = attempt.id AND subject.scope_kind = 'attempt'
         JOIN budget_reservations reservation ON reservation.charge_subject_id = subject.id
         WHERE member.arm_execution_id = NEW.arm_execution_id
           AND reservation.id = json_extract(item.value, '$.reservation_id')
       )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_arm_settlement'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

CREATE TRIGGER benchmark_arm_settlement_seals_no_update
BEFORE UPDATE ON benchmark_arm_settlement_seals
BEGIN SELECT RAISE(ABORT, 'benchmark settlement seals are immutable'); END;

CREATE TRIGGER benchmark_arm_settlement_seals_no_delete
BEFORE DELETE ON benchmark_arm_settlement_seals
BEGIN SELECT RAISE(ABORT, 'benchmark settlement seals are immutable'); END;

CREATE TRIGGER benchmark_settlement_invalidation_is_exact_late_usage
BEFORE INSERT ON benchmark_arm_settlement_invalidations
BEGIN
  SELECT RAISE(ABORT, 'settlement invalidation is not exact post-seal usage')
  WHERE NEW.id <> 'late-usage:' || NEW.settlement_digest || ':' || NEW.usage_event_id
     OR NEW.invalidated_at_ms <> (unixepoch('subsec') * 1000)
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_settlement_seals settlement,
            json_each(settlement.reservation_snapshot_json) snapshot
       JOIN usage_events usage ON usage.id = NEW.usage_event_id
       WHERE settlement.digest = NEW.settlement_digest
         AND json_extract(snapshot.value, '$.reservation_id') = usage.reservation_id
         AND usage.sequence_no > COALESCE(json_extract(snapshot.value, '$.final_sequence_no'), 0)
     );
END;

CREATE TRIGGER benchmark_late_usage_invalidates_settlement
AFTER INSERT ON usage_events
BEGIN
  INSERT OR IGNORE INTO benchmark_arm_settlement_invalidations(
    id, settlement_digest, usage_event_id, reason, invalidated_at_ms
  )
  SELECT 'late-usage:' || settlement.digest || ':' || NEW.id,
         settlement.digest, NEW.id, 'late_usage_after_settlement',
         (unixepoch('subsec') * 1000)
  FROM benchmark_arm_settlement_seals settlement,
       json_each(settlement.reservation_snapshot_json) snapshot
  WHERE json_extract(snapshot.value, '$.reservation_id') = NEW.reservation_id
    AND NEW.sequence_no > COALESCE(json_extract(snapshot.value, '$.final_sequence_no'), 0);
END;

