BEFORE UPDATE ON benchmark_arm_settlement_invalidations
BEGIN SELECT RAISE(ABORT, 'settlement invalidations are immutable'); END;

CREATE TRIGGER benchmark_arm_settlement_invalidations_no_delete
BEFORE DELETE ON benchmark_arm_settlement_invalidations
BEGIN SELECT RAISE(ABORT, 'settlement invalidations are immutable'); END;

CREATE TRIGGER benchmark_blind_assignment_is_exact_and_signed
BEFORE INSERT ON benchmark_blind_assignments
BEGIN
  SELECT RAISE(ABORT, 'benchmark blind assignment is not exact, terminal, isolated, or broker signed')
  WHERE NEW.assigned_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.assigned_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR EXISTS (
       SELECT 1 FROM benchmark_arm_budget_breaches breach
       WHERE breach.arm_execution_id = NEW.arm_execution_id
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_campaign_invalidations invalidation
         ON invalidation.preregistration_digest = arm.preregistration_digest
       WHERE arm.arm_execution_id = NEW.arm_execution_id
     )
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_settlement_seals settlement
       WHERE settlement.arm_execution_id = NEW.arm_execution_id
         AND settlement.sealed_at_ms <= NEW.assigned_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           WHERE invalidation.settlement_digest = settlement.digest
         )
     )
     OR json_extract(NEW.canonical_json, '$.blind_code') IS NOT NEW.blind_code
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.terminal_run_id') IS NOT NEW.terminal_run_id
     OR json_extract(NEW.canonical_json, '$.candidate_artifact_instance_id') IS NOT NEW.candidate_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.blinded_package_digest') IS NOT NEW.blinded_package_digest
     OR json_extract(NEW.canonical_json, '$.evaluator_attempt_id') IS NOT NEW.evaluator_attempt_id
     OR json_extract(NEW.canonical_json, '$.rubric_policy_digest') IS NOT NEW.rubric_policy_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.assigned_at_ms') IS NOT NEW.assigned_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_preregistrations preregistration
         ON preregistration.digest = arm.preregistration_digest
       JOIN benchmark_arm_run_members terminal_member
         ON terminal_member.arm_execution_id = arm.arm_execution_id
        AND terminal_member.run_id = NEW.terminal_run_id
        AND terminal_member.run_kind = 'delivery'
       JOIN runs terminal_run
         ON terminal_run.id = terminal_member.run_id
        AND terminal_run.state = 'completed'
       JOIN run_completion_seals completion
         ON completion.run_id = terminal_run.id
        AND completion.final_artifact_instance_id = NEW.candidate_artifact_instance_id
       JOIN artifact_instances candidate
         ON candidate.id = NEW.candidate_artifact_instance_id
        AND candidate.run_id = terminal_run.id
        AND candidate.artifact_type = 'node_output'
       JOIN attempts producer
         ON producer.id = candidate.producer_attempt_id
        AND producer.state = 'accepted'
       JOIN benchmark_blinded_candidate_packages package
         ON package.digest = NEW.blinded_package_digest
        AND package.arm_execution_id = arm.arm_execution_id
        AND package.blind_code = NEW.blind_code
        AND package.source_candidate_artifact_instance_id = candidate.id
       JOIN artifact_instances normalized
         ON normalized.id = package.normalized_archive_artifact_instance_id
       JOIN attempts evaluator ON evaluator.id = NEW.evaluator_attempt_id
       JOIN benchmark_evaluator_inputs evaluator_input
         ON evaluator_input.evaluator_attempt_id = evaluator.id
        AND evaluator_input.arm_execution_id = arm.arm_execution_id
        AND evaluator_input.blind_code = NEW.blind_code
        AND evaluator_input.blinded_package_digest = package.digest
        AND evaluator_input.normalized_artifact_instance_id = normalized.id
        AND evaluator_input.rubric_policy_digest = NEW.rubric_policy_digest
       JOIN executors evaluator_executor ON evaluator_executor.id = evaluator.executor_id
       JOIN executor_capabilities evaluator_capability
         ON evaluator_capability.executor_id = evaluator_executor.id
        AND evaluator_capability.capability = 'benchmark-evaluator'
        AND evaluator_capability.scope IN ('global', evaluator.project_id)
       JOIN work_packets packet ON packet.attempt_id = evaluator.id
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND preregistration.evaluation_rubric_policy_digest = NEW.rubric_policy_digest
         AND evaluator.state = 'created'
         AND evaluator.created_at_ms <= NEW.assigned_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM result_envelopes existing_result
           WHERE existing_result.attempt_id = evaluator.id
         )
         AND terminal_member.phase_no = (
           SELECT MAX(member.phase_no)
           FROM benchmark_arm_run_members member
           WHERE member.arm_execution_id = arm.arm_execution_id
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_arm_runs participant_arm
           JOIN benchmark_arm_run_members participant_member
             ON participant_member.arm_execution_id = participant_arm.arm_execution_id
           JOIN attempts participant_attempt
             ON participant_attempt.run_id = participant_member.run_id
           WHERE participant_arm.preregistration_digest = arm.preregistration_digest
             AND participant_arm.task_id = arm.task_id
             AND participant_attempt.executor_id = evaluator.executor_id
         )
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blind_code') = NEW.blind_code
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blinded_package_digest')
             = package.digest
         AND packet.input_manifest_digest = evaluator_input.detached_manifest_digest
         AND json_type(packet.canonical_json, '$.benchmark') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.candidate_manifest_digest') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.source_candidate_artifact_instance_id') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.arm') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.task_id') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.preregistration_digest') IS NULL
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_blind_assignment'
         AND receipt.record_id = NEW.blind_code
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.assigned_at_ms - 5000 AND NEW.assigned_at_ms
     );
END;

