BEFORE UPDATE ON benchmark_blind_assignments
BEGIN SELECT RAISE(ABORT, 'benchmark blind assignments are immutable'); END;

CREATE TRIGGER benchmark_blind_assignments_no_delete
BEFORE DELETE ON benchmark_blind_assignments
BEGIN SELECT RAISE(ABORT, 'benchmark blind assignments are immutable'); END;

CREATE TRIGGER benchmark_hidden_test_observation_is_exact_independent_and_signed
BEFORE INSERT ON benchmark_hidden_test_observations
BEGIN
  SELECT RAISE(ABORT, 'hidden-test observation is not exact, post-assignment, independent, or validator signed')
  WHERE NEW.observed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.observed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.blind_code') IS NOT NEW.blind_code
     OR json_extract(NEW.canonical_json, '$.evaluator_attempt_id') IS NOT NEW.evaluator_attempt_id
     OR json_extract(NEW.canonical_json, '$.hidden_test_pass') IS NOT NEW.hidden_test_pass
     OR json_extract(NEW.canonical_json, '$.security_pass') IS NOT NEW.security_pass
     OR json_extract(NEW.canonical_json, '$.p95_latency_ms') IS NOT NEW.p95_latency_ms
     OR json_extract(NEW.canonical_json, '$.metrics_json') IS NOT NEW.metrics_json
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.observed_at_ms') IS NOT NEW.observed_at_ms
     OR json_extract(NEW.metrics_json, '$.hidden_test_pass') IS NOT NEW.hidden_test_pass
     OR json_extract(NEW.metrics_json, '$.security_pass') IS NOT NEW.security_pass
     OR json_extract(NEW.metrics_json, '$.p95_latency_ms') IS NOT NEW.p95_latency_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_blind_assignments assignment
       JOIN benchmark_arm_settlement_seals settlement
         ON settlement.arm_execution_id = assignment.arm_execution_id
       JOIN attempts evaluator
         ON evaluator.id = assignment.evaluator_attempt_id
        AND evaluator.id = NEW.evaluator_attempt_id
        AND evaluator.state = 'accepted'
       JOIN result_envelopes result
         ON result.attempt_id = evaluator.id AND result.state = 'accepted'
       JOIN benchmark_evaluator_output_bindings output_binding
         ON output_binding.evaluator_attempt_id = evaluator.id
        AND output_binding.result_envelope_id = result.id
        AND output_binding.output_manifest_digest = result.output_manifest_digest
       JOIN artifact_instance_taints output_taint
         ON output_taint.artifact_instance_id = output_binding.output_artifact_instance_id
        AND output_taint.preregistration_digest = output_binding.preregistration_digest
        AND output_taint.task_id = output_binding.task_id
        AND output_taint.arm = output_binding.arm
        AND output_taint.reason = 'benchmark_evaluator_output'
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN principals validator
         ON validator.id = NEW.signer_principal_id
        AND validator.kind = 'service'
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       WHERE assignment.blind_code = NEW.blind_code
         AND output_binding.arm_execution_id = assignment.arm_execution_id
         AND output_binding.output_manifest_digest = NEW.evidence_manifest_digest
         AND assignment.assigned_at_ms <= evaluator.started_at_ms
         AND evaluator.started_at_ms <= result.received_at_ms
         AND result.received_at_ms <= NEW.observed_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           WHERE invalidation.settlement_digest = settlement.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_budget_breaches breach
           WHERE breach.arm_execution_id = assignment.arm_execution_id
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_hidden_test_observation'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.observed_at_ms - 5000 AND NEW.observed_at_ms
     );
END;

