CREATE TRIGGER benchmark_invalidated_campaign_rejects_hidden_test_observation
BEFORE INSERT ON benchmark_hidden_test_observations
WHEN EXISTS (
  SELECT 1
  FROM benchmark_blind_assignments assignment
  JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
  JOIN benchmark_campaign_invalidations invalidation
    ON invalidation.preregistration_digest = arm.preregistration_digest
  WHERE assignment.blind_code = NEW.blind_code
)
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot record hidden evaluation');
END;

CREATE TRIGGER benchmark_evaluation_is_blind_exact_and_signed
BEFORE INSERT ON benchmark_evaluations
BEGIN
  SELECT RAISE(ABORT, 'benchmark evaluation is not blind, exact, independent, or signed')
  WHERE EXISTS (
       SELECT 1
       FROM benchmark_blind_assignments assignment
       JOIN benchmark_arm_budget_breaches breach
         ON breach.arm_execution_id = assignment.arm_execution_id
       WHERE assignment.blind_code = NEW.blind_code
     )
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_blind_assignments assignment
       JOIN benchmark_arm_settlement_seals settlement
         ON settlement.arm_execution_id = assignment.arm_execution_id
       WHERE assignment.blind_code = NEW.blind_code
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           WHERE invalidation.settlement_digest = settlement.digest
         )
     )
     OR NEW.evaluated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.evaluated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.task_id') IS NOT NEW.task_id
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.blind_code') IS NOT NEW.blind_code
     OR json_extract(NEW.canonical_json, '$.evaluator_attempt_id') IS NOT NEW.evaluator_attempt_id
     OR json_extract(NEW.canonical_json, '$.evaluator_output_binding_digest') IS NOT NEW.evaluator_output_binding_digest
     OR json_extract(NEW.canonical_json, '$.hidden_test_observation_id') IS NOT NEW.hidden_test_observation_id
     OR json_extract(NEW.canonical_json, '$.rubric_policy_digest') IS NOT NEW.rubric_policy_digest
     OR json_extract(NEW.canonical_json, '$.metrics_json') IS NOT NEW.metrics_json
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.evaluated_at_ms') IS NOT NEW.evaluated_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN benchmark_arm_runs arm
         ON arm.preregistration_digest = NEW.preregistration_digest
        AND arm.task_id = NEW.task_id
        AND arm.arm = NEW.arm
       JOIN benchmark_blind_assignments assignment
         ON assignment.blind_code = NEW.blind_code
        AND assignment.arm_execution_id = arm.arm_execution_id
        AND assignment.evaluator_attempt_id = NEW.evaluator_attempt_id
        AND assignment.rubric_policy_digest = NEW.rubric_policy_digest
       JOIN benchmark_blinded_candidate_packages package
         ON package.digest = assignment.blinded_package_digest
        AND package.arm_execution_id = arm.arm_execution_id
        AND package.blind_code = assignment.blind_code
       JOIN artifact_instances normalized
         ON normalized.id = package.normalized_archive_artifact_instance_id
       JOIN attempts evaluator ON evaluator.id = NEW.evaluator_attempt_id
       JOIN benchmark_evaluator_inputs evaluator_input
         ON evaluator_input.evaluator_attempt_id = evaluator.id
        AND evaluator_input.arm_execution_id = arm.arm_execution_id
        AND evaluator_input.blind_code = NEW.blind_code
        AND evaluator_input.blinded_package_digest = package.digest
        AND evaluator_input.normalized_artifact_instance_id = normalized.id
        AND evaluator_input.rubric_policy_digest = NEW.rubric_policy_digest
       JOIN result_envelopes result
         ON result.attempt_id = evaluator.id AND result.state = 'accepted'
       JOIN artifact_instances evaluator_output
         ON evaluator_output.manifest_digest = result.output_manifest_digest
        AND evaluator_output.producer_attempt_id = evaluator.id
       JOIN benchmark_evaluator_output_bindings output_binding
         ON output_binding.digest = NEW.evaluator_output_binding_digest
        AND output_binding.evaluator_input_digest = evaluator_input.digest
        AND output_binding.evaluator_attempt_id = evaluator.id
        AND output_binding.result_envelope_id = result.id
        AND output_binding.output_artifact_instance_id = evaluator_output.id
        AND output_binding.output_manifest_digest = result.output_manifest_digest
        AND output_binding.source_normalized_artifact_instance_id = normalized.id
        AND output_binding.preregistration_digest = arm.preregistration_digest
        AND output_binding.task_id = arm.task_id
        AND output_binding.arm = arm.arm
        AND output_binding.arm_execution_id = arm.arm_execution_id
       JOIN benchmark_hidden_test_observations hidden_observation
         ON hidden_observation.id = NEW.hidden_test_observation_id
        AND hidden_observation.blind_code = NEW.blind_code
        AND hidden_observation.evaluator_attempt_id = NEW.evaluator_attempt_id
        AND hidden_observation.metrics_json = NEW.metrics_json
       JOIN work_packets packet ON packet.attempt_id = evaluator.id
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       WHERE preregistration.digest = NEW.preregistration_digest
         AND preregistration.evaluation_rubric_policy_digest = NEW.rubric_policy_digest
         AND assignment.assigned_at_ms <= NEW.evaluated_at_ms
         AND evaluator.started_at_ms >= assignment.assigned_at_ms
         AND result.signed_at_ms >= assignment.assigned_at_ms
         AND result.received_at_ms >= assignment.assigned_at_ms
         AND hidden_observation.observed_at_ms >= assignment.assigned_at_ms
         AND hidden_observation.observed_at_ms <= NEW.evaluated_at_ms
         AND evaluator.state = 'accepted'
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_run_members member
           WHERE member.arm_execution_id = arm.arm_execution_id
             AND member.run_id = evaluator.run_id
         )
         AND result.output_manifest_digest = NEW.evidence_manifest_digest
         AND EXISTS (
           SELECT 1 FROM artifact_instance_taints taint
           WHERE taint.artifact_instance_id = evaluator_output.id
             AND taint.preregistration_digest = arm.preregistration_digest
             AND taint.task_id = arm.task_id AND taint.arm = arm.arm
             AND taint.source_input_artifact_instance_id = normalized.id
             AND taint.reason = 'benchmark_evaluator_output'
         )
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blind_code') = NEW.blind_code
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blinded_package_digest') = package.digest
         AND packet.input_manifest_digest = evaluator_input.detached_manifest_digest
         AND json_type(packet.canonical_json, '$.benchmark') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.candidate_manifest_digest') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.source_candidate_artifact_instance_id') IS NULL
         AND json_type(packet.canonical_json, '$.benchmark.arm') IS NULL
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_evaluation'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.verified_at_ms BETWEEN NEW.evaluated_at_ms - 5000 AND NEW.evaluated_at_ms
     );
END;

