BEFORE UPDATE ON benchmark_evaluations
BEGIN SELECT RAISE(ABORT, 'benchmark evaluations are immutable'); END;

CREATE TRIGGER benchmark_evaluations_no_delete
BEFORE DELETE ON benchmark_evaluations
BEGIN SELECT RAISE(ABORT, 'benchmark evaluations are immutable'); END;

CREATE TRIGGER benchmark_invalidated_campaign_rejects_evaluation
BEFORE INSERT ON benchmark_evaluations
WHEN EXISTS (
  SELECT 1 FROM benchmark_campaign_invalidations invalidation
  WHERE invalidation.preregistration_digest = NEW.preregistration_digest
)
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot record evaluation');
END;

CREATE TRIGGER benchmark_randomization_reveal_is_exact_complete_and_signed
BEFORE INSERT ON benchmark_randomization_reveals
BEGIN
  SELECT RAISE(ABORT, 'benchmark randomization reveal is not a verified complete permutation')
  WHERE NEW.revealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.revealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_type(NEW.permutations_json) <> 'array'
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.completion_seal_digest') IS NOT NEW.completion_seal_digest
     OR json_extract(NEW.canonical_json, '$.reveal_nonce') IS NOT NEW.reveal_nonce
     OR json_extract(NEW.canonical_json, '$.algorithm') IS NOT NEW.algorithm
     OR json_extract(NEW.canonical_json, '$.permutations_json') IS NOT NEW.permutations_json
     OR json_extract(NEW.canonical_json, '$.commitment_verified') IS NOT NEW.commitment_verified
     OR json_extract(NEW.canonical_json, '$.permutation_verified') IS NOT NEW.permutation_verified
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.revealed_at_ms') IS NOT NEW.revealed_at_ms
     OR EXISTS (
       SELECT 1 FROM json_each(NEW.permutations_json) permutation
       WHERE json_type(permutation.value) <> 'object'
          OR json_type(permutation.value, '$.task_id') <> 'text'
          OR json_extract(permutation.value, '$.arm') NOT IN ('A','B','C','D')
          OR json_extract(permutation.value, '$.randomized_order') NOT BETWEEN 1 AND 4
          OR EXISTS (
            SELECT 1 FROM json_each(permutation.value) field
            WHERE field.key NOT IN ('task_id','arm','randomized_order')
          )
     )
     OR EXISTS (
       SELECT 1 FROM json_each(NEW.permutations_json) permutation
       GROUP BY json_extract(permutation.value, '$.task_id'),
                json_extract(permutation.value, '$.arm')
       HAVING COUNT(*) > 1
     )
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN benchmark_campaign_completion_seals completion
         ON completion.preregistration_digest = preregistration.digest
        AND completion.digest = NEW.completion_seal_digest
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN principals validator
         ON validator.id = NEW.signer_principal_id AND validator.kind = 'service'
       WHERE preregistration.digest = NEW.preregistration_digest
         AND completion.sealed_at_ms <= NEW.revealed_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = preregistration.digest
         )
         AND json_array_length(NEW.permutations_json) = (
           SELECT COUNT(*) FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
             AND NOT EXISTS (
               SELECT 1 FROM json_each(NEW.permutations_json) permutation
               WHERE json_extract(permutation.value, '$.task_id') = arm.task_id
                 AND json_extract(permutation.value, '$.arm') = arm.arm
                 AND json_extract(permutation.value, '$.randomized_order') = arm.randomized_order
             )
         )
         AND NOT EXISTS (
           SELECT 1 FROM json_each(NEW.permutations_json) permutation
           WHERE NOT EXISTS (
             SELECT 1 FROM benchmark_arm_runs arm
             WHERE arm.preregistration_digest = NEW.preregistration_digest
               AND arm.task_id = json_extract(permutation.value, '$.task_id')
               AND arm.arm = json_extract(permutation.value, '$.arm')
               AND arm.randomized_order = json_extract(permutation.value, '$.randomized_order')
           )
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
             AND (
               NOT EXISTS (SELECT 1 FROM benchmark_evaluations evaluation
                           WHERE evaluation.preregistration_digest = arm.preregistration_digest
                             AND evaluation.task_id = arm.task_id AND evaluation.arm = arm.arm)
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_arm_settlement_seals settlement
                 WHERE settlement.arm_execution_id = arm.arm_execution_id
                   AND NOT EXISTS (
                     SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
                     WHERE invalidation.settlement_digest = settlement.digest
                   )
               )
             )
         )
     )
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN current_valid_signature_receipts receipt
         ON receipt.record_kind = 'benchmark_randomization_reveal'
        AND receipt.record_id = NEW.digest
        AND receipt.record_canonical_json = NEW.canonical_json
        AND receipt.record_signer_key_id = NEW.signer_key_id
        AND receipt.record_signature = NEW.signature
        AND receipt.referenced_digests_verified = 1
        AND receipt.payload_digest_verified = 1
        AND receipt.verified_payload_digest = preregistration.randomization_commitment_digest
        AND receipt.record_digest_verified = 1
        AND receipt.verified_record_digest = NEW.digest
        AND receipt.verified_at_ms BETWEEN NEW.revealed_at_ms - 5000 AND NEW.revealed_at_ms
       WHERE preregistration.digest = NEW.preregistration_digest
     );
END;

CREATE TRIGGER benchmark_randomization_reveals_no_update
BEFORE UPDATE ON benchmark_randomization_reveals
BEGIN SELECT RAISE(ABORT, 'benchmark randomization reveals are immutable'); END;

CREATE TRIGGER benchmark_randomization_reveals_no_delete
BEFORE DELETE ON benchmark_randomization_reveals
BEGIN SELECT RAISE(ABORT, 'benchmark randomization reveals are immutable'); END;

CREATE TRIGGER benchmark_adoption_is_exact_complete_and_signed
BEFORE INSERT ON benchmark_adoption_decisions
BEGIN
  SELECT RAISE(ABORT, 'benchmark adoption is not an exact complete preregistered analysis')
  WHERE NEW.decided_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.decided_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.analysis_receipt_digest') IS NOT NEW.analysis_receipt_digest
     OR json_extract(NEW.canonical_json, '$.analysis_manifest_digest') IS NOT NEW.analysis_manifest_digest
     OR json_extract(NEW.canonical_json, '$.completed_task_count') IS NOT NEW.completed_task_count
     OR json_extract(NEW.canonical_json, '$.arm_a_hidden_pass_count') IS NOT NEW.arm_a_hidden_pass_count
     OR json_extract(NEW.canonical_json, '$.arm_b_hidden_pass_count') IS NOT NEW.arm_b_hidden_pass_count
     OR json_extract(NEW.canonical_json, '$.arm_c_hidden_pass_count') IS NOT NEW.arm_c_hidden_pass_count
     OR json_extract(NEW.canonical_json, '$.arm_d_hidden_pass_count') IS NOT NEW.arm_d_hidden_pass_count
     OR json_extract(NEW.canonical_json, '$.b_minus_a_lift_ppm') IS NOT NEW.b_minus_a_lift_ppm
     OR json_extract(NEW.canonical_json, '$.b_minus_a_lower95_ppm') IS NOT NEW.b_minus_a_lower95_ppm
     OR json_extract(NEW.canonical_json, '$.c_minus_a_lift_ppm') IS NOT NEW.c_minus_a_lift_ppm
     OR json_extract(NEW.canonical_json, '$.c_minus_a_lower95_ppm') IS NOT NEW.c_minus_a_lower95_ppm
     OR json_extract(NEW.canonical_json, '$.high_risk_task_count') IS NOT NEW.high_risk_task_count
     OR json_extract(NEW.canonical_json, '$.c_high_risk_minus_a_lift_ppm') IS NOT NEW.c_high_risk_minus_a_lift_ppm
     OR json_extract(NEW.canonical_json, '$.c_high_risk_minus_a_lower95_ppm') IS NOT NEW.c_high_risk_minus_a_lower95_ppm
     OR json_extract(NEW.canonical_json, '$.b_cost_ratio_ppm') IS NOT NEW.b_cost_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.c_cost_ratio_ppm') IS NOT NEW.c_cost_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.b_p95_latency_ratio_ppm') IS NOT NEW.b_p95_latency_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.c_p95_latency_ratio_ppm') IS NOT NEW.c_p95_latency_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.c_high_risk_cost_ratio_ppm') IS NOT NEW.c_high_risk_cost_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.c_high_risk_p95_latency_ratio_ppm') IS NOT NEW.c_high_risk_p95_latency_ratio_ppm
     OR json_extract(NEW.canonical_json, '$.b_security_not_worse') IS NOT NEW.b_security_not_worse
     OR json_extract(NEW.canonical_json, '$.c_security_not_worse') IS NOT NEW.c_security_not_worse
     OR json_extract(NEW.canonical_json, '$.c_high_risk_security_not_worse') IS NOT NEW.c_high_risk_security_not_worse
     OR json_extract(NEW.canonical_json, '$.d_matches_c') IS NOT NEW.d_matches_c
     OR json_extract(NEW.canonical_json, '$.adopt_b') IS NOT NEW.adopt_b
     OR json_extract(NEW.canonical_json, '$.adopt_c_for_high_risk') IS NOT NEW.adopt_c_for_high_risk
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.decided_at_ms') IS NOT NEW.decided_at_ms
     OR NEW.adopt_b <> CASE WHEN
          NEW.b_minus_a_lift_ppm >= 50000
          AND NEW.b_minus_a_lower95_ppm > 0
          AND NEW.b_cost_ratio_ppm <= 1500000
          AND NEW.b_p95_latency_ratio_ppm <= 1500000
          AND NEW.b_security_not_worse = 1
        THEN 1 ELSE 0 END
     OR NEW.adopt_c_for_high_risk <> CASE WHEN
          NEW.c_high_risk_minus_a_lift_ppm >= 100000
          AND NEW.c_high_risk_minus_a_lower95_ppm > 0
          AND NEW.c_high_risk_cost_ratio_ppm <= 2500000
          AND NEW.c_high_risk_p95_latency_ratio_ppm <= 2000000
          AND NEW.c_high_risk_security_not_worse = 1
        THEN 1 ELSE 0 END
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN benchmark_randomization_reveals reveal
         ON reveal.preregistration_digest = preregistration.digest
       JOIN artifact_manifests analysis ON analysis.digest = NEW.analysis_manifest_digest
       JOIN current_valid_keys analysis_key
         ON analysis_key.key_id = analysis.signer_key_id
        AND analysis_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys validator_key
         ON validator_key.key_id = NEW.signer_key_id
        AND validator_key.principal_id = NEW.signer_principal_id
        AND validator_key.key_purpose = 'schema_validator'
       JOIN principals validator
         ON validator.id = NEW.signer_principal_id AND validator.kind = 'service'
       WHERE preregistration.digest = NEW.preregistration_digest
         AND reveal.revealed_at_ms <= NEW.decided_at_ms
         AND analysis.created_at_ms <= NEW.decided_at_ms
         AND json_extract(analysis.canonical_json, '$.artifact_type') = 'evidence'
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.preregistration_digest') = NEW.preregistration_digest
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.b_minus_a_lift_ppm') = NEW.b_minus_a_lift_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.b_minus_a_lower95_ppm') = NEW.b_minus_a_lower95_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_minus_a_lift_ppm') = NEW.c_minus_a_lift_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_minus_a_lower95_ppm') = NEW.c_minus_a_lower95_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_high_risk_minus_a_lift_ppm') = NEW.c_high_risk_minus_a_lift_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_high_risk_minus_a_lower95_ppm') = NEW.c_high_risk_minus_a_lower95_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.b_cost_ratio_ppm') = NEW.b_cost_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_cost_ratio_ppm') = NEW.c_cost_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.b_p95_latency_ratio_ppm') = NEW.b_p95_latency_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_p95_latency_ratio_ppm') = NEW.c_p95_latency_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_high_risk_cost_ratio_ppm') = NEW.c_high_risk_cost_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.c_high_risk_p95_latency_ratio_ppm') = NEW.c_high_risk_p95_latency_ratio_ppm
         AND json_extract(analysis.canonical_json, '$.benchmark_analysis.d_matches_c') = NEW.d_matches_c
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = preregistration.evaluation_rubric_policy_digest
         )
     )
     OR NEW.completed_task_count <> (
       SELECT COUNT(*) FROM benchmark_tasks task
       WHERE task.preregistration_digest = NEW.preregistration_digest
     )
     OR NEW.high_risk_task_count <> (
       SELECT COUNT(*) FROM benchmark_tasks task
       WHERE task.preregistration_digest = NEW.preregistration_digest
         AND task.risk_stratum = 'high'
     )
     OR EXISTS (
       SELECT 1 FROM benchmark_preregistrations preregistration
       WHERE preregistration.digest = NEW.preregistration_digest
         AND json_array_length(preregistration.canonical_json, '$.tasks') <> NEW.completed_task_count
     )
     OR EXISTS (
       SELECT 1 FROM benchmark_tasks task
       WHERE task.preregistration_digest = NEW.preregistration_digest
         AND (
           (SELECT COUNT(*) FROM benchmark_arm_runs arm
            WHERE arm.preregistration_digest = task.preregistration_digest
              AND arm.task_id = task.task_id) <> 4
           OR (SELECT COUNT(*) FROM benchmark_evaluations evaluation
               WHERE evaluation.preregistration_digest = task.preregistration_digest
                 AND evaluation.task_id = task.task_id) <> 4
           OR EXISTS (
             SELECT 1 FROM benchmark_arm_runs arm
             WHERE arm.preregistration_digest = task.preregistration_digest
               AND arm.task_id = task.task_id
               AND (
                 EXISTS (SELECT 1 FROM benchmark_arm_budget_breaches breach
                         WHERE breach.arm_execution_id = arm.arm_execution_id)
                 OR NOT EXISTS (
                   SELECT 1 FROM benchmark_arm_settlement_seals settlement
                   WHERE settlement.arm_execution_id = arm.arm_execution_id
                     AND NOT EXISTS (
                       SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
                       WHERE invalidation.settlement_digest = settlement.digest
                     )
                 )
               )
           )
         )
     )
     OR NEW.arm_a_hidden_pass_count <> (
       SELECT COALESCE(SUM(observation.hidden_test_pass),0)
       FROM benchmark_evaluations evaluation
       JOIN benchmark_hidden_test_observations observation
         ON observation.id = evaluation.hidden_test_observation_id
       WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'A'
     )
     OR NEW.arm_b_hidden_pass_count <> (
       SELECT COALESCE(SUM(observation.hidden_test_pass),0)
       FROM benchmark_evaluations evaluation
       JOIN benchmark_hidden_test_observations observation
         ON observation.id = evaluation.hidden_test_observation_id
       WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'B'
     )
     OR NEW.arm_c_hidden_pass_count <> (
       SELECT COALESCE(SUM(observation.hidden_test_pass),0)
       FROM benchmark_evaluations evaluation
       JOIN benchmark_hidden_test_observations observation
         ON observation.id = evaluation.hidden_test_observation_id
       WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'C'
     )
     OR NEW.arm_d_hidden_pass_count <> (
       SELECT COALESCE(SUM(observation.hidden_test_pass),0)
       FROM benchmark_evaluations evaluation
       JOIN benchmark_hidden_test_observations observation
         ON observation.id = evaluation.hidden_test_observation_id
       WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'D'
     )
     OR NEW.b_security_not_worse <> CASE WHEN
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'B')
       >=
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'A')
       THEN 1 ELSE 0 END
     OR NEW.c_security_not_worse <> CASE WHEN
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'C')
       >=
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'A')
       THEN 1 ELSE 0 END
     OR NEW.c_high_risk_security_not_worse <> CASE WHEN
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        JOIN benchmark_tasks task
          ON task.preregistration_digest = evaluation.preregistration_digest
         AND task.task_id = evaluation.task_id AND task.risk_stratum = 'high'
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'C')
       >=
       (SELECT COALESCE(SUM(observation.security_pass),0)
        FROM benchmark_evaluations evaluation
        JOIN benchmark_hidden_test_observations observation ON observation.id = evaluation.hidden_test_observation_id
        JOIN benchmark_tasks task
          ON task.preregistration_digest = evaluation.preregistration_digest
         AND task.task_id = evaluation.task_id AND task.risk_stratum = 'high'
        WHERE evaluation.preregistration_digest = NEW.preregistration_digest AND evaluation.arm = 'A')
       THEN 1 ELSE 0 END
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_adoption_decision'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.decided_at_ms - 5000 AND NEW.decided_at_ms
     );
END;

