-- Benchmark study controls are executable authority, not descriptive metadata.
CREATE TRIGGER benchmark_study_protocol_is_exact_frozen_and_signed
BEFORE INSERT ON benchmark_study_protocols
BEGIN
  SELECT RAISE(ABORT, 'benchmark study protocol is not exact, frozen, powered, or signed')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.study_phase') IS NOT NEW.study_phase
     OR json_extract(NEW.canonical_json, '$.required_task_count') IS NOT NEW.required_task_count
     OR json_extract(NEW.canonical_json, '$.minimum_tasks_per_risk_stratum') IS NOT NEW.minimum_tasks_per_risk_stratum
     OR json_extract(NEW.canonical_json, '$.power_analysis_manifest_digest') IS NOT NEW.power_analysis_manifest_digest
     OR json_extract(NEW.canonical_json, '$.analysis_policy_digest') IS NOT NEW.analysis_policy_digest
     OR json_extract(NEW.canonical_json, '$.adoption_rule_policy_digest') IS NOT NEW.adoption_rule_policy_digest
     OR json_extract(NEW.canonical_json, '$.analysis_closure_digest') IS NOT NEW.analysis_closure_digest
     OR json_extract(NEW.canonical_json, '$.normalizer_closure_digest') IS NOT NEW.normalizer_closure_digest
     OR json_extract(NEW.canonical_json, '$.leakage_scan_rules_digest') IS NOT NEW.leakage_scan_rules_digest
     OR json_extract(NEW.canonical_json, '$.adoption_eligible') IS NOT NEW.adoption_eligible
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN policies analysis_policy ON analysis_policy.digest = NEW.analysis_policy_digest
       JOIN policies adoption_policy ON adoption_policy.digest = NEW.adoption_rule_policy_digest
       JOIN configuration_artifacts analysis_closure
         ON analysis_closure.digest = NEW.analysis_closure_digest
        AND analysis_closure.artifact_kind = 'benchmark_analysis_closure'
       JOIN configuration_artifacts normalizer
         ON normalizer.digest = NEW.normalizer_closure_digest
        AND normalizer.artifact_kind = 'benchmark_normalizer_closure'
       JOIN configuration_artifacts leakage_rules
         ON leakage_rules.digest = NEW.leakage_scan_rules_digest
        AND leakage_rules.artifact_kind = 'sanitization_rules'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE preregistration.digest = NEW.preregistration_digest
         AND NEW.sealed_at_ms >= preregistration.sealed_at_ms
         AND json_array_length(preregistration.canonical_json, '$.tasks') = NEW.required_task_count
         AND analysis_policy.policy_type = 'benchmark_analysis'
         AND adoption_policy.policy_type = 'benchmark_adoption'
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest IN (analysis_policy.digest, adoption_policy.digest)
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest IN (
             analysis_closure.digest, normalizer.digest, leakage_rules.digest
           )
         )
         AND (SELECT COUNT(*) FROM json_each(preregistration.canonical_json, '$.tasks') task
              WHERE json_extract(task.value, '$.risk_stratum') = 'low')
             >= NEW.minimum_tasks_per_risk_stratum
         AND (SELECT COUNT(*) FROM json_each(preregistration.canonical_json, '$.tasks') task
              WHERE json_extract(task.value, '$.risk_stratum') = 'medium')
             >= NEW.minimum_tasks_per_risk_stratum
         AND (SELECT COUNT(*) FROM json_each(preregistration.canonical_json, '$.tasks') task
              WHERE json_extract(task.value, '$.risk_stratum') = 'high')
             >= NEW.minimum_tasks_per_risk_stratum
         AND (
           NEW.power_analysis_manifest_digest IS NULL
           OR EXISTS (
             SELECT 1 FROM artifact_manifests power
             JOIN current_valid_keys power_key
               ON power_key.key_id = power.signer_key_id
              AND power_key.key_purpose = 'artifact_broker'
             WHERE power.digest = NEW.power_analysis_manifest_digest
               AND json_extract(power.canonical_json, '$.artifact_type') = 'evidence'
               AND json_extract(power.canonical_json, '$.benchmark_power.preregistration_digest')
                   = NEW.preregistration_digest
               AND json_extract(power.canonical_json, '$.benchmark_power.target_power_ppm') >= 800000
               AND json_extract(power.canonical_json, '$.benchmark_power.required_task_count')
                   = NEW.required_task_count
           )
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_study_protocol'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

