CREATE TRIGGER benchmark_treatment_spec_is_exact_ordered_and_signed
BEFORE INSERT ON benchmark_treatment_specs
BEGIN
  SELECT RAISE(ABORT, 'benchmark treatment spec is not exact, ordered, topology-bound, or signed')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR (SELECT COUNT(*) FROM benchmark_treatment_specs prior
         WHERE prior.preregistration_digest = NEW.preregistration_digest)
        <> CASE NEW.arm WHEN 'A' THEN 0 WHEN 'B' THEN 1 WHEN 'C' THEN 2 WHEN 'D' THEN 3 END
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.treatment_spec_manifest_digest') IS NOT NEW.treatment_spec_manifest_digest
     OR json_extract(NEW.canonical_json, '$.planning_graph_digest') IS NOT NEW.planning_graph_digest
     OR json_extract(NEW.canonical_json, '$.delivery_graph_digest') IS NOT NEW.delivery_graph_digest
     OR json_extract(NEW.canonical_json, '$.ordered_model_call_cells_digest') IS NOT NEW.ordered_model_call_cells_digest
     OR json_extract(NEW.canonical_json, '$.critique_mode') IS NOT NEW.critique_mode
     OR json_extract(NEW.canonical_json, '$.critique_edge_count') IS NOT NEW.critique_edge_count
     OR json_extract(NEW.canonical_json, '$.refutation_edge_count') IS NOT NEW.refutation_edge_count
     OR json_extract(NEW.canonical_json, '$.normalized_summary_only') IS NOT NEW.normalized_summary_only
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR json(json_extract(NEW.canonical_json, '$.required_stage_sequence')) IS NOT CASE NEW.arm
          WHEN 'A' THEN json('["fable_plan_v1","codex_build","hidden_evaluation"]')
          WHEN 'B' THEN json('["fable_plan_v1","blind_o2_challenge","fable_plan_v2","codex_build","hidden_evaluation"]')
          WHEN 'C' THEN json('["blind_codex_research_1","blind_codex_research_2","o1_contradiction_synthesis","fable_plan_v1","blind_o2_critique","independent_codex_feasibility","fable_plan_v2","isolated_codex_build","independent_verification","fresh_o3_review","hidden_evaluation"]')
          WHEN 'D' THEN json('["independent_codex_research_1","independent_codex_research_2","independent_o1_summary","independent_fable_plan","independent_o2_summary","independent_codex_feasibility","normalized_fable_resolution","isolated_codex_build","independent_verification","fresh_o3_review","hidden_evaluation"]')
        END
     OR (NEW.arm = 'D' AND json_extract(NEW.canonical_json, '$.normalizer_closure_digest') IS NOT (
       SELECT protocol.normalizer_closure_digest FROM benchmark_study_protocols protocol
       WHERE protocol.preregistration_digest = NEW.preregistration_digest
     ))
     OR (NEW.arm <> 'D' AND json_type(NEW.canonical_json, '$.normalizer_closure_digest') IS NOT 'null')
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_study_protocols protocol
       JOIN artifact_manifests manifest ON manifest.digest = NEW.treatment_spec_manifest_digest
       JOIN current_valid_keys manifest_key
         ON manifest_key.key_id = manifest.signer_key_id
        AND manifest_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE protocol.preregistration_digest = NEW.preregistration_digest
         AND json_extract(manifest.canonical_json, '$.artifact_type') = 'evidence'
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.preregistration_digest') = NEW.preregistration_digest
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.arm') = NEW.arm
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.planning_graph_digest') = NEW.planning_graph_digest
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.delivery_graph_digest') = NEW.delivery_graph_digest
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.ordered_model_call_cells_digest') = NEW.ordered_model_call_cells_digest
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.critique_mode') = NEW.critique_mode
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.critique_edge_count') = NEW.critique_edge_count
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.refutation_edge_count') = NEW.refutation_edge_count
         AND json_extract(manifest.canonical_json, '$.benchmark_treatment.normalized_summary_only') = NEW.normalized_summary_only
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = NEW.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_randomization_reveals reveal
           WHERE reveal.preregistration_digest = NEW.preregistration_digest
         )
     )
     OR (NEW.arm = 'D' AND NOT EXISTS (
       SELECT 1 FROM benchmark_treatment_specs control
       WHERE control.preregistration_digest = NEW.preregistration_digest
         AND control.arm = 'C'
         AND control.delivery_graph_digest = NEW.delivery_graph_digest
         AND control.ordered_model_call_cells_digest = NEW.ordered_model_call_cells_digest
     ))
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_treatment_spec'
         AND receipt.record_id = NEW.preregistration_digest || ':' || NEW.arm
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.ordered_model_call_cells_digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

