CREATE TRIGGER benchmark_treatment_call_cell_is_exact_contiguous_and_signed
BEFORE INSERT ON benchmark_treatment_call_cells
BEGIN
  SELECT RAISE(ABORT, 'benchmark treatment call cell is not an exact frozen ordered cell')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.cell_no <> COALESCE((
       SELECT MAX(prior.cell_no) + 1 FROM benchmark_treatment_call_cells prior
       WHERE prior.preregistration_digest = NEW.preregistration_digest
         AND prior.arm = NEW.arm
     ), 1)
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.cell_no') IS NOT NEW.cell_no
     OR json_extract(NEW.canonical_json, '$.phase_no') IS NOT NEW.phase_no
     OR json_extract(NEW.canonical_json, '$.stage') IS NOT NEW.stage
     OR json_extract(NEW.canonical_json, '$.required_pool') IS NOT NEW.required_pool
     OR json_extract(NEW.canonical_json, '$.required_capability') IS NOT NEW.required_capability
     OR json_extract(NEW.canonical_json, '$.expected_provider') IS NOT NEW.expected_provider
     OR json_extract(NEW.canonical_json, '$.runtime') IS NOT NEW.runtime
     OR json_extract(NEW.canonical_json, '$.requested_model') IS NOT NEW.requested_model
     OR json_extract(NEW.canonical_json, '$.requested_profile') IS NOT NEW.requested_profile
     OR json_extract(NEW.canonical_json, '$.expected_model') IS NOT NEW.expected_model
     OR json_extract(NEW.canonical_json, '$.expected_model_family') IS NOT NEW.expected_model_family
     OR json_extract(NEW.canonical_json, '$.expected_profile') IS NOT NEW.expected_profile
     OR json_extract(NEW.canonical_json, '$.max_input_tokens') IS NOT NEW.max_input_tokens
     OR json_extract(NEW.canonical_json, '$.max_output_tokens') IS NOT NEW.max_output_tokens
     OR json_extract(NEW.canonical_json, '$.max_cache_read_tokens') IS NOT NEW.max_cache_read_tokens
     OR json_extract(NEW.canonical_json, '$.max_cache_write_tokens') IS NOT NEW.max_cache_write_tokens
     OR json_extract(NEW.canonical_json, '$.max_tool_calls') IS NOT NEW.max_tool_calls
     OR json_extract(NEW.canonical_json, '$.max_wall_time_ms') IS NOT NEW.max_wall_time_ms
     OR json_extract(NEW.canonical_json, '$.required_reservation_micro_usd') IS NOT NEW.required_reservation_micro_usd
     OR json_extract(NEW.canonical_json, '$.retry_policy') IS NOT NEW.retry_policy
     OR json_extract(NEW.canonical_json, '$.parity_cell_digest') IS NOT NEW.parity_cell_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_treatment_specs spec
       JOIN artifact_manifests manifest
         ON manifest.digest = spec.treatment_spec_manifest_digest
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       WHERE spec.preregistration_digest = NEW.preregistration_digest
         AND spec.arm = NEW.arm
         AND json_array_length(manifest.canonical_json, '$.benchmark_treatment.model_call_cells') >= NEW.cell_no
         AND json_extract(manifest.canonical_json,
               '$.benchmark_treatment.model_call_cells[' || (NEW.cell_no - 1) || '].id') = NEW.id
         AND json_extract(manifest.canonical_json,
               '$.benchmark_treatment.model_call_cells[' || (NEW.cell_no - 1) || '].parity_cell_digest') = NEW.parity_cell_digest
         AND json_extract(manifest.canonical_json,
               '$.benchmark_treatment.model_call_cells[' || (NEW.cell_no - 1) || '].canonical_json') = NEW.canonical_json
     )
     OR (NEW.arm = 'D' AND NOT EXISTS (
       SELECT 1 FROM benchmark_treatment_call_cells control
       WHERE control.preregistration_digest = NEW.preregistration_digest
         AND control.arm = 'C'
         AND control.cell_no = NEW.cell_no
         AND control.phase_no = NEW.phase_no
         AND control.required_pool = NEW.required_pool
         AND control.expected_provider = NEW.expected_provider
         AND control.runtime = NEW.runtime
         AND control.requested_model = NEW.requested_model
         AND control.requested_profile = NEW.requested_profile
         AND control.expected_model = NEW.expected_model
         AND control.expected_model_family = NEW.expected_model_family
         AND control.expected_profile = NEW.expected_profile
         AND control.max_input_tokens = NEW.max_input_tokens
         AND control.max_output_tokens = NEW.max_output_tokens
         AND control.max_cache_read_tokens = NEW.max_cache_read_tokens
         AND control.max_cache_write_tokens = NEW.max_cache_write_tokens
         AND control.max_tool_calls = NEW.max_tool_calls
         AND control.max_wall_time_ms = NEW.max_wall_time_ms
         AND control.required_reservation_micro_usd = NEW.required_reservation_micro_usd
         AND control.retry_policy = NEW.retry_policy
         AND control.parity_cell_digest = NEW.parity_cell_digest
     ))
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_treatment_call_cell'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.parity_cell_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.id
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

