CREATE TRIGGER benchmark_arm_run_requires_complete_treatment_matrix
BEFORE INSERT ON benchmark_arm_runs
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm lacks a complete exact treatment matrix')
  WHERE (SELECT COUNT(*) FROM benchmark_treatment_specs spec
         WHERE spec.preregistration_digest = NEW.preregistration_digest) <> 4
     OR NOT EXISTS (
       SELECT 1 FROM benchmark_treatment_specs spec
       WHERE spec.preregistration_digest = NEW.preregistration_digest
         AND spec.arm = NEW.arm
         AND spec.treatment_spec_manifest_digest = NEW.treatment_spec_manifest_digest
     )
     OR NOT EXISTS (
       SELECT 1 FROM benchmark_treatment_specs c
       JOIN benchmark_treatment_specs d
         ON d.preregistration_digest = c.preregistration_digest AND d.arm = 'D'
       WHERE c.preregistration_digest = NEW.preregistration_digest AND c.arm = 'C'
         AND c.delivery_graph_digest = d.delivery_graph_digest
         AND c.ordered_model_call_cells_digest = d.ordered_model_call_cells_digest
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_treatment_specs spec
       JOIN artifact_manifests manifest ON manifest.digest = spec.treatment_spec_manifest_digest
       WHERE spec.preregistration_digest = NEW.preregistration_digest
         AND (SELECT COUNT(*) FROM benchmark_treatment_call_cells cell
              WHERE cell.preregistration_digest = spec.preregistration_digest
                AND cell.arm = spec.arm)
             <> json_array_length(manifest.canonical_json, '$.benchmark_treatment.model_call_cells')
     )
     OR EXISTS (
       SELECT 1 FROM benchmark_treatment_call_cells c
       LEFT JOIN benchmark_treatment_call_cells d
         ON d.preregistration_digest = c.preregistration_digest
        AND d.arm = 'D' AND d.cell_no = c.cell_no
        AND d.parity_cell_digest = c.parity_cell_digest
       WHERE c.preregistration_digest = NEW.preregistration_digest
         AND c.arm = 'C' AND d.id IS NULL
     )
     OR EXISTS (
       SELECT 1 FROM benchmark_treatment_call_cells d
       LEFT JOIN benchmark_treatment_call_cells c
         ON c.preregistration_digest = d.preregistration_digest
        AND c.arm = 'C' AND c.cell_no = d.cell_no
        AND c.parity_cell_digest = d.parity_cell_digest
       WHERE d.preregistration_digest = NEW.preregistration_digest
         AND d.arm = 'D' AND c.id IS NULL
     )
     OR (NEW.arm IN ('C','D') AND EXISTS (
       SELECT 1 FROM benchmark_arm_runs peer
       WHERE peer.preregistration_digest = NEW.preregistration_digest
         AND peer.task_id = NEW.task_id
         AND peer.arm IN ('C','D') AND peer.arm <> NEW.arm
         AND peer.inference_budget_digest <> NEW.inference_budget_digest
     ))
     OR EXISTS (
       SELECT 1 FROM benchmark_campaign_invalidations invalidation
       WHERE invalidation.preregistration_digest = NEW.preregistration_digest
     )
     OR EXISTS (
       SELECT 1 FROM benchmark_randomization_reveals reveal
       WHERE reveal.preregistration_digest = NEW.preregistration_digest
     );
END;

CREATE TRIGGER benchmark_arm_start_permit_is_next_exact_current_and_signed
BEFORE INSERT ON benchmark_arm_start_permits
BEGIN
  SELECT RAISE(ABORT, 'benchmark arm start permit is not the next executable randomized arm')
  WHERE NEW.permit_no <> COALESCE((
       SELECT MAX(prior.permit_no) + 1 FROM benchmark_arm_start_permits prior
       WHERE prior.arm_execution_id = NEW.arm_execution_id
     ), 1)
     OR NEW.issued_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.issued_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.expires_at_ms > NEW.issued_at_ms + 60000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.run_id') IS NOT NEW.run_id
     OR json_extract(NEW.canonical_json, '$.permit_no') IS NOT NEW.permit_no
     OR json_extract(NEW.canonical_json, '$.randomized_order') IS NOT NEW.randomized_order
     OR json_extract(NEW.canonical_json, '$.provider_health_snapshot_digest') IS NOT NEW.provider_health_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.runtime_catalog_snapshot_digest') IS NOT NEW.runtime_catalog_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.resource_snapshot_digest') IS NOT NEW.resource_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.fairness_snapshot_digest') IS NOT NEW.fairness_snapshot_digest
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.issued_at_ms') IS NOT NEW.issued_at_ms
     OR json_extract(NEW.canonical_json, '$.expires_at_ms') IS NOT NEW.expires_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_arm_run_members member
         ON member.arm_execution_id = arm.arm_execution_id
        AND member.phase_no = 1 AND member.run_kind = 'planning'
       JOIN runs run ON run.id = member.run_id AND run.state = 'created'
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control
         ON control.current_term = term.term
        AND control.admission_mode = 'open' AND control.dispatch_enabled = 1
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       JOIN artifact_manifests provider_snapshot ON provider_snapshot.digest = NEW.provider_health_snapshot_digest
       JOIN artifact_manifests catalog_snapshot ON catalog_snapshot.digest = NEW.runtime_catalog_snapshot_digest
       JOIN artifact_manifests resource_snapshot ON resource_snapshot.digest = NEW.resource_snapshot_digest
       JOIN artifact_manifests fairness_snapshot ON fairness_snapshot.digest = NEW.fairness_snapshot_digest
       JOIN current_valid_keys provider_snapshot_key
         ON provider_snapshot_key.key_id = provider_snapshot.signer_key_id
        AND provider_snapshot_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys catalog_snapshot_key
         ON catalog_snapshot_key.key_id = catalog_snapshot.signer_key_id
        AND catalog_snapshot_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys resource_snapshot_key
         ON resource_snapshot_key.key_id = resource_snapshot.signer_key_id
        AND resource_snapshot_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys fairness_snapshot_key
         ON fairness_snapshot_key.key_id = fairness_snapshot.signer_key_id
        AND fairness_snapshot_key.key_purpose = 'artifact_broker'
       JOIN host_capacity capacity ON capacity.singleton = 1
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND member.run_id = NEW.run_id
         AND arm.randomized_order = NEW.randomized_order
         AND (SELECT COUNT(*) FROM benchmark_arm_runs matrix_arm
              WHERE matrix_arm.preregistration_digest = arm.preregistration_digest
                AND matrix_arm.task_id = arm.task_id) = 4
         AND (SELECT COUNT(*) FROM benchmark_arm_runs lower_arm
              WHERE lower_arm.preregistration_digest = arm.preregistration_digest
                AND lower_arm.task_id = arm.task_id
                AND lower_arm.randomized_order < arm.randomized_order)
             = arm.randomized_order - 1
         AND json_extract(provider_snapshot.canonical_json, '$.benchmark_start.arm_execution_id') = arm.arm_execution_id
         AND json_extract(provider_snapshot.canonical_json, '$.benchmark_start.snapshot_kind') = 'provider_health'
         AND json_extract(catalog_snapshot.canonical_json, '$.benchmark_start.arm_execution_id') = arm.arm_execution_id
         AND json_extract(catalog_snapshot.canonical_json, '$.benchmark_start.snapshot_kind') = 'runtime_catalog'
         AND json_extract(resource_snapshot.canonical_json, '$.benchmark_start.arm_execution_id') = arm.arm_execution_id
         AND json_extract(resource_snapshot.canonical_json, '$.benchmark_start.snapshot_kind') = 'host_resource'
         AND json_extract(resource_snapshot.canonical_json, '$.benchmark_start.host_capacity_revision') = capacity.revision
         AND json_extract(resource_snapshot.canonical_json, '$.benchmark_start.measurement_id') = capacity.measurement_id
         AND capacity.measurement_at_ms >= NEW.issued_at_ms - 60000
         AND json_extract(fairness_snapshot.canonical_json, '$.benchmark_start.arm_execution_id') = arm.arm_execution_id
         AND json_extract(fairness_snapshot.canonical_json, '$.benchmark_start.snapshot_kind') = 'fairness'
         AND provider_snapshot.created_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND catalog_snapshot.created_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND resource_snapshot.created_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND fairness_snapshot.created_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = arm.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_randomization_reveals reveal
           WHERE reveal.preregistration_digest = arm.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_arm_runs earlier
           WHERE earlier.preregistration_digest = arm.preregistration_digest
             AND earlier.task_id = arm.task_id
             AND earlier.randomized_order < arm.randomized_order
             AND (
               (SELECT COUNT(*) FROM benchmark_arm_run_members earlier_member
                JOIN runs earlier_run ON earlier_run.id = earlier_member.run_id
                JOIN run_completion_seals completion ON completion.run_id = earlier_run.id
                WHERE earlier_member.arm_execution_id = earlier.arm_execution_id
                  AND earlier_run.state = 'completed') <> 2
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_treatment_execution_receipts execution
                 WHERE execution.arm_execution_id = earlier.arm_execution_id
               )
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_arm_settlement_seals settlement
                 WHERE settlement.arm_execution_id = earlier.arm_execution_id
                   AND NOT EXISTS (
                     SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
                     WHERE invalidation.settlement_digest = settlement.digest
                   )
               )
             )
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_arm_start_permit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.issued_at_ms - 5000 AND NEW.issued_at_ms
     );
END;

