CREATE TRIGGER benchmark_run_activation_requires_randomized_start_authority
BEFORE UPDATE OF state ON runs
WHEN OLD.state = 'created' AND NEW.state = 'active'
 AND NEW.benchmark_preregistration_digest IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'benchmark run activation lacks exact randomized start authority')
  WHERE EXISTS (
    SELECT 1
    FROM benchmark_arm_run_members member
    JOIN benchmark_arm_runs arm ON arm.arm_execution_id = member.arm_execution_id
    WHERE member.run_id = NEW.id
      AND (
        (member.phase_no = 1 AND NOT EXISTS (
          SELECT 1 FROM benchmark_arm_start_permits permit
          JOIN leader_terms term ON term.term = permit.leader_term AND term.state = 'active'
          JOIN control_state control
            ON control.current_term = permit.leader_term
           AND control.admission_mode = 'open' AND control.dispatch_enabled = 1
          WHERE permit.arm_execution_id = arm.arm_execution_id
            AND permit.run_id = NEW.id
            AND permit.randomized_order = arm.randomized_order
            AND permit.permit_no = (
              SELECT MAX(latest.permit_no) FROM benchmark_arm_start_permits latest
              WHERE latest.arm_execution_id = arm.arm_execution_id
            )
            AND permit.issued_at_ms <= (unixepoch('subsec') * 1000)
            AND permit.expires_at_ms >= (unixepoch('subsec') * 1000)
        ))
        OR (member.phase_no = 2 AND NOT EXISTS (
          SELECT 1 FROM benchmark_arm_run_members planning
          JOIN runs planning_run ON planning_run.id = planning.run_id
          JOIN run_completion_seals completion ON completion.run_id = planning_run.id
          WHERE planning.arm_execution_id = arm.arm_execution_id
            AND planning.phase_no = 1
            AND planning_run.state = 'completed'
            AND NEW.predecessor_run_id = planning_run.id
        ))
        OR EXISTS (
          SELECT 1 FROM benchmark_campaign_invalidations invalidation
          WHERE invalidation.preregistration_digest = arm.preregistration_digest
        )
        OR EXISTS (
          SELECT 1 FROM benchmark_randomization_reveals reveal
          WHERE reveal.preregistration_digest = arm.preregistration_digest
        )
      )
  )
  OR NOT EXISTS (
    SELECT 1 FROM benchmark_arm_run_members member
    WHERE member.run_id = NEW.id
  );
END;

CREATE TRIGGER benchmark_treatment_execution_receipt_is_exact_and_signed
BEFORE INSERT ON benchmark_treatment_execution_receipts
BEGIN
  SELECT RAISE(ABORT, 'benchmark treatment execution does not match its frozen treatment')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.treatment_spec_manifest_digest') IS NOT NEW.treatment_spec_manifest_digest
     OR json_extract(NEW.canonical_json, '$.planning_plan_manifest_digest') IS NOT NEW.planning_plan_manifest_digest
     OR json_extract(NEW.canonical_json, '$.delivery_plan_manifest_digest') IS NOT NEW.delivery_plan_manifest_digest
     OR json_extract(NEW.canonical_json, '$.execution_input_manifest_digest') IS NOT NEW.execution_input_manifest_digest
     OR json_extract(NEW.canonical_json, '$.realized_planning_graph_digest') IS NOT NEW.realized_planning_graph_digest
     OR json_extract(NEW.canonical_json, '$.realized_delivery_graph_digest') IS NOT NEW.realized_delivery_graph_digest
     OR json_extract(NEW.canonical_json, '$.realized_ordered_model_call_cells_digest') IS NOT NEW.realized_ordered_model_call_cells_digest
     OR json_extract(NEW.canonical_json, '$.realized_call_cell_count') IS NOT NEW.realized_call_cell_count
     OR json_extract(NEW.canonical_json, '$.realized_attempt_count') IS NOT NEW.realized_attempt_count
     OR json_extract(NEW.canonical_json, '$.protocol_deviation_count') IS NOT NEW.protocol_deviation_count
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_treatment_specs spec
         ON spec.preregistration_digest = arm.preregistration_digest AND spec.arm = arm.arm
       JOIN benchmark_study_protocols protocol
         ON protocol.preregistration_digest = arm.preregistration_digest
       JOIN benchmark_arm_run_members planning_member
         ON planning_member.arm_execution_id = arm.arm_execution_id
        AND planning_member.phase_no = 1 AND planning_member.run_kind = 'planning'
       JOIN runs planning_run
         ON planning_run.id = planning_member.run_id
        AND planning_run.plan_manifest_digest = NEW.planning_plan_manifest_digest
       JOIN benchmark_arm_run_members delivery_member
         ON delivery_member.arm_execution_id = arm.arm_execution_id
        AND delivery_member.phase_no = 2 AND delivery_member.run_kind = 'delivery'
       JOIN runs delivery_run
         ON delivery_run.id = delivery_member.run_id
        AND delivery_run.plan_manifest_digest = NEW.delivery_plan_manifest_digest
       JOIN artifact_manifests execution_input
         ON execution_input.digest = NEW.execution_input_manifest_digest
       JOIN current_valid_keys execution_input_key
         ON execution_input_key.key_id = execution_input.signer_key_id
        AND execution_input_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND spec.treatment_spec_manifest_digest = NEW.treatment_spec_manifest_digest
         AND spec.planning_graph_digest = NEW.realized_planning_graph_digest
         AND spec.delivery_graph_digest = NEW.realized_delivery_graph_digest
         AND spec.ordered_model_call_cells_digest = NEW.realized_ordered_model_call_cells_digest
         AND json_extract(execution_input.canonical_json, '$.artifact_type') = 'benchmark_execution_input'
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.arm_execution_id') = arm.arm_execution_id
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.planning_run_id') = planning_run.id
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.delivery_run_id') = delivery_run.id
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.planning_plan_manifest_digest') = NEW.planning_plan_manifest_digest
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.delivery_plan_manifest_digest') = NEW.delivery_plan_manifest_digest
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_planning_graph_digest') = NEW.realized_planning_graph_digest
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_delivery_graph_digest') = NEW.realized_delivery_graph_digest
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_ordered_model_call_cells_digest') = NEW.realized_ordered_model_call_cells_digest
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_call_cell_count') = NEW.realized_call_cell_count
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_attempt_count') = NEW.realized_attempt_count
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_critique_edge_count')
             = json_extract(NEW.canonical_json, '$.realized_critique_edge_count')
         AND json_extract(execution_input.canonical_json, '$.benchmark_execution_input.realized_refutation_edge_count')
             = json_extract(NEW.canonical_json, '$.realized_refutation_edge_count')
         AND NEW.realized_attempt_count = (
           SELECT COUNT(*) FROM benchmark_arm_run_members member
           JOIN attempts attempt ON attempt.run_id = member.run_id
           WHERE member.arm_execution_id = arm.arm_execution_id
         )
         AND NEW.realized_call_cell_count = (
           SELECT COUNT(*) FROM benchmark_realized_call_cells realized
           WHERE realized.arm_execution_id = arm.arm_execution_id
         )
         AND NEW.realized_call_cell_count = (
           SELECT COUNT(*) FROM benchmark_treatment_call_cells frozen
           WHERE frozen.preregistration_digest = arm.preregistration_digest
             AND frozen.arm = arm.arm
         )
         AND NEW.realized_attempt_count = NEW.realized_call_cell_count
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_treatment_call_cells frozen
           WHERE frozen.preregistration_digest = arm.preregistration_digest
             AND frozen.arm = arm.arm
             AND NOT EXISTS (
               SELECT 1 FROM benchmark_realized_call_cells realized
               WHERE realized.arm_execution_id = arm.arm_execution_id
                 AND realized.cell_no = frozen.cell_no
                 AND realized.treatment_cell_id = frozen.id
                 AND realized.parity_cell_digest = frozen.parity_cell_digest
             )
         )
         AND (SELECT COUNT(*)
              FROM benchmark_arm_run_members completed_member
              JOIN runs completed_run ON completed_run.id = completed_member.run_id
              JOIN run_completion_seals completion ON completion.run_id = completed_run.id
              WHERE completed_member.arm_execution_id = arm.arm_execution_id
                AND completed_member.phase_no IN (1,2)
                AND completed_member.run_kind = CASE completed_member.phase_no
                  WHEN 1 THEN 'planning' ELSE 'delivery' END
                AND completed_run.state = 'completed') = 2
         AND (SELECT COUNT(*) FROM benchmark_arm_run_members exact_member
              WHERE exact_member.arm_execution_id = arm.arm_execution_id) = 2
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_run_members live_member
           JOIN attempts live_attempt ON live_attempt.run_id = live_member.run_id
           WHERE live_member.arm_execution_id = arm.arm_execution_id
             AND live_attempt.state <> 'accepted'
         )
         AND (arm.arm <> 'D' OR (
           spec.critique_edge_count = 0 AND spec.refutation_edge_count = 0
           AND spec.normalized_summary_only = 1
           AND json_extract(NEW.canonical_json, '$.normalizer_closure_digest') = protocol.normalizer_closure_digest
           AND json_extract(NEW.canonical_json, '$.realized_critique_edge_count') = 0
           AND json_extract(NEW.canonical_json, '$.realized_refutation_edge_count') = 0
         ))
         AND (arm.arm = 'D' OR json_type(NEW.canonical_json, '$.normalizer_closure_digest') = 'null')
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_budget_breaches breach
           WHERE breach.arm_execution_id = arm.arm_execution_id
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = arm.preregistration_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts input_receipt
       WHERE input_receipt.record_kind = 'benchmark_execution_input_manifest'
         AND input_receipt.record_id = NEW.execution_input_manifest_digest
         AND input_receipt.record_canonical_json = (
           SELECT manifest.canonical_json FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.execution_input_manifest_digest
         )
         AND input_receipt.record_signer_key_id = (
           SELECT manifest.signer_key_id FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.execution_input_manifest_digest
         )
         AND input_receipt.record_signature = (
           SELECT manifest.signature FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.execution_input_manifest_digest
         )
         AND input_receipt.referenced_digests_verified = 1
         AND input_receipt.record_digest_verified = 1
         AND input_receipt.verified_record_digest = NEW.execution_input_manifest_digest
         AND input_receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_treatment_execution_receipt'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

CREATE TRIGGER benchmark_treatment_execution_receipts_no_update
BEFORE UPDATE ON benchmark_treatment_execution_receipts
BEGIN SELECT RAISE(ABORT, 'benchmark treatment execution receipts are immutable'); END;

CREATE TRIGGER benchmark_treatment_execution_receipts_no_delete
BEFORE DELETE ON benchmark_treatment_execution_receipts
BEGIN SELECT RAISE(ABORT, 'benchmark treatment execution receipts are immutable'); END;

CREATE TRIGGER benchmark_attempt_cannot_be_created_after_treatment_execution_seal
BEFORE INSERT ON attempts
WHEN EXISTS (
  SELECT 1
  FROM benchmark_arm_run_members member
  JOIN benchmark_treatment_execution_receipts execution
    ON execution.arm_execution_id = member.arm_execution_id
  WHERE member.run_id = NEW.run_id
)
BEGIN
  SELECT RAISE(ABORT, 'benchmark attempt cannot be created after treatment execution is sealed');
END;

CREATE TRIGGER benchmark_campaign_invalidation_is_exact_and_signed
BEFORE INSERT ON benchmark_campaign_invalidations
BEGIN
  SELECT RAISE(ABORT, 'benchmark campaign invalidation lacks exact campaign evidence and authority')
  WHERE NEW.invalidated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.invalidated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.task_id') IS NOT NEW.task_id
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.reason') IS NOT NEW.reason
     OR json_extract(NEW.canonical_json, '$.provider_observation_id') IS NOT NEW.provider_observation_id
     OR json_extract(NEW.canonical_json, '$.host_capacity_revision') IS NOT NEW.host_capacity_revision
     OR json_extract(NEW.canonical_json, '$.evidence_manifest_digest') IS NOT NEW.evidence_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.invalidated_at_ms') IS NOT NEW.invalidated_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_preregistrations preregistration
       JOIN artifact_manifests evidence ON evidence.digest = NEW.evidence_manifest_digest
       JOIN current_valid_keys evidence_key
         ON evidence_key.key_id = evidence.signer_key_id
        AND evidence_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = CASE NEW.signature
          WHEN 'derived:sqlite-trigger-v1' THEN 'provider_observer'
          ELSE 'control_plane' END
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE preregistration.digest = NEW.preregistration_digest
         AND NEW.invalidated_at_ms >= preregistration.sealed_at_ms
         AND (NEW.task_id IS NULL OR EXISTS (
           SELECT 1 FROM benchmark_tasks task
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND task.task_id = NEW.task_id
         ))
         AND (NEW.arm IS NULL OR EXISTS (
           SELECT 1 FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
             AND arm.task_id = NEW.task_id AND arm.arm = NEW.arm
         ))
         AND (
           (NEW.reason IN ('provider_outage','breaker_open')
             AND NEW.provider_observation_id IS NOT NULL
             AND NEW.host_capacity_revision IS NULL
             AND EXISTS (
               SELECT 1 FROM provider_health_observations observation
               WHERE observation.id = NEW.provider_observation_id
                 AND observation.observed_state = CASE NEW.reason
                   WHEN 'provider_outage' THEN 'outage' ELSE 'breaker_open' END
                 AND observation.evidence_manifest_digest = NEW.evidence_manifest_digest
                 AND observation.observed_at_ms <= NEW.invalidated_at_ms
             ))
           OR (NEW.reason = 'capacity_intervention'
             AND NEW.provider_observation_id IS NULL
             AND NEW.host_capacity_revision IS NOT NULL
             AND NEW.host_capacity_revision <= (SELECT capacity.revision FROM host_capacity capacity WHERE capacity.singleton = 1))
           OR (NEW.reason NOT IN ('provider_outage','breaker_open','capacity_intervention')
             AND NEW.provider_observation_id IS NULL)
         )
     )
     OR NOT (
       EXISTS (
         SELECT 1 FROM current_valid_signature_receipts receipt
         WHERE receipt.record_kind = 'benchmark_campaign_invalidation'
           AND receipt.record_id = NEW.id
           AND receipt.record_canonical_json = NEW.canonical_json
           AND receipt.record_signer_key_id = NEW.signer_key_id
           AND receipt.record_signature = NEW.signature
           AND receipt.referenced_digests_verified = 1
           AND receipt.verified_at_ms BETWEEN NEW.invalidated_at_ms - 5000 AND NEW.invalidated_at_ms
       )
       OR (
         NEW.reason = 'late_usage'
         AND NEW.signature = 'derived:sqlite-trigger-v1'
         AND NEW.id = 'benchmark-campaign-invalidation:late-usage:' || NEW.preregistration_digest
         AND EXISTS (
           SELECT 1
           FROM benchmark_arm_settlement_invalidations settlement_invalidation
           JOIN benchmark_arm_settlement_seals settlement
             ON settlement.digest = settlement_invalidation.settlement_digest
           JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
           JOIN usage_events usage ON usage.id = settlement_invalidation.usage_event_id
           WHERE arm.preregistration_digest = NEW.preregistration_digest
             AND arm.task_id = NEW.task_id AND arm.arm = NEW.arm
             AND usage.evidence_manifest_digest = NEW.evidence_manifest_digest
             AND settlement_invalidation.invalidated_at_ms = NEW.invalidated_at_ms
         )
       )
       OR (
         NEW.reason IN ('provider_outage','breaker_open')
         AND NEW.signature = 'derived:sqlite-trigger-v1'
         AND NEW.id = 'benchmark-campaign-invalidation:provider:' || NEW.preregistration_digest
         AND NEW.task_id IS NULL AND NEW.arm IS NULL
         AND EXISTS (
           SELECT 1
           FROM provider_health_observations observation
           JOIN (
             SELECT arm.preregistration_digest,
                    catalog.provider,
                    attempt.model_family,
                    attempt.state
             FROM benchmark_arm_runs arm
             JOIN benchmark_arm_run_members member
               ON member.arm_execution_id = arm.arm_execution_id
             JOIN attempts attempt ON attempt.run_id = member.run_id
             JOIN pricing_catalogs catalog ON catalog.digest = attempt.pricing_catalog_digest
             UNION
             SELECT arm.preregistration_digest,
                    catalog.provider,
                    evaluator.model_family,
                    evaluator.state
             FROM benchmark_blind_assignments assignment
             JOIN benchmark_arm_runs arm
               ON arm.arm_execution_id = assignment.arm_execution_id
             JOIN attempts evaluator ON evaluator.id = assignment.evaluator_attempt_id
             JOIN pricing_catalogs catalog ON catalog.digest = evaluator.pricing_catalog_digest
           ) affected
           WHERE observation.id = NEW.provider_observation_id
             AND observation.observed_state = CASE NEW.reason
               WHEN 'provider_outage' THEN 'outage' ELSE 'breaker_open' END
             AND observation.provider = affected.provider
             AND observation.model_family = affected.model_family
             AND observation.evidence_manifest_digest = NEW.evidence_manifest_digest
             AND observation.observed_at_ms = NEW.invalidated_at_ms
             AND affected.preregistration_digest = NEW.preregistration_digest
             AND affected.state IN ('created','dispatched','acked','running','result_pending','unknown')
         )
       )
     );
END;

CREATE TRIGGER benchmark_campaign_invalidations_no_update
BEFORE UPDATE ON benchmark_campaign_invalidations
BEGIN SELECT RAISE(ABORT, 'benchmark campaign invalidations are immutable'); END;

CREATE TRIGGER benchmark_campaign_invalidations_no_delete
BEFORE DELETE ON benchmark_campaign_invalidations
BEGIN SELECT RAISE(ABORT, 'benchmark campaign invalidations are immutable'); END;

CREATE TRIGGER benchmark_late_usage_invalidates_whole_campaign
AFTER INSERT ON benchmark_arm_settlement_invalidations
BEGIN
  INSERT OR IGNORE INTO benchmark_campaign_invalidations(
    id, preregistration_digest, task_id, arm, reason,
    provider_observation_id, host_capacity_revision, evidence_manifest_digest,
    canonical_json, signer_principal_id, signer_key_id, signature, invalidated_at_ms
  )
  SELECT 'benchmark-campaign-invalidation:late-usage:' || arm.preregistration_digest,
         arm.preregistration_digest, arm.task_id, arm.arm, 'late_usage',
         NULL, NULL, usage.evidence_manifest_digest,
         json_object(
           'id', 'benchmark-campaign-invalidation:late-usage:' || arm.preregistration_digest,
           'preregistration_digest', arm.preregistration_digest,
           'task_id', arm.task_id,
           'arm', arm.arm,
           'reason', 'late_usage',
           'provider_observation_id', NULL,
           'host_capacity_revision', NULL,
           'evidence_manifest_digest', usage.evidence_manifest_digest,
           'signer_principal_id', usage.signer_principal_id,
           'signer_key_id', usage.signer_key_id,
           'invalidated_at_ms', NEW.invalidated_at_ms
         ),
         usage.signer_principal_id, usage.signer_key_id,
         'derived:sqlite-trigger-v1', NEW.invalidated_at_ms
  FROM benchmark_arm_settlement_seals settlement
  JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
  JOIN usage_events usage ON usage.id = NEW.usage_event_id
  WHERE settlement.digest = NEW.settlement_digest
    AND EXISTS (
      SELECT 1 FROM current_valid_keys usage_key
      WHERE usage_key.key_id = usage.signer_key_id
        AND usage_key.principal_id = usage.signer_principal_id
        AND usage_key.key_purpose = 'provider_observer'
    );
END;

CREATE TRIGGER benchmark_provider_disruption_invalidates_active_campaigns
AFTER INSERT ON provider_health_observations
WHEN NEW.observed_state IN ('outage','breaker_open')
BEGIN
  INSERT OR IGNORE INTO benchmark_campaign_invalidations(
    id, preregistration_digest, task_id, arm, reason,
    provider_observation_id, host_capacity_revision, evidence_manifest_digest,
    canonical_json, signer_principal_id, signer_key_id, signature, invalidated_at_ms
  )
  SELECT DISTINCT
         'benchmark-campaign-invalidation:provider:' || affected.preregistration_digest,
         affected.preregistration_digest, NULL, NULL,
         CASE NEW.observed_state WHEN 'outage' THEN 'provider_outage' ELSE 'breaker_open' END,
         NEW.id, NULL, NEW.evidence_manifest_digest,
         json_object(
           'id', 'benchmark-campaign-invalidation:provider:' || affected.preregistration_digest,
           'preregistration_digest', affected.preregistration_digest,
           'task_id', NULL,
           'arm', NULL,
           'reason', CASE NEW.observed_state WHEN 'outage' THEN 'provider_outage' ELSE 'breaker_open' END,
           'provider_observation_id', NEW.id,
           'host_capacity_revision', NULL,
           'evidence_manifest_digest', NEW.evidence_manifest_digest,
           'signer_principal_id', NEW.signer_principal_id,
           'signer_key_id', NEW.signer_key_id,
           'invalidated_at_ms', NEW.observed_at_ms
         ),
         NEW.signer_principal_id, NEW.signer_key_id,
         'derived:sqlite-trigger-v1', NEW.observed_at_ms
  FROM (
    SELECT arm.preregistration_digest,
           catalog.provider,
           attempt.model_family,
           attempt.state
    FROM benchmark_arm_runs arm
    JOIN benchmark_arm_run_members member
      ON member.arm_execution_id = arm.arm_execution_id
    JOIN attempts attempt ON attempt.run_id = member.run_id
    JOIN pricing_catalogs catalog ON catalog.digest = attempt.pricing_catalog_digest
    UNION
    SELECT arm.preregistration_digest,
           catalog.provider,
           evaluator.model_family,
           evaluator.state
    FROM benchmark_blind_assignments assignment
    JOIN benchmark_arm_runs arm
      ON arm.arm_execution_id = assignment.arm_execution_id
    JOIN attempts evaluator ON evaluator.id = assignment.evaluator_attempt_id
    JOIN pricing_catalogs catalog ON catalog.digest = evaluator.pricing_catalog_digest
  ) affected
  WHERE affected.provider = NEW.provider
    AND affected.model_family = NEW.model_family
    AND affected.state IN ('created','dispatched','acked','running','result_pending','unknown');
END;

-- The invalidation row is also the durable campaign fence. Its AFTER trigger
-- synchronously removes every still-live database authority before the writer
-- transaction can commit; process death and usage reconciliation continue under
-- the same native invalidation operation and its postcondition.
CREATE TRIGGER benchmark_campaign_invalidation_atomically_fences_active_work
AFTER INSERT ON benchmark_campaign_invalidations
BEGIN
  UPDATE outbox
     SET state = 'cancelled'
   WHERE state IN ('pending','claimed','sent','unknown')
     AND (
       EXISTS (
         SELECT 1
         FROM attempts attempt
         JOIN runs run ON run.id = attempt.run_id
         WHERE attempt.id = outbox.attempt_id
           AND run.benchmark_preregistration_digest = NEW.preregistration_digest
       )
       OR EXISTS (
         SELECT 1
         FROM benchmark_blind_assignments assignment
         JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
         WHERE assignment.evaluator_attempt_id = outbox.attempt_id
           AND arm.preregistration_digest = NEW.preregistration_digest
       )
     );

  UPDATE leases
     SET state = 'revoked', released_at_ms = NEW.invalidated_at_ms
   WHERE state = 'active'
     AND (
       EXISTS (
         SELECT 1
         FROM attempts attempt
         JOIN runs run ON run.id = attempt.run_id
         WHERE attempt.id = leases.attempt_id
           AND run.benchmark_preregistration_digest = NEW.preregistration_digest
       )
       OR EXISTS (
         SELECT 1
         FROM benchmark_blind_assignments assignment
         JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
         WHERE assignment.evaluator_attempt_id = leases.attempt_id
           AND arm.preregistration_digest = NEW.preregistration_digest
       )
     );

  UPDATE attempts
     SET state = 'quarantined',
         finished_at_ms = CASE
           WHEN state = 'unknown' THEN finished_at_ms
           ELSE NEW.invalidated_at_ms
         END,
         error_code = CASE
           WHEN state = 'unknown' THEN error_code
           ELSE 'benchmark_campaign_invalidated'
         END
   WHERE state IN ('created','dispatched','acked','running','result_pending','unknown')
     AND (
       EXISTS (
         SELECT 1 FROM runs run
         WHERE run.id = attempts.run_id
           AND run.benchmark_preregistration_digest = NEW.preregistration_digest
       )
       OR EXISTS (
         SELECT 1
         FROM benchmark_blind_assignments assignment
         JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
         WHERE assignment.evaluator_attempt_id = attempts.id
           AND arm.preregistration_digest = NEW.preregistration_digest
       )
     );

  UPDATE node_versions
     SET state = 'cancelled', current_attempt_id = NULL, revision = revision + 1
   WHERE state IN ('pending','ready','dispatched')
     AND (
       EXISTS (
         SELECT 1 FROM runs run
         WHERE run.id = node_versions.run_id
           AND run.benchmark_preregistration_digest = NEW.preregistration_digest
       )
       OR EXISTS (
         SELECT 1
         FROM attempts evaluator
         JOIN benchmark_blind_assignments assignment
           ON assignment.evaluator_attempt_id = evaluator.id
         JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
         WHERE evaluator.node_version_id = node_versions.id
           AND arm.preregistration_digest = NEW.preregistration_digest
       )
     );
END;

CREATE TRIGGER benchmark_invalidated_campaign_rejects_new_attempt
BEFORE INSERT ON attempts
WHEN EXISTS (
  SELECT 1
  FROM runs run
  JOIN benchmark_campaign_invalidations invalidation
    ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
  WHERE run.id = NEW.run_id
)
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot create an attempt');
END;

CREATE TRIGGER benchmark_invalidated_campaign_rejects_new_outbox
BEFORE INSERT ON outbox
WHEN EXISTS (
       SELECT 1
       FROM attempts attempt
       JOIN runs run ON run.id = attempt.run_id
       JOIN benchmark_campaign_invalidations invalidation
         ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
       WHERE attempt.id = NEW.attempt_id
     )
  OR EXISTS (
       SELECT 1
       FROM benchmark_blind_assignments assignment
       JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
       JOIN benchmark_campaign_invalidations invalidation
         ON invalidation.preregistration_digest = arm.preregistration_digest
       WHERE assignment.evaluator_attempt_id = NEW.attempt_id
     )
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark campaign cannot create dispatch work');
END;

CREATE TRIGGER benchmark_invalidated_campaign_cannot_advance_attempt
BEFORE UPDATE OF state ON attempts
WHEN OLD.state <> NEW.state
 AND NEW.state IN ('dispatched','acked','running','result_pending','accepted')
 AND (
   EXISTS (
     SELECT 1
     FROM runs run
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
     WHERE run.id = NEW.run_id
   )
   OR EXISTS (
     SELECT 1
     FROM benchmark_blind_assignments assignment
     JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = arm.preregistration_digest
     WHERE assignment.evaluator_attempt_id = NEW.id
   )
 )
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark attempt cannot advance');
END;

CREATE TRIGGER benchmark_invalidated_campaign_cannot_claim_or_send_outbox
BEFORE UPDATE OF state ON outbox
WHEN OLD.state <> NEW.state
 AND NEW.state IN ('claimed','sent')
 AND (
   EXISTS (
     SELECT 1
     FROM attempts attempt
     JOIN runs run ON run.id = attempt.run_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
     WHERE attempt.id = NEW.attempt_id
   )
   OR EXISTS (
     SELECT 1
     FROM benchmark_blind_assignments assignment
     JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = arm.preregistration_digest
     WHERE assignment.evaluator_attempt_id = NEW.attempt_id
   )
 )
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark dispatch cannot be claimed or sent');
END;

CREATE TRIGGER benchmark_invalidated_campaign_cannot_renew_lease
BEFORE UPDATE OF heartbeat_seq, expires_at_ms ON leases
WHEN (OLD.heartbeat_seq IS NOT NEW.heartbeat_seq OR OLD.expires_at_ms IS NOT NEW.expires_at_ms)
 AND (
   EXISTS (
     SELECT 1
     FROM attempts attempt
     JOIN runs run ON run.id = attempt.run_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
     WHERE attempt.id = NEW.attempt_id
   )
   OR EXISTS (
     SELECT 1
     FROM benchmark_blind_assignments assignment
     JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = arm.preregistration_digest
     WHERE assignment.evaluator_attempt_id = NEW.attempt_id
   )
 )
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark lease cannot renew');
END;

CREATE TRIGGER benchmark_invalidated_campaign_cannot_advance_node
BEFORE UPDATE OF state ON node_versions
WHEN OLD.state <> NEW.state
 AND NEW.state IN ('ready','dispatched','accepted')
 AND (
   EXISTS (
     SELECT 1
     FROM runs run
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = run.benchmark_preregistration_digest
     WHERE run.id = NEW.run_id
   )
   OR EXISTS (
     SELECT 1
     FROM attempts evaluator
     JOIN benchmark_blind_assignments assignment ON assignment.evaluator_attempt_id = evaluator.id
     JOIN benchmark_arm_runs arm ON arm.arm_execution_id = assignment.arm_execution_id
     JOIN benchmark_campaign_invalidations invalidation
       ON invalidation.preregistration_digest = arm.preregistration_digest
     WHERE evaluator.node_version_id = NEW.id
   )
 )
BEGIN
  SELECT RAISE(ABORT, 'invalidated benchmark node cannot advance');
END;

CREATE TRIGGER benchmark_campaign_invalidation_commit_is_exact_quiescent_and_signed
BEFORE INSERT ON benchmark_campaign_invalidation_commits
BEGIN
  SELECT RAISE(ABORT, 'benchmark invalidation commit is incomplete, nonquiescent, or unsigned')
  WHERE NEW.committed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.committed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.transaction_id') IS NOT NEW.transaction_id
     OR json_extract(NEW.canonical_json, '$.invalidation_set_digest') IS NOT NEW.invalidation_set_digest
     OR json_extract(NEW.canonical_json, '$.invalidation_count') IS NOT NEW.invalidation_count
     OR json_extract(NEW.canonical_json, '$.cancelled_outbox_count') IS NOT NEW.cancelled_outbox_count
     OR json_extract(NEW.canonical_json, '$.revoked_lease_count') IS NOT NEW.revoked_lease_count
     OR json_extract(NEW.canonical_json, '$.quarantined_attempt_count') IS NOT NEW.quarantined_attempt_count
     OR json_extract(NEW.canonical_json, '$.cancelled_node_count') IS NOT NEW.cancelled_node_count
     OR json_extract(NEW.canonical_json, '$.cancelled_run_count') IS NOT NEW.cancelled_run_count
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.committed_at_ms') IS NOT NEW.committed_at_ms
     OR (SELECT COUNT(*) FROM benchmark_campaign_invalidation_commit_members member
         WHERE member.commit_digest = NEW.digest) <> NEW.invalidation_count
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       WHERE member.commit_digest = NEW.digest
         AND invalidation.invalidated_at_ms > NEW.committed_at_ms
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN runs run ON run.benchmark_preregistration_digest = invalidation.preregistration_digest
       JOIN attempts attempt ON attempt.run_id = run.id
       JOIN outbox message ON message.attempt_id = attempt.id
       WHERE member.commit_digest = NEW.digest
         AND message.state IN ('pending','claimed','sent','unknown')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN runs run ON run.benchmark_preregistration_digest = invalidation.preregistration_digest
       JOIN attempts attempt ON attempt.run_id = run.id
       JOIN leases lease ON lease.attempt_id = attempt.id
       WHERE member.commit_digest = NEW.digest AND lease.state = 'active'
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN runs run ON run.benchmark_preregistration_digest = invalidation.preregistration_digest
       JOIN attempts attempt ON attempt.run_id = run.id
       WHERE member.commit_digest = NEW.digest
         AND attempt.state IN ('created','dispatched','acked','running','result_pending','unknown')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN runs run ON run.benchmark_preregistration_digest = invalidation.preregistration_digest
       JOIN node_versions node ON node.run_id = run.id
       WHERE member.commit_digest = NEW.digest
         AND node.state IN ('pending','ready','dispatched')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN runs run ON run.benchmark_preregistration_digest = invalidation.preregistration_digest
       WHERE member.commit_digest = NEW.digest
         AND run.state IN ('created','active','blocked','paused')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN benchmark_arm_runs arm ON arm.preregistration_digest = invalidation.preregistration_digest
       JOIN benchmark_blind_assignments assignment ON assignment.arm_execution_id = arm.arm_execution_id
       JOIN outbox message ON message.attempt_id = assignment.evaluator_attempt_id
       WHERE member.commit_digest = NEW.digest
         AND message.state IN ('pending','claimed','sent','unknown')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN benchmark_arm_runs arm ON arm.preregistration_digest = invalidation.preregistration_digest
       JOIN benchmark_blind_assignments assignment ON assignment.arm_execution_id = arm.arm_execution_id
       JOIN leases lease ON lease.attempt_id = assignment.evaluator_attempt_id
       WHERE member.commit_digest = NEW.digest AND lease.state = 'active'
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN benchmark_arm_runs arm ON arm.preregistration_digest = invalidation.preregistration_digest
       JOIN benchmark_blind_assignments assignment ON assignment.arm_execution_id = arm.arm_execution_id
       JOIN attempts evaluator ON evaluator.id = assignment.evaluator_attempt_id
       WHERE member.commit_digest = NEW.digest
         AND evaluator.state IN ('created','dispatched','acked','running','result_pending','unknown')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN benchmark_arm_runs arm ON arm.preregistration_digest = invalidation.preregistration_digest
       JOIN benchmark_blind_assignments assignment ON assignment.arm_execution_id = arm.arm_execution_id
       JOIN attempts evaluator ON evaluator.id = assignment.evaluator_attempt_id
       JOIN node_versions node ON node.id = evaluator.node_version_id
       WHERE member.commit_digest = NEW.digest
         AND node.state IN ('pending','ready','dispatched')
     )
     OR EXISTS (
       SELECT 1
       FROM benchmark_campaign_invalidation_commit_members member
       JOIN benchmark_campaign_invalidations invalidation ON invalidation.id = member.invalidation_id
       JOIN benchmark_arm_runs arm ON arm.preregistration_digest = invalidation.preregistration_digest
       JOIN benchmark_blind_assignments assignment ON assignment.arm_execution_id = arm.arm_execution_id
       JOIN attempts evaluator ON evaluator.id = assignment.evaluator_attempt_id
       JOIN runs evaluator_run ON evaluator_run.id = evaluator.run_id
       WHERE member.commit_digest = NEW.digest
         AND evaluator_run.state IN ('created','active','blocked','paused')
     )
     OR NOT EXISTS (
       SELECT 1
       FROM current_valid_keys signer_key
       JOIN principals signer ON signer.id = signer_key.principal_id
       WHERE signer_key.key_id = NEW.signer_key_id
         AND signer_key.principal_id = NEW.signer_principal_id
         AND signer_key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_campaign_invalidation_commit'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.invalidation_set_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.committed_at_ms - 5000 AND NEW.committed_at_ms
     );
END;

