BEGIN SELECT RAISE(ABORT, 'benchmark invalidation commit membership is immutable'); END;

CREATE TRIGGER benchmark_blinded_candidate_package_is_exact_normalized_and_signed
BEFORE INSERT ON benchmark_blinded_candidate_packages
BEGIN
  SELECT RAISE(ABORT, 'benchmark blinded package is not an exact normalized leakage-scanned candidate')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.blind_code') IS NOT NEW.blind_code
     OR json_extract(NEW.canonical_json, '$.normalized_archive_artifact_instance_id') IS NOT NEW.normalized_archive_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.normalizer_closure_digest') IS NOT NEW.normalizer_closure_digest
     OR json_extract(NEW.canonical_json, '$.leakage_scan_attestation_digest') IS NOT NEW.leakage_scan_attestation_digest
     OR json_extract(NEW.canonical_json, '$.source_candidate_artifact_instance_id') IS NOT NEW.source_candidate_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_arm_runs arm
       JOIN benchmark_study_protocols protocol
         ON protocol.preregistration_digest = arm.preregistration_digest
       JOIN configuration_artifacts normalizer
         ON normalizer.digest = NEW.normalizer_closure_digest
        AND normalizer.artifact_kind = 'benchmark_normalizer_closure'
       JOIN artifact_instances source
         ON source.id = NEW.source_candidate_artifact_instance_id
       JOIN benchmark_arm_run_members delivery_member
         ON delivery_member.arm_execution_id = arm.arm_execution_id
        AND delivery_member.phase_no = 2 AND delivery_member.run_kind = 'delivery'
       JOIN runs delivery_run
         ON delivery_run.id = delivery_member.run_id AND delivery_run.state = 'completed'
       JOIN run_completion_seals completion
         ON completion.run_id = delivery_run.id
        AND completion.final_artifact_instance_id = source.id
       JOIN artifact_instances normalized
         ON normalized.id = NEW.normalized_archive_artifact_instance_id
        AND normalized.project_id = arm.project_id
        AND normalized.run_id = delivery_run.id
        AND normalized.artifact_type = 'sanitized_assets'
        AND normalized.producer_attempt_id IS NULL
       JOIN artifact_inputs normalized_edge
         ON normalized_edge.artifact_instance_id = normalized.id
        AND normalized_edge.input_artifact_instance_id = source.id
        AND normalized_edge.relation = 'normalized_blind_summary'
       JOIN artifact_manifests normalized_manifest
         ON normalized_manifest.digest = normalized.manifest_digest
       JOIN sanitization_attestations leakage
         ON leakage.digest = NEW.leakage_scan_attestation_digest
        AND leakage.subject_manifest_digest = normalized.manifest_digest
        AND leakage.rules_digest = protocol.leakage_scan_rules_digest
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'approval_broker'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE arm.arm_execution_id = NEW.arm_execution_id
         AND protocol.normalizer_closure_digest = NEW.normalizer_closure_digest
         AND source.project_id = arm.project_id
         AND source.run_id = delivery_run.id
         AND source.artifact_type = 'node_output'
         AND json_extract(normalized_manifest.canonical_json, '$.artifact_type') = 'sanitized_assets'
         AND json_extract(normalized_manifest.canonical_json, '$.benchmark_blind.blind_code') = NEW.blind_code
         AND json_extract(normalized_manifest.canonical_json, '$.benchmark_blind.package_digest') = NEW.digest
         AND json_extract(normalized_manifest.canonical_json, '$.benchmark_blind.normalizer_closure_digest') = normalizer.digest
         AND json_extract(normalized_manifest.canonical_json, '$.benchmark_blind.source_candidate_digest') = source.blob_digest
         AND json_extract(normalizer.canonical_json, '$.forbidden_identity_field_audit') = 'pass'
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest IN (
             normalizer.digest, protocol.leakage_scan_rules_digest
           )
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = arm.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_randomization_reveals reveal
           WHERE reveal.preregistration_digest = arm.preregistration_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_blinded_candidate_package'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = (
           SELECT normalized.blob_digest FROM artifact_instances normalized
           WHERE normalized.id = NEW.normalized_archive_artifact_instance_id
         )
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER benchmark_blinded_candidate_packages_no_update
BEFORE UPDATE ON benchmark_blinded_candidate_packages
BEGIN SELECT RAISE(ABORT, 'benchmark blinded candidate packages are immutable'); END;

CREATE TRIGGER benchmark_blinded_candidate_packages_no_delete
BEFORE DELETE ON benchmark_blinded_candidate_packages
BEGIN SELECT RAISE(ABORT, 'benchmark blinded candidate packages are immutable'); END;

CREATE TRIGGER benchmark_evaluator_input_is_detached_strict_and_signed
BEFORE INSERT ON benchmark_evaluator_inputs
BEGIN
  SELECT RAISE(ABORT, 'benchmark evaluator input is not a detached identity-free package')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.blind_code') IS NOT NEW.blind_code
     OR json_extract(NEW.canonical_json, '$.blinded_package_digest') IS NOT NEW.blinded_package_digest
     OR json_extract(NEW.canonical_json, '$.normalized_artifact_instance_id') IS NOT NEW.normalized_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.normalized_blob_digest') IS NOT NEW.normalized_blob_digest
     OR json_extract(NEW.canonical_json, '$.detached_manifest_digest') IS NOT NEW.detached_manifest_digest
     OR json_extract(NEW.canonical_json, '$.evaluator_attempt_id') IS NOT NEW.evaluator_attempt_id
     OR json_extract(NEW.canonical_json, '$.rubric_policy_digest') IS NOT NEW.rubric_policy_digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.task_id') IS NOT NEW.task_id
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.leakage_scan_attestation_digest') IS NOT NEW.leakage_scan_attestation_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_blinded_candidate_packages package
       JOIN benchmark_arm_runs arm ON arm.arm_execution_id = package.arm_execution_id
       JOIN artifact_instances normalized
         ON normalized.id = package.normalized_archive_artifact_instance_id
       JOIN artifact_blobs blob ON blob.digest = normalized.blob_digest
       JOIN artifact_manifests detached ON detached.digest = NEW.detached_manifest_digest
       JOIN current_valid_keys detached_key
         ON detached_key.key_id = detached.signer_key_id
        AND detached_key.key_purpose = 'artifact_broker'
       JOIN attempts evaluator ON evaluator.id = NEW.evaluator_attempt_id
       JOIN runs evaluator_run ON evaluator_run.id = evaluator.run_id
       JOIN work_packets packet ON packet.attempt_id = evaluator.id
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       WHERE package.digest = NEW.blinded_package_digest
         AND package.blind_code = NEW.blind_code
         AND package.leakage_scan_attestation_digest = NEW.leakage_scan_attestation_digest
         AND normalized.id = NEW.normalized_artifact_instance_id
         AND blob.digest = NEW.normalized_blob_digest
         AND arm.preregistration_digest = NEW.preregistration_digest
         AND arm.task_id = NEW.task_id AND arm.arm = NEW.arm
         AND arm.arm_execution_id = NEW.arm_execution_id
         AND NEW.rubric_policy_digest = (
           SELECT preregistration.evaluation_rubric_policy_digest
           FROM benchmark_preregistrations preregistration
           WHERE preregistration.digest = arm.preregistration_digest
         )
         AND evaluator.state = 'created'
         AND evaluator.project_id <> arm.project_id
         AND evaluator_run.benchmark_preregistration_digest IS NULL
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_runs participant
           WHERE participant.project_id = evaluator.project_id
         )
         AND packet.input_manifest_digest = detached.digest
         AND detached.schema_version = 1
         AND json_type(detached.canonical_json) = 'object'
         AND (SELECT COUNT(*) FROM json_each(detached.canonical_json)) = 12
         AND NOT EXISTS (
           SELECT 1 FROM json_each(detached.canonical_json) field
           WHERE field.key NOT IN (
             'digest','schema_version','artifact_type','blind_code','blinded_package_digest',
             'blob_digest','size_bytes','media_type','rubric_policy_digest',
             'created_at_ms','signer_principal_id','signer_key_id'
           )
         )
         AND json_extract(detached.canonical_json, '$.digest') = detached.digest
         AND json_extract(detached.canonical_json, '$.schema_version') = 1
         AND json_extract(detached.canonical_json, '$.artifact_type') = 'benchmark_evaluator_input'
         AND json_extract(detached.canonical_json, '$.blind_code') = NEW.blind_code
         AND json_extract(detached.canonical_json, '$.blinded_package_digest') = NEW.blinded_package_digest
         AND json_extract(detached.canonical_json, '$.blob_digest') = blob.digest
         AND json_extract(detached.canonical_json, '$.size_bytes') = blob.size_bytes
         AND json_extract(detached.canonical_json, '$.media_type') = blob.media_type
         AND json_extract(detached.canonical_json, '$.rubric_policy_digest') = NEW.rubric_policy_digest
         AND json_extract(detached.canonical_json, '$.created_at_ms') = detached.created_at_ms
         AND json_extract(detached.canonical_json, '$.signer_principal_id') = detached.signer_principal_id
         AND json_extract(detached.canonical_json, '$.signer_key_id') = detached.signer_key_id
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = arm.preregistration_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_evaluator_input_manifest_v1'
         AND receipt.record_id = NEW.detached_manifest_digest
         AND receipt.record_canonical_json = (
           SELECT manifest.canonical_json FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.detached_manifest_digest
         )
         AND receipt.record_signer_key_id = (
           SELECT manifest.signer_key_id FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.detached_manifest_digest
         )
         AND receipt.record_signature = (
           SELECT manifest.signature FROM artifact_manifests manifest
           WHERE manifest.digest = NEW.detached_manifest_digest
         )
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.normalized_blob_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.detached_manifest_digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     )
     OR NOT EXISTS (
       SELECT 1
       FROM work_packets packet
       JOIN current_valid_signature_receipts receipt
         ON receipt.record_kind = 'benchmark_evaluator_work_packet_v1'
        AND receipt.record_id = packet.digest
        AND receipt.record_canonical_json = packet.canonical_json
        AND receipt.record_signer_key_id = packet.signer_key_id
        AND receipt.record_signature = packet.signature
        AND receipt.referenced_digests_verified = 1
       WHERE packet.attempt_id = NEW.evaluator_attempt_id
         AND packet.input_manifest_digest = NEW.detached_manifest_digest
         AND json_type(packet.canonical_json) = 'object'
         AND (SELECT COUNT(*) FROM json_each(packet.canonical_json)) = 7
         AND NOT EXISTS (
           SELECT 1 FROM json_each(packet.canonical_json) field
           WHERE field.key NOT IN (
             'digest','attempt_id','signer_key_id','created_at_ms',
             'lineage','cost_envelope','benchmark_evaluator'
           )
         )
         AND json_type(packet.canonical_json, '$.lineage') = 'object'
         AND (SELECT COUNT(*) FROM json_each(packet.canonical_json, '$.lineage')) = 3
         AND NOT EXISTS (
           SELECT 1 FROM json_each(packet.canonical_json, '$.lineage') field
           WHERE field.key NOT IN ('lineage_digest','input_manifest_digest','output_schema_digest')
         )
         AND json_type(packet.canonical_json, '$.cost_envelope') = 'object'
         AND (SELECT COUNT(*) FROM json_each(packet.canonical_json, '$.cost_envelope')) = 8
         AND NOT EXISTS (
           SELECT 1 FROM json_each(packet.canonical_json, '$.cost_envelope') field
           WHERE field.key NOT IN (
             'pricing_catalog_digest','max_input_tokens','max_output_tokens',
             'max_cache_read_tokens','max_cache_write_tokens','max_tool_calls',
             'max_wall_time_ms','required_reservation_micro_usd'
           )
         )
         AND json_type(packet.canonical_json, '$.benchmark_evaluator') = 'object'
         AND (SELECT COUNT(*) FROM json_each(packet.canonical_json, '$.benchmark_evaluator')) = 2
         AND NOT EXISTS (
           SELECT 1 FROM json_each(packet.canonical_json, '$.benchmark_evaluator') field
           WHERE field.key NOT IN ('blind_code','blinded_package_digest')
         )
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blind_code') = NEW.blind_code
         AND json_extract(packet.canonical_json, '$.benchmark_evaluator.blinded_package_digest') = NEW.blinded_package_digest
         AND json_type(packet.canonical_json, '$.benchmark') IS NULL
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_evaluator_input_binding'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER benchmark_evaluator_inputs_no_update
BEFORE UPDATE ON benchmark_evaluator_inputs
BEGIN SELECT RAISE(ABORT, 'benchmark evaluator inputs are immutable'); END;

CREATE TRIGGER benchmark_evaluator_inputs_no_delete
BEFORE DELETE ON benchmark_evaluator_inputs
BEGIN SELECT RAISE(ABORT, 'benchmark evaluator inputs are immutable'); END;

CREATE TRIGGER benchmark_evaluator_output_binding_is_exact_private_and_signed
BEFORE INSERT ON benchmark_evaluator_output_bindings
BEGIN
  SELECT RAISE(ABORT, 'benchmark evaluator output binding is not exact, private, taintable, or broker signed')
  WHERE NEW.bound_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.bound_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_type(NEW.canonical_json) <> 'object'
     OR (SELECT COUNT(*) FROM json_each(NEW.canonical_json)) <> 16
     OR EXISTS (
       SELECT 1 FROM json_each(NEW.canonical_json) field
       WHERE field.key NOT IN (
         'digest','version','evaluator_input_digest','evaluator_attempt_id',
         'result_envelope_id','output_artifact_instance_id','output_manifest_digest',
         'output_blob_digest','source_normalized_artifact_instance_id',
         'preregistration_digest','task_id','arm','arm_execution_id',
         'signer_principal_id','signer_key_id','bound_at_ms'
       )
     )
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.version') IS NOT NEW.version
     OR json_extract(NEW.canonical_json, '$.evaluator_input_digest') IS NOT NEW.evaluator_input_digest
     OR json_extract(NEW.canonical_json, '$.evaluator_attempt_id') IS NOT NEW.evaluator_attempt_id
     OR json_extract(NEW.canonical_json, '$.result_envelope_id') IS NOT NEW.result_envelope_id
     OR json_extract(NEW.canonical_json, '$.output_artifact_instance_id') IS NOT NEW.output_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.output_manifest_digest') IS NOT NEW.output_manifest_digest
     OR json_extract(NEW.canonical_json, '$.output_blob_digest') IS NOT NEW.output_blob_digest
     OR json_extract(NEW.canonical_json, '$.source_normalized_artifact_instance_id') IS NOT NEW.source_normalized_artifact_instance_id
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.task_id') IS NOT NEW.task_id
     OR json_extract(NEW.canonical_json, '$.arm') IS NOT NEW.arm
     OR json_extract(NEW.canonical_json, '$.arm_execution_id') IS NOT NEW.arm_execution_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.bound_at_ms') IS NOT NEW.bound_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_evaluator_inputs input
       JOIN benchmark_blind_assignments assignment
         ON assignment.evaluator_attempt_id = input.evaluator_attempt_id
        AND assignment.arm_execution_id = input.arm_execution_id
        AND assignment.blind_code = input.blind_code
        AND assignment.blinded_package_digest = input.blinded_package_digest
       JOIN benchmark_arm_runs arm
         ON arm.arm_execution_id = input.arm_execution_id
        AND arm.preregistration_digest = input.preregistration_digest
        AND arm.task_id = input.task_id
        AND arm.arm = input.arm
       JOIN benchmark_arm_settlement_seals settlement
         ON settlement.arm_execution_id = arm.arm_execution_id
       JOIN attempts evaluator
         ON evaluator.id = input.evaluator_attempt_id
        AND evaluator.state = 'result_pending'
       JOIN runs evaluator_run
         ON evaluator_run.id = evaluator.run_id
        AND evaluator_run.benchmark_preregistration_digest IS NULL
       JOIN result_envelopes result
         ON result.id = NEW.result_envelope_id
        AND result.attempt_id = evaluator.id
        AND result.state = 'prevalidated'
        AND result.input_manifest_digest = input.detached_manifest_digest
        AND result.output_manifest_digest = NEW.output_manifest_digest
       JOIN schema_validation_attestations validation
         ON validation.result_envelope_id = result.id
        AND validation.output_manifest_digest = NEW.output_manifest_digest
        AND validation.verdict = 'pass'
       JOIN artifact_instances output
         ON output.id = NEW.output_artifact_instance_id
        AND output.manifest_digest = NEW.output_manifest_digest
        AND output.blob_digest = NEW.output_blob_digest
        AND output.project_id = evaluator.project_id
        AND output.run_id = evaluator.run_id
        AND output.node_version_id = evaluator.node_version_id
        AND output.producer_attempt_id = evaluator.id
        AND output.artifact_type = 'evidence'
       JOIN artifact_instances normalized
         ON normalized.id = input.normalized_artifact_instance_id
        AND normalized.id = NEW.source_normalized_artifact_instance_id
        AND normalized.blob_digest = input.normalized_blob_digest
        AND normalized.project_id = arm.project_id
       JOIN artifact_instance_taints source_taint
         ON source_taint.artifact_instance_id = normalized.id
        AND source_taint.preregistration_digest = arm.preregistration_digest
        AND source_taint.task_id = arm.task_id
        AND source_taint.arm = arm.arm
       JOIN current_valid_keys broker_key
         ON broker_key.key_id = NEW.signer_key_id
        AND broker_key.principal_id = NEW.signer_principal_id
        AND broker_key.key_purpose = 'approval_broker'
       JOIN principals broker
         ON broker.id = NEW.signer_principal_id
        AND broker.kind = 'service'
       WHERE input.digest = NEW.evaluator_input_digest
         AND input.evaluator_attempt_id = NEW.evaluator_attempt_id
         AND input.preregistration_digest = NEW.preregistration_digest
         AND input.task_id = NEW.task_id
         AND input.arm = NEW.arm
         AND input.arm_execution_id = NEW.arm_execution_id
         AND evaluator.project_id <> arm.project_id
         AND result.received_at_ms <= NEW.bound_at_ms
         AND output.created_at_ms <= NEW.bound_at_ms
         AND settlement.sealed_at_ms <= assignment.assigned_at_ms
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           WHERE invalidation.settlement_digest = settlement.digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_budget_breaches breach
           WHERE breach.arm_execution_id = arm.arm_execution_id
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = arm.preregistration_digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_evaluator_output_binding_v1'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.output_blob_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.bound_at_ms - 5000 AND NEW.bound_at_ms
     );
END;

CREATE TRIGGER benchmark_evaluator_output_binding_applies_exact_taint
AFTER INSERT ON benchmark_evaluator_output_bindings
BEGIN
  INSERT INTO artifact_instance_taints(
    id, artifact_instance_id, blob_digest, preregistration_digest, task_id, arm,
    source_artifact_instance_id, source_input_artifact_instance_id,
    reason, created_at_ms
  )
  SELECT 'artifact-taint:' || NEW.output_artifact_instance_id || ':'
           || NEW.preregistration_digest || ':' || NEW.task_id || ':' || NEW.arm,
         NEW.output_artifact_instance_id, NEW.output_blob_digest,
         NEW.preregistration_digest, NEW.task_id, NEW.arm,
         NEW.output_artifact_instance_id, NEW.source_normalized_artifact_instance_id,
         'benchmark_evaluator_output', output.created_at_ms
  FROM artifact_instances output
  WHERE output.id = NEW.output_artifact_instance_id;
END;

CREATE TRIGGER benchmark_evaluator_output_bindings_no_update
BEFORE UPDATE ON benchmark_evaluator_output_bindings
BEGIN SELECT RAISE(ABORT, 'benchmark evaluator output bindings are immutable'); END;

CREATE TRIGGER benchmark_evaluator_output_bindings_no_delete
BEFORE DELETE ON benchmark_evaluator_output_bindings
BEGIN SELECT RAISE(ABORT, 'benchmark evaluator output bindings are immutable'); END;

CREATE TRIGGER benchmark_evaluator_dispatch_requires_detached_input
BEFORE UPDATE OF state ON attempts
WHEN OLD.state = 'created' AND NEW.state = 'dispatched'
 AND EXISTS (
   SELECT 1 FROM executor_capabilities capability
   WHERE capability.executor_id = NEW.executor_id
     AND capability.capability = 'benchmark-evaluator'
 )
BEGIN
  SELECT RAISE(ABORT, 'benchmark evaluator dispatch lacks its detached strict input')
  WHERE NOT EXISTS (
    SELECT 1 FROM benchmark_evaluator_inputs input
    JOIN work_packets packet ON packet.attempt_id = NEW.id
    WHERE input.evaluator_attempt_id = NEW.id
      AND packet.input_manifest_digest = input.detached_manifest_digest
  );
END;

CREATE TRIGGER benchmark_campaign_completion_is_exact_complete_and_signed
BEFORE INSERT ON benchmark_campaign_completion_seals
BEGIN
  SELECT RAISE(ABORT, 'benchmark campaign completion is partial, invalid, or not exactly sealed')
  WHERE NEW.sealed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.sealed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.completed_task_count') IS NOT NEW.completed_task_count
     OR json_extract(NEW.canonical_json, '$.completed_arm_count') IS NOT NEW.completed_arm_count
     OR json_extract(NEW.canonical_json, '$.ordered_input_snapshot_manifest_digest') IS NOT NEW.ordered_input_snapshot_manifest_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.sealed_at_ms') IS NOT NEW.sealed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_study_protocols protocol
       JOIN benchmark_preregistrations preregistration
         ON preregistration.digest = protocol.preregistration_digest
       JOIN artifact_manifests snapshot
         ON snapshot.digest = NEW.ordered_input_snapshot_manifest_digest
       JOIN current_valid_keys snapshot_key
         ON snapshot_key.key_id = snapshot.signer_key_id
        AND snapshot_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE protocol.preregistration_digest = NEW.preregistration_digest
         AND NEW.completed_task_count = protocol.required_task_count
         AND NEW.completed_task_count = (
           SELECT COUNT(*) FROM benchmark_tasks task
           WHERE task.preregistration_digest = NEW.preregistration_digest
         )
         AND NEW.completed_arm_count = NEW.completed_task_count * 4
         AND NEW.completed_arm_count = (
           SELECT COUNT(*) FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
         )
         AND (SELECT COUNT(*) FROM benchmark_tasks task
              WHERE task.preregistration_digest = NEW.preregistration_digest
                AND task.risk_stratum = 'low') >= protocol.minimum_tasks_per_risk_stratum
         AND (SELECT COUNT(*) FROM benchmark_tasks task
              WHERE task.preregistration_digest = NEW.preregistration_digest
                AND task.risk_stratum = 'medium') >= protocol.minimum_tasks_per_risk_stratum
         AND (SELECT COUNT(*) FROM benchmark_tasks task
              WHERE task.preregistration_digest = NEW.preregistration_digest
                AND task.risk_stratum = 'high') >= protocol.minimum_tasks_per_risk_stratum
         AND json_extract(snapshot.canonical_json, '$.artifact_type') = 'evidence'
         AND json_extract(snapshot.canonical_json, '$.benchmark_completion.preregistration_digest') = NEW.preregistration_digest
         AND json_type(snapshot.canonical_json, '$.benchmark_completion.inputs') = 'array'
         AND json_array_length(snapshot.canonical_json, '$.benchmark_completion.inputs') = NEW.completed_arm_count
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = NEW.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_runs arm
           WHERE arm.preregistration_digest = NEW.preregistration_digest
             AND (
               (SELECT COUNT(*) FROM benchmark_arm_run_members member
                JOIN runs run ON run.id = member.run_id
                JOIN run_completion_seals completion ON completion.run_id = run.id
                WHERE member.arm_execution_id = arm.arm_execution_id
                  AND run.state = 'completed') <> 2
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_treatment_execution_receipts execution
                 WHERE execution.arm_execution_id = arm.arm_execution_id
                   AND execution.realized_attempt_count = (
                     SELECT COUNT(*)
                     FROM benchmark_arm_run_members receipt_member
                     JOIN attempts receipt_attempt ON receipt_attempt.run_id = receipt_member.run_id
                     WHERE receipt_member.arm_execution_id = arm.arm_execution_id
                   )
                   AND execution.treatment_spec_manifest_digest = arm.treatment_spec_manifest_digest
               )
               OR EXISTS (
                 SELECT 1 FROM benchmark_arm_budget_breaches breach
                 WHERE breach.arm_execution_id = arm.arm_execution_id
               )
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_arm_settlement_seals settlement
                 WHERE settlement.arm_execution_id = arm.arm_execution_id
                   AND NOT EXISTS (
                     SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
                     WHERE invalidation.settlement_digest = settlement.digest
                   )
               )
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_blinded_candidate_packages package
                 WHERE package.arm_execution_id = arm.arm_execution_id
               )
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_blind_assignments assignment
                 WHERE assignment.arm_execution_id = arm.arm_execution_id
               )
               OR NOT EXISTS (
                 SELECT 1 FROM benchmark_evaluations evaluation
                 WHERE evaluation.preregistration_digest = arm.preregistration_digest
                   AND evaluation.task_id = arm.task_id AND evaluation.arm = arm.arm
               )
               OR NOT EXISTS (
                 SELECT 1
                 FROM json_each(snapshot.canonical_json, '$.benchmark_completion.inputs') item
                 JOIN benchmark_treatment_execution_receipts execution
                   ON execution.arm_execution_id = arm.arm_execution_id
                 JOIN benchmark_arm_settlement_seals settlement
                   ON settlement.arm_execution_id = arm.arm_execution_id
                 JOIN benchmark_blinded_candidate_packages package
                   ON package.arm_execution_id = arm.arm_execution_id
                 JOIN benchmark_evaluations evaluation
                   ON evaluation.preregistration_digest = arm.preregistration_digest
                  AND evaluation.task_id = arm.task_id AND evaluation.arm = arm.arm
                 WHERE json_extract(item.value, '$.arm_execution_id') = arm.arm_execution_id
                   AND json_extract(item.value, '$.treatment_execution_receipt_digest') = execution.digest
                   AND json_extract(item.value, '$.settlement_digest') = settlement.digest
                   AND json_extract(item.value, '$.blinded_package_digest') = package.digest
                   AND json_extract(item.value, '$.evaluation_id') = evaluation.id
                   AND json_extract(item.value, '$.evaluator_output_binding_digest')
                       = evaluation.evaluator_output_binding_digest
               )
             )
         )
         AND NOT EXISTS (
           SELECT 1 FROM json_each(snapshot.canonical_json, '$.benchmark_completion.inputs') item
           WHERE NOT EXISTS (
             SELECT 1 FROM benchmark_arm_runs arm
             WHERE arm.preregistration_digest = NEW.preregistration_digest
               AND arm.arm_execution_id = json_extract(item.value, '$.arm_execution_id')
           )
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_tasks task
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND (SELECT COUNT(*) FROM benchmark_arm_runs arm
                  WHERE arm.preregistration_digest = task.preregistration_digest
                    AND arm.task_id = task.task_id) <> 4
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_tasks task
           JOIN benchmark_arm_runs c
             ON c.preregistration_digest = task.preregistration_digest
            AND c.task_id = task.task_id AND c.arm = 'C'
           JOIN benchmark_arm_runs d
             ON d.preregistration_digest = task.preregistration_digest
            AND d.task_id = task.task_id AND d.arm = 'D'
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND c.inference_budget_digest <> d.inference_budget_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_tasks task
           JOIN benchmark_arm_runs c
             ON c.preregistration_digest = task.preregistration_digest
            AND c.task_id = task.task_id AND c.arm = 'C'
           JOIN benchmark_arm_runs d
             ON d.preregistration_digest = task.preregistration_digest
            AND d.task_id = task.task_id AND d.arm = 'D'
           JOIN benchmark_treatment_execution_receipts c_execution
             ON c_execution.arm_execution_id = c.arm_execution_id
           JOIN benchmark_treatment_execution_receipts d_execution
             ON d_execution.arm_execution_id = d.arm_execution_id
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND (
               c_execution.realized_delivery_graph_digest
                 <> d_execution.realized_delivery_graph_digest
               OR c_execution.realized_ordered_model_call_cells_digest
                 <> d_execution.realized_ordered_model_call_cells_digest
               OR c_execution.realized_call_cell_count
                 <> d_execution.realized_call_cell_count
             )
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_tasks task
           JOIN benchmark_arm_runs c
             ON c.preregistration_digest = task.preregistration_digest
            AND c.task_id = task.task_id AND c.arm = 'C'
           JOIN benchmark_arm_runs d
             ON d.preregistration_digest = task.preregistration_digest
            AND d.task_id = task.task_id AND d.arm = 'D'
           JOIN benchmark_realized_call_cells c_cell
             ON c_cell.arm_execution_id = c.arm_execution_id
           LEFT JOIN benchmark_realized_call_cells d_cell
             ON d_cell.arm_execution_id = d.arm_execution_id
            AND d_cell.cell_no = c_cell.cell_no
            AND d_cell.phase_no = c_cell.phase_no
            AND d_cell.provider = c_cell.provider
            AND d_cell.runtime = c_cell.runtime
            AND d_cell.requested_model = c_cell.requested_model
            AND d_cell.requested_profile = c_cell.requested_profile
            AND d_cell.model = c_cell.model
            AND d_cell.model_family = c_cell.model_family
            AND d_cell.profile = c_cell.profile
            AND d_cell.max_input_tokens = c_cell.max_input_tokens
            AND d_cell.max_output_tokens = c_cell.max_output_tokens
            AND d_cell.max_cache_read_tokens = c_cell.max_cache_read_tokens
            AND d_cell.max_cache_write_tokens = c_cell.max_cache_write_tokens
            AND d_cell.max_tool_calls = c_cell.max_tool_calls
            AND d_cell.max_wall_time_ms = c_cell.max_wall_time_ms
            AND d_cell.required_reservation_micro_usd = c_cell.required_reservation_micro_usd
            AND d_cell.parity_cell_digest = c_cell.parity_cell_digest
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND d_cell.digest IS NULL
         )
         AND NOT EXISTS (
           SELECT 1
           FROM benchmark_tasks task
           JOIN benchmark_arm_runs c
             ON c.preregistration_digest = task.preregistration_digest
            AND c.task_id = task.task_id AND c.arm = 'C'
           JOIN benchmark_arm_runs d
             ON d.preregistration_digest = task.preregistration_digest
            AND d.task_id = task.task_id AND d.arm = 'D'
           JOIN benchmark_realized_call_cells d_cell
             ON d_cell.arm_execution_id = d.arm_execution_id
           LEFT JOIN benchmark_realized_call_cells c_cell
             ON c_cell.arm_execution_id = c.arm_execution_id
            AND c_cell.cell_no = d_cell.cell_no
            AND c_cell.phase_no = d_cell.phase_no
            AND c_cell.provider = d_cell.provider
            AND c_cell.runtime = d_cell.runtime
            AND c_cell.requested_model = d_cell.requested_model
            AND c_cell.requested_profile = d_cell.requested_profile
            AND c_cell.model = d_cell.model
            AND c_cell.model_family = d_cell.model_family
            AND c_cell.profile = d_cell.profile
            AND c_cell.max_input_tokens = d_cell.max_input_tokens
            AND c_cell.max_output_tokens = d_cell.max_output_tokens
            AND c_cell.max_cache_read_tokens = d_cell.max_cache_read_tokens
            AND c_cell.max_cache_write_tokens = d_cell.max_cache_write_tokens
            AND c_cell.max_tool_calls = d_cell.max_tool_calls
            AND c_cell.max_wall_time_ms = d_cell.max_wall_time_ms
            AND c_cell.required_reservation_micro_usd = d_cell.required_reservation_micro_usd
            AND c_cell.parity_cell_digest = d_cell.parity_cell_digest
           WHERE task.preregistration_digest = NEW.preregistration_digest
             AND c_cell.digest IS NULL
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_campaign_completion_seal'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.sealed_at_ms - 5000 AND NEW.sealed_at_ms
     );
END;

CREATE TRIGGER benchmark_campaign_completion_seals_no_update
BEFORE UPDATE ON benchmark_campaign_completion_seals
BEGIN SELECT RAISE(ABORT, 'benchmark campaign completion seals are immutable'); END;

CREATE TRIGGER benchmark_campaign_completion_seals_no_delete
BEFORE DELETE ON benchmark_campaign_completion_seals
BEGIN SELECT RAISE(ABORT, 'benchmark campaign completion seals are immutable'); END;

CREATE TRIGGER benchmark_analysis_receipt_is_exact_pinned_and_signed
BEFORE INSERT ON benchmark_analysis_receipts
BEGIN
  SELECT RAISE(ABORT, 'benchmark analysis receipt does not pin the completed revealed study')
  WHERE NEW.analyzed_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.analyzed_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR length(NEW.bootstrap_seed_digest) <> 71
     OR substr(NEW.bootstrap_seed_digest, 1, 7) <> 'sha256:'
     OR substr(NEW.bootstrap_seed_digest, 8) GLOB '*[^0-9a-f]*'
     OR json_type(NEW.exclusions_json) <> 'array'
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.preregistration_digest') IS NOT NEW.preregistration_digest
     OR json_extract(NEW.canonical_json, '$.completion_seal_digest') IS NOT NEW.completion_seal_digest
     OR json_extract(NEW.canonical_json, '$.randomization_reveal_digest') IS NOT NEW.randomization_reveal_digest
     OR json_extract(NEW.canonical_json, '$.ordered_input_snapshot_manifest_digest') IS NOT NEW.ordered_input_snapshot_manifest_digest
     OR json_extract(NEW.canonical_json, '$.analysis_policy_digest') IS NOT NEW.analysis_policy_digest
     OR json_extract(NEW.canonical_json, '$.adoption_rule_policy_digest') IS NOT NEW.adoption_rule_policy_digest
     OR json_extract(NEW.canonical_json, '$.analysis_closure_digest') IS NOT NEW.analysis_closure_digest
     OR json_extract(NEW.canonical_json, '$.bootstrap_seed_digest') IS NOT NEW.bootstrap_seed_digest
     OR json_extract(NEW.canonical_json, '$.output_manifest_digest') IS NOT NEW.output_manifest_digest
     OR json_extract(NEW.canonical_json, '$.exclusions_json') IS NOT NEW.exclusions_json
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.analyzed_at_ms') IS NOT NEW.analyzed_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_study_protocols protocol
       JOIN benchmark_campaign_completion_seals completion
         ON completion.preregistration_digest = protocol.preregistration_digest
        AND completion.digest = NEW.completion_seal_digest
       JOIN benchmark_randomization_reveals reveal
         ON reveal.preregistration_digest = protocol.preregistration_digest
        AND reveal.digest = NEW.randomization_reveal_digest
        AND reveal.completion_seal_digest = completion.digest
       JOIN policies analysis_policy
         ON analysis_policy.digest = NEW.analysis_policy_digest
       JOIN policies adoption_policy
         ON adoption_policy.digest = NEW.adoption_rule_policy_digest
       JOIN configuration_artifacts analyzer
         ON analyzer.digest = NEW.analysis_closure_digest
        AND analyzer.artifact_kind = 'benchmark_analysis_closure'
       JOIN artifact_manifests output ON output.digest = NEW.output_manifest_digest
       JOIN current_valid_keys output_key
         ON output_key.key_id = output.signer_key_id
        AND output_key.key_purpose = 'artifact_broker'
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'schema_validator'
       JOIN principals signer ON signer.id = NEW.signer_principal_id AND signer.kind = 'service'
       WHERE protocol.preregistration_digest = NEW.preregistration_digest
         AND protocol.analysis_policy_digest = analysis_policy.digest
         AND protocol.adoption_rule_policy_digest = adoption_policy.digest
         AND protocol.analysis_closure_digest = analyzer.digest
         AND completion.ordered_input_snapshot_manifest_digest = NEW.ordered_input_snapshot_manifest_digest
         AND completion.sealed_at_ms <= reveal.revealed_at_ms
         AND reveal.revealed_at_ms <= NEW.analyzed_at_ms
         AND analysis_policy.policy_type = 'benchmark_analysis'
         AND adoption_policy.policy_type = 'benchmark_adoption'
         AND json(NEW.exclusions_json) = json(json_extract(protocol.canonical_json, '$.analysis.exclusions'))
         AND json_extract(output.canonical_json, '$.artifact_type') = 'evidence'
         AND json_extract(output.canonical_json, '$.benchmark_analysis.preregistration_digest') = NEW.preregistration_digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.completion_seal_digest') = completion.digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.randomization_reveal_digest') = reveal.digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.ordered_input_snapshot_manifest_digest') = NEW.ordered_input_snapshot_manifest_digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.analysis_policy_digest') = analysis_policy.digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.adoption_rule_policy_digest') = adoption_policy.digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.analysis_closure_digest') = analyzer.digest
         AND json_extract(output.canonical_json, '$.benchmark_analysis.bootstrap_seed_digest') = NEW.bootstrap_seed_digest
         AND json(json_extract(output.canonical_json, '$.benchmark_analysis.exclusions')) = json(NEW.exclusions_json)
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = protocol.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           JOIN benchmark_arm_settlement_seals settlement
             ON settlement.digest = invalidation.settlement_digest
           JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
           WHERE arm.preregistration_digest = protocol.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest IN (analysis_policy.digest, adoption_policy.digest)
         )
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest = analyzer.digest
         )
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'benchmark_analysis_receipt'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.referenced_digests_verified = 1
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.output_manifest_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.analyzed_at_ms - 5000 AND NEW.analyzed_at_ms
     );
END;

CREATE TRIGGER benchmark_analysis_receipts_no_update
BEFORE UPDATE ON benchmark_analysis_receipts
BEGIN SELECT RAISE(ABORT, 'benchmark analysis receipts are immutable'); END;

CREATE TRIGGER benchmark_analysis_receipts_no_delete
BEFORE DELETE ON benchmark_analysis_receipts
BEGIN SELECT RAISE(ABORT, 'benchmark analysis receipts are immutable'); END;

CREATE TRIGGER benchmark_adoption_requires_definitive_pinned_uninvalidated_analysis
BEFORE INSERT ON benchmark_adoption_decisions
BEGIN
  SELECT RAISE(ABORT, 'benchmark adoption requires a definitive pinned uninvalidated analysis')
  WHERE json_extract(NEW.canonical_json, '$.c_gain_attribution') IS NOT
        CASE NEW.d_matches_c
          WHEN 1 THEN 'additional_inference_control_explains_gain'
          ELSE 'debate_specific_signal'
        END
     OR NOT EXISTS (
       SELECT 1
       FROM benchmark_study_protocols protocol
       JOIN benchmark_analysis_receipts analysis
         ON analysis.preregistration_digest = protocol.preregistration_digest
        AND analysis.digest = NEW.analysis_receipt_digest
       JOIN benchmark_campaign_completion_seals completion
         ON completion.digest = analysis.completion_seal_digest
       JOIN benchmark_randomization_reveals reveal
         ON reveal.digest = analysis.randomization_reveal_digest
        AND reveal.completion_seal_digest = completion.digest
       JOIN policies adoption_policy
         ON adoption_policy.digest = protocol.adoption_rule_policy_digest
       WHERE protocol.preregistration_digest = NEW.preregistration_digest
         AND protocol.study_phase = 'definitive'
         AND protocol.adoption_eligible = 1
         AND analysis.output_manifest_digest = NEW.analysis_manifest_digest
         AND analysis.analyzed_at_ms <= NEW.decided_at_ms
         AND completion.completed_task_count = NEW.completed_task_count
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.b.minimum_lift_ppm') = 50000
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.b.lower95_must_exceed_ppm') = 0
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.b.max_cost_ratio_ppm') = 1500000
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.b.max_p95_latency_ratio_ppm') = 1500000
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.c_high_risk.minimum_lift_ppm') = 100000
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.c_high_risk.lower95_must_exceed_ppm') = 0
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.c_high_risk.max_cost_ratio_ppm') = 2500000
         AND json_extract(adoption_policy.canonical_json, '$.thresholds.c_high_risk.max_p95_latency_ratio_ppm') = 2000000
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_campaign_invalidations invalidation
           WHERE invalidation.preregistration_digest = protocol.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
           JOIN benchmark_arm_settlement_seals settlement
             ON settlement.digest = invalidation.settlement_digest
           JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
           WHERE arm.preregistration_digest = protocol.preregistration_digest
         )
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations invalidation
           WHERE invalidation.policy_digest = adoption_policy.digest
         )
     );
END;

CREATE TRIGGER benchmark_adoption_invalidation_is_exact_derived
BEFORE INSERT ON benchmark_adoption_invalidations
BEGIN
  SELECT RAISE(ABORT, 'benchmark adoption invalidation is not an exact derived consequence')
  WHERE NEW.id <> 'benchmark-adoption-invalidation:' || NEW.adoption_digest
     OR NOT EXISTS (
       SELECT 1 FROM benchmark_adoption_decisions adoption
       WHERE adoption.digest = NEW.adoption_digest
         AND (
           (NEW.reason = 'campaign_invalidated'
             AND NEW.campaign_invalidation_id IS NOT NULL
             AND NEW.settlement_invalidation_id IS NULL
             AND EXISTS (
               SELECT 1 FROM benchmark_campaign_invalidations invalidation
               WHERE invalidation.id = NEW.campaign_invalidation_id
                 AND invalidation.preregistration_digest = adoption.preregistration_digest
                 AND NEW.invalidated_at_ms = invalidation.invalidated_at_ms
             ))
           OR (NEW.reason = 'late_usage'
             AND NEW.campaign_invalidation_id IS NULL
             AND NEW.settlement_invalidation_id IS NOT NULL
             AND EXISTS (
               SELECT 1 FROM benchmark_arm_settlement_invalidations invalidation
               JOIN benchmark_arm_settlement_seals settlement
                 ON settlement.digest = invalidation.settlement_digest
               JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
               WHERE invalidation.id = NEW.settlement_invalidation_id
                 AND arm.preregistration_digest = adoption.preregistration_digest
                 AND NEW.invalidated_at_ms = invalidation.invalidated_at_ms
             ))
         )
     );
END;

CREATE TRIGGER benchmark_campaign_invalidation_invalidates_existing_adoption
AFTER INSERT ON benchmark_campaign_invalidations
BEGIN
  INSERT OR IGNORE INTO benchmark_adoption_invalidations(
    id, adoption_digest, campaign_invalidation_id, settlement_invalidation_id,
    reason, invalidated_at_ms
  )
  SELECT 'benchmark-adoption-invalidation:' || adoption.digest,
         adoption.digest, NEW.id, NULL, 'campaign_invalidated', NEW.invalidated_at_ms
  FROM benchmark_adoption_decisions adoption
  WHERE adoption.preregistration_digest = NEW.preregistration_digest;
END;

CREATE TRIGGER benchmark_late_usage_invalidates_existing_adoption
AFTER INSERT ON benchmark_arm_settlement_invalidations
BEGIN
  INSERT OR IGNORE INTO benchmark_adoption_invalidations(
    id, adoption_digest, campaign_invalidation_id, settlement_invalidation_id,
    reason, invalidated_at_ms
  )
  SELECT 'benchmark-adoption-invalidation:' || adoption.digest,
         adoption.digest, NULL, NEW.id, 'late_usage', NEW.invalidated_at_ms
  FROM benchmark_adoption_decisions adoption
  JOIN benchmark_arm_settlement_seals settlement
  JOIN benchmark_arm_runs arm ON arm.arm_execution_id = settlement.arm_execution_id
  WHERE settlement.digest = NEW.settlement_digest
    AND adoption.preregistration_digest = arm.preregistration_digest;
END;

