BEFORE UPDATE ON benchmark_adoption_invalidations
BEGIN SELECT RAISE(ABORT, 'benchmark adoption invalidations are immutable'); END;

CREATE TRIGGER benchmark_adoption_invalidations_no_delete
BEFORE DELETE ON benchmark_adoption_invalidations
BEGIN SELECT RAISE(ABORT, 'benchmark adoption invalidations are immutable'); END;

CREATE TRIGGER fairness_policy_rotation_is_exact_and_dispatch_stopped
BEFORE UPDATE ON fairness_policies
BEGIN
  SELECT RAISE(ABORT, 'fairness policy rotation is not contiguous, signed, invalidation-backed, or quiescent')
  WHERE NEW.pool <> OLD.pool
     OR NEW.version <> OLD.version + 1
     OR NEW.revision <> OLD.revision + 1
     OR NEW.updated_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.updated_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NOT EXISTS (
       SELECT 1 FROM control_state control
       WHERE control.singleton = 1
         AND control.dispatch_enabled = 0
         AND control.admission_mode = 'stopped'
     )
     OR NOT EXISTS (
       SELECT 1 FROM policy_invalidations invalidation
       WHERE invalidation.policy_digest = OLD.policy_digest
     )
     OR NOT EXISTS (
       SELECT 1
       FROM policies policy
       JOIN current_valid_keys policy_key
         ON policy_key.key_id = policy.signer_key_id
        AND policy_key.key_purpose = 'control_plane'
       JOIN json_each(policy.canonical_json, '$.fairness_pools') member
       WHERE policy.digest = NEW.policy_digest
         AND policy.policy_type = 'scheduler_fairness'
         AND policy.version = NEW.version
         AND json_extract(member.value, '$.pool') = NEW.pool
         AND json_extract(member.value, '$.quantum_units') = NEW.quantum_units
         AND json_extract(member.value, '$.max_deficit_units') = NEW.max_deficit_units
         AND json_extract(member.value, '$.aging_threshold_ms') = NEW.aging_threshold_ms
         AND json_extract(member.value, '$.max_wait_ms') = NEW.max_wait_ms
         AND NOT EXISTS (
           SELECT 1 FROM policy_invalidations current_invalidation
           WHERE current_invalidation.policy_digest = policy.digest
         )
     );
END;

CREATE TRIGGER fairness_policies_no_delete
BEFORE DELETE ON fairness_policies
BEGIN SELECT RAISE(ABORT, 'fairness policies are immutable signed projections'); END;

CREATE TRIGGER fairness_state_enters_zero_current_term
BEFORE INSERT ON fairness_state
BEGIN
  SELECT RAISE(ABORT, 'fairness state must enter at zero under the current active term')
  WHERE NEW.scheduler_epoch <> 0
     OR NEW.deficit_units <> 0
     OR NEW.waiting_since_ms IS NOT NULL
     OR NEW.last_dispatch_at_ms IS NOT NULL
     OR NEW.dispatch_count <> 0
     OR NEW.revision <> 0
     OR NOT EXISTS (
       SELECT 1 FROM leader_terms term
       JOIN control_state control ON control.current_term = term.term
       WHERE term.term = NEW.leader_term AND term.state = 'active'
     );
END;

CREATE TRIGGER node_state_refreshes_durable_fairness_wait
AFTER UPDATE OF state ON node_versions
WHEN OLD.state <> NEW.state
BEGIN
  UPDATE fairness_state
  SET scheduler_epoch = scheduler_epoch + 1,
      waiting_since_ms = (
        SELECT MIN(candidate.ready_since_ms)
        FROM runs run
        JOIN node_versions candidate ON candidate.run_id = run.id
        WHERE run.project_id = fairness_state.project_id
          AND run.state = 'active'
          AND candidate.required_pool = fairness_state.pool
          AND candidate.state = 'ready'
      ),
      leader_term = (SELECT current_term FROM control_state WHERE singleton = 1),
      revision = revision + 1
  WHERE project_id = (SELECT run.project_id FROM runs run WHERE run.id = NEW.run_id)
    AND pool = NEW.required_pool;
END;

CREATE TRIGGER leader_change_rebases_all_fairness_states
AFTER UPDATE OF current_term ON control_state
WHEN OLD.current_term <> NEW.current_term
BEGIN
  UPDATE fairness_state
  SET scheduler_epoch = scheduler_epoch + 1,
      leader_term = NEW.current_term,
      revision = revision + 1;
END;

CREATE TRIGGER fairness_state_updates_are_current_term_cas
BEFORE UPDATE ON fairness_state
BEGIN
  SELECT RAISE(ABORT, 'fairness update is not monotonic current-term CAS')
  WHERE NEW.project_id <> OLD.project_id
     OR NEW.pool <> OLD.pool
     OR NEW.revision <> OLD.revision + 1
     OR NEW.scheduler_epoch <> OLD.scheduler_epoch + 1
     OR NEW.dispatch_count < OLD.dispatch_count
     OR NEW.dispatch_count > OLD.dispatch_count + 1
     OR (NEW.last_dispatch_at_ms IS NOT OLD.last_dispatch_at_ms
         AND (NEW.last_dispatch_at_ms IS NULL
              OR NEW.last_dispatch_at_ms < COALESCE(OLD.last_dispatch_at_ms, 0)
              OR NEW.dispatch_count <> OLD.dispatch_count + 1))
     OR NOT EXISTS (
       SELECT 1 FROM leader_terms term
       JOIN control_state control ON control.current_term = term.term
       JOIN fairness_policies policy ON policy.pool = NEW.pool
       WHERE term.term = NEW.leader_term
         AND term.state = 'active'
         AND NEW.deficit_units BETWEEN -policy.max_deficit_units AND policy.max_deficit_units
     );
END;

CREATE TRIGGER fairness_state_no_delete
BEFORE DELETE ON fairness_state
BEGIN SELECT RAISE(ABORT, 'fairness state is durable across restarts'); END;

CREATE TRIGGER projection_change_batch_is_exact_current_and_verified
BEFORE INSERT ON projection_change_batches
BEGIN
  SELECT RAISE(ABORT, 'projection changeset batch is not exact, chained, current, or verified')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.batch_seq <> COALESCE((
       SELECT MAX(prior.batch_seq) + 1 FROM projection_change_batches prior
     ), 1)
     OR NEW.prior_batch_digest IS NOT (
       SELECT prior.digest FROM projection_change_batches prior
       ORDER BY prior.batch_seq DESC LIMIT 1
     )
     OR json_extract(NEW.canonical_json, '$.batch_seq') IS NOT NEW.batch_seq
     OR json_extract(NEW.canonical_json, '$.digest') IS NOT NEW.digest
     OR json_extract(NEW.canonical_json, '$.transaction_id') IS NOT NEW.transaction_id
     OR json_extract(NEW.canonical_json, '$.prior_batch_digest') IS NOT NEW.prior_batch_digest
     OR json_extract(NEW.canonical_json, '$.projection_schema_digest') IS NOT NEW.projection_schema_digest
     OR json_extract(NEW.canonical_json, '$.transformer_closure_digest') IS NOT NEW.transformer_closure_digest
     OR json_extract(NEW.canonical_json, '$.table_set_digest') IS NOT NEW.table_set_digest
     OR json_extract(NEW.canonical_json, '$.source_changeset_digest') IS NOT NEW.source_changeset_digest
     OR json_extract(NEW.canonical_json, '$.projection_delta_digest') IS NOT NEW.projection_delta_digest
     OR json_extract(NEW.canonical_json, '$.projection_delta_encoding') IS NOT NEW.projection_delta_encoding
     OR json_extract(NEW.canonical_json, '$.compressed_size_bytes') IS NOT NEW.compressed_size_bytes
     OR json_extract(NEW.canonical_json, '$.uncompressed_size_bytes') IS NOT NEW.uncompressed_size_bytes
     OR json_extract(NEW.canonical_json, '$.source_row_change_count') IS NOT NEW.source_row_change_count
     OR json_extract(NEW.canonical_json, '$.projection_record_count') IS NOT NEW.projection_record_count
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.scope_manifest_json') IS NOT NEW.scope_manifest_json
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.actor_principal_id') IS NOT NEW.actor_principal_id
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.correlation_id') IS NOT NEW.correlation_id
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1
       FROM configuration_artifacts schema_closure
       JOIN configuration_artifacts transformer
         ON transformer.digest = NEW.transformer_closure_digest
       JOIN current_valid_keys signer_key
         ON signer_key.key_id = NEW.signer_key_id
        AND signer_key.principal_id = NEW.signer_principal_id
        AND signer_key.key_purpose = 'control_plane'
       JOIN principals signer ON signer.id = NEW.signer_principal_id
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       WHERE schema_closure.digest = NEW.projection_schema_digest
         AND schema_closure.artifact_kind = 'projection_schema_closure'
         AND transformer.artifact_kind = 'projection_transformer_closure'
         AND json_extract(schema_closure.canonical_json, '$.source_capture_format') = 'sqlite-session-v1'
         AND json_extract(schema_closure.canonical_json, '$.projection_delta_encoding') = NEW.projection_delta_encoding
         AND json_extract(schema_closure.canonical_json, '$.source_table_set_digest') = NEW.table_set_digest
         AND json_extract(schema_closure.canonical_json, '$.transformer_closure_digest') = transformer.digest
         AND json_extract(transformer.canonical_json, '$.forbidden_field_audit') = 'pass'
         AND signer.kind = 'service'
         AND NOT EXISTS (
           SELECT 1 FROM configuration_artifact_invalidations invalidation
           WHERE invalidation.configuration_digest IN (schema_closure.digest, transformer.digest)
         )
     )
     OR (NEW.command_id IS NULL AND NEW.actor_principal_id <> NEW.signer_principal_id)
     OR (NEW.command_id IS NOT NULL AND NOT EXISTS (
       SELECT 1
       FROM commands command
       JOIN command_authorizations authorization ON authorization.command_id = command.id
       WHERE command.id = NEW.command_id
         AND command.principal_id = NEW.actor_principal_id
         AND command.project_id IS NEW.project_id
         AND command.state IN ('authorized','applied')
         AND authorization.leader_term = NEW.leader_term
         AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
     ))
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'projection_change_batch'
         AND receipt.record_id = NEW.digest
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.validator_closure_digest = json_extract(
           (SELECT schema_closure.canonical_json
            FROM configuration_artifacts schema_closure
            WHERE schema_closure.digest = NEW.projection_schema_digest),
           '$.projection_delta_validator_closure_digest'
         )
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.projection_delta_digest
         AND receipt.record_digest_verified = 1
         AND receipt.verified_record_digest = NEW.digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER projection_change_batches_no_update
BEFORE UPDATE ON projection_change_batches
BEGIN SELECT RAISE(ABORT, 'projection changeset batches are append-only'); END;

CREATE TRIGGER projection_change_batches_no_delete
BEFORE DELETE ON projection_change_batches
BEGIN SELECT RAISE(ABORT, 'projection changeset batches are append-only'); END;

CREATE TRIGGER event_is_exact_current_signed_projection
BEFORE INSERT ON events
BEGIN
  SELECT RAISE(ABORT, 'event is not an exact signed projection of current authoritative state')
  WHERE NEW.created_at_ms < (unixepoch('subsec') * 1000) - 5000
     OR NEW.created_at_ms > (unixepoch('subsec') * 1000) + 5000
     OR NEW.leader_term IS NULL
     OR json_extract(NEW.canonical_json, '$.id') IS NOT NEW.id
     OR json_extract(NEW.canonical_json, '$.project_id') IS NOT NEW.project_id
     OR json_extract(NEW.canonical_json, '$.leader_term') IS NOT NEW.leader_term
     OR json_extract(NEW.canonical_json, '$.actor_principal_id') IS NOT NEW.actor_principal_id
     OR json_extract(NEW.canonical_json, '$.command_id') IS NOT NEW.command_id
     OR json_extract(NEW.canonical_json, '$.correlation_id') IS NOT NEW.correlation_id
     OR json_extract(NEW.canonical_json, '$.causation_event_id') IS NOT NEW.causation_event_id
     OR json_extract(NEW.canonical_json, '$.entity_type') IS NOT NEW.entity_type
     OR json_extract(NEW.canonical_json, '$.entity_id') IS NOT NEW.entity_id
     OR json_extract(NEW.canonical_json, '$.entity_revision') IS NOT NEW.entity_revision
     OR json_extract(NEW.canonical_json, '$.event_type') IS NOT NEW.event_type
     OR json_extract(NEW.canonical_json, '$.payload_json') IS NOT NEW.payload_json
     OR json_extract(NEW.canonical_json, '$.payload_digest') IS NOT NEW.payload_digest
     OR json_extract(NEW.canonical_json, '$.signer_principal_id') IS NOT NEW.signer_principal_id
     OR json_extract(NEW.canonical_json, '$.signer_key_id') IS NOT NEW.signer_key_id
     OR json_extract(NEW.canonical_json, '$.created_at_ms') IS NOT NEW.created_at_ms
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_keys signer_key
       JOIN principals signer ON signer.id = signer_key.principal_id
       JOIN leader_terms term ON term.term = NEW.leader_term AND term.state = 'active'
       JOIN control_state control ON control.current_term = NEW.leader_term
       WHERE signer_key.key_id = NEW.signer_key_id
         AND signer_key.principal_id = NEW.signer_principal_id
         AND signer_key.key_purpose = 'control_plane'
         AND signer.kind = 'service'
     )
     OR (NEW.command_id IS NULL AND NEW.actor_principal_id <> NEW.signer_principal_id)
     OR (NEW.command_id IS NOT NULL AND NOT EXISTS (
       SELECT 1
       FROM commands command
       JOIN command_authorizations authorization ON authorization.command_id = command.id
       WHERE command.id = NEW.command_id
         AND command.principal_id = NEW.actor_principal_id
         AND command.project_id IS NEW.project_id
         AND command.state IN ('authorized','applied')
         AND authorization.leader_term = NEW.leader_term
         AND authorization.authorization_expires_at_ms >= NEW.created_at_ms
     ))
     OR (NEW.causation_event_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM events cause
       WHERE cause.id = NEW.causation_event_id
         AND cause.project_id IS NEW.project_id
         AND cause.correlation_id = NEW.correlation_id
         AND cause.created_at_ms <= NEW.created_at_ms
     ))
     OR NOT (
       (NEW.entity_type = 'project' AND EXISTS (
         SELECT 1 FROM projects entity
         WHERE entity.id = NEW.entity_id AND entity.revision = NEW.entity_revision
           AND entity.id IS NEW.project_id
       ))
       OR (NEW.entity_type = 'control_state' AND NEW.entity_id = '1' AND EXISTS (
         SELECT 1 FROM control_state entity
         WHERE entity.singleton = 1 AND entity.revision = NEW.entity_revision
       ))
       OR (NEW.entity_type = 'budget_account' AND EXISTS (
         SELECT 1 FROM budget_accounts entity
         WHERE entity.id = NEW.entity_id AND entity.revision = NEW.entity_revision
           AND entity.project_id IS NEW.project_id
       ))
       OR (NEW.entity_type = 'node_version' AND EXISTS (
         SELECT 1 FROM node_versions entity
         JOIN logical_nodes node ON node.id = entity.logical_node_id
         WHERE entity.id = NEW.entity_id AND entity.revision = NEW.entity_revision
           AND node.project_id IS NEW.project_id
       ))
       OR (NEW.entity_type = 'executor_slot' AND EXISTS (
         SELECT 1 FROM executor_slots entity
         WHERE entity.id = NEW.entity_id AND entity.revision = NEW.entity_revision
       ))
       OR (NEW.entity_type = 'host_capacity' AND NEW.entity_id = '1' AND EXISTS (
         SELECT 1 FROM host_capacity entity
         WHERE entity.singleton = 1 AND entity.revision = NEW.entity_revision
       ))
       OR (NEW.entity_type = 'fairness_state' AND EXISTS (
         SELECT 1 FROM fairness_state entity
         WHERE NEW.entity_id = entity.project_id || ':' || entity.pool
           AND entity.revision = NEW.entity_revision
           AND entity.project_id IS NEW.project_id
       ))
     )
     OR NOT EXISTS (
       SELECT 1 FROM current_valid_signature_receipts receipt
       WHERE receipt.record_kind = 'event'
         AND receipt.record_id = NEW.id
         AND receipt.record_canonical_json = NEW.canonical_json
         AND receipt.record_signer_key_id = NEW.signer_key_id
         AND receipt.record_signature = NEW.signature
         AND receipt.payload_digest_verified = 1
         AND receipt.verified_payload_digest = NEW.payload_digest
         AND receipt.verified_at_ms BETWEEN NEW.created_at_ms - 5000 AND NEW.created_at_ms
     );
END;

CREATE TRIGGER events_no_update
BEFORE UPDATE ON events
BEGIN SELECT RAISE(ABORT, 'events are append-only'); END;

CREATE TRIGGER events_no_delete
BEFORE DELETE ON events
BEGIN SELECT RAISE(ABORT, 'events are append-only'); END;

